\set ON_ERROR_STOP on
set check_function_bodies = off;
set search_path = pg_catalog, public, extensions;

-- mailshot_fields_bulk_apply(uuid[],text,text,uuid)
CREATE OR REPLACE FUNCTION public.mailshot_fields_bulk_apply(p_field_ids uuid[], p_action text, p_entity_type text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();

  v_action text := upper(btrim(coalesce(p_action, '')));
  v_entity_type text := nullif(lower(btrim(coalesce(p_entity_type, ''))), '');

  v_requested_count int := 0;
  v_existing_count int := 0;
  v_eligible_count int := 0;
  v_applied_count int := 0;
  v_not_found_count int := 0;
  v_invalid_for_entity_count int := 0;
  v_noop_count int := 0;

  v_applied_field_ids jsonb := '[]'::jsonb;
  v_not_found_field_ids jsonb := '[]'::jsonb;
  v_invalid_for_entity_field_ids jsonb := '[]'::jsonb;

  v_requires_entity boolean := false;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if p_field_ids is null or coalesce(array_length(p_field_ids, 1), 0) = 0 then
    raise exception 'field_ids[] required';
  end if;

  if v_action is null or v_action = '' then
    raise exception 'action required';
  end if;

  if v_action not in (
    'GLOBAL_ENABLE',
    'GLOBAL_DISABLE',
    'ADD_VISIBLE_IN_ENTITY',
    'REMOVE_VISIBLE_IN_ENTITY',
    'OVERRIDE_ENABLE',
    'OVERRIDE_DISABLE',
    'CLEAR_OVERRIDE'
  ) then
    raise exception 'invalid action: %', v_action;
  end if;

  v_requires_entity := v_action in (
    'ADD_VISIBLE_IN_ENTITY',
    'REMOVE_VISIBLE_IN_ENTITY',
    'OVERRIDE_ENABLE',
    'OVERRIDE_DISABLE',
    'CLEAR_OVERRIDE'
  );

  if v_requires_entity and v_entity_type is null then
    raise exception 'entity_type required for action %', v_action;
  end if;

  if v_entity_type is not null then
    perform 1
    from public.v_mailshot_resolution_graph as rg
    where rg.root_entity_type = v_entity_type
    limit 1;

    if not found then
      raise exception 'invalid entity_type: %', v_entity_type;
    end if;
  end if;

  drop table if exists tmp_mailshot_bulk_ids;
  create temporary table tmp_mailshot_bulk_ids(
    field_id uuid primary key
  ) on commit drop;

  insert into tmp_mailshot_bulk_ids(field_id)
  select distinct
    u.field_id
  from unnest(p_field_ids) as u(field_id)
  where u.field_id is not null;

  select count(*) into v_requested_count
  from tmp_mailshot_bulk_ids as tbi;

  if v_requested_count = 0 then
    raise exception 'field_ids[] required';
  end if;

  drop table if exists tmp_mailshot_bulk_targets;
  create temporary table tmp_mailshot_bulk_targets(
    field_id uuid primary key,
    field_exists boolean not null,
    source_family text,
    allowed_entity_types text[],
    valid_for_entity boolean,
    skip_reason text
  ) on commit drop;

  insert into tmp_mailshot_bulk_targets(
    field_id,
    field_exists,
    source_family,
    allowed_entity_types,
    valid_for_entity,
    skip_reason
  )
  select
    tbi.field_id,
    (mf.id is not null) as field_exists,
    case
      when mf.id is null then null
      else coalesce(
        nullif(mf.resolver_spec_json ->> 'source_family', ''),
        split_part(mf.field_key, '.', 1)
      )
    end as source_family,
    mf.allowed_entity_types,
    case
      when v_entity_type is null then null
      when mf.id is null then false
      else exists (
        select 1
        from public.v_mailshot_resolution_graph as rg
        where rg.root_entity_type = v_entity_type
          and rg.source_family = coalesce(
            nullif(mf.resolver_spec_json ->> 'source_family', ''),
            split_part(mf.field_key, '.', 1)
          )
      )
    end as valid_for_entity,
    case
      when mf.id is null then 'field_not_found'
      when v_entity_type is not null
       and not exists (
         select 1
         from public.v_mailshot_resolution_graph as rg
         where rg.root_entity_type = v_entity_type
           and rg.source_family = coalesce(
             nullif(mf.resolver_spec_json ->> 'source_family', ''),
             split_part(mf.field_key, '.', 1)
           )
       ) then 'not_resolvable_for_entity'
      else null
    end as skip_reason
  from tmp_mailshot_bulk_ids as tbi
  left join public.mailshot_fields as mf
    on mf.id = tbi.field_id;

  select count(*) into v_existing_count
  from tmp_mailshot_bulk_targets as tbt
  where tbt.field_exists = true;

  select count(*) into v_not_found_count
  from tmp_mailshot_bulk_targets as tbt
  where tbt.skip_reason = 'field_not_found';

  select count(*) into v_invalid_for_entity_count
  from tmp_mailshot_bulk_targets as tbt
  where tbt.skip_reason = 'not_resolvable_for_entity';

  select coalesce(
           jsonb_agg((tbt.field_id)::text order by (tbt.field_id)::text),
           '[]'::jsonb
         )
    into v_not_found_field_ids
  from tmp_mailshot_bulk_targets as tbt
  where tbt.skip_reason = 'field_not_found';

  select coalesce(
           jsonb_agg((tbt.field_id)::text order by (tbt.field_id)::text),
           '[]'::jsonb
         )
    into v_invalid_for_entity_field_ids
  from tmp_mailshot_bulk_targets as tbt
  where tbt.skip_reason = 'not_resolvable_for_entity';

  if v_requires_entity then
    select count(*) into v_eligible_count
    from tmp_mailshot_bulk_targets as tbt
    where tbt.field_exists = true
      and tbt.valid_for_entity = true;
  else
    select count(*) into v_eligible_count
    from tmp_mailshot_bulk_targets as tbt
    where tbt.field_exists = true;
  end if;

  drop table if exists tmp_mailshot_bulk_applied_ids;
  create temporary table tmp_mailshot_bulk_applied_ids(
    field_id uuid primary key
  ) on commit drop;

  if v_action = 'GLOBAL_ENABLE' then
    with upd as (
      update public.mailshot_fields as mf
      set
        enabled_global = true,
        updated_at_utc = v_now
      where mf.id in (
        select tbt.field_id
        from tmp_mailshot_bulk_targets as tbt
        where tbt.field_exists = true
      )
        and mf.enabled_global is distinct from true
      returning mf.id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      upd.id
    from upd;

  elsif v_action = 'GLOBAL_DISABLE' then
    with upd as (
      update public.mailshot_fields as mf
      set
        enabled_global = false,
        updated_at_utc = v_now
      where mf.id in (
        select tbt.field_id
        from tmp_mailshot_bulk_targets as tbt
        where tbt.field_exists = true
      )
        and mf.enabled_global is distinct from false
      returning mf.id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      upd.id
    from upd;

  elsif v_action = 'ADD_VISIBLE_IN_ENTITY' then
    with upd as (
      update public.mailshot_fields as mf
      set
        allowed_entity_types = array(
          select distinct
            u.entity_type_value
          from unnest(coalesce(mf.allowed_entity_types, '{}'::text[]) || array[v_entity_type]::text[]) as u(entity_type_value)
          order by u.entity_type_value
        ),
        updated_at_utc = v_now
      where mf.id in (
        select tbt.field_id
        from tmp_mailshot_bulk_targets as tbt
        where tbt.field_exists = true
          and tbt.valid_for_entity = true
      )
        and not (v_entity_type = any(coalesce(mf.allowed_entity_types, '{}'::text[])))
      returning mf.id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      upd.id
    from upd;

  elsif v_action = 'REMOVE_VISIBLE_IN_ENTITY' then
    with upd as (
      update public.mailshot_fields as mf
      set
        allowed_entity_types = array_remove(coalesce(mf.allowed_entity_types, '{}'::text[]), v_entity_type),
        updated_at_utc = v_now
      where mf.id in (
        select tbt.field_id
        from tmp_mailshot_bulk_targets as tbt
        where tbt.field_exists = true
          and tbt.valid_for_entity = true
      )
        and v_entity_type = any(coalesce(mf.allowed_entity_types, '{}'::text[]))
      returning mf.id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      upd.id
    from upd;

  elsif v_action = 'OVERRIDE_ENABLE' then
    with upserted as (
      insert into public.mailshot_field_overrides(
        field_id,
        entity_type,
        label_override,
        enabled_local
      )
      select
        tbt.field_id,
        v_entity_type,
        null,
        true
      from tmp_mailshot_bulk_targets as tbt
      where tbt.field_exists = true
        and tbt.valid_for_entity = true
      on conflict (field_id, entity_type)
      do update
      set enabled_local = excluded.enabled_local
      where public.mailshot_field_overrides.enabled_local is distinct from excluded.enabled_local
      returning field_id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      upserted.field_id
    from upserted;

  elsif v_action = 'OVERRIDE_DISABLE' then
    with upserted as (
      insert into public.mailshot_field_overrides(
        field_id,
        entity_type,
        label_override,
        enabled_local
      )
      select
        tbt.field_id,
        v_entity_type,
        null,
        false
      from tmp_mailshot_bulk_targets as tbt
      where tbt.field_exists = true
        and tbt.valid_for_entity = true
      on conflict (field_id, entity_type)
      do update
      set enabled_local = excluded.enabled_local
      where public.mailshot_field_overrides.enabled_local is distinct from excluded.enabled_local
      returning field_id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      upserted.field_id
    from upserted;

  elsif v_action = 'CLEAR_OVERRIDE' then
    with deleted_rows as (
      delete from public.mailshot_field_overrides as mfo
      where mfo.entity_type = v_entity_type
        and mfo.field_id in (
          select tbt.field_id
          from tmp_mailshot_bulk_targets as tbt
          where tbt.field_exists = true
            and tbt.valid_for_entity = true
        )
      returning mfo.field_id
    )
    insert into tmp_mailshot_bulk_applied_ids(field_id)
    select
      deleted_rows.field_id
    from deleted_rows;
  end if;

  select count(*) into v_applied_count
  from tmp_mailshot_bulk_applied_ids as tbai;

  select coalesce(
           jsonb_agg((tbai.field_id)::text order by (tbai.field_id)::text),
           '[]'::jsonb
         )
    into v_applied_field_ids
  from tmp_mailshot_bulk_applied_ids as tbai;

  v_noop_count := greatest(v_eligible_count - v_applied_count, 0);

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'entity_type', v_entity_type,
    'requested_count', v_requested_count,
    'existing_count', v_existing_count,
    'eligible_count', v_eligible_count,
    'applied_count', v_applied_count,
    'noop_count', v_noop_count,
    'not_found_count', v_not_found_count,
    'invalid_for_entity_count', v_invalid_for_entity_count,
    'applied_field_ids', v_applied_field_ids,
    'not_found_field_ids', v_not_found_field_ids,
    'invalid_for_entity_field_ids', v_invalid_for_entity_field_ids,
    'applied_at_utc', v_now::text
  );
end;
$function$;

-- mailshot_fields_catalog_list(text,boolean)
CREATE OR REPLACE FUNCTION public.mailshot_fields_catalog_list(p_entity_type text DEFAULT NULL::text, p_include_disabled boolean DEFAULT false)
 RETURNS TABLE(field_id uuid, field_key text, source_family text, label_default text, label_override text, label_effective text, enabled_global boolean, enabled_local boolean, enabled_effective boolean, allowed_entity_types text[], is_resolvable_for_root boolean, stale boolean, resolver_spec_json jsonb, entity_type text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with normalized_input as (
  select
    nullif(lower(btrim(coalesce(p_entity_type, ''))), '') as entity_type_norm,
    coalesce(p_include_disabled, false) as include_disabled_norm
),
approved_families as (
  select distinct
    rg.source_family
  from public.v_mailshot_resolution_graph as rg
),
base_rows as (
  select
    mf.id as field_id,
    mf.field_key,
    coalesce(
      nullif(mf.resolver_spec_json ->> 'source_family', ''),
      split_part(mf.field_key, '.', 1)
    ) as source_family,
    coalesce(
      nullif(mf.resolver_spec_json ->> 'source_column_name', ''),
      nullif(split_part(mf.field_key, '.', 2), '')
    ) as source_column_name,
    mf.label_default,
    mfo.label_override,
    mf.enabled_global,
    case
      when ni.entity_type_norm is null then null
      else coalesce(mfo.enabled_local, true)
    end as enabled_local,
    mf.allowed_entity_types,
    case
      when lower(coalesce(mf.resolver_spec_json ->> 'stale', '')) = 'true' then true
      when lower(coalesce(mf.resolver_spec_json ->> 'stale', '')) = 'false' then false
      else false
    end as stale,
    mf.resolver_spec_json,
    ni.entity_type_norm as entity_type
  from public.mailshot_fields as mf
  cross join normalized_input as ni
  left join public.mailshot_field_overrides as mfo
    on mfo.field_id = mf.id
   and ni.entity_type_norm is not null
   and mfo.entity_type = ni.entity_type_norm
)
select
  br.field_id,
  br.field_key,
  br.source_family,
  br.label_default,
  br.label_override,
  coalesce(br.label_override, br.label_default) as label_effective,
  br.enabled_global,
  br.enabled_local,
  case
    when br.entity_type is null then br.enabled_global
    else (br.enabled_global and coalesce(br.enabled_local, true))
  end as enabled_effective,
  br.allowed_entity_types,
  case
    when br.entity_type is null then null
    else exists (
      select 1
      from public.v_mailshot_resolution_graph as rg
      where rg.root_entity_type = br.entity_type
        and rg.source_family = br.source_family
    )
  end as is_resolvable_for_root,
  br.stale,
  br.resolver_spec_json,
  br.entity_type
from base_rows as br
where exists (
    select 1
    from approved_families as af
    where af.source_family = br.source_family
  )
  and left(coalesce(br.source_column_name, ''), 1) <> '_'
  and (
    (select ni.include_disabled_norm from normalized_input as ni)
    or (
      case
        when br.entity_type is null then br.enabled_global
        else (br.enabled_global and coalesce(br.enabled_local, true))
      end
    )
  )
order by
  lower(br.source_family) asc,
  lower(coalesce(br.label_override, br.label_default)) asc,
  lower(br.field_key) asc;
$function$;

-- mailshot_fields_list(text,boolean)
CREATE OR REPLACE FUNCTION public.mailshot_fields_list(p_entity_type text DEFAULT NULL::text, p_include_disabled boolean DEFAULT false)
 RETURNS TABLE(field_id uuid, field_key text, label_default text, label_override text, label_effective text, enabled_global boolean, enabled_local boolean, enabled_effective boolean, allowed_entity_types text[], resolver_spec_json jsonb, entity_type text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    f.id as field_id,
    f.field_key,
    f.label_default,
    o.label_override,
    coalesce(o.label_override, f.label_default) as label_effective,
    f.enabled_global,
    coalesce(o.enabled_local, true) as enabled_local,
    (f.enabled_global and coalesce(o.enabled_local, true)) as enabled_effective,
    f.allowed_entity_types,
    f.resolver_spec_json,
    p_entity_type as entity_type
  from public.mailshot_fields f
  left join public.mailshot_field_overrides o
    on o.field_id = f.id
   and (p_entity_type is not null and o.entity_type = p_entity_type)
  where
    (
      p_include_disabled = true
      or (f.enabled_global = true and coalesce(o.enabled_local, true) = true)
    )
    and (
      p_entity_type is null
      or coalesce(array_length(f.allowed_entity_types,1),0) = 0
      or p_entity_type = any(f.allowed_entity_types)
    )
  order by lower(coalesce(o.label_override, f.label_default)) asc, lower(f.field_key) asc;
$function$;

-- mailshot_fields_seed_from_schema(uuid)
CREATE OR REPLACE FUNCTION public.mailshot_fields_seed_from_schema(p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();

  v_inserted int := 0;
  v_updated int := 0;
  v_marked_stale int := 0;

  v_source_family_count int := 0;
  v_source_view_count int := 0;
  v_helper_column_count int := 0;
  v_discovered_total int := 0;

  v_source_views jsonb := '[]'::jsonb;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  drop table if exists tmp_mailshot_source_families;
  create temporary table tmp_mailshot_source_families(
    source_family text not null,
    source_view_name text not null,
    allowed_entity_types text[] not null
  ) on commit drop;

  insert into tmp_mailshot_source_families(
    source_family,
    source_view_name,
    allowed_entity_types
  )
  select
    rg.source_family,
    rg.source_view_name,
    array_agg(distinct rg.root_entity_type order by rg.root_entity_type) as allowed_entity_types
  from public.v_mailshot_resolution_graph as rg
  group by
    rg.source_family,
    rg.source_view_name;

  select count(*) into v_source_family_count
  from tmp_mailshot_source_families as msf;

  if v_source_family_count = 0 then
    raise exception 'no source families found in public.v_mailshot_resolution_graph';
  end if;

  select count(distinct msf.source_view_name) into v_source_view_count
  from tmp_mailshot_source_families as msf;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'source_family', msf.source_family,
          'source_view_name', msf.source_view_name,
          'allowed_entity_types', to_jsonb(msf.allowed_entity_types)
        )
        order by msf.source_family, msf.source_view_name
      ),
      '[]'::jsonb
    )
  into v_source_views
  from tmp_mailshot_source_families as msf;

  drop table if exists tmp_mailshot_source_columns;
  create temporary table tmp_mailshot_source_columns(
    source_family text not null,
    source_view_name text not null,
    column_name text not null,
    allowed_entity_types text[] not null,
    is_helper boolean not null
  ) on commit drop;

  insert into tmp_mailshot_source_columns(
    source_family,
    source_view_name,
    column_name,
    allowed_entity_types,
    is_helper
  )
  select
    msf.source_family,
    msf.source_view_name,
    isc.column_name,
    msf.allowed_entity_types,
    left(isc.column_name, 1) = '_' as is_helper
  from tmp_mailshot_source_families as msf
  join information_schema.columns as isc
    on isc.table_schema = 'public'
   and isc.table_name = msf.source_view_name;

  select count(*) into v_helper_column_count
  from tmp_mailshot_source_columns as msc
  where msc.is_helper = true;

  drop table if exists tmp_mailshot_discovered_fields;
  create temporary table tmp_mailshot_discovered_fields(
    field_key text not null,
    label_default text not null,
    enabled_global boolean not null,
    allowed_entity_types text[] not null,
    resolver_spec_json jsonb not null,
    source_family text not null,
    source_view_name text not null,
    source_column_name text not null
  ) on commit drop;

  insert into tmp_mailshot_discovered_fields(
    field_key,
    label_default,
    enabled_global,
    allowed_entity_types,
    resolver_spec_json,
    source_family,
    source_view_name,
    source_column_name
  )
  select
    msc.source_family || '.' || msc.column_name as field_key,
    initcap(replace(msc.source_family, '_', ' ')) || ' — ' || initcap(replace(msc.column_name, '_', ' ')) as label_default,
    true as enabled_global,
    msc.allowed_entity_types,
    jsonb_build_object(
      'managed_by', 'approved_view_sync',
      'source_family', msc.source_family,
      'source_view_name', msc.source_view_name,
      'source_column_name', msc.column_name,
      'path', msc.source_family || '.' || msc.column_name,
      'stale', false
    ) as resolver_spec_json,
    msc.source_family,
    msc.source_view_name,
    msc.column_name
  from tmp_mailshot_source_columns as msc
  where msc.is_helper = false
  order by
    msc.source_family,
    msc.column_name;

  insert into tmp_mailshot_discovered_fields(
    field_key,
    label_default,
    enabled_global,
    allowed_entity_types,
    resolver_spec_json,
    source_family,
    source_view_name,
    source_column_name
  )
  values (
    'system.sender_display_name',
    'System — Sender Display Name',
    true,
    array['candidate','client','contract','timesheet','invoice','umbrella']::text[],
    jsonb_build_object(
      'managed_by', 'system_seed',
      'source_family', 'system',
      'source_view_name', 'runtime_system',
      'source_column_name', 'sender_display_name',
      'path', 'system.sender_display_name',
      'resolution_mode', 'runtime_injected',
      'runtime_source_function', 'public.mailshot_prepare',
      'runtime_value_key', 'sender_display_name',
      'stale', false
    ),
    'system',
    'runtime_system',
    'sender_display_name'
  );

  select count(*) into v_discovered_total
  from tmp_mailshot_discovered_fields as mdf;

  if v_discovered_total = 0 then
    raise exception 'no approved mailshot fields discovered from public.v_mailshot_resolution_graph source views';
  end if;

  insert into public.mailshot_fields(
    field_key,
    label_default,
    enabled_global,
    allowed_entity_types,
    resolver_spec_json,
    created_at_utc,
    updated_at_utc
  )
  select
    mdf.field_key,
    mdf.label_default,
    mdf.enabled_global,
    mdf.allowed_entity_types,
    mdf.resolver_spec_json,
    v_now,
    v_now
  from tmp_mailshot_discovered_fields as mdf
  where not exists (
    select 1
    from public.mailshot_fields as mf
    where mf.field_key = mdf.field_key
  );

  get diagnostics v_inserted = row_count;

  update public.mailshot_fields as mf
  set
    allowed_entity_types = mdf.allowed_entity_types,
    resolver_spec_json = mdf.resolver_spec_json,
    updated_at_utc = v_now
  from tmp_mailshot_discovered_fields as mdf
  where mf.field_key = mdf.field_key
    and (
      mf.allowed_entity_types is distinct from mdf.allowed_entity_types
      or mf.resolver_spec_json is distinct from mdf.resolver_spec_json
    );

  get diagnostics v_updated = row_count;

  update public.mailshot_fields as mf
  set
    resolver_spec_json = coalesce(mf.resolver_spec_json, '{}'::jsonb) || jsonb_build_object(
      'managed_by', 'approved_view_sync',
      'source_family', split_part(mf.field_key, '.', 1),
      'path', mf.field_key,
      'stale', true,
      'stale_detected_at_utc', v_now::text
    ),
    updated_at_utc = v_now
  where split_part(mf.field_key, '.', 1) in (
      select msf.source_family
      from tmp_mailshot_source_families as msf
    )
    and not exists (
      select 1
      from tmp_mailshot_discovered_fields as mdf
      where mdf.field_key = mf.field_key
    )
    and coalesce((mf.resolver_spec_json ->> 'stale')::boolean, false) = false;

  get diagnostics v_marked_stale = row_count;

  return jsonb_build_object(
    'ok', true,
    'source_family_count', v_source_family_count,
    'source_view_count', v_source_view_count,
    'helper_columns_skipped', v_helper_column_count,
    'discovered_total', v_discovered_total,
    'inserted', v_inserted,
    'updated_existing', v_updated,
    'marked_stale', v_marked_stale,
    'source_views', v_source_views
  );
end;
$function$;

-- mailshot_fields_upsert_global(uuid,text,text,boolean,text[],jsonb,uuid)
CREATE OR REPLACE FUNCTION public.mailshot_fields_upsert_global(p_field_id uuid, p_field_key text, p_label_default text, p_enabled_global boolean, p_allowed_entity_types text[], p_resolver_spec_json jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_field public.mailshot_fields%rowtype;

  v_key text := nullif(btrim(coalesce(p_field_key, '')), '');
  v_label_input text := nullif(btrim(coalesce(p_label_default, '')), '');
  v_label_final text;
  v_enabled_final boolean;

  v_prefix text;
  v_suffix text;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if p_field_id is null and v_key is null then
    raise exception 'field_id or field_key required';
  end if;

  if v_key is not null and position('.' in v_key) = 0 then
    raise exception 'field_key must be namespaced like candidate.email (got: %)', v_key;
  end if;

  if p_field_id is not null then
    select mf.*
      into v_field
    from public.mailshot_fields as mf
    where mf.id = p_field_id;

    if not found then
      raise exception 'mailshot_field not found: %', p_field_id;
    end if;

    if v_key is not null and v_field.field_key <> v_key then
      raise exception 'field_id and field_key refer to different mailshot_fields';
    end if;
  else
    select mf.*
      into v_field
    from public.mailshot_fields as mf
    where mf.field_key = v_key;

    if not found then
      raise exception 'mailshot_field not found for field_key: %', v_key;
    end if;
  end if;

  if v_label_input is null then
    v_label_final := v_field.label_default;
  else
    v_label_final := v_label_input;
  end if;

  if v_label_final is null or v_label_final = '' then
    v_prefix := split_part(v_field.field_key, '.', 1);
    v_suffix := split_part(v_field.field_key, '.', 2);
    v_label_final :=
      initcap(replace(v_prefix, '_', ' ')) || ' — ' ||
      initcap(replace(v_suffix, '_', ' '));
  end if;

  v_enabled_final := coalesce(p_enabled_global, v_field.enabled_global);

  update public.mailshot_fields as mf
  set
    label_default = v_label_final,
    enabled_global = v_enabled_final,
    updated_at_utc = v_now
  where mf.id = v_field.id
  returning mf.* into v_field;

  return jsonb_build_object(
    'ok', true,
    'field', jsonb_build_object(
      'id', v_field.id::text,
      'field_key', v_field.field_key,
      'label_default', v_field.label_default,
      'enabled_global', v_field.enabled_global,
      'allowed_entity_types', to_jsonb(v_field.allowed_entity_types),
      'resolver_spec_json', v_field.resolver_spec_json,
      'created_at_utc', v_field.created_at_utc::text,
      'updated_at_utc', v_field.updated_at_utc::text
    )
  );
end;
$function$;

-- mailshot_fields_upsert_override(uuid,text,text,boolean,uuid)
CREATE OR REPLACE FUNCTION public.mailshot_fields_upsert_override(p_field_id uuid, p_entity_type text, p_label_override text, p_enabled_local boolean, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entity text := nullif(lower(btrim(coalesce(p_entity_type, ''))), '');
  v_label text := nullif(btrim(coalesce(p_label_override, '')), '');

  v_field public.mailshot_fields%rowtype;
  v_row public.mailshot_field_overrides%rowtype;
  v_source_family text;
  v_enabled_final boolean;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if p_field_id is null then
    raise exception 'field_id required';
  end if;

  if v_entity is null then
    raise exception 'entity_type required';
  end if;

  perform 1
  from public.v_mailshot_resolution_graph as rg
  where rg.root_entity_type = v_entity
  limit 1;

  if not found then
    raise exception 'invalid entity_type: %', v_entity;
  end if;

  select mf.*
    into v_field
  from public.mailshot_fields as mf
  where mf.id = p_field_id;

  if not found then
    raise exception 'mailshot_field not found: %', p_field_id;
  end if;

  v_source_family := coalesce(
    nullif(v_field.resolver_spec_json ->> 'source_family', ''),
    split_part(v_field.field_key, '.', 1)
  );

  perform 1
  from public.v_mailshot_resolution_graph as rg
  where rg.root_entity_type = v_entity
    and rg.source_family = v_source_family
  limit 1;

  if not found then
    raise exception 'field source family % is not resolvable for entity_type %', v_source_family, v_entity;
  end if;

  if not (v_entity = any(coalesce(v_field.allowed_entity_types, '{}'::text[]))) then
    raise exception 'field % is not currently visible for entity_type %', v_field.field_key, v_entity;
  end if;

  select mfo.*
    into v_row
  from public.mailshot_field_overrides as mfo
  where mfo.field_id = p_field_id
    and mfo.entity_type = v_entity;

  if found then
    v_enabled_final := coalesce(p_enabled_local, v_row.enabled_local);

    update public.mailshot_field_overrides as mfo
    set
      label_override = v_label,
      enabled_local = v_enabled_final
    where mfo.id = v_row.id
    returning mfo.* into v_row;
  else
    v_enabled_final := coalesce(p_enabled_local, true);

    insert into public.mailshot_field_overrides(
      field_id,
      entity_type,
      label_override,
      enabled_local
    )
    values (
      p_field_id,
      v_entity,
      v_label,
      v_enabled_final
    )
    returning * into v_row;
  end if;

  return jsonb_build_object(
    'ok', true,
    'override', jsonb_build_object(
      'id', v_row.id::text,
      'field_id', v_row.field_id::text,
      'entity_type', v_row.entity_type,
      'label_override', v_row.label_override,
      'enabled_local', v_row.enabled_local
    )
  );
end;
$function$;

-- mailshot_prepare(text,uuid[],text,uuid,uuid)
CREATE OR REPLACE FUNCTION public.mailshot_prepare(p_context_kind text, p_context_ids uuid[], p_output_type text, p_document_template_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_today_uk date := (now() at time zone 'Europe/London')::date;

  v_context_kind text := lower(btrim(coalesce(p_context_kind,'')));
  v_entity_type text;
  v_output_type text := upper(btrim(coalesce(p_output_type,'')));

  v_template public.document_templates%rowtype;
  v_has_template boolean := false;

  v_selected_keys text[] := '{}'::text[];
  v_to_field_key text := null;
  v_email_type text := null;

  v_rows jsonb := '[]'::jsonb;
  v_prepare_attachment_instructions jsonb := '[]'::jsonb;

  v_ctx record;
  v_field record;
  v_ctx_json jsonb;
  v_field_values jsonb;
  v_key text;
  v_path text;
  v_path_arr text[];
  v_val text;

  v_to_value text;
  v_recipient_kind text;
  v_recipient_id uuid;
  v_recipient_display_name text;
  v_candidate_name text;
  v_candidate_display_name text;
  v_client_display_name text;
  v_umbrella_display_name text;
  v_sender_display_name text;

  v_opt_ok boolean;
  v_skip_reason text;

  v_client_settings_json jsonb;
  v_template_content_json jsonb := '{}'::jsonb;
  v_template_attachment_cfg jsonb := '{}'::jsonb;
  v_row_attachment_instructions jsonb := '[]'::jsonb;
  v_template_generic_attachment_instructions jsonb := '[]'::jsonb;
  v_attach_timesheet_pdf boolean := false;
  v_attach_invoice_pdf boolean := false;

  v_sms_or_voice boolean := false;

  v_requested_context_count integer := coalesce(array_length(p_context_ids,1),0);
  v_resolved_context_count integer := 0;
  v_returned_row_count integer := 0;
  v_eligible_count integer := 0;
  v_skipped_count integer := 0;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if v_context_kind is null or v_context_kind = '' then
    raise exception 'context_kind required';
  end if;

  if p_context_ids is null or coalesce(array_length(p_context_ids,1),0) = 0 then
    raise exception 'context_ids[] required';
  end if;

  if v_output_type is null or v_output_type = '' then
    raise exception 'output_type required';
  end if;

  if v_output_type not in ('EMAIL','WHATSAPP','SMS','VOICE','WORD','EXCEL') then
    raise exception 'invalid output_type: %', v_output_type;
  end if;

  v_sms_or_voice := (v_output_type in ('SMS','VOICE'));

  select
    coalesce(
      nullif(btrim(coalesce(tu.display_name, '')), ''),
      nullif(btrim(coalesce(tu.email, '')), ''),
      'CloudTMS user'
    )
  into v_sender_display_name
  from public.tms_users as tu
  where tu.id = p_actor_user_id;

  v_sender_display_name := coalesce(nullif(btrim(coalesce(v_sender_display_name, '')), ''), 'CloudTMS user');

  v_entity_type :=
    case v_context_kind
      when 'candidates' then 'candidate'
      when 'candidate' then 'candidate'
      when 'clients' then 'client'
      when 'client' then 'client'
      when 'contracts' then 'contract'
      when 'contract' then 'contract'
      when 'timesheets' then 'timesheet'
      when 'timesheet' then 'timesheet'
      when 'invoices' then 'invoice'
      when 'invoice' then 'invoice'
      when 'umbrellas' then 'umbrella'
      when 'umbrella' then 'umbrella'
      else null
    end;

  if v_entity_type is null then
    raise exception 'unsupported context_kind: %', v_context_kind;
  end if;

  if p_document_template_id is not null then
    select dt.*
      into v_template
    from public.document_templates as dt
    where dt.id = p_document_template_id;

    if not found then
      raise exception 'document_template not found: %', p_document_template_id;
    end if;

    v_has_template := true;

    if lower(v_template.entity_type) <> v_entity_type then
      raise exception 'template entity_type % does not match context entity_type %', v_template.entity_type, v_entity_type;
    end if;

    if upper(v_template.output_type) <> v_output_type then
      raise exception 'template output_type % does not match requested %', v_template.output_type, v_output_type;
    end if;

    v_selected_keys := coalesce(v_template.selected_field_keys, '{}'::text[]);
    v_email_type := v_template.email_type;
    v_to_field_key := nullif(btrim(coalesce(v_template.template_content_json->>'to_field_key','')), '');
    v_template_content_json := coalesce(v_template.template_content_json, '{}'::jsonb);
  end if;

  if v_to_field_key is null then
    if v_output_type = 'EMAIL' then
      v_to_field_key :=
        case v_entity_type
          when 'candidate' then 'candidate.email'
          when 'contract' then 'candidate.email'
          when 'timesheet' then 'candidate.email'
          when 'client' then 'client.primary_invoice_email'
          when 'invoice' then 'client.primary_invoice_email'
          when 'umbrella' then 'umbrella.remittance_email'
          else 'candidate.email'
        end;
    else
      v_to_field_key :=
        case v_entity_type
          when 'candidate' then 'candidate.phone'
          when 'contract' then 'candidate.phone'
          when 'timesheet' then 'candidate.phone'
          when 'client' then 'client.contact_mobile'
          when 'invoice' then 'client.contact_mobile'
          when 'umbrella' then null
          else 'candidate.phone'
        end;
    end if;
  end if;

  if jsonb_typeof(v_template_content_json->'mailshot_attachments') = 'object' then
    v_template_attachment_cfg := coalesce(v_template_content_json->'mailshot_attachments', '{}'::jsonb);
  else
    v_template_attachment_cfg := '{}'::jsonb;
  end if;

  v_attach_timesheet_pdf := coalesce((v_template_attachment_cfg->>'attach_authoritative_timesheet_pdf')::boolean, false);
  v_attach_invoice_pdf := coalesce((v_template_attachment_cfg->>'attach_authoritative_invoice_pdf')::boolean, false);

  if v_output_type = 'EMAIL'
     and jsonb_typeof(v_template_attachment_cfg->'attachments') = 'array' then
    with template_attachment_src as (
      select
        jbe.ordinality as attachment_ord,
        jsonb_strip_nulls(
          jsonb_build_object(
            'r2_key', nullif(btrim(coalesce(jbe.value->>'r2_key', jbe.value->>'r2Key', '')), ''),
            'filename', nullif(btrim(coalesce(jbe.value->>'filename', jbe.value->>'file_name', jbe.value->>'name', '')), ''),
            'content_type', coalesce(
              nullif(btrim(coalesce(jbe.value->>'content_type', jbe.value->>'contentType', '')), ''),
              'application/octet-stream'
            ),
            'source', nullif(btrim(coalesce(jbe.value->>'source', '')), ''),
            'source_label', nullif(btrim(coalesce(jbe.value->>'source_label', jbe.value->>'sourceLabel', '')), ''),
            'read_only', case
              when jbe.value ? 'read_only' and jsonb_typeof(jbe.value->'read_only') = 'boolean'
                then (jbe.value->>'read_only')::boolean
              when jbe.value ? 'readOnly' and jsonb_typeof(jbe.value->'readOnly') = 'boolean'
                then (jbe.value->>'readOnly')::boolean
              else false
            end,
            'size_bytes', case
              when nullif(btrim(coalesce(jbe.value->>'size_bytes', jbe.value->>'sizeBytes', '')), '') is not null
                   and btrim(coalesce(jbe.value->>'size_bytes', jbe.value->>'sizeBytes', '')) ~ '^\d+$'
                then (coalesce(jbe.value->>'size_bytes', jbe.value->>'sizeBytes'))::bigint
              else null
            end
          )
        ) as attachment_item,
        nullif(btrim(coalesce(jbe.value->>'r2_key', jbe.value->>'r2Key', '')), '') as r2_key,
        nullif(btrim(coalesce(jbe.value->>'filename', jbe.value->>'file_name', jbe.value->>'name', '')), '') as filename,
        coalesce(
          nullif(btrim(coalesce(jbe.value->>'content_type', jbe.value->>'contentType', '')), ''),
          'application/octet-stream'
        ) as content_type
      from jsonb_array_elements(v_template_attachment_cfg->'attachments') with ordinality as jbe(value, ordinality)
      where jsonb_typeof(jbe.value) = 'object'
    ),
    template_attachment_grp as (
      select
        min(tas.attachment_ord) as first_ord,
        (array_agg(tas.attachment_item order by tas.attachment_ord))[1] as first_item
      from template_attachment_src as tas
      where tas.r2_key is not null
        and tas.filename is not null
      group by
        tas.r2_key,
        tas.filename,
        tas.content_type
    )
    select coalesce(
      jsonb_agg(tag.first_item order by tag.first_ord),
      '[]'::jsonb
    )
      into v_template_generic_attachment_instructions
    from template_attachment_grp as tag;
  else
    v_template_generic_attachment_instructions := '[]'::jsonb;
  end if;

  drop table if exists tmp_selected_fields;
  create temporary table tmp_selected_fields(
    field_ord integer not null,
    field_key text not null,
    path_text text not null,
    path_arr text[] not null
  ) on commit drop;

  if v_selected_keys is not null and array_length(v_selected_keys,1) > 0 then
    insert into tmp_selected_fields(field_ord, field_key, path_text, path_arr)
    select
      src.field_ord,
      src.field_key,
      src.path_text,
      string_to_array(src.path_text, '.') as path_arr
    from (
      select
        key_src.ord::integer as field_ord,
        key_src.field_key,
        coalesce(
          nullif(btrim(coalesce(mf.resolver_spec_json->>'path','')), ''),
          key_src.field_key
        ) as path_text
      from unnest(v_selected_keys) with ordinality as key_src(field_key, ord)
      left join public.mailshot_fields as mf
        on mf.field_key = key_src.field_key
      where key_src.field_key is not null
        and length(btrim(key_src.field_key)) > 0
    ) as src;
  end if;

  drop table if exists tmp_ctx;
  create temporary table tmp_ctx(
    context_id uuid not null,
    ctx_json jsonb not null
  ) on commit drop;

  drop table if exists tmp_prepared_rows;
  create temporary table tmp_prepared_rows(
    row_ord bigserial primary key,
    eligible boolean not null,
    payload jsonb not null
  ) on commit drop;

  if v_entity_type = 'candidate' then
    insert into tmp_ctx(context_id, ctx_json)
    select
      c.id,
      jsonb_build_object(
        'candidate', to_jsonb(c),
        'umbrella', case when u.id is null then null else to_jsonb(u) end,
        'system', jsonb_build_object(
          'today_ymd', v_today_uk::text,
          'now_utc', v_now::text,
          'sender_display_name', v_sender_display_name
        )
      )
    from public.candidates as c
    left join public.umbrellas as u
      on u.id = c.umbrella_id
    where c.id = any(p_context_ids);
  elsif v_entity_type = 'client' then
    insert into tmp_ctx(context_id, ctx_json)
    select
      cl.id,
      jsonb_build_object(
        'client', to_jsonb(cl),
        'client_settings', case when cs.id is null then null else to_jsonb(cs) end,
        'system', jsonb_build_object(
          'today_ymd', v_today_uk::text,
          'now_utc', v_now::text,
          'sender_display_name', v_sender_display_name
        )
      )
    from public.clients as cl
    left join lateral (
      select cs1.*
      from public.client_settings as cs1
      where cs1.client_id = cl.id
      order by cs1.effective_from desc
      limit 1
    ) as cs on true
    where cl.id = any(p_context_ids);
  elsif v_entity_type = 'contract' then
    insert into tmp_ctx(context_id, ctx_json)
    select
      ct.id,
      jsonb_build_object(
        'contract', to_jsonb(ct),
        'candidate', case when c.id is null then null else to_jsonb(c) end,
        'client', case when cl.id is null then null else to_jsonb(cl) end,
        'client_settings', case when cs.id is null then null else to_jsonb(cs) end,
        'umbrella', case when u.id is null then null else to_jsonb(u) end,
        'system', jsonb_build_object(
          'today_ymd', v_today_uk::text,
          'now_utc', v_now::text,
          'sender_display_name', v_sender_display_name
        )
      )
    from public.contracts as ct
    left join public.candidates as c
      on c.id = ct.candidate_id
    left join public.umbrellas as u
      on u.id = c.umbrella_id
    left join public.clients as cl
      on cl.id = ct.client_id
    left join lateral (
      select cs1.*
      from public.client_settings as cs1
      where cs1.client_id = cl.id
      order by cs1.effective_from desc
      limit 1
    ) as cs on true
    where ct.id = any(p_context_ids);
  elsif v_entity_type = 'timesheet' then
    insert into tmp_ctx(context_id, ctx_json)
    select
      ts.timesheet_id,
      jsonb_build_object(
        'timesheet', to_jsonb(ts),
        'contract', case when ct.id is null then null else to_jsonb(ct) end,
        'candidate', case when c.id is null then null else to_jsonb(c) end,
        'client', case when cl.id is null then null else to_jsonb(cl) end,
        'client_settings', case when cs.id is null then null else to_jsonb(cs) end,
        'umbrella', case when u.id is null then null else to_jsonb(u) end,
        'system', jsonb_build_object(
          'today_ymd', v_today_uk::text,
          'now_utc', v_now::text,
          'sender_display_name', v_sender_display_name
        )
      )
    from public.timesheets as ts
    left join public.contracts as ct
      on ct.id = ts.contract_id
    left join public.candidates as c
      on c.id = ct.candidate_id
    left join public.umbrellas as u
      on u.id = c.umbrella_id
    left join public.clients as cl
      on cl.id = ct.client_id
    left join lateral (
      select cs1.*
      from public.client_settings as cs1
      where cs1.client_id = cl.id
      order by cs1.effective_from desc
      limit 1
    ) as cs on true
    where ts.timesheet_id = any(p_context_ids);
  elsif v_entity_type = 'invoice' then
    insert into tmp_ctx(context_id, ctx_json)
    select
      inv.id,
      jsonb_build_object(
        'invoice', to_jsonb(inv),
        'client', case when cl.id is null then null else to_jsonb(cl) end,
        'client_settings', case when cs.id is null then null else to_jsonb(cs) end,
        'system', jsonb_build_object(
          'today_ymd', v_today_uk::text,
          'now_utc', v_now::text,
          'sender_display_name', v_sender_display_name
        )
      )
    from public.invoices as inv
    left join public.clients as cl
      on cl.id = inv.client_id
    left join lateral (
      select cs1.*
      from public.client_settings as cs1
      where cs1.client_id = cl.id
      order by cs1.effective_from desc
      limit 1
    ) as cs on true
    where inv.id = any(p_context_ids);
  elsif v_entity_type = 'umbrella' then
    insert into tmp_ctx(context_id, ctx_json)
    select
      u.id,
      jsonb_build_object(
        'umbrella', to_jsonb(u),
        'system', jsonb_build_object(
          'today_ymd', v_today_uk::text,
          'now_utc', v_now::text,
          'sender_display_name', v_sender_display_name
        )
      )
    from public.umbrellas as u
    where u.id = any(p_context_ids);
  end if;

  select count(*)
    into v_resolved_context_count
  from tmp_ctx as t;

  for v_ctx in
    select t.context_id, t.ctx_json
    from tmp_ctx as t
    order by t.context_id::text
  loop
    v_ctx_json := v_ctx.ctx_json;
    v_field_values := '{}'::jsonb;
    v_row_attachment_instructions := '[]'::jsonb;
    v_candidate_name := null;
    v_recipient_display_name := null;

    if exists (select 1 from tmp_selected_fields) then
      for v_field in
        select tsf.field_key, tsf.path_text, tsf.path_arr
        from tmp_selected_fields as tsf
        order by tsf.field_ord
      loop
        v_key := v_field.field_key;
        v_path := v_field.path_text;
        v_path_arr := v_field.path_arr;

        if v_path_arr is null or array_length(v_path_arr,1) = 0 then
          v_val := null;
        elsif array_length(v_path_arr,1) = 1 then
          v_val := v_ctx_json ->> v_path_arr[1];
        elsif array_length(v_path_arr,1) = 2 then
          v_val := (v_ctx_json -> v_path_arr[1]) ->> v_path_arr[2];
        else
          v_val := v_ctx_json #>> v_path_arr;
        end if;

        v_field_values := v_field_values || jsonb_build_object(v_key, v_val);
      end loop;
    end if;

    v_path := v_to_field_key;
    v_path_arr := string_to_array(v_path, '.');

    if v_path_arr is null or array_length(v_path_arr,1) = 0 then
      v_to_value := null;
      v_recipient_kind := null;
    else
      v_recipient_kind := lower(v_path_arr[1]);
      if array_length(v_path_arr,1) = 1 then
        v_to_value := v_ctx_json ->> v_path_arr[1];
      elsif array_length(v_path_arr,1) = 2 then
        v_to_value := (v_ctx_json -> v_path_arr[1]) ->> v_path_arr[2];
      else
        v_to_value := v_ctx_json #>> v_path_arr;
      end if;
    end if;

    v_to_value := nullif(btrim(coalesce(v_to_value,'')), '');

    v_recipient_id := null;
    if v_recipient_kind = 'candidate' then
      v_recipient_id := nullif((v_ctx_json->'candidate'->>'id'),'')::uuid;
    elsif v_recipient_kind = 'client' then
      v_recipient_id := nullif((v_ctx_json->'client'->>'id'),'')::uuid;
    elsif v_recipient_kind = 'umbrella' then
      v_recipient_id := nullif((v_ctx_json->'umbrella'->>'id'),'')::uuid;
    end if;

    v_candidate_display_name := nullif(btrim(coalesce(v_ctx_json->'candidate'->>'display_name','')), '');
    if v_candidate_display_name is null then
      v_candidate_display_name := nullif(
        btrim(
          concat_ws(
            ' ',
            nullif(btrim(coalesce(v_ctx_json->'candidate'->>'first_name','')), ''),
            nullif(btrim(coalesce(v_ctx_json->'candidate'->>'last_name','')), '')
          )
        ),
        ''
      );
    end if;

    v_client_display_name := nullif(btrim(coalesce(v_ctx_json->'client'->>'name','')), '');
    v_umbrella_display_name := nullif(btrim(coalesce(v_ctx_json->'umbrella'->>'name','')), '');

    v_candidate_name := v_candidate_display_name;

    v_recipient_display_name :=
      case v_recipient_kind
        when 'candidate' then coalesce(v_candidate_display_name, v_to_value)
        when 'client' then coalesce(v_client_display_name, v_to_value)
        when 'umbrella' then coalesce(v_umbrella_display_name, v_to_value)
        else coalesce(v_candidate_display_name, v_client_display_name, v_umbrella_display_name, v_to_value)
      end;

    v_opt_ok := true;
    v_skip_reason := null;

    if v_to_value is null then
      v_opt_ok := false;
      v_skip_reason := 'MISSING_RECIPIENT';
    end if;

    if v_opt_ok = true and v_recipient_kind = 'candidate' then
      if v_output_type = 'EMAIL' then
        v_opt_ok := coalesce((v_ctx_json->'candidate'->>'opt_in_email')::boolean, false);
      elsif v_output_type = 'WHATSAPP' then
        v_opt_ok := coalesce((v_ctx_json->'candidate'->>'opt_in_whatsapp')::boolean, false);
      elsif v_sms_or_voice = true then
        v_opt_ok := coalesce((v_ctx_json->'candidate'->>'opt_in_sms')::boolean, false);
      else
        v_opt_ok := true;
      end if;

      if v_opt_ok = false then
        v_skip_reason := 'OPTOUT';
      end if;
    elsif v_opt_ok = true and v_recipient_kind = 'client' then
      v_client_settings_json := v_ctx_json->'client_settings';

      if v_client_settings_json is null or jsonb_typeof(v_client_settings_json) <> 'object' then
        v_opt_ok := true;
      else
        if v_output_type = 'EMAIL' then
          v_opt_ok := coalesce((v_client_settings_json->>'opt_in_email')::boolean, true);
        elsif v_output_type = 'WHATSAPP' then
          v_opt_ok := coalesce((v_client_settings_json->>'opt_in_whatsapp')::boolean, true);
        elsif v_sms_or_voice = true then
          v_opt_ok := coalesce((v_client_settings_json->>'opt_in_sms')::boolean, true);
        else
          v_opt_ok := true;
        end if;
      end if;

      if v_opt_ok = false then
        v_skip_reason := 'OPTOUT';
      end if;
    end if;

    if v_output_type = 'EMAIL' and v_entity_type = 'timesheet' and v_attach_timesheet_pdf = true then
      v_row_attachment_instructions := v_row_attachment_instructions || jsonb_build_array(
        jsonb_build_object(
          'kind', 'AUTHORITATIVE_TIMESHEET_PDF',
          'context_id', v_ctx.context_id::text,
          'entity_type', v_entity_type,
          'filename', format('Timesheet_%s.pdf', v_ctx.context_id::text),
          'content_type', 'application/pdf'
        )
      );
    elsif v_output_type = 'EMAIL' and v_entity_type = 'invoice' and v_attach_invoice_pdf = true then
      v_row_attachment_instructions := v_row_attachment_instructions || jsonb_build_array(
        jsonb_build_object(
          'kind', 'AUTHORITATIVE_INVOICE_PDF',
          'context_id', v_ctx.context_id::text,
          'entity_type', v_entity_type,
          'filename', format('Invoice_%s.pdf', v_ctx.context_id::text),
          'content_type', 'application/pdf'
        )
      );
    end if;

    if v_output_type = 'EMAIL' then
      with row_attachment_src as (
        select
          jbe.ordinality as attachment_ord,
          jbe.value as attachment_item,
          nullif(btrim(coalesce(jbe.value->>'kind', '')), '') as kind,
          nullif(btrim(coalesce(jbe.value->>'context_id', jbe.value->>'contextId', '')), '') as context_id,
          nullif(btrim(coalesce(jbe.value->>'entity_type', jbe.value->>'entityType', '')), '') as entity_type,
          nullif(btrim(coalesce(jbe.value->>'invoice_id', jbe.value->>'invoiceId', '')), '') as invoice_id,
          nullif(btrim(coalesce(jbe.value->>'r2_key', jbe.value->>'r2Key', '')), '') as r2_key,
          nullif(btrim(coalesce(jbe.value->>'filename', jbe.value->>'file_name', jbe.value->>'name', '')), '') as filename,
          nullif(btrim(coalesce(jbe.value->>'content_type', jbe.value->>'contentType', '')), '') as content_type,
          nullif(btrim(coalesce(jbe.value->>'source', '')), '') as source,
          nullif(btrim(coalesce(jbe.value->>'source_label', jbe.value->>'sourceLabel', '')), '') as source_label,
          case
            when jbe.value ? 'read_only' and jsonb_typeof(jbe.value->'read_only') = 'boolean'
              then (jbe.value->>'read_only')::boolean
            when jbe.value ? 'readOnly' and jsonb_typeof(jbe.value->'readOnly') = 'boolean'
              then (jbe.value->>'readOnly')::boolean
            else false
          end as read_only,
          case
            when nullif(btrim(coalesce(jbe.value->>'size_bytes', jbe.value->>'sizeBytes', '')), '') is not null
                 and btrim(coalesce(jbe.value->>'size_bytes', jbe.value->>'sizeBytes', '')) ~ '^\d+$'
              then (coalesce(jbe.value->>'size_bytes', jbe.value->>'sizeBytes'))::bigint
            else null
          end as size_bytes
        from jsonb_array_elements(
          coalesce(v_row_attachment_instructions, '[]'::jsonb) ||
          coalesce(v_template_generic_attachment_instructions, '[]'::jsonb)
        ) with ordinality as jbe(value, ordinality)
        where jsonb_typeof(jbe.value) = 'object'
      ),
      row_attachment_grp as (
        select
          min(ras.attachment_ord) as first_ord,
          (array_agg(ras.attachment_item order by ras.attachment_ord))[1] as first_item
        from row_attachment_src as ras
        where ras.kind is not null
           or ras.invoice_id is not null
           or ras.r2_key is not null
        group by
          ras.kind,
          ras.context_id,
          ras.entity_type,
          ras.invoice_id,
          ras.r2_key,
          ras.filename,
          ras.content_type
      )
      select coalesce(
        jsonb_agg(rag.first_item order by rag.first_ord),
        '[]'::jsonb
      )
        into v_row_attachment_instructions
      from row_attachment_grp as rag;
    end if;

    insert into tmp_prepared_rows(eligible, payload)
    values (
      v_opt_ok,
      jsonb_build_object(
        'context_id', v_ctx.context_id::text,
        'context_kind', v_context_kind,
        'entity_type', v_entity_type,
        'output_type', v_output_type,
        'document_template_id', case when p_document_template_id is null then null else p_document_template_id::text end,
        'to_field_key', v_to_field_key,
        'to', v_to_value,
        'recipient_kind', v_recipient_kind,
        'recipient_id', case when v_recipient_id is null then null else v_recipient_id::text end,
        'recipient_display_name', v_recipient_display_name,
        'candidate_name', v_candidate_name,
        'eligible', v_opt_ok,
        'skip_reason', v_skip_reason,
        'field_values', v_field_values,
        'template_content_json', case when v_has_template then v_template_content_json else '{}'::jsonb end,
        'email_type', v_email_type,
        'attachment_instructions', v_row_attachment_instructions,
        'attachments', v_row_attachment_instructions
      )
    );
  end loop;

  select
    coalesce(jsonb_agg(tpr.payload order by tpr.row_ord), '[]'::jsonb),
    count(*)::integer,
    count(*) filter (where tpr.eligible)::integer,
    count(*) filter (where not tpr.eligible)::integer
  into
    v_rows,
    v_returned_row_count,
    v_eligible_count,
    v_skipped_count
  from tmp_prepared_rows as tpr;

  return jsonb_build_object(
    'ok', true,
    'context_kind', v_context_kind,
    'entity_type', v_entity_type,
    'output_type', v_output_type,
    'document_template_id', case when p_document_template_id is null then null else p_document_template_id::text end,
    'selected_field_keys', to_jsonb(v_selected_keys),
    'to_field_key', v_to_field_key,
    'requested_context_count', v_requested_context_count,
    'resolved_context_count', v_resolved_context_count,
    'returned_row_count', v_returned_row_count,
    'eligible_count', v_eligible_count,
    'skipped_count', v_skipped_count,
    'prepare_counts', jsonb_build_object(
      'requested_context_count', v_requested_context_count,
      'resolved_context_count', v_resolved_context_count,
      'returned_row_count', v_returned_row_count,
      'eligible_count', v_eligible_count,
      'skipped_count', v_skipped_count
    ),
    'attachment_instructions', v_prepare_attachment_instructions,
    'attachments', v_prepare_attachment_instructions,
    'rows', v_rows
  );
end;
$function$;

-- mailshot_run_cancel_pending(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.mailshot_run_cancel_pending(p_mailshot_run_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text := nullif(btrim(coalesce(p_reason,'')), '');
  v_run public.mailshot_runs%rowtype;

  v_total_rows int := 0;
  v_deleted_pending int := 0;
  v_skipped_already_sent int := 0;

  v_deleted_mail_ids jsonb := '[]'::jsonb;
  v_deleted_comms_ids jsonb := '[]'::jsonb;

  v_mail_row public.mail_outbox%rowtype;
  v_comms_row public.comms_outbox%rowtype;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if p_mailshot_run_id is null then
    raise exception 'mailshot_run_id required';
  end if;

  select mr.*
  into v_run
  from public.mailshot_runs as mr
  where mr.id = p_mailshot_run_id
  for update;

  if not found then
    raise exception 'mailshot_run not found';
  end if;

  for v_mail_row in
    select mo.*
    from public.mail_outbox as mo
    where mo.mailshot_run_id = p_mailshot_run_id
    order by mo.created_at_utc asc, mo.id::text asc
    for update
  loop
    v_total_rows := v_total_rows + 1;

    if v_mail_row.read_at is not null
       or v_mail_row.delivered_at is not null
       or v_mail_row.sent_at is not null then
      v_skipped_already_sent := v_skipped_already_sent + 1;
      continue;
    end if;

    if upper(coalesce(v_mail_row.status::text,'')) not in ('QUEUED','FAILED') then
      v_skipped_already_sent := v_skipped_already_sent + 1;
      continue;
    end if;

    perform public._audit_insert(
      'outbox',
      v_mail_row.id::text,
      'MAILSHOT_RUN_CANCEL_PENDING_DELETE',
      jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'mailshot_run_id', p_mailshot_run_id::text,
        'status', v_mail_row.status::text,
        'to_address', v_mail_row."to"
      ),
      null,
      v_reason,
      p_actor_user_id
    );

    delete from public.mail_outbox as mo
    where mo.id = v_mail_row.id;

    v_deleted_pending := v_deleted_pending + 1;
    v_deleted_mail_ids := v_deleted_mail_ids || jsonb_build_array(v_mail_row.id::text);
  end loop;

  for v_comms_row in
    select co.*
    from public.comms_outbox as co
    where co.mailshot_run_id = p_mailshot_run_id
    order by co.created_at_utc asc, co.id::text asc
    for update
  loop
    v_total_rows := v_total_rows + 1;

    if v_comms_row.read_at is not null
       or v_comms_row.delivered_at is not null
       or v_comms_row.sent_at is not null then
      v_skipped_already_sent := v_skipped_already_sent + 1;
      continue;
    end if;

    if upper(coalesce(v_comms_row.status,'')) not in ('QUEUED','FAILED') then
      v_skipped_already_sent := v_skipped_already_sent + 1;
      continue;
    end if;

    perform public._audit_insert(
      'outbox',
      v_comms_row.id::text,
      'MAILSHOT_RUN_CANCEL_PENDING_DELETE',
      jsonb_build_object(
        'channel', v_comms_row.channel,
        'outbox_id', v_comms_row.id::text,
        'mailshot_run_id', p_mailshot_run_id::text,
        'status', v_comms_row.status,
        'to_address', v_comms_row.to_address
      ),
      null,
      v_reason,
      p_actor_user_id
    );

    delete from public.comms_outbox as co
    where co.id = v_comms_row.id;

    v_deleted_pending := v_deleted_pending + 1;
    v_deleted_comms_ids := v_deleted_comms_ids || jsonb_build_array(v_comms_row.id::text);
  end loop;

  perform public._audit_insert(
    'mailshot_run',
    p_mailshot_run_id::text,
    'MAILSHOT_RUN_CANCEL_PENDING',
    jsonb_build_object(
      'mailshot_run_id', p_mailshot_run_id::text,
      'total_rows', v_total_rows
    ),
    jsonb_build_object(
      'mailshot_run_id', p_mailshot_run_id::text,
      'total_rows', v_total_rows,
      'deleted_pending', v_deleted_pending,
      'skipped_already_sent', v_skipped_already_sent,
      'deleted_mail_outbox_ids', v_deleted_mail_ids,
      'deleted_comms_outbox_ids', v_deleted_comms_ids
    ),
    v_reason,
    p_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'mailshot_run_id', p_mailshot_run_id::text,
    'total_rows', v_total_rows,
    'deleted_pending', v_deleted_pending,
    'skipped_already_sent', v_skipped_already_sent,
    'deleted_mail_outbox_ids', v_deleted_mail_ids,
    'deleted_comms_outbox_ids', v_deleted_comms_ids
  );
end;
$function$;

-- mailshot_run_delete_if_unsent(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.mailshot_run_delete_if_unsent(p_mailshot_run_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text := nullif(btrim(coalesce(p_reason,'')), '');
  v_run public.mailshot_runs%rowtype;

  v_total_rows int := 0;
  v_mail_row_count int := 0;
  v_comms_row_count int := 0;

  v_blocking_mail_sent int := 0;
  v_blocking_mail_delivered int := 0;
  v_blocking_mail_read int := 0;

  v_blocking_comms_sent int := 0;
  v_blocking_comms_delivered int := 0;
  v_blocking_comms_read int := 0;

  v_blocking_total int := 0;

  v_deleted_mail_ids jsonb := '[]'::jsonb;
  v_deleted_comms_ids jsonb := '[]'::jsonb;

  v_mail_row public.mail_outbox%rowtype;
  v_comms_row public.comms_outbox%rowtype;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if p_mailshot_run_id is null then
    raise exception 'mailshot_run_id required';
  end if;

  select mr.*
  into v_run
  from public.mailshot_runs as mr
  where mr.id = p_mailshot_run_id
  for update;

  if not found then
    raise exception 'mailshot_run not found';
  end if;

  select count(*)::int
  into v_mail_row_count
  from public.mail_outbox as mo
  where mo.mailshot_run_id = p_mailshot_run_id;

  select count(*)::int
  into v_comms_row_count
  from public.comms_outbox as co
  where co.mailshot_run_id = p_mailshot_run_id;

  v_total_rows := coalesce(v_mail_row_count, 0) + coalesce(v_comms_row_count, 0);

  select count(*)::int
  into v_blocking_mail_read
  from public.mail_outbox as mo
  where mo.mailshot_run_id = p_mailshot_run_id
    and mo.read_at is not null;

  select count(*)::int
  into v_blocking_mail_delivered
  from public.mail_outbox as mo
  where mo.mailshot_run_id = p_mailshot_run_id
    and mo.read_at is null
    and mo.delivered_at is not null;

  select count(*)::int
  into v_blocking_mail_sent
  from public.mail_outbox as mo
  where mo.mailshot_run_id = p_mailshot_run_id
    and mo.read_at is null
    and mo.delivered_at is null
    and mo.sent_at is not null;

  select count(*)::int
  into v_blocking_comms_read
  from public.comms_outbox as co
  where co.mailshot_run_id = p_mailshot_run_id
    and co.read_at is not null;

  select count(*)::int
  into v_blocking_comms_delivered
  from public.comms_outbox as co
  where co.mailshot_run_id = p_mailshot_run_id
    and co.read_at is null
    and co.delivered_at is not null;

  select count(*)::int
  into v_blocking_comms_sent
  from public.comms_outbox as co
  where co.mailshot_run_id = p_mailshot_run_id
    and co.read_at is null
    and co.delivered_at is null
    and co.sent_at is not null;

  v_blocking_total :=
      coalesce(v_blocking_mail_sent, 0)
    + coalesce(v_blocking_mail_delivered, 0)
    + coalesce(v_blocking_mail_read, 0)
    + coalesce(v_blocking_comms_sent, 0)
    + coalesce(v_blocking_comms_delivered, 0)
    + coalesce(v_blocking_comms_read, 0);

  if v_blocking_total > 0 then
    return jsonb_build_object(
      'ok', true,
      'deleted', false,
      'reason', 'RUN_ALREADY_PARTIALLY_SENT',
      'mailshot_run_id', p_mailshot_run_id::text,
      'counts', jsonb_build_object(
        'total_rows', v_total_rows,
        'mail_rows', v_mail_row_count,
        'comms_rows', v_comms_row_count,
        'blocking_mail_sent', v_blocking_mail_sent,
        'blocking_mail_delivered', v_blocking_mail_delivered,
        'blocking_mail_read', v_blocking_mail_read,
        'blocking_comms_sent', v_blocking_comms_sent,
        'blocking_comms_delivered', v_blocking_comms_delivered,
        'blocking_comms_read', v_blocking_comms_read,
        'blocking_total', v_blocking_total
      )
    );
  end if;

  for v_mail_row in
    select mo.*
    from public.mail_outbox as mo
    where mo.mailshot_run_id = p_mailshot_run_id
    order by mo.created_at_utc asc, mo.id::text asc
    for update
  loop
    perform public._audit_insert(
      'outbox',
      v_mail_row.id::text,
      'MAILSHOT_RUN_DELETE_IF_UNSENT_CHILD_DELETE',
      jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', v_mail_row.status::text,
        'to_address', v_mail_row."to",
        'mailshot_run_id', p_mailshot_run_id::text
      ),
      null,
      v_reason,
      p_actor_user_id
    );

    delete from public.mail_outbox as mo
    where mo.id = v_mail_row.id;

    v_deleted_mail_ids := v_deleted_mail_ids || jsonb_build_array(v_mail_row.id::text);
  end loop;

  for v_comms_row in
    select co.*
    from public.comms_outbox as co
    where co.mailshot_run_id = p_mailshot_run_id
    order by co.created_at_utc asc, co.id::text asc
    for update
  loop
    perform public._audit_insert(
      'outbox',
      v_comms_row.id::text,
      'MAILSHOT_RUN_DELETE_IF_UNSENT_CHILD_DELETE',
      jsonb_build_object(
        'channel', v_comms_row.channel,
        'outbox_id', v_comms_row.id::text,
        'status', v_comms_row.status,
        'to_address', v_comms_row.to_address,
        'mailshot_run_id', p_mailshot_run_id::text
      ),
      null,
      v_reason,
      p_actor_user_id
    );

    delete from public.comms_outbox as co
    where co.id = v_comms_row.id;

    v_deleted_comms_ids := v_deleted_comms_ids || jsonb_build_array(v_comms_row.id::text);
  end loop;

  perform public._audit_insert(
    'mailshot_run',
    p_mailshot_run_id::text,
    'MAILSHOT_RUN_DELETE_IF_UNSENT',
    jsonb_build_object(
      'mailshot_run_id', p_mailshot_run_id::text,
      'context_kind', v_run.context_kind,
      'output_type', v_run.output_type,
      'document_template_id', case when v_run.document_template_id is null then null else v_run.document_template_id::text end,
      'created_by', case when v_run.created_by is null then null else v_run.created_by::text end,
      'created_at_utc', v_run.created_at_utc::text,
      'delivery_timing_json', v_run.delivery_timing_json
    ),
    jsonb_build_object(
      'deleted', true,
      'deleted_mail_outbox_ids', v_deleted_mail_ids,
      'deleted_comms_outbox_ids', v_deleted_comms_ids,
      'mail_row_count', v_mail_row_count,
      'comms_row_count', v_comms_row_count,
      'total_rows', v_total_rows
    ),
    v_reason,
    p_actor_user_id
  );

  delete from public.mailshot_runs as mr
  where mr.id = p_mailshot_run_id;

  return jsonb_build_object(
    'ok', true,
    'deleted', true,
    'mailshot_run_id', p_mailshot_run_id::text,
    'counts', jsonb_build_object(
      'total_rows', v_total_rows,
      'mail_rows', v_mail_row_count,
      'comms_rows', v_comms_row_count,
      'blocking_mail_sent', 0,
      'blocking_mail_delivered', 0,
      'blocking_mail_read', 0,
      'blocking_comms_sent', 0,
      'blocking_comms_delivered', 0,
      'blocking_comms_read', 0,
      'blocking_total', 0
    ),
    'deleted_mail_outbox_ids', v_deleted_mail_ids,
    'deleted_comms_outbox_ids', v_deleted_comms_ids
  );
end;
$function$;

-- mailshot_run_get(uuid)
CREATE OR REPLACE FUNCTION public.mailshot_run_get(p_mailshot_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb;
begin
  if p_mailshot_run_id is null then
    raise exception 'mailshot_run_id required';
  end if;

  with run_row as (
    select
      mr.id,
      mr.context_kind,
      mr.output_type,
      mr.document_template_id,
      mr.created_by,
      mr.created_at_utc,
      case
        when jsonb_typeof(mr.selection_json) = 'object' then mr.selection_json
        else '{}'::jsonb
      end as selection_json,
      case
        when jsonb_typeof(mr.result_json) = 'object' then mr.result_json
        else '{}'::jsonb
      end as result_json,
      case
        when jsonb_typeof(mr.delivery_timing_json) = 'object' then mr.delivery_timing_json
        else '{}'::jsonb
      end as delivery_timing_json,
      dt.filename as template_filename
    from public.mailshot_runs as mr
    left join public.document_templates as dt
      on dt.id = mr.document_template_id
    where mr.id = p_mailshot_run_id
    limit 1
  ),
  initial_counts as (
    select
      rr.id,
      case
        when jsonb_typeof(rr.result_json->'queued') = 'number' then (rr.result_json->>'queued')::int
        when coalesce(rr.result_json->>'queued', '') ~ '^-?\d+$' then (rr.result_json->>'queued')::int
        else 0
      end as initial_queued,
      case
        when jsonb_typeof(rr.result_json->'skipped') = 'number' then (rr.result_json->>'skipped')::int
        when coalesce(rr.result_json->>'skipped', '') ~ '^-?\d+$' then (rr.result_json->>'skipped')::int
        else 0
      end as initial_skipped,
      case
        when jsonb_typeof(rr.result_json->'failed') = 'number' then (rr.result_json->>'failed')::int
        when coalesce(rr.result_json->>'failed', '') ~ '^-?\d+$' then (rr.result_json->>'failed')::int
        else 0
      end as initial_failed
    from run_row as rr
  ),
  mail_counts as (
    select
      count(*)::int as total_rows,
      count(*) filter (
        where mo.read_at is null
          and mo.delivered_at is null
          and mo.sent_at is null
          and mo.failed_at is null
      )::int as pending_total,
      count(*) filter (
        where mo.read_at is null
          and mo.delivered_at is null
          and mo.sent_at is null
          and mo.failed_at is not null
      )::int as failed_total,
      count(*) filter (
        where mo.read_at is null
          and mo.delivered_at is null
          and mo.sent_at is not null
      )::int as sent_total,
      count(*) filter (
        where mo.read_at is null
          and mo.delivered_at is not null
      )::int as delivered_total,
      count(*) filter (
        where mo.read_at is not null
      )::int as read_total,
      count(*) filter (
        where mo.read_at is not null
           or (mo.read_at is null and mo.delivered_at is not null)
           or (mo.read_at is null and mo.delivered_at is null and mo.sent_at is not null)
      )::int as blocking_total,
      count(*) filter (
        where mo.read_at is null
          and mo.delivered_at is null
          and mo.sent_at is null
      )::int as cancelable_total
    from public.mail_outbox as mo
    where mo.mailshot_run_id = p_mailshot_run_id
  ),
  comms_counts as (
    select
      count(*)::int as total_rows,
      count(*) filter (
        where co.read_at is null
          and co.delivered_at is null
          and co.sent_at is null
          and co.failed_at is null
      )::int as pending_total,
      count(*) filter (
        where co.read_at is null
          and co.delivered_at is null
          and co.sent_at is null
          and co.failed_at is not null
      )::int as failed_total,
      count(*) filter (
        where co.read_at is null
          and co.delivered_at is null
          and co.sent_at is not null
      )::int as sent_total,
      count(*) filter (
        where co.read_at is null
          and co.delivered_at is not null
      )::int as delivered_total,
      count(*) filter (
        where co.read_at is not null
      )::int as read_total,
      count(*) filter (
        where co.read_at is not null
           or (co.read_at is null and co.delivered_at is not null)
           or (co.read_at is null and co.delivered_at is null and co.sent_at is not null)
      )::int as blocking_total,
      count(*) filter (
        where co.read_at is null
          and co.delivered_at is null
          and co.sent_at is null
      )::int as cancelable_total
    from public.comms_outbox as co
    where co.mailshot_run_id = p_mailshot_run_id
  ),
  mail_preview as (
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', mp.id::text,
            'status', mp.status,
            'to_address', mp.to_address,
            'sent_at', mp.sent_at,
            'delivered_at', mp.delivered_at,
            'read_at', mp.read_at,
            'failed_at', mp.failed_at
          )
          order by mp.created_at_utc desc, mp.id desc
        ),
        '[]'::jsonb
      ) as items
    from (
      select
        mo.id,
        mo.status,
        mo."to" as to_address,
        mo.sent_at,
        mo.delivered_at,
        mo.read_at,
        mo.failed_at,
        mo.created_at_utc
      from public.mail_outbox as mo
      where mo.mailshot_run_id = p_mailshot_run_id
      order by mo.created_at_utc desc, mo.id desc
      limit 25
    ) as mp
  ),
  comms_preview as (
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', cp.id::text,
            'channel', cp.channel,
            'status', cp.status,
            'to_address', cp.to_address,
            'sent_at', cp.sent_at,
            'delivered_at', cp.delivered_at,
            'read_at', cp.read_at,
            'failed_at', cp.failed_at
          )
          order by cp.created_at_utc desc, cp.id desc
        ),
        '[]'::jsonb
      ) as items
    from (
      select
        co.id,
        co.channel,
        co.status,
        co.to_address,
        co.sent_at,
        co.delivered_at,
        co.read_at,
        co.failed_at,
        co.created_at_utc
      from public.comms_outbox as co
      where co.mailshot_run_id = p_mailshot_run_id
      order by co.created_at_utc desc, co.id desc
      limit 25
    ) as cp
  )
  select
    jsonb_build_object(
      'ok', true,
      'item',
      jsonb_build_object(
        'id', rr.id::text,
        'mailshot_run_id', rr.id::text,
        'context_kind', rr.context_kind,
        'output_type', rr.output_type,
        'document_template_id', case when rr.document_template_id is null then null else rr.document_template_id::text end,
        'template_filename', rr.template_filename,
        'created_by', case when rr.created_by is null then null else rr.created_by::text end,
        'created_at_utc', rr.created_at_utc,
        'delivery_timing_json', rr.delivery_timing_json,
        'selection_json', rr.selection_json,
        'result_json', rr.result_json,
        'counts',
        jsonb_build_object(
          'queued', mc.pending_total + cc.pending_total,
          'skipped', ic.initial_skipped,
          'failed', ic.initial_failed + mc.failed_total + cc.failed_total,
          'success', mc.sent_total + mc.delivered_total + mc.read_total + cc.sent_total + cc.delivered_total + cc.read_total,
          'blocking', mc.blocking_total + cc.blocking_total,
          'total_rows', mc.total_rows + cc.total_rows,
          'cancelable', mc.cancelable_total + cc.cancelable_total,
          'sent', mc.sent_total + cc.sent_total,
          'delivered', mc.delivered_total + cc.delivered_total,
          'read', mc.read_total + cc.read_total
        ),
        'initial_counts',
        jsonb_build_object(
          'queued', ic.initial_queued,
          'skipped', ic.initial_skipped,
          'failed', ic.initial_failed
        ),
        'live_counts',
        jsonb_build_object(
          'total_rows', mc.total_rows + cc.total_rows,
          'mail_rows', mc.total_rows,
          'comms_rows', cc.total_rows,
          'pending_total', mc.pending_total + cc.pending_total,
          'failed_total', mc.failed_total + cc.failed_total,
          'sent_total', mc.sent_total + cc.sent_total,
          'delivered_total', mc.delivered_total + cc.delivered_total,
          'read_total', mc.read_total + cc.read_total,
          'success_total', mc.sent_total + mc.delivered_total + mc.read_total + cc.sent_total + cc.delivered_total + cc.read_total,
          'blocking_total', mc.blocking_total + cc.blocking_total,
          'cancelable_total', mc.cancelable_total + cc.cancelable_total,
          'blocking_mail_sent', mc.sent_total,
          'blocking_mail_delivered', mc.delivered_total,
          'blocking_mail_read', mc.read_total,
          'blocking_comms_sent', cc.sent_total,
          'blocking_comms_delivered', cc.delivered_total,
          'blocking_comms_read', cc.read_total
        ),
        'can_cancel_pending', ((mc.cancelable_total + cc.cancelable_total) > 0) or ((mc.blocking_total + cc.blocking_total) = 0),
        'can_delete_if_unsent', ((mc.blocking_total + cc.blocking_total) = 0),
        'child_preview',
        jsonb_build_object(
          'mail_items', mp.items,
          'comms_items', cp.items
        )
      )
    )
  into v_payload
  from run_row as rr
  left join initial_counts as ic
    on ic.id = rr.id
  cross join mail_counts as mc
  cross join comms_counts as cc
  cross join mail_preview as mp
  cross join comms_preview as cp;

  if v_payload is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'mailshot_run_not_found'
    );
  end if;

  return v_payload;
end;
$function$;

-- mailshot_runs_list(integer,integer,text,text)
CREATE OR REPLACE FUNCTION public.mailshot_runs_list(p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_order_by text DEFAULT 'created_at_utc'::text, p_order_dir text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(1, least(coalesce(p_page_size, 25), 100));
  v_offset integer := 0;
  v_order_by text := 'created_at_utc';
  v_order_dir text := 'desc';
  v_total_count integer := 0;
  v_items jsonb := '[]'::jsonb;
  v_item_count integer := 0;
begin
  v_offset := (v_page - 1) * v_page_size;

  v_order_by :=
    case lower(coalesce(p_order_by, ''))
      when 'created_at_utc' then 'created_at_utc'
      when 'output_type' then 'output_type'
      when 'context_kind' then 'context_kind'
      else 'created_at_utc'
    end;

  v_order_dir :=
    case lower(coalesce(p_order_dir, ''))
      when 'asc' then 'asc'
      else 'desc'
    end;

  select count(*)::integer
    into v_total_count
  from public.mailshot_runs as mr_count;

  with ordered_runs as (
    select
      mr.id,
      mr.context_kind,
      mr.output_type,
      mr.document_template_id,
      mr.created_by,
      mr.created_at_utc,
      case
        when jsonb_typeof(mr.result_json) = 'object' then mr.result_json
        else '{}'::jsonb
      end as result_json_obj,
      case
        when jsonb_typeof(mr.delivery_timing_json) = 'object' then mr.delivery_timing_json
        else '{}'::jsonb
      end as delivery_timing_json_obj,
      dt.filename as template_filename,
      coalesce(mail_counts.total_rows, 0) as mail_rows,
      coalesce(mail_counts.pending_total, 0) as mail_pending_total,
      coalesce(mail_counts.failed_total, 0) as mail_failed_total,
      coalesce(mail_counts.sent_total, 0) as mail_sent_total,
      coalesce(mail_counts.delivered_total, 0) as mail_delivered_total,
      coalesce(mail_counts.read_total, 0) as mail_read_total,
      coalesce(mail_counts.blocking_total, 0) as mail_blocking_total,
      coalesce(mail_counts.cancelable_total, 0) as mail_cancelable_total,
      coalesce(comms_counts.total_rows, 0) as comms_rows,
      coalesce(comms_counts.pending_total, 0) as comms_pending_total,
      coalesce(comms_counts.failed_total, 0) as comms_failed_total,
      coalesce(comms_counts.sent_total, 0) as comms_sent_total,
      coalesce(comms_counts.delivered_total, 0) as comms_delivered_total,
      coalesce(comms_counts.read_total, 0) as comms_read_total,
      coalesce(comms_counts.blocking_total, 0) as comms_blocking_total,
      coalesce(comms_counts.cancelable_total, 0) as comms_cancelable_total,
      row_number() over (
        order by
          case
            when v_order_by = 'created_at_utc' and v_order_dir = 'asc' then mr.created_at_utc
            else null
          end asc nulls last,
          case
            when v_order_by = 'created_at_utc' and v_order_dir = 'desc' then mr.created_at_utc
            else null
          end desc nulls last,
          case
            when v_order_by = 'output_type' and v_order_dir = 'asc' then mr.output_type
            else null
          end asc nulls last,
          case
            when v_order_by = 'output_type' and v_order_dir = 'desc' then mr.output_type
            else null
          end desc nulls last,
          case
            when v_order_by = 'context_kind' and v_order_dir = 'asc' then mr.context_kind
            else null
          end asc nulls last,
          case
            when v_order_by = 'context_kind' and v_order_dir = 'desc' then mr.context_kind
            else null
          end desc nulls last,
          mr.created_at_utc desc,
          mr.id desc
      ) as sort_idx
    from public.mailshot_runs as mr
    left join public.document_templates as dt
      on dt.id = mr.document_template_id
    left join lateral (
      select
        count(*)::integer as total_rows,
        count(*) filter (
          where mo.read_at is null
            and mo.delivered_at is null
            and mo.sent_at is null
            and mo.failed_at is null
        )::integer as pending_total,
        count(*) filter (
          where mo.failed_at is not null
        )::integer as failed_total,
        count(*) filter (
          where mo.sent_at is not null
            and mo.delivered_at is null
            and mo.read_at is null
        )::integer as sent_total,
        count(*) filter (
          where mo.delivered_at is not null
            and mo.read_at is null
        )::integer as delivered_total,
        count(*) filter (
          where mo.read_at is not null
        )::integer as read_total,
        count(*) filter (
          where mo.read_at is not null
             or mo.delivered_at is not null
             or mo.sent_at is not null
        )::integer as blocking_total,
        count(*) filter (
          where mo.read_at is null
            and mo.delivered_at is null
            and mo.sent_at is null
        )::integer as cancelable_total
      from public.mail_outbox as mo
      where mo.mailshot_run_id = mr.id
    ) as mail_counts
      on true
    left join lateral (
      select
        count(*)::integer as total_rows,
        count(*) filter (
          where co.read_at is null
            and co.delivered_at is null
            and co.sent_at is null
            and co.failed_at is null
        )::integer as pending_total,
        count(*) filter (
          where co.failed_at is not null
        )::integer as failed_total,
        count(*) filter (
          where co.sent_at is not null
            and co.delivered_at is null
            and co.read_at is null
        )::integer as sent_total,
        count(*) filter (
          where co.delivered_at is not null
            and co.read_at is null
        )::integer as delivered_total,
        count(*) filter (
          where co.read_at is not null
        )::integer as read_total,
        count(*) filter (
          where co.read_at is not null
             or co.delivered_at is not null
             or co.sent_at is not null
        )::integer as blocking_total,
        count(*) filter (
          where co.read_at is null
            and co.delivered_at is null
            and co.sent_at is null
        )::integer as cancelable_total
      from public.comms_outbox as co
      where co.mailshot_run_id = mr.id
    ) as comms_counts
      on true
  ),
  paged_runs as (
    select
      orun.id,
      orun.context_kind,
      orun.output_type,
      orun.document_template_id,
      orun.created_by,
      orun.created_at_utc,
      orun.result_json_obj,
      orun.delivery_timing_json_obj,
      orun.template_filename,
      orun.mail_rows,
      orun.mail_pending_total,
      orun.mail_failed_total,
      orun.mail_sent_total,
      orun.mail_delivered_total,
      orun.mail_read_total,
      orun.mail_blocking_total,
      orun.mail_cancelable_total,
      orun.comms_rows,
      orun.comms_pending_total,
      orun.comms_failed_total,
      orun.comms_sent_total,
      orun.comms_delivered_total,
      orun.comms_read_total,
      orun.comms_blocking_total,
      orun.comms_cancelable_total,
      case
        when coalesce(orun.result_json_obj ->> 'queued', '') ~ '^[0-9]+$'
          then greatest((orun.result_json_obj ->> 'queued')::integer, 0)
        else 0
      end as initial_queued,
      case
        when coalesce(orun.result_json_obj ->> 'skipped', '') ~ '^[0-9]+$'
          then greatest((orun.result_json_obj ->> 'skipped')::integer, 0)
        else 0
      end as initial_skipped,
      case
        when coalesce(orun.result_json_obj ->> 'failed', '') ~ '^[0-9]+$'
          then greatest((orun.result_json_obj ->> 'failed')::integer, 0)
        else 0
      end as initial_failed,
      (orun.mail_rows + orun.comms_rows) as total_rows,
      (orun.mail_pending_total + orun.comms_pending_total) as pending_total,
      (orun.mail_failed_total + orun.comms_failed_total) as live_failed_total,
      (orun.mail_sent_total + orun.comms_sent_total) as sent_total,
      (orun.mail_delivered_total + orun.comms_delivered_total) as delivered_total,
      (orun.mail_read_total + orun.comms_read_total) as read_total,
      (
        orun.mail_sent_total
        + orun.mail_delivered_total
        + orun.mail_read_total
        + orun.comms_sent_total
        + orun.comms_delivered_total
        + orun.comms_read_total
      ) as success_total,
      (orun.mail_blocking_total + orun.comms_blocking_total) as blocking_total,
      (orun.mail_cancelable_total + orun.comms_cancelable_total) as cancelable_total,
      orun.sort_idx
    from ordered_runs as orun
    where orun.sort_idx > v_offset
      and orun.sort_idx <= (v_offset + v_page_size)
    order by orun.sort_idx
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', pr.id::text,
          'mailshot_run_id', pr.id::text,
          'context_kind', pr.context_kind,
          'output_type', pr.output_type,
          'document_template_id', case when pr.document_template_id is null then null else pr.document_template_id::text end,
          'template_filename', pr.template_filename,
          'created_by', case when pr.created_by is null then null else pr.created_by::text end,
          'created_at_utc', pr.created_at_utc,
          'delivery_timing_json', pr.delivery_timing_json_obj,
          'counts', jsonb_build_object(
            'queued', pr.pending_total,
            'skipped', pr.initial_skipped,
            'failed', (pr.initial_failed + pr.live_failed_total),
            'success', pr.success_total,
            'blocking', pr.blocking_total,
            'total_rows', pr.total_rows,
            'cancelable', pr.cancelable_total,
            'sent', pr.sent_total,
            'delivered', pr.delivered_total,
            'read', pr.read_total
          ),
          'initial_counts', jsonb_build_object(
            'queued', pr.initial_queued,
            'skipped', pr.initial_skipped,
            'failed', pr.initial_failed
          ),
          'live_counts', jsonb_build_object(
            'total_rows', pr.total_rows,
            'mail_rows', pr.mail_rows,
            'comms_rows', pr.comms_rows,
            'pending_total', pr.pending_total,
            'failed_total', pr.live_failed_total,
            'sent_total', pr.sent_total,
            'delivered_total', pr.delivered_total,
            'read_total', pr.read_total,
            'success_total', pr.success_total,
            'blocking_total', pr.blocking_total,
            'cancelable_total', pr.cancelable_total
          ),
          'can_cancel_pending', ((pr.cancelable_total > 0) or (pr.blocking_total = 0)),
          'can_delete_if_unsent', (pr.blocking_total = 0),
          'result_json', pr.result_json_obj
        )
        order by pr.sort_idx
      ),
      '[]'::jsonb
    ),
    count(*)::integer
    into v_items, v_item_count
  from paged_runs as pr;

  return jsonb_build_object(
    'ok', true,
    'items', v_items,
    'page', v_page,
    'page_size', v_page_size,
    'total_count', v_total_count,
    'has_more', ((v_offset + v_item_count) < v_total_count),
    'order_by', v_order_by,
    'order_dir', v_order_dir
  );
end;
$function$;

-- manual_timesheet_queue_attach_process_atomic(uuid,uuid,uuid,text,text,uuid,jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.manual_timesheet_queue_attach_process_atomic(p_queue_id uuid, p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_storage_key text, p_kind text DEFAULT 'TIMESHEET'::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_source_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_queue public.manual_timesheet_queue%rowtype;
  v_ts public.timesheets%rowtype;
  v_kind text:=upper(btrim(coalesce(p_kind,'TIMESHEET')));
  v_expected_key text:=nullif(regexp_replace(coalesce(btrim(p_expected_storage_key),''),'^/+','','g'),'');
  v_key text; v_evidence_id uuid; v_asset_id uuid; v_operation_id uuid;
  v_document_operation_id uuid; v_document_version_id uuid;
  v_document_revision bigint; v_document_status text; v_document_r2_key text;
  v_document_idempotency text;
  v_display_name text; v_rotation_raw integer; v_rotation integer;
  v_revision text; v_evidence_inserted boolean:=false; v_asset_reused boolean:=false;
  v_asset_state text; v_asset_ready boolean:=false; v_normalised_r2_key text;
  v_asset_error jsonb; v_terminal_asset boolean:=false; v_actor_role text;
  v_state text; v_msg text; v_detail text;
begin
  perform set_config('lock_timeout','2500ms',true);

  if coalesce(auth.role(),'')<>'service_role' then
    if auth.uid() is null or p_actor_user_id is distinct from auth.uid() then
      raise exception using errcode='42501',message='AUTHENTICATED_ACTOR_REQUIRED';
    end if;
  end if;
  if p_actor_user_id is null or not exists(
    select 1 from public.tms_users u where u.id=p_actor_user_id and u.is_active
  ) then
    raise exception using errcode='42501',message='ACTIVE_ACTOR_REQUIRED';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_actor_role
  from public.tms_users u where u.id=p_actor_user_id and u.is_active;
  if v_actor_role<>'admin' then
    raise exception using errcode='42501',message='TIMESHEET_ADMIN_REQUIRED';
  end if;

  if p_queue_id is null then return jsonb_build_object('ok',false,'error_code','QUEUE_ID_REQUIRED'); end if;
  if p_timesheet_id is null then return jsonb_build_object('ok',false,'error_code','TIMESHEET_ID_REQUIRED'); end if;
  if p_expected_timesheet_id is null then return jsonb_build_object('ok',false,'error_code','EXPECTED_TIMESHEET_ID_REQUIRED'); end if;
  if v_expected_key is null then return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_STORAGE_REQUIRED'); end if;

  if v_kind in('','TS') then v_kind:='TIMESHEET';
  elsif v_kind in('EXPENSE','EXPENSES') then v_kind:='TRAVEL';
  elsif v_kind in('MILES','MILE') then v_kind:='MILEAGE';
  elsif v_kind='ACCOM' then v_kind:='ACCOMMODATION'; end if;
  if v_kind not in('TIMESHEET','MILEAGE','TRAVEL','ACCOMMODATION','OTHER') then
    return jsonb_build_object('ok',false,'error_code','INVALID_EVIDENCE_KIND','kind',p_kind);
  end if;

  select * into v_ts
  from public.timesheets
  where timesheet_id=p_timesheet_id and is_current
  for update;
  if not found then return jsonb_build_object('ok',false,'error_code','TIMESHEET_NOT_FOUND'); end if;
  if v_ts.timesheet_id is distinct from p_expected_timesheet_id then
    return jsonb_build_object('ok',false,'error_code','TIMESHEET_MOVED',
      'current_timesheet_id',v_ts.timesheet_id,'expected_timesheet_id',p_expected_timesheet_id);
  end if;

  if exists(
    select 1 from public.timesheets_financials tf
    where tf.timesheet_id=v_ts.timesheet_id and tf.is_current
      and(
        tf.locked_by_invoice_id is not null
        or exists(
          select 1 from jsonb_array_elements(
            case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
              then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) seg(value)
          where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is not null))
  ) then
    return jsonb_build_object(
      'ok',false,'error_code','TIMESHEET_DOCUMENT_LOCKED');
  end if;

  if lower(coalesce(public._ctms_import_correction_classify_v1(v_ts.timesheet_id)
      ->>'is_import_authoritative_correction','false')) in('true','t','1','yes') then
    return jsonb_build_object(
      'ok',false,'error_code','IMPORT_AUTHORITATIVE_EVIDENCE_READ_ONLY');
  end if;

  if v_kind='TIMESHEET' and exists(
    select 1 from public.v_timesheets_summary_base s
    where s.timesheet_id=v_ts.timesheet_id
      and(coalesce(s.client_no_timesheet_required,false)
        or coalesce(s.client_is_nhsp,false))
  ) then
    return jsonb_build_object(
      'ok',false,'error_code','TIMESHEET_EVIDENCE_NOT_PERMITTED');
  end if;

  -- CloudTMS staff access is represented by an active tms_users record.  The
  -- queue item and current-timesheet locks below are the entity-scoped authority:
  -- callers cannot attach an object to a different or superseded timesheet.
  select * into v_queue
  from public.manual_timesheet_queue
  where id=p_queue_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_NOT_AVAILABLE'); end if;
  v_key:=nullif(regexp_replace(coalesce(btrim(v_queue.r2_key),''),'^/+','','g'),'');
  if v_key is null or v_key is distinct from v_expected_key then
    return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_STORAGE_MISMATCH',
      'expected_storage_key',v_expected_key,'storage_key',v_key);
  end if;
  if upper(coalesce(v_queue.status,''))<>'QUEUED' or v_queue.timesheet_id is not null then
    return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_NOT_AVAILABLE',
      'status',v_queue.status,'timesheet_id',v_queue.timesheet_id);
  end if;

  if v_kind='TIMESHEET' and exists(
    select 1 from public.timesheet_evidence te
    where te.timesheet_id=v_ts.timesheet_id and upper(te.kind)='TIMESHEET'
      and regexp_replace(te.storage_key,'^/+','','g') is distinct from v_key
  ) then
    return jsonb_build_object('ok',false,'error_code','TIMESHEET_EVIDENCE_ALREADY_EXISTS');
  end if;

  select te.id into v_evidence_id
  from public.timesheet_evidence te
  where te.timesheet_id=v_ts.timesheet_id and upper(te.kind)=v_kind
    and regexp_replace(te.storage_key,'^/+','','g')=v_key
  order by te.created_at desc,te.id desc
  limit 1 for update;

  v_display_name:=coalesce(nullif(btrim(v_queue.original_filename),''),
    reverse(split_part(reverse(v_key),'/',1)));
  v_rotation_raw:=((coalesce(v_queue.last_rotation_deg,0)%360)+360)%360;
  v_rotation:=case when v_rotation_raw>=315 or v_rotation_raw<45 then 0
    when v_rotation_raw<135 then 90 when v_rotation_raw<225 then 180 else 270 end;
  v_revision:=encode(digest(concat_ws('|',v_ts.timesheet_id::text,v_kind,v_key,
    coalesce(v_queue.content_hash,''),v_rotation::text),'sha256'),'hex');

  if v_evidence_id is null then
    insert into public.timesheet_evidence(
      timesheet_id,kind,display_name,storage_key,created_at,created_by,
      source_revision,processing_state
    ) values(
      v_ts.timesheet_id,v_kind,v_display_name,v_key,v_now,p_actor_user_id,
      v_revision,'DISCOVERED'
    ) returning id into v_evidence_id;
    v_evidence_inserted:=true;
  else
    update public.timesheet_evidence
    set source_revision=v_revision
    where id=v_evidence_id and source_revision is distinct from v_revision;
  end if;

  select a.id,a.status,a.operation_id,a.normalised_r2_key,a.error_json
    into v_asset_id,v_asset_state,v_operation_id,v_normalised_r2_key,v_asset_error
  from public.invoice_document_assets a
  where a.source_kind='TIMESHEET_EVIDENCE' and a.source_id=v_evidence_id
    and a.source_revision=v_revision and a.original_r2_key=v_key
  for update;

  if found then
    v_asset_reused:=true;
  else
    insert into public.invoice_document_assets(
      source_kind,source_id,source_revision,original_r2_key,original_filename,
      declared_media_type,original_sha256,orientation_degrees,status,
      created_at_utc,updated_at_utc
    ) values(
      'TIMESHEET_EVIDENCE',v_evidence_id,v_revision,v_key,v_display_name,
      v_queue.mime_type,v_queue.content_hash,v_rotation,'DISCOVERED',v_now,v_now
    ) returning id,status into v_asset_id,v_asset_state;
  end if;
  v_asset_ready:=v_asset_state='READY';
  v_terminal_asset:=v_asset_state in(
    'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED');

  if not v_asset_ready and not v_terminal_asset then
    select o.id into v_operation_id
    from public.invoice_operations o
    where o.operation_type='PREPARE_ASSET'
      and o.entity_type='DOCUMENT_ASSET' and o.entity_id=v_asset_id
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
    order by o.created_at_utc desc limit 1 for update;

    if v_operation_id is null
       and v_asset_reused
       and v_asset_state in('INSPECTING','NORMALISING') then
      raise exception using errcode='55000',
        message='ASSET_WORKFLOW_INCONSISTENT';
    end if;

    if v_operation_id is null then
      insert into public.invoice_operations(
        operation_type,entity_type,entity_id,actor_user_id,idempotency_key,status,phase,
        priority,source_revision,input_json,config_json,progress_json,total_units,chunk_count,
        control_version,change_seq,created_at_utc,updated_at_utc
      ) values(
        'PREPARE_ASSET','DOCUMENT_ASSET',v_asset_id,p_actor_user_id,
        encode(digest('PREPARE_ASSET|'||v_asset_id||'|'||v_revision,'sha256'),'hex'),
        'QUEUED','INSPECT',550,v_revision,
        jsonb_build_object('asset_id',v_asset_id,'source_kind','TIMESHEET_EVIDENCE',
          'source_id',v_evidence_id,'source_revision',v_revision,
          'original_r2_key',v_key,'original_filename',v_display_name,
          'declared_media_type',v_queue.mime_type,'rotation_degrees',v_rotation),
        jsonb_build_object('processor_policy',private._invoice_processor_limits()),
        jsonb_build_object('status_message','Asset queued for inspection'),
        1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
      ) returning id into v_operation_id;
    else
      update public.invoice_operations set priority=greatest(priority,550),
        change_seq=nextval('public.invoice_operation_change_seq'),updated_at_utc=v_now
      where id=v_operation_id;
    end if;

    update public.invoice_document_assets
    set operation_id=v_operation_id,updated_at_utc=v_now
    where id=v_asset_id and status<>'READY';

    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_asset_id,status,priority,run_after_utc,payload_json,
      operation_control_version,created_at_utc,updated_at_utc
    )
    select v_operation_id,'ASSET_INSPECT','INSPECT',
      encode(digest(concat_ws('|','ASSET_INSPECT',v_asset_id::text,v_revision,
        private._invoice_processor_limits()->>'policy_version'),'sha256'),'hex'),
      0,'DOCUMENT_ASSET',v_asset_id,
      v_asset_id,'QUEUED',550,v_now,
      jsonb_build_object('source_kind','TIMESHEET_EVIDENCE',
        'source_id',v_evidence_id,'source_revision',v_revision,'original_r2_key',v_key),
      o.control_version,v_now,v_now
    from public.invoice_operations o
    where o.id=v_operation_id
      and not exists(
        select 1 from public.invoice_operation_chunks ac
        where ac.document_asset_id=v_asset_id and ac.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and ac.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      )
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing;
  else
    v_operation_id:=null;
  end if;

  update public.timesheet_evidence
  set document_asset_id=v_asset_id,processing_state=v_asset_state,
    processing_error_json=case when v_terminal_asset then v_asset_error else null end
  where id=v_evidence_id;

  if v_kind='TIMESHEET' then
    update public.timesheets
    set manual_document_asset_id=v_asset_id,
      manual_pdf_r2_key=null,
      manual_pdf_rotation_degrees=v_rotation,
      document_state=case when v_terminal_asset then 'FAILED' else 'QUEUED' end,
      last_document_error_json=case when v_terminal_asset then v_asset_error else null end,
      updated_at=v_now
    where timesheet_id=v_ts.timesheet_id and is_current
    returning document_revision into v_document_revision;
  else
    select t.document_revision into v_document_revision
    from public.timesheets t
    where t.timesheet_id=v_ts.timesheet_id and t.is_current;
  end if;

  if not v_terminal_asset then
      select v.id,v.operation_id,v.status,v.r2_key
        into v_document_version_id,v_document_operation_id,
          v_document_status,v_document_r2_key
      from public.invoice_document_versions v
      where v.entity_type='TIMESHEET' and v.entity_id=v_ts.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=v_document_revision::text
        and v.template_version='timesheet-professional-v1'
        and v.status in(
          'PLANNING','WAITING_FOR_INPUTS','RENDERING',
          'ASSEMBLING','VERIFYING','READY')
      order by(v.status='READY') desc,v.created_at_utc desc,v.id desc
      limit 1;

      if v_document_status='READY' then
        update public.timesheets t
        set current_document_version_id=v_document_version_id,
            manual_pdf_r2_key=v_document_r2_key,
            document_state='READY',
            active_document_operation_id=case
              when t.active_document_operation_id=v_document_operation_id
              then null else t.active_document_operation_id end,
            last_document_error_json=null,updated_at=v_now
        where t.timesheet_id=v_ts.timesheet_id and t.is_current
          and t.document_revision=v_document_revision;
      elsif v_document_version_id is null then
        v_document_idempotency:=encode(digest(concat_ws('|',
          'BUILD_DOCUMENT','TIMESHEET',v_ts.timesheet_id::text,'TIMESHEET',
          v_document_revision::text,'timesheet-professional-v1'),
          'sha256'),'hex');

        insert into public.invoice_operations(
          operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
          status,phase,priority,source_revision,template_version,input_json,
          config_json,progress_json,total_units,chunk_count,control_version,
          change_seq,created_at_utc,updated_at_utc
        ) values(
          'BUILD_DOCUMENT','TIMESHEET',v_ts.timesheet_id,p_actor_user_id,
          v_document_idempotency,'QUEUED','BUILD_MANIFEST',550,
          v_document_revision::text,'timesheet-professional-v1',
          jsonb_build_object(
            'entity_type','TIMESHEET','entity_id',v_ts.timesheet_id,
            'purpose','TIMESHEET','source_revision',v_document_revision,
            'template_version','timesheet-professional-v1'),
          jsonb_build_object('processor_policy',private._invoice_processor_limits()),
          jsonb_build_object('status_message','Timesheet document queued'),
          1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
        )
        on conflict do nothing
        returning id into v_document_operation_id;

        if v_document_operation_id is null then
          select o.id into v_document_operation_id
          from public.invoice_operations o
          where o.idempotency_key=v_document_idempotency
            and o.status in(
              'QUEUED','RUNNING','WAITING','RETRY_WAIT')
          order by o.created_at_utc desc,o.id desc
          limit 1;
        end if;

        insert into public.invoice_document_versions(
          entity_type,entity_id,purpose,operation_id,source_revision,
          template_version,status,snapshot_json,snapshot_hash,
          manifest_json,manifest_hash,created_at_utc
        ) values(
          'TIMESHEET',v_ts.timesheet_id,'TIMESHEET',
          v_document_operation_id,v_document_revision::text,
          'timesheet-professional-v1','PLANNING','{}'::jsonb,
          encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
          encode(digest('[]','sha256'),'hex'),v_now
        )
        on conflict(entity_type,entity_id,purpose,source_revision,template_version)
          where purpose in('DRAFT_PREVIEW','TIMESHEET')
            and status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY')
        do nothing
        returning id into v_document_version_id;

        if v_document_version_id is null then
          select v.id,v.operation_id into
            v_document_version_id,v_document_operation_id
          from public.invoice_document_versions v
          where v.entity_type='TIMESHEET' and v.entity_id=v_ts.timesheet_id
            and v.purpose='TIMESHEET'
            and v.source_revision=v_document_revision::text
            and v.template_version='timesheet-professional-v1'
            and v.status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY')
          order by(v.status='READY') desc,v.created_at_utc desc,v.id desc
          limit 1;
        end if;

        insert into public.invoice_operation_chunks(
          operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
          document_version_id,status,priority,run_after_utc,payload_json,
          operation_control_version,created_at_utc,updated_at_utc
        )
        select v_document_operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
          encode(digest(concat_ws('|','DOCUMENT_PLAN',v_document_version_id::text,
            v_document_revision::text,'timesheet-professional-v1','1'),
            'sha256'),'hex'),
          0,
          'TIMESHEET',v_ts.timesheet_id,v_document_version_id,'QUEUED',550,
          v_now,jsonb_build_object(
            'purpose','TIMESHEET','source_revision',v_document_revision,
            'template_version','timesheet-professional-v1'),
          o.control_version,v_now,v_now
        from public.invoice_operations o
        where o.id=v_document_operation_id
        on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
          do nothing;

        update public.timesheets t
        set current_document_version_id=v_document_version_id,
            active_document_operation_id=v_document_operation_id,
            document_state='QUEUED',last_document_error_json=null,
            updated_at=v_now
        where t.timesheet_id=v_ts.timesheet_id and t.is_current
          and t.document_revision=v_document_revision;
      else
        update public.timesheets t
        set current_document_version_id=v_document_version_id,
            active_document_operation_id=v_document_operation_id,
            document_state=case when v_document_status='PLANNING'
              then 'QUEUED' else 'PREPARING' end,
            last_document_error_json=null,updated_at=v_now
        where t.timesheet_id=v_ts.timesheet_id and t.is_current
          and t.document_revision=v_document_revision;
      end if;
  end if;

  update public.manual_timesheet_queue
  set status='ATTACHED',timesheet_id=v_ts.timesheet_id,r2_key=v_key,
    meta_json=coalesce(meta_json,'{}')||jsonb_build_object(
      'attached_kind',v_kind,'attached_to_timesheet_id',v_ts.timesheet_id,
      'attached_at_utc',v_now,'attached_storage_key',v_key,
      'asset_id',v_asset_id,'asset_operation_id',v_operation_id,
      'document_operation_id',v_document_operation_id,
      'source',p_source_json->>'source')
  where id=p_queue_id and status='QUEUED' and timesheet_id is null
    and regexp_replace(r2_key,'^/+','','g')=v_key;
  if not found then raise exception 'QUEUE_ITEM_NOT_AVAILABLE'; end if;

  return jsonb_build_object(
    'ok',true,'success',true,'attached',true,'queue_id',p_queue_id,
    'evidence_id',v_evidence_id,'timesheet_id',v_ts.timesheet_id,'kind',v_kind,
    'storage_key',v_key,'asset_id',v_asset_id,
    'operation_id',v_operation_id,'asset_operation_id',v_operation_id,
    'document_operation_id',v_document_operation_id,
    'document_version_id',v_document_version_id,
    'asset_state',v_asset_state,'processing_state',v_asset_state,
    'asset_reused',v_asset_reused,'asset_ready',v_asset_ready,
    'terminal_asset',v_terminal_asset,
    'terminal_error',case when v_terminal_asset then v_asset_error end,
    'retry_required',v_terminal_asset,
    'backend_should_nudge',
      v_operation_id is not null or v_document_operation_id is not null,
    'timesheet_document_revision',(select document_revision from public.timesheets
      where timesheet_id=v_ts.timesheet_id and is_current),
    'queue_item_consumed',true,
    'changed_domains',jsonb_build_array(
      'timesheet_evidence','manual_timesheet_queue','invoice_document_assets',
      case when v_kind='TIMESHEET' then 'timesheets' end,
      case when v_operation_id is not null then 'invoice_operations' end)
  );
exception when others then
  get stacked diagnostics v_state=returned_sqlstate,v_msg=message_text,v_detail=pg_exception_detail;
  if v_state in('55P03','57014') then
    return jsonb_build_object('ok',false,'success',false,'error_code','LOCK_TIMEOUT',
      'sqlstate',v_state,'detail',v_detail);
  end if;
  return jsonb_build_object('ok',false,'success',false,
    'error_code',coalesce(nullif(v_msg,''),v_state),
    'message',coalesce(nullif(v_msg,''),'Attach failed'),
    'sqlstate',v_state,'detail',v_detail,'queue_id',p_queue_id,'timesheet_id',p_timesheet_id);
end;
$function$;

-- nhsp_apply_import_phase1(uuid,text[],text[],text[])
CREATE OR REPLACE FUNCTION public.nhsp_apply_import_phase1(p_import_id uuid, p_selected_group_ids text[] DEFAULT NULL::text[], p_skip_external_row_keys text[] DEFAULT NULL::text[], p_force_overwrite_external_row_keys text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_created           int := 0;
  v_updated           int := 0;
  v_mapped_candidates int := 0;
  v_mapped_clients    int := 0;

  -- selection normalisation + mode
  v_force_mode boolean := false;
  v_skip_keys text[] := array[]::text[];
  v_force_keys text[] := array[]::text[];

  -- pre-write diagnostics
  v_raw_rows_count int := 0;
  v_src_rows_count int := 0;
  v_resolved_rows_count int := 0;

  v_sample_skip_keys jsonb := '[]'::jsonb;
  v_sample_force_keys jsonb := '[]'::jsonb;
  v_sample_src_keys jsonb := '[]'::jsonb;
  v_sample_written jsonb := '[]'::jsonb;
begin
  ----------------------------------------------------------------
  -- 0) Sanity check the import exists and is NHSP
  ----------------------------------------------------------------
  perform 1
  from public.hr_imports hi
  where hi.id = p_import_id
    and hi.source_system = 'NHSP'::public.hr_source_enum;

  if not found then
    raise exception 'nhsp_apply_import_phase1: import % not found or not NHSP', p_import_id;
  end if;

  ----------------------------------------------------------------
  -- 0.5) Normalise key arrays (distinct, trimmed, non-empty)
  -- Selection rule:
  --  - If p_force_overwrite_external_row_keys IS PROVIDED (even empty) => "FORCE MODE":
  --      only keys in FORCE list are eligible; SKIP list is still enforced as an exclusion.
  --  - Else (force is NULL) => legacy "SKIP MODE":
  --      all rows except SKIP list are eligible.
  ----------------------------------------------------------------
  v_force_mode := (p_force_overwrite_external_row_keys is not null);

  select coalesce(array_agg(distinct btrim(k)),'{}'::text[])
  into v_skip_keys
  from unnest(coalesce(p_skip_external_row_keys, '{}'::text[])) as k
  where k is not null and btrim(k) <> '';

  select coalesce(array_agg(distinct btrim(k)),'{}'::text[])
  into v_force_keys
  from unnest(coalesce(p_force_overwrite_external_row_keys, '{}'::text[])) as k
  where k is not null and btrim(k) <> '';

  select coalesce(jsonb_agg(x.k), '[]'::jsonb)
  into v_sample_skip_keys
  from (
    select k as k
    from unnest(coalesce(v_skip_keys, array[]::text[])) as k
    order by k
    limit 20
  ) as x;

  select coalesce(jsonb_agg(x.k), '[]'::jsonb)
  into v_sample_force_keys
  from (
    select k as k
    from unnest(coalesce(v_force_keys, array[]::text[])) as k
    order by k
    limit 20
  ) as x;

  ----------------------------------------------------------------
  -- 1) Prepare / resolve all relevant hr_rows
  -- IMPORTANT: We only act on rows with a non-null external_row_key.
  -- This prevents accidental mass updates via "skip list" semantics.
  ----------------------------------------------------------------
  create temporary table tmp_phase1_raw on commit drop as
  select
    r.id                           as hr_row_id,
    r.external_row_key,
    r.date_local                   as work_date,
    r.staff_norm                   as staff_norm,
    coalesce(
      nullif((r.payload_json ->> 'staff_name'), ''),
      nullif((r.payload_json ->> 'worker_name'), ''),
      nullif(r.staff_raw, ''),
      nullif(r.staff_norm, '')
    )                              as staff_name,
    coalesce(
      nullif((r.payload_json ->> 'ward'), ''),
      nullif((r.payload_json ->> 'unit'), ''),
      nullif(r.unit_hint, ''),
      nullif(r.unit_raw, '')
    )                              as ward,
    coalesce(
      nullif((r.payload_json ->> 'trust'), ''),
      nullif((r.payload_json ->> 'hospital_or_trust'), ''),
      nullif(r.unit_raw, '')
    )                              as trust_raw,
    (r.payload_json ->> 'start_utc')::timestamptz as start_utc,
    (r.payload_json ->> 'end_utc')::timestamptz   as end_utc,
    coalesce((r.payload_json ->> 'break_mins')::int, 0) as break_mins,
    coalesce(
      nullif((r.payload_json ->> 'ref_num'), ''),
      nullif((r.payload_json ->> 'Reference'), ''),
      nullif(r.hr_request_id, '')
    )                              as ref_num,
    coalesce(
      nullif((r.payload_json ->> 'assignment_code'), ''),
      nullif((r.payload_json ->> 'assignment'), ''),
      nullif((r.payload_json ->> 'Request_Grade'), ''),
      nullif(r.assignment_grade_norm, '')
    )                              as assignment_code
  from public.hr_rows r
  where r.import_id = p_import_id
    and r.external_row_key is not null
    and r.date_local is not null
    and (r.payload_json ->> 'start_utc') is not null
    and (r.payload_json ->> 'end_utc')   is not null;

  select count(*)::int
  into v_raw_rows_count
  from tmp_phase1_raw tr;

  create temporary table tmp_phase1_src on commit drop as
  select tr.*
  from tmp_phase1_raw tr
  where
    -- Always enforce SKIP as an exclusion (if present)
    (
      array_length(v_skip_keys, 1) is null
      or tr.external_row_key <> all(v_skip_keys)
    )
    and
    (
      -- FORCE MODE: only keys in FORCE list (empty list => select none)
      (v_force_mode is true and array_length(v_force_keys, 1) is not null and tr.external_row_key = any(v_force_keys))
      or
      -- LEGACY SKIP MODE: include everything not skipped
      (v_force_mode is false)
    );

  select count(*)::int
  into v_src_rows_count
  from tmp_phase1_src ts;

  select coalesce(jsonb_agg(x.k), '[]'::jsonb)
  into v_sample_src_keys
  from (
    select ts.external_row_key as k
    from tmp_phase1_src ts
    order by ts.external_row_key
    limit 20
  ) as x;

  create temporary table tmp_phase1_resolved on commit drop as
  select
    src.*,
    n.staff_lc,
    n.staff_norm2,
    n.trust_lc,
    n.trust_norm,

    greatest(
      0,
      (extract(epoch from (src.end_utc - src.start_utc)) / 60)::int
      - src.break_mins
    ) as pay_minutes,

    coalesce(
      cand_alias.id,
      cand_map.candidate_id,
      cand_exact_unique.candidate_id
    ) as candidate_id,

    coalesce(
      cli_alias.client_id,
      cli_name.client_id
    ) as client_id
  from tmp_phase1_src src

  cross join lateral (
    select
      nullif(lower(trim(coalesce(src.staff_name,''))), '') as staff_lc,
      nullif(regexp_replace(lower(coalesce(src.staff_name,'')), '[^a-z0-9]+', '', 'g'), '') as staff_norm2,
      nullif(lower(trim(coalesce(src.trust_raw,''))), '') as trust_lc,
      nullif(regexp_replace(lower(coalesce(src.trust_raw,'')), '[^a-z0-9]+', '', 'g'), '') as trust_norm
  ) n

  left join lateral (
    select c.id
    from public.candidates c
    where c.nhsp_hr_name_aliases is not null
      and (
        (n.staff_lc    is not null and c.nhsp_hr_name_aliases @> to_jsonb(array[n.staff_lc]::text[]))
        or
        (n.staff_norm2 is not null and c.nhsp_hr_name_aliases @> to_jsonb(array[n.staff_norm2]::text[]))
      )
    limit 1
  ) cand_alias on true

  left join lateral (
    select hm.candidate_id
    from public.hr_name_mappings hm
    where hm.active = true
      and (
        (n.staff_lc    is not null and hm.hr_name_norm = n.staff_lc)
        or
        (n.staff_norm2 is not null and hm.hr_name_norm = n.staff_norm2)
      )
    order by hm.created_at desc
    limit 1
  ) cand_map on (cand_alias.id is null)

  left join lateral (
    with matches as (
      select c.id as candidate_id
      from public.candidates c
      where c.active = true
        and n.staff_norm2 is not null
        and (
          regexp_replace(lower(coalesce(c.first_name,'') || coalesce(c.last_name,'')), '[^a-z0-9]+', '', 'g') = n.staff_norm2
          or
          regexp_replace(lower(coalesce(c.last_name,'')  || coalesce(c.first_name,'')), '[^a-z0-9]+', '', 'g') = n.staff_norm2
        )
    )
    select
      case
        when count(*) = 1
          then (array_agg(candidate_id order by candidate_id::text))[1]
      end as candidate_id
    from matches
  ) cand_exact_unique on (cand_alias.id is null and cand_map.candidate_id is null)

  left join lateral (
    select ch.client_id
    from public.client_hospitals ch
    where ch.hospital_name_norm is not null
      and (
        (n.trust_lc   is not null and ch.hospital_name_norm @> to_jsonb(array[n.trust_lc]::text[]))
        or
        (n.trust_norm is not null and ch.hospital_name_norm @> to_jsonb(array[n.trust_norm]::text[]))
      )
    limit 1
  ) cli_alias on true

  left join lateral (
    with matches as (
      select cl.id as client_id
      from public.clients cl
      where n.trust_norm is not null
        and regexp_replace(lower(coalesce(cl.name,'')), '[^a-z0-9]+', '', 'g') = n.trust_norm
    )
    select
      case
        when count(*) = 1
          then (array_agg(client_id order by client_id::text))[1]
      end as client_id
    from matches
  ) cli_name on (cli_alias.client_id is null);

  select count(*)::int
  into v_resolved_rows_count
  from tmp_phase1_resolved rr;

  ----------------------------------------------------------------
  -- 2) Current TSFIN lock state (for safe overwrite logic)
  ----------------------------------------------------------------
  create temporary table tmp_phase1_fin_current on commit drop as
  select distinct on (tf.timesheet_id)
    tf.timesheet_id,
    tf.locked_by_invoice_id,
    tf.paid_at_utc
  from public.timesheets_financials tf
  where tf.is_current = true
  order by tf.timesheet_id, tf.created_at desc;

  ----------------------------------------------------------------
  -- 3) Apply inserts/updates and capture samples
  ----------------------------------------------------------------
  create temporary table tmp_phase1_written(
    op text not null,
    shift_id uuid not null,
    external_row_key text not null
  ) on commit drop;

  with ins as (
    insert into public.nhsp_shifts (
      external_row_key,
      latest_import_id,
      source_system,
      staff_name,
      staff_norm,
      ward,
      ward_norm,
      work_date,
      assignment_code,
      ref_num,
      start_utc,
      end_utc,
      break_mins,
      pay_minutes,
      invoice_status,
      created_at,
      updated_at,
      candidate_id,
      client_id
    )
    select
      rr.external_row_key,
      p_import_id,
      'NHSP'::public.hr_source_enum,
      nullif(rr.staff_name, ''),
      nullif(lower(rr.staff_name), ''),
      nullif(rr.ward, ''),
      nullif(lower(rr.ward), ''),
      rr.work_date,
      nullif(rr.assignment_code, ''),
      nullif(rr.ref_num, ''),
      rr.start_utc,
      rr.end_utc,
      coalesce(rr.break_mins, 0),
      greatest(0, rr.pay_minutes),
      'PENDING',
      now(),
      now(),
      rr.candidate_id,
      rr.client_id
    from tmp_phase1_resolved rr
    where rr.external_row_key is not null
      and not exists (
        select 1
        from public.nhsp_shifts s2
        where s2.external_row_key = rr.external_row_key
          and s2.source_system = 'NHSP'::public.hr_source_enum
      )
    returning
      public.nhsp_shifts.id as shift_id,
      public.nhsp_shifts.external_row_key as external_row_key,
      (public.nhsp_shifts.candidate_id is not null) as mapped_candidate,
      (public.nhsp_shifts.client_id    is not null) as mapped_client
  ),
  upd_src as (
    select
      s.id as shift_id,
      s.external_row_key,
      s.timesheet_id,
      s.candidate_id as old_candidate_id,
      s.client_id    as old_client_id,

      rr.work_date,
      rr.staff_name,
      rr.ward,
      rr.assignment_code,
      rr.ref_num,
      rr.start_utc,
      rr.end_utc,
      rr.break_mins,
      rr.pay_minutes,

      rr.candidate_id as new_candidate_id,
      rr.client_id    as new_client_id,

      fc.locked_by_invoice_id,
      fc.paid_at_utc,

      (
        s.timesheet_id is null
        or fc.timesheet_id is null
        or (fc.locked_by_invoice_id is null and fc.paid_at_utc is null)
      ) as safe_to_overwrite,

      (
        v_force_mode is true
        and array_length(v_force_keys, 1) is not null
        and s.external_row_key = any(v_force_keys)
      ) as force_overwrite,

      (
        (
          s.timesheet_id is null
          or fc.timesheet_id is null
          or (fc.locked_by_invoice_id is null and fc.paid_at_utc is null)
        )
        or (
          v_force_mode is true
          and array_length(v_force_keys, 1) is not null
          and s.external_row_key = any(v_force_keys)
        )
      ) as should_overwrite_time

    from public.nhsp_shifts s
    join tmp_phase1_resolved rr
      on rr.external_row_key = s.external_row_key
    left join tmp_phase1_fin_current fc
      on fc.timesheet_id = s.timesheet_id
    where s.source_system = 'NHSP'::public.hr_source_enum
  ),
  upd as (
    update public.nhsp_shifts s
    set
      latest_import_id = p_import_id,

      staff_name       = nullif(us.staff_name, ''),
      staff_norm       = nullif(lower(us.staff_name), ''),
      ward             = nullif(us.ward, ''),
      ward_norm        = nullif(lower(us.ward), ''),
      work_date        = us.work_date,
      assignment_code  = nullif(us.assignment_code, ''),
      ref_num          = nullif(us.ref_num, ''),
      source_system    = 'NHSP'::public.hr_source_enum,
      updated_at       = now(),

      cancelled_at_utc = null,
      cancelled_by_import_id = null,
      cancelled_reason = null,

      start_utc        = case when us.should_overwrite_time then us.start_utc else s.start_utc end,
      end_utc          = case when us.should_overwrite_time then us.end_utc   else s.end_utc   end,
      break_mins       = case when us.should_overwrite_time then coalesce(us.break_mins, 0) else s.break_mins end,
      pay_minutes      = case when us.should_overwrite_time then greatest(0, us.pay_minutes) else s.pay_minutes end,

      candidate_id     = case
                           when us.new_candidate_id is not null and us.safe_to_overwrite
                             then us.new_candidate_id
                           else s.candidate_id
                         end,
      client_id        = case
                           when us.new_client_id is not null and us.safe_to_overwrite
                             then us.new_client_id
                           else s.client_id
                         end
    from upd_src us
    where s.id = us.shift_id
    returning
      s.id as shift_id,
      s.external_row_key as external_row_key,
      (us.old_candidate_id is null and us.new_candidate_id is not null and us.safe_to_overwrite) as mapped_candidate,
      (us.old_client_id    is null and us.new_client_id    is not null and us.safe_to_overwrite) as mapped_client
  )
  insert into tmp_phase1_written(op, shift_id, external_row_key)
  select 'INSERT', i.shift_id, i.external_row_key from ins i
  union all
  select 'UPDATE', u.shift_id, u.external_row_key from upd u;

  select
    coalesce((select count(*) from tmp_phase1_written w where w.op = 'INSERT'), 0) as created,
    coalesce((select count(*) from tmp_phase1_written w where w.op = 'UPDATE'), 0) as updated,
    coalesce((select count(*) from (
      select 1
      from tmp_phase1_written w
      join public.nhsp_shifts ns on ns.id = w.shift_id
      where ns.candidate_id is not null
    ) as x), 0) as mapped_candidates,
    coalesce((select count(*) from (
      select 1
      from tmp_phase1_written w
      join public.nhsp_shifts ns on ns.id = w.shift_id
      where ns.client_id is not null
    ) as y), 0) as mapped_clients
  into
    v_created,
    v_updated,
    v_mapped_candidates,
    v_mapped_clients;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'op', w.op,
        'external_row_key', w.external_row_key,
        'shift_id', w.shift_id::text
      )
      order by w.op, w.external_row_key
    ),
    '[]'::jsonb
  )
  into v_sample_written
  from (
    select w.op, w.shift_id, w.external_row_key
    from tmp_phase1_written w
    order by w.op, w.external_row_key
    limit 20
  ) as w;

  ----------------------------------------------------------------
  -- 4) Debug audit (invoice_debug gated inside _imp_debug_audit)
  -- NOTE: nhsp_apply_import_phase1 has no actor param; use NULL actor.
  ----------------------------------------------------------------
  perform public._imp_debug_audit(
    null,
    'NHSP_PHASE1_DEBUG',
    jsonb_build_object(
      'import_id', p_import_id::text,
      'force_mode', v_force_mode,

      'input_skip_keys_count', coalesce(array_length(v_skip_keys, 1), 0),
      'input_force_keys_count', coalesce(array_length(v_force_keys, 1), 0),
      'sample_skip_keys', v_sample_skip_keys,
      'sample_force_keys', v_sample_force_keys,

      'raw_rows_count', v_raw_rows_count,
      'src_rows_count', v_src_rows_count,
      'resolved_rows_count', v_resolved_rows_count,
      'sample_src_external_row_keys', v_sample_src_keys,

      'shifts_created', v_created,
      'shifts_updated', v_updated,
      'mapped_candidates', v_mapped_candidates,
      'mapped_clients', v_mapped_clients,
      'sample_written', v_sample_written
    ),
    'hr_imports',
    p_import_id::text,
    null,
    null,
    null,
    null
  );

  return jsonb_build_object(
    'import_id',          p_import_id,
    'shifts_created',     v_created,
    'shifts_updated',     v_updated,
    'mapped_candidates',  v_mapped_candidates,
    'mapped_clients',     v_mapped_clients
  );

exception when others then
  begin
    perform public._imp_debug_audit(
      null,
      'NHSP_PHASE1_ERROR',
      jsonb_build_object(
        'import_id', p_import_id::text,
        'force_mode', v_force_mode,
        'input_skip_keys_count', coalesce(array_length(v_skip_keys, 1), 0),
        'input_force_keys_count', coalesce(array_length(v_force_keys, 1), 0),
        'raw_rows_count', v_raw_rows_count,
        'src_rows_count', v_src_rows_count,
        'resolved_rows_count', v_resolved_rows_count,
        'error', sqlerrm
      ),
      'hr_imports',
      p_import_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  raise;
end;
$function$;

-- nhsp_apply_import_phase1(uuid,text[])
CREATE OR REPLACE FUNCTION public.nhsp_apply_import_phase1(p_import_id uuid, p_selected_group_ids text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_created           int := 0;
  v_updated           int := 0;
  v_mapped_candidates int := 0;
  v_mapped_clients    int := 0;
begin
  ----------------------------------------------------------------
  -- 0) Sanity check the import exists and is NHSP
  ----------------------------------------------------------------
  perform 1
  from public.hr_imports hi
  where hi.id = p_import_id
    and hi.source_system = 'NHSP'::hr_source_enum;

  if not found then
    raise exception 'nhsp_apply_import_phase1: import % not found or not NHSP', p_import_id;
  end if;

  ----------------------------------------------------------------
  -- 1) Prepare / resolve all relevant hr_rows
  ----------------------------------------------------------------
  with raw as (
    select
      r.id                           as hr_row_id,
      r.external_row_key,
      r.date_local                   as work_date,
      r.staff_norm                   as staff_norm,
      coalesce(
        nullif((r.payload_json ->> 'staff_name'), ''),
        nullif((r.payload_json ->> 'worker_name'), ''),
        nullif(r.staff_raw, ''),
        nullif(r.staff_norm, '')
      )                              as staff_name,
      coalesce(
        nullif((r.payload_json ->> 'ward'), ''),
        nullif((r.payload_json ->> 'unit'), ''),
        nullif(r.unit_hint, ''),
        nullif(r.unit_raw, '')
      )                              as ward,
      coalesce(
        nullif((r.payload_json ->> 'trust'), ''),
        nullif((r.payload_json ->> 'hospital_or_trust'), ''),
        nullif(r.unit_raw, '')
      )                              as trust_raw,
      (r.payload_json ->> 'start_utc')::timestamptz as start_utc,
      (r.payload_json ->> 'end_utc')::timestamptz   as end_utc,
      coalesce((r.payload_json ->> 'break_mins')::int, 0) as break_mins,
      coalesce(
        nullif((r.payload_json ->> 'ref_num'), ''),
        nullif((r.payload_json ->> 'Reference'), ''),
        nullif(r.hr_request_id, '')
      )                              as ref_num,
      coalesce(
        nullif((r.payload_json ->> 'assignment_code'), ''),
        nullif((r.payload_json ->> 'assignment'), ''),          -- ✅ parser writes payload_json.assignment
        nullif((r.payload_json ->> 'Request_Grade'), ''),
        nullif(r.assignment_grade_norm, '')
      )                              as assignment_code,
      coalesce(
        nullif((r.payload_json ->> 'group_key'), ''),
        nullif((r.payload_json ->> 'group_id'), '')
      )                              as group_key
    from public.hr_rows r
    where r.import_id = p_import_id
      -- Only rows with usable dates/times
      and r.date_local is not null
      and (r.payload_json ->> 'start_utc') is not null
      and (r.payload_json ->> 'end_utc')   is not null
  ),
  src as (
    select *
    from raw
    where
      p_selected_group_ids is null
      or array_length(p_selected_group_ids, 1) is null
      or group_key = any(p_selected_group_ids)
  ),
  resolved as (
    select
      src.*,
      n.staff_lc,
      n.staff_norm2,
      n.trust_lc,
      n.trust_norm,

      -- Compute pay_minutes (for completeness; not heavily used)
      greatest(
        0,
        (extract(epoch from (src.end_utc - src.start_utc)) / 60)::int
        - src.break_mins
      ) as pay_minutes,

      -- Candidate mapping precedence:
      coalesce(
        cand_alias.id,
        cand_map.candidate_id,
        cand_exact_unique.candidate_id
      ) as candidate_id,

      -- Client mapping:
      coalesce(
        cli_alias.client_id,
        cli_name.client_id
      ) as client_id

    from src

    cross join lateral (
      select
        nullif(lower(trim(coalesce(src.staff_name,''))), '') as staff_lc,
        nullif(regexp_replace(lower(coalesce(src.staff_name,'')), '[^a-z0-9]+', '', 'g'), '') as staff_norm2,
        nullif(lower(trim(coalesce(src.trust_raw,''))), '') as trust_lc,
        nullif(regexp_replace(lower(coalesce(src.trust_raw,'')), '[^a-z0-9]+', '', 'g'), '') as trust_norm
    ) n

    left join lateral (
      select c.id
      from public.candidates c
      where c.nhsp_hr_name_aliases is not null
        and (
          (n.staff_lc    is not null and c.nhsp_hr_name_aliases @> to_jsonb(array[n.staff_lc]::text[]))
          or
          (n.staff_norm2 is not null and c.nhsp_hr_name_aliases @> to_jsonb(array[n.staff_norm2]::text[]))
        )
      limit 1
    ) cand_alias on true

    left join lateral (
      select hm.candidate_id
      from public.hr_name_mappings hm
      where hm.active = true
        and (
          (n.staff_lc    is not null and hm.hr_name_norm = n.staff_lc)
          or
          (n.staff_norm2 is not null and hm.hr_name_norm = n.staff_norm2)
        )
      order by hm.created_at desc
      limit 1
    ) cand_map on (cand_alias.id is null)

    left join lateral (
      with matches as (
        select c.id as candidate_id
        from public.candidates c
        where c.active = true
          and n.staff_norm2 is not null
          and (
            regexp_replace(lower(coalesce(c.first_name,'') || coalesce(c.last_name,'')), '[^a-z0-9]+', '', 'g') = n.staff_norm2
            or
            regexp_replace(lower(coalesce(c.last_name,'')  || coalesce(c.first_name,'')), '[^a-z0-9]+', '', 'g') = n.staff_norm2
          )
      )
      select
        case
          when count(*) = 1
            then (array_agg(candidate_id order by candidate_id::text))[1]
        end as candidate_id
      from matches
    ) cand_exact_unique on (cand_alias.id is null and cand_map.candidate_id is null)

    left join lateral (
      select ch.client_id
      from public.client_hospitals ch
      where ch.hospital_name_norm is not null
        and (
          (n.trust_lc   is not null and ch.hospital_name_norm @> to_jsonb(array[n.trust_lc]::text[]))
          or
          (n.trust_norm is not null and ch.hospital_name_norm @> to_jsonb(array[n.trust_norm]::text[]))
        )
      limit 1
    ) cli_alias on true

    left join lateral (
      with matches as (
        select cl.id as client_id
        from public.clients cl
        where n.trust_norm is not null
          and regexp_replace(lower(coalesce(cl.name,'')), '[^a-z0-9]+', '', 'g') = n.trust_norm
      )
      select
        case
          when count(*) = 1
            then (array_agg(client_id order by client_id::text))[1]
        end as client_id
      from matches
    ) cli_name on (cli_alias.client_id is null)
  ),

  ----------------------------------------------------------------
  -- Current TSFIN state per timesheet (no reference to nhsp_shifts alias)
  ----------------------------------------------------------------
  fin_current as (
    select distinct on (tf.timesheet_id)
      tf.timesheet_id,
      tf.locked_by_invoice_id,
      tf.paid_at_utc
    from public.timesheets_financials tf
    where tf.is_current = true
    order by tf.timesheet_id, tf.created_at desc
  ),

  ins as (
    insert into public.nhsp_shifts (
      external_row_key,
      latest_import_id,
      source_system,
      staff_name,
      staff_norm,
      ward,
      ward_norm,
      work_date,
      assignment_code,
      ref_num,
      start_utc,
      end_utc,
      break_mins,
      pay_minutes,
      invoice_status,
      created_at,
      updated_at,
      candidate_id,
      client_id
    )
    select
      r.external_row_key,
      p_import_id,
      'NHSP'::hr_source_enum,
      nullif(r.staff_name, ''),
      nullif(lower(r.staff_name), ''),    -- keep existing stored format
      nullif(r.ward, ''),
      nullif(lower(r.ward), ''),          -- keep existing stored format
      r.work_date,
      nullif(r.assignment_code, ''),
      nullif(r.ref_num, ''),
      r.start_utc,
      r.end_utc,
      coalesce(r.break_mins, 0),
      greatest(0, r.pay_minutes),
      'PENDING',
      now(),
      now(),
      r.candidate_id,
      r.client_id
    from resolved r
    where r.external_row_key is not null
      and not exists (
        select 1
        from public.nhsp_shifts s2
        where s2.external_row_key = r.external_row_key
      )
    returning
      (candidate_id is not null) as mapped_candidate,
      (client_id    is not null) as mapped_client
  ),

  ----------------------------------------------------------------
  -- Build update source rows with safe/blocked flags (avoids illegal LATERAL reference to UPDATE target)
  ----------------------------------------------------------------
  upd_src as (
    select
      s.external_row_key,
      s.timesheet_id,
      s.candidate_id as old_candidate_id,
      s.client_id    as old_client_id,

      r.work_date,
      r.staff_name,
      r.ward,
      r.assignment_code,
      r.ref_num,
      r.start_utc,
      r.end_utc,
      r.break_mins,
      r.pay_minutes,

      r.candidate_id as new_candidate_id,
      r.client_id    as new_client_id,

      fc.locked_by_invoice_id,
      fc.paid_at_utc,
      (fc.timesheet_id is null) as tsfin_missing,

      (
        s.timesheet_id is null
        or fc.timesheet_id is null
        or (fc.locked_by_invoice_id is null and fc.paid_at_utc is null)
      ) as safe_to_overwrite
    from public.nhsp_shifts s
    join resolved r
      on r.external_row_key = s.external_row_key
    left join fin_current fc
      on fc.timesheet_id = s.timesheet_id
  ),

  upd as (
    update public.nhsp_shifts s
    set
      latest_import_id = p_import_id,
      staff_name       = nullif(u.staff_name, ''),
      staff_norm       = nullif(lower(u.staff_name), ''),  -- keep existing stored format
      ward             = nullif(u.ward, ''),
      ward_norm        = nullif(lower(u.ward), ''),        -- keep existing stored format
      work_date        = u.work_date,
      assignment_code  = nullif(u.assignment_code, ''),
      ref_num          = nullif(u.ref_num, ''),
      start_utc        = u.start_utc,
      end_utc          = u.end_utc,
      break_mins       = coalesce(u.break_mins, 0),
      pay_minutes      = greatest(0, u.pay_minutes),
      source_system    = 'NHSP'::hr_source_enum,
      updated_at       = now(),

      -- ✅ UPDATED FIX (SAFE OVERWRITE):
      -- Allow corrected candidate_id/client_id to overwrite when SAFE:
      --   - shift not linked to a timesheet yet, OR
      --   - linked timesheet has no current TSFIN row, OR
      --   - linked timesheet TSFIN exists and is not paid and not invoice-locked.
      candidate_id     = case
                           when u.new_candidate_id is not null and u.safe_to_overwrite
                             then u.new_candidate_id
                           else s.candidate_id
                         end,
      client_id        = case
                           when u.new_client_id is not null and u.safe_to_overwrite
                             then u.new_client_id
                           else s.client_id
                         end
    from upd_src u
    where s.external_row_key = u.external_row_key
    returning
      (u.old_candidate_id is null and u.new_candidate_id is not null and u.safe_to_overwrite) as mapped_candidate,
      (u.old_client_id    is null and u.new_client_id    is not null and u.safe_to_overwrite) as mapped_client
  )

  select
    coalesce((select count(*) from ins), 0)                                   as created,
    coalesce((select count(*) from upd), 0)                                   as updated,
    coalesce((select count(*) from ins where mapped_candidate), 0)
      + coalesce((select count(*) from upd where mapped_candidate), 0)       as mapped_candidates,
    coalesce((select count(*) from ins where mapped_client), 0)
      + coalesce((select count(*) from upd where mapped_client), 0)          as mapped_clients
  into
    v_created,
    v_updated,
    v_mapped_candidates,
    v_mapped_clients;

  return jsonb_build_object(
    'import_id',          p_import_id,
    'shifts_created',     v_created,
    'shifts_updated',     v_updated,
    'mapped_candidates',  v_mapped_candidates,
    'mapped_clients',     v_mapped_clients
  );
end;
$function$;

-- nhsp_preview_mappings_phase1(uuid)
CREATE OR REPLACE FUNCTION public.nhsp_preview_mappings_phase1(p_import_id uuid)
 RETURNS TABLE(hr_row_id uuid, staff_name text, work_date date, ward text, trust_raw text, start_utc timestamp with time zone, end_utc timestamp with time zone, break_mins integer, ref_num text, assignment_code text, candidate_id uuid, candidate_name text, client_id uuid, client_name text)
 LANGUAGE sql
AS $function$
  with raw as (
    select
      r.id                             as hr_row_id,
      r.external_row_key,
      r.date_local                     as work_date,
      r.staff_norm                     as staff_norm,
      coalesce(
        nullif((r.payload_json ->> 'staff_name'), ''),
        nullif((r.payload_json ->> 'worker_name'), ''),
        nullif((r.payload_json ->> 'name'), ''),
        nullif(r.staff_raw, ''),
        nullif(r.staff_norm, '')
      )                                as staff_name,
      coalesce(
        nullif((r.payload_json ->> 'ward'), ''),
        nullif((r.payload_json ->> 'unit'), ''),
        nullif(r.unit_hint, ''),
        nullif(r.unit_raw, '')
      )                                as ward,
      coalesce(
        nullif((r.payload_json ->> 'trust'), ''),
        nullif((r.payload_json ->> 'hospital_or_trust'), ''),
        nullif(r.unit_raw, '')
      )                                as trust_raw,
      (r.payload_json ->> 'start_utc')::timestamptz as start_utc,
      (r.payload_json ->> 'end_utc')::timestamptz   as end_utc,
      coalesce(
        (r.payload_json ->> 'break_mins')::int,
        (r.payload_json ->> 'break_minutes')::int,
        (r.payload_json ->> 'actual_break_minutes')::int,
        0
      )                                as break_mins,
      coalesce(
        nullif((r.payload_json ->> 'ref_num'), ''),
        nullif((r.payload_json ->> 'Reference'), ''),
        nullif(r.hr_request_id, '')
      )                                as ref_num,
      coalesce(
        nullif((r.payload_json ->> 'assignment_code'), ''),
        nullif((r.payload_json ->> 'assignment'), ''),          -- ✅ parser writes payload_json.assignment
        nullif((r.payload_json ->> 'Request_Grade'), ''),
        nullif(r.assignment_grade_norm, '')
      )                                as assignment_code
    from public.hr_rows r
    where r.import_id = p_import_id
      and r.date_local is not null
      and (r.payload_json ->> 'start_utc') is not null
      and (r.payload_json ->> 'end_utc')   is not null
  ),
  resolved as (
    select
      src.*,
      n.staff_lc,
      n.staff_norm2,
      n.trust_lc,
      n.trust_norm,

      greatest(
        0,
        (extract(epoch from (src.end_utc - src.start_utc)) / 60)::int
        - src.break_mins
      ) as pay_minutes,

      -- Candidate mapping precedence:
      --  1) candidates.nhsp_hr_name_aliases contains staff_lc OR staff_norm2
      --  2) fallback to hr_name_mappings.hr_name_norm = staff_lc OR staff_norm2
      --  3) UNIQUE exact candidate match on (first+last) OR (last+first) using staff_norm2 (spaces/symbols removed)
      coalesce(
        cand_alias.id,
        cand_map.candidate_id,
        cand_exact_unique.candidate_id
      ) as candidate_id,

      -- Client mapping:
      --  1) client_hospitals.hospital_name_norm contains trust_lc OR trust_norm
      --  2) UNIQUE fallback where norm(clients.name) = trust_norm (spaces/symbols removed)
      coalesce(
        cli_alias.client_id,
        cli_name.client_id
      ) as client_id

    from raw src

    -- shared normalisations (strip spaces/symbols; keep only [a-z0-9])
    cross join lateral (
      select
        nullif(lower(trim(coalesce(src.staff_name,''))), '') as staff_lc,
        nullif(regexp_replace(lower(coalesce(src.staff_name,'')), '[^a-z0-9]+', '', 'g'), '') as staff_norm2,
        nullif(lower(trim(coalesce(src.trust_raw,''))), '') as trust_lc,
        nullif(regexp_replace(lower(coalesce(src.trust_raw,'')), '[^a-z0-9]+', '', 'g'), '') as trust_norm
    ) n

    -- 1) candidate alias match (support legacy + normalised)
    left join lateral (
      select c.id
      from public.candidates c
      where c.nhsp_hr_name_aliases is not null
        and (
          (n.staff_lc    is not null and c.nhsp_hr_name_aliases @> to_jsonb(array[n.staff_lc]::text[]))
          or
          (n.staff_norm2 is not null and c.nhsp_hr_name_aliases @> to_jsonb(array[n.staff_norm2]::text[]))
        )
      limit 1
    ) cand_alias on true

    -- 2) hr_name_mappings match (support legacy + normalised)
    left join lateral (
      select hm.candidate_id
      from public.hr_name_mappings hm
      where hm.active = true
        and (
          (n.staff_lc    is not null and hm.hr_name_norm = n.staff_lc)
          or
          (n.staff_norm2 is not null and hm.hr_name_norm = n.staff_norm2)
        )
      order by hm.created_at desc
      limit 1
    ) cand_map on (cand_alias.id is null)

    -- 3) UNIQUE exact candidate fallback (first+last OR last+first), symbols/spaces removed
    left join lateral (
      with matches as (
        select c.id as candidate_id
        from public.candidates c
        where c.active = true
          and n.staff_norm2 is not null
          and (
            regexp_replace(lower(coalesce(c.first_name,'') || coalesce(c.last_name,'')), '[^a-z0-9]+', '', 'g') = n.staff_norm2
            or
            regexp_replace(lower(coalesce(c.last_name,'')  || coalesce(c.first_name,'')), '[^a-z0-9]+', '', 'g') = n.staff_norm2
          )
      )
      select
        case
          when count(*) = 1
            then (array_agg(candidate_id order by candidate_id::text))[1]
        end as candidate_id
      from matches
    ) cand_exact_unique on (cand_alias.id is null and cand_map.candidate_id is null)

    -- 1) client alias match (support legacy + normalised)
    left join lateral (
      select ch.client_id
      from public.client_hospitals ch
      where ch.hospital_name_norm is not null
        and (
          (n.trust_lc   is not null and ch.hospital_name_norm @> to_jsonb(array[n.trust_lc]::text[]))
          or
          (n.trust_norm is not null and ch.hospital_name_norm @> to_jsonb(array[n.trust_norm]::text[]))
        )
      limit 1
    ) cli_alias on true

    -- 2) UNIQUE fallback: normalised clients.name == trust_norm
    left join lateral (
      with matches as (
        select cl.id as client_id
        from public.clients cl
        where n.trust_norm is not null
          and regexp_replace(lower(coalesce(cl.name,'')), '[^a-z0-9]+', '', 'g') = n.trust_norm
      )
      select
        case
          when count(*) = 1
            then (array_agg(client_id order by client_id::text))[1]
        end as client_id
      from matches
    ) cli_name on (cli_alias.client_id is null)
  )
  select
    r.hr_row_id,
    r.staff_name,
    r.work_date,
    r.ward,
    r.trust_raw,
    r.start_utc,
    r.end_utc,
    r.break_mins,
    r.ref_num,
    r.assignment_code,
    r.candidate_id,
    cand.display_name as candidate_name,
    r.client_id,
    cli.name          as client_name
  from resolved r
  left join public.candidates cand on cand.id = r.candidate_id
  left join public.clients    cli  on cli.id  = r.client_id;
$function$;

-- nhsp_weekly_apply_cancellations(uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.nhsp_weekly_apply_cancellations(p_import_id uuid, p_actions jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();

  v_actions jsonb := coalesce(p_actions, '[]'::jsonb);
  v_cancelled_count int := 0;

  v_import_source_system text;
  v_import_client_id uuid;

  v_idx int;
  v_item jsonb;

  v_shift_id_text text;
  v_shift_id uuid;
  v_reason text;

  -- shift fields
  v_timesheet_id uuid;
  v_shift_invoice_id uuid;
  v_shift_source_system text;
  v_shift_candidate_id uuid;
  v_shift_client_id uuid;
  v_shift_contract_id uuid;
  v_shift_work_date date;
  v_shift_cancelled_at timestamptz;

  v_shift_external_row_key text;
  v_shift_ref_num text;
  v_shift_ref_norm text;

  v_shift_start_utc timestamptz;
  v_shift_end_utc timestamptz;
  v_shift_break_mins int;
  v_shift_pay_minutes int;
  v_shift_ward text;
  v_shift_week_ending_date date;

  -- ✅ evidence pointer: shift's current latest_import_id (may be overwritten by anchor evidence)
  v_shift_latest_import_id uuid;

  -- import scope guard (NHSP may span multiple clients)
  v_import_client_in_scope boolean;

  -- file ref set
  v_file_ref_count int := 0;
  v_present_in_file boolean := false;

  -- invoiced-at-all detection (segment-level)
  v_tf_locked_by_invoice_id uuid;
  v_tf_invoice_breakdown_json jsonb;

  v_seg_json jsonb := null;
  v_seg_invoice_id uuid;
  v_seg_pay_amount numeric := null;
  v_seg_charge_amount numeric := null;

  v_invoiced_detected boolean := false;
  v_invoice_id_detected uuid := null;

  -- invoice number (best-effort; MUST NOT break apply)
  v_invoice_number_text text := null;

  -- cancellation correction timesheet (for invoiced-at-all)
  v_branch text := null;

  v_contract_display_site text;
  v_contract_ward_hint text;
  v_contract_role text;
  v_contract_week_ending_weekday_snapshot int := 0;

  v_candidate_display_name text;
  v_candidate_tms_ref text;
  v_client_name text;

  v_week_ending_date date;
  v_base_ts_week_ending date;

  v_correction_id text;
  v_kind text := 'CANCEL_SHIFT_REVERSAL';

  v_shift_label text;
  v_shift_label_norm text;

  v_booking_base text;
  v_booking_id text;
  v_hash_hex text;

  v_schedule jsonb;
  v_hint jsonb;

  v_base_week_id uuid;
  v_cw_id uuid;
  v_next_additional_seq int;
  v_try int;

  v_existing_ts_id uuid;
  v_existing_cw_id uuid;

  v_correction_ts_id uuid;
  v_ts_id uuid;

  -- fnv1a32 helper vars (needed for deterministic correction_id)
  v_fnv_h bigint;
  v_fnv_i int;
  v_fnv_s text;
  v_fnv_hex text;

  -- user-facing audit helpers (minutes + amounts)
  v_old_paid_minutes int := 0;
  v_new_paid_minutes int := 0;
  v_delta_paid_minutes int := 0;

  v_old_pay_amount_ex_vat numeric := null;
  v_old_charge_amount_ex_vat numeric := null;

  v_reversal_pay_amount_ex_vat numeric := null;
  v_reversal_charge_amount_ex_vat numeric := null;

  -- ✅ Cancellation anchor (what we reverse)
  v_anchor_start_utc timestamptz := null;
  v_anchor_end_utc timestamptz := null;
  v_anchor_break_mins int := 0;
  v_anchor_import_id uuid := null;

  -- ✅ Detect invoiced replacement (POS) to decide anchor
  v_pos_ts_id uuid := null;
  v_pos_schedule jsonb := null;
  v_pos_tf_locked_by_invoice_id uuid := null;
  v_pos_tf_invoice_breakdown_json jsonb := null;
  v_pos_seg_invoice_id uuid := null;
  v_pos_is_invoiced boolean := false;

  -- ✅ Base evidence import via existing CHANGED_HOURS_REVERSAL schedule (when POS is NOT invoiced)
  v_base_evidence_import_id uuid := null;

  -- ✅ Cleanup: remove uninvoiced CHANGED_HOURS corrections when cancelling
  v_cleanup_ts_ids uuid[] := array[]::uuid[];
  v_cleanup_count int := 0;
  -- Canonical historical correction-chain evidence
  v_chain_scope jsonb := null;
  v_financial_preflight jsonb := null;
  v_correction_financials_policy_envelope jsonb := null;
  v_correction_financials_policy_envelope_fingerprint text := null;
  v_correction_operation_id uuid := null;
  v_root_timesheet_id uuid := null;
  v_latest_positive_timesheet_id uuid := null;
  v_reversal_ts_id uuid := null;
  v_replacement_ts_id uuid := null;
  v_replacement_cw_id uuid := null;
  v_replacement_booking_id text := null;
  v_pair_changed boolean := false;


  -- return arrays
  v_timesheet_ids uuid[] := array[]::uuid[];
  v_invoice_ids uuid[] := array[]::uuid[];
  v_credit_note_ids uuid[] := array[]::uuid[];
  v_pdf_jobs_enqueued int := 0;

  -- debug sample
  v_sample jsonb := '[]'::jsonb;
  v_sample_n int := 0;

  v_last_shift_id uuid := null;
  v_review_status text;
  v_review_operation_id uuid;
  v_review_input_shift_ids uuid[] := array[]::uuid[];
  v_review_selected_shift_ids uuid[] := array[]::uuid[];

  v_sqlstate text;
  v_err text;
begin
  -- Validate import exists and is NHSP
  select
    upper(coalesce(hi.source_system::text, '')),
    hi.client_id
  into
    v_import_source_system,
    v_import_client_id
  from public.hr_imports hi
  where hi.id = p_import_id
  limit 1;

  if v_import_source_system is null or v_import_source_system = '' then
    raise exception 'nhsp_weekly_apply_cancellations: import % not found in hr_imports.', p_import_id;
  end if;

  if v_import_source_system <> 'NHSP' then
    raise exception 'nhsp_weekly_apply_cancellations: import % source_system=%; expected NHSP.', p_import_id, v_import_source_system;
  end if;

  -- Validate actions payload
  if jsonb_typeof(v_actions) <> 'array' then
    raise exception 'nhsp_weekly_apply_cancellations: p_actions must be a JSON array.';
  end if;

  select s.status,s.last_operation_id into v_review_status,v_review_operation_id
  from public.import_review_states s where s.import_id=p_import_id;
  if found then
    if v_review_status<>'APPLYING' or v_review_operation_id is null then
      raise exception 'IMPORT_REVIEW_CANCELLATION_CONTEXT_REQUIRED' using errcode='55000';
    end if;
    if jsonb_array_length(v_actions)>500 or exists(
      select 1 from jsonb_array_elements(v_actions) a
      where jsonb_typeof(a)<>'object' or coalesce(a->>'shift_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) then raise exception 'IMPORT_REVIEW_CANCELLATION_ACTIONS_INVALID' using errcode='22023'; end if;
    select coalesce(array_agg(distinct (a->>'shift_id')::uuid order by (a->>'shift_id')::uuid),array[]::uuid[])
      into v_review_input_shift_ids from jsonb_array_elements(v_actions) a;
    select coalesce(array_agg(d.shift_id order by d.shift_id),array[]::uuid[])
      into v_review_selected_shift_ids
    from public.import_review_decisions d
    where d.import_id=p_import_id and d.is_current and d.selected and d.action_kind='APPLY_CANCELLATION';
    if v_review_input_shift_ids is distinct from v_review_selected_shift_ids then
      raise exception 'IMPORT_REVIEW_CANCELLATION_ACTION_SET_MISMATCH' using errcode='40001';
    end if;
  end if;

  if jsonb_array_length(v_actions) = 0 then
    return jsonb_build_object(
      'import_id', p_import_id,
      'cancelled_count', 0,
      'affected_timesheet_ids', to_jsonb(array[]::uuid[]),
      'affected_invoice_ids', to_jsonb(array[]::uuid[]),
      'credit_note_ids_created', to_jsonb(array[]::uuid[]),
      'invoice_pdf_jobs_enqueued', 0
    );
  end if;

  -- ─────────────────────────────────────────────
  -- 1) Import scope guard (NHSP): client_id must be deterministically present in file
  --     ("deterministically present" = phase2 has candidate_id + client_id + work_date)
  -- ─────────────────────────────────────────────
  create temporary table tmp_import_client_scope(
    client_id uuid primary key
  ) on commit drop;

  insert into tmp_import_client_scope(client_id)
  select distinct p2.client_id
  from public.weekly_import_phase2(
    p_import_id := p_import_id,
    p_system_type := 'NHSP'
  ) as p2
  where p2.client_id is not null
    and p2.candidate_id is not null
    and p2.work_date is not null
  on conflict (client_id) do nothing;

  -- ─────────────────────────────────────────────
  -- 2) Build file ref set (identity key = booking ref)
  --     Spec: coalesce(payload_json->>'ref_num', payload_json->>'Reference', hr_request_id)
  -- ─────────────────────────────────────────────
  create temporary table tmp_file_ref_set(
    ref_norm text primary key,
    ref_raw  text
  ) on commit drop;

  insert into tmp_file_ref_set(ref_norm, ref_raw)
  select
    lower(regexp_replace(btrim(src.ref_raw), '\s+', ' ', 'g')) as ref_norm,
    src.ref_raw as ref_raw
  from (
    select distinct
      nullif(
        btrim(
          coalesce(
            nullif(r.payload_json->>'ref_num',''),
            nullif(r.payload_json->>'Reference',''),
            nullif(r.hr_request_id,'')
          )
        ),
        ''
      ) as ref_raw
    from public.hr_rows r
    where r.import_id = p_import_id
  ) as src
  where src.ref_raw is not null
  on conflict (ref_norm) do nothing;

  select count(*)::int
  into v_file_ref_count
  from tmp_file_ref_set;

  -- ─────────────────────────────────────────────
  -- 3) Apply is transactional: any invalid selected row fails the whole apply.
  -- ─────────────────────────────────────────────
  for v_idx, v_item in
    select (e.ord)::int, e.value
    from jsonb_array_elements(v_actions) with ordinality as e(value, ord)
  loop
    v_shift_id_text := nullif(btrim(coalesce(v_item->>'shift_id', '')), '');
    v_reason := nullif(btrim(coalesce(v_item->>'reason', '')), '');

    if v_shift_id_text is null then
      raise exception 'nhsp_weekly_apply_cancellations: item % missing shift_id.', v_idx;
    end if;

    begin
      v_shift_id := v_shift_id_text::uuid;
    exception when others then
      raise exception 'nhsp_weekly_apply_cancellations: item % invalid shift_id "%".', v_idx, v_shift_id_text;
    end;

    v_last_shift_id := v_shift_id;

    if v_reason is null then
      v_reason := 'MISSING_FROM_IMPORT';
    end if;

    -- reset per-item helpers
    v_tf_locked_by_invoice_id := null;
    v_tf_invoice_breakdown_json := null;
    v_seg_json := null;
    v_seg_invoice_id := null;
    v_seg_pay_amount := null;
    v_seg_charge_amount := null;

    v_invoice_id_detected := null;
    v_invoiced_detected := false;
    v_invoice_number_text := null;

    v_old_paid_minutes := 0;
    v_new_paid_minutes := 0;
    v_delta_paid_minutes := 0;
    v_old_pay_amount_ex_vat := null;
    v_old_charge_amount_ex_vat := null;
    v_reversal_pay_amount_ex_vat := null;
    v_reversal_charge_amount_ex_vat := null;

    v_shift_latest_import_id := null;

    v_anchor_start_utc := null;
    v_anchor_end_utc := null;
    v_anchor_break_mins := 0;
    v_anchor_import_id := null;

    v_pos_ts_id := null;
    v_pos_schedule := null;
    v_pos_tf_locked_by_invoice_id := null;
    v_pos_tf_invoice_breakdown_json := null;
    v_pos_seg_invoice_id := null;
    v_pos_is_invoiced := false;

    v_base_evidence_import_id := null;

    v_cleanup_ts_ids := array[]::uuid[];
    v_cleanup_count := 0;
    v_chain_scope := null;
    v_financial_preflight := null;
    v_correction_financials_policy_envelope := null;
    v_correction_financials_policy_envelope_fingerprint := null;
    v_root_timesheet_id := null;
    v_latest_positive_timesheet_id := null;
    v_reversal_ts_id := null;
    v_replacement_ts_id := null;
    v_replacement_cw_id := null;
    v_replacement_booking_id := null;
    v_pair_changed := false;

    -- Lock shift row + load required fields
    select
      ns.timesheet_id,
      ns.invoice_id,
      upper(coalesce(ns.source_system::text,'')) as shift_source_system,
      ns.candidate_id,
      ns.client_id,
      ns.contract_id,
      ns.work_date,
      ns.cancelled_at_utc,
      ns.external_row_key,
      ns.ref_num,
      ns.start_utc,
      ns.end_utc,
      ns.break_mins,
      ns.pay_minutes,
      ns.ward,
      ns.week_ending_date,
      ns.latest_import_id
    into
      v_timesheet_id,
      v_shift_invoice_id,
      v_shift_source_system,
      v_shift_candidate_id,
      v_shift_client_id,
      v_shift_contract_id,
      v_shift_work_date,
      v_shift_cancelled_at,
      v_shift_external_row_key,
      v_shift_ref_num,
      v_shift_start_utc,
      v_shift_end_utc,
      v_shift_break_mins,
      v_shift_pay_minutes,
      v_shift_ward,
      v_shift_week_ending_date,
      v_shift_latest_import_id
    from public.nhsp_shifts ns
    where ns.id = v_shift_id
    for update;

    if not found then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % not found in nhsp_shifts.', v_idx, v_shift_id;
    end if;

    if v_shift_cancelled_at is not null then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % is already cancelled (cancelled_at_utc not null).', v_idx, v_shift_id;
    end if;

    -- Locked guard: cancellations RPC only operates on NHSP shifts
    if v_shift_source_system <> 'NHSP' then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % source_system=%; expected NHSP.',
        v_idx, v_shift_id, v_shift_source_system;
    end if;

    if v_shift_contract_id is null then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % missing contract_id.', v_idx, v_shift_id;
    end if;

    if v_shift_candidate_id is null then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % missing candidate_id.', v_idx, v_shift_id;
    end if;

    if v_shift_work_date is null then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % missing work_date.', v_idx, v_shift_id;
    end if;

    if v_shift_client_id is null then
      raise exception 'nhsp_weekly_apply_cancellations: item % shift % missing client_id.', v_idx, v_shift_id;
    end if;

    -- Import scope safety: shift.client_id must be present deterministically in file.
    select exists (
      select 1
      from tmp_import_client_scope sc
      where sc.client_id = v_shift_client_id
    )
    into v_import_client_in_scope;

    if not v_import_client_in_scope then
      raise exception
        'nhsp_weekly_apply_cancellations: item % shift % client_id=% is out-of-scope for this import (client not deterministically present in file).',
        v_idx, v_shift_id, v_shift_client_id;
    end if;

    -- Guard A: require non-empty nhsp_shifts.ref_num (NHSP booking ref)
    if nullif(btrim(coalesce(v_shift_ref_num,'')), '') is null then
      raise exception
        'nhsp_weekly_apply_cancellations: item % shift % has empty ref_num; cannot use ref-based cancellation identity.',
        v_idx, v_shift_id;
    end if;

    v_shift_ref_norm := lower(regexp_replace(btrim(v_shift_ref_num), '\s+', ' ', 'g'));

    -- Presence test: if the ref is present in the file, cancellation is not eligible
    select exists (
      select 1
      from tmp_file_ref_set fr
      where fr.ref_norm = v_shift_ref_norm
    )
    into v_present_in_file;

    if v_present_in_file then
      raise exception
        'nhsp_weekly_apply_cancellations: item % shift % ref_num is present in the import file; cancellation rejected (not missing).',
        v_idx, v_shift_id;
    end if;

    -- ─────────────────────────────────────────────
    -- Invoiced-at-all detection (segment-level authoritative, base timesheet)
    -- ─────────────────────────────────────────────
    if v_timesheet_id is not null then
      select
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json
      into
        v_tf_locked_by_invoice_id,
        v_tf_invoice_breakdown_json
      from public.timesheets_financials tf
      where tf.timesheet_id = v_timesheet_id
        and tf.is_current = true
      limit 1;

      begin
        select s2.seg
        into v_seg_json
        from (
          select s2.seg
          from jsonb_array_elements(
            case
              when v_tf_invoice_breakdown_json is not null
               and jsonb_typeof(v_tf_invoice_breakdown_json) = 'object'
               and upper(coalesce(v_tf_invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
               and jsonb_typeof(v_tf_invoice_breakdown_json->'segments') = 'array'
              then v_tf_invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) as s2(seg)
          where
            (s2.seg->>'nhsp_shift_id') = v_shift_id::text
            or (
              v_shift_external_row_key is not null
              and (s2.seg->>'external_row_key') = v_shift_external_row_key
            )
          order by
            case when (s2.seg->>'nhsp_shift_id') = v_shift_id::text then 0 else 1 end
          limit 1
        ) as s2;
      exception when others then
        v_seg_json := null;
      end;

      if v_seg_json is not null then
        begin
          v_seg_invoice_id := nullif(btrim(coalesce(v_seg_json->>'invoice_locked_invoice_id','')), '')::uuid;
        exception when others then
          v_seg_invoice_id := null;
        end;

        begin
          v_seg_pay_amount := nullif(btrim(coalesce(v_seg_json->>'pay_amount','')), '')::numeric;
        exception when others then
          v_seg_pay_amount := null;
        end;

        begin
          v_seg_charge_amount := nullif(btrim(coalesce(v_seg_json->>'charge_amount','')), '')::numeric;
        exception when others then
          v_seg_charge_amount := null;
        end;
      end if;
    end if;

    v_invoice_id_detected := coalesce(v_seg_invoice_id, v_tf_locked_by_invoice_id, v_shift_invoice_id);
    v_invoiced_detected := (v_invoice_id_detected is not null);

    if v_invoice_id_detected is not null then
      v_invoice_ids := array_append(v_invoice_ids, v_invoice_id_detected);

      -- Best-effort invoice number lookup using the current invoices.invoice_no column only.
      -- Do not reference legacy/stale invoice_number or number columns.
      begin
        select nullif(btrim(coalesce(i.invoice_no::text, '')), '')
        into v_invoice_number_text
        from public.invoices as i
        where i.id = v_invoice_id_detected
        limit 1;
      exception when undefined_table then
        v_invoice_number_text := null;
      when others then
        v_invoice_number_text := null;
      end;
    end if;

    -- Default audit minute/amount helpers (may be overridden for CORRECTION anchor)
    if v_shift_pay_minutes is not null then
      v_old_paid_minutes := greatest(0, v_shift_pay_minutes);
    elsif v_shift_start_utc is not null and v_shift_end_utc is not null then
      v_old_paid_minutes := greatest(
        0,
        (extract(epoch from (v_shift_end_utc - v_shift_start_utc)) / 60)::int - greatest(0, coalesce(v_shift_break_mins, 0))
      );
    else
      v_old_paid_minutes := 0;
    end if;

    v_new_paid_minutes := 0;
    v_delta_paid_minutes := (0 - v_old_paid_minutes);

    v_old_pay_amount_ex_vat := v_seg_pay_amount;
    v_old_charge_amount_ex_vat := v_seg_charge_amount;

    if v_old_pay_amount_ex_vat is not null then
      v_reversal_pay_amount_ex_vat := (0 - v_old_pay_amount_ex_vat);
    end if;

    if v_old_charge_amount_ex_vat is not null then
      v_reversal_charge_amount_ex_vat := (0 - v_old_charge_amount_ex_vat);
    end if;

    -- ─────────────────────────────────────────────

    if v_timesheet_id is not null then
      select public.import_timesheet_financial_preflight_v1(
        p_timesheet_ids := array[v_timesheet_id]::uuid[],
        p_action := 'IMPORT_CANCELLATION',
        p_actor_user_id := p_actor_user_id,
        p_expected_state_json := '{}'::jsonb,
        p_lock_rows := true,
        p_max_scope := 100
      ) into v_financial_preflight;

      if coalesce((v_financial_preflight->>'allowed')::boolean,false) is not true then
        raise exception using message='IMPORT_FINANCIAL_PREFLIGHT_BLOCKED', errcode='P0001', detail=v_financial_preflight::text;
      end if;

      if v_financial_preflight->>'required_path' = 'CREATE_OR_UPDATE_CORRECTION_CHAIN'
         and v_invoiced_detected is false then
        select il.invoice_id
        into v_invoice_id_detected
        from public.invoice_lines il
        join public.invoices i on i.id=il.invoice_id
        where il.timesheet_id=v_timesheet_id
        order by coalesce(i.issued_at_utc,i.created_at) desc, il.invoice_id desc
        limit 1;

        if v_invoice_id_detected is null then
          raise exception using message='IMPORT_INVOICE_EVIDENCE_INCOMPLETE',errcode='P0001',
            detail=jsonb_build_object(
              'code','IMPORT_INVOICE_EVIDENCE_INCOMPLETE',
              'timesheet_id',v_timesheet_id,
              'required_path','CREATE_OR_UPDATE_CORRECTION_CHAIN'
            )::text;
        end if;

        v_invoiced_detected := true;
        v_invoice_ids := array_append(v_invoice_ids,v_invoice_id_detected);
      end if;
    end if;

    -- Branch: INPLACE vs CORRECTION
    -- ─────────────────────────────────────────────
    if v_invoiced_detected = false then
      v_branch := 'INPLACE';

      if v_timesheet_id is not null and exists (
        select 1
        from public.timesheets guard_ts
        left join public.timesheets_financials guard_tf
          on guard_tf.timesheet_id=guard_ts.timesheet_id and guard_tf.is_current=true
        where guard_ts.timesheet_id=v_timesheet_id
          and (guard_ts.authorised_at_server is not null or guard_tf.authorised_at_utc is not null)
          and not exists (
            select 1 from public.timesheets_financials paid_guard
            where paid_guard.timesheet_id=guard_ts.timesheet_id
              and paid_guard.paid_at_utc is not null
          )
      ) then
        raise exception using message='CANONICAL_UNAUTHORISE_REQUIRED', errcode='P0001',
          detail=jsonb_build_object(
            'code','CANONICAL_UNAUTHORISE_REQUIRED','timesheet_id',v_timesheet_id,
            'required_path',jsonb_build_array('UNAUTHORISE','AMEND','RECALCULATE','REAUTHORISE'),
            'paid_uninvoiced_rollover_required',false
          )::text;
      end if;

      if v_timesheet_id is not null
         and exists (select 1 from public.timesheets_financials paid_tf where paid_tf.timesheet_id=v_timesheet_id and paid_tf.paid_at_utc is not null)
         and not exists (
           select 1 from public.timesheets_financials current_tf
           where current_tf.timesheet_id=v_timesheet_id and current_tf.is_current=true
             and current_tf.stale_reason='IMPORT_PAID_TSFIN_ROLLOVER_PENDING_CALCULATION'
             and coalesce((current_tf.policy_snapshot_json->>'requires_frozen_correction_policy')::boolean,false)=true
         ) then
        raise exception using message='PAID_UNINVOICED_ROLLOVER_REQUIRED', errcode='P0001',
          detail=jsonb_build_object(
            'code','PAID_UNINVOICED_ROLLOVER_REQUIRED','timesheet_id',v_timesheet_id,
            'required_path',jsonb_build_array(
              'UNAUTHORISE','PAID_UNINVOICED_ROLLOVER','AMEND','RECALCULATE','REAUTHORISE'
            ),
            'invoice_policy_without_history','NOW',
            'replacement_timesheet_required',false
          )::text;
      end if;


      -- Cancel + detach (no deletions)
      update public.nhsp_shifts ns2
      set
        cancelled_at_utc = v_now,
        cancelled_by_import_id = p_import_id,
        cancelled_reason = v_reason,
        timesheet_id = null
      where ns2.id = v_shift_id;

      v_cancelled_count := v_cancelled_count + 1;

      -- TSFIN recompute is mandatory for any cancel/detach/change (in-place branch only).
      if v_timesheet_id is not null then
        v_timesheet_ids := array_append(v_timesheet_ids, v_timesheet_id);

        update public.timesheets_financials tfu
        set
          is_stale = true,
          stale_reason = 'IMPORT_CANCEL_DETACH',
          updated_at = v_now
        where tfu.is_current = true
          and tfu.timesheet_id = v_timesheet_id;

        perform public.enqueue_ts_financials_priority(array[v_timesheet_id]::uuid[], 'CONTEXT_CHANGED'::public.ts_fin_reason_enum);
      end if;

      v_correction_ts_id := null;

      -- Retained financial history is never deleted. Existing changed-hours
      -- corrections stay in the chain and are reconciled by the reversal-only correction unit.
      v_cleanup_ts_ids := array[]::uuid[];
      v_cleanup_count := 0;

      -- User-facing audit (UNGATED) for in-place cancellation (timesheet)
      begin
        if v_timesheet_id is not null then
          perform public._audit_insert(
            'timesheets',
            v_timesheet_id::text,
            'NHSP_IMPORT_CANCELLATION_APPLIED',
            null,
            jsonb_build_object(
              'import_id', p_import_id::text,
              'branch', v_branch,
              'shift_id', v_shift_id::text,
              'work_date', v_shift_work_date::text,
              'external_row_key', v_shift_external_row_key,
              'ref_num', nullif(btrim(coalesce(v_shift_ref_num,'')), ''),
              'cancel_reason', v_reason,
              'old_paid_minutes', v_old_paid_minutes,
              'new_paid_minutes', 0,
              'delta_paid_minutes', v_delta_paid_minutes,
              'old_pay_amount_ex_vat', v_old_pay_amount_ex_vat,
              'old_charge_amount_ex_vat', v_old_charge_amount_ex_vat,
              'retained_changed_hours_count', v_cleanup_count
            ),
            'IMPORT_CANCEL_DETACH',
            p_actor_user_id
          );
        end if;
      exception when others then
        null;
      end;

    else
      v_branch := 'CORRECTION';

      -- Resolve week_ending_date for the correction timesheet (never assume Sunday)
      v_week_ending_date := null;
      v_base_ts_week_ending := null;

      if v_timesheet_id is not null then
        select t.week_ending_date
        into v_base_ts_week_ending
        from public.timesheets t
        where t.timesheet_id = v_timesheet_id
        limit 1;

        if v_base_ts_week_ending is not null then
          v_week_ending_date := v_base_ts_week_ending;
        end if;
      end if;

      if v_week_ending_date is null and v_shift_week_ending_date is not null then
        v_week_ending_date := v_shift_week_ending_date;
      end if;

      if v_week_ending_date is null then
        select coalesce(c.week_ending_weekday_snapshot, 0)
        into v_contract_week_ending_weekday_snapshot
        from public.contracts c
        where c.id = v_shift_contract_id
        limit 1;

        v_week_ending_date :=
          (v_shift_work_date + (((v_contract_week_ending_weekday_snapshot - extract(dow from v_shift_work_date)::int + 7) % 7))::int)::date;
      end if;

      if v_week_ending_date is null then
        raise exception 'nhsp_weekly_apply_cancellations: shift % cannot resolve week_ending_date for correction.', v_shift_id;
      end if;

      -- ─────────────────────────────────────────────

      if v_timesheet_id is null then
        raise exception using message='CORRECTION_BASE_TIMESHEET_REQUIRED', errcode='P0001',
          detail=jsonb_build_object('code','CORRECTION_BASE_TIMESHEET_REQUIRED','shift_id',v_shift_id)::text;
      end if;

      select public.timesheet_correction_chain_scope_v1(
        v_timesheet_id, true, 32, 100
      ) into v_chain_scope;

      if coalesce((v_chain_scope->>'valid')::boolean,false) is not true then
        raise exception using message='CORRECTION_CHAIN_UNRESOLVED', errcode='P0001', detail=v_chain_scope::text;
      end if;

      v_root_timesheet_id := nullif(v_chain_scope->>'root_timesheet_id','')::uuid;
      v_latest_positive_timesheet_id := coalesce(
        nullif(v_chain_scope->>'latest_positive_timesheet_id','')::uuid,
        v_timesheet_id
      );
      v_correction_operation_id := public._ctms_import_correction_operation_find_v1(
        p_import_id,
        v_root_timesheet_id,
        v_shift_external_row_key,
        'CANCELLATION',
        'REVERSAL_ONLY'
      );
      update public.nhsp_shifts canonical_cancel
      set cancelled_at_utc=coalesce(canonical_cancel.cancelled_at_utc,v_now),
          cancelled_by_import_id=p_import_id
      where canonical_cancel.id=v_shift_id
        and (canonical_cancel.cancelled_by_import_id is null
             or canonical_cancel.cancelled_by_import_id=p_import_id);
      if not found then
        raise exception 'CANCELLATION_IMPORT_EVIDENCE_CONFLICT' using errcode='P0001';
      end if;
      v_correction_financials_policy_envelope := public.correction_financials_policy_resolve_v1(
        v_timesheet_id,
        v_correction_operation_id,
        v_shift_external_row_key,
        'CANCELLATION',
        null::text,
        true,
        32
      );
      v_correction_financials_policy_envelope_fingerprint :=
        v_correction_financials_policy_envelope ->> 'envelope_fingerprint';
      v_kind := 'CANCELLATION_REVERSAL';

      -- ✅ Determine cancellation anchor:
      --   - If there is an invoiced/locked CHANGED_HOURS_REPLACEMENT (POS), reverse that.
      --   - Else reverse the BASE locked segment (v_seg_json), and use base import evidence from CHANGED_HOURS_REVERSAL when available.
      -- ─────────────────────────────────────────────
      -- Default anchor = current shift truth (fallback only)
      v_anchor_start_utc := v_shift_start_utc;
      v_anchor_end_utc := v_shift_end_utc;
      v_anchor_break_mins := greatest(0, coalesce(v_shift_break_mins, 0));
      v_anchor_import_id := v_shift_latest_import_id;

      -- Find latest POS (replacement) correction timesheet for this shift
      begin
        select
          tpos.timesheet_id,
          tpos.actual_schedule_json
        into
          v_pos_ts_id,
          v_pos_schedule
        from public.timesheets tpos
        where tpos.is_adjustment is true
          and tpos.is_current is true
          and tpos.correction_kind = 'CHANGED_HOURS_REPLACEMENT'
          and tpos.contract_id = v_shift_contract_id
          and tpos.week_ending_date = v_week_ending_date
          and jsonb_typeof(tpos.actual_schedule_json) = 'array'
          and (
            tpos.actual_schedule_json @> jsonb_build_array(jsonb_build_object('shift_id', v_shift_id::text))
            or (
              v_shift_external_row_key is not null
              and tpos.actual_schedule_json @> jsonb_build_array(jsonb_build_object('external_row_key', v_shift_external_row_key))
            )
          )
        order by tpos.updated_at desc nulls last, tpos.created_at desc nulls last
        limit 1
        for update;
      exception when others then
        v_pos_ts_id := null;
        v_pos_schedule := null;
      end;

      if v_pos_ts_id is not null then
        select
          tf.locked_by_invoice_id,
          tf.invoice_breakdown_json
        into
          v_pos_tf_locked_by_invoice_id,
          v_pos_tf_invoice_breakdown_json
        from public.timesheets_financials tf
        where tf.timesheet_id = v_pos_ts_id
          and tf.is_current = true
        order by tf.created_at desc
        limit 1;

        begin
          select
            nullif(btrim(coalesce(s2.seg->>'invoice_locked_invoice_id','')), '')::uuid
          into v_pos_seg_invoice_id
          from (
            select s2.seg
            from jsonb_array_elements(
              case
                when v_pos_tf_invoice_breakdown_json is not null
                 and jsonb_typeof(v_pos_tf_invoice_breakdown_json)='object'
                 and jsonb_typeof(v_pos_tf_invoice_breakdown_json->'segments')='array'
                then v_pos_tf_invoice_breakdown_json->'segments'
                else '[]'::jsonb
              end
            ) s2(seg)
            where nullif(btrim(coalesce(s2.seg->>'invoice_locked_invoice_id','')), '') is not null
            limit 1
          ) as s2;
        exception when others then
          v_pos_seg_invoice_id := null;
        end;

        v_pos_is_invoiced :=
          (v_pos_tf_locked_by_invoice_id is not null)
          or (v_pos_seg_invoice_id is not null);

        if v_pos_is_invoiced is true and v_pos_schedule is not null and jsonb_typeof(v_pos_schedule)='array' then
          begin
            v_anchor_start_utc := nullif(btrim(coalesce((v_pos_schedule->0)->>'start_utc','')), '')::timestamptz;
          exception when others then
            v_anchor_start_utc := v_shift_start_utc;
          end;

          begin
            v_anchor_end_utc := nullif(btrim(coalesce((v_pos_schedule->0)->>'end_utc','')), '')::timestamptz;
          exception when others then
            v_anchor_end_utc := v_shift_end_utc;
          end;

          begin
            v_anchor_break_mins := greatest(0, coalesce(nullif(btrim(coalesce((v_pos_schedule->0)->>'break_mins','')), '')::int, 0));
          exception when others then
            v_anchor_break_mins := greatest(0, coalesce(v_shift_break_mins, 0));
          end;

          begin
            if ((v_pos_schedule->0) ? 'import_id')
              and nullif(btrim(coalesce((v_pos_schedule->0)->>'import_id','')), '') is not null
              and (v_pos_schedule->0)->>'import_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then
              v_anchor_import_id := ((v_pos_schedule->0)->>'import_id')::uuid;
            end if;
          exception when others then
            null;
          end;
        end if;
      end if;

      -- If POS is NOT invoiced, anchor to base locked segment (if available)
      if v_pos_is_invoiced is not true then
        -- Base evidence import id: from CHANGED_HOURS_REVERSAL schedule if present
        begin
          select
            nullif(btrim(coalesce((tneg.actual_schedule_json->0)->>'import_id','')), '')::uuid
          into v_base_evidence_import_id
          from public.timesheets tneg
          where tneg.is_adjustment is true
            and tneg.is_current is true
            and tneg.correction_kind = 'CHANGED_HOURS_REVERSAL'
            and tneg.contract_id = v_shift_contract_id
            and tneg.week_ending_date = v_week_ending_date
            and jsonb_typeof(tneg.actual_schedule_json)='array'
            and (
              tneg.actual_schedule_json @> jsonb_build_array(jsonb_build_object('shift_id', v_shift_id::text))
              or (
                v_shift_external_row_key is not null
                and tneg.actual_schedule_json @> jsonb_build_array(jsonb_build_object('external_row_key', v_shift_external_row_key))
              )
            )
          order by tneg.updated_at desc nulls last, tneg.created_at desc nulls last
          limit 1;
        exception when others then
          v_base_evidence_import_id := null;
        end;

        if v_base_evidence_import_id is not null then
          v_anchor_import_id := v_base_evidence_import_id;
        end if;

        if v_seg_json is not null then
          begin
            if nullif(btrim(coalesce(v_seg_json->>'start_utc','')), '') is not null then
              v_anchor_start_utc := (v_seg_json->>'start_utc')::timestamptz;
            end if;
          exception when others then
            null;
          end;

          begin
            if nullif(btrim(coalesce(v_seg_json->>'end_utc','')), '') is not null then
              v_anchor_end_utc := (v_seg_json->>'end_utc')::timestamptz;
            end if;
          exception when others then
            null;
          end;

          begin
            if nullif(btrim(coalesce(v_seg_json->>'break_mins','')), '') is not null then
              v_anchor_break_mins := greatest(0, (v_seg_json->>'break_mins')::int);
            end if;
          exception when others then
            null;
          end;
        end if;
      end if;

      -- Require anchor start/end for schedule-driven correction artefact
      if v_anchor_start_utc is null or v_anchor_end_utc is null then
        raise exception 'nhsp_weekly_apply_cancellations: shift % missing anchor start/end; cannot create schedule-driven cancellation correction.', v_shift_id;
      end if;

      -- Recompute minutes helper for audit based on anchor (not current truth)
      v_old_paid_minutes := greatest(
        0,
        (extract(epoch from (v_anchor_end_utc - v_anchor_start_utc)) / 60)::int - greatest(0, coalesce(v_anchor_break_mins, 0))
      );
      v_new_paid_minutes := 0;
      v_delta_paid_minutes := (0 - v_old_paid_minutes);

      -- Build correction_id (stable + deterministic) using anchor times
      v_fnv_s :=
        coalesce(p_import_id::text,'') || '|' ||
        coalesce(v_shift_id::text,'') || '|' ||
        coalesce(v_shift_ref_num,'') || '|' ||
        coalesce(v_shift_external_row_key,'') || '|' ||
        coalesce(v_anchor_start_utc::text,'') || '|' ||
        coalesce(v_anchor_end_utc::text,'') || '|' ||
        coalesce(coalesce(v_anchor_break_mins,0)::text,'');

      v_fnv_h := 2166136261;
      for v_fnv_i in 1..char_length(v_fnv_s) loop
        v_fnv_h := (v_fnv_h # ascii(substring(v_fnv_s from v_fnv_i for 1)));
        v_fnv_h := (v_fnv_h * 16777619) % 4294967296;
      end loop;
      v_fnv_hex := lpad(lower(to_hex(v_fnv_h)), 8, '0');

      v_correction_id := 'can:' || p_import_id::text || ':' || v_shift_id::text || ':' || v_fnv_hex;

      -- Load contract + optional client/candidate display context for norms
      select
        c2.display_site,
        c2.ward_hint,
        c2.role
      into
        v_contract_display_site,
        v_contract_ward_hint,
        v_contract_role
      from public.contracts c2
      where c2.id = v_shift_contract_id
      limit 1;

      select cl.name
      into v_client_name
      from public.clients cl
      where cl.id = v_shift_client_id
      limit 1;

      select cand.display_name, cand.tms_ref
      into v_candidate_display_name, v_candidate_tms_ref
      from public.candidates cand
      where cand.id = v_shift_candidate_id
      limit 1;

      -- Schedule entry (anchor-based)
      v_schedule := jsonb_build_array(
        jsonb_build_object(
          'date', v_shift_work_date::text,
          'ward', nullif(btrim(coalesce(v_shift_ward, v_contract_ward_hint, '')), ''),
          'start_utc', v_anchor_start_utc::text,
          'end_utc', v_anchor_end_utc::text,
          'start', to_char((v_anchor_start_utc at time zone 'Europe/London')::time, 'HH24:MI'),
          'end', to_char((v_anchor_end_utc at time zone 'Europe/London')::time, 'HH24:MI'),
          'break_mins', greatest(0, coalesce(v_anchor_break_mins, 0)),
          'ref_num', nullif(btrim(coalesce(v_shift_ref_num,'')), ''),
          'shift_id', v_shift_id::text,
          'external_row_key', v_shift_external_row_key,
          'import_id', case when v_anchor_import_id is null then null else v_anchor_import_id::text end
        )
      );

      v_hint := jsonb_build_object(
        'import_cancellation', jsonb_build_object(
          'import_id', p_import_id::text,
          'shift_id', v_shift_id::text,
          'ref_num', nullif(btrim(coalesce(v_shift_ref_num,'')), ''),
          'correction_id', v_correction_id,
          'correction_kind', 'CANCELLATION_REVERSAL_ONLY',
              'correction_financials_policy_envelope_fingerprint', v_correction_financials_policy_envelope_fingerprint,
              'reversal_timesheet_id', case when v_reversal_ts_id is null then null else v_reversal_ts_id::text end,
              'replacement_timesheet_id', case when v_replacement_ts_id is null then null else v_replacement_ts_id::text end,
          'invoice_id_detected', case when v_invoice_id_detected is null then null else v_invoice_id_detected::text end,
          'anchor', case
                      when v_pos_is_invoiced is true then 'INVOICED_REPLACEMENT'
                      else 'BASE_LOCKED'
                    end
        )
      );
      v_hint := v_hint || jsonb_build_object(
        'correction_financials_policy_envelope',v_correction_financials_policy_envelope,
        'correction_financials_policy_envelope_fingerprint',v_correction_financials_policy_envelope_fingerprint,
        'root_timesheet_id',v_root_timesheet_id::text,
        'latest_positive_timesheet_id',v_latest_positive_timesheet_id::text
      );

      v_shift_label := 'weekly-cancel-reversal-' || v_correction_id;

      v_shift_label_norm :=
        regexp_replace(
          regexp_replace(lower(trim(v_shift_label)), '\s+', ' ', 'g'),
          '[^\w\s\-@&\/,:]',
          '',
          'g'
        );

      v_booking_base :=
        'scope=WEEKLY' || '|' ||
        'contract_id=' || coalesce(v_shift_contract_id::text,'') || '|' ||
        'candidate_id=' || coalesce(v_shift_candidate_id::text,'') || '|' ||
        'client_id=' || coalesce(v_shift_client_id::text,'') || '|' ||
        'week_ending_date=' || coalesce(v_week_ending_date::text,'') || '|' ||
        'correction_id=' || coalesce(v_correction_id,'') || '|' ||
        'correction_kind=' || v_kind;

      v_hash_hex := substring(encode(extensions.digest(convert_to(v_booking_base, 'utf8'), 'sha256'::text), 'hex') from 1 for 16);
      v_booking_id := 'bk_' || v_hash_hex;

      -- Ensure base week exists (seq=0)
      insert into public.contract_weeks(
        contract_id,
        week_ending_date,
        additional_seq,
        status,
        submission_mode_snapshot,
        timesheet_id,
        planned_schedule_json,
        created_at,
        updated_at,
        is_adjustment
      )
      values (
        v_shift_contract_id,
        v_week_ending_date,
        0,
        'SUBMITTED'::public.contract_week_status_enum,
        'MANUAL'::public.submission_mode_enum,
        null,
        '[]'::jsonb,
        v_now,
        v_now,
        false
      )
      on conflict (contract_id, week_ending_date, additional_seq) do nothing;

      select cw0.id
      into v_base_week_id
      from public.contract_weeks cw0
      where cw0.contract_id = v_shift_contract_id
        and cw0.week_ending_date = v_week_ending_date
        and cw0.additional_seq = 0
      limit 1
      for update;

      if v_base_week_id is null then
        raise exception 'nhsp_weekly_apply_cancellations: failed to ensure base contract_week exists (contract_id=% week_ending=%).',
          v_shift_contract_id, v_week_ending_date;
      end if;

      -- Idempotency: reuse existing correction timesheet (unique on correction_id+kind)
      v_existing_ts_id := null;

      select t2.timesheet_id
      into v_existing_ts_id
      from public.timesheets t2
      where t2.correction_id = v_correction_id
        and t2.correction_kind in (v_kind, 'CANCEL_SHIFT_REVERSAL')
      order by
        case when t2.correction_kind=v_kind then 0 else 1 end,
        t2.is_current desc,
        t2.version desc,
        t2.timesheet_id
      limit 1
      for update;

      if v_existing_ts_id is not null then
        v_correction_ts_id := v_existing_ts_id;

        -- Ensure there is an adjustment contract_week linked; if missing, create one and link it.
        v_existing_cw_id := null;

        select cw2.id
        into v_existing_cw_id
        from public.contract_weeks cw2
        where cw2.timesheet_id = v_existing_ts_id
          and cw2.contract_id = v_shift_contract_id
          and cw2.week_ending_date = v_week_ending_date
        limit 1
        for update;

        if v_existing_cw_id is null then
          perform 1
          from public.contract_weeks cwlock
          where cwlock.contract_id = v_shift_contract_id
            and cwlock.week_ending_date = v_week_ending_date
          for update;

          v_try := 0;
          loop
            v_try := v_try + 1;
            if v_try > 10 then
              raise exception 'nhsp_weekly_apply_cancellations: failed to allocate additional_seq after retries (contract_id=% week_ending=%).',
                v_shift_contract_id, v_week_ending_date;
            end if;

            select coalesce(max(cwmax.additional_seq), 0) + 1
            into v_next_additional_seq
            from public.contract_weeks cwmax
            where cwmax.contract_id = v_shift_contract_id
              and cwmax.week_ending_date = v_week_ending_date;

            begin
              insert into public.contract_weeks(
                contract_id,
                week_ending_date,
                additional_seq,
                is_adjustment,
                submission_mode_snapshot,
                status,
                created_at,
                updated_at,
                timesheet_id
              )
              values (
                v_shift_contract_id,
                v_week_ending_date,
                v_next_additional_seq,
                true,
                'MANUAL'::public.submission_mode_enum,
                'SUBMITTED'::public.contract_week_status_enum,
                v_now,
                v_now,
                v_existing_ts_id
              )
              returning id into v_existing_cw_id;

              exit;
            exception when unique_violation then
              v_existing_cw_id := null;
            end;
          end loop;
        end if;

        if exists (
          select 1
          from public.timesheets desired_reversal
          where desired_reversal.timesheet_id=v_existing_ts_id
            and (
              desired_reversal.actual_schedule_json is distinct from v_schedule
              or desired_reversal.parent_timesheet_id is distinct from v_latest_positive_timesheet_id
              or desired_reversal.contract_id is distinct from v_shift_contract_id
              or desired_reversal.week_ending_date is distinct from v_week_ending_date
              or desired_reversal.correction_id is distinct from v_correction_id
              or desired_reversal.correction_kind is distinct from v_kind
              or coalesce(desired_reversal.candidate_hint_text->>'correction_financials_policy_envelope_fingerprint','')
                   is distinct from coalesce(v_correction_financials_policy_envelope_fingerprint,'')
            )
        ) then
          if exists (
            select 1
            from public.timesheets legacy_reversal
            left join public.timesheets_financials legacy_financial
              on legacy_financial.timesheet_id=legacy_reversal.timesheet_id
             and legacy_financial.is_current=true
            where legacy_reversal.timesheet_id=v_existing_ts_id
              and legacy_reversal.correction_kind='CANCEL_SHIFT_REVERSAL'
              and (
                legacy_reversal.authorised_at_server is not null
                or legacy_financial.authorised_at_utc is not null
                or legacy_financial.paid_at_utc is not null
                or legacy_financial.locked_by_invoice_id is not null
                or exists(select 1 from public.invoice_lines legacy_line where legacy_line.timesheet_id=legacy_reversal.timesheet_id)
              )
          ) then
            raise exception using message='LEGACY_CANCELLATION_CORRECTION_MIGRATION_REQUIRED',errcode='P0001',
              detail=jsonb_build_object('code','LEGACY_CANCELLATION_CORRECTION_MIGRATION_REQUIRED','timesheet_id',v_existing_ts_id,'correction_id',v_correction_id)::text;
          end if;

          if exists (
            select 1
            from public.timesheets guarded_reversal
            left join public.timesheets_financials guarded_reversal_financial
              on guarded_reversal_financial.timesheet_id=guarded_reversal.timesheet_id
             and guarded_reversal_financial.is_current=true
            where guarded_reversal.timesheet_id=v_existing_ts_id
              and (
                guarded_reversal.authorised_at_server is not null
                or guarded_reversal_financial.authorised_at_utc is not null
                or guarded_reversal_financial.paid_at_utc is not null
                or guarded_reversal_financial.locked_by_invoice_id is not null
                or exists(select 1 from public.invoice_lines guarded_line where guarded_line.timesheet_id=guarded_reversal.timesheet_id)
              )
          ) then
            raise exception using message='CORRECTION_PAIR_LIFECYCLE_TRANSITION_REQUIRED',errcode='P0001',
              detail=jsonb_build_object('code','CORRECTION_PAIR_LIFECYCLE_TRANSITION_REQUIRED','timesheet_id',v_existing_ts_id,'required_path','PAIR_UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE')::text;
          end if;

          update public.timesheets tu
          set
            booking_id = v_booking_id,
            is_current = true,
            status = 'RECEIVED'::public.timesheet_status_enum,
            sheet_scope = 'WEEKLY'::public.timesheet_scope_enum,
            submission_mode = 'MANUAL'::public.submission_mode_enum,
            line_type = 'HOURS'::public.timesheet_line_type_enum,
            authorised_at_server = null,
            occupant_key_norm = lower(coalesce(v_candidate_tms_ref, v_candidate_display_name, v_shift_candidate_id::text)),
            hospital_norm = lower(coalesce(v_contract_display_site, v_client_name, v_shift_client_id::text)),
            ward_norm = lower(coalesce(v_contract_ward_hint, 'contract')),
            job_title_norm = lower(coalesce(v_contract_role, 'weekly')),
            shift_label_norm = v_shift_label_norm,
            week_ending_date = v_week_ending_date,
            contract_id = v_shift_contract_id,
            manual_pdf_r2_key = null,
            actual_schedule_json = v_schedule,
            qr_payload_json = v_hint,
            candidate_hint_text = v_hint,
            is_adjustment = true,
            parent_timesheet_id = v_latest_positive_timesheet_id,
            correction_id = v_correction_id,
            correction_kind = v_kind,
            adjustment_origin = 'IMPORT_CANCELLATION',
            updated_at = v_now
          where tu.timesheet_id = v_existing_ts_id;

          v_pair_changed := true;
        end if;

      else
        -- Create a new adjustment contract_week (safe additional_seq)
        perform 1
        from public.contract_weeks cwlock2
        where cwlock2.contract_id = v_shift_contract_id
          and cwlock2.week_ending_date = v_week_ending_date
        for update;

        v_try := 0;
        loop
          v_try := v_try + 1;
          if v_try > 10 then
            raise exception 'nhsp_weekly_apply_cancellations: failed to allocate additional_seq after retries (contract_id=% week_ending=%).',
              v_shift_contract_id, v_week_ending_date;
          end if;

          select coalesce(max(cwmax2.additional_seq), 0) + 1
          into v_next_additional_seq
          from public.contract_weeks cwmax2
          where cwmax2.contract_id = v_shift_contract_id
            and cwmax2.week_ending_date = v_week_ending_date;

          begin
            insert into public.contract_weeks(
              contract_id,
              week_ending_date,
              additional_seq,
              is_adjustment,
              submission_mode_snapshot,
              status,
              created_at,
              updated_at
            )
            values (
              v_shift_contract_id,
              v_week_ending_date,
              v_next_additional_seq,
              true,
              'MANUAL'::public.submission_mode_enum,
              'SUBMITTED'::public.contract_week_status_enum,
              v_now,
              v_now
            )
            returning id into v_cw_id;

            exit;
          exception when unique_violation then
            v_cw_id := null;
          end;
        end loop;

        -- Insert correction timesheet (idempotent by uq_timesheets_correction_id_kind)
        begin
          insert into public.timesheets(
            booking_id,
            version,
            is_current,
            status,

            sheet_scope,
            submission_mode,
            line_type,
            authorised_at_server,

            occupant_key_norm,
            hospital_norm,
            ward_norm,
            job_title_norm,
            shift_label_norm,

            week_ending_date,
            contract_id,

            manual_pdf_r2_key,
            actual_schedule_json,

            qr_payload_json,
            candidate_hint_text,

            is_adjustment,
            parent_timesheet_id,
            correction_id,
            correction_kind,
            adjustment_origin,

            created_at,
            updated_at
          )
          values (
            v_booking_id,
            1,
            true,
            'RECEIVED'::public.timesheet_status_enum,

            'WEEKLY'::public.timesheet_scope_enum,
            'MANUAL'::public.submission_mode_enum,
            'HOURS'::public.timesheet_line_type_enum,
            null,

            lower(coalesce(v_candidate_tms_ref, v_candidate_display_name, v_shift_candidate_id::text)),
            lower(coalesce(v_contract_display_site, v_client_name, v_shift_client_id::text)),
            lower(coalesce(v_contract_ward_hint, 'contract')),
            lower(coalesce(v_contract_role, 'weekly')),
            v_shift_label_norm,

            v_week_ending_date,
            v_shift_contract_id,

            null,
            v_schedule,

            v_hint,
            v_hint,

            true,
            null,
            v_correction_id,
            v_kind,
            'IMPORT_CANCELLATION',

            v_now,
            v_now
          )
          returning timesheet_id into v_ts_id;

          v_correction_ts_id := v_ts_id;
        v_pair_changed := true;

        exception when unique_violation then
          select t3.timesheet_id
          into v_ts_id
          from public.timesheets t3
          where t3.correction_id = v_correction_id
            and t3.correction_kind = v_kind
          order by t3.is_current desc, t3.version desc
          limit 1
          for update;

          if v_ts_id is null then
            raise exception 'nhsp_weekly_apply_cancellations: unique_violation inserting correction timesheet but failed to find existing row (correction_id=% kind=%).',
              v_correction_id, v_kind;
          end if;

          v_correction_ts_id := v_ts_id;

          if exists (
            select 1 from public.timesheets desired_race_member
            where desired_race_member.timesheet_id=v_ts_id
              and (
                desired_race_member.actual_schedule_json is distinct from v_schedule
                or desired_race_member.parent_timesheet_id is distinct from v_latest_positive_timesheet_id
                or desired_race_member.correction_kind is distinct from v_kind
                or coalesce(desired_race_member.candidate_hint_text->>'correction_financials_policy_envelope_fingerprint','')
                     is distinct from coalesce(v_correction_financials_policy_envelope_fingerprint,'')
              )
          ) then
            if exists (
              select 1 from public.timesheets guarded_race_member
              left join public.timesheets_financials guarded_race_financial
                on guarded_race_financial.timesheet_id=guarded_race_member.timesheet_id
               and guarded_race_financial.is_current=true
              where guarded_race_member.timesheet_id=v_ts_id
                and (
                  guarded_race_member.authorised_at_server is not null
                  or guarded_race_financial.authorised_at_utc is not null
                  or guarded_race_financial.paid_at_utc is not null
                  or guarded_race_financial.locked_by_invoice_id is not null
                  or exists(select 1 from public.invoice_lines guarded_line where guarded_line.timesheet_id=guarded_race_member.timesheet_id)
                )
            ) then
              raise exception using message='CORRECTION_PAIR_LIFECYCLE_TRANSITION_REQUIRED',errcode='P0001',
                detail=jsonb_build_object('code','CORRECTION_PAIR_LIFECYCLE_TRANSITION_REQUIRED','timesheet_id',v_ts_id,'required_path','PAIR_UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE')::text;
            end if;

            update public.timesheets t4
            set
              booking_id = v_booking_id,
              is_current = true,
              status = 'RECEIVED'::public.timesheet_status_enum,
              sheet_scope = 'WEEKLY'::public.timesheet_scope_enum,
              submission_mode = 'MANUAL'::public.submission_mode_enum,
              line_type = 'HOURS'::public.timesheet_line_type_enum,
              authorised_at_server = null,
              occupant_key_norm = lower(coalesce(v_candidate_tms_ref, v_candidate_display_name, v_shift_candidate_id::text)),
              hospital_norm = lower(coalesce(v_contract_display_site, v_client_name, v_shift_client_id::text)),
              ward_norm = lower(coalesce(v_contract_ward_hint, 'contract')),
              job_title_norm = lower(coalesce(v_contract_role, 'weekly')),
              shift_label_norm = v_shift_label_norm,
              week_ending_date = v_week_ending_date,
              contract_id = v_shift_contract_id,
              manual_pdf_r2_key = null,
              actual_schedule_json = v_schedule,
              qr_payload_json = v_hint,
              candidate_hint_text = v_hint,
              is_adjustment = true,
              parent_timesheet_id = v_latest_positive_timesheet_id,
              correction_id = v_correction_id,
              correction_kind = v_kind,
              adjustment_origin = 'IMPORT_CANCELLATION',
              updated_at = v_now
            where t4.timesheet_id = v_ts_id;

            v_pair_changed := true;
          end if;
        end;

        -- Link adjustment contract_week -> timesheet
        update public.contract_weeks cwlink
        set
          timesheet_id = v_correction_ts_id,
          status = 'SUBMITTED'::public.contract_week_status_enum,
          submission_mode_snapshot = 'MANUAL'::public.submission_mode_enum,
          is_adjustment = true,
          updated_at = v_now
        where cwlink.id = v_cw_id;

      end if;


      v_reversal_ts_id := v_correction_ts_id;
      if exists (
        select 1 from public.timesheets legacy_replacement
        where legacy_replacement.correction_id=v_correction_id
          and legacy_replacement.correction_kind in ('CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
      ) then
        raise exception 'LEGACY_ZERO_HOUR_REPLACEMENT_REQUIRES_RECONCILIATION'
          using errcode='P0001',detail=jsonb_build_object('correction_id',v_correction_id)::text;
      end if;
      v_replacement_ts_id := null;
      v_correction_ts_id := v_reversal_ts_id;
      v_timesheet_ids := array_append(v_timesheet_ids,v_reversal_ts_id);
      if v_pair_changed then
        perform public.enqueue_ts_financials_priority(
          array[v_reversal_ts_id]::uuid[],
          'CONTEXT_CHANGED'::public.ts_fin_reason_enum
        );
      end if;

      -- Update truth (cancel) but do NOT recompute base TSFIN in this branch
      update public.nhsp_shifts ns3
      set
        cancelled_at_utc = v_now,
        cancelled_by_import_id = p_import_id,
        cancelled_reason = v_reason,
        timesheet_id = null
      where ns3.id = v_shift_id;

      v_cancelled_count := v_cancelled_count + 1;

      -- Retained financial history is never deleted. Existing correction
      -- members remain in the root chain and the reversal-only unit records the forward
      -- economic correction.
      v_cleanup_ts_ids := array[]::uuid[];
      v_cleanup_count := 0;

      -- User-facing audit (UNGATED): correction timesheet + contract_week + invoice history
      begin
        if v_correction_ts_id is not null then
          perform public._audit_insert(
            'timesheets',
            v_correction_ts_id::text,
            'NHSP_IMPORT_CANCELLATION_CORRECTION_CREATED',
            null,
            jsonb_build_object(
              'import_id', p_import_id::text,
              'evidence_import_id', case when v_anchor_import_id is null then null else v_anchor_import_id::text end,
              'branch', v_branch,
              'shift_id', v_shift_id::text,
              'work_date', v_shift_work_date::text,
              'external_row_key', v_shift_external_row_key,
              'ref_num', nullif(btrim(coalesce(v_shift_ref_num,'')), ''),
              'cancel_reason', v_reason,
              'invoice_id', case when v_invoice_id_detected is null then null else v_invoice_id_detected::text end,
              'invoice_no', v_invoice_number_text,
              'anchor_start_utc', v_anchor_start_utc::text,
              'anchor_end_utc', v_anchor_end_utc::text,
              'anchor_break_mins', v_anchor_break_mins,
              'anchor_mode', case when v_pos_is_invoiced is true then 'INVOICED_REPLACEMENT' else 'BASE_LOCKED' end,
              'retained_changed_hours_count', v_cleanup_count,
              'retained_timesheet_ids', to_jsonb(coalesce(v_cleanup_ts_ids, array[]::uuid[])),
              'correction_id', v_correction_id,
              'correction_kind', v_kind
            ),
            'IMPORT_CANCELLATION_CORRECTION',
            p_actor_user_id
          );
        end if;

        if v_invoice_id_detected is not null then
          perform public._inv_write_audit(
            p_actor_user_id,
            'NHSP_IMPORT_CANCELLATION_CORRECTION_CREATED',
            jsonb_build_object(
              'import_id', p_import_id::text,
              'evidence_import_id', case when v_anchor_import_id is null then null else v_anchor_import_id::text end,
              'shift_id', v_shift_id::text,
              'work_date', v_shift_work_date::text,
              'external_row_key', v_shift_external_row_key,
              'ref_num', nullif(btrim(coalesce(v_shift_ref_num,'')), ''),
              'invoice_id', v_invoice_id_detected::text,
              'invoice_no', v_invoice_number_text,
              'correction_timesheet_id', case when v_correction_ts_id is null then null else v_correction_ts_id::text end,
              'anchor_mode', case when v_pos_is_invoiced is true then 'INVOICED_REPLACEMENT' else 'BASE_LOCKED' end,
              'retained_changed_hours_count', v_cleanup_count
            ),
            'invoices',
            v_invoice_id_detected::text,
            null,
            'IMPORT_CANCELLATION_CORRECTION',
            null,
            null,
            null
          );
        end if;
      exception when others then
        null;
      end;

    end if;

    -- Debug sample (cap 30)
    if v_sample_n < 30 then
      v_sample := v_sample || jsonb_build_array(jsonb_build_object(
        'shift_id', v_shift_id::text,
        'ref_num', v_shift_ref_num,
        'present_in_file', v_present_in_file,
        'timesheet_id', case when v_timesheet_id is null then null else v_timesheet_id::text end,
        'invoice_id_detected', case when v_invoice_id_detected is null then null else v_invoice_id_detected::text end,
        'invoice_no', v_invoice_number_text,
        'invoiced_detected', v_invoiced_detected,
        'branch', v_branch,
        'correction_timesheet_id', case when v_correction_ts_id is null then null else v_correction_ts_id::text end,
        'anchor_mode', case when v_pos_is_invoiced is true then 'INVOICED_REPLACEMENT' else 'BASE_LOCKED' end,
        'retained_changed_hours_count', v_cleanup_count
      ));
      v_sample_n := v_sample_n + 1;
    end if;

  end loop;

  -- Deduplicate id arrays for output
  select coalesce(array_agg(distinct x), array[]::uuid[])
  into v_timesheet_ids
  from unnest(v_timesheet_ids) x
  where x is not null;

  select coalesce(array_agg(distinct x), array[]::uuid[])
  into v_invoice_ids
  from unnest(v_invoice_ids) x
  where x is not null;

  -- Debug audit (invoice_debug gated inside _imp_debug_audit)
  perform public._imp_debug_audit(
    p_actor_user_id,
    'NHSP_CANCEL_APPLY_DEBUG',
    jsonb_build_object(
      'import_id', p_import_id::text,
      'selected_count', jsonb_array_length(v_actions),
      'cancelled_count', v_cancelled_count,
      'file_ref_count', v_file_ref_count,
      'affected_timesheet_ids_count', coalesce(array_length(v_timesheet_ids, 1), 0),
      'affected_invoice_ids_count', coalesce(array_length(v_invoice_ids, 1), 0),
      'sample', v_sample
    ),
    'hr_imports',
    p_import_id::text,
    null,
    null,
    null,
    null
  );

  -- No credit notes / pdf jobs created by this RPC under locked policy
  v_credit_note_ids := array[]::uuid[];
  v_pdf_jobs_enqueued := 0;

  return jsonb_build_object(
    'import_id', p_import_id,
    'cancelled_count', v_cancelled_count,
    'affected_timesheet_ids', to_jsonb(v_timesheet_ids),
    'affected_invoice_ids', to_jsonb(v_invoice_ids),
    'credit_note_ids_created', to_jsonb(v_credit_note_ids),
    'invoice_pdf_jobs_enqueued', v_pdf_jobs_enqueued
  );

exception when others then
  get stacked diagnostics v_sqlstate = returned_sqlstate, v_err = message_text;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'NHSP_CANCEL_APPLY_ERROR',
      jsonb_build_object(
        'import_id', p_import_id::text,
        'last_shift_id', case when v_last_shift_id is null then null else v_last_shift_id::text end,
        'selected_count', case when jsonb_typeof(v_actions) = 'array' then jsonb_array_length(v_actions) else null end,
        'cancelled_count', v_cancelled_count,
        'file_ref_count', v_file_ref_count,
        'sqlstate', v_sqlstate,
        'error', v_err
      ),
      'hr_imports',
      p_import_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  raise;
end;
$function$;

-- nhsp_weekly_apply_transactional(uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.nhsp_weekly_apply_transactional(p_import_id uuid, p_payload jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
declare
  v_now timestamptz := now();

  -- import header
  v_import_source_system text;

  -- payload parts
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_actions_json jsonb := '[]'::jsonb;

  -- normalized selections
  v_selected_action_ids text[] := array[]::text[];
  v_selected_truth_keys text[] := array[]::text[];
  v_selected_cancel_shift_ids uuid[] := array[]::uuid[];

  -- deterministic external keys in this import (NHSP, OK rows)
  v_all_ok_external_keys text[] := array[]::text[];

  -- selected truth keys constrained to OK rows
  v_selected_truth_keys_ok text[] := array[]::text[];

  -- tick-only enforced lists
  v_force_keys_final text[] := array[]::text[];
  v_skip_keys_final text[] := array[]::text[];

  -- changed-hours partition (selected keys only)
  v_invoiced_changed_keys text[] := array[]::text[];
  v_not_invoiced_changed_keys text[] := array[]::text[];

  -- phase3 / phase1 / phase1.5
  v_phase3_result jsonb := null;
  v_changed_preflight jsonb := null;
  v_changed_timesheet_ids uuid[] := array[]::uuid[];
  v_protected_source_timesheet_ids uuid[] := array[]::uuid[];
  v_reauthorise_timesheet_ids uuid[] := array[]::uuid[];
  v_auto_authorise_timesheet_ids uuid[] := array[]::uuid[];
  v_lifecycle_items jsonb := '[]'::jsonb;
  v_unauthorise_result jsonb := null;
  v_reconciliation_action_ids text[] := array[]::text[];
  v_operation_bound_correction_action_ids text[] := array[]::text[];
  v_operation_bound_correction_keys text[] := array[]::text[];
  v_operation_bound_correction_timesheet_ids uuid[] := array[]::uuid[];
  v_general_authorise_timesheet_ids uuid[] := array[]::uuid[];
  v_reconciliation_transition jsonb := null;
  v_reconciliation_units jsonb := '[]'::jsonb;
  v_paid_unit jsonb;
  v_paid_timesheet_id uuid;
  v_paid_intent text;
  v_paid_current_count integer := 0;
  v_paid_current_tf public.timesheets_financials%rowtype;
  v_paid_preflight jsonb;
  v_paid_rollover jsonb;
  v_paid_mode text;
  v_paid_historical_id uuid;
  v_paid_shell_id uuid;
  v_paid_applied jsonb;
  v_paid_applied_timesheet_ids uuid[] := array[]::uuid[];
  v_paid_current_contract jsonb;
  v_paid_current_contract_fingerprint text;
  v_paid_current_policy_unit jsonb;
  v_paid_current_policy_count integer := 0;
  v_paid_current_policy jsonb;
  v_paid_origin_operation public.import_apply_operations%rowtype;
  v_paid_origin_contract jsonb;
  v_paid_origin_contract_fingerprint text;
  v_paid_origin_policy_unit jsonb;
  v_paid_origin_policy_count integer := 0;
  v_paid_historical_tf public.timesheets_financials%rowtype;
  v_paid_digest text;
  v_phase1_result jsonb := null;
  v_phase15_ok int := 0;
  v_phase15_updated int := 0;

  -- policy A replacement-day enforcement + cancellation reasoning
  v_selected_cancel_shift_id_set text[] := array[]::text[];

  -- cancellations
  v_cancel_actions jsonb := '[]'::jsonb;
  v_cancellations_result jsonb := null;

  -- affected timesheets
  v_affected_timesheet_ids uuid[] := array[]::uuid[];
  v_force_keys_non_invoiced text[] := array[]::text[];

  -- debug / audit
  v_sample_selected_action_ids jsonb := '[]'::jsonb;
  v_sample_force_keys jsonb := '[]'::jsonb;
  v_sample_skip_keys jsonb := '[]'::jsonb;
  v_sample_cancel_shift_ids jsonb := '[]'::jsonb;
  v_steps jsonb := '[]'::jsonb;

  v_selected_action_ids_count int := 0;
  v_selected_row_keys_count int := 0;
  v_selected_cancel_shift_ids_count int := 0;

  v_ok_keys_total int := 0;
  v_force_keys_count int := 0;
  v_skip_keys_count int := 0;

  v_invoiced_changed_keys_count int := 0;
  v_not_invoiced_changed_keys_count int := 0;

  v_cancellations_count int := 0;

  v_phase1_shifts_created int := 0;
  v_phase1_shifts_updated int := 0;

  v_phase3_created_count int := 0;
  v_phase3_updated_count int := 0;
  v_cancel_adjustment_count int := 0;
  v_correction_timesheets_created_count int := 0;

  v_should_run_phase1 boolean := false;
  v_should_run_phase15 boolean := false;
  v_should_run_phase3 boolean := false;
  v_should_run_cancellations boolean := false;

  v_review_contract jsonb := coalesce(v_payload->'review_contract','{}'::jsonb);
  v_review_selected_ids jsonb := coalesce(v_payload->'review_selected_action_ids','[]'::jsonb);
  v_review_operation_id uuid;
  v_review_guard jsonb;
  v_review_result jsonb;

  -- ENSURE BASE WEEKLY TIMESHEET + ATTACH ACTIVE SHIFTS (invariant)
  v_ensure_pairs_count int := 0;
  v_ensure_pairs_skipped_no_active int := 0;

  v_ensure_base_week_created_count int := 0;
  v_ensure_base_week_existing_count int := 0;

  v_ensure_timesheet_created_count int := 0;
  v_ensure_timesheet_reused_count int := 0;
  v_ensure_timesheet_missing_reference_count int := 0;

  v_ensure_shifts_attached_count int := 0;
  v_ensure_shifts_relinked_invalid_ts_count int := 0;
  v_ensure_remaining_active_detached_count int := 0;

  v_ensure_sample_pairs jsonb := '[]'::jsonb;
  v_ensure_sample_created_ts_ids jsonb := '[]'::jsonb;

  -- loop vars for ensure
  v_pair_contract_id uuid;
  v_pair_candidate_id uuid;
  v_pair_client_id uuid;
  v_pair_week_ending_date date;

  v_active_count int := 0;

  v_base_week_id uuid := null;
  v_base_week_ts_id uuid := null;

  v_ts_exists boolean := false;

  v_candidate_display_name text := null;
  v_candidate_tms_ref text := null;
  v_client_name text := null;
  v_contract_display_site text := null;
  v_contract_ward_hint text := null;
  v_contract_role text := null;

  v_occupant_norm text := null;
  v_hospital_norm text := null;
  v_ward_norm text := null;
  v_role_norm text := null;

  v_booking_base text := null;
  v_hash_hex text := null;
  v_booking_id text := null;
  v_shift_label_norm text := null;

  v_new_ts_id uuid := null;

  v_attached_null_count int := 0;
  v_relinked_invalid_count int := 0;

  -- shared error
  v_sqlstate text;
  v_err text;
begin
  v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','START'));

  -- ─────────────────────────────────────────────
  -- 0) Validate import exists and is NHSP
  -- ─────────────────────────────────────────────
  select upper(coalesce(hi.source_system::text, ''))
  into v_import_source_system
  from public.hr_imports hi
  where hi.id = p_import_id
  limit 1;

  if v_import_source_system is null or v_import_source_system = '' then
    raise exception 'nhsp_weekly_apply_transactional: import % not found in hr_imports.', p_import_id;
  end if;

  if v_import_source_system <> 'NHSP' then
    raise exception 'nhsp_weekly_apply_transactional: import % source_system=%; expected NHSP.', p_import_id, v_import_source_system;
  end if;

  if not exists(select 1 from public.import_review_states where import_id=p_import_id) then
    raise exception 'IMPORT_REVIEW_REQUIRED' using errcode='55000';
  end if;
  if jsonb_typeof(v_payload)<>'object' then
    raise exception 'IMPORT_REVIEW_APPLY_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(v_payload) as keys(key_name)
    where keys.key_name not in ('review_contract','review_selected_action_ids','invalidation_action_ids')) then
    raise exception 'IMPORT_REVIEW_BROWSER_AUTHORITY_REJECTED' using errcode='22023';
  end if;
  if jsonb_typeof(v_review_contract)<>'object' or jsonb_typeof(v_review_selected_ids)<>'array'
    or not(v_payload?'invalidation_action_ids') or jsonb_typeof(v_payload->'invalidation_action_ids')<>'array' then
    raise exception 'IMPORT_REVIEW_APPLY_CONTRACT_REQUIRED' using errcode='22023';
  end if;
  v_review_operation_id:=(v_review_contract->>'operation_id')::uuid;
  v_review_guard:=public.import_review_apply_guard_v1(p_import_id,(v_review_contract->>'state_version')::bigint,
    v_review_contract->>'coverage_fingerprint',v_review_contract->>'preview_fingerprint',v_review_operation_id,
    v_review_contract->>'request_hash',v_review_selected_ids,v_payload->'invalidation_action_ids',p_actor_user_id);
  if coalesce((v_review_guard->>'replay')::boolean,false) then return v_review_guard->'stored_response'; end if;
  select coalesce(jsonb_agg(to_jsonb(case when d.action_kind='APPLY_CANCELLATION' then 'CANCEL:'||d.shift_id::text else 'ROW:'||d.source_identity end) order by d.action_id),'[]'::jsonb)
    into v_actions_json
  from public.import_review_decisions d
  where d.import_id=p_import_id and d.is_current and d.selected
    and d.action_id in (select jsonb_array_elements_text(v_review_guard->'selected_action_ids'))
    and d.action_kind in ('INCLUDE_SHIFT','APPLY_AMENDMENT','APPLY_CANCELLATION');

  v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','IMPORT_OK'));

  -- ─────────────────────────────────────────────
  -- 1) Parse and normalize selection payload (ROW:/CANCEL:)
  -- ─────────────────────────────────────────────
  if jsonb_typeof(v_actions_json) <> 'array' then
    raise exception 'nhsp_weekly_apply_transactional: selected_action_ids must be a JSON array.';
  end if;

  create temporary table tmp_sel_ids(
    action_id text primary key
  ) on commit drop;

  insert into tmp_sel_ids(action_id)
  select distinct nullif(btrim(x.value), '')
  from jsonb_array_elements_text(v_actions_json) as x(value)
  where nullif(btrim(x.value), '') is not null
  on conflict do nothing;

  if exists (
    select 1
    from tmp_sel_ids tsi
    where tsi.action_id !~ '^(ROW|CANCEL):'
  ) then
    raise exception 'nhsp_weekly_apply_transactional: invalid action_id in selection (expected ROW:<external_row_key> or CANCEL:<shift_id>).';
  end if;

  select coalesce(array_agg(tsi.action_id order by tsi.action_id), array[]::text[])
  into v_selected_action_ids
  from tmp_sel_ids tsi;

  select coalesce(array_agg(distinct substring(tsi.action_id from 5) order by substring(tsi.action_id from 5)), array[]::text[])
  into v_selected_truth_keys
  from tmp_sel_ids tsi
  where tsi.action_id like 'ROW:%';

  select coalesce(array_agg(distinct (substring(tsi.action_id from 8))::uuid order by (substring(tsi.action_id from 8))::uuid), array[]::uuid[])
  into v_selected_cancel_shift_ids
  from tmp_sel_ids tsi
  where tsi.action_id like 'CANCEL:%';

  v_selected_action_ids_count := coalesce(array_length(v_selected_action_ids, 1), 0);
  v_selected_row_keys_count := coalesce(array_length(v_selected_truth_keys, 1), 0);
  v_selected_cancel_shift_ids_count := coalesce(array_length(v_selected_cancel_shift_ids, 1), 0);

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','SELECTION_PARSED',
    'selected_action_ids_count', v_selected_action_ids_count,
    'selected_row_keys_count', v_selected_row_keys_count,
    'selected_cancel_shift_ids_count', v_selected_cancel_shift_ids_count
  ));

  -- sample selected action ids (cap 40)
  select coalesce(jsonb_agg(x.action_id), '[]'::jsonb)
  into v_sample_selected_action_ids
  from (
    select s.action_id
    from unnest(coalesce(v_selected_action_ids, array[]::text[])) as s(action_id)
    order by s.action_id
    limit 40
  ) as x;

  -- ─────────────────────────────────────────────
  -- 2) Load weekly_import_phase2 for NHSP and constrain selection to OK rows
  -- ─────────────────────────────────────────────
  create temporary table tmp_p2_all on commit drop as
  select *
  from public.weekly_import_phase2(p_import_id := p_import_id, p_system_type := 'NHSP');

  create temporary table tmp_p2_ok on commit drop as
  select
    p2.hr_row_id,
    p2.external_row_key,
    p2.work_date,
    p2.week_ending_date,
    p2.candidate_id,
    p2.client_id,
    p2.contract_id,
    upper(coalesce(p2.action::text,'')) as action
  from tmp_p2_all p2
  where upper(coalesce(p2.action::text,'')) = 'OK'
    and p2.external_row_key is not null
    and p2.candidate_id is not null
    and p2.client_id is not null
    and p2.contract_id is not null
    and p2.work_date is not null
    and p2.week_ending_date is not null;

  select coalesce(array_agg(distinct p2.external_row_key order by p2.external_row_key), array[]::text[])
  into v_all_ok_external_keys
  from tmp_p2_ok p2;

  v_ok_keys_total := coalesce(array_length(v_all_ok_external_keys, 1), 0);

  -- selected truth keys must be present in OK universe
  if exists (
    select 1
    from unnest(coalesce(v_selected_truth_keys, array[]::text[])) as k(external_row_key)
    left join (select distinct p2.external_row_key from tmp_p2_ok p2) as okk
      on okk.external_row_key = k.external_row_key
    where okk.external_row_key is null
  ) then
    raise exception 'nhsp_weekly_apply_transactional: selection includes ROW:<external_row_key> that is not an OK/resolved NHSP row (resolve mappings first).';
  end if;

  select coalesce(array_agg(distinct k.external_row_key order by k.external_row_key), array[]::text[])
  into v_selected_truth_keys_ok
  from (
    select distinct k.external_row_key
    from unnest(coalesce(v_selected_truth_keys, array[]::text[])) as k(external_row_key)
    join (select distinct p2.external_row_key from tmp_p2_ok p2) as okk
      on okk.external_row_key = k.external_row_key
  ) as k;

  -- Tick = PROCEED semantics
  v_force_keys_final := coalesce(v_selected_truth_keys_ok, array[]::text[]);

  select coalesce(array_agg(x.external_row_key order by x.external_row_key), array[]::text[])
  into v_skip_keys_final
  from (
    select distinct okk.external_row_key
    from unnest(coalesce(v_all_ok_external_keys, array[]::text[])) as okk(external_row_key)
    left join unnest(coalesce(v_force_keys_final, array[]::text[])) as fk(external_row_key)
      on fk.external_row_key = okk.external_row_key
    where fk.external_row_key is null
  ) as x;

  v_force_keys_count := coalesce(array_length(v_force_keys_final, 1), 0);
  v_skip_keys_count := coalesce(array_length(v_skip_keys_final, 1), 0);
  v_cancellations_count := coalesce(array_length(v_selected_cancel_shift_ids, 1), 0);

  -- Import-authoritative NHSP shifts and calculated expenses must never share
  -- a timesheet.  Check both an existing imported shift and the base
  -- contract-week timesheet that a new row would reuse, before any source or
  -- financial mutation begins.
  if exists (
    select 1
    from (
      select cw.timesheet_id
      from tmp_p2_ok p2
      join public.contract_weeks cw
        on cw.contract_id=p2.contract_id
       and cw.week_ending_date=p2.week_ending_date
       and cw.is_adjustment=false
       and coalesce(cw.additional_seq,0)=0
      where p2.external_row_key=any(coalesce(v_force_keys_final,array[]::text[]))
        and cw.timesheet_id is not null
        and not exists (
          select 1
          from public.nhsp_shifts existing_import_shift
          where existing_import_shift.source_system='NHSP'::public.hr_source_enum
            and existing_import_shift.external_row_key=p2.external_row_key
            and existing_import_shift.cancelled_at_utc is null
        )
      union
      select ns.timesheet_id
      from public.nhsp_shifts ns
      where ns.source_system='NHSP'::public.hr_source_enum
        and ns.timesheet_id is not null
        and (
          ns.external_row_key=any(coalesce(v_force_keys_final,array[]::text[]))
          or ns.id=any(coalesce(v_selected_cancel_shift_ids,array[]::uuid[]))
        )
    ) expense_target
    where public._import_review_timesheet_has_calculated_expenses_core_v1(expense_target.timesheet_id)
  ) then
    raise exception using
      message='IMPORT_AUTHORITATIVE_EXPENSE_SEPARATION_REQUIRED',
      errcode='P0001',
      detail=jsonb_build_object(
        'code','IMPORT_AUTHORITATIVE_EXPENSE_SEPARATION_REQUIRED',
        'message','Timesheet occupied by expenses. Remove the expenses from this timesheet, save or recalculate it, then choose Recheck. Expenses must be invoiced on a separate timesheet for import-authoritative work; no import mutation was applied.'
      )::text;
  end if;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','PHASE2_OK_LOADED',
    'ok_keys_total', v_ok_keys_total,
    'force_keys_count', v_force_keys_count,
    'skip_keys_count', v_skip_keys_count,
    'cancellations_count', v_cancellations_count
  ));

  -- samples (cap 40 each)
  select coalesce(jsonb_agg(x.k), '[]'::jsonb)
  into v_sample_force_keys
  from (
    select k as k
    from unnest(coalesce(v_force_keys_final, array[]::text[])) as k
    order by k
    limit 40
  ) as x;

  select coalesce(jsonb_agg(x.k), '[]'::jsonb)
  into v_sample_skip_keys
  from (
    select k as k
    from unnest(coalesce(v_skip_keys_final, array[]::text[])) as k
    order by k
    limit 40
  ) as x;

  select coalesce(jsonb_agg(y.s), '[]'::jsonb)
  into v_sample_cancel_shift_ids
  from (
    select s::text as s
    from unnest(coalesce(v_selected_cancel_shift_ids, array[]::uuid[])) as s
    order by s::text
    limit 40
  ) as y;

  -- ─────────────────────────────────────────────
  -- ✅ FIX: No-op apply guard
  -- ─────────────────────────────────────────────
  v_should_run_phase1 := (v_force_keys_count > 0);
  v_should_run_phase15 := v_should_run_phase1;
  v_should_run_cancellations := (v_cancellations_count > 0);

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','NOOP_GUARD_EVAL',
    'should_run_phase1', v_should_run_phase1,
    'should_run_phase15', v_should_run_phase15,
    'should_run_cancellations', v_should_run_cancellations,
    'reason',
      case
        when (v_should_run_phase1 is false and v_should_run_cancellations is false)
          then 'NO_SELECTION_NO_AUTONEW_NO_CANCELLATION => SKIP_TRUTH_MUTATION'
        when (v_should_run_phase1 is true and v_should_run_cancellations is false)
          then 'HAS_SELECTED_ROWS'
        when (v_should_run_phase1 is false and v_should_run_cancellations is true)
          then 'HAS_SELECTED_CANCELLATIONS'
        else 'HAS_SELECTED_ROWS_AND_CANCELLATIONS'
      end
  ));

  if (v_should_run_phase1 is false and v_should_run_cancellations is false) then
    update public.hr_imports hi_noop
    set import_scope = 'NHSP'
    where hi_noop.id = p_import_id;

    v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','IMPORT_BATCH_APPLIED_NOOP'));

    perform public._imp_debug_audit(
      p_actor_user_id,
      'NHSP_WEEKLY_APPLY_DEBUG',
      jsonb_build_object(
        'import_id', p_import_id::text,
        'steps', v_steps,

        'selected_action_ids_count', v_selected_action_ids_count,
        'selected_row_keys_count', v_selected_row_keys_count,
        'selected_cancel_shift_ids_count', v_selected_cancel_shift_ids_count,

        'selected_action_ids_sample', v_sample_selected_action_ids,

        'ok_keys_total', v_ok_keys_total,
        'force_keys_count', v_force_keys_count,
        'skip_keys_count', v_skip_keys_count,

        'phase1_called', false,
        'phase1_force_keys_sample', v_sample_force_keys,
        'phase1_skip_keys_sample', v_sample_skip_keys,

        'cancellations_called', false,
        'sample_cancel_shift_ids', v_sample_cancel_shift_ids,

        'invoiced_changed_keys_count', 0,
        'not_invoiced_changed_keys_count', 0,
        'phase3_created_count', 0,
        'phase3_updated_count', 0,
        'cancel_adjustment_count', 0,
        'correction_timesheets_created_count', 0,
        'affected_timesheet_ids_count', 0
      ),
      'hr_imports',
      p_import_id::text,
      null,
      null,
      null,
      null
    );

    v_review_result:=jsonb_build_object(
      'import_id', p_import_id,
      'mode_b', jsonb_build_object(
        'selected_truth_keys', to_jsonb(array[]::text[]),
        'force_overwrite_external_row_keys', to_jsonb(array[]::text[]),
        'skip_external_row_keys', to_jsonb(coalesce(v_all_ok_external_keys, array[]::text[])),
        'phase3', null,
        'phase1', null,
        'phase15', jsonb_build_object('ok_rows', 0, 'shift_updated_rows', 0),
        'cancellations', null
      ),
      'affected_timesheet_ids', to_jsonb(array[]::uuid[]),
      'post_commit_email_action_ids','[]'::jsonb,
      'review_operation_id',v_review_operation_id
    );
    perform public._import_review_apply_complete_core_v1(p_import_id,v_review_operation_id,p_actor_user_id,v_review_result,false);
    return v_review_result;
  end if;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','NOOP_GUARD_PASSED'));

  -- ─────────────────────────────────────────────
  -- 3) Snapshot changed-hours rows for selected keys BEFORE any truth mutation
  -- ─────────────────────────────────────────────
  create temporary table tmp_changed_sel on commit drop as
  select
    ch.external_row_key,
    ch.timesheet_id,
    ch.is_paid,
    ch.is_invoiced
  from public.weekly_import_changed_hours_phase3(p_import_id := p_import_id, p_system_type := 'NHSP') as ch
  where ch.external_row_key = any(coalesce(v_force_keys_final, array[]::text[]));

  if to_regclass('pg_temp.import_review_reconciliation_units_v1') is not null then
    if exists(select 1 from pg_temp.import_review_reconciliation_units_v1 u
      where u.unit_json->>'source_system'<>'NHSP'
         or u.unit_json->>'schema_version'<>'IMPORT_AUTHORITATIVE_RECONCILIATION_V1'
         or u.route not in ('AMEND_SOURCE','AMEND_PAID_UNINVOICED_SOURCE','AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT')) then
      raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
    end if;
    select coalesce(array_agg(u.action_id order by u.action_id),array[]::text[]),
      coalesce(array_agg(u.action_id order by u.action_id) filter(where u.route in ('AMEND_PAID_UNINVOICED_SOURCE','AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT')),array[]::text[]),
      coalesce(array_agg(u.source_identity order by u.source_identity) filter(where u.route in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT')),array[]::text[])
    into v_reconciliation_action_ids,v_operation_bound_correction_action_ids,v_operation_bound_correction_keys
    from pg_temp.import_review_reconciliation_units_v1 u;
  end if;

  select coalesce(array_agg(cs.external_row_key order by cs.external_row_key), array[]::text[])
  into v_invoiced_changed_keys
  from tmp_changed_sel cs
  where cs.is_invoiced is true;

  select coalesce(array_agg(cs.external_row_key order by cs.external_row_key), array[]::text[])
  into v_not_invoiced_changed_keys
  from tmp_changed_sel cs
  where cs.is_invoiced is false;

  if cardinality(v_reconciliation_action_ids)>0 then
    select coalesce(array_agg(u.source_identity order by u.source_identity)
      filter(where u.route in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT')),array[]::text[]),
      coalesce(array_agg(u.source_identity order by u.source_identity)
      filter(where u.route in ('AMEND_SOURCE','AMEND_PAID_UNINVOICED_SOURCE')),array[]::text[])
    into v_invoiced_changed_keys,v_not_invoiced_changed_keys
    from pg_temp.import_review_reconciliation_units_v1 u;
    if cardinality(v_operation_bound_correction_action_ids)>0 then
      v_reconciliation_transition:=public.import_review_correction_generation_transition_v1(
        p_import_id,v_review_operation_id,v_review_contract->>'request_hash','PREPARE',p_actor_user_id,
        v_operation_bound_correction_action_ids,v_now);
    end if;
  end if;

  select coalesce(array_agg(distinct protected.timesheet_id order by protected.timesheet_id),array[]::uuid[])
  into v_protected_source_timesheet_ids
  from (
    select cs.timesheet_id
    from tmp_changed_sel cs
    where cs.timesheet_id is not null
      and cs.is_invoiced is true
    union all
    -- A financial-position-only action may have no legacy changed-hours row.
    -- Its reviewed reconciliation unit is then the durable authority proving
    -- that the ordinary source is protected history and only the mutable
    -- correction members may enter the post-commit TSFIN target set.
    select nullif(u.unit_json->>'source_timesheet_id','')::uuid
    from pg_temp.import_review_reconciliation_units_v1 u
    where u.route in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT')
      and nullif(u.unit_json->>'source_timesheet_id','') is not null
  ) protected
  where protected.timesheet_id is not null;

  v_invoiced_changed_keys_count := coalesce(array_length(v_invoiced_changed_keys, 1), 0);
  v_not_invoiced_changed_keys_count := coalesce(array_length(v_not_invoiced_changed_keys, 1), 0);

  select coalesce(array_agg(distinct cs.timesheet_id order by cs.timesheet_id), array[]::uuid[])
    into v_changed_timesheet_ids
  from tmp_changed_sel cs
  where cs.timesheet_id is not null;

  if coalesce(array_length(v_changed_timesheet_ids, 1), 0) > 0 then
    select public.import_timesheet_financial_preflight_v1(
      p_timesheet_ids := v_changed_timesheet_ids,
      p_action := 'IMPORT_CHANGED_HOURS',
      p_actor_user_id := p_actor_user_id,
      p_expected_state_json := '{}'::jsonb,
      p_lock_rows := true,
      p_max_scope := 100
    ) into v_changed_preflight;

    if coalesce((v_changed_preflight->>'allowed')::boolean, false) is not true then
      raise exception using message='IMPORT_FINANCIAL_PREFLIGHT_BLOCKED', errcode='P0001', detail=v_changed_preflight::text;
    end if;

  end if;

  -- Preserve the lifecycle state of authorised, mutable source timesheets.
  -- The source transaction performs the canonical unauthorise step before
  -- changing truth.  The Worker reauthorises exactly this persisted set only
  -- after its bounded TSFIN follow-up has completed successfully.
  select coalesce(array_agg(distinct lifecycle_scope.timesheet_id order by lifecycle_scope.timesheet_id),array[]::uuid[])
  into v_reauthorise_timesheet_ids
  from (
    select cs.timesheet_id
    from tmp_changed_sel cs
    join public.timesheets ts on ts.timesheet_id=cs.timesheet_id and ts.is_current=true
    left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
    left join public.contract_weeks cw on cw.timesheet_id=ts.timesheet_id
    where cs.timesheet_id is not null
      and not (cs.external_row_key=any(coalesce(v_operation_bound_correction_keys,array[]::text[])))
      and cs.is_invoiced is false
      and (cs.is_paid is false or exists(select 1 from pg_temp.import_review_reconciliation_units_v1 paid_unit
        where paid_unit.source_identity=cs.external_row_key
          and paid_unit.route='AMEND_PAID_UNINVOICED_SOURCE'
          and paid_unit.unit_json->>'intended_authorisation_action'='REAUTHORISE'))
      and (ts.authorised_at_server is not null or tf.authorised_at_utc is not null
        or cw.status='AUTHORISED'::public.contract_week_status_enum)
    union
    -- A protected source timesheet can already have a later, still-mutable
    -- correction pair. Phase 3 deliberately amends that pair's replacement
    -- in place. Put its currently authorised replacement through the same
    -- canonical lifecycle; the bulk RPC expands it to the complete pair.
    select existing_replacement.timesheet_id
    from tmp_changed_sel cs
    cross join lateral (
      select ns_existing.id
      from public.nhsp_shifts ns_existing
      where ns_existing.source_system='NHSP'::public.hr_source_enum
        and ns_existing.external_row_key=cs.external_row_key
        and ns_existing.cancelled_at_utc is null
      order by ns_existing.updated_at desc nulls last,ns_existing.created_at desc nulls last
      limit 1
    ) source_shift
    cross join lateral (
      select tpos.timesheet_id
      from public.timesheets tpos
      where tpos.is_adjustment is true
        and tpos.is_current is true
        and tpos.correction_kind='CHANGED_HOURS_REPLACEMENT'
        and jsonb_typeof(tpos.actual_schedule_json)='array'
        and tpos.actual_schedule_json @> jsonb_build_array(jsonb_build_object(
          'shift_id',source_shift.id::text,
          'external_row_key',cs.external_row_key
        ))
      order by tpos.updated_at desc nulls last,tpos.created_at desc nulls last
      limit 1
    ) existing_replacement
    join public.timesheets pair_pos
      on pair_pos.timesheet_id=existing_replacement.timesheet_id and pair_pos.is_current=true
    left join public.timesheets_financials pair_tf
      on pair_tf.timesheet_id=pair_pos.timesheet_id and pair_tf.is_current=true
    left join public.contract_weeks pair_cw on pair_cw.timesheet_id=pair_pos.timesheet_id
    where cs.is_invoiced is true
      and not (cs.external_row_key=any(coalesce(v_operation_bound_correction_keys,array[]::text[])))
      and coalesce((public._import_review_timesheet_protection_core_v1(existing_replacement.timesheet_id)->>'paid')::boolean,false)=false
      and coalesce((public._import_review_timesheet_protection_core_v1(existing_replacement.timesheet_id)->>'invoice_locked')::boolean,false)=false
      and (pair_pos.authorised_at_server is not null or pair_tf.authorised_at_utc is not null
        or pair_cw.status='AUTHORISED'::public.contract_week_status_enum)
    union
    select ns.timesheet_id
    from public.nhsp_shifts ns
    join public.timesheets ts on ts.timesheet_id=ns.timesheet_id and ts.is_current=true
    left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
    left join public.contract_weeks cw on cw.timesheet_id=ts.timesheet_id
    where ns.id=any(coalesce(v_selected_cancel_shift_ids,array[]::uuid[]))
      and ns.timesheet_id is not null
      and coalesce((public._import_review_timesheet_protection_core_v1(ns.timesheet_id)->>'paid')::boolean,false)=false
      and coalesce((public._import_review_timesheet_protection_core_v1(ns.timesheet_id)->>'invoice_locked')::boolean,false)=false
      and (ts.authorised_at_server is not null or tf.authorised_at_utc is not null
        or cw.status='AUTHORISED'::public.contract_week_status_enum)
  ) lifecycle_scope;

  if cardinality(v_reauthorise_timesheet_ids)>100 then
    raise exception 'IMPORT_REVIEW_REAUTHORISE_SCOPE_TOO_LARGE' using errcode='54000';
  end if;
  if cardinality(v_reauthorise_timesheet_ids)>0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'timesheet_id',target_id::text,
      'expected_timesheet_id',target_id::text
    ) order by target_id),'[]'::jsonb)
    into v_lifecycle_items
    from unnest(v_reauthorise_timesheet_ids) as lifecycle_target(target_id);

    select public.timesheet_unauthorise_bulk_atomic(v_lifecycle_items,p_actor_user_id,v_now)
    into v_unauthorise_result;
    if coalesce((v_unauthorise_result->>'ok')::boolean,false) is not true
      or coalesce((v_unauthorise_result->>'all_success')::boolean,false) is not true then
      raise exception using message='IMPORT_REVIEW_CANONICAL_UNAUTHORISE_FAILED',errcode='P0001',
        detail=jsonb_build_object(
          'code','IMPORT_REVIEW_CANONICAL_UNAUTHORISE_FAILED',
          'timesheet_ids',to_jsonb(v_reauthorise_timesheet_ids),
          'failure_count',coalesce((v_unauthorise_result->>'failure_count')::int,cardinality(v_reauthorise_timesheet_ids))
        )::text;
    end if;
    v_steps:=v_steps||jsonb_build_array(jsonb_build_object(
      'step','CANONICAL_UNAUTHORISE_COMPLETE',
      'reauthorise_timesheet_count',cardinality(v_reauthorise_timesheet_ids)
    ));
  end if;

  -- Execute the reviewed ordinary paid-but-uninvoiced route before source
  -- truth is amended. Paid status alone never routes a source through phase 3.
  for v_paid_unit in
    select u.unit_json from pg_temp.import_review_reconciliation_units_v1 u
    where u.route='AMEND_PAID_UNINVOICED_SOURCE'
    order by u.source_timesheet_id
  loop
    v_paid_timesheet_id:=nullif(v_paid_unit->>'source_timesheet_id','')::uuid;
    v_paid_intent:=v_paid_unit->>'intended_authorisation_action';
    if v_paid_timesheet_id is null
       or v_paid_intent not in ('REAUTHORISE','AUTHORISE','LEAVE_UNAUTHORISED') then
      raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
    end if;

    select operation_row.response_json#>'{correction_operation_contract}'
    into v_paid_current_contract from public.import_apply_operations operation_row
    where operation_row.id=v_review_operation_id;
    v_paid_current_contract_fingerprint:=encode(extensions.digest(convert_to(
      (v_paid_current_contract-'operation_contract_fingerprint')::text,'UTF8'),'sha256'),'hex');
    if jsonb_typeof(v_paid_current_contract)<>'object'
       or v_paid_current_contract->>'operation_contract_fingerprint' is distinct from v_paid_current_contract_fingerprint then
      raise exception 'PAID_TSFIN_ROLLOVER_ORDINARY_SOURCE_POLICY_INVALID' using errcode='P0001';
    end if;
    select count(*)::integer,min(policy_unit::text)::jsonb
    into v_paid_current_policy_count,v_paid_current_policy_unit
    from jsonb_array_elements(coalesce(v_paid_current_contract->'correction_units','[]'::jsonb)) policy_unit
    where policy_unit->>'action_id'=v_paid_unit->>'action_id'
      and policy_unit->>'root_timesheet_id'=v_paid_timesheet_id::text
      and policy_unit->>'source_row_key'=v_paid_unit->>'source_identity';
    if v_paid_current_policy_count<>1
       or jsonb_typeof(v_paid_current_policy_unit->'policy_envelope')<>'object' then
      raise exception 'PAID_TSFIN_ROLLOVER_ORDINARY_SOURCE_POLICY_INVALID' using errcode='P0001';
    end if;
    v_paid_current_policy:=v_paid_current_policy_unit->'policy_envelope';

    perform 1 from public.timesheets exact_source
    where exact_source.timesheet_id=v_paid_timesheet_id
      and exact_source.is_current and exact_source.archived_at_utc is null for update;
    if not found then
      raise exception 'IMPORT_REVIEW_SELECTED_ACTION_STALE' using errcode='40001';
    end if;
    perform 1 from public.timesheets_financials current_lock
    where current_lock.timesheet_id=v_paid_timesheet_id and current_lock.is_current
    order by current_lock.id for update;
    select count(*)::integer into v_paid_current_count from public.timesheets_financials current_tf
    where current_tf.timesheet_id=v_paid_timesheet_id and current_tf.is_current;
    if v_paid_current_count<>1 then
      raise exception 'IMPORT_REVIEW_SELECTED_ACTION_STALE' using errcode='40001';
    end if;
    select current_tf.* into v_paid_current_tf from public.timesheets_financials current_tf
    where current_tf.timesheet_id=v_paid_timesheet_id and current_tf.is_current;

    if v_paid_current_tf.paid_at_utc is not null then
      v_paid_preflight:=public.import_timesheet_financial_preflight_v1(
        array[v_paid_timesheet_id]::uuid[],'PAID_UNINVOICED_ROLLOVER',p_actor_user_id,
        '{}'::jsonb,false,100);
      if coalesce((v_paid_preflight->>'allowed')::boolean,false) is not true
         or v_paid_preflight->>'required_path' is distinct from 'PAID_UNINVOICED_ROLLOVER'
         or coalesce((v_paid_preflight->>'input_count')::integer,0)<>1
         or coalesce((v_paid_preflight->>'member_count')::integer,0)<>1
         or coalesce((v_paid_preflight->>'paid_count')::integer,0)<>1
         or coalesce((v_paid_preflight->>'invoice_lined_count')::integer,0)<>0
         or coalesce((v_paid_preflight->>'blocking_batch_count')::integer,0)<>0
         or coalesce((v_paid_preflight->>'stale_tsfin_count')::integer,0)<>0
         or jsonb_array_length(coalesce(v_paid_preflight->'errors','[]'::jsonb))<>0 then
        raise exception 'PAID_TSFIN_ROLLOVER_ORDINARY_SOURCE_PREFLIGHT_INVALID' using errcode='P0001';
      end if;
      v_paid_rollover:=public.timesheet_paid_uninvoiced_rollover_v1(
        v_paid_timesheet_id,p_actor_user_id,v_review_operation_id,v_paid_current_tf.id,
        v_paid_preflight->>'preflight_fingerprint',v_now);
      v_paid_historical_id:=nullif(v_paid_rollover->>'historical_paid_tsfin_id','')::uuid;
      v_paid_shell_id:=nullif(v_paid_rollover->>'new_current_tsfin_id','')::uuid;
      v_paid_mode:='CREATED_CURRENT_OPERATION_SHELL';
      if coalesce((v_paid_rollover->>'ok')::boolean,false) is not true
         or v_paid_historical_id is distinct from v_paid_current_tf.id
         or v_paid_shell_id is null
         or not exists(select 1 from public.timesheets_financials shell
           where shell.id=v_paid_shell_id and shell.timesheet_id=v_paid_timesheet_id and shell.is_current
             and shell.paid_at_utc is null and shell.processing_status='PENDING_AUTH'::public.ts_fin_processing_status_enum
             and shell.stale_reason='IMPORT_PAID_TSFIN_ROLLOVER_PENDING_CALCULATION'
             and coalesce((shell.policy_snapshot_json->>'requires_frozen_correction_policy')::boolean,false)
             and shell.policy_snapshot_json->>'import_apply_operation_id'=v_review_operation_id::text
             and shell.policy_snapshot_json->>'rollover_source_tsfin_id'=v_paid_historical_id::text)
         or (select count(*) from public.timesheets_financials shell
           where shell.timesheet_id=v_paid_timesheet_id and shell.is_current)<>1 then
        raise exception 'PAID_TSFIN_ROLLOVER_ORDINARY_SOURCE_PREFLIGHT_INVALID' using errcode='P0001';
      end if;
    else
      -- Reuse only a settled shell from a completed prior operation whose own
      -- frozen contract and paid lineage prove it, then compare only stable
      -- policy facts with this operation.
      if v_paid_current_tf.locked_by_invoice_id is not null
         or exists(select 1 from public.invoice_lines il where il.timesheet_id=v_paid_timesheet_id)
         or v_paid_current_tf.authorised_at_utc is not null
         or v_paid_current_tf.processing_status<>'PENDING_AUTH'::public.ts_fin_processing_status_enum
         or coalesce(v_paid_current_tf.is_stale,false)
         or v_paid_current_tf.stale_reason is not null
         or not coalesce((v_paid_current_tf.policy_snapshot_json->>'requires_frozen_correction_policy')::boolean,false)
         or coalesce(v_paid_current_tf.policy_snapshot_json->>'import_apply_operation_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or coalesce(v_paid_current_tf.policy_snapshot_json->>'rollover_source_tsfin_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or nullif(v_paid_current_tf.policy_snapshot_json->>'rollover_source_paid_digest','') is null then
        raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_INVALID' using errcode='P0001';
      end if;
      select origin.* into v_paid_origin_operation from public.import_apply_operations origin
      where origin.id=(v_paid_current_tf.policy_snapshot_json->>'import_apply_operation_id')::uuid for update;
      if not found or v_paid_origin_operation.state<>'COMPLETE' then
        raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_ORIGIN_INCOMPLETE' using errcode='P0001';
      end if;
      v_paid_origin_contract:=v_paid_origin_operation.response_json#>'{correction_operation_contract}';
      v_paid_origin_contract_fingerprint:=encode(extensions.digest(convert_to(
        (v_paid_origin_contract-'operation_contract_fingerprint')::text,'UTF8'),'sha256'),'hex');
      if jsonb_typeof(v_paid_origin_contract)<>'object'
         or v_paid_origin_contract->>'operation_contract_fingerprint' is distinct from v_paid_origin_contract_fingerprint then
        raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_INVALID' using errcode='P0001';
      end if;
      select count(*)::integer,min(origin_unit::text)::jsonb
      into v_paid_origin_policy_count,v_paid_origin_policy_unit
      from jsonb_array_elements(coalesce(v_paid_origin_contract->'correction_units','[]'::jsonb)) origin_unit
      where origin_unit->>'root_timesheet_id'=v_paid_timesheet_id::text
        and origin_unit->>'source_row_key'=v_paid_unit->>'source_identity';
      if v_paid_origin_policy_count<>1
         or v_paid_origin_policy_unit->'policy_envelope' is distinct from
           v_paid_current_tf.policy_snapshot_json->'correction_financials_policy_envelope'
         or v_paid_origin_policy_unit->>'policy_envelope_fingerprint' is distinct from
           v_paid_current_tf.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint' then
        raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_INVALID' using errcode='P0001';
      end if;
      select historical.* into v_paid_historical_tf from public.timesheets_financials historical
      where historical.id=(v_paid_current_tf.policy_snapshot_json->>'rollover_source_tsfin_id')::uuid
        and historical.timesheet_id=v_paid_timesheet_id and not historical.is_current
        and historical.paid_at_utc is not null and historical.locked_by_invoice_id is null;
      if not found then raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_INVALID' using errcode='P0001'; end if;
      v_paid_digest:=encode(extensions.digest(convert_to(jsonb_build_object(
        'id',v_paid_historical_tf.id::text,'timesheet_id',v_paid_historical_tf.timesheet_id::text,
        'timesheet_version',v_paid_historical_tf.timesheet_version,'paid_at_utc',v_paid_historical_tf.paid_at_utc,
        'paid_by_user_id',case when v_paid_historical_tf.paid_by_user_id is null then null else v_paid_historical_tf.paid_by_user_id::text end,
        'payment_reference',v_paid_historical_tf.payment_reference,'total_hours',v_paid_historical_tf.total_hours,
        'total_pay_ex_vat',v_paid_historical_tf.total_pay_ex_vat,'total_charge_ex_vat',v_paid_historical_tf.total_charge_ex_vat,
        'pay_vat_rate_pct_snapshot',v_paid_historical_tf.pay_vat_rate_pct_snapshot,
        'pay_vat_amount_snapshot',v_paid_historical_tf.pay_vat_amount_snapshot,
        'pay_total_inc_vat_snapshot',v_paid_historical_tf.pay_total_inc_vat_snapshot,
        'policy_snapshot_json',v_paid_historical_tf.policy_snapshot_json,'rate_source_refs_json',v_paid_historical_tf.rate_source_refs_json,
        'actual_schedule_json',v_paid_historical_tf.actual_schedule_json)::text,'UTF8'),'sha256'),'hex');
      if v_paid_digest is distinct from v_paid_current_tf.policy_snapshot_json->>'rollover_source_paid_digest' then
        raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_INVALID' using errcode='P0001';
      end if;
      if v_paid_origin_contract->>'source_system' is distinct from v_paid_current_contract->>'source_system'
         or v_paid_origin_policy_unit#>>'{policy_envelope,classification,source_shift_id}' is distinct from v_paid_current_policy#>>'{classification,source_shift_id}'
         or v_paid_origin_policy_unit#>>'{policy_envelope,classification,source_row_key}' is distinct from v_paid_current_policy#>>'{classification,source_row_key}'
         or v_paid_origin_policy_unit#>>'{policy_envelope,root_timesheet_id}' is distinct from v_paid_current_policy->>'root_timesheet_id'
         or v_paid_origin_policy_unit#>>'{policy_envelope,replacement,leg_fingerprint}' is distinct from v_paid_current_policy#>>'{replacement,leg_fingerprint}'
         or v_paid_origin_policy_unit#>>'{policy_envelope,replacement,tsfin_policy,tsfin_policy_fingerprint}' is distinct from v_paid_current_policy#>>'{replacement,tsfin_policy,tsfin_policy_fingerprint}'
         or v_paid_origin_policy_unit#>>'{policy_envelope,replacement,invoice_policy,invoice_policy_fingerprint}' is distinct from v_paid_current_policy#>>'{replacement,invoice_policy,invoice_policy_fingerprint}'
         or v_paid_origin_policy_unit#>>'{policy_envelope,replacement,invoice_policy,invoice_stream}' is distinct from v_paid_current_policy#>>'{replacement,invoice_policy,invoice_stream}' then
        raise exception 'IMPORT_REVIEW_PAID_ROLLOVER_SHELL_POLICY_CHANGED' using errcode='P0001';
      end if;
      v_paid_historical_id:=v_paid_historical_tf.id;
      v_paid_shell_id:=v_paid_current_tf.id;
      v_paid_mode:='REUSED_COMPLETED_OPERATION_SHELL';
    end if;

    v_paid_applied:=jsonb_build_object(
      'applied_timesheet_id',v_paid_timesheet_id,'rollover_mode',v_paid_mode,
      'historical_paid_tsfin_id',v_paid_historical_id,'current_shell_tsfin_id',v_paid_shell_id,
      'intended_authorisation_action',v_paid_intent,
      'reviewed_unit_fingerprint',v_paid_unit->>'unit_fingerprint',
      'reconciliation_fingerprint',v_paid_unit->>'reconciliation_fingerprint');
    update pg_temp.import_review_reconciliation_units_v1 applied_unit
    set unit_json=applied_unit.unit_json||v_paid_applied||jsonb_build_object(
      'applied_result_fingerprint',encode(extensions.digest(convert_to(v_paid_applied::text,'UTF8'),'sha256'),'hex'))
    where applied_unit.action_id=v_paid_unit->>'action_id';
    v_paid_applied_timesheet_ids:=array_append(v_paid_applied_timesheet_ids,v_paid_timesheet_id);
  end loop;

  v_should_run_phase3 := (v_invoiced_changed_keys_count > 0);

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','CHANGED_HOURS_PARTITIONED',
    'invoiced_changed_keys_count', v_invoiced_changed_keys_count,
    'not_invoiced_changed_keys_count', v_not_invoiced_changed_keys_count,
    'phase3_should_run', v_should_run_phase3
  ));

  -- ─────────────────────────────────────────────
  -- 4) Policy A replacement-day enforcement (NHSP)
  -- ─────────────────────────────────────────────
  create temporary table tmp_selected_replacement_keys(
    candidate_id uuid,
    client_id uuid,
    old_work_date date,
    replacement_day_key text
  ) on commit drop;

  if array_length(v_force_keys_final, 1) is not null then
    create temporary table tmp_sel_truth_p2 on commit drop as
    select
      p2.external_row_key,
      p2.candidate_id,
      p2.client_id,
      p2.work_date as import_work_date
    from tmp_p2_ok p2
    where p2.external_row_key = any(v_force_keys_final);

    create temporary table tmp_existing_by_key on commit drop as
    select distinct on (ns.external_row_key)
      ns.external_row_key,
      ns.id as shift_id,
      ns.candidate_id as candidate_id,
      ns.client_id as client_id,
      ns.work_date as old_work_date
    from public.nhsp_shifts ns
    where ns.source_system = 'NHSP'::public.hr_source_enum
      and ns.cancelled_at_utc is null
      and ns.external_row_key = any(v_force_keys_final)
      and ns.work_date is not null
    order by ns.external_row_key, ns.updated_at desc nulls last, ns.created_at desc nulls last;

    insert into tmp_selected_replacement_keys(candidate_id, client_id, old_work_date, replacement_day_key)
    select distinct
      (coalesce(ex.candidate_id, st.candidate_id))::uuid as candidate_id,
      (coalesce(ex.client_id, st.client_id))::uuid as client_id,
      ex.old_work_date as old_work_date,
      ((coalesce(ex.candidate_id, st.candidate_id))::text || '|' ||
       (coalesce(ex.client_id, st.client_id))::text || '|' ||
       (ex.old_work_date)::text) as replacement_day_key
    from tmp_sel_truth_p2 st
    join tmp_existing_by_key ex
      on ex.external_row_key = st.external_row_key
    where ex.old_work_date is not null
      and st.import_work_date is not null
      and ex.old_work_date <> st.import_work_date;

    select coalesce(array_agg(x::text), array[]::text[])
    into v_selected_cancel_shift_id_set
    from unnest(coalesce(v_selected_cancel_shift_ids, array[]::uuid[])) as x;

    if exists (select 1 from tmp_selected_replacement_keys) then
      create temporary table tmp_required_cancel_ids on commit drop as
      select distinct
        rk.replacement_day_key,
        ns2.id as shift_id
      from tmp_selected_replacement_keys rk
      join public.nhsp_shifts ns2
        on ns2.source_system = 'NHSP'::public.hr_source_enum
       and ns2.cancelled_at_utc is null
       and ns2.candidate_id = rk.candidate_id
       and ns2.client_id = rk.client_id
       and ns2.work_date = rk.old_work_date;

      if exists (
        select 1
        from tmp_required_cancel_ids rc
        left join unnest(v_selected_cancel_shift_id_set) as sel(shift_id_text)
          on sel.shift_id_text = rc.shift_id::text
        where sel.shift_id_text is null
      ) then
        raise exception 'nhsp_weekly_apply_transactional: Policy A violation (replacement-day selected without selecting all required cancellations).';
      end if;
    end if;
  end if;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','POLICY_A_OK'));

  -- ─────────────────────────────────────────────
  -- 5) Changed-hours correction series for invoiced keys (BEFORE Phase 1)
  -- ─────────────────────────────────────────────
  if v_should_run_phase3 then
    select public.nhsp_weekly_phase3_apply_adjustment_truth(
      p_import_id := p_import_id,
      p_selected_external_row_keys := v_invoiced_changed_keys,
      p_actor_user_id := p_actor_user_id
    )
    into v_phase3_result;
  end if;

  v_phase3_created_count := jsonb_array_length(coalesce(v_phase3_result->'created_timesheet_ids', '[]'::jsonb));
  v_phase3_updated_count := jsonb_array_length(coalesce(v_phase3_result->'updated_timesheet_ids', '[]'::jsonb));

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','PHASE3_CORRECTIONS_DONE',
    'phase3_called', v_should_run_phase3,
    'phase3_created_count', v_phase3_created_count,
    'phase3_updated_count', v_phase3_updated_count
  ));

  -- ─────────────────────────────────────────────
  -- 6) Phase 1 upsert (NHSP) with tick-only skip/force
  -- ─────────────────────────────────────────────
  if v_should_run_phase1 then
    select public.nhsp_apply_import_phase1(
      p_import_id := p_import_id,
      p_selected_group_ids := array[]::text[],
      p_skip_external_row_keys := v_skip_keys_final,
      p_force_overwrite_external_row_keys := v_force_keys_final
    )
    into v_phase1_result;
  else
    v_phase1_result := null;
  end if;

  v_phase1_shifts_created := coalesce(nullif((coalesce(v_phase1_result,'{}'::jsonb)->>'shifts_created')::int, null), 0);
  v_phase1_shifts_updated := coalesce(nullif((coalesce(v_phase1_result,'{}'::jsonb)->>'shifts_updated')::int, null), 0);

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','PHASE1_DONE',
    'phase1_called', v_should_run_phase1,
    'phase1_shifts_created', v_phase1_shifts_created,
    'phase1_shifts_updated', v_phase1_shifts_updated
  ));

  -- ─────────────────────────────────────────────
  -- 7) Phase 1.5 repair (NHSP)
  -- ─────────────────────────────────────────────
  if v_should_run_phase15 then
    create temporary table tmp_phase15_rows on commit drop as
    select *
    from public.weekly_import_apply_phase2(p_import_id := p_import_id, p_system_type := 'NHSP');

    select count(*)::int
    into v_phase15_ok
    from tmp_phase15_rows r
    where upper(coalesce(r.action::text,'')) = 'OK';

    select count(*)::int
    into v_phase15_updated
    from tmp_phase15_rows r
    where coalesce(r.shift_updated,false) is true;
  else
    v_phase15_ok := 0;
    v_phase15_updated := 0;
  end if;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','PHASE15_DONE',
    'phase15_called', v_should_run_phase15,
    'phase15_ok_rows', v_phase15_ok,
    'phase15_shift_updated_rows', v_phase15_updated
  ));

  -- ─────────────────────────────────────────────
  -- 8) Apply selected cancellations (explicit shift_id only; NHSP)
  -- ─────────────────────────────────────────────
  if v_should_run_cancellations then
    create temporary table tmp_cancel_meta on commit drop as
    select
      ns.id as shift_id,
      ns.candidate_id,
      ns.client_id,
      ns.work_date
    from public.nhsp_shifts ns
    where ns.id = any(v_selected_cancel_shift_ids);

    create temporary table tmp_selected_rep_keys_text on commit drop as
    select distinct
      rk.replacement_day_key
    from tmp_selected_replacement_keys rk;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'shift_id', cm.shift_id::text,
          'reason',
            case
              when exists (
                select 1
                from tmp_selected_rep_keys_text sr
                where sr.replacement_day_key = (cm.candidate_id::text || '|' || cm.client_id::text || '|' || cm.work_date::text)
              ) then 'REPLACEMENT_DAY'
              else 'MISSING_FROM_IMPORT'
            end
        )
      ),
      '[]'::jsonb
    )
    into v_cancel_actions
    from tmp_cancel_meta cm;

    select public.nhsp_weekly_apply_cancellations(
      p_import_id := p_import_id,
      p_actions := v_cancel_actions,
      p_actor_user_id := p_actor_user_id
    )
    into v_cancellations_result;
  else
    v_cancellations_result := null;
  end if;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','CANCELLATIONS_DONE',
    'cancellations_called', v_should_run_cancellations
  ));

  -- ─────────────────────────────────────────────
  -- ✅ 8.5) ENSURE BASE WEEKLY TIMESHEET EXISTS + ATTACH ACTIVE NHSP SHIFTS
  -- ─────────────────────────────────────────────
  v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','ENSURE_BASE_WEEKLY_START'));

  create temporary table tmp_ensure_pairs(
    contract_id uuid,
    candidate_id uuid,
    client_id uuid,
    week_ending_date date
  ) on commit drop;

  insert into tmp_ensure_pairs(contract_id, candidate_id, client_id, week_ending_date)
  select distinct
    p2ok.contract_id,
    p2ok.candidate_id,
    p2ok.client_id,
    p2ok.week_ending_date
  from tmp_p2_ok p2ok
  where p2ok.external_row_key = any(coalesce(v_force_keys_final, array[]::text[]));

  if array_length(v_selected_cancel_shift_ids, 1) is not null then
    insert into tmp_ensure_pairs(contract_id, candidate_id, client_id, week_ending_date)
    select distinct
      ns.contract_id,
      ns.candidate_id,
      ns.client_id,
      ns.week_ending_date
    from public.nhsp_shifts ns
    where ns.id = any(v_selected_cancel_shift_ids)
      and ns.contract_id is not null
      and ns.client_id is not null
      and ns.candidate_id is not null
      and ns.week_ending_date is not null;
  end if;

  create temporary table tmp_ensure_pairs_u on commit drop as
  select distinct
    tep.contract_id,
    tep.candidate_id,
    tep.client_id,
    tep.week_ending_date
  from tmp_ensure_pairs tep
  where tep.contract_id is not null
    and tep.client_id is not null
    and tep.candidate_id is not null
    and tep.week_ending_date is not null;

  select count(*)::int
  into v_ensure_pairs_count
  from tmp_ensure_pairs_u teu;

  select coalesce(jsonb_agg(jsonb_build_object(
    'contract_id', teu.contract_id::text,
    'week_ending_date', teu.week_ending_date::text
  )), '[]'::jsonb)
  into v_ensure_sample_pairs
  from (
    select teu.contract_id, teu.week_ending_date
    from tmp_ensure_pairs_u teu
    order by teu.contract_id::text, teu.week_ending_date::text
    limit 20
  ) as teu;

  drop table if exists pg_temp.tmp_aff_ts;
  create temporary table tmp_aff_ts(
    timesheet_id uuid primary key
  ) on commit drop;

  create temporary table tmp_ensure_created_ts_ids(
    timesheet_id uuid primary key
  ) on commit drop;

  for v_pair_contract_id, v_pair_candidate_id, v_pair_client_id, v_pair_week_ending_date in
    select teu.contract_id, teu.candidate_id, teu.client_id, teu.week_ending_date
    from tmp_ensure_pairs_u teu
    order by teu.contract_id::text, teu.week_ending_date::text
  loop

    select count(*)::int
    into v_active_count
    from public.nhsp_shifts ns_active
    where ns_active.source_system = 'NHSP'::public.hr_source_enum
      and ns_active.cancelled_at_utc is null
      and ns_active.contract_id = v_pair_contract_id
      and ns_active.candidate_id = v_pair_candidate_id
      and ns_active.client_id = v_pair_client_id
      and ns_active.week_ending_date = v_pair_week_ending_date;

    if coalesce(v_active_count, 0) <= 0 then
      v_ensure_pairs_skipped_no_active := v_ensure_pairs_skipped_no_active + 1;
      continue;
    end if;

    v_base_week_id := null;
    v_base_week_ts_id := null;

    select cw0.id, cw0.timesheet_id
    into v_base_week_id, v_base_week_ts_id
    from public.contract_weeks cw0
    where cw0.contract_id = v_pair_contract_id
      and cw0.week_ending_date = v_pair_week_ending_date
      and cw0.is_adjustment is false
      and coalesce(cw0.additional_seq, 0) = 0
    limit 1
    for update;

    if v_base_week_id is null then
      insert into public.contract_weeks(
        contract_id,
        week_ending_date,
        additional_seq,
        status,
        submission_mode_snapshot,
        timesheet_id,
        planned_schedule_json,
        created_at,
        updated_at,
        is_adjustment
      )
      values (
        v_pair_contract_id,
        v_pair_week_ending_date,
        0,
        'SUBMITTED'::public.contract_week_status_enum,
        'MANUAL'::public.submission_mode_enum,
        null,
        null,
        v_now,
        v_now,
        false
      )
      returning id into v_base_week_id;

      v_ensure_base_week_created_count := v_ensure_base_week_created_count + 1;
      v_base_week_ts_id := null;
    else
      v_ensure_base_week_existing_count := v_ensure_base_week_existing_count + 1;
    end if;

    if v_base_week_ts_id is not null then
      select exists(
        select 1
        from public.timesheets tchk
        where tchk.timesheet_id = v_base_week_ts_id
        limit 1
      )
      into v_ts_exists;

      if v_ts_exists is not true then
        update public.contract_weeks cw0u
        set
          timesheet_id = null,
          updated_at = v_now
        where cw0u.id = v_base_week_id;

        v_ensure_timesheet_missing_reference_count := v_ensure_timesheet_missing_reference_count + 1;
        v_base_week_ts_id := null;
      end if;
    end if;

    select ct.display_site, ct.ward_hint, ct.role
    into v_contract_display_site, v_contract_ward_hint, v_contract_role
    from public.contracts ct
    where ct.id = v_pair_contract_id
    limit 1;

    select cand.display_name, cand.tms_ref
    into v_candidate_display_name, v_candidate_tms_ref
    from public.candidates cand
    where cand.id = v_pair_candidate_id
    limit 1;

    select cli.name
    into v_client_name
    from public.clients cli
    where cli.id = v_pair_client_id
    limit 1;

    v_occupant_norm := lower(coalesce(v_candidate_tms_ref, v_candidate_display_name, v_pair_candidate_id::text));
    v_hospital_norm := lower(coalesce(v_contract_display_site, v_client_name, v_pair_client_id::text));
    v_ward_norm := lower(coalesce(v_contract_ward_hint, 'contract'));
    v_role_norm := lower(coalesce(v_contract_role, 'weekly'));

    v_shift_label_norm := 'weekly-0';

    v_booking_base :=
      v_occupant_norm || '|' ||
      v_pair_week_ending_date::text || '|' ||
      v_hospital_norm || '|' ||
      v_ward_norm || '|' ||
      v_role_norm || '|' ||
      v_shift_label_norm;

    v_hash_hex := encode(extensions.digest(convert_to(v_booking_base, 'utf8'), 'sha256'::text), 'hex');
    v_booking_id := 'bk_' || substr(v_hash_hex, 1, 16);

    if v_base_week_ts_id is null then
      v_new_ts_id := null;

      insert into public.timesheets(
        booking_id,
        version,
        is_current,
        status,

        sheet_scope,
        submission_mode,
        line_type,
        authorised_at_server,

        occupant_key_norm,
        hospital_norm,
        ward_norm,
        job_title_norm,
        shift_label_norm,

        week_ending_date,
        contract_id,

        manual_pdf_r2_key,
        actual_schedule_json,

        qr_payload_json,
        candidate_hint_text,

        is_adjustment,
        parent_timesheet_id,
        correction_id,
        correction_kind,
        adjustment_origin,

        created_at,
        updated_at
      )
      values (
        v_booking_id,
        1,
        true,
        'RECEIVED'::public.timesheet_status_enum,

        'WEEKLY'::public.timesheet_scope_enum,
        'MANUAL'::public.submission_mode_enum,
        'HOURS'::public.timesheet_line_type_enum,
        null,

        v_occupant_norm,
        v_hospital_norm,
        v_ward_norm,
        v_role_norm,
        v_shift_label_norm,

        v_pair_week_ending_date,
        v_pair_contract_id,

        null,
        '[]'::jsonb,

        '{}'::jsonb,
        null,

        false,
        null,
        null,
        null,
        null,

        v_now,
        v_now
      )
      returning timesheet_id into v_new_ts_id;

      v_ensure_timesheet_created_count := v_ensure_timesheet_created_count + 1;
      v_base_week_ts_id := v_new_ts_id;

      insert into tmp_ensure_created_ts_ids(timesheet_id)
      values (v_new_ts_id)
      on conflict do nothing;

      update public.contract_weeks cw0link
      set
        timesheet_id = v_new_ts_id,
        status = case
          when cw0link.status = 'AUTHORISED'::public.contract_week_status_enum then cw0link.status
          else 'SUBMITTED'::public.contract_week_status_enum
        end,
        submission_mode_snapshot = 'MANUAL'::public.submission_mode_enum,
        updated_at = v_now
      where cw0link.id = v_base_week_id;

      -- ✅ NEW: user-facing audit line for "birth of base weekly timesheet" (NHSP)
      perform public._audit_insert(
        'timesheets',
        v_new_ts_id::text,
        'NHSP_IMPORT_TIMESHEET_CREATED',
        null,
        jsonb_build_object(
          'import_id', p_import_id::text,
          'source_system', 'NHSP',
          'kind', 'BASE_WEEKLY',
          'contract_id', v_pair_contract_id::text,
          'contract_week_id', v_base_week_id::text,
          'candidate_id', v_pair_candidate_id::text,
          'client_id', v_pair_client_id::text,
          'week_ending_date', v_pair_week_ending_date::text,
          'booking_id', v_booking_id,
          'active_shifts_count', v_active_count
        ),
        'IMPORT_BIRTH',
        p_actor_user_id
      );

    else
      v_ensure_timesheet_reused_count := v_ensure_timesheet_reused_count + 1;

      update public.contract_weeks cw0keep
      set
        status = case
          when cw0keep.status = 'AUTHORISED'::public.contract_week_status_enum then cw0keep.status
          else 'SUBMITTED'::public.contract_week_status_enum
        end,
        submission_mode_snapshot = 'MANUAL'::public.submission_mode_enum,
        updated_at = v_now
      where cw0keep.id = v_base_week_id;

      if exists (
        select 1
        from public.timesheets identity_target
        where identity_target.timesheet_id=v_base_week_ts_id
          and (
            identity_target.week_ending_date is distinct from v_pair_week_ending_date
            or identity_target.contract_id is distinct from v_pair_contract_id
            or identity_target.occupant_key_norm is distinct from v_occupant_norm
            or identity_target.hospital_norm is distinct from v_hospital_norm
            or identity_target.ward_norm is distinct from v_ward_norm
            or identity_target.job_title_norm is distinct from v_role_norm
          )
      ) then
        select public.import_timesheet_financial_preflight_v1(
          p_timesheet_ids := array[v_base_week_ts_id]::uuid[],
          p_action := 'IMPORT_FINANCIAL_IDENTITY_CHANGE',
          p_actor_user_id := p_actor_user_id,
          p_expected_state_json := '{}'::jsonb,
          p_lock_rows := true,
          p_max_scope := 100
        ) into v_changed_preflight;

        if coalesce((v_changed_preflight->>'allowed')::boolean,false) is not true then
          raise exception using message='IMPORT_FINANCIAL_PREFLIGHT_BLOCKED',errcode='P0001',detail=v_changed_preflight::text;
        end if;

        if v_changed_preflight->>'required_path'='CREATE_OR_UPDATE_CORRECTION_CHAIN' then
          raise exception using message='IMPORT_INVOICED_CORRECTION_REQUIRED',errcode='P0001',
            detail=jsonb_build_object(
              'code','IMPORT_INVOICED_CORRECTION_REQUIRED','timesheet_id',v_base_week_ts_id,
              'reason','FINANCIAL_IDENTITY_CHANGE',
              'required_path','CREATE_OR_UPDATE_CORRECTION_CHAIN'
            )::text;
        elsif v_changed_preflight->>'required_path'='UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE' then
          raise exception using message='CANONICAL_UNAUTHORISE_REQUIRED',errcode='P0001',
            detail=jsonb_build_object(
              'code','CANONICAL_UNAUTHORISE_REQUIRED','timesheet_id',v_base_week_ts_id,
              'reason','FINANCIAL_IDENTITY_CHANGE',
              'required_path',jsonb_build_array('UNAUTHORISE','AMEND','RECALCULATE','REAUTHORISE'),
              'paid_uninvoiced_rollover_required',false
            )::text;
        elsif v_changed_preflight->>'required_path'='PAID_UNINVOICED_ROLLOVER'
          and not exists (
            select 1 from public.timesheets_financials rollover_identity
            where rollover_identity.timesheet_id=v_base_week_ts_id
              and rollover_identity.is_current=true
              and rollover_identity.stale_reason='IMPORT_PAID_TSFIN_ROLLOVER_PENDING_CALCULATION'
              and coalesce((rollover_identity.policy_snapshot_json->>'requires_frozen_correction_policy')::boolean,false)=true
          ) then
          raise exception using message='PAID_UNINVOICED_ROLLOVER_REQUIRED',errcode='P0001',
            detail=jsonb_build_object(
              'code','PAID_UNINVOICED_ROLLOVER_REQUIRED','timesheet_id',v_base_week_ts_id,
              'reason','FINANCIAL_IDENTITY_CHANGE',
              'required_path',jsonb_build_array(
                'UNAUTHORISE','PAID_UNINVOICED_ROLLOVER','AMEND','RECALCULATE','REAUTHORISE'
              ),
              'invoice_policy_without_history','NOW'
            )::text;
        end if;
      end if;

      update public.timesheets tnorm
      set
        is_current = true,
        status = 'RECEIVED'::public.timesheet_status_enum,
        sheet_scope = 'WEEKLY'::public.timesheet_scope_enum,
        submission_mode = 'MANUAL'::public.submission_mode_enum,
        line_type = 'HOURS'::public.timesheet_line_type_enum,
        week_ending_date = v_pair_week_ending_date,
        contract_id = v_pair_contract_id,
        occupant_key_norm = v_occupant_norm,
        hospital_norm = v_hospital_norm,
        ward_norm = v_ward_norm,
        job_title_norm = v_role_norm,
        shift_label_norm = v_shift_label_norm,
        updated_at = v_now
      where tnorm.timesheet_id = v_base_week_ts_id;
    end if;

    if exists (
      select 1 from public.nhsp_shifts ns_scope
      where ns_scope.source_system = 'NHSP'::public.hr_source_enum
        and ns_scope.cancelled_at_utc is null
        and ns_scope.contract_id = v_pair_contract_id
        and ns_scope.candidate_id = v_pair_candidate_id
        and ns_scope.client_id = v_pair_client_id
        and ns_scope.week_ending_date = v_pair_week_ending_date
        and (
          ns_scope.timesheet_id is null
          or not exists (
            select 1 from public.timesheets existing_link
            where existing_link.timesheet_id=ns_scope.timesheet_id
          )
        )
    ) then
      select public.import_timesheet_financial_preflight_v1(
        p_timesheet_ids := array[v_base_week_ts_id]::uuid[],
        p_action := 'IMPORT_SOURCE_ASSIGNMENT',
        p_actor_user_id := p_actor_user_id,
        p_expected_state_json := '{}'::jsonb,
        p_lock_rows := true,
        p_max_scope := 100
      ) into v_changed_preflight;

      if coalesce((v_changed_preflight->>'allowed')::boolean,false) is not true then
        raise exception using message='IMPORT_FINANCIAL_PREFLIGHT_BLOCKED',errcode='P0001',detail=v_changed_preflight::text;
      end if;

      if v_changed_preflight->>'required_path'='CREATE_OR_UPDATE_CORRECTION_CHAIN' then
        raise exception using message='IMPORT_INVOICED_CORRECTION_REQUIRED',errcode='P0001',
          detail=jsonb_build_object(
            'code','IMPORT_INVOICED_CORRECTION_REQUIRED','timesheet_id',v_base_week_ts_id,
            'reason','FINANCIAL_SOURCE_ASSIGNMENT_CHANGE',
            'required_path','CREATE_OR_UPDATE_CORRECTION_CHAIN'
          )::text;
      end if;

      if exists (
        select 1 from public.timesheets source_target
        left join public.timesheets_financials source_target_tf
          on source_target_tf.timesheet_id=source_target.timesheet_id and source_target_tf.is_current=true
        where source_target.timesheet_id=v_base_week_ts_id
          and (source_target.authorised_at_server is not null or source_target_tf.authorised_at_utc is not null)
          and not exists (
            select 1 from public.timesheets_financials paid_target
            where paid_target.timesheet_id=source_target.timesheet_id
              and paid_target.paid_at_utc is not null
          )
      ) then
        raise exception using message='CANONICAL_UNAUTHORISE_REQUIRED',errcode='P0001',
          detail=jsonb_build_object(
            'code','CANONICAL_UNAUTHORISE_REQUIRED','timesheet_id',v_base_week_ts_id,
            'reason','FINANCIAL_SOURCE_ASSIGNMENT_CHANGE',
            'required_path',jsonb_build_array('UNAUTHORISE','AMEND','RECALCULATE','REAUTHORISE'),
            'paid_uninvoiced_rollover_required',false
          )::text;
      end if;

      if exists (
        select 1 from public.timesheets_financials paid_source
        where paid_source.timesheet_id=v_base_week_ts_id and paid_source.paid_at_utc is not null
      ) and not exists (
        select 1 from public.timesheets_financials rollover_source
        where rollover_source.timesheet_id=v_base_week_ts_id and rollover_source.is_current=true
          and rollover_source.stale_reason='IMPORT_PAID_TSFIN_ROLLOVER_PENDING_CALCULATION'
          and coalesce((rollover_source.policy_snapshot_json->>'requires_frozen_correction_policy')::boolean,false)=true
      ) then
        raise exception using message='PAID_UNINVOICED_ROLLOVER_REQUIRED',errcode='P0001',
          detail=jsonb_build_object(
            'code','PAID_UNINVOICED_ROLLOVER_REQUIRED','timesheet_id',v_base_week_ts_id,
            'reason','FINANCIAL_SOURCE_ASSIGNMENT_CHANGE',
            'required_path',jsonb_build_array(
              'UNAUTHORISE','PAID_UNINVOICED_ROLLOVER','AMEND','RECALCULATE','REAUTHORISE'
            ),
            'invoice_policy_without_history','NOW'
          )::text;
      end if;
    end if;

    update public.nhsp_shifts nsu0
    set
      timesheet_id = v_base_week_ts_id,
      updated_at = v_now
    where nsu0.source_system = 'NHSP'::public.hr_source_enum
      and nsu0.cancelled_at_utc is null
      and nsu0.contract_id = v_pair_contract_id
      and nsu0.candidate_id = v_pair_candidate_id
      and nsu0.client_id = v_pair_client_id
      and nsu0.week_ending_date = v_pair_week_ending_date
      and nsu0.timesheet_id is null;

    get diagnostics v_attached_null_count = row_count;
    v_ensure_shifts_attached_count := v_ensure_shifts_attached_count + coalesce(v_attached_null_count, 0);

    update public.nhsp_shifts nsu1
    set
      timesheet_id = v_base_week_ts_id,
      updated_at = v_now
    where nsu1.source_system = 'NHSP'::public.hr_source_enum
      and nsu1.cancelled_at_utc is null
      and nsu1.contract_id = v_pair_contract_id
      and nsu1.candidate_id = v_pair_candidate_id
      and nsu1.client_id = v_pair_client_id
      and nsu1.week_ending_date = v_pair_week_ending_date
      and nsu1.timesheet_id is not null
      and not exists (
        select 1
        from public.timesheets tmiss
        where tmiss.timesheet_id = nsu1.timesheet_id
        limit 1
      );

    get diagnostics v_relinked_invalid_count = row_count;
    v_ensure_shifts_relinked_invalid_ts_count := v_ensure_shifts_relinked_invalid_ts_count + coalesce(v_relinked_invalid_count, 0);

    select count(*)::int
    into v_active_count
    from public.nhsp_shifts nscheck
    where nscheck.source_system = 'NHSP'::public.hr_source_enum
      and nscheck.cancelled_at_utc is null
      and nscheck.contract_id = v_pair_contract_id
      and nscheck.candidate_id = v_pair_candidate_id
      and nscheck.client_id = v_pair_client_id
      and nscheck.week_ending_date = v_pair_week_ending_date
      and (
        nscheck.timesheet_id is null
        or not exists (
          select 1
          from public.timesheets tchk2
          where tchk2.timesheet_id = nscheck.timesheet_id
          limit 1
        )
      );

    if coalesce(v_active_count, 0) > 0 then
      v_ensure_remaining_active_detached_count := v_ensure_remaining_active_detached_count + v_active_count;
      raise exception
        'nhsp_weekly_apply_transactional: ENSURE invariant failed (active NHSP shifts remain detached or linked to missing timesheets) contract_id=% week_ending_date=% remaining=%.',
        v_pair_contract_id, v_pair_week_ending_date, v_active_count;
    end if;

    insert into tmp_aff_ts(timesheet_id)
    values (v_base_week_ts_id)
    on conflict do nothing;

  end loop;

  select coalesce(jsonb_agg(x.ts_id), '[]'::jsonb)
  into v_ensure_sample_created_ts_ids
  from (
    select tct.timesheet_id::text as ts_id
    from tmp_ensure_created_ts_ids tct
    order by tct.timesheet_id::text
    limit 20
  ) as x;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','ENSURE_BASE_WEEKLY_DONE',
    'ensure_pairs_count', v_ensure_pairs_count,
    'ensure_pairs_skipped_no_active', v_ensure_pairs_skipped_no_active,
    'base_week_created_count', v_ensure_base_week_created_count,
    'base_week_existing_count', v_ensure_base_week_existing_count,
    'base_timesheet_created_count', v_ensure_timesheet_created_count,
    'base_timesheet_reused_count', v_ensure_timesheet_reused_count,
    'missing_timesheet_reference_count', v_ensure_timesheet_missing_reference_count,
    'shifts_attached_null_count', v_ensure_shifts_attached_count,
    'shifts_relinked_invalid_ts_count', v_ensure_shifts_relinked_invalid_ts_count,
    'sample_pairs', v_ensure_sample_pairs,
    'sample_created_ts_ids', v_ensure_sample_created_ts_ids
  ));

  -- ─────────────────────────────────────────────
  -- 9) Compute affected_timesheet_ids (union of ensure + corrections + cancellations + non-invoiced updates)
  -- ─────────────────────────────────────────────
  select coalesce(array_agg(k.external_row_key order by k.external_row_key), array[]::text[])
  into v_force_keys_non_invoiced
  from (
    select distinct fk.external_row_key
    from unnest(coalesce(v_force_keys_final, array[]::text[])) as fk(external_row_key)
    left join unnest(coalesce(v_invoiced_changed_keys, array[]::text[])) as ik(external_row_key)
      on ik.external_row_key = fk.external_row_key
    where ik.external_row_key is null
  ) as k;

  insert into tmp_aff_ts(timesheet_id)
  select (x.value)::uuid
  from jsonb_array_elements_text(coalesce(v_cancellations_result->'affected_timesheet_ids', '[]'::jsonb)) as x(value)
  where nullif(btrim(x.value), '') is not null
  on conflict do nothing;

  insert into tmp_aff_ts(timesheet_id)
  select (x2.value)::uuid
  from jsonb_array_elements_text(coalesce(v_phase3_result->'created_timesheet_ids', '[]'::jsonb)) as x2(value)
  where nullif(btrim(x2.value), '') is not null
  on conflict do nothing;

  insert into tmp_aff_ts(timesheet_id)
  select (x3.value)::uuid
  from jsonb_array_elements_text(coalesce(v_phase3_result->'updated_timesheet_ids', '[]'::jsonb)) as x3(value)
  where nullif(btrim(x3.value), '') is not null
  on conflict do nothing;

  insert into tmp_aff_ts(timesheet_id)
  select distinct ns.timesheet_id
  from public.nhsp_shifts ns
  where ns.source_system = 'NHSP'::public.hr_source_enum
    and ns.cancelled_at_utc is null
    and ns.external_row_key = any(coalesce(v_force_keys_non_invoiced, array[]::text[]))
    and ns.timesheet_id is not null
  on conflict do nothing;

  insert into tmp_aff_ts(timesheet_id)
  select distinct partner.timesheet_id
  from tmp_aff_ts seed
  join public.timesheets seed_ts
    on seed_ts.timesheet_id=seed.timesheet_id
   and seed_ts.is_current=true
   and seed_ts.correction_id is not null
   and upper(btrim(coalesce(seed_ts.adjustment_origin,''))) in (
     'IMPORT_CORRECTION','IMPORT_CANCELLATION','HEALTHROSTER_CHANGED_HOURS',
     'NHSP_CHANGED_HOURS','HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION'
   )
  join public.timesheets partner
    on partner.correction_id=seed_ts.correction_id
   and partner.is_current=true
   and upper(btrim(coalesce(partner.adjustment_origin,''))) in (
     'IMPORT_CORRECTION','IMPORT_CANCELLATION','HEALTHROSTER_CHANGED_HOURS',
     'NHSP_CHANGED_HOURS','HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION'
   )
  on conflict do nothing;

  -- Persist and enqueue complete correction units, including unchanged legs.
  select coalesce(array_agg(distinct a.timesheet_id order by a.timesheet_id), array[]::uuid[])
  into v_affected_timesheet_ids
  from (
    select a.timesheet_id
    from tmp_aff_ts a
    where a.timesheet_id is not null
      and not (a.timesheet_id=any(coalesce(v_protected_source_timesheet_ids,array[]::uuid[])))
    union all
    select paid_id from unnest(coalesce(v_paid_applied_timesheet_ids,array[]::uuid[])) paid(paid_id)
  ) a;

  -- Authorised-state restoration and imported financial correction members
  -- are mandatory regardless of the ordinary auto-authorise setting.  This
  -- keeps a reversal/replacement unit authorised together and also covers a
  -- reversal-only cancellation without fabricating a replacement.
  select coalesce(array_agg(distinct required.timesheet_id order by required.timesheet_id),array[]::uuid[])
  into v_reauthorise_timesheet_ids
  from (
    select existing.timesheet_id
    from unnest(coalesce(v_reauthorise_timesheet_ids,array[]::uuid[])) existing(timesheet_id)
    union all
    select correction.timesheet_id
    from unnest(coalesce(v_affected_timesheet_ids,array[]::uuid[])) affected(timesheet_id)
    join public.timesheets correction on correction.timesheet_id=affected.timesheet_id
    where correction.is_current=true
      and correction.revoked_at is null
      and coalesce(correction.is_adjustment,false)
      and correction.correction_id is not null
  ) required
  where required.timesheet_id is not null;

  if to_regclass('pg_temp.import_review_reconciliation_units_v1') is not null then
    if exists(
      select 1 from pg_temp.import_review_reconciliation_units_v1 u
      where u.route in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT') and (
        nullif(u.unit_json->>'correction_id','') is null
        or jsonb_typeof(u.unit_json->'applied_member_ids')<>'array'
        or jsonb_array_length(u.unit_json->'applied_member_ids')<>2
        or (select count(*)=2
              and count(*) filter(where t.correction_kind='CHANGED_HOURS_REVERSAL')=1
              and count(*) filter(where t.correction_kind='CHANGED_HOURS_REPLACEMENT')=1
              and count(distinct t.parent_timesheet_id)=1
              and count(t.parent_timesheet_id)=2
            from public.timesheets t
            where t.correction_id=u.unit_json->>'correction_id' and t.is_current and t.archived_at_utc is null
              and t.adjustment_origin='IMPORT_CORRECTION'
              and t.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')) is not true
      )
    ) then
      raise exception 'IMPORT_REVIEW_APPLY_POSTCONDITION_FAILED' using errcode='55000',
        detail=jsonb_build_object('reason_code','CORRECTION_MEMBER_SET_INCOMPLETE')::text;
    end if;
    if exists(select 1 from pg_temp.import_review_reconciliation_units_v1 u
      where u.route='AMEND_PAID_UNINVOICED_SOURCE' and (
        nullif(u.unit_json->>'applied_timesheet_id','')::uuid is distinct from u.source_timesheet_id
        or nullif(u.unit_json->>'reviewed_unit_fingerprint','') is distinct from u.unit_fingerprint
        or coalesce(u.unit_json->>'rollover_mode','') not in ('CREATED_CURRENT_OPERATION_SHELL','REUSED_COMPLETED_OPERATION_SHELL')
        or coalesce(u.unit_json->>'historical_paid_tsfin_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or coalesce(u.unit_json->>'current_shell_tsfin_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or u.unit_json->>'applied_result_fingerprint' is distinct from encode(extensions.digest(convert_to(
          jsonb_build_object(
            'applied_timesheet_id',(u.unit_json->>'applied_timesheet_id')::uuid,
            'rollover_mode',u.unit_json->>'rollover_mode',
            'historical_paid_tsfin_id',(u.unit_json->>'historical_paid_tsfin_id')::uuid,
            'current_shell_tsfin_id',(u.unit_json->>'current_shell_tsfin_id')::uuid,
            'intended_authorisation_action',u.unit_json->>'intended_authorisation_action',
            'reviewed_unit_fingerprint',u.unit_json->>'reviewed_unit_fingerprint',
            'reconciliation_fingerprint',u.unit_json->>'reconciliation_fingerprint')::text,'UTF8'),'sha256'),'hex')
        or not exists(select 1 from public.timesheets_financials historical
          where historical.id=(u.unit_json->>'historical_paid_tsfin_id')::uuid
            and historical.timesheet_id=u.source_timesheet_id and not historical.is_current
            and historical.paid_at_utc is not null and historical.locked_by_invoice_id is null)
        or not exists(select 1 from public.timesheets_financials shell
          where shell.id=(u.unit_json->>'current_shell_tsfin_id')::uuid
            and shell.timesheet_id=u.source_timesheet_id and shell.is_current and shell.paid_at_utc is null)
      )) then
      raise exception 'IMPORT_REVIEW_APPLY_POSTCONDITION_FAILED' using errcode='55000',
        detail=jsonb_build_object('reason_code','PAID_SOURCE_ROLLOVER_RESULT_INVALID')::text;
    end if;
    select coalesce(array_agg(distinct x.value::uuid order by x.value::uuid) filter (where x.value is not null),array[]::uuid[])
    into v_operation_bound_correction_timesheet_ids
    from pg_temp.import_review_reconciliation_units_v1 u
    left join lateral jsonb_array_elements_text(coalesce(u.unit_json->'applied_member_ids','[]'::jsonb)) x(value) on true
    where u.route in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT');
    select coalesce(jsonb_agg(u.unit_json order by u.action_id),'[]'::jsonb) into v_reconciliation_units
    from pg_temp.import_review_reconciliation_units_v1 u;
    select coalesce(array_agg(x order by x),array[]::uuid[]) into v_reauthorise_timesheet_ids
    from unnest(coalesce(v_reauthorise_timesheet_ids,array[]::uuid[])) x
    where not (x=any(coalesce(v_operation_bound_correction_timesheet_ids,array[]::uuid[])));
  end if;

  v_auto_authorise_timesheet_ids:=public._import_review_auto_authorise_targets_core_v1(
    v_affected_timesheet_ids,'NHSP'::public.hr_source_enum,false
  );
  select coalesce(array_agg(distinct target_id order by target_id),array[]::uuid[])
  into v_auto_authorise_timesheet_ids from (
    select target_id from unnest(coalesce(v_auto_authorise_timesheet_ids,array[]::uuid[])) x(target_id)
    where not (target_id=any(coalesce(v_paid_applied_timesheet_ids,array[]::uuid[])))
    union all
    select u.source_timesheet_id from pg_temp.import_review_reconciliation_units_v1 u
    where u.route='AMEND_PAID_UNINVOICED_SOURCE'
      and u.unit_json->>'intended_authorisation_action'='AUTHORISE'
  ) reviewed_auto;
  select coalesce(array_agg(distinct target_id order by target_id),array[]::uuid[])
  into v_reauthorise_timesheet_ids from (
    select target_id from unnest(coalesce(v_reauthorise_timesheet_ids,array[]::uuid[])) x(target_id)
    where not (target_id=any(coalesce(v_paid_applied_timesheet_ids,array[]::uuid[])))
    union all
    select u.source_timesheet_id from pg_temp.import_review_reconciliation_units_v1 u
    where u.route='AMEND_PAID_UNINVOICED_SOURCE'
      and u.unit_json->>'intended_authorisation_action'='REAUTHORISE'
  ) reviewed_reauthorise;
  select coalesce(array_agg(x order by x),array[]::uuid[]) into v_general_authorise_timesheet_ids
  from unnest(coalesce(v_auto_authorise_timesheet_ids,array[]::uuid[])||coalesce(v_reauthorise_timesheet_ids,array[]::uuid[])) x
  where not (x=any(coalesce(v_operation_bound_correction_timesheet_ids,array[]::uuid[])));

  if array_length(v_affected_timesheet_ids, 1) is not null then
    perform public.enqueue_ts_financials_priority(v_affected_timesheet_ids, 'CONTEXT_CHANGED'::public.ts_fin_reason_enum);
  end if;

  if jsonb_array_length(coalesce(v_cancellations_result->'affected_timesheet_ids', '[]'::jsonb)) > 0 then
    create temporary table tmp_cancel_aff_ts(ts_id uuid primary key) on commit drop;

    insert into tmp_cancel_aff_ts(ts_id)
    select distinct (x4.value)::uuid
    from jsonb_array_elements_text(coalesce(v_cancellations_result->'affected_timesheet_ids', '[]'::jsonb)) as x4(value)
    where nullif(btrim(x4.value), '') is not null
    on conflict do nothing;

    select count(*)::int
    into v_cancel_adjustment_count
    from tmp_cancel_aff_ts cts
    join public.timesheets tts
      on tts.timesheet_id = cts.ts_id
    where tts.is_adjustment is true;
  else
    v_cancel_adjustment_count := 0;
  end if;

  v_correction_timesheets_created_count := (v_phase3_created_count + v_phase3_updated_count + coalesce(v_cancel_adjustment_count, 0));

  v_steps := v_steps || jsonb_build_array(jsonb_build_object(
    'step','AFFECTED_TS_DONE',
    'affected_timesheet_ids_count', coalesce(array_length(v_affected_timesheet_ids, 1), 0),
    'cancel_adjustment_count', v_cancel_adjustment_count,
    'correction_timesheets_created_count', v_correction_timesheets_created_count
  ));

  -- ─────────────────────────────────────────────
  -- 10) Preserve the source route.  Whole-import completion is owned by
  -- _import_review_apply_complete_core_v1 only after no work remains.
  -- ─────────────────────────────────────────────
  update public.hr_imports hi3
  set import_scope = 'NHSP'
  where hi3.id = p_import_id;

  v_steps := v_steps || jsonb_build_array(jsonb_build_object('step','IMPORT_BATCH_APPLIED'));

  -- ─────────────────────────────────────────────
  -- 11) Debug audit (invoice_debug gated inside _imp_debug_audit)
  -- ─────────────────────────────────────────────
  perform public._imp_debug_audit(
    p_actor_user_id,
    'NHSP_WEEKLY_APPLY_DEBUG',
    jsonb_build_object(
      'import_id', p_import_id::text,
      'steps', v_steps,

      'selected_action_ids_count', v_selected_action_ids_count,
      'selected_row_keys_count', v_selected_row_keys_count,
      'selected_cancel_shift_ids_count', v_selected_cancel_shift_ids_count,
      'selected_action_ids_sample', v_sample_selected_action_ids,

      'ok_keys_total', v_ok_keys_total,

      'phase1_called', v_should_run_phase1,
      'phase1_force_keys_count', v_force_keys_count,
      'phase1_skip_keys_count', v_skip_keys_count,
      'phase1_force_keys_sample', v_sample_force_keys,
      'phase1_skip_keys_sample', v_sample_skip_keys,
      'phase1_shifts_created', v_phase1_shifts_created,
      'phase1_shifts_updated', v_phase1_shifts_updated,

      'phase15_called', v_should_run_phase15,
      'phase15_ok_rows', v_phase15_ok,
      'phase15_shift_updated_rows', v_phase15_updated,

      'invoiced_changed_keys_count', v_invoiced_changed_keys_count,
      'not_invoiced_changed_keys_count', v_not_invoiced_changed_keys_count,
      'phase3_called', v_should_run_phase3,
      'phase3_created_count', v_phase3_created_count,
      'phase3_updated_count', v_phase3_updated_count,

      'cancellations_called', v_should_run_cancellations,
      'cancellations_count', v_cancellations_count,
      'sample_cancel_shift_ids', v_sample_cancel_shift_ids,

      'ensure_pairs_count', v_ensure_pairs_count,
      'ensure_pairs_skipped_no_active', v_ensure_pairs_skipped_no_active,
      'ensure_base_week_created_count', v_ensure_base_week_created_count,
      'ensure_base_week_existing_count', v_ensure_base_week_existing_count,
      'ensure_timesheet_created_count', v_ensure_timesheet_created_count,
      'ensure_timesheet_reused_count', v_ensure_timesheet_reused_count,
      'ensure_timesheet_missing_reference_count', v_ensure_timesheet_missing_reference_count,
      'ensure_shifts_attached_null_count', v_ensure_shifts_attached_count,
      'ensure_shifts_relinked_invalid_ts_count', v_ensure_shifts_relinked_invalid_ts_count,
      'ensure_sample_pairs', v_ensure_sample_pairs,
      'ensure_sample_created_ts_ids', v_ensure_sample_created_ts_ids,

      'cancel_adjustment_count', v_cancel_adjustment_count,
      'correction_timesheets_created_count', v_correction_timesheets_created_count,

      'affected_timesheet_ids_count', coalesce(array_length(v_affected_timesheet_ids, 1), 0)
    ),
    'hr_imports',
    p_import_id::text,
    null,
    null,
    null,
    null
  );

  v_review_result:=jsonb_build_object(
    'import_id', p_import_id,
    'mode_b', jsonb_build_object(
      'selected_truth_keys', to_jsonb(coalesce(v_selected_truth_keys_ok, array[]::text[])),
      'force_overwrite_external_row_keys', to_jsonb(coalesce(v_force_keys_final, array[]::text[])),
      'skip_external_row_keys', to_jsonb(coalesce(v_skip_keys_final, array[]::text[])),
      'phase3', v_phase3_result,
      'phase1', v_phase1_result,
      'phase15', jsonb_build_object(
        'ok_rows', v_phase15_ok,
        'shift_updated_rows', v_phase15_updated
      ),
      'cancellations', v_cancellations_result
    ),
    'affected_timesheet_ids', to_jsonb(coalesce(v_affected_timesheet_ids, array[]::uuid[])),
    'auto_authorise_timesheet_ids',to_jsonb(coalesce(v_auto_authorise_timesheet_ids,array[]::uuid[])),
    'post_commit_reauthorise_timesheet_ids',to_jsonb(coalesce(v_reauthorise_timesheet_ids,array[]::uuid[])),
    'reconciliation_action_ids',to_jsonb(coalesce(v_reconciliation_action_ids,array[]::text[])),
    'operation_bound_correction_action_ids',to_jsonb(coalesce(v_operation_bound_correction_action_ids,array[]::text[])),
    'general_authorise_timesheet_ids',to_jsonb(coalesce(v_general_authorise_timesheet_ids,array[]::uuid[])),
    'operation_bound_correction_timesheet_ids',to_jsonb(coalesce(v_operation_bound_correction_timesheet_ids,array[]::uuid[])),
    'reconciliation_units',coalesce(v_reconciliation_units,'[]'::jsonb),
    'post_commit_email_action_ids','[]'::jsonb,
    'review_operation_id',v_review_operation_id
  );
  perform public._import_review_apply_complete_core_v1(p_import_id,v_review_operation_id,p_actor_user_id,v_review_result,
    cardinality(v_affected_timesheet_ids)>0);
  return v_review_result;

exception when others then
  get stacked diagnostics v_sqlstate = returned_sqlstate, v_err = message_text;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'NHSP_WEEKLY_APPLY_ERROR',
      jsonb_build_object(
        'import_id', p_import_id::text,
        'steps', v_steps,
        'sqlstate', v_sqlstate,
        'error', v_err,

        'selected_action_ids_count', v_selected_action_ids_count,
        'selected_row_keys_count', v_selected_row_keys_count,
        'selected_cancel_shift_ids_count', v_selected_cancel_shift_ids_count,
        'selected_action_ids_sample', v_sample_selected_action_ids
      ),
      'hr_imports',
      p_import_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  raise;
end;
$function$;

-- nhsp_weekly_phase3_apply_adjustment_truth(uuid,text[],uuid)
CREATE OR REPLACE FUNCTION public.nhsp_weekly_phase3_apply_adjustment_truth(p_import_id uuid, p_selected_external_row_keys text[], p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();

  v_src public.hr_source_enum;

  v_selected_keys text[] := '{}';
  v_key text;
  v_last_key text := null;

  v_row jsonb;

  v_is_invoiced boolean := false;
  v_invoice_id_detected uuid := null;

  v_contract_id uuid;
  v_candidate_id uuid;
  v_client_id uuid;
  v_work_date date;

  -- Week ending date (MUST be contract-driven or base-timesheet driven; not assumed Sunday)
  v_week_ending_date date;
  v_base_timesheet_id uuid := null;
  v_base_week_ending_date date := null;

  -- ✅ NEW: inherit policy identity from the parent/base timesheet (so adjustments follow parent stream)
  v_parent_sheet_scope public.timesheet_scope_enum := 'WEEKLY'::public.timesheet_scope_enum;
  v_parent_submission_mode public.submission_mode_enum := 'MANUAL'::public.submission_mode_enum;

  v_contract_week_ending_weekday_snapshot int := 0;
  v_work_dow int := 0;
  v_we_delta int := 0;

  v_correction_id text;
  v_reviewed_correction_id text;
  v_repair_identity_mode text;
  v_repair_operation_id text;
  v_kind text;

  v_old_start_utc timestamptz;
  v_old_end_utc   timestamptz;
  v_new_start_utc timestamptz;
  v_new_end_utc   timestamptz;
  v_old_break_mins int;
  v_new_break_mins int;

  -- ✅ Keep original string forms for deterministic correction_id hashing
  v_old_start_str text := null;
  v_old_end_str text := null;
  v_new_start_str text := null;
  v_new_end_str text := null;
  v_old_break_str text := null;
  v_new_break_str text := null;

  v_seg_start_utc timestamptz;
  v_seg_end_utc timestamptz;
  v_seg_break_mins int;

  v_ref_num text := null;

  -- ✅ Evidence linkage (NHSP)
  v_shift_id uuid := null;
  v_shift_prev_import_id uuid := null;
  v_schedule_import_id uuid := null;

  -- ✅ Existing replacement (POS₀) handling to avoid stacking corrections
  v_existing_pos_ts_id uuid := null;
  v_existing_pos_correction_id text := null;
  v_existing_pos_schedule jsonb := null;
  v_existing_pos_hint jsonb := null;
  v_existing_pos_is_invoiced boolean := false;
  v_existing_pos_tf_locked_by_invoice_id uuid := null;
  v_existing_pos_tf_invoice_breakdown_json jsonb := null;
  v_existing_pos_seg_invoice_id uuid := null;
  v_existing_pos_seg jsonb := null;

  v_existing_pos_old_start_str text := null;
  v_existing_pos_old_end_str text := null;
  v_existing_pos_old_break_str text := null;
  v_existing_pos_import_id uuid := null;
  v_existing_pair_parent_timesheet_id uuid := null;

  -- ✅ NEW: Existing base reversal (NEG₀) for edge-case deletion
  v_existing_neg_ts_id uuid := null;
  v_existing_neg_schedule jsonb := null;
  v_existing_neg_is_invoiced boolean := false;
  v_existing_neg_tf_locked_by_invoice_id uuid := null;
  v_existing_neg_tf_invoice_breakdown_json jsonb := null;
  v_existing_neg_seg_invoice_id uuid := null;

  v_existing_neg_base_start_utc timestamptz := null;
  v_existing_neg_base_end_utc timestamptz := null;
  v_existing_neg_base_break_mins int := null;

  v_existing_pos_count int := 0;
  v_existing_neg_count int := 0;

  v_deleted_redundant_pair boolean := false;
  v_reconciliation_unit jsonb := null;
  v_reconciliation_route text := null;
  v_reconciliation_b_schedule jsonb := null;
  v_reconciliation_a_schedule jsonb := null;
  -- Historical correction finance authority (Policy X pre-draft only)
  v_chain_scope jsonb := null;
  v_financial_preflight jsonb := null;
  v_correction_financials_policy_envelope jsonb := null;
  v_correction_financials_policy_envelope_fingerprint text := null;
  v_correction_operation_id uuid := null;
  v_root_timesheet_id uuid := null;
  v_latest_positive_timesheet_id uuid := null;


  v_updated_existing_replacement boolean := false;

  -- Per-key audit helpers
  v_old_paid_minutes int := null;
  v_new_paid_minutes int := null;
  v_delta_paid_minutes int := null;

  v_invoice_number_text text := null;

  v_rev_ts_id uuid := null;
  v_rep_ts_id uuid := null;

  v_shift_date_ymd text;

  v_contract_display_site text;
  v_contract_ward_hint text;
  v_contract_role text;

  v_client_name text;
  v_candidate_display_name text;
  v_candidate_tms_ref text;

  v_booking_base text;
  v_booking_id text;
  v_hash_hex text;

  v_base_week_id uuid;

  v_existing_ts_id uuid;
  v_existing_cw_id uuid;
  v_existing_cw_seq int;
  v_existing_cw_is_adjustment boolean;

  v_next_additional_seq int;

  v_ts_id uuid;

  v_ins_count int := 0;
  v_upd_count int := 0;
  v_skipped_count int := 0;

  v_created_ts_ids uuid[] := '{}';
  v_updated_ts_ids uuid[] := '{}';

  -- fnv1a32 helper vars
  v_fnv_h bigint;
  v_fnv_i int;
  v_fnv_s text;
  v_fnv_hex text;

  v_hospital_norm text;
  v_ward_norm text;
  v_role_norm text;
  v_shift_label text;
  v_shift_label_norm text;

  v_schedule jsonb;
  v_hint jsonb;

  v_try int;

  -- debug sample (invoice_debug gated inside _imp_debug_audit)
  v_sample jsonb := '[]'::jsonb;
  v_sample_n int := 0;
  v_key_ts jsonb;
  v_kind_op text;

  v_sqlstate text;
  v_err text;
begin
  -- ---- Validate import exists and is NHSP ----
  select hi.source_system
  into v_src
  from public.hr_imports hi
  where hi.id = p_import_id
  limit 1;

  if v_src is null then
    raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: import_not_found (import_id=%)', p_import_id;
  end if;

  if v_src <> 'NHSP'::public.hr_source_enum then
    raise exception
      'nhsp_weekly_phase3_apply_adjustment_truth: source_system_mismatch (import_id=% actual=% expected=NHSP)',
      p_import_id, v_src;
  end if;

  -- ---- Normalise selected keys ----
  select coalesce(array_agg(distinct btrim(k)), '{}')
  into v_selected_keys
  from unnest(coalesce(p_selected_external_row_keys, '{}'::text[])) as k
  where k is not null and btrim(k) <> '';

  if array_length(v_selected_keys, 1) is null then
    return jsonb_build_object(
      'import_id', p_import_id,
      'selected_count', 0,
      'skipped_count', 0,
      'inserted_count', 0,
      'updated_count', 0,
      'created_timesheet_ids', '[]'::jsonb,
      'updated_timesheet_ids', '[]'::jsonb
    );
  end if;

  -- ---- Load Phase 3 rows for selected keys into a lookup ----
  create temporary table tmp_phase3_by_key(
    external_row_key text primary key,
    row_json jsonb not null
  ) on commit drop;

  insert into tmp_phase3_by_key(external_row_key, row_json)
  select
    r.external_row_key,
    to_jsonb(r) as row_json
  from public.weekly_import_changed_hours_phase3(
    p_import_id := p_import_id,
    p_system_type := 'NHSP'
  ) as r
  where r.external_row_key = any(v_selected_keys)
  on conflict (external_row_key) do nothing;

  -- ---- Process each selected key ----
  foreach v_key in array v_selected_keys loop
    v_last_key := v_key;

    -- reset per-key flags
    v_updated_existing_replacement := false;
    v_deleted_redundant_pair := false;
    v_reconciliation_unit := null;
    v_reconciliation_route := null;
    v_reconciliation_b_schedule := null;
    v_reconciliation_a_schedule := null;

    if to_regclass('pg_temp.import_review_reconciliation_units_v1') is not null then
      select u.unit_json into v_reconciliation_unit
      from pg_temp.import_review_reconciliation_units_v1 u
      where u.source_identity=v_key;
      if v_reconciliation_unit is not null then
        if v_reconciliation_unit->>'source_system'<>'NHSP'
           or v_reconciliation_unit->>'route' not in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT') then
          raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
        end if;
        v_reconciliation_route:=v_reconciliation_unit->>'route';
        v_reconciliation_b_schedule:=coalesce(v_reconciliation_unit->'B_standard_schedule_json','[]'::jsonb);
        v_reconciliation_a_schedule:=coalesce(v_reconciliation_unit->'A_schedule_json','[]'::jsonb);
      end if;
    end if;

    v_existing_pos_ts_id := null;
    v_existing_pos_correction_id := null;
    v_existing_pos_schedule := null;
    v_existing_pos_is_invoiced := false;
    v_existing_pos_tf_locked_by_invoice_id := null;
    v_existing_pos_tf_invoice_breakdown_json := null;
    v_existing_pos_seg_invoice_id := null;
    v_existing_pos_seg := null;
    v_existing_pos_old_start_str := null;
    v_existing_pos_old_end_str := null;
    v_existing_pos_old_break_str := null;
    v_existing_pos_import_id := null;
    v_existing_pair_parent_timesheet_id := null;

    v_existing_neg_ts_id := null;
    v_existing_neg_schedule := null;
    v_existing_neg_is_invoiced := false;
    v_existing_neg_tf_locked_by_invoice_id := null;
    v_existing_neg_tf_invoice_breakdown_json := null;
    v_existing_neg_seg_invoice_id := null;

    v_existing_neg_base_start_utc := null;
    v_existing_neg_base_end_utc := null;
    v_existing_neg_base_break_mins := null;

    v_existing_pos_count := 0;
    v_existing_neg_count := 0;

    select t.row_json
    into v_row
    from tmp_phase3_by_key t
    where t.external_row_key = v_key;

    -- A financial-position-only amendment can remain necessary after the
    -- source shift has already adopted the latest authoritative schedule. In
    -- that case the legacy changed-hours reader intentionally returns no row.
    -- Reconstruct the narrow Phase 3 carrier only from the already validated,
    -- transaction-local reconciliation unit: frozen B supplies the schedule
    -- to reverse and authoritative A supplies the replacement schedule.
    if v_row is null and v_reconciliation_unit is not null then
      if jsonb_typeof(v_reconciliation_b_schedule)<>'array'
         or jsonb_array_length(v_reconciliation_b_schedule)<>1
         or jsonb_typeof(v_reconciliation_a_schedule)<>'array'
         or jsonb_array_length(v_reconciliation_a_schedule)<>1 then
        raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
      end if;

      select jsonb_build_object(
        'shift_id', ns.id,
        'candidate_id', ns.candidate_id,
        'client_id', ns.client_id,
        'contract_id', ns.contract_id,
        'timesheet_id', ns.timesheet_id,
        'work_date', coalesce(
          nullif(v_reconciliation_a_schedule#>>'{0,date}','')::date,
          ((v_reconciliation_a_schedule#>>'{0,start_utc}')::timestamptz at time zone 'Europe/London')::date
        ),
        'week_ending_date', coalesce(ts.week_ending_date,ns.week_ending_date),
        'old_start_utc', v_reconciliation_b_schedule#>>'{0,start_utc}',
        'old_end_utc', v_reconciliation_b_schedule#>>'{0,end_utc}',
        'old_break_mins', coalesce(v_reconciliation_b_schedule#>>'{0,break_mins}','0'),
        'new_start_utc', v_reconciliation_a_schedule#>>'{0,start_utc}',
        'new_end_utc', v_reconciliation_a_schedule#>>'{0,end_utc}',
        'new_break_mins', coalesce(v_reconciliation_a_schedule#>>'{0,break_mins}','0'),
        'old_paid_minutes', greatest(0,
          floor(extract(epoch from (
            (v_reconciliation_b_schedule#>>'{0,end_utc}')::timestamptz
            - (v_reconciliation_b_schedule#>>'{0,start_utc}')::timestamptz
          )) / 60.0)::integer
          - coalesce((v_reconciliation_b_schedule#>>'{0,break_mins}')::integer,0)
        ),
        'new_paid_minutes', greatest(0,
          floor(extract(epoch from (
            (v_reconciliation_a_schedule#>>'{0,end_utc}')::timestamptz
            - (v_reconciliation_a_schedule#>>'{0,start_utc}')::timestamptz
          )) / 60.0)::integer
          - coalesce((v_reconciliation_a_schedule#>>'{0,break_mins}')::integer,0)
        ),
        'is_invoiced', false,
        'invoice_id_detected', null
      )
      into v_row
      from public.nhsp_shifts ns
      left join public.timesheets ts
        on ts.timesheet_id=ns.timesheet_id
       and ts.is_current=true
      where ns.id=nullif(v_reconciliation_unit->>'source_shift_id','')::uuid
        and ns.external_row_key=v_key
        and ns.source_system='NHSP'::public.hr_source_enum
        and ns.cancelled_at_utc is null
        and exists (
          select 1
          from public.hr_rows current_row
          where current_row.import_id=p_import_id
            and current_row.external_row_key=v_key
        )
      limit 1;
    end if;

    if v_row is null then
      raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: Phase 3 row not found for selected external_row_key=%', v_key;
    end if;

    -- Determine invoiced flag (from Phase3 row) for logging only
    v_is_invoiced :=
      case
        when lower(coalesce(v_row->>'is_invoiced','')) in ('true','1') then true
        else false
      end;

    begin
      v_invoice_id_detected := nullif(btrim(coalesce(v_row->>'invoice_id_detected','')), '')::uuid;
    exception when others then
      v_invoice_id_detected := null;
    end;

    -- Extract required mapping fields
    begin
      v_contract_id := (v_row->>'contract_id')::uuid;
      v_candidate_id := (v_row->>'candidate_id')::uuid;
      v_client_id := (v_row->>'client_id')::uuid;
      v_work_date := (v_row->>'work_date')::date;
    exception when others then
      raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: Phase 3 row missing/invalid contract_id/candidate_id/client_id/work_date for external_row_key=%', v_key;
    end;

    -- ---- Resolve week_ending_date (DO NOT assume Sunday) ----
    v_week_ending_date := null;
    v_base_timesheet_id := null;
    v_base_week_ending_date := null;

    -- ✅ reset inherited policy identity defaults for this key (avoid leaking previous key’s parent settings)
    v_parent_sheet_scope := 'WEEKLY'::public.timesheet_scope_enum;
    v_parent_submission_mode := 'MANUAL'::public.submission_mode_enum;

    -- 1) Prefer base timesheet week_ending_date when timesheet_id exists (authoritative)
    begin
      v_base_timesheet_id := nullif(btrim(coalesce(v_row->>'timesheet_id','')), '')::uuid;
    exception when others then
      v_base_timesheet_id := null;
    end;
    if v_base_timesheet_id is not null then
      select
        ts.week_ending_date,
        ts.sheet_scope,
        ts.submission_mode
      into
        v_base_week_ending_date,
        v_parent_sheet_scope,
        v_parent_submission_mode
      from public.timesheets ts
      where ts.timesheet_id = v_base_timesheet_id
        and ts.is_current = true
      limit 1;

      if v_base_week_ending_date is not null then
        v_week_ending_date := v_base_week_ending_date;
      end if;
    end if;

    -- 2) Next: use week_ending_date present on Phase3 row if provided
    if v_week_ending_date is null then
      begin
        v_week_ending_date := nullif(btrim(coalesce(v_row->>'week_ending_date','')), '')::date;
      exception when others then
        v_week_ending_date := null;
      end;
    end if;

    -- 3) Final fallback: derive from contracts.week_ending_weekday_snapshot (0=Sunday) and work_date
    if v_week_ending_date is null then
      select coalesce(ct.week_ending_weekday_snapshot, 0)
      into v_contract_week_ending_weekday_snapshot
      from public.contracts ct
      where ct.id = v_contract_id
      limit 1;

      v_work_dow := extract(dow from v_work_date)::int; -- 0=Sun..6=Sat
      v_we_delta := ((v_contract_week_ending_weekday_snapshot - v_work_dow + 7) % 7);
      v_week_ending_date := (v_work_date + v_we_delta)::date;
    end if;

    if v_week_ending_date is null then
      raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: Failed to resolve week_ending_date for external_row_key=% (contract_id=% work_date=%)', v_key, v_contract_id, v_work_date;
    end if;

    if v_base_timesheet_id is null then
      raise exception using message='CORRECTION_BASE_TIMESHEET_REQUIRED', errcode='P0001',
        detail=jsonb_build_object('code','CORRECTION_BASE_TIMESHEET_REQUIRED','external_row_key',v_key)::text;
    end if;

    begin
      v_new_paid_minutes := nullif(btrim(v_row ->> 'new_paid_minutes'), '')::integer;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception using message='CORRECTION_NEW_PAID_MINUTES_INVALID', errcode='22023',
        detail=jsonb_build_object('external_row_key',v_key,'new_paid_minutes',v_row ->> 'new_paid_minutes')::text;
    end;
    if v_new_paid_minutes is null then
      raise exception using message='CORRECTION_NEW_PAID_MINUTES_REQUIRED', errcode='P0001',
        detail=jsonb_build_object('external_row_key',v_key)::text;
    end if;
    if v_new_paid_minutes = 0 then
      raise exception using message='ZERO_HOURS_MUST_USE_CANCELLATION', errcode='P0001',
        detail=jsonb_build_object(
          'external_row_key',v_key,
          'required_action','CANCELLATION',
          'required_shape','REVERSAL_ONLY',
          'replacement_timesheet_required',false
        )::text;
    end if;

    select public.timesheet_correction_chain_scope_v1(
      v_base_timesheet_id, true, 32, 100
    ) into v_chain_scope;

    if coalesce((v_chain_scope->>'valid')::boolean,false) is not true
       and v_reconciliation_unit is null then
      raise exception using message='CORRECTION_CHAIN_UNRESOLVED', errcode='P0001', detail=v_chain_scope::text;
    end if;

    v_root_timesheet_id := nullif(v_chain_scope->>'root_timesheet_id','')::uuid;
    if v_root_timesheet_id is null then
      raise exception 'IMPORT_REVIEW_RECONCILIATION_PARENT_INVALID' using errcode='55000';
    end if;
    v_latest_positive_timesheet_id := coalesce(
      nullif(v_chain_scope->>'latest_positive_timesheet_id','')::uuid,
      v_base_timesheet_id
    );
    v_correction_operation_id := public._ctms_import_correction_operation_find_v1(
      p_import_id,
      v_root_timesheet_id,
      v_key,
      'CHANGED_HOURS',
      'REVERSAL_REPLACEMENT'
    );
    v_correction_financials_policy_envelope := public.correction_financials_policy_resolve_v1(
      v_base_timesheet_id,
      v_correction_operation_id,
      v_key,
      'CHANGED_HOURS',
      null::text,
      true,
      32
    );
    v_correction_financials_policy_envelope_fingerprint :=
      v_correction_financials_policy_envelope ->> 'envelope_fingerprint';

    if v_reconciliation_unit is null then
      select public.import_timesheet_financial_preflight_v1(
        p_timesheet_ids := array[v_base_timesheet_id]::uuid[],
        p_action := 'IMPORT_CHANGED_HOURS_CORRECTION',
        p_actor_user_id := p_actor_user_id,
        p_expected_state_json := jsonb_build_object(
          'chain_fingerprints',jsonb_build_object(v_root_timesheet_id::text,v_chain_scope->>'chain_fingerprint')
        ),
        p_lock_rows := true,
        p_max_scope := 100
      ) into v_financial_preflight;

      if coalesce((v_financial_preflight->>'allowed')::boolean,false) is not true then
        raise exception using message='IMPORT_FINANCIAL_PREFLIGHT_BLOCKED', errcode='P0001', detail=v_financial_preflight::text;
      end if;
    elsif nullif(current_setting('cloudtms.import_reconciliation_operation_id',true),'') is null
       or nullif(current_setting('cloudtms.import_reconciliation_request_hash',true),'') is null then
      raise exception 'IMPORT_REVIEW_RECONCILIATION_GUARD_REQUIRED' using errcode='55000';
    end if;

    -- Extract old/new shift times and break mins
    begin
      v_old_start_utc := nullif(v_row->>'old_start_utc','')::timestamptz;
      v_old_end_utc   := nullif(v_row->>'old_end_utc','')::timestamptz;
      v_new_start_utc := nullif(v_row->>'new_start_utc','')::timestamptz;
      v_new_end_utc   := nullif(v_row->>'new_end_utc','')::timestamptz;
    exception when others then
      raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: Phase 3 row has invalid timestamp fields for external_row_key=%', v_key;
    end;

    if v_old_start_utc is null or v_old_end_utc is null or v_new_start_utc is null or v_new_end_utc is null then
      raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: Phase 3 row missing old/new start/end timestamps for external_row_key=%', v_key;
    end if;

    begin
      v_old_break_mins := coalesce(nullif(v_row->>'old_break_mins','')::int, 0);
    exception when others then
      v_old_break_mins := 0;
    end;

    begin
      v_new_break_mins := coalesce(nullif(v_row->>'new_break_mins','')::int, 0);
    exception when others then
      v_new_break_mins := 0;
    end;

    -- ✅ Preserve string forms for deterministic correction_id hashing
    v_old_start_str := coalesce(v_row->>'old_start_utc', '');
    v_old_end_str   := coalesce(v_row->>'old_end_utc', '');
    v_new_start_str := coalesce(v_row->>'new_start_utc', '');
    v_new_end_str   := coalesce(v_row->>'new_end_utc', '');
    v_old_break_str := coalesce(v_row->>'old_break_mins', '');
    v_new_break_str := coalesce(v_row->>'new_break_mins', '');

    if v_reconciliation_unit is not null then
      if jsonb_typeof(v_reconciliation_unit->'A_schedule_json')<>'array'
         or jsonb_array_length(v_reconciliation_unit->'A_schedule_json')<>1 then
        raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
      end if;
      begin
        v_new_start_utc:=(v_reconciliation_unit#>>'{A_schedule_json,0,start_utc}')::timestamptz;
        v_new_end_utc:=(v_reconciliation_unit#>>'{A_schedule_json,0,end_utc}')::timestamptz;
        v_new_break_mins:=coalesce((v_reconciliation_unit#>>'{A_schedule_json,0,break_mins}')::integer,0);
      exception when others then
        raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
      end;
      if v_new_start_utc is null or v_new_end_utc is null or v_new_end_utc<=v_new_start_utc then
        raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
      end if;
      v_new_start_str:=v_reconciliation_unit#>>'{A_schedule_json,0,start_utc}';
      v_new_end_str:=v_reconciliation_unit#>>'{A_schedule_json,0,end_utc}';
      v_new_break_str:=coalesce(v_reconciliation_unit#>>'{A_schedule_json,0,break_mins}','0');
    end if;

    -- Compute correction_id (stable + deterministic)
    v_fnv_s :=
      coalesce(p_import_id::text,'') || '|' ||
      coalesce(v_key,'') || '|' ||
      coalesce(v_old_start_str,'') || '|' ||
      coalesce(v_new_start_str,'') || '|' ||
      coalesce(v_old_end_str,'')   || '|' ||
      coalesce(v_new_end_str,'')   || '|' ||
      coalesce(v_old_break_str,'') || '|' ||
      coalesce(v_new_break_str,'');

    v_fnv_h := 2166136261;
    for v_fnv_i in 1..char_length(v_fnv_s) loop
      v_fnv_h := (v_fnv_h # ascii(substring(v_fnv_s from v_fnv_i for 1)));
      v_fnv_h := (v_fnv_h * 16777619) % 4294967296;
    end loop;

    v_fnv_hex := lpad(lower(to_hex(v_fnv_h)), 8, '0');
    v_correction_id := 'chg:' || p_import_id::text || ':' || v_key || ':' || v_fnv_hex;

    -- Load contract + optional client/candidate display context for norms
    select
      c.display_site,
      c.ward_hint,
      c.role
    into
      v_contract_display_site,
      v_contract_ward_hint,
      v_contract_role
    from public.contracts c
    where c.id = v_contract_id
    limit 1;

    select cl.name
    into v_client_name
    from public.clients cl
    where cl.id = v_client_id
    limit 1;

    select cand.display_name, cand.tms_ref
    into v_candidate_display_name, v_candidate_tms_ref
    from public.candidates cand
    where cand.id = v_candidate_id
    limit 1;

    v_hospital_norm := lower(coalesce(v_contract_display_site, v_client_name, v_client_id::text));
    v_ward_norm := lower(coalesce(v_contract_ward_hint, 'contract'));
    v_role_norm := lower(coalesce(v_contract_role, 'weekly'));

    v_booking_base :=
      'scope=WEEKLY' || '|' ||
      'client_id=' || coalesce(v_client_id::text,'') || '|' ||
      'candidate_id=' || coalesce(v_candidate_id::text,'') || '|' ||
      'contract_id=' || coalesce(v_contract_id::text,'') || '|' ||
      'week_ending_date=' || coalesce(v_week_ending_date::text,'') || '|' ||
      'hospital=' || v_hospital_norm || '|' ||
      'ward=' || v_ward_norm || '|' ||
      'role=' || v_role_norm;

    -- Ensure base week exists (additional_seq=0, is_adjustment=false)
    v_base_week_id := null;

    select cw0.id
    into v_base_week_id
    from public.contract_weeks cw0
    where cw0.contract_id = v_contract_id
      and cw0.week_ending_date = v_week_ending_date
      and cw0.is_adjustment is false
      and coalesce(cw0.additional_seq, 0) = 0
    limit 1
    for update;

    if v_base_week_id is null then
      insert into public.contract_weeks(
        contract_id,
        week_ending_date,
        additional_seq,
        is_adjustment,
        status,
        created_at,
        updated_at
      )
      values (
        v_contract_id,
        v_week_ending_date,
        0,
        false,
        'SUBMITTED'::public.contract_week_status_enum,
        v_now,
        v_now
      )
      returning id into v_base_week_id;
    end if;

    -- Resolve reference number for this external_row_key (used on BOTH reversal + replacement schedules)
    v_ref_num := null;

    select ns_ref.ref_num
    into v_ref_num
    from public.nhsp_shifts ns_ref
    where ns_ref.source_system = 'NHSP'::public.hr_source_enum
      and ns_ref.external_row_key = v_key
    order by ns_ref.updated_at desc nulls last, ns_ref.created_at desc nulls last
    limit 1;

    if nullif(btrim(coalesce(v_ref_num,'')), '') is null then
      v_ref_num := nullif(btrim(coalesce(v_row->>'ref_num', v_row->>'reference', '')), '');
    end if;

    if nullif(btrim(coalesce(v_ref_num,'')), '') is null then
      v_ref_num := nullif(btrim(split_part(v_key, '|', 5)), '');
    end if;

    -- ✅ Resolve shift_id + previous import id (used for evidence on schedules)
    v_shift_id := null;
    v_shift_prev_import_id := null;

    select
      ns0.id,
      ns0.latest_import_id
    into
      v_shift_id,
      v_shift_prev_import_id
    from public.nhsp_shifts ns0
    where ns0.source_system = 'NHSP'::public.hr_source_enum
      and ns0.external_row_key = v_key
      and ns0.cancelled_at_utc is null
    order by ns0.updated_at desc nulls last, ns0.created_at desc nulls last
    limit 1;

    if v_shift_id is null then
      raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: cannot resolve nhsp_shifts.id (shift_id) for external_row_key=% (required for evidence linkage).', v_key;
    end if;

    -- ✅ Find current POS (replacement) for this shift
    select count(*)::int
    into v_existing_pos_count
    from public.timesheets tpos_cnt
    where tpos_cnt.is_adjustment is true
      and tpos_cnt.is_current is true
      and tpos_cnt.correction_kind = 'CHANGED_HOURS_REPLACEMENT'
      and jsonb_typeof(tpos_cnt.actual_schedule_json) = 'array'
      and tpos_cnt.actual_schedule_json @> jsonb_build_array(
        jsonb_build_object(
          'shift_id', v_shift_id::text,
          'external_row_key', v_key
        )
      );

    select
      tpos.timesheet_id,
      tpos.correction_id,
      tpos.actual_schedule_json,
      coalesce(tpos.candidate_hint_text,tpos.qr_payload_json,'{}'::jsonb)
    into
      v_existing_pos_ts_id,
      v_existing_pos_correction_id,
      v_existing_pos_schedule,
      v_existing_pos_hint
    from public.timesheets tpos
    where tpos.is_adjustment is true
      and tpos.is_current is true
      and tpos.correction_kind = 'CHANGED_HOURS_REPLACEMENT'
      and jsonb_typeof(tpos.actual_schedule_json) = 'array'
      and tpos.actual_schedule_json @> jsonb_build_array(
        jsonb_build_object(
          'shift_id', v_shift_id::text,
          'external_row_key', v_key
        )
      )
    order by tpos.updated_at desc nulls last, tpos.created_at desc nulls last
    limit 1;

    if v_existing_pos_ts_id is not null then
      select
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json
      into
        v_existing_pos_tf_locked_by_invoice_id,
        v_existing_pos_tf_invoice_breakdown_json
      from public.timesheets_financials tf
      where tf.timesheet_id = v_existing_pos_ts_id
        and tf.is_current = true
      order by tf.created_at desc
      limit 1;

      v_existing_pos_seg_invoice_id := null;

      begin
        select
          nullif(btrim(coalesce(s2.seg->>'invoice_locked_invoice_id','')), '')::uuid
        into v_existing_pos_seg_invoice_id
        from (
          select s2.seg
          from jsonb_array_elements(
            case
              when v_existing_pos_tf_invoice_breakdown_json is not null
               and jsonb_typeof(v_existing_pos_tf_invoice_breakdown_json) = 'object'
               and jsonb_typeof(v_existing_pos_tf_invoice_breakdown_json->'segments') = 'array'
              then v_existing_pos_tf_invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) as s2(seg)
          where nullif(btrim(coalesce(s2.seg->>'invoice_locked_invoice_id','')), '') is not null
          limit 1
        ) as s2;
      exception when others then
        v_existing_pos_seg_invoice_id := null;
      end;

      v_existing_pos_is_invoiced :=
        (v_existing_pos_tf_locked_by_invoice_id is not null)
        or (v_existing_pos_seg_invoice_id is not null);
    end if;

    -- ✅ Find current NEG (base reversal) for this shift (needed for edge-case deletion)
    select count(*)::int
    into v_existing_neg_count
    from public.timesheets tneg_cnt
    where tneg_cnt.is_adjustment is true
      and tneg_cnt.is_current is true
      and tneg_cnt.correction_kind = 'CHANGED_HOURS_REVERSAL'
      and jsonb_typeof(tneg_cnt.actual_schedule_json) = 'array'
      and tneg_cnt.actual_schedule_json @> jsonb_build_array(
        jsonb_build_object(
          'shift_id', v_shift_id::text,
          'external_row_key', v_key
        )
      );

    select
      tneg.timesheet_id,
      tneg.actual_schedule_json
    into
      v_existing_neg_ts_id,
      v_existing_neg_schedule
    from public.timesheets tneg
    where tneg.is_adjustment is true
      and tneg.is_current is true
      and tneg.correction_kind = 'CHANGED_HOURS_REVERSAL'
      and jsonb_typeof(tneg.actual_schedule_json) = 'array'
      and tneg.actual_schedule_json @> jsonb_build_array(
        jsonb_build_object(
          'shift_id', v_shift_id::text,
          'external_row_key', v_key
        )
      )
    order by tneg.updated_at desc nulls last, tneg.created_at desc nulls last
    limit 1;

    if v_existing_neg_ts_id is not null then
      select
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json
      into
        v_existing_neg_tf_locked_by_invoice_id,
        v_existing_neg_tf_invoice_breakdown_json
      from public.timesheets_financials tf
      where tf.timesheet_id = v_existing_neg_ts_id
        and tf.is_current = true
      order by tf.created_at desc
      limit 1;

      v_existing_neg_seg_invoice_id := null;

      begin
        select
          nullif(btrim(coalesce(s3.seg->>'invoice_locked_invoice_id','')), '')::uuid
        into v_existing_neg_seg_invoice_id
        from (
          select s3.seg
          from jsonb_array_elements(
            case
              when v_existing_neg_tf_invoice_breakdown_json is not null
               and jsonb_typeof(v_existing_neg_tf_invoice_breakdown_json) = 'object'
               and jsonb_typeof(v_existing_neg_tf_invoice_breakdown_json->'segments') = 'array'
              then v_existing_neg_tf_invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) as s3(seg)
          where nullif(btrim(coalesce(s3.seg->>'invoice_locked_invoice_id','')), '') is not null
          limit 1
        ) as s3;
      exception when others then
        v_existing_neg_seg_invoice_id := null;
      end;

      v_existing_neg_is_invoiced :=
        (v_existing_neg_tf_locked_by_invoice_id is not null)
        or (v_existing_neg_seg_invoice_id is not null);
    end if;

    -- Policy X retained-history rule: retain prior correction members even when
    -- the latest truth returns to the original schedule. The pair is amended to
    -- a zero residual only after its canonical pair lifecycle transition.
    v_deleted_redundant_pair := false;

    if v_reconciliation_unit is not null then
      if jsonb_typeof(v_reconciliation_b_schedule)<>'array' or jsonb_array_length(v_reconciliation_b_schedule)<>1 then
        raise exception 'IMPORT_REVIEW_EFFECTIVE_POSITION_NOT_STANDARD_REPRESENTABLE' using errcode='55000';
      end if;
      if jsonb_typeof(v_reconciliation_a_schedule)<>'array' or jsonb_array_length(v_reconciliation_a_schedule)<>1 then
        raise exception 'IMPORT_REVIEW_MUTABLE_GENERATION_EVIDENCE_UNPROVABLE' using errcode='55000';
      end if;
      v_existing_pos_old_start_str:=v_reconciliation_b_schedule#>>'{0,start_utc}';
      v_existing_pos_old_end_str:=v_reconciliation_b_schedule#>>'{0,end_utc}';
      v_existing_pos_old_break_str:=coalesce(v_reconciliation_b_schedule#>>'{0,break_mins}','0');
      v_old_start_utc:=v_existing_pos_old_start_str::timestamptz;
      v_old_end_utc:=v_existing_pos_old_end_str::timestamptz;
      v_old_break_mins:=v_existing_pos_old_break_str::integer;
      v_old_start_str:=v_existing_pos_old_start_str;
      v_old_end_str:=v_existing_pos_old_end_str;
      v_old_break_str:=v_existing_pos_old_break_str;
      if v_reconciliation_route='AMEND_EXISTING_REPLACEMENT' then
        v_reviewed_correction_id:=coalesce(v_reconciliation_unit->>'reviewed_existing_correction_id',v_reconciliation_unit->>'correction_id');
        v_correction_id:=v_reviewed_correction_id;
        if nullif(v_correction_id,'') is null then
          raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
        end if;
        v_repair_identity_mode:=coalesce(v_reconciliation_unit->>'repair_identity_mode','RETAIN_EXISTING_CORRECTION_ID');
        if v_repair_identity_mode not in ('RETAIN_EXISTING_CORRECTION_ID','FRESH_CORRECTION_ID_ARCHIVED_ROLE_IGNORED') then
          raise exception 'IMPORT_REVIEW_RECONCILIATION_UNIT_INVALID' using errcode='22023';
        end if;
        perform 1 from public.timesheets repair_scope
        where repair_scope.correction_id=v_reviewed_correction_id
          and repair_scope.is_current and repair_scope.archived_at_utc is null
          and repair_scope.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
        order by repair_scope.timesheet_id for update;
        if v_repair_identity_mode='FRESH_CORRECTION_ID_ARCHIVED_ROLE_IGNORED' then
          v_repair_operation_id:=current_setting('cloudtms.import_reconciliation_operation_id',true);
          if coalesce(v_repair_operation_id,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
            raise exception 'IMPORT_REVIEW_RECONCILIATION_GUARD_REQUIRED' using errcode='55000';
          end if;
          v_correction_id:='chg:repair:'||encode(extensions.digest(convert_to(concat_ws('|','archived-role-repair-v1',
            v_repair_operation_id,v_key,v_reviewed_correction_id,v_reconciliation_unit->>'reconciliation_fingerprint',
            coalesce(v_reconciliation_unit->'archived_history_roles','[]'::jsonb)::text),'UTF8'),'sha256'),'hex');
          perform 1 from public.timesheets repair_lock
          where repair_lock.timesheet_id in (select x.value::uuid from jsonb_array_elements_text(coalesce(v_reconciliation_unit->'M_active_member_ids','[]'::jsonb)) x(value))
          order by repair_lock.timesheet_id for update;
          update public.timesheets repair_member
          set correction_id=v_correction_id,updated_at=v_now
          where repair_member.timesheet_id in (select x.value::uuid from jsonb_array_elements_text(coalesce(v_reconciliation_unit->'M_active_member_ids','[]'::jsonb)) x(value))
            and repair_member.correction_id=v_reviewed_correction_id and repair_member.is_current and repair_member.archived_at_utc is null;
          if exists(select 1 from public.timesheets remaining where remaining.correction_id=v_reviewed_correction_id
            and remaining.is_current and remaining.archived_at_utc is null) then
            raise exception 'IMPORT_REVIEW_MUTABLE_GENERATION_REPAIR_POSTCONDITION_FAILED' using errcode='55000';
          end if;
        end if;
      end if;
      if v_reconciliation_route='CREATE_REVERSAL_REPLACEMENT'
         and v_existing_pos_ts_id is not null and v_existing_pos_is_invoiced then
        v_base_timesheet_id:=v_existing_pos_ts_id;
      elsif nullif(v_reconciliation_unit->>'parent_timesheet_id','') is not null then
        v_base_timesheet_id:=(v_reconciliation_unit->>'parent_timesheet_id')::uuid;
      end if;
      if not exists(select 1 from public.timesheets parent_ts
        where parent_ts.timesheet_id=v_base_timesheet_id and parent_ts.is_current and parent_ts.archived_at_utc is null) then
        raise exception 'IMPORT_REVIEW_RECONCILIATION_PARENT_INVALID' using errcode='55000';
      end if;
      perform 1 from public.timesheets parent_lock
      where parent_lock.timesheet_id=v_base_timesheet_id for update;
      v_existing_pos_ts_id:=null;
      v_existing_pos_is_invoiced:=false;
      v_existing_neg_ts_id:=null;
      v_existing_neg_is_invoiced:=false;
    end if;

        -- If the latest POS is invoiced, the new series must reverse POS (not the original base).
    if v_existing_pos_ts_id is not null and v_existing_pos_is_invoiced is true then
      v_existing_pos_seg := null;
      v_existing_pos_old_start_str := null;
      v_existing_pos_old_end_str := null;
      v_existing_pos_old_break_str := null;
      v_existing_pos_import_id := null;

      -- ✅ Treat the invoiced POS as the effective parent for policy inheritance
      v_base_timesheet_id := v_existing_pos_ts_id;

      select
        coalesce(ts.sheet_scope, 'WEEKLY'::public.timesheet_scope_enum),
        coalesce(ts.submission_mode, 'MANUAL'::public.submission_mode_enum)
      into
        v_parent_sheet_scope,
        v_parent_submission_mode
      from public.timesheets ts
      where ts.timesheet_id = v_base_timesheet_id
        and ts.is_current = true
      limit 1;

      if not found then
        v_parent_sheet_scope := 'WEEKLY'::public.timesheet_scope_enum;
        v_parent_submission_mode := 'MANUAL'::public.submission_mode_enum;
      end if;

      if v_existing_pos_schedule is not null and jsonb_typeof(v_existing_pos_schedule) = 'array' then
        v_existing_pos_seg := v_existing_pos_schedule->0;
      end if;

      if v_existing_pos_seg is not null then
        v_existing_pos_old_start_str := nullif(btrim(coalesce(v_existing_pos_seg->>'start_utc','')), '');
        v_existing_pos_old_end_str   := nullif(btrim(coalesce(v_existing_pos_seg->>'end_utc','')), '');
        v_existing_pos_old_break_str := nullif(btrim(coalesce(v_existing_pos_seg->>'break_mins','')), '');


        begin
          if (v_existing_pos_seg ? 'import_id')
             and (v_existing_pos_seg->>'import_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
            v_existing_pos_import_id := (v_existing_pos_seg->>'import_id')::uuid;
          else
            v_existing_pos_import_id := null;
          end if;
        exception when others then
          v_existing_pos_import_id := null;
        end;

        begin
          if v_existing_pos_old_start_str is not null then
            v_old_start_utc := v_existing_pos_old_start_str::timestamptz;
          end if;
        exception when others then
          null;
        end;

        begin
          if v_existing_pos_old_end_str is not null then
            v_old_end_utc := v_existing_pos_old_end_str::timestamptz;
          end if;
        exception when others then
          null;
        end;

        begin
          if v_existing_pos_old_break_str is not null and v_existing_pos_old_break_str ~ '^[0-9]+$' then
            v_old_break_mins := v_existing_pos_old_break_str::int;
          end if;
        exception when others then
          null;
        end;

        -- Override evidence "previous import" to the POS import_id when present (so new NEG shows correct raw row)
        if v_existing_pos_import_id is not null then
          v_shift_prev_import_id := v_existing_pos_import_id;
        end if;

        -- Recompute correction_id deterministically using POS-as-old values (stable strings)
        v_old_start_str := coalesce(v_existing_pos_old_start_str, v_old_start_str);
        v_old_end_str   := coalesce(v_existing_pos_old_end_str, v_old_end_str);
        v_old_break_str := coalesce(v_existing_pos_old_break_str, v_old_break_str);

        v_fnv_s :=
          coalesce(p_import_id::text,'') || '|' ||
          coalesce(v_key,'') || '|' ||
          coalesce(v_old_start_str,'') || '|' ||
          coalesce(v_new_start_str,'') || '|' ||
          coalesce(v_old_end_str,'')   || '|' ||
          coalesce(v_new_end_str,'')   || '|' ||
          coalesce(v_old_break_str,'') || '|' ||
          coalesce(v_new_break_str,'');

        v_fnv_h := 2166136261;
        for v_fnv_i in 1..char_length(v_fnv_s) loop
          v_fnv_h := (v_fnv_h # ascii(substring(v_fnv_s from v_fnv_i for 1)));
          v_fnv_h := (v_fnv_h * 16777619) % 4294967296;
        end loop;

        v_fnv_hex := lpad(lower(to_hex(v_fnv_h)), 8, '0');
        v_correction_id := 'chg:' || p_import_id::text || ':' || v_key || ':' || v_fnv_hex;
      end if;
    end if;

    -- Reset per-key outputs (so we can write a single meaningful audit entry)
    v_rev_ts_id := null;
    v_rep_ts_id := null;

    -- Best-effort invoice number lookup for UI using the current invoices.invoice_no column only.
    -- Do not reference legacy/stale invoice_number or number columns.
    v_invoice_number_text := null;

    if v_invoice_id_detected is not null then
      begin
        select nullif(btrim(coalesce(i.invoice_no::text, '')), '')
        into v_invoice_number_text
        from public.invoices as i
        where i.id = v_invoice_id_detected
        limit 1;
      exception when undefined_table then
        v_invoice_number_text := null;
      when others then
        v_invoice_number_text := null;
      end;
    end if;

    -- Paid minutes (prefer Phase3 row fields; fallback to timestamp diff - break mins)
    begin
      v_old_paid_minutes := nullif(btrim(coalesce(v_row->>'old_paid_minutes','')), '')::int;
    exception when others then
      v_old_paid_minutes := null;
    end;

    begin
      v_new_paid_minutes := nullif(btrim(coalesce(v_row->>'new_paid_minutes','')), '')::int;
    exception when others then
      v_new_paid_minutes := null;
    end;

    if v_old_paid_minutes is null then
      v_old_paid_minutes :=
        greatest(
          0,
          (extract(epoch from (v_old_end_utc - v_old_start_utc)) / 60)::int - coalesce(v_old_break_mins, 0)
        );
    end if;

    if v_new_paid_minutes is null then
      v_new_paid_minutes :=
        greatest(
          0,
          (extract(epoch from (v_new_end_utc - v_new_start_utc)) / 60)::int - coalesce(v_new_break_mins, 0)
        );
    end if;

    v_delta_paid_minutes := coalesce(v_new_paid_minutes, 0) - coalesce(v_old_paid_minutes, 0);

    v_key_ts := coalesce(v_key_ts, '[]'::jsonb);

    -- ✅ Case A: if latest POS exists and is NOT invoiced -> update POS in place and do NOT create new series.
    if v_existing_pos_ts_id is not null and v_existing_pos_is_invoiced is false then
      -- Use existing POS correction_id for audit consistency
      if nullif(btrim(coalesce(v_existing_pos_correction_id,'')), '') is not null then
        v_correction_id := v_existing_pos_correction_id;
      end if;

      -- Build replacement schedule from NEW truth (the new import)
      v_shift_date_ymd := to_char((v_new_start_utc at time zone 'Europe/London')::date, 'YYYY-MM-DD');

      v_schedule := jsonb_build_array(
        jsonb_build_object(
          'date', v_shift_date_ymd,
          'ward', nullif(btrim(coalesce(v_contract_ward_hint,'contract')), ''),
          'start_utc', v_new_start_utc::text,
          'end_utc', v_new_end_utc::text,
          'break_mins', greatest(0, v_new_break_mins),
          'ref_num', nullif(btrim(coalesce(v_ref_num,'')), ''),
          'shift_id', v_shift_id::text,
          'external_row_key', v_key,
          'import_id', p_import_id::text
        )
      );

      v_hint := jsonb_build_object(
        'import_correction', jsonb_build_object(
          'import_id', p_import_id::text,
          'external_row_key', v_key,
          'correction_id', v_correction_id,
          'correction_kind', 'CHANGED_HOURS_REPLACEMENT',
          'updated_from_import_id', p_import_id::text
        )
      );

      v_hint := v_hint || jsonb_build_object(
        'correction_financials_policy_envelope', v_correction_financials_policy_envelope,
        'correction_financials_policy_envelope_fingerprint', v_correction_financials_policy_envelope_fingerprint,
        'root_timesheet_id', v_root_timesheet_id::text,
        'latest_positive_timesheet_id', coalesce(v_latest_positive_timesheet_id,v_base_timesheet_id)::text
      );
      if v_reconciliation_unit is not null then
        v_hint:=v_hint||jsonb_build_object('import_authoritative_reconciliation',jsonb_build_object(
          'operation_id',current_setting('cloudtms.import_reconciliation_operation_id',true),
          'unit_fingerprint',v_reconciliation_unit->>'unit_fingerprint','route',v_reconciliation_route,
          'source_identity',v_key));
      end if;


      -- This is an amendment within the existing correction unit, not a new
      -- correction unit. Preserve the pair's shared frozen policy envelope and
      -- operation identity; otherwise the untouched reversal and amended
      -- replacement become two invalid one-member units. Only append bounded
      -- provenance for the import that amended the mutable replacement.
      if jsonb_typeof(v_existing_pos_hint) <> 'object'
         or jsonb_typeof(v_existing_pos_hint->'correction_financials_policy_envelope') <> 'object'
         or nullif(v_existing_pos_hint#>>'{correction_financials_policy_envelope,operation,operation_id}','') is null then
        raise exception using message='EXISTING_CORRECTION_POLICY_ENVELOPE_INVALID',errcode='P0001',
          detail=jsonb_build_object(
            'code','EXISTING_CORRECTION_POLICY_ENVELOPE_INVALID',
            'timesheet_id',v_existing_pos_ts_id
          )::text;
      end if;
      v_hint := v_existing_pos_hint || jsonb_build_object(
        'import_correction',coalesce(v_existing_pos_hint->'import_correction','{}'::jsonb)
          || jsonb_build_object('updated_from_import_id',p_import_id::text)
      );
      -- Lock the complete existing correction unit before validating or
      -- repairing its shared parent identity.
      perform 1
       from public.timesheets tlock
       where tlock.correction_id = v_existing_pos_correction_id
         and tlock.is_current = true
         and tlock.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
       order by tlock.timesheet_id
       for update;

      if (
        select count(*) = 2
          and count(*) filter (where pair_check.correction_kind='CHANGED_HOURS_REVERSAL') = 1
          and count(*) filter (where pair_check.correction_kind='CHANGED_HOURS_REPLACEMENT') = 1
        from public.timesheets pair_check
        where pair_check.correction_id=v_existing_pos_correction_id
          and pair_check.is_current=true
          and pair_check.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
      ) is not true then
        raise exception using message='CORRECTION_PAIR_INCOMPLETE',errcode='P0001',
          detail=jsonb_build_object('code','CORRECTION_PAIR_INCOMPLETE','correction_id',v_existing_pos_correction_id)::text;
      end if;

      if exists (
        select 1
        from public.timesheets pair_ts
        left join public.timesheets_financials pair_tf
          on pair_tf.timesheet_id=pair_ts.timesheet_id and pair_tf.is_current=true
        where pair_ts.correction_id=v_existing_pos_correction_id
          and pair_ts.is_current=true
          and pair_ts.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
          and (
            pair_ts.authorised_at_server is not null
            or pair_tf.authorised_at_utc is not null
            or pair_tf.paid_at_utc is not null
            or pair_tf.locked_by_invoice_id is not null
            or exists (select 1 from public.invoice_lines il where il.timesheet_id=pair_ts.timesheet_id)
          )
      ) then
        raise exception using message='CORRECTION_PAIR_LIFECYCLE_TRANSITION_REQUIRED', errcode='P0001',
          detail=jsonb_build_object(
            'code','CORRECTION_PAIR_LIFECYCLE_TRANSITION_REQUIRED',
            'correction_id',v_existing_pos_correction_id,
            'required_path','PAIR_UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE'
          )::text;
      end if;

      select pair_reversal.parent_timesheet_id
      into v_existing_pair_parent_timesheet_id
      from public.timesheets pair_reversal
      where pair_reversal.correction_id=v_existing_pos_correction_id
        and pair_reversal.is_current=true
        and pair_reversal.correction_kind='CHANGED_HOURS_REVERSAL'
      limit 1;

      if v_existing_pair_parent_timesheet_id is null then
        raise exception using message='CORRECTION_PAIR_PARENT_MISSING',errcode='P0001',
          detail=jsonb_build_object(
            'code','CORRECTION_PAIR_PARENT_MISSING',
            'correction_id',v_existing_pos_correction_id
          )::text;
      end if;

      -- A previous implementation could rewrite only the mutable replacement
      -- to the latest base timesheet during replay, splitting the pair's
      -- parent identity. Repair only that exact, complete, mutable pair before
      -- continuing; lifecycle/frozen evidence was rejected above.
      update public.timesheets pair_replacement
      set parent_timesheet_id=v_existing_pair_parent_timesheet_id,
          updated_at=v_now
      where pair_replacement.correction_id=v_existing_pos_correction_id
        and pair_replacement.is_current=true
        and pair_replacement.correction_kind='CHANGED_HOURS_REPLACEMENT'
        and pair_replacement.parent_timesheet_id is distinct from v_existing_pair_parent_timesheet_id;

      if (
        select count(*) = 2
          and count(*) filter (where pair_check.correction_kind='CHANGED_HOURS_REVERSAL') = 1
          and count(*) filter (where pair_check.correction_kind='CHANGED_HOURS_REPLACEMENT') = 1
          and count(distinct pair_check.parent_timesheet_id) = 1
          and count(pair_check.parent_timesheet_id) = 2
        from public.timesheets pair_check
        where pair_check.correction_id=v_existing_pos_correction_id
          and pair_check.is_current=true
          and pair_check.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
      ) is not true then
        raise exception using message='CORRECTION_PAIR_INCOMPLETE',errcode='P0001',
          detail=jsonb_build_object('code','CORRECTION_PAIR_INCOMPLETE','correction_id',v_existing_pos_correction_id)::text;
      end if;

      update public.timesheets tup
      set
        actual_schedule_json = v_schedule,
        qr_payload_json = v_hint,
        candidate_hint_text = v_hint,

        -- ✅ inherit policy identity from base timesheet
        sheet_scope = v_parent_sheet_scope,
        submission_mode = v_parent_submission_mode,

        updated_at = v_now
      where tup.timesheet_id = v_existing_pos_ts_id;

      v_rep_ts_id := v_existing_pos_ts_id;
      v_updated_existing_replacement := true;

      v_upd_count := v_upd_count + 1;
      v_updated_ts_ids := array_append(v_updated_ts_ids, v_existing_pos_ts_id);

      v_key_ts := v_key_ts || jsonb_build_array(jsonb_build_object(
        'kind', 'CHANGED_HOURS_REPLACEMENT',
        'timesheet_id', v_existing_pos_ts_id::text,
        'op', 'UPDATED_IN_PLACE'
      ));
    end if;

    -- Two correction kinds per selected key: reversal + replacement
    if v_updated_existing_replacement is false then
      foreach v_kind in array array['CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT'] loop
        v_kind_op := null;

        if v_kind = 'CHANGED_HOURS_REVERSAL' then
          v_seg_start_utc := v_old_start_utc;
          v_seg_end_utc := v_old_end_utc;
          v_seg_break_mins := greatest(0, v_old_break_mins);
          v_schedule_import_id := v_shift_prev_import_id;
        else
          v_seg_start_utc := v_new_start_utc;
          v_seg_end_utc := v_new_end_utc;
          v_seg_break_mins := greatest(0, v_new_break_mins);
          v_schedule_import_id := p_import_id;
        end if;

        v_shift_date_ymd := to_char((v_seg_start_utc at time zone 'Europe/London')::date, 'YYYY-MM-DD');

        v_hint := jsonb_build_object(
          'import_correction', jsonb_build_object(
            'import_id', p_import_id::text,
            'external_row_key', v_key,
            'correction_id', v_correction_id,
            'correction_kind', v_kind
          )
        );

        v_hint := v_hint || jsonb_build_object(
          'correction_financials_policy_envelope', v_correction_financials_policy_envelope,
          'correction_financials_policy_envelope_fingerprint', v_correction_financials_policy_envelope_fingerprint,
          'root_timesheet_id', v_root_timesheet_id::text,
          'latest_positive_timesheet_id', coalesce(v_latest_positive_timesheet_id,v_base_timesheet_id)::text
        );
        if v_reconciliation_unit is not null then
          v_hint:=v_hint||jsonb_build_object('import_authoritative_reconciliation',jsonb_build_object(
            'operation_id',current_setting('cloudtms.import_reconciliation_operation_id',true),
            'unit_fingerprint',v_reconciliation_unit->>'unit_fingerprint','route',v_reconciliation_route,
            'source_identity',v_key));
        end if;


        v_shift_label := 'weekly-correction-' || lower(v_kind) || '-' || v_correction_id;

        v_shift_label_norm :=
          regexp_replace(
            regexp_replace(lower(trim(v_shift_label)), '\s+', ' ', 'g'),
            '[^\w\s\-@&\/,:]',
            '',
            'g'
          );

        -- ✅ booking_id must be UNIQUE per correction kind (REVERSAL vs REPLACEMENT)
        v_hash_hex := substring(
          encode(
            extensions.digest(
              convert_to(
                (v_booking_base || '|shift_label_norm=' || coalesce(v_shift_label_norm, '')),
                'utf8'
              ),
              'sha256'::text
            ),
            'hex'
          )
          from 1 for 16
        );
        v_booking_id := 'bk_' || v_hash_hex;

        -- ✅ Schedule includes evidence linkage (shift_id, external_row_key, import_id)
        if v_reconciliation_unit is not null then
          v_schedule:=case when v_kind='CHANGED_HOURS_REVERSAL'
            then v_reconciliation_b_schedule else v_reconciliation_a_schedule end;
        else
          v_schedule := jsonb_build_array(
            jsonb_build_object(
              'date', v_shift_date_ymd,
              'ward', nullif(btrim(coalesce(v_contract_ward_hint,'contract')), ''),
              'start_utc', v_seg_start_utc::text,
              'end_utc', v_seg_end_utc::text,
              'break_mins', v_seg_break_mins,
              'ref_num', nullif(btrim(coalesce(v_ref_num,'')), ''),
              'shift_id', v_shift_id::text,
              'external_row_key', v_key,
              'import_id', case when v_schedule_import_id is null then null else v_schedule_import_id::text end
            )
          );
        end if;

        -- Idempotency: reuse existing correction timesheet (unique on correction_id+kind)
        v_existing_ts_id := null;

        select t.timesheet_id
        into v_existing_ts_id
        from public.timesheets t
        where t.correction_id = v_correction_id
          and t.correction_kind = v_kind
          and (v_reconciliation_unit is null or (t.is_current and t.archived_at_utc is null))
        order by t.is_current desc, t.version desc
        limit 1
        for update;

        if v_existing_ts_id is not null then
          -- Ensure there is an adjustment contract_week linked; reuse it if present.
          v_existing_cw_id := null;
          v_existing_cw_seq := null;
          v_existing_cw_is_adjustment := null;

          select
            cw.id,
            cw.additional_seq,
            cw.is_adjustment
          into
            v_existing_cw_id,
            v_existing_cw_seq,
            v_existing_cw_is_adjustment
          from public.contract_weeks cw
          where cw.timesheet_id = v_existing_ts_id
            and cw.contract_id = v_contract_id
            and cw.week_ending_date = v_week_ending_date
          limit 1
          for update;

          if v_reconciliation_unit is not null and (select count(*) from public.contract_weeks cw
            where cw.timesheet_id=v_existing_ts_id and cw.contract_id=v_contract_id
              and cw.week_ending_date=v_week_ending_date)>1 then
            raise exception 'IMPORT_REVIEW_MUTABLE_GENERATION_CONTRACT_WEEK_AMBIGUOUS' using errcode='55000';
          end if;

          if v_existing_cw_id is not null then
            if v_existing_cw_is_adjustment is not true or coalesce(v_existing_cw_seq,0) <= 0 then
              update public.contract_weeks cw2
              set
                is_adjustment = true,
                status = 'SUBMITTED'::public.contract_week_status_enum,
                updated_at = v_now
              where cw2.id = v_existing_cw_id;
            end if;

             update public.timesheets t2
            set
              is_current = true,
              status = 'RECEIVED'::public.timesheet_status_enum,
              actual_schedule_json = v_schedule,
              qr_payload_json = v_hint,
              candidate_hint_text = v_hint,

              -- ✅ inherit policy identity from base timesheet
              sheet_scope = v_parent_sheet_scope,
              submission_mode = v_parent_submission_mode,
              parent_timesheet_id = v_base_timesheet_id,
              week_ending_date = v_week_ending_date,
              contract_id = v_contract_id,
              is_adjustment = true,
              correction_id = v_correction_id,
              correction_kind = v_kind,
              adjustment_origin = 'IMPORT_CORRECTION',

              updated_at = v_now
            where t2.timesheet_id = v_existing_ts_id;

            if v_kind = 'CHANGED_HOURS_REVERSAL' then
              v_rev_ts_id := v_existing_ts_id;
            else
              v_rep_ts_id := v_existing_ts_id;
            end if;

            v_upd_count := v_upd_count + 1;
            v_updated_ts_ids := array_append(v_updated_ts_ids, v_existing_ts_id);
            v_kind_op := 'UPDATED';

            v_key_ts := v_key_ts || jsonb_build_array(jsonb_build_object(
              'kind', v_kind,
              'timesheet_id', v_existing_ts_id::text,
              'op', v_kind_op
            ));

            continue;
          end if;

          -- If we have an existing correction timesheet but no linked contract_week, create one.
          select coalesce(max(cw3.additional_seq), 0) + 1
          into v_next_additional_seq
          from public.contract_weeks cw3
          where cw3.contract_id = v_contract_id
            and cw3.week_ending_date = v_week_ending_date
            and cw3.is_adjustment is true;

          insert into public.contract_weeks(
            contract_id,
            week_ending_date,
            additional_seq,
            is_adjustment,
            status,
            timesheet_id,
            created_at,
            updated_at
          )
          values (
            v_contract_id,
            v_week_ending_date,
            v_next_additional_seq,
            true,
            'SUBMITTED'::public.contract_week_status_enum,
            v_existing_ts_id,
            v_now,
            v_now
          )
          returning id into v_existing_cw_id;
          update public.timesheets t2b
          set
            is_current = true,
            status = 'RECEIVED'::public.timesheet_status_enum,
            actual_schedule_json = v_schedule,
            qr_payload_json = v_hint,
            candidate_hint_text = v_hint,

            -- ✅ inherit policy identity from base timesheet
            sheet_scope = v_parent_sheet_scope,
            submission_mode = v_parent_submission_mode,
            parent_timesheet_id = v_base_timesheet_id,
            week_ending_date = v_week_ending_date,
            contract_id = v_contract_id,
            is_adjustment = true,
            correction_id = v_correction_id,
            correction_kind = v_kind,
            adjustment_origin = 'IMPORT_CORRECTION',

            updated_at = v_now
          where t2b.timesheet_id = v_existing_ts_id;

          if v_kind = 'CHANGED_HOURS_REVERSAL' then
            v_rev_ts_id := v_existing_ts_id;
          else
            v_rep_ts_id := v_existing_ts_id;
          end if;

          v_upd_count := v_upd_count + 1;
          v_updated_ts_ids := array_append(v_updated_ts_ids, v_existing_ts_id);
          v_kind_op := 'UPDATED';

          v_key_ts := v_key_ts || jsonb_build_array(jsonb_build_object(
            'kind', v_kind,
            'timesheet_id', v_existing_ts_id::text,
            'op', v_kind_op
          ));

          continue;
        end if;

        -- No existing correction timesheet: create new adjustment contract_week + timesheet
        v_ts_id := null;

        for v_try in 1..5 loop
          select coalesce(max(cw4.additional_seq), 0) + 1
          into v_next_additional_seq
          from public.contract_weeks cw4
          where cw4.contract_id = v_contract_id
            and cw4.week_ending_date = v_week_ending_date
            and cw4.is_adjustment is true;

          begin
               insert into public.timesheets(
              booking_id,
              version,
              is_current,
              status,
              occupant_key_norm,
              hospital_norm,
              ward_norm,
              job_title_norm,
              shift_label_norm,
              week_ending_date,
              contract_id,
              sheet_scope,
              submission_mode,
              line_type,
              manual_pdf_r2_key,
              actual_schedule_json,
              additional_units_week,
              additional_units_per_day,
              day_references_json,
              qr_status,
              qr_token,
              qr_generated_at,
              qr_scanned_at,
              qr_scan_info_json,
              qr_r2_key,
              qr_payload_json,
              created_at,
              updated_at,
              is_adjustment,
              parent_timesheet_id,
              candidate_hint_text,
              correction_id,
              correction_kind,
              adjustment_origin
            )
            values (
              v_booking_id,
              1,
              true,
              'RECEIVED'::public.timesheet_status_enum,
              lower(coalesce(v_candidate_tms_ref, v_candidate_display_name, v_candidate_id::text)),
              lower(coalesce(v_contract_display_site, v_client_name, v_client_id::text)),
              lower(coalesce(v_contract_ward_hint,'contract')),
              lower(coalesce(v_contract_role,'weekly')),
              v_shift_label_norm,
              v_week_ending_date,
              v_contract_id,

              -- ✅ inherit policy identity from base timesheet
              v_parent_sheet_scope,
              v_parent_submission_mode,

              'HOURS'::public.timesheet_line_type_enum,
              null,
              v_schedule,
              '{}'::jsonb,
              '{}'::jsonb,
              '{}'::jsonb,
              null,
              null,
              null,
              null,
              '{}'::jsonb,
              null,
              v_hint,
              v_now,
              v_now,
              true,

              -- ✅ link to parent/base timesheet (may be null if not provided)
              v_base_timesheet_id,

              v_hint,
              v_correction_id,
              v_kind,
              'IMPORT_CORRECTION'
            )
            returning timesheet_id into v_ts_id;


            if v_kind = 'CHANGED_HOURS_REVERSAL' then
              v_rev_ts_id := v_ts_id;
            else
              v_rep_ts_id := v_ts_id;
            end if;

            insert into public.contract_weeks(
              contract_id,
              week_ending_date,
              additional_seq,
              is_adjustment,
              status,
              timesheet_id,
              created_at,
              updated_at
            )
            values (
              v_contract_id,
              v_week_ending_date,
              v_next_additional_seq,
              true,
              'SUBMITTED'::public.contract_week_status_enum,
              v_ts_id,
              v_now,
              v_now
            );

            v_ins_count := v_ins_count + 1;
            v_created_ts_ids := array_append(v_created_ts_ids, v_ts_id);
            v_kind_op := 'CREATED';

            v_key_ts := v_key_ts || jsonb_build_array(jsonb_build_object(
              'kind', v_kind,
              'timesheet_id', v_ts_id::text,
              'op', v_kind_op
            ));

            exit;
          exception
            when unique_violation then
              v_ts_id := null;
          end;

          exit when v_ts_id is not null;
        end loop;

        if v_ts_id is null then
          raise exception 'nhsp_weekly_phase3_apply_adjustment_truth: Failed to allocate correction timesheet/contract_week after retries (external_row_key=% kind=%)', v_key, v_kind;
        end if;

      end loop; -- kind loop
    end if; -- updated_existing_replacement

    if v_reconciliation_unit is not null then
      if v_rev_ts_id is null or v_rep_ts_id is null then
        raise exception 'IMPORT_REVIEW_APPLY_POSTCONDITION_FAILED' using errcode='55000',
          detail=jsonb_build_object('reason_code','CORRECTION_MEMBER_SET_INCOMPLETE','source_identity',v_key)::text;
      end if;
      if (select count(*)=2
            and count(*) filter(where t.correction_kind='CHANGED_HOURS_REVERSAL')=1
            and count(*) filter(where t.correction_kind='CHANGED_HOURS_REPLACEMENT')=1
            and count(distinct t.parent_timesheet_id)=1
            and bool_and(t.parent_timesheet_id=v_base_timesheet_id)
            and bool_and(t.contract_id=v_contract_id and t.week_ending_date=v_week_ending_date)
            and bool_and(t.adjustment_origin='IMPORT_CORRECTION' and coalesce(t.is_adjustment,false))
            and bool_and(t.candidate_hint_text#>>'{import_authoritative_reconciliation,operation_id}'=
              current_setting('cloudtms.import_reconciliation_operation_id',true))
            and bool_and(t.candidate_hint_text#>>'{import_authoritative_reconciliation,unit_fingerprint}'=
              v_reconciliation_unit->>'unit_fingerprint')
            and bool_and(case when t.correction_kind='CHANGED_HOURS_REVERSAL'
              then t.actual_schedule_json is not distinct from v_reconciliation_b_schedule
              else t.actual_schedule_json is not distinct from v_reconciliation_a_schedule end)
          from public.timesheets t
          where t.correction_id=v_correction_id and t.is_current and t.archived_at_utc is null
            and t.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')) is not true
         or exists(select 1 from public.timesheets t
           where t.timesheet_id in (v_rev_ts_id,v_rep_ts_id)
             and (select count(*) from public.contract_weeks cw where cw.timesheet_id=t.timesheet_id
               and cw.contract_id=v_contract_id and cw.week_ending_date=v_week_ending_date)<>1)
         or (v_repair_identity_mode='FRESH_CORRECTION_ID_ARCHIVED_ROLE_IGNORED' and exists(
           select 1 from public.timesheets t where t.correction_id=v_reviewed_correction_id
             and t.is_current and t.archived_at_utc is null)) then
        raise exception 'IMPORT_REVIEW_MUTABLE_GENERATION_REPAIR_POSTCONDITION_FAILED' using errcode='55000';
      end if;
      with applied as (
        select jsonb_build_object(
          'correction_id',v_correction_id,
          'reversal_timesheet_id',v_rev_ts_id,
          'replacement_timesheet_id',v_rep_ts_id,
          'M_active_member_ids',jsonb_build_array(v_rev_ts_id,v_rep_ts_id),
          'applied_member_ids',jsonb_build_array(v_rev_ts_id,v_rep_ts_id),
          'parent_timesheet_id',v_base_timesheet_id,
          'repair_identity_mode',coalesce(v_repair_identity_mode,'CREATE_NEW_GENERATION'),
          'reviewed_unit_fingerprint',v_reconciliation_unit->>'unit_fingerprint',
          'reconciliation_fingerprint',v_reconciliation_unit->>'reconciliation_fingerprint'
        ) value
      )
      update pg_temp.import_review_reconciliation_units_v1 u
      set unit_json=u.unit_json||applied.value||jsonb_build_object(
        'applied_result_fingerprint',encode(extensions.digest(convert_to(applied.value::text,'UTF8'),'sha256'),'hex'))
      from applied where u.source_identity=v_key;
    end if;

    -- ─────────────────────────────────────────────
    -- ✅ User-facing audit entries (timesheet modal + invoice history)
    -- ─────────────────────────────────────────────
    begin
      -- Timesheet audit: reversal
      if v_rev_ts_id is not null then
        perform public._audit_insert(
          'timesheets',
          v_rev_ts_id::text,
          'NHSP_IMPORT_CORRECTION_APPLIED',
          null,
          jsonb_build_object(
            'import_id', p_import_id::text,
            'evidence_import_id', case when v_shift_prev_import_id is null then null else v_shift_prev_import_id::text end,
            'external_row_key', v_key,
            'shift_id', v_shift_id::text,
            'work_date', v_work_date::text,
            'ref_num', nullif(btrim(coalesce(v_ref_num,'')), ''),
            'invoice_id', case when v_invoice_id_detected is null then null else v_invoice_id_detected::text end,
            'invoice_number', v_invoice_number_text,
            'correction_id', v_correction_id,
            'correction_kind', 'CHANGED_HOURS_REVERSAL',
            'old_paid_minutes', v_old_paid_minutes,
            'new_paid_minutes', v_new_paid_minutes,
            'delta_paid_minutes', v_delta_paid_minutes,
            'counterpart_timesheet_id', case when v_rep_ts_id is null then null else v_rep_ts_id::text end,
            'op', case
                    when v_rev_ts_id = any(coalesce(v_created_ts_ids, '{}'::uuid[])) then 'CREATED'
                    when v_rev_ts_id = any(coalesce(v_updated_ts_ids, '{}'::uuid[])) then 'UPDATED'
                    else 'UPSERT'
                  end
          ),
          'IMPORT_CORRECTION',
          p_actor_user_id
        );
      end if;

      -- Timesheet audit: replacement
      if v_rep_ts_id is not null then
        perform public._audit_insert(
          'timesheets',
          v_rep_ts_id::text,
          'NHSP_IMPORT_CORRECTION_APPLIED',
          null,
          jsonb_build_object(
            'import_id', p_import_id::text,
            'evidence_import_id', p_import_id::text,
            'external_row_key', v_key,
            'shift_id', v_shift_id::text,
            'work_date', v_work_date::text,
            'ref_num', nullif(btrim(coalesce(v_ref_num,'')), ''),
            'invoice_id', case when v_invoice_id_detected is null then null else v_invoice_id_detected::text end,
            'invoice_number', v_invoice_number_text,
            'correction_id', v_correction_id,
            'correction_kind', 'CHANGED_HOURS_REPLACEMENT',
            'old_paid_minutes', v_old_paid_minutes,
            'new_paid_minutes', v_new_paid_minutes,
            'delta_paid_minutes', v_delta_paid_minutes,
            'counterpart_timesheet_id', case when v_rev_ts_id is null then null else v_rev_ts_id::text end,
            'op', case
                    when v_rep_ts_id = any(coalesce(v_created_ts_ids, '{}'::uuid[])) then 'CREATED'
                    when v_rep_ts_id = any(coalesce(v_updated_ts_ids, '{}'::uuid[])) then 'UPDATED'
                    else 'UPSERT'
                  end
          ),
          'IMPORT_CORRECTION',
          p_actor_user_id
        );
      end if;

      -- Invoice history entry
      if v_invoice_id_detected is not null then
        perform public._inv_write_audit(
          p_actor_user_id,
          'NHSP_IMPORT_CORRECTION_APPLIED',
          jsonb_build_object(
            'import_id', p_import_id::text,
            'external_row_key', v_key,
            'shift_id', v_shift_id::text,
            'work_date', v_work_date::text,
            'ref_num', nullif(btrim(coalesce(v_ref_num,'')), ''),
            'invoice_id', v_invoice_id_detected::text,
            'invoice_number', v_invoice_number_text,
            'correction_id', v_correction_id,
            'old_paid_minutes', v_old_paid_minutes,
            'new_paid_minutes', v_new_paid_minutes,
            'delta_paid_minutes', v_delta_paid_minutes,
            'reversal_timesheet_id', case when v_rev_ts_id is null then null else v_rev_ts_id::text end,
            'replacement_timesheet_id', case when v_rep_ts_id is null then null else v_rep_ts_id::text end,
            'replacement_updated_in_place', v_updated_existing_replacement,
            'redundant_pair_deleted', v_deleted_redundant_pair
          ),
          'invoices',
          v_invoice_id_detected::text,
          null,
          'IMPORT_CORRECTION',
          null,
          null,
          null
        );
      end if;
    exception when others then
      null;
    end;

    if v_sample_n < 20 then
      v_sample := v_sample || jsonb_build_array(jsonb_build_object(
        'external_row_key', v_key,
        'is_invoiced', v_is_invoiced,
        'invoice_id_detected', case when v_invoice_id_detected is null then null else v_invoice_id_detected::text end,
        'week_ending_date', v_week_ending_date::text,
        'base_timesheet_id', case when v_base_timesheet_id is null then null else v_base_timesheet_id::text end,
        'correction_id', v_correction_id,
        'replacement_updated_in_place', v_updated_existing_replacement,
        'redundant_pair_deleted', v_deleted_redundant_pair,
        'timesheets', v_key_ts
      ));
      v_sample_n := v_sample_n + 1;
    end if;

  end loop; -- selected keys loop

  perform public._imp_debug_audit(
    p_actor_user_id,
    'NHSP_CORRECTION_SERIES_DEBUG',
    jsonb_build_object(
      'import_id', p_import_id::text,
      'selected_count', coalesce(array_length(v_selected_keys, 1), 0),
      'inserted_count', v_ins_count,
      'updated_count', v_upd_count,
      'created_timesheet_ids_count', coalesce(array_length(v_created_ts_ids, 1), 0),
      'updated_timesheet_ids_count', coalesce(array_length(v_updated_ts_ids, 1), 0),
      'sample', v_sample
    ),
    'hr_imports',
    p_import_id::text,
    null,
    null,
    null,
    null
  );

  return jsonb_build_object(
    'import_id', p_import_id,
    'selected_count', coalesce(array_length(v_selected_keys, 1), 0),
    'skipped_count', v_skipped_count,
    'inserted_count', v_ins_count,
    'updated_count', v_upd_count,
    'created_timesheet_ids', to_jsonb(coalesce(v_created_ts_ids, '{}'::uuid[])),
    'updated_timesheet_ids', to_jsonb(coalesce(v_updated_ts_ids, '{}'::uuid[]))
  );

exception when others then
  get stacked diagnostics v_sqlstate = returned_sqlstate, v_err = message_text;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'NHSP_CORRECTION_SERIES_ERROR',
      jsonb_build_object(
        'import_id', p_import_id::text,
        'last_external_row_key', v_last_key,
        'selected_count', coalesce(array_length(v_selected_keys, 1), 0),
        'inserted_count', v_ins_count,
        'updated_count', v_upd_count,
        'sqlstate', v_sqlstate,
        'error', v_err
      ),
      'hr_imports',
      p_import_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  raise;
end;
$function$;

-- nhsp_weekly_review_preview_v1(uuid,text,integer)
CREATE OR REPLACE FUNCTION public.nhsp_weekly_review_preview_v1(p_import_id uuid, p_after_action_id text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_limit integer:=least(greatest(coalesce(p_limit,100),1),200); v_state public.import_review_states%rowtype; v_actions jsonb; v_last text;
begin
  select * into v_state from public.import_review_states where import_id=p_import_id;
  if not found then raise exception 'IMPORT_REVIEW_NOT_FOUND' using errcode='P0002'; end if;
  with p as (select * from public.import_review_decisions d where d.import_id=p_import_id and d.is_current
    and d.action_kind in ('INCLUDE_SHIFT','APPLY_AMENDMENT','APPLY_CANCELLATION','ADVISORY','NO_ACTION')
    and (p_after_action_id is null or d.action_id>p_after_action_id) order by d.action_id limit v_limit+1),
  l as (select * from p order by action_id limit v_limit)
  select coalesce(jsonb_agg(jsonb_build_object('action_id',action_id,'action_kind',action_kind,'category',action_category,
    'evidence_fingerprint',evidence_fingerprint,'selectable',selectable,'default_selected',default_selected,'selected',selected,
    'blocking',blocking,'summary',summary_json) order by action_id),'[]'),max(action_id) into v_actions,v_last from l;
  return jsonb_build_object('ok',true,'import_id',p_import_id,'state_version',v_state.state_version,
    'preview_generation',v_state.preview_generation,'preview_fingerprint',v_state.preview_fingerprint,'actions',v_actions,
    'next_cursor',case when jsonb_array_length(v_actions)=v_limit then v_last end);
end $function$;

-- outbox_unified_delete_many(jsonb,uuid,text)
CREATE OR REPLACE FUNCTION public.outbox_unified_delete_many(p_items jsonb, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text := nullif(btrim(coalesce(p_reason,'')), '');
  v_item jsonb;
  v_channel text;
  v_id_text text;
  v_id uuid;

  v_result jsonb;
  v_results jsonb := '[]'::jsonb;

  v_requested int := 0;
  v_deleted int := 0;
  v_blocked_already_sent int := 0;
  v_blocked_invalid_status int := 0;
  v_not_found int := 0;
  v_other_blocked int := 0;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'items array required';
  end if;

  for v_item in
    select jbe.value
    from jsonb_array_elements(p_items) as jbe(value)
  loop
    v_requested := v_requested + 1;

    v_channel := nullif(upper(btrim(coalesce(v_item->>'channel',''))), '');
    v_id_text := nullif(btrim(coalesce(v_item->>'id','')), '');

    if v_channel is null or v_id_text is null then
      v_results := v_results || jsonb_build_array(
        jsonb_build_object(
          'ok', true,
          'deleted', false,
          'reason', 'INVALID_ITEM',
          'row', jsonb_build_object(
            'channel', v_channel,
            'outbox_id', v_id_text
          )
        )
      );
      v_other_blocked := v_other_blocked + 1;
      continue;
    end if;

    begin
      v_id := v_id_text::uuid;
    exception
      when others then
        v_results := v_results || jsonb_build_array(
          jsonb_build_object(
            'ok', true,
            'deleted', false,
            'reason', 'INVALID_ID',
            'row', jsonb_build_object(
              'channel', v_channel,
              'outbox_id', v_id_text
            )
          )
        );
        v_other_blocked := v_other_blocked + 1;
        continue;
    end;

    v_result := public.outbox_unified_delete(
      v_channel,
      v_id,
      p_actor_user_id,
      v_reason
    );

    v_results := v_results || jsonb_build_array(v_result);

    if coalesce((v_result->>'deleted')::boolean, false) = true then
      v_deleted := v_deleted + 1;
    else
      case upper(coalesce(v_result->>'reason',''))
        when 'NOT_FOUND' then
          v_not_found := v_not_found + 1;
        when 'ALREADY_SENT', 'ALREADY_DELIVERED', 'ALREADY_READ' then
          v_blocked_already_sent := v_blocked_already_sent + 1;
        when 'INVALID_STATUS' then
          v_blocked_invalid_status := v_blocked_invalid_status + 1;
        else
          v_other_blocked := v_other_blocked + 1;
      end case;
    end if;
  end loop;

  perform public._audit_insert(
    'outbox_batch',
    null,
    'OUTBOX_DELETE_MANY',
    jsonb_build_object(
      'requested', v_requested
    ),
    jsonb_build_object(
      'requested', v_requested,
      'deleted', v_deleted,
      'blocked_already_sent', v_blocked_already_sent,
      'blocked_invalid_status', v_blocked_invalid_status,
      'not_found', v_not_found,
      'other_blocked', v_other_blocked
    ),
    v_reason,
    p_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'requested', v_requested,
    'deleted', v_deleted,
    'blocked_already_sent', v_blocked_already_sent,
    'blocked_invalid_status', v_blocked_invalid_status,
    'not_found', v_not_found,
    'other_blocked', v_other_blocked,
    'results', v_results
  );
end;
$function$;

-- outbox_unified_delete(text,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.outbox_unified_delete(p_channel text, p_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel text := nullif(upper(btrim(coalesce(p_channel,''))), '');
  v_reason text := nullif(btrim(coalesce(p_reason,'')), '');
  v_now timestamptz := now();

  v_mail_row public.mail_outbox%rowtype;
  v_comms_row public.comms_outbox%rowtype;

  v_row_channel text;
  v_row_id_text text;
  v_row_status text;
  v_row_to text;
  v_row_mailshot_run_id_text text;
  v_row_recipient_kind text;
  v_row_recipient_id_text text;
  v_row_context_kind text;
  v_row_context_id_text text;

  v_block_reason text := null;
  v_deleted boolean := false;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if v_channel is null then
    raise exception 'channel required';
  end if;

  if p_id is null then
    raise exception 'id required';
  end if;

  if v_channel not in ('EMAIL','WHATSAPP','SMS','VOICE') then
    raise exception 'unsupported channel %', v_channel;
  end if;

  if v_channel = 'EMAIL' then
    select mo.*
    into v_mail_row
    from public.mail_outbox as mo
    where mo.id = p_id
    for update;

    if not found then
      return jsonb_build_object(
        'ok', true,
        'deleted', false,
        'reason', 'NOT_FOUND',
        'row', jsonb_build_object(
          'channel', v_channel,
          'outbox_id', p_id::text
        )
      );
    end if;

    v_row_channel := 'EMAIL';
    v_row_id_text := v_mail_row.id::text;
    v_row_status := v_mail_row.status::text;
    v_row_to := v_mail_row."to";
    v_row_mailshot_run_id_text := case when v_mail_row.mailshot_run_id is null then null else v_mail_row.mailshot_run_id::text end;
    v_row_recipient_kind := v_mail_row.recipient_kind;
    v_row_recipient_id_text := case when v_mail_row.recipient_id is null then null else v_mail_row.recipient_id::text end;
    v_row_context_kind := v_mail_row.context_kind;
    v_row_context_id_text := case when v_mail_row.context_id is null then null else v_mail_row.context_id::text end;

    if v_mail_row.read_at is not null then
      v_block_reason := 'ALREADY_READ';
    elsif v_mail_row.delivered_at is not null then
      v_block_reason := 'ALREADY_DELIVERED';
    elsif v_mail_row.sent_at is not null then
      v_block_reason := 'ALREADY_SENT';
    elsif upper(coalesce(v_mail_row.status::text,'')) not in ('QUEUED','FAILED') then
      v_block_reason := 'INVALID_STATUS';
    end if;

    if v_block_reason is null then
      perform public._audit_insert(
        'outbox',
        v_mail_row.id::text,
        'OUTBOX_DELETE',
        jsonb_build_object(
          'channel', 'EMAIL',
          'outbox_id', v_mail_row.id::text,
          'status', v_mail_row.status::text,
          'to_address', v_mail_row."to",
          'mailshot_run_id', case when v_mail_row.mailshot_run_id is null then null else v_mail_row.mailshot_run_id::text end,
          'recipient_kind', v_mail_row.recipient_kind,
          'recipient_id', case when v_mail_row.recipient_id is null then null else v_mail_row.recipient_id::text end,
          'context_kind', v_mail_row.context_kind,
          'context_id', case when v_mail_row.context_id is null then null else v_mail_row.context_id::text end
        ),
        null,
        v_reason,
        p_actor_user_id
      );

      delete from public.mail_outbox as mo
      where mo.id = v_mail_row.id;

      v_deleted := true;
    end if;

  else
    select co.*
    into v_comms_row
    from public.comms_outbox as co
    where co.id = p_id
    for update;

    if not found then
      return jsonb_build_object(
        'ok', true,
        'deleted', false,
        'reason', 'NOT_FOUND',
        'row', jsonb_build_object(
          'channel', v_channel,
          'outbox_id', p_id::text
        )
      );
    end if;

    if upper(coalesce(v_comms_row.channel,'')) <> v_channel then
      return jsonb_build_object(
        'ok', true,
        'deleted', false,
        'reason', 'CHANNEL_MISMATCH',
        'row', jsonb_build_object(
          'channel', v_comms_row.channel,
          'outbox_id', v_comms_row.id::text
        )
      );
    end if;

    v_row_channel := v_comms_row.channel;
    v_row_id_text := v_comms_row.id::text;
    v_row_status := v_comms_row.status;
    v_row_to := v_comms_row.to_address;
    v_row_mailshot_run_id_text := case when v_comms_row.mailshot_run_id is null then null else v_comms_row.mailshot_run_id::text end;
    v_row_recipient_kind := v_comms_row.recipient_kind;
    v_row_recipient_id_text := case when v_comms_row.recipient_id is null then null else v_comms_row.recipient_id::text end;
    v_row_context_kind := v_comms_row.context_kind;
    v_row_context_id_text := case when v_comms_row.context_id is null then null else v_comms_row.context_id::text end;

    if v_comms_row.read_at is not null then
      v_block_reason := 'ALREADY_READ';
    elsif v_comms_row.delivered_at is not null then
      v_block_reason := 'ALREADY_DELIVERED';
    elsif v_comms_row.sent_at is not null then
      v_block_reason := 'ALREADY_SENT';
    elsif upper(coalesce(v_comms_row.status,'')) not in ('QUEUED','FAILED') then
      v_block_reason := 'INVALID_STATUS';
    end if;

    if v_block_reason is null then
      perform public._audit_insert(
        'outbox',
        v_comms_row.id::text,
        'OUTBOX_DELETE',
        jsonb_build_object(
          'channel', v_comms_row.channel,
          'outbox_id', v_comms_row.id::text,
          'status', v_comms_row.status,
          'to_address', v_comms_row.to_address,
          'mailshot_run_id', case when v_comms_row.mailshot_run_id is null then null else v_comms_row.mailshot_run_id::text end,
          'recipient_kind', v_comms_row.recipient_kind,
          'recipient_id', case when v_comms_row.recipient_id is null then null else v_comms_row.recipient_id::text end,
          'context_kind', v_comms_row.context_kind,
          'context_id', case when v_comms_row.context_id is null then null else v_comms_row.context_id::text end
        ),
        null,
        v_reason,
        p_actor_user_id
      );

      delete from public.comms_outbox as co
      where co.id = v_comms_row.id;

      v_deleted := true;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'deleted', v_deleted,
    'deleted_at_utc', case when v_deleted then v_now::text else null end,
    'reason', case when v_deleted then null else v_block_reason end,
    'row', jsonb_build_object(
      'channel', v_row_channel,
      'outbox_id', v_row_id_text,
      'status', v_row_status,
      'to_address', v_row_to,
      'mailshot_run_id', v_row_mailshot_run_id_text,
      'recipient_kind', v_row_recipient_kind,
      'recipient_id', v_row_recipient_id_text,
      'context_kind', v_row_context_kind,
      'context_id', v_row_context_id_text
    )
  );
end;
$function$;

-- outbox_unified_get(text,uuid)
CREATE OR REPLACE FUNCTION public.outbox_unified_get(p_channel text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel text := nullif(upper(btrim(coalesce(p_channel,''))), '');
  v_now timestamptz := now();
  v_row record;
begin
  if v_channel is null then
    raise exception 'channel required';
  end if;

  if p_id is null then
    raise exception 'id required';
  end if;

  select
    u.channel,
    u.outbox_id,
    u.outbox_type,
    u.status,
    u.delivery_status,
    u.created_at_utc,
    u.sent_at,
    u.delivered_at,
    u.read_at,
    u.failed_at,
    u.to_address,
    u.cc,
    u.bcc,
    u.reply_to,
    u.importance,
    u.email_type,
    u.subject,
    u.body_text,
    u.body_html,
    u.attachments,
    u.reference,
    u.provider_message_id,
    u.last_error,
    u.created_by,
    u.recipient_kind,
    u.recipient_id,
    coalesce(
      case
        when lower(coalesce(u.recipient_kind, '')) = 'candidate' then nullif(btrim(coalesce(c_rec.display_name, concat_ws(' ', c_rec.first_name, c_rec.last_name), c_rec.email, c_rec.phone, u.to_address)), '')
        when lower(coalesce(u.recipient_kind, '')) = 'client' then nullif(btrim(coalesce(cl_rec.name, cl_rec.primary_invoice_email, cl_rec.contact_email, u.to_address)), '')
        when lower(coalesce(u.recipient_kind, '')) = 'umbrella' then nullif(btrim(coalesce(um_rec.name, um_rec.remittance_email, u.to_address)), '')
        else null
      end,
      nullif(btrim(coalesce(u.to_address, '')), '')
    ) as recipient_display_name,
    u.context_kind,
    u.context_id,
    u.mailshot_run_id,
    u.document_template_id,
    u.scheduled_for_utc,
    u.next_attempt_at_utc,
    coalesce(u.next_attempt_at_utc, u.scheduled_for_utc, u.created_at_utc) as effective_ready_at_utc,
    case
      when u.read_at is not null then 'READ'
      when u.delivered_at is not null then 'DELIVERED'
      when u.sent_at is not null then 'SENT'
      when upper(coalesce(u.status,'')) = 'FAILED' or u.failed_at is not null then 'FAILED'
      when upper(coalesce(u.status,'')) = 'QUEUED'
           and coalesce(u.next_attempt_at_utc, u.scheduled_for_utc, u.created_at_utc) > v_now then 'SCHEDULED'
      when upper(coalesce(u.status,'')) = 'QUEUED' then 'QUEUED'
      else upper(coalesce(u.status,''))
    end as queue_state,
    (u.scheduled_for_utc is not null) as is_scheduled
  into v_row
  from public.v_outbox_unified as u
  left join public.candidates as c_rec
    on lower(coalesce(u.recipient_kind, '')) = 'candidate'
   and u.recipient_id = c_rec.id
  left join public.clients as cl_rec
    on lower(coalesce(u.recipient_kind, '')) = 'client'
   and u.recipient_id = cl_rec.id
  left join public.umbrellas as um_rec
    on lower(coalesce(u.recipient_kind, '')) = 'umbrella'
   and u.recipient_id = um_rec.id
  where upper(coalesce(u.channel,'')) = v_channel
    and u.outbox_id = p_id;

  if not found then
    raise exception 'outbox row not found for channel % id %', v_channel, p_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'row', jsonb_build_object(
      'channel', v_row.channel,
      'outbox_id', v_row.outbox_id::text,
      'outbox_type', v_row.outbox_type,
      'status', v_row.status,
      'delivery_status', v_row.delivery_status,
      'created_at_utc', v_row.created_at_utc::text,
      'sent_at', case when v_row.sent_at is null then null else v_row.sent_at::text end,
      'delivered_at', case when v_row.delivered_at is null then null else v_row.delivered_at::text end,
      'read_at', case when v_row.read_at is null then null else v_row.read_at::text end,
      'failed_at', case when v_row.failed_at is null then null else v_row.failed_at::text end,
      'to_address', v_row.to_address,
      'cc', v_row.cc,
      'bcc', v_row.bcc,
      'reply_to', v_row.reply_to,
      'importance', v_row.importance,
      'email_type', v_row.email_type,
      'subject', v_row.subject,
      'body_text', v_row.body_text,
      'body_html', v_row.body_html,
      'attachments', v_row.attachments,
      'reference', v_row.reference,
      'provider_message_id', v_row.provider_message_id,
      'last_error', v_row.last_error,
      'created_by', case when v_row.created_by is null then null else v_row.created_by::text end,
      'recipient_kind', v_row.recipient_kind,
      'recipient_id', case when v_row.recipient_id is null then null else v_row.recipient_id::text end,
      'recipient_display_name', v_row.recipient_display_name,
      'context_kind', v_row.context_kind,
      'context_id', case when v_row.context_id is null then null else v_row.context_id::text end,
      'mailshot_run_id', case when v_row.mailshot_run_id is null then null else v_row.mailshot_run_id::text end,
      'document_template_id', case when v_row.document_template_id is null then null else v_row.document_template_id::text end,
      'scheduled_for_utc', case when v_row.scheduled_for_utc is null then null else v_row.scheduled_for_utc::text end,
      'next_attempt_at_utc', case when v_row.next_attempt_at_utc is null then null else v_row.next_attempt_at_utc::text end,
      'effective_ready_at_utc', case when v_row.effective_ready_at_utc is null then null else v_row.effective_ready_at_utc::text end,
      'queue_state', v_row.queue_state,
      'is_scheduled', v_row.is_scheduled
    )
  );
end;
$function$;

-- outbox_unified_list(text,text,text,integer,integer)
CREATE OR REPLACE FUNCTION public.outbox_unified_list(p_status text, p_channel text, p_search text, p_limit integer, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_status text := nullif(upper(btrim(coalesce(p_status,''))), '');
  v_channel text := nullif(upper(btrim(coalesce(p_channel,''))), '');
  v_search text := nullif(btrim(coalesce(p_search,'')), '');

  v_limit int := coalesce(p_limit, 50);
  v_offset int := coalesce(p_offset, 0);

  v_total bigint := 0;
  v_items jsonb := '[]'::jsonb;
begin
  if v_limit < 1 then v_limit := 1; end if;
  if v_limit > 500 then v_limit := 500; end if;
  if v_offset < 0 then v_offset := 0; end if;

  with filtered as (
    select
      u.channel,
      u.outbox_id,
      u.outbox_type,
      u.status,
      u.delivery_status,
      u.created_at_utc,
      u.sent_at,
      u.delivered_at,
      u.read_at,
      u.failed_at,
      u.to_address,
      u.subject,
      u.body_text,
      u.reference,
      u.provider_message_id,
      u.last_error,
      u.created_by,
      u.recipient_kind,
      u.recipient_id,
      u.context_kind,
      u.context_id,
      u.mailshot_run_id,
      u.document_template_id
    from public.v_outbox_unified u
    where
      (v_status is null or upper(coalesce(u.status,'')) = v_status)
      and (v_channel is null or upper(coalesce(u.channel,'')) = v_channel)
      and (
        v_search is null
        or coalesce(u.to_address,'') ilike ('%' || v_search || '%')
        or coalesce(u.subject,'') ilike ('%' || v_search || '%')
        or coalesce(u.body_text,'') ilike ('%' || v_search || '%')
        or coalesce(u.reference,'') ilike ('%' || v_search || '%')
        or coalesce(u.last_error,'') ilike ('%' || v_search || '%')
      )
  ),
  counted as (
    select count(*)::bigint as total_count
    from filtered
  ),
  paged as (
    select *
    from filtered
    order by created_at_utc desc, outbox_id::text desc
    limit v_limit offset v_offset
  )
  select
    (select total_count from counted),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'channel', p.channel,
          'outbox_id', p.outbox_id::text,
          'outbox_type', p.outbox_type,
          'status', p.status,
          'delivery_status', p.delivery_status,
          'created_at_utc', p.created_at_utc::text,
          'sent_at', case when p.sent_at is null then null else p.sent_at::text end,
          'delivered_at', case when p.delivered_at is null then null else p.delivered_at::text end,
          'read_at', case when p.read_at is null then null else p.read_at::text end,
          'failed_at', case when p.failed_at is null then null else p.failed_at::text end,
          'to_address', p.to_address,
          'subject', p.subject,
          'body_preview', case
            when p.body_text is null then null
            when char_length(p.body_text) <= 200 then p.body_text
            else left(p.body_text, 200) || '…'
          end,
          'reference', p.reference,
          'provider_message_id', p.provider_message_id,
          'last_error', p.last_error,
          'created_by', case when p.created_by is null then null else p.created_by::text end,
          'recipient_kind', p.recipient_kind,
          'recipient_id', case when p.recipient_id is null then null else p.recipient_id::text end,
          'context_kind', p.context_kind,
          'context_id', case when p.context_id is null then null else p.context_id::text end,
          'mailshot_run_id', case when p.mailshot_run_id is null then null else p.mailshot_run_id::text end,
          'document_template_id', case when p.document_template_id is null then null else p.document_template_id::text end
        )
        order by p.created_at_utc desc, p.outbox_id::text desc
      ),
      '[]'::jsonb
    )
  into v_total, v_items
  from paged p;

  return jsonb_build_object(
    'ok', true,
    'filters', jsonb_build_object(
      'status', v_status,
      'channel', v_channel,
      'search', v_search
    ),
    'limit', v_limit,
    'offset', v_offset,
    'total_count', v_total,
    'items', v_items
  );
end;
$function$;

-- outbox_unified_list(text,text,text,text,integer,integer,text,text)
CREATE OR REPLACE FUNCTION public.outbox_unified_list(p_status text, p_channel text, p_search text, p_queue_state text, p_limit integer, p_offset integer, p_sort_by text DEFAULT 'created_at_utc'::text, p_sort_dir text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text := nullif(upper(btrim(coalesce(p_status,''))), '');
  v_channel text := nullif(upper(btrim(coalesce(p_channel,''))), '');
  v_search text := nullif(btrim(coalesce(p_search,'')), '');
  v_queue_state text := nullif(upper(btrim(coalesce(p_queue_state,''))), '');

  v_limit int := coalesce(p_limit, 50);
  v_offset int := coalesce(p_offset, 0);

  v_sort_by text := lower(btrim(coalesce(p_sort_by, 'created_at_utc')));
  v_sort_dir text := lower(btrim(coalesce(p_sort_dir, 'desc')));

  v_now timestamptz := now();

  v_total bigint := 0;
  v_items jsonb := '[]'::jsonb;
begin
  if v_limit < 1 then v_limit := 1; end if;
  if v_limit > 500 then v_limit := 500; end if;
  if v_offset < 0 then v_offset := 0; end if;

  if v_sort_by not in ('created_at_utc', 'scheduled_for_utc', 'effective_ready_at_utc', 'status', 'channel') then
    v_sort_by := 'created_at_utc';
  end if;

  if v_sort_dir not in ('asc', 'desc') then
    v_sort_dir := 'desc';
  end if;

  if v_queue_state is not null and v_queue_state not in ('SCHEDULED', 'QUEUED', 'SENT', 'DELIVERED', 'READ', 'FAILED') then
    v_queue_state := null;
  end if;

  with base_rows as (
    select
      u.channel,
      u.outbox_id,
      u.outbox_type,
      u.status,
      u.delivery_status,
      u.created_at_utc,
      u.sent_at,
      u.delivered_at,
      u.read_at,
      u.failed_at,
      u.to_address,
      u.subject,
      u.body_text,
      u.reference,
      u.provider_message_id,
      u.last_error,
      u.created_by,
      u.recipient_kind,
      u.recipient_id,
      coalesce(
        case
          when lower(coalesce(u.recipient_kind, '')) = 'candidate' then nullif(btrim(coalesce(c_rec.display_name, concat_ws(' ', c_rec.first_name, c_rec.last_name), c_rec.email, c_rec.phone, u.to_address)), '')
          when lower(coalesce(u.recipient_kind, '')) = 'client' then nullif(btrim(coalesce(cl_rec.name, cl_rec.primary_invoice_email, cl_rec.contact_email, u.to_address)), '')
          when lower(coalesce(u.recipient_kind, '')) = 'umbrella' then nullif(btrim(coalesce(um_rec.name, um_rec.remittance_email, u.to_address)), '')
          else null
        end,
        nullif(btrim(coalesce(u.to_address, '')), '')
      ) as recipient_display_name,
      u.context_kind,
      u.context_id,
      u.mailshot_run_id,
      u.document_template_id,
      u.scheduled_for_utc,
      u.next_attempt_at_utc,
      coalesce(u.next_attempt_at_utc, u.scheduled_for_utc, u.created_at_utc) as effective_ready_at_utc,
      case
        when u.read_at is not null then 'READ'
        when u.delivered_at is not null then 'DELIVERED'
        when u.sent_at is not null then 'SENT'
        when upper(coalesce(u.status,'')) = 'FAILED' or u.failed_at is not null then 'FAILED'
        when upper(coalesce(u.status,'')) = 'QUEUED'
             and coalesce(u.next_attempt_at_utc, u.scheduled_for_utc, u.created_at_utc) > v_now then 'SCHEDULED'
        when upper(coalesce(u.status,'')) = 'QUEUED' then 'QUEUED'
        else upper(coalesce(u.status,''))
      end as queue_state,
      (u.scheduled_for_utc is not null) as is_scheduled
    from public.v_outbox_unified as u
    left join public.candidates as c_rec
      on lower(coalesce(u.recipient_kind, '')) = 'candidate'
     and u.recipient_id = c_rec.id
    left join public.clients as cl_rec
      on lower(coalesce(u.recipient_kind, '')) = 'client'
     and u.recipient_id = cl_rec.id
    left join public.umbrellas as um_rec
      on lower(coalesce(u.recipient_kind, '')) = 'umbrella'
     and u.recipient_id = um_rec.id
  ),
  filtered as (
    select
      b.channel,
      b.outbox_id,
      b.outbox_type,
      b.status,
      b.delivery_status,
      b.created_at_utc,
      b.sent_at,
      b.delivered_at,
      b.read_at,
      b.failed_at,
      b.to_address,
      b.subject,
      b.body_text,
      b.reference,
      b.provider_message_id,
      b.last_error,
      b.created_by,
      b.recipient_kind,
      b.recipient_id,
      b.recipient_display_name,
      b.context_kind,
      b.context_id,
      b.mailshot_run_id,
      b.document_template_id,
      b.scheduled_for_utc,
      b.next_attempt_at_utc,
      b.effective_ready_at_utc,
      b.queue_state,
      b.is_scheduled
    from base_rows as b
    where
      (v_status is null or upper(coalesce(b.status,'')) = v_status)
      and (v_channel is null or upper(coalesce(b.channel,'')) = v_channel)
      and (v_queue_state is null or b.queue_state = v_queue_state)
      and (
        v_search is null
        or coalesce(b.to_address,'') ilike ('%' || v_search || '%')
        or coalesce(b.recipient_display_name,'') ilike ('%' || v_search || '%')
        or coalesce(b.subject,'') ilike ('%' || v_search || '%')
        or coalesce(b.body_text,'') ilike ('%' || v_search || '%')
        or coalesce(b.reference,'') ilike ('%' || v_search || '%')
        or coalesce(b.last_error,'') ilike ('%' || v_search || '%')
      )
  ),
  counted as (
    select count(*)::bigint as total_count
    from filtered as f
  ),
  paged as (
    select
      f.channel,
      f.outbox_id,
      f.outbox_type,
      f.status,
      f.delivery_status,
      f.created_at_utc,
      f.sent_at,
      f.delivered_at,
      f.read_at,
      f.failed_at,
      f.to_address,
      f.subject,
      f.body_text,
      f.reference,
      f.provider_message_id,
      f.last_error,
      f.created_by,
      f.recipient_kind,
      f.recipient_id,
      f.recipient_display_name,
      f.context_kind,
      f.context_id,
      f.mailshot_run_id,
      f.document_template_id,
      f.scheduled_for_utc,
      f.next_attempt_at_utc,
      f.effective_ready_at_utc,
      f.queue_state,
      f.is_scheduled
    from filtered as f
    order by
      case when v_sort_by = 'created_at_utc' and v_sort_dir = 'asc' then f.created_at_utc end asc nulls last,
      case when v_sort_by = 'created_at_utc' and v_sort_dir = 'desc' then f.created_at_utc end desc nulls last,

      case when v_sort_by = 'scheduled_for_utc' and v_sort_dir = 'asc' then f.scheduled_for_utc end asc nulls last,
      case when v_sort_by = 'scheduled_for_utc' and v_sort_dir = 'desc' then f.scheduled_for_utc end desc nulls last,

      case when v_sort_by = 'effective_ready_at_utc' and v_sort_dir = 'asc' then f.effective_ready_at_utc end asc nulls last,
      case when v_sort_by = 'effective_ready_at_utc' and v_sort_dir = 'desc' then f.effective_ready_at_utc end desc nulls last,

      case when v_sort_by = 'status' and v_sort_dir = 'asc' then f.queue_state end asc nulls last,
      case when v_sort_by = 'status' and v_sort_dir = 'desc' then f.queue_state end desc nulls last,

      case when v_sort_by = 'channel' and v_sort_dir = 'asc' then f.channel end asc nulls last,
      case when v_sort_by = 'channel' and v_sort_dir = 'desc' then f.channel end desc nulls last,

      f.created_at_utc desc,
      f.outbox_id::text desc
    limit v_limit offset v_offset
  )
  select
    (select c.total_count from counted as c),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'channel', p.channel,
          'outbox_id', p.outbox_id::text,
          'outbox_type', p.outbox_type,
          'status', p.status,
          'delivery_status', p.delivery_status,
          'created_at_utc', p.created_at_utc::text,
          'sent_at', case when p.sent_at is null then null else p.sent_at::text end,
          'delivered_at', case when p.delivered_at is null then null else p.delivered_at::text end,
          'read_at', case when p.read_at is null then null else p.read_at::text end,
          'failed_at', case when p.failed_at is null then null else p.failed_at::text end,
          'to_address', p.to_address,
          'subject', p.subject,
          'body_preview', case
            when p.body_text is null then null
            when char_length(p.body_text) <= 200 then p.body_text
            else left(p.body_text, 200) || '…'
          end,
          'reference', p.reference,
          'provider_message_id', p.provider_message_id,
          'last_error', p.last_error,
          'created_by', case when p.created_by is null then null else p.created_by::text end,
          'recipient_kind', p.recipient_kind,
          'recipient_id', case when p.recipient_id is null then null else p.recipient_id::text end,
          'recipient_display_name', p.recipient_display_name,
          'context_kind', p.context_kind,
          'context_id', case when p.context_id is null then null else p.context_id::text end,
          'mailshot_run_id', case when p.mailshot_run_id is null then null else p.mailshot_run_id::text end,
          'document_template_id', case when p.document_template_id is null then null else p.document_template_id::text end,
          'scheduled_for_utc', case when p.scheduled_for_utc is null then null else p.scheduled_for_utc::text end,
          'next_attempt_at_utc', case when p.next_attempt_at_utc is null then null else p.next_attempt_at_utc::text end,
          'effective_ready_at_utc', case when p.effective_ready_at_utc is null then null else p.effective_ready_at_utc::text end,
          'queue_state', p.queue_state,
          'is_scheduled', p.is_scheduled
        )
        order by
          case when v_sort_by = 'created_at_utc' and v_sort_dir = 'asc' then p.created_at_utc end asc nulls last,
          case when v_sort_by = 'created_at_utc' and v_sort_dir = 'desc' then p.created_at_utc end desc nulls last,

          case when v_sort_by = 'scheduled_for_utc' and v_sort_dir = 'asc' then p.scheduled_for_utc end asc nulls last,
          case when v_sort_by = 'scheduled_for_utc' and v_sort_dir = 'desc' then p.scheduled_for_utc end desc nulls last,

          case when v_sort_by = 'effective_ready_at_utc' and v_sort_dir = 'asc' then p.effective_ready_at_utc end asc nulls last,
          case when v_sort_by = 'effective_ready_at_utc' and v_sort_dir = 'desc' then p.effective_ready_at_utc end desc nulls last,

          case when v_sort_by = 'status' and v_sort_dir = 'asc' then p.queue_state end asc nulls last,
          case when v_sort_by = 'status' and v_sort_dir = 'desc' then p.queue_state end desc nulls last,

          case when v_sort_by = 'channel' and v_sort_dir = 'asc' then p.channel end asc nulls last,
          case when v_sort_by = 'channel' and v_sort_dir = 'desc' then p.channel end desc nulls last,

          p.created_at_utc desc,
          p.outbox_id::text desc
      ),
      '[]'::jsonb
    )
  into v_total, v_items
  from paged as p;

  return jsonb_build_object(
    'ok', true,
    'filters', jsonb_build_object(
      'status', v_status,
      'channel', v_channel,
      'search', v_search,
      'queue_state', v_queue_state
    ),
    'sort', jsonb_build_object(
      'sort_by', v_sort_by,
      'sort_dir', v_sort_dir
    ),
    'limit', v_limit,
    'offset', v_offset,
    'total_count', v_total,
    'items', v_items
  );
end;
$function$;

-- outbox_unified_reschedule(text,uuid,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.outbox_unified_reschedule(p_channel text, p_id uuid, p_actor_user_id uuid, p_scheduled_for_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel text := nullif(upper(btrim(coalesce(p_channel,''))), '');
  v_target_utc timestamptz := p_scheduled_for_utc;
  v_effective_target_utc timestamptz;
  v_reason text := 'RESCHEDULE';

  v_mail_row public.mail_outbox%rowtype;
  v_comms_row public.comms_outbox%rowtype;

  v_cfg jsonb;
  v_cfg_scheduling jsonb;
  v_now timestamptz := now();
  v_max_future_days int := 365;
  v_allow_past_grace_minutes int := 15;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if v_channel is null then
    raise exception 'channel required';
  end if;

  if p_id is null then
    raise exception 'id required';
  end if;

  if v_target_utc is null then
    raise exception 'scheduled_for_utc required';
  end if;

  if v_channel not in ('EMAIL','WHATSAPP','SMS','VOICE') then
    raise exception 'unsupported channel %', v_channel;
  end if;

  select sd.comms_adaptors_json
  into v_cfg
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cfg is not null and jsonb_typeof(v_cfg) = 'object' then
    v_cfg_scheduling := v_cfg->'scheduling';

    if v_cfg_scheduling is not null and jsonb_typeof(v_cfg_scheduling) = 'object' then
      v_max_future_days := coalesce(nullif((v_cfg_scheduling->>'max_future_days')::int, 0), v_max_future_days);
      v_allow_past_grace_minutes := coalesce((v_cfg_scheduling->>'allow_past_grace_minutes')::int, v_allow_past_grace_minutes);
    end if;
  end if;

  if v_target_utc > (v_now + make_interval(days => v_max_future_days)) then
    raise exception 'scheduled_for_utc exceeds max_future_days';
  end if;

  if v_target_utc < (v_now - make_interval(mins => v_allow_past_grace_minutes)) then
    raise exception 'scheduled_for_utc too far in past';
  end if;

  if v_target_utc <= v_now then
    v_effective_target_utc := v_now;
  else
    v_effective_target_utc := v_target_utc;
  end if;

  if v_channel = 'EMAIL' then
    select mo.*
    into v_mail_row
    from public.mail_outbox as mo
    where mo.id = p_id
    for update;

    if not found then
      raise exception 'outbox row not found';
    end if;

    if v_mail_row.read_at is not null
       or v_mail_row.delivered_at is not null
       or v_mail_row.sent_at is not null then
      raise exception 'outbox row is not reschedulable because it has already been sent';
    end if;

    if upper(coalesce(v_mail_row.status::text,'')) not in ('QUEUED','FAILED') then
      raise exception 'outbox row status is not reschedulable';
    end if;

    perform public._audit_insert(
      'outbox',
      v_mail_row.id::text,
      'OUTBOX_RESCHEDULE',
      jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', v_mail_row.status::text,
        'scheduled_for_utc', case when v_mail_row.scheduled_for_utc is null then null else v_mail_row.scheduled_for_utc::text end,
        'next_attempt_at_utc', case when v_mail_row.next_attempt_at_utc is null then null else v_mail_row.next_attempt_at_utc::text end,
        'provider_message_id', v_mail_row.provider_message_id,
        'provider_status', v_mail_row.provider_status,
        'last_error', v_mail_row.last_error
      ),
      jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', 'QUEUED',
        'scheduled_for_utc', v_effective_target_utc::text,
        'next_attempt_at_utc', v_effective_target_utc::text,
        'provider_message_id', null,
        'provider_status', null,
        'last_error', null
      ),
      v_reason,
      p_actor_user_id
    );

    update public.mail_outbox as mo
    set status = 'QUEUED'::public.mail_status_enum,
        sent_at = null,
        delivered_at = null,
        read_at = null,
        failed_at = null,
        last_error = null,
        provider_message_id = null,
        provider_status = null,
        scheduled_for_utc = v_effective_target_utc,
        next_attempt_at_utc = v_effective_target_utc
    where mo.id = v_mail_row.id;

    select mo.*
    into v_mail_row
    from public.mail_outbox as mo
    where mo.id = p_id;

    return jsonb_build_object(
      'ok', true,
      'row', jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', v_mail_row.status::text,
        'to_address', v_mail_row."to",
        'mailshot_run_id', case when v_mail_row.mailshot_run_id is null then null else v_mail_row.mailshot_run_id::text end,
        'recipient_kind', v_mail_row.recipient_kind,
        'recipient_id', case when v_mail_row.recipient_id is null then null else v_mail_row.recipient_id::text end,
        'context_kind', v_mail_row.context_kind,
        'context_id', case when v_mail_row.context_id is null then null else v_mail_row.context_id::text end,
        'scheduled_for_utc', case when v_mail_row.scheduled_for_utc is null then null else v_mail_row.scheduled_for_utc::text end,
        'next_attempt_at_utc', case when v_mail_row.next_attempt_at_utc is null then null else v_mail_row.next_attempt_at_utc::text end
      )
    );
  end if;

  select co.*
  into v_comms_row
  from public.comms_outbox as co
  where co.id = p_id
  for update;

  if not found then
    raise exception 'outbox row not found';
  end if;

  if upper(coalesce(v_comms_row.channel,'')) <> v_channel then
    raise exception 'channel mismatch';
  end if;

  if v_comms_row.read_at is not null
     or v_comms_row.delivered_at is not null
     or v_comms_row.sent_at is not null then
    raise exception 'outbox row is not reschedulable because it has already been sent';
  end if;

  if upper(coalesce(v_comms_row.status,'')) not in ('QUEUED','FAILED') then
    raise exception 'outbox row status is not reschedulable';
  end if;

  perform public._audit_insert(
    'outbox',
    v_comms_row.id::text,
    'OUTBOX_RESCHEDULE',
    jsonb_build_object(
      'channel', v_comms_row.channel,
      'outbox_id', v_comms_row.id::text,
      'status', v_comms_row.status,
      'scheduled_for_utc', case when v_comms_row.scheduled_for_utc is null then null else v_comms_row.scheduled_for_utc::text end,
      'next_attempt_at_utc', case when v_comms_row.next_attempt_at_utc is null then null else v_comms_row.next_attempt_at_utc::text end,
      'provider_key', v_comms_row.provider_key,
      'provider_message_id', v_comms_row.provider_message_id,
      'last_error', v_comms_row.last_error
    ),
    jsonb_build_object(
      'channel', v_comms_row.channel,
      'outbox_id', v_comms_row.id::text,
      'status', 'QUEUED',
      'scheduled_for_utc', v_effective_target_utc::text,
      'next_attempt_at_utc', v_effective_target_utc::text,
      'provider_key', 'AUTO',
      'provider_message_id', null,
      'last_error', null
    ),
    v_reason,
    p_actor_user_id
  );

  update public.comms_outbox as co
  set status = 'QUEUED',
      provider_key = 'AUTO',
      provider_message_id = null,
      provider_response_json = '{}'::jsonb,
      last_error = null,
      sent_at = null,
      delivered_at = null,
      read_at = null,
      failed_at = null,
      scheduled_for_utc = v_effective_target_utc,
      next_attempt_at_utc = v_effective_target_utc
  where co.id = v_comms_row.id;

  select co.*
  into v_comms_row
  from public.comms_outbox as co
  where co.id = p_id;

  return jsonb_build_object(
    'ok', true,
    'row', jsonb_build_object(
      'channel', v_comms_row.channel,
      'outbox_id', v_comms_row.id::text,
      'status', v_comms_row.status,
      'to_address', v_comms_row.to_address,
      'mailshot_run_id', case when v_comms_row.mailshot_run_id is null then null else v_comms_row.mailshot_run_id::text end,
      'recipient_kind', v_comms_row.recipient_kind,
      'recipient_id', case when v_comms_row.recipient_id is null then null else v_comms_row.recipient_id::text end,
      'context_kind', v_comms_row.context_kind,
      'context_id', case when v_comms_row.context_id is null then null else v_comms_row.context_id::text end,
      'scheduled_for_utc', case when v_comms_row.scheduled_for_utc is null then null else v_comms_row.scheduled_for_utc::text end,
      'next_attempt_at_utc', case when v_comms_row.next_attempt_at_utc is null then null else v_comms_row.next_attempt_at_utc::text end
    )
  );
end;
$function$;

-- outbox_unified_retry(text,uuid,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.outbox_unified_retry(p_channel text, p_id uuid, p_actor_user_id uuid, p_retry_at_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel text := nullif(upper(btrim(coalesce(p_channel,''))), '');
  v_retry_at_utc timestamptz := coalesce(p_retry_at_utc, now());
  v_effective_retry_at_utc timestamptz;
  v_reason text := 'RETRY';

  v_mail_row public.mail_outbox%rowtype;
  v_comms_row public.comms_outbox%rowtype;

  v_cfg jsonb;
  v_cfg_scheduling jsonb;
  v_now timestamptz := now();
  v_max_future_days int := 365;
  v_allow_past_grace_minutes int := 15;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id required';
  end if;

  if v_channel is null then
    raise exception 'channel required';
  end if;

  if p_id is null then
    raise exception 'id required';
  end if;

  if v_channel not in ('EMAIL','WHATSAPP','SMS','VOICE') then
    raise exception 'unsupported channel %', v_channel;
  end if;

  select sd.comms_adaptors_json
  into v_cfg
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cfg is not null and jsonb_typeof(v_cfg) = 'object' then
    v_cfg_scheduling := v_cfg->'scheduling';

    if v_cfg_scheduling is not null and jsonb_typeof(v_cfg_scheduling) = 'object' then
      v_max_future_days := coalesce(nullif((v_cfg_scheduling->>'max_future_days')::int, 0), v_max_future_days);
      v_allow_past_grace_minutes := coalesce((v_cfg_scheduling->>'allow_past_grace_minutes')::int, v_allow_past_grace_minutes);
    end if;
  end if;

  if v_retry_at_utc > (v_now + make_interval(days => v_max_future_days)) then
    raise exception 'retry_at_utc exceeds max_future_days';
  end if;

  if v_retry_at_utc < (v_now - make_interval(mins => v_allow_past_grace_minutes)) then
    raise exception 'retry_at_utc too far in past';
  end if;

  if v_retry_at_utc <= v_now then
    v_effective_retry_at_utc := v_now;
  else
    v_effective_retry_at_utc := v_retry_at_utc;
  end if;

  if v_channel = 'EMAIL' then
    select mo.*
    into v_mail_row
    from public.mail_outbox as mo
    where mo.id = p_id
    for update;

    if not found then
      raise exception 'outbox row not found';
    end if;

    if v_mail_row.read_at is not null
       or v_mail_row.delivered_at is not null
       or v_mail_row.sent_at is not null then
      raise exception 'outbox row is not retryable because it has already been sent';
    end if;

    if coalesce(v_mail_row.attempt_lease_token, '') <> ''
       and v_mail_row.attempt_lease_expires_at_utc is not null
       and v_mail_row.attempt_lease_expires_at_utc > v_now then
      raise exception 'outbox row is not retryable because it is currently being sent';
    end if;

    if upper(coalesce(v_mail_row.status::text,'')) not in ('QUEUED','FAILED') then
      raise exception 'outbox row status is not retryable';
    end if;

    perform public._audit_insert(
      'outbox',
      v_mail_row.id::text,
      'OUTBOX_RETRY',
      jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', v_mail_row.status::text,
        'next_attempt_at_utc', case when v_mail_row.next_attempt_at_utc is null then null else v_mail_row.next_attempt_at_utc::text end,
        'scheduled_for_utc', case when v_mail_row.scheduled_for_utc is null then null else v_mail_row.scheduled_for_utc::text end,
        'provider_message_id', v_mail_row.provider_message_id,
        'provider_status', v_mail_row.provider_status,
        'last_error', v_mail_row.last_error
      ),
      jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', 'QUEUED',
        'next_attempt_at_utc', v_effective_retry_at_utc::text,
        'scheduled_for_utc', case when v_mail_row.scheduled_for_utc is null then null else v_mail_row.scheduled_for_utc::text end,
        'provider_message_id', null,
        'provider_status', null,
        'last_error', null
      ),
      v_reason,
      p_actor_user_id
    );

    update public.mail_outbox as mo
    set status = 'QUEUED'::public.mail_status_enum,
        sent_at = null,
        delivered_at = null,
        read_at = null,
        failed_at = null,
        last_error = null,
        provider_message_id = null,
        provider_status = null,
        attempt_lease_token = null,
        attempt_leased_at_utc = null,
        attempt_lease_expires_at_utc = null,
        next_attempt_at_utc = v_effective_retry_at_utc
    where mo.id = v_mail_row.id;

    select mo.*
    into v_mail_row
    from public.mail_outbox as mo
    where mo.id = p_id;

    return jsonb_build_object(
      'ok', true,
      'row', jsonb_build_object(
        'channel', 'EMAIL',
        'outbox_id', v_mail_row.id::text,
        'status', v_mail_row.status::text,
        'to_address', v_mail_row."to",
        'mailshot_run_id', case when v_mail_row.mailshot_run_id is null then null else v_mail_row.mailshot_run_id::text end,
        'recipient_kind', v_mail_row.recipient_kind,
        'recipient_id', case when v_mail_row.recipient_id is null then null else v_mail_row.recipient_id::text end,
        'context_kind', v_mail_row.context_kind,
        'context_id', case when v_mail_row.context_id is null then null else v_mail_row.context_id::text end,
        'scheduled_for_utc', case when v_mail_row.scheduled_for_utc is null then null else v_mail_row.scheduled_for_utc::text end,
        'next_attempt_at_utc', case when v_mail_row.next_attempt_at_utc is null then null else v_mail_row.next_attempt_at_utc::text end
      )
    );
  end if;

  select co.*
  into v_comms_row
  from public.comms_outbox as co
  where co.id = p_id
  for update;

  if not found then
    raise exception 'outbox row not found';
  end if;

  if upper(coalesce(v_comms_row.channel,'')) <> v_channel then
    raise exception 'channel mismatch';
  end if;

  if v_comms_row.read_at is not null
     or v_comms_row.delivered_at is not null
     or v_comms_row.sent_at is not null then
    raise exception 'outbox row is not retryable because it has already been sent';
  end if;

  if upper(coalesce(v_comms_row.status,'')) not in ('QUEUED','FAILED') then
    raise exception 'outbox row status is not retryable';
  end if;

  perform public._audit_insert(
    'outbox',
    v_comms_row.id::text,
    'OUTBOX_RETRY',
    jsonb_build_object(
      'channel', v_comms_row.channel,
      'outbox_id', v_comms_row.id::text,
      'status', v_comms_row.status,
      'next_attempt_at_utc', case when v_comms_row.next_attempt_at_utc is null then null else v_comms_row.next_attempt_at_utc::text end,
      'scheduled_for_utc', case when v_comms_row.scheduled_for_utc is null then null else v_comms_row.scheduled_for_utc::text end,
      'provider_key', v_comms_row.provider_key,
      'provider_message_id', v_comms_row.provider_message_id,
      'last_error', v_comms_row.last_error
    ),
    jsonb_build_object(
      'channel', v_comms_row.channel,
      'outbox_id', v_comms_row.id::text,
      'status', 'QUEUED',
      'next_attempt_at_utc', v_effective_retry_at_utc::text,
      'scheduled_for_utc', case when v_comms_row.scheduled_for_utc is null then null else v_comms_row.scheduled_for_utc::text end,
      'provider_key', 'AUTO',
      'provider_message_id', null,
      'last_error', null
    ),
    v_reason,
    p_actor_user_id
  );

  update public.comms_outbox as co
  set status = 'QUEUED',
      provider_key = 'AUTO',
      provider_message_id = null,
      provider_response_json = '{}'::jsonb,
      last_error = null,
      sent_at = null,
      delivered_at = null,
      read_at = null,
      failed_at = null,
      next_attempt_at_utc = v_effective_retry_at_utc
  where co.id = v_comms_row.id;

  select co.*
  into v_comms_row
  from public.comms_outbox as co
  where co.id = p_id;

  return jsonb_build_object(
    'ok', true,
    'row', jsonb_build_object(
      'channel', v_comms_row.channel,
      'outbox_id', v_comms_row.id::text,
      'status', v_comms_row.status,
      'to_address', v_comms_row.to_address,
      'mailshot_run_id', case when v_comms_row.mailshot_run_id is null then null else v_comms_row.mailshot_run_id::text end,
      'recipient_kind', v_comms_row.recipient_kind,
      'recipient_id', case when v_comms_row.recipient_id is null then null else v_comms_row.recipient_id::text end,
      'context_kind', v_comms_row.context_kind,
      'context_id', case when v_comms_row.context_id is null then null else v_comms_row.context_id::text end,
      'scheduled_for_utc', case when v_comms_row.scheduled_for_utc is null then null else v_comms_row.scheduled_for_utc::text end,
      'next_attempt_at_utc', case when v_comms_row.next_attempt_at_utc is null then null else v_comms_row.next_attempt_at_utc::text end
    )
  );
end;
$function$;

-- pay_advances_register_pdf_payload(uuid,text,text,text,uuid,boolean,boolean,numeric,numeric,date,date,text,text,date)
CREATE OR REPLACE FUNCTION public.pay_advances_register_pdf_payload(p_actor_user_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid, p_outstanding_only boolean DEFAULT true, p_due_this_week_only boolean DEFAULT false, p_amount_min numeric DEFAULT NULL::numeric, p_amount_max numeric DEFAULT NULL::numeric, p_created_from date DEFAULT NULL::date, p_created_to date DEFAULT NULL::date, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text, p_as_of_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
begin
  v_base := public.pay_advances_register(
    p_actor_user_id => p_actor_user_id,
    p_search => p_search,
    p_type => p_type,
    p_status => p_status,
    p_client_id => p_client_id,
    p_outstanding_only => p_outstanding_only,
    p_due_this_week_only => p_due_this_week_only,
    p_amount_min => p_amount_min,
    p_amount_max => p_amount_max,
    p_created_from => p_created_from,
    p_created_to => p_created_to,
    p_sort_key => p_sort_key,
    p_sort_dir => p_sort_dir,
    p_limit => 100000,
    p_offset => 0,
    p_as_of_date => p_as_of_date
  );

  v_rows := coalesce(v_base->'rows', '[]'::jsonb);

  select jsonb_build_array(
    jsonb_build_object(
      'record_type', 'PAYMENT_ADVANCE',
      'title', 'Payment Advances',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'PAYMENT_ADVANCE'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'OVERPAYMENT',
      'title', 'Overpayments',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'OVERPAYMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'MANUAL_DEBT_ADJUSTMENT',
      'title', 'Manual Debt Adjustments',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'MANUAL_DEBT_ADJUSTMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'MANUAL_CREDIT_ADJUSTMENT',
      'title', 'Manual Credit Adjustments',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'MANUAL_CREDIT_ADJUSTMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'SNOOZED_DEFERRED',
      'title', 'Snoozed / Deferred items',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'SNOOZED_DEFERRED'), '[]'::jsonb)
    )
  )
  into v_groups;

  return jsonb_build_object(
    'ok', true,
    'title', 'Finance Cases & Snoozes Register',
    'generated_at_utc', now()::text,
    'applied_filters', coalesce(v_base->'meta'->'applied_filters', '{}'::jsonb),
    'summary', coalesce(v_base->'summary', '{}'::jsonb),
    'meta', coalesce(v_base->'meta', '{}'::jsonb),
    'rows', v_rows,
    'groups', coalesce(v_groups, '[]'::jsonb)
  );
end;
$function$;

-- pay_advances_register(uuid,text,text,text,uuid,boolean,boolean,numeric,numeric,date,date,text,text,integer,integer,date)
CREATE OR REPLACE FUNCTION public.pay_advances_register(p_actor_user_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid, p_outstanding_only boolean DEFAULT true, p_due_this_week_only boolean DEFAULT false, p_amount_min numeric DEFAULT NULL::numeric, p_amount_max numeric DEFAULT NULL::numeric, p_created_from date DEFAULT NULL::date, p_created_to date DEFAULT NULL::date, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 500, p_offset integer DEFAULT 0, p_as_of_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_as_of_date date := coalesce(p_as_of_date, (now() at time zone 'Europe/London')::date);
  v_week_start date := public._pay_week_start_monday(coalesce(p_as_of_date, (now() at time zone 'Europe/London')::date));
  v_week_end date := (public._pay_week_start_monday(coalesce(p_as_of_date, (now() at time zone 'Europe/London')::date)) + 6);

  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_type text := upper(btrim(coalesce(p_type, '')));
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_sort_key text := lower(btrim(coalesce(p_sort_key, 'created_at')));
  v_sort_dir text := upper(btrim(coalesce(p_sort_dir, 'DESC')));

  v_limit integer := greatest(1, least(coalesce(p_limit, 500), 10000));
  v_offset integer := greatest(0, coalesce(p_offset, 0));

  v_total_count integer := 0;
  v_summary jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_type_filter text := null;
begin
  if v_sort_dir not in ('ASC', 'DESC') then
    v_sort_dir := 'DESC';
  end if;

  if v_sort_key not in (
    'candidate',
    'client',
    'type',
    'status',
    'created_at',
    'original_amount',
    'recovered_total',
    'remaining_outstanding',
    'due_this_week',
    'start_week_start',
    'next_due_week_start',
    'authoritative_payment_date'
  ) then
    v_sort_key := 'created_at';
  end if;

  if v_type <> '' then
    v_type_filter := case
      when v_type in ('PAYMENT_ADVANCE', 'LOAN', 'ADVANCE', 'MISSING_SHIFT_ADVANCE') then 'PAYMENT_ADVANCE'
      when v_type = 'OVERPAYMENT' then 'OVERPAYMENT'
      when v_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_ADJUSTMENT'
      when v_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'MANUAL_CREDIT_ADJUSTMENT'
      when v_type in ('SNOOZED', 'DEFERRED', 'SNOOZED_DEFERRED') then 'SNOOZED_DEFERRED'
      else v_type
    end;
  end if;

  with finance_rows as (
    select
      case
        when vfc.active_snooze_id is not null then 'SNOOZED_DEFERRED'
        else vfc.case_type::text
      end as row_group,
      'FINANCE_CASE'::text as row_kind,
      vfc.finance_case_id,
      vfc.case_type::text as case_type,
      vfc.candidate_id,
      vfc.candidate_tms_ref,
      vfc.candidate_display_name,
      vfc.candidate_first_name,
      vfc.candidate_last_name,
      vfc.client_id,
      vfc.client_name,
      vfc.linked_timesheet_id,
      vfc.linked_shift_date,
      vfc.payout_pay_batch_id,
      vfc.payout_transfer_id,
      vfc.latest_recovery_pay_batch_id,
      vfc.created_at,
      vfc.start_week_start,
      vfc.next_due_week_start,
      round(coalesce(vfc.original_amount, 0), 2)::numeric(12,2) as original_amount,
      round(
        case
          when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 0
          else greatest(coalesce(vfc.original_amount, 0) - coalesce(vfc.outstanding_amount, 0), 0)
        end,
        2
      )::numeric(12,2) as recovered_total,
      round(coalesce(vfc.outstanding_amount, 0), 2)::numeric(12,2) as remaining_outstanding,
      round(
        case
          when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
           and coalesce(vfc.written_off_at_utc, null) is null
           and coalesce(vfc.cleared_at_utc, null) is null
           and upper(coalesce(vfc.status, '')) not in ('PAID_OFF', 'CLEARED')
           and vfc.next_due_week_start is not null
           and vfc.next_due_week_start <= v_week_start
          then least(coalesce(vfc.weekly_due, 0), coalesce(vfc.outstanding_amount, 0))
          else 0
        end,
        2
      )::numeric(12,2) as due_this_week,
      vfc.status,
      vfc.payout_status,
      vfc.baseline_signature,
      vfc.reason,
      vfc.notes,
      vfc.adjustment_comment,
      vfc.source_original_paid_amount,
      vfc.source_corrected_paid_amount,
      vfc.minimum_earnings_threshold,
      vfc.take_home_floor_override,
      vfc.active_snooze_id,
      vfc.active_snooze_kind,
      vfc.active_snooze_until_date,
      vfc.active_snooze_note,
      case
        when vfc.active_snooze_id is null then 'NONE'
        when vfc.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      case
        when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
        when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'CLEARED'
        when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RESERVED'
        when coalesce(vfc.committed_amount, 0) > 0 then 'COMMITTED'
        when coalesce(vfc.settled_amount, 0) > 0 then 'SETTLED'
        when vfc.active_snooze_id is not null then 'SNOOZED'
        else upper(coalesce(vfc.status, 'ACTIVE'))
      end as lifecycle_state,
      case
        when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_CREDIT_ADJUSTMENT') then coalesce(pbp.authoritative_payment_date, pbp.pay_date)
        else coalesce(pbr.authoritative_payment_date, pbr.pay_date)
      end as authoritative_payment_date,
      case
        when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfc.payout_status, 'NOT_PAID')
        when vfc.case_type = 'PAYMENT_ADVANCE' then
          case
            when coalesce(vfc.payout_status, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) > 0 then 'RECOVERY_ACTIVE'
            when coalesce(vfc.payout_status, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            else coalesce(vfc.payout_status, 'NOT_PAID')
          end
        when vfc.case_type in ('OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT') then
          case
            when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
            when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RECOVERY_RESERVED'
            when coalesce(vfc.committed_amount, 0) > 0 then 'RECOVERY_COMMITTED'
            when coalesce(vfc.settled_amount, 0) > 0 then 'RECOVERY_SETTLED'
            else 'RECOVERY_ACTIVE'
          end
        else coalesce(vfc.status, 'ACTIVE')
      end as payout_or_recovery_status,
      null::text as source_booking_id,
      null::date as source_week_ending_date,
      null::text as source_shift_label_norm
    from public.v_finance_cases_register vfc
    left join public.pay_batches pbp
      on pbp.id = vfc.payout_pay_batch_id
    left join public.pay_batches pbr
      on pbr.id = vfc.latest_recovery_pay_batch_id
  ),
  snoozed_timesheet_rows as (
    select
      'SNOOZED_DEFERRED'::text as row_group,
      'TIMESHEET_SNOOZE'::text as row_kind,
      null::uuid as finance_case_id,
      null::text as case_type,
      c.id as candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      c.first_name as candidate_first_name,
      c.last_name as candidate_last_name,
      cli.id as client_id,
      cli.name as client_name,
      s.timesheet_id as linked_timesheet_id,
      null::date as linked_shift_date,
      null::uuid as payout_pay_batch_id,
      null::uuid as payout_transfer_id,
      null::uuid as latest_recovery_pay_batch_id,
      s.created_at_utc as created_at,
      null::date as start_week_start,
      null::date as next_due_week_start,
      0::numeric(12,2) as original_amount,
      0::numeric(12,2) as recovered_total,
      0::numeric(12,2) as remaining_outstanding,
      0::numeric(12,2) as due_this_week,
      null::text as status,
      null::text as payout_status,
      null::text as baseline_signature,
      null::text as reason,
      null::text as notes,
      null::text as adjustment_comment,
      null::numeric as source_original_paid_amount,
      null::numeric as source_corrected_paid_amount,
      null::numeric as minimum_earnings_threshold,
      null::numeric as take_home_floor_override,
      s.id as active_snooze_id,
      upper(coalesce(s.snooze_kind, '')) as active_snooze_kind,
      s.snooze_until_date as active_snooze_until_date,
      s.note as active_snooze_note,
      case
        when s.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      'SNOOZED'::text as lifecycle_state,
      null::date as authoritative_payment_date,
      'DEFERRED'::text as payout_or_recovery_status,
      ts.booking_id as source_booking_id,
      ts.week_ending_date as source_week_ending_date,
      ts.shift_label_norm as source_shift_label_norm
    from public.pay_item_snoozes s
    join public.timesheets ts
      on ts.timesheet_id = s.timesheet_id
    join public.candidates c
      on c.id = s.candidate_id
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cli
      on cli.id = ct.client_id
    where s.cleared_at_utc is null
      and s.timesheet_id is not null
      and s.source_ref is null
      and (
        upper(coalesce(s.snooze_kind, '')) in ('TIMESHEET_PAYMENT', 'BLOCKED_TIMESHEET', 'DO_NOT_PAY')
        or upper(coalesce(s.snooze_kind, '')) like 'TIMESHEET%'
      )
  ),
  base_rows as (
    select * from finance_rows
    union all
    select * from snoozed_timesheet_rows
  ),
  filtered_rows as (
    select
      br.row_group,
      br.row_kind,
      br.finance_case_id,
      br.case_type,
      br.candidate_id,
      br.candidate_tms_ref,
      br.candidate_display_name,
      br.candidate_first_name,
      br.candidate_last_name,
      br.client_id,
      br.client_name,
      br.linked_timesheet_id,
      br.linked_shift_date,
      br.payout_pay_batch_id,
      br.payout_transfer_id,
      br.latest_recovery_pay_batch_id,
      br.created_at,
      br.start_week_start,
      br.next_due_week_start,
      br.original_amount,
      br.recovered_total,
      br.remaining_outstanding,
      br.due_this_week,
      br.status,
      br.payout_status,
      br.baseline_signature,
      br.reason,
      br.notes,
      br.adjustment_comment,
      br.source_original_paid_amount,
      br.source_corrected_paid_amount,
      br.minimum_earnings_threshold,
      br.take_home_floor_override,
      br.active_snooze_id,
      br.active_snooze_kind,
      br.active_snooze_until_date,
      br.active_snooze_note,
      br.snooze_status,
      br.lifecycle_state,
      br.authoritative_payment_date,
      br.payout_or_recovery_status,
      br.source_booking_id,
      br.source_week_ending_date,
      br.source_shift_label_norm
    from base_rows br
    where (v_type_filter is null or br.row_group = v_type_filter)
      and (
        v_status = ''
        or upper(coalesce(br.lifecycle_state, '')) = v_status
        or upper(coalesce(br.status, '')) = v_status
        or upper(coalesce(br.payout_or_recovery_status, '')) = v_status
        or upper(coalesce(br.row_group, '')) = v_status
      )
      and (p_client_id is null or br.client_id is not distinct from p_client_id)
      and (
        coalesce(p_outstanding_only, true) = false
        or br.row_group = 'SNOOZED_DEFERRED'
        or coalesce(br.remaining_outstanding, 0) > 0
      )
      and (
        coalesce(p_due_this_week_only, false) = false
        or coalesce(br.due_this_week, 0) > 0
      )
      and (p_amount_min is null or coalesce(br.remaining_outstanding, 0) >= round(p_amount_min, 2))
      and (p_amount_max is null or coalesce(br.remaining_outstanding, 0) <= round(p_amount_max, 2))
      and (
        p_created_from is null
        or br.created_at is not null
        and (br.created_at at time zone 'Europe/London')::date >= p_created_from
      )
      and (
        p_created_to is null
        or br.created_at is not null
        and (br.created_at at time zone 'Europe/London')::date <= p_created_to
      )
      and (
        v_search is null
        or coalesce(br.candidate_tms_ref, '') ilike '%' || v_search || '%'
        or coalesce(br.candidate_display_name, '') ilike '%' || v_search || '%'
        or coalesce(br.candidate_first_name, '') ilike '%' || v_search || '%'
        or coalesce(br.candidate_last_name, '') ilike '%' || v_search || '%'
        or coalesce(br.client_name, '') ilike '%' || v_search || '%'
        or coalesce(br.adjustment_comment, '') ilike '%' || v_search || '%'
        or coalesce(br.notes, '') ilike '%' || v_search || '%'
        or coalesce(br.reason, '') ilike '%' || v_search || '%'
      )
  ),
  counted_rows as (
    select count(*)::int as total_count from filtered_rows
  ),
  summary_rows as (
    select
      jsonb_build_object(
        'row_count', count(*)::int,
        'week_start', v_week_start::text,
        'week_end', v_week_end::text,
        'as_of_date', v_as_of_date::text,
        'counts_by_group', jsonb_build_object(
          'PAYMENT_ADVANCE', count(*) filter (where fr.row_group = 'PAYMENT_ADVANCE'),
          'OVERPAYMENT', count(*) filter (where fr.row_group = 'OVERPAYMENT'),
          'MANUAL_DEBT_ADJUSTMENT', count(*) filter (where fr.row_group = 'MANUAL_DEBT_ADJUSTMENT'),
          'MANUAL_CREDIT_ADJUSTMENT', count(*) filter (where fr.row_group = 'MANUAL_CREDIT_ADJUSTMENT'),
          'SNOOZED_DEFERRED', count(*) filter (where fr.row_group = 'SNOOZED_DEFERRED')
        ),
        'totals_by_group', jsonb_build_object(
          'PAYMENT_ADVANCE', round(coalesce(sum(case when fr.row_group = 'PAYMENT_ADVANCE' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
          'OVERPAYMENT', round(coalesce(sum(case when fr.row_group = 'OVERPAYMENT' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
          'MANUAL_DEBT_ADJUSTMENT', round(coalesce(sum(case when fr.row_group = 'MANUAL_DEBT_ADJUSTMENT' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
          'MANUAL_CREDIT_ADJUSTMENT', round(coalesce(sum(case when fr.row_group = 'MANUAL_CREDIT_ADJUSTMENT' then fr.original_amount else 0 end), 0), 2)::numeric(12,2),
          'SNOOZED_DEFERRED', round(coalesce(sum(case when fr.row_group = 'SNOOZED_DEFERRED' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2)
        ),
        'due_this_week_total', round(coalesce(sum(coalesce(fr.due_this_week, 0)), 0), 2)::numeric(12,2)
      ) as summary_json
    from filtered_rows fr
  ),
  ordered_rows as (
    select
      fr.row_group,
      fr.row_kind,
      fr.finance_case_id,
      fr.case_type,
      fr.candidate_id,
      fr.candidate_tms_ref,
      fr.candidate_display_name,
      fr.candidate_first_name,
      fr.candidate_last_name,
      fr.client_id,
      fr.client_name,
      fr.linked_timesheet_id,
      fr.linked_shift_date,
      fr.payout_pay_batch_id,
      fr.payout_transfer_id,
      fr.latest_recovery_pay_batch_id,
      fr.created_at,
      fr.start_week_start,
      fr.next_due_week_start,
      fr.original_amount,
      fr.recovered_total,
      fr.remaining_outstanding,
      fr.due_this_week,
      fr.status,
      fr.payout_status,
      fr.baseline_signature,
      fr.reason,
      fr.notes,
      fr.adjustment_comment,
      fr.source_original_paid_amount,
      fr.source_corrected_paid_amount,
      fr.minimum_earnings_threshold,
      fr.take_home_floor_override,
      fr.active_snooze_id,
      fr.active_snooze_kind,
      fr.active_snooze_until_date,
      fr.active_snooze_note,
      fr.snooze_status,
      fr.lifecycle_state,
      fr.authoritative_payment_date,
      fr.payout_or_recovery_status,
      fr.source_booking_id,
      fr.source_week_ending_date,
      fr.source_shift_label_norm
    from filtered_rows fr
    order by
      case when v_sort_dir = 'ASC' and v_sort_key = 'candidate' then lower(coalesce(fr.candidate_display_name, fr.candidate_tms_ref, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'candidate' then lower(coalesce(fr.candidate_display_name, fr.candidate_tms_ref, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'client' then lower(coalesce(fr.client_name, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'client' then lower(coalesce(fr.client_name, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'type' then lower(coalesce(fr.row_group, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'type' then lower(coalesce(fr.row_group, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'status' then lower(coalesce(fr.lifecycle_state, fr.status, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'status' then lower(coalesce(fr.lifecycle_state, fr.status, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'created_at' then fr.created_at end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'created_at' then fr.created_at end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'original_amount' then fr.original_amount end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'original_amount' then fr.original_amount end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'recovered_total' then fr.recovered_total end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'recovered_total' then fr.recovered_total end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'remaining_outstanding' then fr.remaining_outstanding end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'remaining_outstanding' then fr.remaining_outstanding end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'due_this_week' then coalesce(fr.due_this_week, 0) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'due_this_week' then coalesce(fr.due_this_week, 0) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'start_week_start' then fr.start_week_start end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'start_week_start' then fr.start_week_start end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'next_due_week_start' then fr.next_due_week_start end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'next_due_week_start' then fr.next_due_week_start end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'authoritative_payment_date' then fr.authoritative_payment_date end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'authoritative_payment_date' then fr.authoritative_payment_date end desc nulls last,
      fr.created_at desc nulls last,
      fr.finance_case_id asc nulls last,
      fr.linked_timesheet_id asc nulls last
    limit v_limit
    offset v_offset
  )
  select
    coalesce(cr.total_count, 0),
    coalesce(sr.summary_json, '{}'::jsonb),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'record_type', orw.row_group,
          'row_group', orw.row_group,
          'row_kind', orw.row_kind,
          'finance_case_id', case when orw.finance_case_id is null then null else orw.finance_case_id::text end,
          'case_type', orw.case_type,
          'candidate_id', orw.candidate_id::text,
          'candidate_tms_ref', orw.candidate_tms_ref,
          'candidate_display_name', orw.candidate_display_name,
          'candidate_first_name', orw.candidate_first_name,
          'candidate_last_name', orw.candidate_last_name,
          'client_id', case when orw.client_id is null then null else orw.client_id::text end,
          'client_name', orw.client_name,
          'linked_timesheet_id', case when orw.linked_timesheet_id is null then null else orw.linked_timesheet_id::text end,
          'linked_shift_date', case when orw.linked_shift_date is null then null else orw.linked_shift_date::text end,
          'payout_pay_batch_id', case when orw.payout_pay_batch_id is null then null else orw.payout_pay_batch_id::text end,
          'payout_transfer_id', case when orw.payout_transfer_id is null then null else orw.payout_transfer_id::text end,
          'latest_recovery_pay_batch_id', case when orw.latest_recovery_pay_batch_id is null then null else orw.latest_recovery_pay_batch_id::text end,
          'created_at', case when orw.created_at is null then null else orw.created_at::text end,
          'start_week_start', case when orw.start_week_start is null then null else orw.start_week_start::text end,
          'next_due_week_start', case when orw.next_due_week_start is null then null else orw.next_due_week_start::text end,
          'original_amount', orw.original_amount,
          'recovered_total', orw.recovered_total,
          'remaining_outstanding', orw.remaining_outstanding,
          'due_this_week', orw.due_this_week,
          'status', orw.status,
          'payout_status', orw.payout_status,
          'baseline_signature', orw.baseline_signature,
          'reason', orw.reason,
          'notes', orw.notes,
          'adjustment_comment', orw.adjustment_comment,
          'source_original_paid_amount', orw.source_original_paid_amount,
          'source_corrected_paid_amount', orw.source_corrected_paid_amount,
          'minimum_earnings_threshold', orw.minimum_earnings_threshold,
          'take_home_floor_override', orw.take_home_floor_override,
          'active_snooze_id', case when orw.active_snooze_id is null then null else orw.active_snooze_id::text end,
          'active_snooze_kind', orw.active_snooze_kind,
          'active_snooze_until_date', case when orw.active_snooze_until_date is null then null else orw.active_snooze_until_date::text end,
          'active_snooze_note', orw.active_snooze_note,
          'snooze_status', orw.snooze_status,
          'lifecycle_state', orw.lifecycle_state,
          'authoritative_payment_date', case when orw.authoritative_payment_date is null then null else orw.authoritative_payment_date::text end,
          'payout_or_recovery_status', orw.payout_or_recovery_status,
          'source_booking_id', orw.source_booking_id,
          'source_week_ending_date', case when orw.source_week_ending_date is null then null else orw.source_week_ending_date::text end,
          'source_shift_label_norm', orw.source_shift_label_norm
        )
      ),
      '[]'::jsonb
    )
  into
    v_total_count,
    v_summary,
    v_rows
  from ordered_rows orw
  cross join counted_rows cr
  cross join summary_rows sr;

  return jsonb_build_object(
    'ok', true,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb),
    'meta', jsonb_build_object(
      'as_of_date', v_as_of_date::text,
      'today_uk', v_today_uk::text,
      'week_start', v_week_start::text,
      'week_end', v_week_end::text,
      'total_count', v_total_count,
      'limit', v_limit,
      'offset', v_offset,
      'sort_key', v_sort_key,
      'sort_dir', v_sort_dir,
      'applied_filters', jsonb_build_object(
        'search', v_search,
        'type', case when v_type_filter is null then null else v_type_filter end,
        'status', case when v_status = '' then null else v_status end,
        'client_id', case when p_client_id is null then null else p_client_id::text end,
        'outstanding_only', coalesce(p_outstanding_only, true),
        'due_this_week_only', coalesce(p_due_this_week_only, false),
        'amount_min', p_amount_min,
        'amount_max', p_amount_max,
        'created_from', case when p_created_from is null then null else p_created_from::text end,
        'created_to', case when p_created_to is null then null else p_created_to::text end
      )
    )
  );
end;
$function$;

-- pay_bank_csv_export_summary_get(uuid,text,uuid)
CREATE OR REPLACE FUNCTION public.pay_bank_csv_export_summary_get(p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
    v_batch_row public.pay_batches%ROWTYPE;
    v_batch_status_upper text := NULL;
    v_execution_commit_state text := 'NOT_SUBMITTED';
    v_execution_commit_ref text := NULL;
    v_execution_committed_at_utc timestamptz := NULL;
    v_pre_execution_export boolean := false;

    v_row_count integer := 0;
    v_total_amount numeric := 0;
    v_current_transfer_hash text := NULL;
    v_current_transfer_hash_basis text := NULL;

    v_pending_row_count integer := 0;
    v_pending_total_amount numeric := 0;
    v_pending_transfer_hash text := NULL;

    v_stable_row_count integer := 0;
    v_stable_total_amount numeric := 0;
    v_stable_transfer_hash text := NULL;

    v_blocked_row_count integer := 0;
    v_all_transfer_count integer := 0;
    v_pay_channels_included jsonb := '[]'::jsonb;
    v_status_counts jsonb := '{}'::jsonb;
    v_provider_counts jsonb := '{}'::jsonb;
    v_rail_env_counts jsonb := '{}'::jsonb;
    v_exportable_status_filter text := NULL;
    v_bank_csv_export_hash text := NULL;
BEGIN
    IF p_pay_batch_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_ID_REQUIRED',
            'message', 'pay_bank_csv_export_summary_get: pay_batch_id is required'
        )::text;
    END IF;

    IF v_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'INVALID_SCOPE',
            'message', 'pay_bank_csv_export_summary_get: scope must be ALL, PAYE, or UMBRELLA',
            'scope', p_scope
        )::text;
    END IF;

    IF p_actor_user_id IS NOT NULL THEN
        PERFORM 1
        FROM public.tms_users AS actor_user
        WHERE actor_user.id = p_actor_user_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
                'code', 'ACTOR_USER_NOT_FOUND',
                'message', 'pay_bank_csv_export_summary_get: actor user was not found',
                'actor_user_id', p_actor_user_id::text,
                'pay_batch_id', p_pay_batch_id::text
            )::text;
        END IF;
    END IF;

    SELECT pay_batch.*
    INTO v_batch_row
    FROM public.pay_batches AS pay_batch
    WHERE pay_batch.id = p_pay_batch_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_NOT_FOUND',
            'message', 'pay_bank_csv_export_summary_get: pay batch was not found',
            'pay_batch_id', p_pay_batch_id::text
        )::text;
    END IF;

    v_batch_status_upper := upper(btrim(coalesce(v_batch_row.status, '')));
    v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));

    IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
        v_execution_commit_state := 'NOT_SUBMITTED';
    END IF;

    v_execution_commit_ref := nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '');
    v_execution_committed_at_utc := v_batch_row.execution_committed_at_utc;
    v_bank_csv_export_hash := nullif(btrim(coalesce(v_batch_row.bank_csv_export_json->>'transfer_hash', '')), '');

    v_pre_execution_export := (
        v_batch_row.cancelled_at_utc IS NULL
        AND v_batch_status_upper NOT IN ('CANCELLED', 'CANCELED')
        AND v_execution_commit_state = 'NOT_SUBMITTED'
        AND v_execution_commit_ref IS NULL
        AND v_execution_committed_at_utc IS NULL
    );

    SELECT
        count(*)::integer,
        round(coalesce(sum(CASE WHEN upper(coalesce(pending_transfer.status, '')) = 'PENDING' THEN pending_transfer.amount ELSE 0 END), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', pending_transfer.id,
                'candidate_id', pending_transfer.candidate_id,
                'umbrella_id', pending_transfer.umbrella_id,
                'pay_channel', pending_transfer.pay_channel,
                'amount', pending_transfer.amount,
                'currency', pending_transfer.currency,
                'payment_reference', pending_transfer.payment_reference,
                'payee_name', pending_transfer.payee_name,
                'sort_code_digits', pending_transfer.sort_code_digits,
                'account_number_digits', pending_transfer.account_number_digits,
                'account_type', pending_transfer.account_type,
                'bank_details_hash_snapshot', pending_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', pending_transfer.payee_entity_kind,
                'payee_entity_id', pending_transfer.payee_entity_id,
                'transfer_group_key', pending_transfer.transfer_group_key
            )
            ORDER BY pending_transfer.id
        )::text, '[]'))
    INTO
        v_pending_row_count,
        v_pending_total_amount,
        v_pending_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key,
            transfer_row.status AS status
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) = 'PENDING'
        ORDER BY transfer_row.id
    ) AS pending_transfer;

    SELECT
        count(*)::integer,
        round(coalesce(sum(stable_transfer.amount), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', stable_transfer.id,
                'candidate_id', stable_transfer.candidate_id,
                'umbrella_id', stable_transfer.umbrella_id,
                'pay_channel', stable_transfer.pay_channel,
                'amount', stable_transfer.amount,
                'currency', stable_transfer.currency,
                'payment_reference', stable_transfer.payment_reference,
                'payee_name', stable_transfer.payee_name,
                'sort_code_digits', stable_transfer.sort_code_digits,
                'account_number_digits', stable_transfer.account_number_digits,
                'account_type', stable_transfer.account_type,
                'bank_details_hash_snapshot', stable_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', stable_transfer.payee_entity_kind,
                'payee_entity_id', stable_transfer.payee_entity_id,
                'transfer_group_key', stable_transfer.transfer_group_key
            )
            ORDER BY stable_transfer.id
        )::text, '[]'))
    INTO
        v_stable_row_count,
        v_stable_total_amount,
        v_stable_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED'
        ORDER BY transfer_row.id
    ) AS stable_transfer;

    IF v_pre_execution_export THEN
        v_row_count := coalesce(v_pending_row_count, 0);
        v_total_amount := coalesce(v_pending_total_amount, 0);
        v_current_transfer_hash := v_pending_transfer_hash;
        v_current_transfer_hash_basis := 'PENDING_TRANSFER_HASH';
        v_exportable_status_filter := 'PENDING';
    ELSE
        v_row_count := coalesce(v_stable_row_count, 0);
        v_total_amount := coalesce(v_stable_total_amount, 0);
        v_current_transfer_hash := v_stable_transfer_hash;
        v_current_transfer_hash_basis := 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH';
        v_exportable_status_filter := 'ALL_NON_BLOCKED';
    END IF;

    SELECT count(*)::integer
    INTO v_all_transfer_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope);

    SELECT count(*)::integer
    INTO v_blocked_row_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
      AND upper(coalesce(transfer_row.status, '')) = 'BLOCKED';

    SELECT coalesce(jsonb_agg(to_jsonb(pay_channel_values.pay_channel) ORDER BY pay_channel_values.pay_channel), '[]'::jsonb)
    INTO v_pay_channels_included
    FROM (
        SELECT DISTINCT upper(coalesce(transfer_row.pay_channel, '')) AS pay_channel
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
    ) AS pay_channel_values
    WHERE pay_channel_values.pay_channel <> '';

    SELECT coalesce(jsonb_object_agg(status_counts.status_key, status_counts.status_count ORDER BY status_counts.status_key), '{}'::jsonb)
    INTO v_status_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.status, '')) AS status_key,
            count(*)::integer AS status_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
        GROUP BY upper(coalesce(transfer_row.status, ''))
    ) AS status_counts
    WHERE status_counts.status_key <> '';

    SELECT coalesce(jsonb_object_agg(provider_counts.provider_key, provider_counts.provider_count ORDER BY provider_counts.provider_key), '{}'::jsonb)
    INTO v_provider_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_provider, '')) AS provider_key,
            count(*)::integer AS provider_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_provider, ''))
    ) AS provider_counts
    WHERE provider_counts.provider_key <> '';

    SELECT coalesce(jsonb_object_agg(env_counts.env_key, env_counts.env_count ORDER BY env_counts.env_key), '{}'::jsonb)
    INTO v_rail_env_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_env, '')) AS env_key,
            count(*)::integer AS env_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_env, ''))
    ) AS env_counts
    WHERE env_counts.env_key <> '';

    RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'pay_channel_scope', v_scope,
        'pre_execution_export', v_pre_execution_export,
        'exportable_status_filter', v_exportable_status_filter,
        'row_count', coalesce(v_row_count, 0),
        'total_amount', coalesce(v_total_amount, 0),
        'transfer_hash', v_current_transfer_hash,
        'current_transfer_hash', v_current_transfer_hash,
        'current_transfer_hash_basis', v_current_transfer_hash_basis,
        'pending_transfer_hash', v_pending_transfer_hash,
        'stable_transfer_hash', v_stable_transfer_hash,
        'provider_snapshot', nullif(btrim(coalesce(v_batch_row.rail_provider_snapshot, '')), ''),
        'rail_env_snapshot', nullif(btrim(coalesce(v_batch_row.rail_env_snapshot, '')), ''),
        'freshness_validation_status', nullif(upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))), ''),
        'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END,
        'freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), ''),
        'freshness_scope_hash', nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'bank_csv_export_hash', v_bank_csv_export_hash,
        'csv_export_matches_current_transfers', CASE WHEN v_bank_csv_export_hash IS NULL OR v_current_transfer_hash IS NULL THEN NULL ELSE v_bank_csv_export_hash = v_current_transfer_hash END,
        'pending_row_count', coalesce(v_pending_row_count, 0),
        'pending_total_amount', coalesce(v_pending_total_amount, 0),
        'stable_row_count', coalesce(v_stable_row_count, 0),
        'stable_total_amount', coalesce(v_stable_total_amount, 0),
        'blocked_row_count', coalesce(v_blocked_row_count, 0),
        'all_transfer_count', coalesce(v_all_transfer_count, 0),
        'pay_channels_included', coalesce(v_pay_channels_included, '[]'::jsonb),
        'status_counts', coalesce(v_status_counts, '{}'::jsonb),
        'provider_counts', coalesce(v_provider_counts, '{}'::jsonb),
        'rail_env_counts', coalesce(v_rail_env_counts, '{}'::jsonb),
        'summary_source', 'pay_bank_transfers',
        'policy_x_authority', 'FROZEN_MATERIALISED_TRANSFER_ROWS',
        'generated_at_utc', now()::text
    ));
END;
$function$;

-- pay_bank_event_ingest(jsonb,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_bank_event_ingest(p_event_json jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_ingest_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_event_json jsonb := COALESCE(p_event_json, '{}'::jsonb);
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_now timestamptz := now();
  v_ingest_options_json jsonb := COALESCE(p_ingest_options_json, '{}'::jsonb);
  v_touch_signal boolean := true;
  v_signal_mode text := 'IMMEDIATE';
  v_should_touch_signal boolean := true;
  v_source_delivery_id text := NULL::text;
  v_source_batch_event_group_key text := NULL::text;
  v_signal_recommendation_json jsonb := '{}'::jsonb;

  v_pay_batch_id uuid := NULL::uuid;
  v_supplied_pay_batch_id uuid := NULL::uuid;
  v_pay_batch_id_text text;
  v_pay_bank_transfer_id uuid := NULL::uuid;
  v_pay_bank_transfer_id_text text;
  v_candidate_id uuid := NULL::uuid;
  v_candidate_id_text text;
  v_umbrella_id uuid := NULL::uuid;
  v_umbrella_id_text text;

  v_provider_key text;
  v_provider_event_id text;
  v_provider_reference text;
  v_provider_state text;
  v_normalised_state text;
  v_event_source text;
  v_event_time_utc timestamptz := NULL::timestamptz;
  v_event_time_text text;
  v_amount numeric := NULL::numeric;
  v_amount_text text;
  v_currency text := 'GBP';
  v_raw_payload jsonb := '{}'::jsonb;
  v_idempotency_key text;
  v_provider_webhook_receipt_id uuid := NULL::uuid;
  v_provider_webhook_receipt_id_text text := NULL::text;
  v_provider_webhook_id text := NULL::text;
  v_provider_event_type text := NULL::text;
  v_provider_transaction_id text := NULL::text;
  v_provider_request_id text := NULL::text;
  v_provider_event_key text := NULL::text;
  v_provider_signature_valid boolean := NULL::boolean;
  v_provider_event_transport text := NULL::text;
  v_adapter_key text := NULL::text;
  v_adapter_version text := NULL::text;
  v_rail_env text := NULL::text;
  v_provider_failure_reason_code text := NULL::text;
  v_provider_failure_reason_group text := NULL::text;
  v_provider_failure_reason_label text := NULL::text;
  v_receipt_status text := NULL::text;
  v_receipt_provider_key text := NULL::text;
  v_receipt_rail_env text := NULL::text;
  v_receipt_provider_event_key text := NULL::text;
  v_receipt_signature_valid boolean := NULL::boolean;
  v_receipt_normalised_events_json jsonb := '[]'::jsonb;
  v_receipt_ingest_results_json jsonb := '[]'::jsonb;
  v_provider_event_key_in_receipt boolean := false;
  v_webhook_gate_ok boolean := false;
  v_replay_gate_ok boolean := false;
  v_mapping_hints_json jsonb := '{}'::jsonb;
  v_failure_reason_result jsonb := '{}'::jsonb;
  v_live_signal_result jsonb := '{}'::jsonb;

  v_mapping_status text := 'UNMATCHED';
  v_mapping_method text := 'UNMATCHED';
  v_mapping_candidate_count integer := 0;
  v_has_strong_transfer_mapping boolean := false;
  v_existing_transfer_is_final_paid boolean := false;
  v_pre_insert_pay_batch_id uuid := NULL::uuid;
  v_pre_insert_pay_bank_transfer_id uuid := NULL::uuid;
  v_pre_insert_candidate_id uuid := NULL::uuid;
  v_pre_insert_umbrella_id uuid := NULL::uuid;
  v_pre_insert_mapping_status text := NULL::text;
  v_pre_insert_mapping_method text := NULL::text;
  v_duplicate_event_should_continue boolean := false;

  v_transfer public.pay_bank_transfers%rowtype;
  v_batch public.pay_batches%rowtype;
  v_event_id uuid := NULL::uuid;
  v_inserted_event boolean := false;

  v_selection_json jsonb := '{}'::jsonb;
  v_classification_result jsonb := '{}'::jsonb;
  v_classification text := 'AMBIGUOUS_REVIEW_REQUIRED';
  v_safe_to_auto_apply boolean := false;
  v_auto_setting boolean := false;
  v_correction_disposition text := 'AMBIGUOUS';

  v_correction_request_id uuid := NULL::uuid;
  v_request_start_result jsonb := NULL::jsonb;
  v_expand_result jsonb := NULL::jsonb;
  v_process_result jsonb := NULL::jsonb;

  v_admin_notice_group_id uuid := NULL::uuid;
  v_admin_notice_result jsonb := NULL::jsonb;
  v_notice_kind text := 'BANK_FAILURE_DETECTED';
  v_exact_mapping_required_blocker jsonb := NULL::jsonb;

  v_provider_state_upper text := NULL::text;
  v_money_movement_classification record;
  v_event_cash_state text := 'UNKNOWN';
  v_event_is_final_paid boolean := false;
  v_event_is_terminal_no_money boolean := false;
  v_event_is_pending_non_final boolean := false;
  v_event_required_action text := NULL::text;
  v_auto_unwind_blocker jsonb := NULL::jsonb;
  v_auto_unwind_result jsonb := NULL::jsonb;
  v_final_work_item_totals jsonb := jsonb_build_object(
    'total', 0,
    'applied', 0,
    'skipped', 0,
    'blocked', 0,
    'failed_retryable', 0,
    'failed_final', 0,
    'pending', 0,
    'processing', 0
  );
  v_carry_forward_mark_result jsonb := '{}'::jsonb;
  v_consumed_carry_forward_count integer := 0;
  v_work_total_count integer := 0;
  v_work_applied_count integer := 0;
  v_work_skipped_count integer := 0;
  v_work_blocked_count integer := 0;
  v_work_failed_retryable_count integer := 0;
  v_work_failed_final_count integer := 0;
  v_work_pending_count integer := 0;
  v_work_processing_count integer := 0;

  v_terminal_bank_event boolean := false;
  v_settlement_required boolean := false;
  v_settlement_trigger text := 'BANK_EVENT_NON_TERMINAL';
  v_all_batch_transfers_terminal boolean := false;
  v_terminal_success_transfer_count integer := 0;
  v_terminal_failed_transfer_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_unknown_transfer_count integer := 0;
  v_pending_or_unknown_transfer_count integer := 0;
  v_settlement_intent_json jsonb := '{}'::jsonb;
  v_settlement_actor_user_id uuid := NULL::uuid;
  v_settlement_apply_result jsonb := '{}'::jsonb;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_suppress_auto_unwind boolean := false;
  v_manual_confirmed_not_paid boolean := false;
  v_paid_after_release boolean := false;
  v_review_acknowledgement boolean := false;
  v_manual_scope_mode boolean := false;
  v_manual_scope_pay_batch_candidate_id uuid := NULL::uuid;
  v_manual_scope_pay_batch_candidate_id_text text := NULL::text;
  v_manual_scope_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_manual_scope_diagnostic_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_manual_scope_member_json jsonb := NULL::jsonb;
  v_manual_scope_member_text text := NULL::text;
  v_manual_scope_diagnostic jsonb := '{}'::jsonb;
  v_manual_scope_result jsonb := '{}'::jsonb;
  v_manual_scope_first_result jsonb := NULL::jsonb;
  v_manual_scope_event_ids jsonb := '[]'::jsonb;
  v_manual_scope_raw_continuations jsonb := '[]'::jsonb;
  v_manual_scope_continuations jsonb := '[]'::jsonb;
  v_manual_scope_idempotency_base text := NULL::text;
  v_manual_scope_hash text := NULL::text;
  v_manual_scope_expected_hash text := NULL::text;
  v_manual_scope_count integer := 0;
  v_manual_scope_distinct_count integer := 0;
  v_manual_scope_locked_count integer := 0;
  v_manual_scope_member_index integer := 0;
  v_manual_scope_all_idempotent boolean := true;
  v_manual_scope_any_inserted boolean := false;
  v_manual_scope_all_mapped boolean := true;
  v_manual_scope_requires_user_action boolean := false;
  v_manual_scope_paid_after_release boolean := false;
  v_manual_scope_release_eligible boolean := false;
  v_manual_scope_auto_release_started boolean := false;
  v_manual_scope_candidate public.pay_batch_candidates%rowtype;
BEGIN
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_BANK_EVENT_INGEST_START',
    jsonb_build_object(
      'actor_user_id', p_actor_user_id,
      'ingest_options', COALESCE(p_ingest_options_json, '{}'::jsonb),
      'event_keys', CASE
        WHEN p_event_json IS NULL OR jsonb_typeof(p_event_json) <> 'object' THEN '[]'::jsonb
        ELSE COALESCE((
          SELECT jsonb_agg(event_keys.key_name ORDER BY event_keys.key_name)
          FROM jsonb_object_keys(p_event_json) AS event_keys(key_name)
        ), '[]'::jsonb)
      END
    ),
    'pay_payment_correction',
    'BANK_EVENT_INGEST',
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_event_json IS NULL OR COALESCE(jsonb_typeof(p_event_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANK_EVENT_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANK_EVENT_JSON_MUST_BE_OBJECT')::text;
  END IF;

  IF p_ingest_options_json IS NULL THEN

    v_ingest_options_json := '{}'::jsonb;
  ELSIF COALESCE(jsonb_typeof(p_ingest_options_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANK_EVENT_INGEST_OPTIONS_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANK_EVENT_INGEST_OPTIONS_MUST_BE_OBJECT')::text;
  ELSE
    v_ingest_options_json := p_ingest_options_json;
  END IF;

  v_manual_scope_mode := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    v_ingest_options_json->>'manual_ambiguity_resolution',
    'false'
  ))) IN ('true','t','1','yes','y','on');

  v_suppress_auto_unwind := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    v_event_json->>'suppress_auto_unwind',
    v_ingest_options_json->>'suppress_auto_unwind',
    'false'
  ))) IN ('true','t','1','yes','y','on');
  v_manual_confirmed_not_paid := pg_catalog.upper(COALESCE(
    v_event_json->>'resolution', v_event_json->>'normalised_state', ''
  )) = 'CONFIRMED_NOT_PAID'
    AND pg_catalog.upper(COALESCE(v_event_json->>'event_source', '')) = 'MANUAL_EVIDENCE';
  v_review_acknowledgement := pg_catalog.upper(COALESCE(
    v_event_json->>'review_status', v_ingest_options_json->>'review_status', ''
  )) = 'ACKNOWLEDGED';

  IF v_ingest_options_json ? 'touch_signal' THEN
    v_touch_signal := lower(btrim(COALESCE(v_ingest_options_json->>'touch_signal', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  ELSE
    v_touch_signal := true;
  END IF;

  v_signal_mode := upper(nullif(btrim(COALESCE(v_ingest_options_json->>'signal_mode', 'IMMEDIATE')), ''));
  IF v_signal_mode IS NULL OR v_signal_mode NOT IN ('IMMEDIATE', 'DEFERRED') THEN
    v_signal_mode := 'IMMEDIATE';
  END IF;
  v_should_touch_signal := COALESCE(v_touch_signal, true) AND v_signal_mode <> 'DEFERRED';
  v_source_delivery_id := nullif(btrim(COALESCE(v_ingest_options_json->>'source_delivery_id', '')), '');
  v_source_batch_event_group_key := nullif(btrim(COALESCE(v_ingest_options_json->>'source_batch_event_group_key', '')), '');

  v_pay_batch_id_text := nullif(btrim(COALESCE(
    v_event_json->>'pay_batch_id',
    v_event_json->>'batch_id',
    ''
  )), '');

  v_pay_bank_transfer_id_text := nullif(btrim(COALESCE(
    v_event_json->>'pay_bank_transfer_id',
    v_event_json->>'transfer_id',
    v_event_json->>'bank_transfer_id',
    ''
  )), '');

  v_candidate_id_text := nullif(btrim(COALESCE(v_event_json->>'candidate_id', '')), '');
  v_umbrella_id_text := nullif(btrim(COALESCE(v_event_json->>'umbrella_id', '')), '');

  IF v_pay_batch_id_text IS NOT NULL THEN
    IF v_pay_batch_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'INVALID_PAY_BATCH_ID_IN_BANK_EVENT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'INVALID_PAY_BATCH_ID_IN_BANK_EVENT', 'pay_batch_id', v_pay_batch_id_text)::text;
    END IF;
    v_pay_batch_id := v_pay_batch_id_text::uuid;
    v_supplied_pay_batch_id := v_pay_batch_id;
  END IF;

  IF v_pay_bank_transfer_id_text IS NOT NULL THEN
    IF v_pay_bank_transfer_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'INVALID_PAY_BANK_TRANSFER_ID_IN_BANK_EVENT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'INVALID_PAY_BANK_TRANSFER_ID_IN_BANK_EVENT', 'pay_bank_transfer_id', v_pay_bank_transfer_id_text)::text;
    END IF;
    v_pay_bank_transfer_id := v_pay_bank_transfer_id_text::uuid;
  END IF;

  IF v_candidate_id_text IS NOT NULL THEN
    IF v_candidate_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_ID_IN_BANK_EVENT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'INVALID_CANDIDATE_ID_IN_BANK_EVENT', 'candidate_id', v_candidate_id_text)::text;
    END IF;
    v_candidate_id := v_candidate_id_text::uuid;
  END IF;

  IF v_umbrella_id_text IS NOT NULL THEN
    IF v_umbrella_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'INVALID_UMBRELLA_ID_IN_BANK_EVENT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'INVALID_UMBRELLA_ID_IN_BANK_EVENT', 'umbrella_id', v_umbrella_id_text)::text;
    END IF;
    v_umbrella_id := v_umbrella_id_text::uuid;
  END IF;

  v_provider_key := upper(nullif(btrim(COALESCE(v_event_json->>'provider_key', v_event_json->>'provider', v_event_json->>'rail_provider', '')), ''));
  v_provider_event_id := nullif(btrim(COALESCE(v_event_json->>'provider_event_id', v_event_json->>'event_id', v_event_json->>'id', '')), '');
  v_provider_webhook_receipt_id_text := nullif(btrim(COALESCE(v_event_json->>'provider_webhook_receipt_id', v_event_json->>'webhook_receipt_id', '')), '');
  IF v_provider_webhook_receipt_id_text IS NOT NULL THEN
    IF v_provider_webhook_receipt_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'INVALID_PROVIDER_WEBHOOK_RECEIPT_ID_IN_BANK_EVENT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'INVALID_PROVIDER_WEBHOOK_RECEIPT_ID_IN_BANK_EVENT', 'provider_webhook_receipt_id', v_provider_webhook_receipt_id_text)::text;
    END IF;
    v_provider_webhook_receipt_id := v_provider_webhook_receipt_id_text::uuid;
  END IF;
  v_provider_webhook_id := nullif(btrim(COALESCE(v_event_json->>'provider_webhook_id', v_event_json->>'webhook_id', '')), '');
  v_provider_event_type := nullif(btrim(COALESCE(v_event_json->>'provider_event_type', v_event_json->>'event_type', v_event_json->>'event', '')), '');
  v_provider_transaction_id := nullif(btrim(COALESCE(v_event_json->>'provider_transaction_id', v_event_json->>'transaction_id', v_event_json->>'provider_payment_id', v_event_json->>'payment_id', v_event_json #>> '{data,id}', '')), '');
  v_provider_request_id := nullif(btrim(COALESCE(v_event_json->>'provider_request_id', v_event_json->>'request_id', v_event_json #>> '{data,request_id}', '')), '');
  v_provider_event_key := nullif(btrim(COALESCE(v_event_json->>'provider_event_key', v_event_json->>'event_key', '')), '');
  v_provider_signature_valid := CASE
    WHEN v_event_json ? 'provider_signature_valid' OR v_event_json ? 'signature_valid' THEN lower(btrim(COALESCE(v_event_json->>'provider_signature_valid', v_event_json->>'signature_valid', ''))) IN ('true','t','1','yes','y','on')
    ELSE NULL::boolean
  END;
  v_provider_event_transport := upper(nullif(btrim(COALESCE(v_event_json->>'provider_event_transport', v_event_json->>'event_source', v_event_json->>'source', 'PROVIDER_POLL')), ''));
  v_adapter_key := nullif(btrim(COALESCE(v_event_json->>'adapter_key', '')), '');
  v_adapter_version := nullif(btrim(COALESCE(v_event_json->>'adapter_version', '')), '');
  v_rail_env := upper(nullif(btrim(COALESCE(v_event_json->>'rail_env', v_event_json->>'rail_environment', 'PROD')), ''));
  v_provider_failure_reason_code := nullif(btrim(COALESCE(v_event_json->>'provider_failure_reason_code', v_event_json->>'failure_reason_code', v_event_json->>'reason_code', v_event_json->>'error_code', v_event_json #>> '{data,reason_code}', v_event_json #>> '{data,error_code}', '')), '');
  v_provider_failure_reason_group := upper(nullif(btrim(COALESCE(v_event_json->>'provider_failure_reason_group', v_event_json->>'failure_reason_group', '')), ''));
  IF v_event_json ? 'mapping_hints_json' AND jsonb_typeof(v_event_json->'mapping_hints_json') = 'object' THEN
    v_mapping_hints_json := v_event_json->'mapping_hints_json';
  ELSIF v_event_json ? 'mapping_hints' AND jsonb_typeof(v_event_json->'mapping_hints') = 'object' THEN
    v_mapping_hints_json := v_event_json->'mapping_hints';
  ELSE
    v_mapping_hints_json := '{}'::jsonb;
  END IF;
  v_provider_reference := nullif(btrim(COALESCE(
    v_event_json->>'provider_reference',
    v_event_json->>'provider_ref',
    v_event_json->>'rail_tx_id',
    v_event_json->>'payment_reference',
    v_provider_transaction_id,
    ''
  )), '');
  v_provider_state := nullif(btrim(COALESCE(v_event_json->>'provider_state', v_event_json->>'state', v_event_json->>'status', v_event_json #>> '{data,new_state}', v_event_json #>> '{data,state}', '')), '');
  v_normalised_state := upper(nullif(btrim(COALESCE(v_event_json->>'normalised_state', v_event_json->>'normalized_state', v_provider_state, 'UNKNOWN')), ''));
  v_event_source := v_provider_event_transport;
  v_event_time_text := nullif(btrim(COALESCE(v_event_json->>'event_time_utc', v_event_json->>'event_time', v_event_json->>'created_at', v_event_json->>'timestamp', '')), '');
  v_amount_text := nullif(btrim(COALESCE(v_event_json->>'amount', v_event_json->>'amount_inc_vat', '')), '');
  v_currency := upper(nullif(btrim(COALESCE(v_event_json->>'currency', 'GBP')), ''));
  v_raw_payload := COALESCE(v_event_json->'raw_payload', v_event_json);

  IF v_event_time_text IS NOT NULL THEN
    BEGIN
      v_event_time_utc := v_event_time_text::timestamptz;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE EXCEPTION 'INVALID_BANK_EVENT_TIME'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'INVALID_BANK_EVENT_TIME', 'event_time_utc', v_event_time_text)::text;
    END;
  END IF;

  IF v_amount_text IS NOT NULL THEN
    BEGIN
      v_amount := v_amount_text::numeric;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE EXCEPTION 'INVALID_BANK_EVENT_AMOUNT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'INVALID_BANK_EVENT_AMOUNT', 'amount', v_amount_text)::text;
    END;
  END IF;

  SELECT classification_rows.*
  INTO v_money_movement_classification
  FROM public._pay_rail_state_money_movement_classify(
    v_normalised_state,
    v_provider_state,
    COALESCE(v_event_json, '{}'::jsonb),
    COALESCE(v_raw_payload, '{}'::jsonb)
  ) AS classification_rows
  LIMIT 1;

  v_event_cash_state := COALESCE(v_money_movement_classification.cash_state, 'UNKNOWN');
  v_event_is_final_paid := COALESCE(v_money_movement_classification.is_final_money_moved, false);
  v_event_is_terminal_no_money := COALESCE(v_money_movement_classification.is_terminal_no_money, false);
  v_event_is_pending_non_final := COALESCE(v_money_movement_classification.is_pending_non_final, false);

  v_normalised_state := CASE
    WHEN v_event_is_final_paid THEN 'COMPLETED'
    WHEN v_event_is_terminal_no_money AND upper(btrim(coalesce(v_provider_state, v_normalised_state, ''))) IN ('CANCELED', 'CANCELLED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN 'CANCELLED'
    WHEN v_event_is_terminal_no_money THEN 'FAILED'
    WHEN v_event_is_pending_non_final AND upper(btrim(coalesce(v_provider_state, v_normalised_state, ''))) IN ('SUBMITTED', 'SENT') THEN 'SUBMITTED'
    WHEN v_event_is_pending_non_final AND upper(btrim(coalesce(v_provider_state, v_normalised_state, ''))) = 'PROCESSING' THEN 'PROCESSING'
    WHEN v_event_is_pending_non_final THEN 'PENDING'
    ELSE 'UNKNOWN'
  END;

  v_failure_reason_result := public._banking_provider_failure_reason_normalise(
    v_provider_key,
    COALESCE(v_provider_state, v_normalised_state),
    v_provider_failure_reason_code,
    COALESCE(v_event_json->>'provider_failure_reason_text', v_event_json->>'failure_reason', v_event_json->>'reason', v_event_json->>'message', v_event_json->>'error_message'),
    COALESCE(v_raw_payload, '{}'::jsonb)
  );
  v_provider_failure_reason_code := COALESCE(v_provider_failure_reason_code, NULLIF(BTRIM(v_failure_reason_result->>'failure_reason_code'), ''));

  v_provider_failure_reason_group := COALESCE(v_provider_failure_reason_group, NULLIF(BTRIM(v_failure_reason_result->>'failure_reason_group'), ''));
  v_provider_failure_reason_label := NULLIF(BTRIM(v_failure_reason_result->>'failure_reason_label'), '');

  v_provider_state_upper := upper(btrim(coalesce(v_provider_state, '')));

  IF v_event_source NOT IN ('PROVIDER_RESPONSE', 'PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'FAILED_WEBHOOK_REPLAY', 'MANUAL_CONFIRM', 'MANUAL_EVIDENCE', 'SYSTEM') THEN
    v_event_source := CASE
      WHEN v_event_source LIKE '%FAILED%WEBHOOK%REPLAY%' THEN 'FAILED_WEBHOOK_REPLAY'
      WHEN v_event_source LIKE '%WEBHOOK%' THEN 'PROVIDER_WEBHOOK'
      WHEN v_event_source LIKE '%RESPONSE%' THEN 'PROVIDER_RESPONSE'
      WHEN v_event_source LIKE '%MANUAL%EVIDENCE%' THEN 'MANUAL_EVIDENCE'
      WHEN v_event_source LIKE '%MANUAL%' THEN 'MANUAL_CONFIRM'
      WHEN v_event_source LIKE '%SYSTEM%' THEN 'SYSTEM'
      ELSE 'PROVIDER_POLL'
    END;
  END IF;

  v_provider_event_transport := CASE
    WHEN v_event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'FAILED_WEBHOOK_REPLAY', 'MANUAL_CONFIRM') THEN v_event_source
    WHEN v_event_source = 'MANUAL_EVIDENCE' THEN 'MANUAL_CONFIRM'
    WHEN v_event_source = 'SYSTEM' THEN 'LOCAL_STATE'
    ELSE 'LOCAL_STATE'
  END;

  v_event_source := CASE
    WHEN v_provider_event_transport = 'PROVIDER_WEBHOOK' THEN 'PROVIDER_WEBHOOK'
    WHEN v_provider_event_transport = 'FAILED_WEBHOOK_REPLAY' THEN 'PROVIDER_WEBHOOK'
    WHEN v_provider_event_transport = 'PROVIDER_RESPONSE' THEN 'PROVIDER_POLL'
    WHEN v_provider_event_transport = 'PROVIDER_POLL' THEN 'PROVIDER_POLL'
    WHEN COALESCE(v_event_source, '') = 'MANUAL_EVIDENCE' THEN 'MANUAL_EVIDENCE'
    WHEN v_provider_event_transport = 'MANUAL_CONFIRM' THEN 'MANUAL_CONFIRM'
    ELSE 'SYSTEM'
  END;

  IF v_event_source IN ('MANUAL_CONFIRM', 'MANUAL_EVIDENCE')
     AND (
       p_actor_user_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.tms_users AS manual_actor
         WHERE manual_actor.id = p_actor_user_id
           AND COALESCE(manual_actor.is_active, false) IS TRUE
       )
     ) THEN
    RAISE EXCEPTION 'BANK_EVENT_MANUAL_ACTOR_REQUIRED'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PERMISSION_DENIED',
        'message', 'An active user is required to record manual payment evidence.'
      )::text;
  END IF;

  -- Manual ambiguity resolution is one bounded database command for the
  -- complete reviewed instruction scope.  Every member is validated before
  -- the first event is written.  Recursive member calls stay in this same
  -- PostgreSQL transaction, so any member failure rolls the entire scope back.
  IF v_manual_scope_mode THEN
    IF v_event_source IS DISTINCT FROM 'MANUAL_EVIDENCE'
       OR COALESCE(v_suppress_auto_unwind, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_SCOPE_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_SCOPE_INVALID',
          'message', 'Manual payment-status resolution must be evidence-only and cannot start an automatic release.'
        )::text;
    END IF;

    IF pg_catalog.upper(COALESCE(v_event_json->>'resolution', ''))
         NOT IN ('CONFIRMED_PAID', 'CONFIRMED_NOT_PAID') THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_OUTCOME_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_OUTCOME_INVALID'
        )::text;
    END IF;

    IF v_pay_batch_id IS NULL OR v_candidate_id IS NULL THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_SCOPE_AUTHORITY_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_SCOPE_AUTHORITY_REQUIRED'
        )::text;
    END IF;

    IF v_pay_bank_transfer_id_text IS NOT NULL
       OR COALESCE(jsonb_typeof(v_event_json->'pay_bank_transfer_ids'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_INVALID',
          'message', 'The complete transfer scope must be supplied as one bounded array.'
        )::text;
    END IF;

    v_manual_scope_count := pg_catalog.jsonb_array_length(v_event_json->'pay_bank_transfer_ids');
    IF v_manual_scope_count < 1 OR v_manual_scope_count > 128 THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_LIMIT'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_LIMIT',
          'minimum', 1,
          'maximum', 128,
          'actual', v_manual_scope_count
        )::text;
    END IF;

    FOR v_manual_scope_member_json IN
      SELECT scope_member.value
      FROM pg_catalog.jsonb_array_elements(v_event_json->'pay_bank_transfer_ids')
        WITH ORDINALITY AS scope_member(value, ordinality)
      ORDER BY scope_member.ordinality
    LOOP
      IF pg_catalog.jsonb_typeof(v_manual_scope_member_json) <> 'string' THEN
        RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_INVALID'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_INVALID'
          )::text;
      END IF;
      v_manual_scope_member_text := pg_catalog.btrim(v_manual_scope_member_json #>> '{}');
      IF v_manual_scope_member_text !~ v_uuid_regex
         OR pg_catalog.lower(v_manual_scope_member_text) IS DISTINCT FROM (v_manual_scope_member_text::uuid)::text THEN
        RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_INVALID'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_INVALID'
          )::text;
      END IF;
      v_manual_scope_transfer_ids := pg_catalog.array_append(
        v_manual_scope_transfer_ids,
        v_manual_scope_member_text::uuid
      );
    END LOOP;

    SELECT COALESCE(pg_catalog.array_agg(DISTINCT scope_id ORDER BY scope_id), ARRAY[]::uuid[]),
           pg_catalog.count(DISTINCT scope_id)::integer
    INTO v_manual_scope_transfer_ids, v_manual_scope_distinct_count
    FROM pg_catalog.unnest(v_manual_scope_transfer_ids) AS supplied_scope(scope_id);

    IF v_manual_scope_distinct_count IS DISTINCT FROM v_manual_scope_count THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_DUPLICATE'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_DUPLICATE'
        )::text;
    END IF;

    v_manual_scope_pay_batch_candidate_id_text := NULLIF(pg_catalog.btrim(COALESCE(
      v_event_json->>'pay_batch_candidate_id', ''
    )), '');
    IF v_manual_scope_pay_batch_candidate_id_text IS NULL
       OR v_manual_scope_pay_batch_candidate_id_text !~ v_uuid_regex
       OR pg_catalog.lower(v_manual_scope_pay_batch_candidate_id_text)
            IS DISTINCT FROM (v_manual_scope_pay_batch_candidate_id_text::uuid)::text THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_BATCH_CANDIDATE_INVALID'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_BATCH_CANDIDATE_INVALID'
        )::text;
    END IF;
    v_manual_scope_pay_batch_candidate_id := v_manual_scope_pay_batch_candidate_id_text::uuid;

    v_manual_scope_idempotency_base := NULLIF(pg_catalog.btrim(COALESCE(
      v_event_json->>'idempotency_key', ''
    )), '');
    IF v_manual_scope_idempotency_base IS NULL
       OR pg_catalog.octet_length(v_manual_scope_idempotency_base) > 1000 THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_IDEMPOTENCY_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_IDEMPOTENCY_REQUIRED'
        )::text;
    END IF;

    SELECT pg_catalog.encode(
             extensions.digest(
               pg_catalog.convert_to(
                 '["' || pg_catalog.array_to_string(
                   ARRAY(
                     SELECT scope_id::text
                     FROM pg_catalog.unnest(v_manual_scope_transfer_ids) AS sorted_scope(scope_id)
                     ORDER BY scope_id
                   ),
                   '","'
                 ) || '"]',
                 'UTF8'
               ),
               'sha256'
             ),
             'hex'
           )
    INTO v_manual_scope_hash;
    v_manual_scope_expected_hash := pg_catalog.lower(NULLIF(pg_catalog.btrim(COALESCE(
      v_ingest_options_json->>'instruction_scope_hash',
      v_mapping_hints_json->>'instruction_scope_hash',
      ''
    )), ''));
    IF v_manual_scope_expected_hash IS NULL
       OR v_manual_scope_expected_hash !~ '^[0-9a-f]{64}$'
       OR v_manual_scope_expected_hash IS DISTINCT FROM v_manual_scope_hash THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_SCOPE_HASH_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_SCOPE_HASH_MISMATCH'
        )::text;
    END IF;

    -- Hold the same mode-aware batch guard for the full member set.
    v_mutation_guard := private.pay_payment_mutation_guard_v1(
      v_pay_batch_id,
      NULL::uuid,
      'AUTHORITATIVE_EVENT'
    );
    IF COALESCE((v_mutation_guard->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION '%', COALESCE(v_mutation_guard->>'code', 'PAYMENT_MUTATION_LOCK_TIMEOUT')
        USING ERRCODE = 'P0001', DETAIL = v_mutation_guard::text;
    END IF;

    SELECT batch_row.*
    INTO v_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = v_pay_batch_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'BANK_EVENT_PAY_BATCH_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'BANK_EVENT_PAY_BATCH_NOT_FOUND'
        )::text;
    END IF;

    SELECT candidate_row.*
    INTO v_manual_scope_candidate
    FROM public.pay_batch_candidates AS candidate_row
    WHERE candidate_row.id = v_manual_scope_pay_batch_candidate_id
      AND candidate_row.pay_batch_id = v_pay_batch_id
      AND candidate_row.candidate_id = v_candidate_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_CANDIDATE_DOMAIN_MISMATCH'
        USING ERRCODE = '23503', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_CANDIDATE_DOMAIN_MISMATCH'
        )::text;
    END IF;

    v_manual_scope_diagnostic := public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id => v_pay_batch_id,
      p_selection_json => pg_catalog.jsonb_build_object(
        'scope_type', 'CANDIDATES',
        'pay_batch_candidate_ids', pg_catalog.jsonb_build_array(v_manual_scope_pay_batch_candidate_id),
        'requested_action', 'RESOLVE_PAYMENT_STATUS'
      ),
      p_actor_user_id => p_actor_user_id,
      p_diagnostic_context => 'CURRENT_PAYMENT_STATUS'
    );
    IF COALESCE((v_manual_scope_diagnostic->>'ok')::boolean, false) IS NOT TRUE
       OR COALESCE((v_manual_scope_diagnostic->>'requires_bank_check')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_RESOLUTION_NO_LONGER_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_RESOLUTION_NO_LONGER_REQUIRED'
        )::text;
    END IF;

    SELECT COALESCE(pg_catalog.array_agg(DISTINCT parsed_scope.scope_id ORDER BY parsed_scope.scope_id), ARRAY[]::uuid[])
    INTO v_manual_scope_diagnostic_transfer_ids
    FROM (
      SELECT raw_scope.scope_text::uuid AS scope_id
      FROM pg_catalog.jsonb_array_elements_text(
        CASE
          WHEN pg_catalog.jsonb_typeof(v_manual_scope_diagnostic #> '{resolved_full_payment_scope_json,pay_bank_transfer_ids}') = 'array'
            THEN v_manual_scope_diagnostic #> '{resolved_full_payment_scope_json,pay_bank_transfer_ids}'
          ELSE '[]'::jsonb
        END
      ) AS raw_scope(scope_text)
      WHERE raw_scope.scope_text ~ v_uuid_regex
    ) AS parsed_scope;
    IF v_manual_scope_diagnostic_transfer_ids IS DISTINCT FROM v_manual_scope_transfer_ids THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_SCOPE_CHANGED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_SCOPE_CHANGED'
        )::text;
    END IF;

    v_manual_scope_locked_count := 0;
    FOR v_transfer IN
      SELECT transfer_row.*
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.id = ANY(v_manual_scope_transfer_ids)
        AND transfer_row.pay_batch_id = v_pay_batch_id
      ORDER BY transfer_row.id
      FOR UPDATE
    LOOP
      v_manual_scope_locked_count := v_manual_scope_locked_count + 1;
    END LOOP;
    IF v_manual_scope_locked_count IS DISTINCT FROM v_manual_scope_count THEN
      RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_CHANGED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_PAYMENT_STATUS_TRANSFER_SCOPE_CHANGED'
        )::text;
    END IF;

    v_manual_scope_member_index := 0;
    FOREACH v_pay_bank_transfer_id IN ARRAY v_manual_scope_transfer_ids
    LOOP
      v_manual_scope_member_index := v_manual_scope_member_index + 1;
      v_manual_scope_result := public.pay_bank_event_ingest(
        p_event_json => (
          ((v_event_json - 'pay_bank_transfer_ids') - 'pay_batch_candidate_id') - 'pay_bank_transfer_id'
        ) || pg_catalog.jsonb_build_object(
          'pay_bank_transfer_id', v_pay_bank_transfer_id,
          'candidate_id', v_candidate_id,
          'idempotency_key', v_manual_scope_idempotency_base || ':' || v_pay_bank_transfer_id::text,
          'mapping_hints_json', v_mapping_hints_json || pg_catalog.jsonb_build_object(
            'instruction_scope_hash', v_manual_scope_hash,
            'instruction_scope_index', v_manual_scope_member_index,
            'instruction_scope_count', v_manual_scope_count,
            'scope_idempotency_key', v_manual_scope_idempotency_base
          )
        ),
        p_actor_user_id => p_actor_user_id,
        p_ingest_options_json => (v_ingest_options_json - 'manual_ambiguity_resolution')
          || pg_catalog.jsonb_build_object(
            'manual_ambiguity_resolution', false,
            'touch_signal', false,
            'signal_mode', 'DEFERRED'
          )
      );

      IF COALESCE((v_manual_scope_result->>'ok')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'MANUAL_PAYMENT_STATUS_SCOPE_MEMBER_FAILED'
          USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
            'code', 'MANUAL_PAYMENT_STATUS_SCOPE_MEMBER_FAILED',
            'scope_index', v_manual_scope_member_index
          )::text;
      END IF;

      IF v_manual_scope_first_result IS NULL THEN
        v_manual_scope_first_result := v_manual_scope_result;
      END IF;
      IF COALESCE(v_manual_scope_result->>'event_id', '') ~ v_uuid_regex THEN
        v_manual_scope_event_ids := v_manual_scope_event_ids
          || pg_catalog.jsonb_build_array(v_manual_scope_result->>'event_id');
      END IF;
      v_manual_scope_raw_continuations := v_manual_scope_raw_continuations
        || CASE
             WHEN pg_catalog.jsonb_typeof(v_manual_scope_result->'continuations') = 'array'
               THEN v_manual_scope_result->'continuations'
             ELSE '[]'::jsonb
           END
        || CASE
             WHEN pg_catalog.jsonb_typeof(v_manual_scope_result->'continuation') = 'object'
               THEN pg_catalog.jsonb_build_array(v_manual_scope_result->'continuation')
             ELSE '[]'::jsonb
           END;
      v_manual_scope_all_idempotent := v_manual_scope_all_idempotent
        AND COALESCE((v_manual_scope_result->>'idempotent')::boolean, false);
      v_manual_scope_any_inserted := v_manual_scope_any_inserted
        OR COALESCE((v_manual_scope_result->>'inserted')::boolean, false);
      v_manual_scope_all_mapped := v_manual_scope_all_mapped
        AND COALESCE((v_manual_scope_result->>'mapped')::boolean, false);
      v_manual_scope_requires_user_action := v_manual_scope_requires_user_action
        OR COALESCE((v_manual_scope_result->>'requires_user_action')::boolean, false);
      v_manual_scope_paid_after_release := v_manual_scope_paid_after_release
        OR COALESCE((v_manual_scope_result->>'paid_after_release')::boolean, false);
      v_manual_scope_release_eligible := v_manual_scope_release_eligible
        OR COALESCE((v_manual_scope_result->>'release_eligible')::boolean, false);
      v_manual_scope_auto_release_started := v_manual_scope_auto_release_started
        OR COALESCE((v_manual_scope_result->>'auto_release_request_prepared')::boolean, false)
        OR COALESCE((v_manual_scope_result->>'release_request_started')::boolean, false);
    END LOOP;

    IF pg_catalog.upper(COALESCE(v_event_json->>'resolution', '')) = 'CONFIRMED_NOT_PAID'
       AND v_manual_scope_auto_release_started THEN
      RAISE EXCEPTION 'MANUAL_RESOLUTION_AUTO_RELEASE_PROHIBITED'
        USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
          'code', 'MANUAL_RESOLUTION_AUTO_RELEASE_PROHIBITED'
        )::text;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(deduped.continuation ORDER BY deduped.operation_id), '[]'::jsonb)
    INTO v_manual_scope_continuations
    FROM (
      SELECT grouped.operation_id, grouped.continuation
      FROM (
        SELECT raw_continuation.value->>'operation_id' AS operation_id,
               pg_catalog.min(raw_continuation.value::text)::jsonb AS continuation
        FROM pg_catalog.jsonb_array_elements(v_manual_scope_raw_continuations) AS raw_continuation(value)
        WHERE pg_catalog.jsonb_typeof(raw_continuation.value) = 'object'
          AND COALESCE((raw_continuation.value->>'required')::boolean, false)
          AND COALESCE((raw_continuation.value->>'terminal')::boolean, false) IS NOT TRUE
          AND COALESCE((raw_continuation.value->>'requires_user_action')::boolean, false) IS NOT TRUE
          AND COALESCE(raw_continuation.value->>'operation_id', '') ~ v_uuid_regex
        GROUP BY raw_continuation.value->>'operation_id'
      ) AS grouped
      ORDER BY grouped.operation_id
      LIMIT 4
    ) AS deduped;

    v_signal_recommendation_json := pg_catalog.jsonb_build_object(
      'pay_batch_id', v_pay_batch_id::text,
      'changed_pay_batch_candidate_ids', pg_catalog.jsonb_build_array(v_manual_scope_pay_batch_candidate_id::text),
      'changed_pay_bank_transfer_ids', pg_catalog.to_jsonb(v_manual_scope_transfer_ids),
      'change_scope_json', pg_catalog.jsonb_build_object(
        'bank_event_ids', v_manual_scope_event_ids,
        'pay_bank_transfer_ids', pg_catalog.to_jsonb(v_manual_scope_transfer_ids),
        'candidate_id', v_candidate_id::text,
        'pay_batch_candidate_id', v_manual_scope_pay_batch_candidate_id::text,
        'instruction_scope_hash', v_manual_scope_hash,
        'resolution', pg_catalog.upper(v_event_json->>'resolution')
      )
    );
    IF v_manual_scope_all_idempotent THEN
      v_live_signal_result := pg_catalog.jsonb_build_object(
        'ok', true,
        'changed', false,
        'duplicate_scope', true,
        'reason', 'The complete manual payment-status scope was already recorded.',
        'signal_recommendation_json', v_signal_recommendation_json
      );
    ELSIF v_should_touch_signal THEN
      v_live_signal_result := public.banking_pay_batch_signal_touch(
        v_pay_batch_id,
        'MANUAL_PAYMENT_STATUS_SCOPE_RECORDED',
        'pay_bank_event_ingest',
        v_signal_recommendation_json->'change_scope_json',
        true,
        false,
        pg_catalog.upper(COALESCE(v_event_json->>'resolution', '')) = 'CONFIRMED_NOT_PAID',
        true
      );
    ELSE
      v_live_signal_result := pg_catalog.jsonb_build_object(
        'ok', true,
        'changed', false,
        'deferred', true,
        'signal_recommendation_json', v_signal_recommendation_json
      );
    END IF;

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_BANK_EVENT_INGEST_MANUAL_SCOPE_RESULT',
      pg_catalog.jsonb_build_object(
        'pay_batch_id', v_pay_batch_id,
        'pay_batch_candidate_id', v_manual_scope_pay_batch_candidate_id,
        'candidate_id', v_candidate_id,
        'instruction_scope_hash', v_manual_scope_hash,
        'scope_count', v_manual_scope_count,
        'event_count', pg_catalog.jsonb_array_length(v_manual_scope_event_ids),
        'all_idempotent', v_manual_scope_all_idempotent
      ),
      'pay_payment_correction',
      v_manual_scope_pay_batch_candidate_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN COALESCE(v_manual_scope_first_result, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'ok', true,
        'event_id', NULLIF(v_manual_scope_event_ids->>0, '')::uuid,
        'event_ids', v_manual_scope_event_ids,
        'event_count', pg_catalog.jsonb_array_length(v_manual_scope_event_ids),
        'pay_batch_id', v_pay_batch_id,
        'pay_batch_candidate_id', v_manual_scope_pay_batch_candidate_id,
        'candidate_id', v_candidate_id,
        'pay_bank_transfer_ids', pg_catalog.to_jsonb(v_manual_scope_transfer_ids),
        'instruction_scope_hash', v_manual_scope_hash,
        'scope_atomic', true,
        'idempotent', v_manual_scope_all_idempotent,
        'inserted', v_manual_scope_any_inserted,
        'mapped', v_manual_scope_all_mapped,
        'mapping_status', CASE WHEN v_manual_scope_all_mapped THEN 'MATCHED' ELSE 'UNMATCHED' END,
        'mapping_method', 'MANUAL_TRANSFER_SELECTION',
        'manual_resolution_recorded', true,
        'release_eligible', pg_catalog.upper(COALESCE(v_event_json->>'resolution', '')) = 'CONFIRMED_NOT_PAID'
          AND v_manual_scope_release_eligible,
        'auto_release_request_prepared', v_manual_scope_auto_release_started,
        'paid_after_release', v_manual_scope_paid_after_release,
        'requires_user_action', v_manual_scope_requires_user_action,
        'display_status', CASE
          WHEN v_manual_scope_paid_after_release THEN 'Paid — evidence received after release'
          WHEN pg_catalog.upper(COALESCE(v_event_json->>'resolution', '')) = 'CONFIRMED_NOT_PAID'
            THEN 'Not paid — ready to release'
          ELSE 'Payment confirmed paid'
        END,
        'display_message', CASE
          WHEN v_manual_scope_paid_after_release THEN 'The bank confirmed this payment after CloudTMS released its payment reservation. CloudTMS retained both histories for Finance review.'
          WHEN pg_catalog.upper(COALESCE(v_event_json->>'resolution', '')) = 'CONFIRMED_NOT_PAID'
            THEN 'The complete payment scope is confirmed not paid and can now be released as a separate authorised action.'
          ELSE 'The complete payment scope was recorded as paid.'
        END,
        'live_signal', v_live_signal_result,
        'signal_recommendation_json', v_signal_recommendation_json,
        'continuations', v_manual_scope_continuations,
        'policy_x_checked', true
      );
  END IF;

  IF v_provider_webhook_receipt_id IS NOT NULL THEN
    SELECT receipt_row.status,
           receipt_row.provider_key,
           receipt_row.rail_env,
           receipt_row.provider_event_key,
           receipt_row.signature_valid,
           COALESCE(receipt_row.normalised_events_json, '[]'::jsonb),
           COALESCE(receipt_row.ingest_results_json, '[]'::jsonb)
    INTO v_receipt_status,
         v_receipt_provider_key,
         v_receipt_rail_env,
         v_receipt_provider_event_key,
         v_receipt_signature_valid,
         v_receipt_normalised_events_json,
         v_receipt_ingest_results_json
    FROM public.bank_provider_webhook_receipts AS receipt_row
    WHERE receipt_row.id = v_provider_webhook_receipt_id;
  END IF;

  IF v_provider_event_transport IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
     AND v_provider_signature_valid IS NULL
     AND v_receipt_signature_valid IS TRUE THEN
    v_provider_signature_valid := true;
  END IF;

  IF NULLIF(btrim(COALESCE(v_provider_event_key, '')), '') IS NOT NULL THEN
    SELECT EXISTS (
      WITH RECURSIVE receipt_json_walk(json_value) AS (
        SELECT jsonb_build_array(
          to_jsonb(v_receipt_provider_event_key),
          COALESCE(v_receipt_normalised_events_json, '[]'::jsonb),
          COALESCE(v_receipt_ingest_results_json, '[]'::jsonb)
        )
        UNION ALL
        SELECT receipt_json_child.child_value
        FROM receipt_json_walk AS receipt_json_parent
        CROSS JOIN LATERAL (
          SELECT array_child.value AS child_value
          FROM jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(receipt_json_parent.json_value) = 'array' THEN receipt_json_parent.json_value
              ELSE '[]'::jsonb
            END
          ) AS array_child(value)
          UNION ALL
          SELECT object_child.value AS child_value
          FROM jsonb_each(
            CASE
              WHEN jsonb_typeof(receipt_json_parent.json_value) = 'object' THEN receipt_json_parent.json_value
              ELSE '{}'::jsonb
            END
          ) AS object_child(key_name, value)
          UNION ALL
          SELECT to_jsonb(object_child_key.key_name) AS child_value
          FROM jsonb_each(
            CASE
              WHEN jsonb_typeof(receipt_json_parent.json_value) = 'object' THEN receipt_json_parent.json_value
              ELSE '{}'::jsonb
            END
          ) AS object_child_key(key_name, value)
        ) AS receipt_json_child
      )
      SELECT 1
      FROM receipt_json_walk AS receipt_json_match
      WHERE (
        jsonb_typeof(receipt_json_match.json_value) = 'string'
        AND trim(both '"' from receipt_json_match.json_value::text) = v_provider_event_key
      )
    )
    INTO v_provider_event_key_in_receipt;
  ELSE
    v_provider_event_key_in_receipt := false;
  END IF;

  v_webhook_gate_ok := (
    v_provider_event_transport = 'PROVIDER_WEBHOOK'
    AND v_provider_signature_valid IS DISTINCT FROM false
    AND v_provider_webhook_receipt_id IS NOT NULL
    AND v_receipt_status IS NOT NULL
    AND upper(COALESCE(v_receipt_status, '')) IN ('VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED')
    AND v_receipt_signature_valid IS TRUE
    AND v_receipt_provider_key IS NOT DISTINCT FROM v_provider_key
    AND v_receipt_rail_env IS NOT DISTINCT FROM v_rail_env
    AND NULLIF(btrim(COALESCE(v_provider_event_key, '')), '') IS NOT NULL
    AND COALESCE(v_provider_event_key_in_receipt, false) IS TRUE
  );

  IF v_provider_event_transport = 'PROVIDER_WEBHOOK' AND COALESCE(v_webhook_gate_ok, false) IS NOT TRUE THEN
    IF v_provider_webhook_receipt_id IS NOT NULL
       AND (v_provider_signature_valid IS FALSE OR COALESCE(v_receipt_signature_valid, false) IS NOT TRUE) THEN
      UPDATE public.bank_provider_webhook_receipts AS receipt_to_update
      SET status = CASE WHEN upper(COALESCE(receipt_to_update.status, '')) = 'SIGNATURE_INVALID' THEN receipt_to_update.status ELSE 'SIGNATURE_INVALID' END,
          error_code = COALESCE(receipt_to_update.error_code, 'WEBHOOK_SIGNATURE_OR_RECEIPT_INVALID'),
          error_message = COALESCE(receipt_to_update.error_message, 'Webhook event was rejected because the webhook signature or receipt signature was invalid.'),
          updated_at_utc = v_now
      WHERE receipt_to_update.id = v_provider_webhook_receipt_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', false,
      'event_id', NULL::uuid,
      'idempotent', false,
      'mapped', false,
      'normalised_state', v_normalised_state,
      'manual_resolution_recorded', false,
      'release_eligible', false,
      'auto_release_request_prepared', false,
      'existing_release_request_id', NULL::uuid,
      'existing_release_operation_woken', false,
      'paid_after_release', false,
      'requires_user_action', true,
      'continuations', '[]'::jsonb,
      'display_status', 'Provider evidence rejected',
      'display_message', CASE
        WHEN v_provider_signature_valid IS FALSE OR COALESCE(v_receipt_signature_valid, false) IS NOT TRUE THEN 'Webhook event was not ingested because its signature or receipt could not be validated.'
        ELSE 'Webhook event was not ingested because it was not present in the signed receipt.'
      END,
      'ignored', true,
      'code', CASE
        WHEN v_provider_signature_valid IS FALSE OR COALESCE(v_receipt_signature_valid, false) IS NOT TRUE THEN 'WEBHOOK_SIGNATURE_OR_RECEIPT_INVALID'
        ELSE 'WEBHOOK_RECEIPT_EVENT_MEMBERSHIP_INVALID'
      END,
      'provider_event_transport', v_provider_event_transport,
      'provider_webhook_receipt_id', CASE WHEN v_provider_webhook_receipt_id IS NULL THEN NULL ELSE v_provider_webhook_receipt_id::text END,
      'provider_event_key', v_provider_event_key,
      'provider_signature_valid', COALESCE(v_provider_signature_valid, v_receipt_signature_valid, false),
      'receipt_status', v_receipt_status,
      'receipt_signature_valid', COALESCE(v_receipt_signature_valid, false),
      'message', CASE
        WHEN v_provider_signature_valid IS FALSE OR COALESCE(v_receipt_signature_valid, false) IS NOT TRUE THEN 'Webhook event was not ingested as provider evidence because signature/receipt validation failed.'
        ELSE 'Webhook event was not ingested as provider evidence because the event key was not present in the signed webhook receipt.'
      END
    );
  END IF;

  v_replay_gate_ok := (
    v_provider_event_transport = 'FAILED_WEBHOOK_REPLAY'
    AND v_provider_webhook_receipt_id IS NOT NULL
    AND v_receipt_status IS NOT NULL
    AND upper(COALESCE(v_receipt_status, '')) IN ('VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED')
    AND v_receipt_signature_valid IS TRUE
    AND v_receipt_provider_key IS NOT DISTINCT FROM v_provider_key
    AND v_receipt_rail_env IS NOT DISTINCT FROM v_rail_env
    AND NULLIF(btrim(COALESCE(v_provider_event_key, '')), '') IS NOT NULL
    AND COALESCE(v_provider_event_key_in_receipt, false) IS TRUE
  );

  IF v_provider_event_transport = 'FAILED_WEBHOOK_REPLAY' AND COALESCE(v_replay_gate_ok, false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'event_id', NULL::uuid,
      'idempotent', false,
      'mapped', false,
      'normalised_state', v_normalised_state,
      'manual_resolution_recorded', false,
      'release_eligible', false,
      'auto_release_request_prepared', false,
      'existing_release_request_id', NULL::uuid,
      'existing_release_operation_woken', false,
      'paid_after_release', false,
      'requires_user_action', true,
      'continuations', '[]'::jsonb,
      'display_status', 'Provider evidence rejected',
      'display_message', 'Failed-webhook replay evidence was not ingested because its signed receipt provenance was invalid.',
      'ignored', true,
      'code', 'FAILED_WEBHOOK_REPLAY_RECEIPT_INVALID',
      'provider_event_transport', v_provider_event_transport,
      'provider_webhook_receipt_id', CASE WHEN v_provider_webhook_receipt_id IS NULL THEN NULL ELSE v_provider_webhook_receipt_id::text END,
      'receipt_status', v_receipt_status,
      'message', 'Failed-webhook replay event was not ingested as provider evidence because replay provenance was not valid.'
    );
  END IF;

  IF v_pay_bank_transfer_id IS NOT NULL THEN
    SELECT public.pay_bank_transfers.*
    INTO v_transfer
    FROM public.pay_bank_transfers

    WHERE public.pay_bank_transfers.id = v_pay_bank_transfer_id;

    IF v_transfer.id IS NULL THEN
      RAISE EXCEPTION 'BANK_TRANSFER_NOT_FOUND_FOR_EVENT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANK_TRANSFER_NOT_FOUND_FOR_EVENT', 'pay_bank_transfer_id', v_pay_bank_transfer_id)::text;
    END IF;

    IF v_supplied_pay_batch_id IS NOT NULL AND v_supplied_pay_batch_id <> v_transfer.pay_batch_id THEN
      RAISE EXCEPTION 'BANK_EVENT_TRANSFER_BATCH_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'BANK_EVENT_TRANSFER_BATCH_MISMATCH',
                'supplied_pay_batch_id', v_supplied_pay_batch_id,
                'transfer_pay_batch_id', v_transfer.pay_batch_id,
                'pay_bank_transfer_id', v_transfer.id
              )::text;
    END IF;

    v_pay_batch_id := v_transfer.pay_batch_id;
    v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
    v_umbrella_id := COALESCE(
      v_umbrella_id,
      v_transfer.umbrella_id,
      CASE
        WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id
        ELSE NULL::uuid
      END
    );
    v_mapping_method := CASE
      WHEN v_event_source = 'MANUAL_EVIDENCE' THEN 'MANUAL_TRANSFER_SELECTION'
      ELSE 'TRANSFER_ID'
    END;
  END IF;

  IF v_pay_bank_transfer_id IS NULL AND v_provider_transaction_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_mapping_candidate_count
    FROM public.pay_bank_transfers AS transfer_match
    WHERE (
      transfer_match.rail_tx_id = v_provider_transaction_id
      OR transfer_match.rail_meta_json #>> '{provider_transaction_id}' = v_provider_transaction_id
      OR transfer_match.rail_meta_json #>> '{transaction_id}' = v_provider_transaction_id
      OR transfer_match.rail_meta_json #>> '{provider_payment_id}' = v_provider_transaction_id
      OR transfer_match.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}' = v_provider_transaction_id
      OR transfer_match.rail_meta_json #>> '{id}' = v_provider_transaction_id
    )
      AND (v_pay_batch_id IS NULL OR transfer_match.pay_batch_id = v_pay_batch_id);

    IF v_mapping_candidate_count = 1 THEN
      SELECT transfer_match.*
      INTO v_transfer
      FROM public.pay_bank_transfers AS transfer_match
      WHERE (
        transfer_match.rail_tx_id = v_provider_transaction_id
        OR transfer_match.rail_meta_json #>> '{provider_transaction_id}' = v_provider_transaction_id
        OR transfer_match.rail_meta_json #>> '{transaction_id}' = v_provider_transaction_id
        OR transfer_match.rail_meta_json #>> '{provider_payment_id}' = v_provider_transaction_id
        OR transfer_match.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}' = v_provider_transaction_id
        OR transfer_match.rail_meta_json #>> '{id}' = v_provider_transaction_id
      )
        AND (v_pay_batch_id IS NULL OR transfer_match.pay_batch_id = v_pay_batch_id)
      ORDER BY transfer_match.created_at_utc DESC, transfer_match.id DESC
      LIMIT 1;

      v_pay_bank_transfer_id := v_transfer.id;
      v_pay_batch_id := COALESCE(v_pay_batch_id, v_transfer.pay_batch_id);
      v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
      v_umbrella_id := COALESCE(v_umbrella_id, v_transfer.umbrella_id, CASE WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id ELSE NULL::uuid END);
      v_mapping_method := 'PROVIDER_TRANSACTION_ID';
    ELSIF v_mapping_candidate_count > 1 THEN
      v_mapping_method := 'AMBIGUOUS';
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NULL AND v_provider_request_id IS NOT NULL AND v_provider_event_transport IN ('PROVIDER_RESPONSE','PROVIDER_POLL','PROVIDER_WEBHOOK','FAILED_WEBHOOK_REPLAY') THEN
    SELECT count(*)::integer
    INTO v_mapping_candidate_count
    FROM public.pay_bank_transfers AS transfer_match
    WHERE (
        transfer_match.request_id = v_provider_request_id
        OR transfer_match.rail_meta_json #>> '{provider_submit_diagnostic,request_id}' = v_provider_request_id
        OR transfer_match.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}' = v_provider_request_id
      )
      AND (v_pay_batch_id IS NULL OR transfer_match.pay_batch_id = v_pay_batch_id);

    IF v_mapping_candidate_count = 1 THEN
      SELECT transfer_match.*
      INTO v_transfer
      FROM public.pay_bank_transfers AS transfer_match
      WHERE (
          transfer_match.request_id = v_provider_request_id
          OR transfer_match.rail_meta_json #>> '{provider_submit_diagnostic,request_id}' = v_provider_request_id
          OR transfer_match.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}' = v_provider_request_id
        )
        AND (v_pay_batch_id IS NULL OR transfer_match.pay_batch_id = v_pay_batch_id)
      ORDER BY transfer_match.created_at_utc DESC, transfer_match.id DESC
      LIMIT 1;

      v_pay_bank_transfer_id := v_transfer.id;
      v_pay_batch_id := COALESCE(v_pay_batch_id, v_transfer.pay_batch_id);
      v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
      v_umbrella_id := COALESCE(v_umbrella_id, v_transfer.umbrella_id, CASE WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id ELSE NULL::uuid END);
      v_mapping_method := 'REQUEST_ID';
    ELSIF v_mapping_candidate_count > 1 THEN
      v_mapping_method := 'AMBIGUOUS';
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NULL AND v_provider_reference IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_mapping_candidate_count
    FROM public.pay_bank_transfers
    WHERE (
      public.pay_bank_transfers.request_id = v_provider_reference
      OR public.pay_bank_transfers.rail_tx_id = v_provider_reference
      OR public.pay_bank_transfers.payment_reference = v_provider_reference
    )
      AND (v_pay_batch_id IS NULL OR public.pay_bank_transfers.pay_batch_id = v_pay_batch_id);

    IF v_mapping_candidate_count = 1 THEN
      SELECT public.pay_bank_transfers.*
      INTO v_transfer
      FROM public.pay_bank_transfers
      WHERE (
        public.pay_bank_transfers.request_id = v_provider_reference
        OR public.pay_bank_transfers.rail_tx_id = v_provider_reference
        OR public.pay_bank_transfers.payment_reference = v_provider_reference
      )
        AND (v_pay_batch_id IS NULL OR public.pay_bank_transfers.pay_batch_id = v_pay_batch_id)
      ORDER BY public.pay_bank_transfers.created_at_utc DESC, public.pay_bank_transfers.id DESC
      LIMIT 1;

      v_pay_bank_transfer_id := v_transfer.id;
      v_pay_batch_id := COALESCE(v_pay_batch_id, v_transfer.pay_batch_id);
      v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
      v_umbrella_id := COALESCE(
        v_umbrella_id,
        v_transfer.umbrella_id,
        CASE
          WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id
          ELSE NULL::uuid
        END
      );
      v_mapping_method := CASE
        WHEN v_transfer.request_id = v_provider_reference THEN 'REQUEST_ID'
        WHEN v_transfer.rail_tx_id = v_provider_reference THEN 'RAIL_TX_ID'
        WHEN v_transfer.payment_reference = v_provider_reference THEN 'PAYMENT_REFERENCE'
        ELSE 'PROVIDER_REFERENCE'
      END;
    ELSIF v_mapping_candidate_count > 1 THEN
      v_mapping_method := 'AMBIGUOUS';
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NULL AND v_provider_event_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_mapping_candidate_count
    FROM public.pay_bank_transfers
    WHERE (
      public.pay_bank_transfers.request_id = v_provider_event_id
      OR public.pay_bank_transfers.rail_tx_id = v_provider_event_id
      OR public.pay_bank_transfers.payment_reference = v_provider_event_id
    )
      AND (v_pay_batch_id IS NULL OR public.pay_bank_transfers.pay_batch_id = v_pay_batch_id);

    IF v_mapping_candidate_count = 1 THEN
      SELECT public.pay_bank_transfers.*
      INTO v_transfer
      FROM public.pay_bank_transfers
      WHERE (
        public.pay_bank_transfers.request_id = v_provider_event_id
        OR public.pay_bank_transfers.rail_tx_id = v_provider_event_id
        OR public.pay_bank_transfers.payment_reference = v_provider_event_id
      )
        AND (v_pay_batch_id IS NULL OR public.pay_bank_transfers.pay_batch_id = v_pay_batch_id)
      ORDER BY public.pay_bank_transfers.created_at_utc DESC, public.pay_bank_transfers.id DESC
      LIMIT 1;

      v_pay_bank_transfer_id := v_transfer.id;

      v_pay_batch_id := COALESCE(v_pay_batch_id, v_transfer.pay_batch_id);
      v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
      v_umbrella_id := COALESCE(
        v_umbrella_id,
        v_transfer.umbrella_id,
        CASE
          WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id
          ELSE NULL::uuid
        END
      );
      v_mapping_method := 'PROVIDER_EVENT_ID';
    ELSIF v_mapping_candidate_count > 1 THEN
      v_mapping_method := 'AMBIGUOUS';
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NULL
     AND (
       v_provider_transaction_id IS NOT NULL
       OR v_provider_request_id IS NOT NULL
       OR v_provider_reference IS NOT NULL
     ) THEN
    SELECT count(DISTINCT event_match.pay_bank_transfer_id)::integer
    INTO v_mapping_candidate_count
    FROM public.pay_bank_transfer_events AS event_match
    JOIN public.pay_bank_transfers AS transfer_match
      ON transfer_match.id = event_match.pay_bank_transfer_id
    WHERE event_match.pay_bank_transfer_id IS NOT NULL
      AND upper(COALESCE(event_match.mapping_status, '')) = 'MATCHED'
      AND upper(COALESCE(event_match.mapping_method, '')) IN (
        'TRANSFER_ID',
        'PROVIDER_EVENT_ID',
        'PROVIDER_TRANSACTION_ID',
        'REQUEST_ID',
        'PROVIDER_REFERENCE',
        'RAIL_TX_ID',
        'MATCHED_PROVIDER_EVENT',
        'MANUAL_TRANSFER_SELECTION'
      )
      AND (
        event_match.provider_transaction_id = v_provider_transaction_id
        OR event_match.provider_request_id = v_provider_request_id
        OR event_match.provider_reference = v_provider_transaction_id
        OR event_match.provider_reference = v_provider_request_id
        OR event_match.provider_transaction_id = v_provider_reference
        OR event_match.provider_request_id = v_provider_reference
      )
      AND (
        v_pay_batch_id IS NULL
        OR event_match.pay_batch_id = v_pay_batch_id
        OR transfer_match.pay_batch_id = v_pay_batch_id
      );

    IF v_mapping_candidate_count = 1 THEN
      SELECT transfer_match.*
      INTO v_transfer
      FROM public.pay_bank_transfer_events AS event_match
      JOIN public.pay_bank_transfers AS transfer_match
        ON transfer_match.id = event_match.pay_bank_transfer_id
      WHERE event_match.pay_bank_transfer_id IS NOT NULL
        AND upper(COALESCE(event_match.mapping_status, '')) = 'MATCHED'
        AND upper(COALESCE(event_match.mapping_method, '')) IN (
          'TRANSFER_ID',
          'PROVIDER_EVENT_ID',
          'PROVIDER_TRANSACTION_ID',
          'REQUEST_ID',
          'PROVIDER_REFERENCE',
          'RAIL_TX_ID',
          'MATCHED_PROVIDER_EVENT',
          'MANUAL_TRANSFER_SELECTION'
        )
        AND (
          event_match.provider_transaction_id = v_provider_transaction_id
          OR event_match.provider_request_id = v_provider_request_id
          OR event_match.provider_reference = v_provider_transaction_id
          OR event_match.provider_reference = v_provider_request_id
          OR event_match.provider_transaction_id = v_provider_reference
          OR event_match.provider_request_id = v_provider_reference
        )
        AND (
          v_pay_batch_id IS NULL
          OR event_match.pay_batch_id = v_pay_batch_id
          OR transfer_match.pay_batch_id = v_pay_batch_id
        )
      ORDER BY event_match.received_at_utc DESC NULLS LAST,
               event_match.event_time_utc DESC NULLS LAST,
               event_match.created_at_utc DESC NULLS LAST,
               event_match.id DESC
      LIMIT 1;

      IF v_transfer.id IS NOT NULL THEN
        v_pay_bank_transfer_id := v_transfer.id;
        v_pay_batch_id := COALESCE(v_pay_batch_id, v_transfer.pay_batch_id);
        v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
        v_umbrella_id := COALESCE(
          v_umbrella_id,
          v_transfer.umbrella_id,
          CASE
            WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id
            ELSE NULL::uuid
          END
        );
        v_mapping_method := 'MATCHED_PROVIDER_EVENT';
      ELSE
        v_mapping_candidate_count := 0;
        v_mapping_method := 'UNMATCHED';
      END IF;
    ELSIF v_mapping_candidate_count > 1 THEN
      v_mapping_method := 'AMBIGUOUS';
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NULL AND v_pay_batch_id IS NOT NULL AND v_amount IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_mapping_candidate_count
    FROM public.pay_bank_transfers
    WHERE public.pay_bank_transfers.pay_batch_id = v_pay_batch_id
      AND abs(COALESCE(public.pay_bank_transfers.amount, 0) - COALESCE(v_amount, 0)) <= 0.01;

    IF v_mapping_candidate_count = 1 THEN
      SELECT public.pay_bank_transfers.*
      INTO v_transfer
      FROM public.pay_bank_transfers
      WHERE public.pay_bank_transfers.pay_batch_id = v_pay_batch_id
        AND abs(COALESCE(public.pay_bank_transfers.amount, 0) - COALESCE(v_amount, 0)) <= 0.01
      ORDER BY public.pay_bank_transfers.created_at_utc DESC, public.pay_bank_transfers.id DESC
      LIMIT 1;

      v_pay_bank_transfer_id := v_transfer.id;
      v_candidate_id := COALESCE(v_candidate_id, v_transfer.candidate_id);
      v_umbrella_id := COALESCE(
        v_umbrella_id,
        v_transfer.umbrella_id,
        CASE
          WHEN upper(COALESCE(v_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN v_transfer.payee_entity_id
          ELSE NULL::uuid
        END
      );
      v_mapping_method := 'AMOUNT_ONLY_UNIQUE';
    ELSIF v_mapping_candidate_count > 1 THEN
      v_mapping_method := 'AMBIGUOUS';
    END IF;
  END IF;

  IF v_pay_batch_id IS NULL
     AND v_provider_event_transport IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
     AND v_provider_webhook_receipt_id IS NOT NULL THEN
    UPDATE public.bank_provider_webhook_receipts AS receipt_to_update
    SET
      status = 'UNMATCHED_REVIEW_REQUIRED',
      error_code = COALESCE(receipt_to_update.error_code, 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'),
      error_message = COALESCE(receipt_to_update.error_message, 'Provider webhook/replay could not be matched to a CloudTMS pay batch or transfer; retained for manual review.'),
      updated_at_utc = v_now
    WHERE receipt_to_update.id = v_provider_webhook_receipt_id;

    RETURN jsonb_build_object(
      'ok', true,
      'event_id', NULL::uuid,
      'idempotent', false,
      'mapped', false,
      'normalised_state', v_normalised_state,
      'manual_resolution_recorded', v_manual_confirmed_not_paid,
      'release_eligible', false,
      'auto_release_request_prepared', false,
      'existing_release_request_id', NULL::uuid,
      'existing_release_operation_woken', false,
      'paid_after_release', false,
      'requires_user_action', true,
      'continuations', '[]'::jsonb,
      'display_status', 'Provider evidence needs review',
      'display_message', 'The provider evidence was retained but could not be matched to a payment.',
      'ignored', true,
      'mapping_status', 'UNMATCHED',
      'mapping_method', 'UNMATCHED',
      'correction_disposition', 'UNMATCHED_REVIEW_REQUIRED',
      'code', 'BANK_EVENT_PAY_BATCH_ID_COULD_NOT_BE_RESOLVED_RETAINED_FOR_REVIEW',
      'provider_event_transport', v_provider_event_transport,
      'provider_webhook_receipt_id', v_provider_webhook_receipt_id::text,
      'provider_event_key', v_provider_event_key,
      'provider_transaction_id', v_provider_transaction_id,
      'provider_request_id', v_provider_request_id,
      'message', 'Provider webhook/replay was retained for review because no CloudTMS pay batch or transfer could be resolved.'
    );
  END IF;

  IF v_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'BANK_EVENT_PAY_BATCH_ID_COULD_NOT_BE_RESOLVED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANK_EVENT_PAY_BATCH_ID_COULD_NOT_BE_RESOLVED',
              'pay_bank_transfer_id', v_pay_bank_transfer_id,
              'provider_reference', v_provider_reference
            )::text;
  END IF;


  SELECT public.pay_batches.*
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = v_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANK_EVENT_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANK_EVENT_PAY_BATCH_NOT_FOUND', 'pay_batch_id', v_pay_batch_id)::text;
  END IF;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    v_pay_batch_id,
    NULL::uuid,
    'AUTHORITATIVE_EVENT'
  );

  IF COALESCE((v_mutation_guard->>'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_mutation_guard->>'code', 'PAYMENT_MUTATION_LOCK_TIMEOUT')
      USING ERRCODE = 'P0001', DETAIL = v_mutation_guard::text;
  END IF;

  IF v_pay_bank_transfer_id IS NOT NULL THEN
    v_mapping_status := 'MATCHED';
    IF v_mapping_method IS NULL OR v_mapping_method = 'UNMATCHED' THEN
      v_mapping_method := 'TRANSFER_ID';
    END IF;
  ELSIF v_mapping_candidate_count > 1 THEN
    v_mapping_status := 'AMBIGUOUS';
    v_mapping_method := 'AMBIGUOUS';
  ELSE
    v_mapping_status := 'UNMATCHED';
    v_mapping_method := 'UNMATCHED';
  END IF;

  IF v_mapping_status = 'UNMATCHED'
     AND (
       COALESCE(v_event_json->>'legacy_no_artifact', 'false') IN ('true', 't', 'yes', 'y', '1')
       OR NOT EXISTS (
         SELECT 1
         FROM public.pay_bank_transfers AS legacy_artifact_check
         WHERE legacy_artifact_check.pay_batch_id = v_pay_batch_id
       )
     ) THEN
    v_mapping_status := 'LEGACY_NO_ARTIFACT';
    v_mapping_method := 'LEGACY_NO_ARTIFACT';
  END IF;

  IF v_provider_event_transport IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
     AND v_provider_webhook_receipt_id IS NOT NULL
     AND v_mapping_status IN ('UNMATCHED', 'AMBIGUOUS', 'LEGACY_NO_ARTIFACT') THEN
    UPDATE public.bank_provider_webhook_receipts AS receipt_to_update
    SET
      status = 'UNMATCHED_REVIEW_REQUIRED',
      error_code = COALESCE(receipt_to_update.error_code, 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'),
      error_message = COALESCE(receipt_to_update.error_message, 'Provider webhook/replay was verified but could not be strongly matched to a CloudTMS transfer; manual review is required.'),
      updated_at_utc = v_now
    WHERE receipt_to_update.id = v_provider_webhook_receipt_id;
  END IF;

  v_has_strong_transfer_mapping := (
    v_mapping_status = 'MATCHED'
    AND v_mapping_method IN (
      'TRANSFER_ID',
      'PROVIDER_EVENT_ID',
      'PROVIDER_TRANSACTION_ID',
      'REQUEST_ID',
      'PROVIDER_REFERENCE',
      'RAIL_TX_ID',
      'MATCHED_PROVIDER_EVENT',
      'MANUAL_TRANSFER_SELECTION'
    )
  );

  v_pre_insert_pay_batch_id := v_pay_batch_id;
  v_pre_insert_pay_bank_transfer_id := v_pay_bank_transfer_id;
  v_pre_insert_candidate_id := v_candidate_id;
  v_pre_insert_umbrella_id := v_umbrella_id;
  v_pre_insert_mapping_status := v_mapping_status;
  v_pre_insert_mapping_method := v_mapping_method;

  v_idempotency_key := nullif(btrim(COALESCE(v_event_json->>'idempotency_key', v_provider_event_key, '')), '');

  IF v_idempotency_key IS NULL THEN
    v_idempotency_key := CASE
      WHEN v_provider_key IS NOT NULL AND v_provider_event_id IS NOT NULL
        THEN v_provider_key || '|' || v_provider_event_id
      WHEN v_provider_key IS NOT NULL AND v_provider_reference IS NOT NULL
        THEN v_provider_key || '|' || v_provider_reference || '|' || v_normalised_state || '|' || COALESCE(v_amount::text, '') || '|' || COALESCE(v_event_time_utc::text, '')
      WHEN v_event_source IN ('MANUAL_CONFIRM', 'MANUAL_EVIDENCE')
        THEN 'MANUAL|' || v_pay_batch_id::text || '|' || COALESCE(v_pay_bank_transfer_id::text, 'NO_TRANSFER') || '|' || v_normalised_state || '|' || COALESCE(p_actor_user_id::text, 'SYSTEM') || '|' || COALESCE(v_event_time_utc::text, v_now::text)
      ELSE 'SYSTEM|' || v_pay_batch_id::text || '|' || COALESCE(v_pay_bank_transfer_id::text, 'NO_TRANSFER') || '|' || v_normalised_state || '|' || md5(v_event_json::text)
    END;
  END IF;

  INSERT INTO public.pay_bank_transfer_events(
    pay_batch_id,
    pay_bank_transfer_id,
    candidate_id,
    umbrella_id,
    provider_key,
    provider_event_id,
    provider_reference,
    provider_state,
    normalised_state,
    event_source,
    event_time_utc,
    received_at_utc,
    amount,
    currency,
    mapping_status,
    mapping_method,
    movement_classification,
    correction_disposition,
    raw_payload,
    idempotency_key,
    provider_webhook_receipt_id,
    provider_event_type,
    provider_transaction_id,
    provider_request_id,
    provider_event_key,
    provider_signature_valid,
    provider_event_transport,
    adapter_key,
    adapter_version,
    rail_env,
    provider_failure_reason_code,
    provider_failure_reason_group,
    mapping_hints_json,
    created_at_utc
  )
  VALUES (
    v_pay_batch_id,
    v_pay_bank_transfer_id,
    v_candidate_id,
    v_umbrella_id,
    v_provider_key,
    v_provider_event_id,
    v_provider_reference,
    v_provider_state,
    v_normalised_state,
    v_event_source,
    v_event_time_utc,
    v_now,
    v_amount,
    COALESCE(v_currency, 'GBP'),
    v_mapping_status,
    v_mapping_method,
    NULL::text,
    NULL::text,
    COALESCE(v_raw_payload, '{}'::jsonb),
    v_idempotency_key,
    v_provider_webhook_receipt_id,
    v_provider_event_type,
    v_provider_transaction_id,
    v_provider_request_id,
    v_provider_event_key,
    v_provider_signature_valid,
    v_provider_event_transport,
    v_adapter_key,
    v_adapter_version,
    v_rail_env,
    v_provider_failure_reason_code,
    v_provider_failure_reason_group,
    v_mapping_hints_json,
    v_now
  )
  ON CONFLICT DO NOTHING
  RETURNING public.pay_bank_transfer_events.id
  INTO v_event_id;

  v_inserted_event := v_event_id IS NOT NULL;

  IF v_event_id IS NULL THEN
    SELECT public.pay_bank_transfer_events.id,
           public.pay_bank_transfer_events.mapping_status,
           public.pay_bank_transfer_events.mapping_method,
           public.pay_bank_transfer_events.movement_classification,
           public.pay_bank_transfer_events.correction_disposition,
           public.pay_bank_transfer_events.pay_bank_transfer_id,
           public.pay_bank_transfer_events.pay_batch_id,
           public.pay_bank_transfer_events.candidate_id,
           public.pay_bank_transfer_events.umbrella_id
    INTO v_event_id,
         v_mapping_status,
         v_mapping_method,
         v_classification,
         v_correction_disposition,
         v_pay_bank_transfer_id,
         v_pay_batch_id,

         v_candidate_id,
         v_umbrella_id
    FROM public.pay_bank_transfer_events
    WHERE public.pay_bank_transfer_events.idempotency_key = v_idempotency_key
       OR (
         v_provider_event_key IS NOT NULL
         AND public.pay_bank_transfer_events.provider_key IS NOT DISTINCT FROM v_provider_key
         AND public.pay_bank_transfer_events.rail_env IS NOT DISTINCT FROM v_rail_env
         AND public.pay_bank_transfer_events.provider_event_transport IS NOT DISTINCT FROM v_provider_event_transport
         AND public.pay_bank_transfer_events.provider_event_key = v_provider_event_key
       )
    ORDER BY CASE WHEN public.pay_bank_transfer_events.idempotency_key = v_idempotency_key THEN 0 ELSE 1 END,
             public.pay_bank_transfer_events.received_at_utc DESC NULLS LAST,
             public.pay_bank_transfer_events.id DESC
    LIMIT 1;

    v_duplicate_event_should_continue := false;

    IF v_event_id IS NOT NULL
       AND v_pre_insert_mapping_status = 'MATCHED'
       AND v_pre_insert_pay_batch_id IS NOT NULL
       AND v_pre_insert_pay_bank_transfer_id IS NOT NULL
       AND v_pre_insert_mapping_method IN (
         'TRANSFER_ID',
         'PROVIDER_EVENT_ID',
         'PROVIDER_TRANSACTION_ID',
         'REQUEST_ID',
         'PROVIDER_REFERENCE',
         'RAIL_TX_ID',
         'MATCHED_PROVIDER_EVENT',
         'MANUAL_TRANSFER_SELECTION'
       )
       AND (
         v_mapping_status IS DISTINCT FROM 'MATCHED'
         OR v_pay_bank_transfer_id IS NULL
         OR v_mapping_method NOT IN (
           'TRANSFER_ID',
           'PROVIDER_EVENT_ID',
           'PROVIDER_TRANSACTION_ID',
           'REQUEST_ID',
           'PROVIDER_REFERENCE',
           'RAIL_TX_ID',
           'MATCHED_PROVIDER_EVENT',
           'MANUAL_TRANSFER_SELECTION'
         )
       ) THEN
      UPDATE public.pay_bank_transfer_events AS existing_event_to_upgrade
      SET
        pay_batch_id = v_pre_insert_pay_batch_id,
        pay_bank_transfer_id = v_pre_insert_pay_bank_transfer_id,
        candidate_id = COALESCE(existing_event_to_upgrade.candidate_id, v_pre_insert_candidate_id),
        umbrella_id = COALESCE(existing_event_to_upgrade.umbrella_id, v_pre_insert_umbrella_id),
        mapping_status = 'MATCHED',
        mapping_method = v_pre_insert_mapping_method,
        correction_disposition = NULL::text
      WHERE existing_event_to_upgrade.id = v_event_id
      RETURNING
        existing_event_to_upgrade.mapping_status,
        existing_event_to_upgrade.mapping_method,
        existing_event_to_upgrade.movement_classification,
        existing_event_to_upgrade.correction_disposition,
        existing_event_to_upgrade.pay_bank_transfer_id,
        existing_event_to_upgrade.pay_batch_id,
        existing_event_to_upgrade.candidate_id,
        existing_event_to_upgrade.umbrella_id
      INTO
        v_mapping_status,
        v_mapping_method,
        v_classification,
        v_correction_disposition,
        v_pay_bank_transfer_id,
        v_pay_batch_id,
        v_candidate_id,
        v_umbrella_id;

      v_duplicate_event_should_continue := true;
      v_inserted_event := false;
    END IF;

    v_has_strong_transfer_mapping := (
      v_mapping_status = 'MATCHED'
      AND v_pay_bank_transfer_id IS NOT NULL
      AND v_mapping_method IN (
        'TRANSFER_ID',
        'PROVIDER_EVENT_ID',
        'PROVIDER_TRANSACTION_ID',
        'REQUEST_ID',
        'PROVIDER_REFERENCE',
        'RAIL_TX_ID',
        'MATCHED_PROVIDER_EVENT',
        'MANUAL_TRANSFER_SELECTION'
      )
    );

    SELECT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS released_item
      WHERE released_item.status = 'APPLIED'
        AND released_item.correction_item_kind IN (
          'PRE_BANK_CANCEL', 'NO_MONEY_UNWIND'
        )
        AND (
          (
            v_pay_bank_transfer_id IS NOT NULL
            AND released_item.pay_bank_transfer_id = v_pay_bank_transfer_id
          )
          OR (
            v_pay_bank_transfer_id IS NULL
            AND v_candidate_id IS NOT NULL
            AND released_item.candidate_id = v_candidate_id
          )
        )
    ) AND COALESCE(v_event_is_final_paid, false)
    INTO v_paid_after_release;

    IF COALESCE(v_duplicate_event_should_continue, false) IS NOT TRUE
       AND COALESCE(v_review_acknowledgement, false) IS NOT TRUE
       AND COALESCE(v_paid_after_release, false) IS NOT TRUE THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_BANK_EVENT_INGEST_IDEMPOTENT_EXISTING',
      jsonb_build_object(
        'event_id', v_event_id,
        'idempotency_key', v_idempotency_key,
        'mapping_status', v_mapping_status,
        'mapping_method', v_mapping_method,
        'classification', v_classification,
        'correction_disposition', v_correction_disposition
      ),
      'pay_payment_correction',
      COALESCE(v_event_id::text, v_pay_batch_id::text),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );


    v_terminal_bank_event := COALESCE(v_has_strong_transfer_mapping, false)
      AND (
        COALESCE(v_event_is_final_paid, false)
        OR COALESCE(v_event_is_terminal_no_money, false)
        OR v_normalised_state IN ('COMPLETED', 'FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED', 'REVERSED')
      );

    v_settlement_required := false;
    v_settlement_trigger := CASE
      WHEN COALESCE(v_has_strong_transfer_mapping, false) IS NOT TRUE THEN 'BANK_EVENT_UNMATCHED_OR_WEAK'
      WHEN COALESCE(v_terminal_bank_event, false) THEN 'BANK_EVENT_TERMINAL_TRANSFER_ONLY'
      ELSE 'BANK_EVENT_NON_TERMINAL'
    END;
    v_all_batch_transfers_terminal := false;
    v_terminal_success_transfer_count := 0;
    v_terminal_failed_transfer_count := 0;
    v_pending_transfer_count := 0;
    v_unknown_transfer_count := 0;
    v_pending_or_unknown_transfer_count := 0;

    IF v_pay_batch_id IS NOT NULL AND COALESCE(v_terminal_bank_event, false) THEN
      SELECT
        COALESCE(COUNT(*) FILTER (WHERE terminality_rows.is_success_terminal), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE terminality_rows.is_failed_terminal), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE terminality_rows.is_pending_non_terminal), 0)::integer,
        COALESCE(COUNT(*) FILTER (
          WHERE terminality_rows.is_success_terminal IS NOT TRUE
            AND terminality_rows.is_failed_terminal IS NOT TRUE
            AND terminality_rows.is_pending_non_terminal IS NOT TRUE
        ), 0)::integer
      INTO
        v_terminal_success_transfer_count,
        v_terminal_failed_transfer_count,
        v_pending_transfer_count,
        v_unknown_transfer_count
      FROM (
        SELECT
          transfer_row.id AS pay_bank_transfer_id,
          (
            COALESCE(transfer_class.is_final_money_moved, false)
            OR upper(btrim(COALESCE(transfer_row.status, ''))) IN ('COMPLETED', 'COMPLETE', 'PAID', 'SETTLED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
          ) AS is_success_terminal,
          (
            COALESCE(transfer_class.is_terminal_no_money, false)
            OR upper(btrim(COALESCE(transfer_row.status, ''))) IN ('FAILED', 'FAILURE', 'REJECTED', 'DECLINED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED')
          ) AS is_failed_terminal,
          (
            COALESCE(transfer_class.is_pending_non_final, false)
            OR upper(btrim(COALESCE(transfer_row.status, ''))) IN ('PENDING', 'SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'WAITING', 'WAITING_BANK_CONFIRM')
          ) AS is_pending_non_terminal
        FROM public.pay_bank_transfers AS transfer_row
        LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
          transfer_row.status,
          transfer_row.rail_state,
          COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
          COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
        ) AS transfer_class ON true
        WHERE transfer_row.pay_batch_id = v_pay_batch_id
      ) AS terminality_rows;

      v_pending_or_unknown_transfer_count := COALESCE(v_pending_transfer_count, 0) + COALESCE(v_unknown_transfer_count, 0);
      v_all_batch_transfers_terminal := (
        COALESCE(v_terminal_success_transfer_count, 0) + COALESCE(v_terminal_failed_transfer_count, 0) > 0
        AND COALESCE(v_pending_or_unknown_transfer_count, 0) = 0
      );

      v_settlement_required := COALESCE(v_all_batch_transfers_terminal, false);
      v_settlement_trigger := CASE
        WHEN COALESCE(v_settlement_required, false) THEN 'BANK_EVENT_TERMINAL_BATCH_READY'
        ELSE 'BANK_EVENT_TERMINAL_TRANSFER_ONLY'
      END;
    END IF;

    v_settlement_intent_json := jsonb_strip_nulls(jsonb_build_object(
      'settlement_required', COALESCE(v_settlement_required, false),
      'settlement_trigger', v_settlement_trigger,
      'pay_batch_id', CASE WHEN v_pay_batch_id IS NULL THEN NULL ELSE v_pay_batch_id::text END,
      'pay_bank_transfer_id', CASE WHEN v_pay_bank_transfer_id IS NULL THEN NULL ELSE v_pay_bank_transfer_id::text END,
      'normalised_state', v_normalised_state,
      'cash_state', v_event_cash_state,
      'all_batch_transfers_terminal', COALESCE(v_all_batch_transfers_terminal, false),
      'terminal_success_transfer_count', COALESCE(v_terminal_success_transfer_count, 0),
      'terminal_failed_transfer_count', COALESCE(v_terminal_failed_transfer_count, 0),
      'pending_or_unknown_transfer_count', COALESCE(v_pending_or_unknown_transfer_count, 0),
      'unknown_transfer_count', COALESCE(v_unknown_transfer_count, 0)
    ));

    v_signal_recommendation_json := jsonb_build_object(
      'pay_batch_id', CASE WHEN v_pay_batch_id IS NULL THEN NULL ELSE v_pay_batch_id::text END,
      'touch_payment_status', false,
      'touch_correction_progress', false,
      'touch_alerts', false,
      'touch_overview', false,
      'change_reason', 'BANK_EVENT_DUPLICATE_NO_SIGNAL',
      'change_source', 'pay_bank_event_ingest',
      'changed_transfer_ids', '[]'::jsonb,
      'changed_candidate_ids', '[]'::jsonb,
      'changed_pay_batch_item_ids', '[]'::jsonb,
      'alert_candidate_kind', NULL::text,
      'alert_candidate_is_success_only', false,
      'provider_failure_reason_code', v_provider_failure_reason_code,
      'provider_failure_reason_group', v_provider_failure_reason_group,
      'source_delivery_id', v_source_delivery_id,
      'source_batch_event_group_key', v_source_batch_event_group_key,
      'change_scope_json', v_settlement_intent_json
    ) || v_settlement_intent_json;

    v_live_signal_result := jsonb_build_object(
      'ok', true,
      'changed', false,
      'duplicate_event', true,
      'reason', 'Bank event already recorded; live signal was not touched.',
      'signal_recommendation_json', v_signal_recommendation_json
    );

    RETURN jsonb_build_object(
      'ok', true,
      'event_id', v_event_id,
      'idempotent', true,
      'mapped', v_mapping_status = 'MATCHED',
      'normalised_state', v_normalised_state,
      'manual_resolution_recorded', v_manual_confirmed_not_paid,
      'release_eligible', v_manual_confirmed_not_paid,
      'auto_release_request_prepared', false,
      'existing_release_request_id', NULL::uuid,
      'existing_release_operation_woken', false,
      'paid_after_release', v_paid_after_release,
      'requires_user_action', v_paid_after_release OR v_mapping_status <> 'MATCHED',
      'continuations', '[]'::jsonb,
      'display_status', CASE WHEN v_paid_after_release THEN 'Paid — evidence received after release' ELSE 'Payment status already recorded' END,
      'display_message', CASE
        WHEN v_paid_after_release THEN 'The bank confirmed this payment after CloudTMS released its payment reservation. CloudTMS has blocked any further payment action and retained both histories for Finance review.'
        ELSE 'This payment status was already recorded.'
      END,
      'inserted', false,
      'mapping_status', v_mapping_status,
      'mapping_method', v_mapping_method,
      'classification', COALESCE(v_classification, 'UNKNOWN'),
      'correction_disposition', COALESCE(v_correction_disposition, 'ALREADY_RECORDED'),
      'correction_request_id', NULL::uuid,
      'admin_notice_group_id', NULL::uuid,
      'live_signal', v_live_signal_result,
      'signal_recommendation_json', v_signal_recommendation_json
    ) || v_settlement_intent_json;
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NOT NULL THEN
    SELECT public.pay_bank_transfers.*
    INTO v_transfer
    FROM public.pay_bank_transfers
    WHERE public.pay_bank_transfers.id = v_pay_bank_transfer_id
    FOR UPDATE;

    IF v_transfer.id IS NOT NULL THEN
      SELECT COALESCE(existing_transfer_classification.is_final_money_moved, false)
      INTO v_existing_transfer_is_final_paid
      FROM public._pay_rail_state_money_movement_classify(
        v_transfer.status,
        v_transfer.rail_state,
        COALESCE(v_transfer.rail_meta_json, '{}'::jsonb),
        COALESCE(v_transfer.rail_meta_json, '{}'::jsonb)
      ) AS existing_transfer_classification
      LIMIT 1;

      v_existing_transfer_is_final_paid := COALESCE(v_existing_transfer_is_final_paid, false);
    ELSE
      v_existing_transfer_is_final_paid := false;
    END IF;
  ELSE
    v_existing_transfer_is_final_paid := false;
  END IF;

  IF v_pay_bank_transfer_id IS NOT NULL AND COALESCE(v_has_strong_transfer_mapping, false) THEN
    IF v_normalised_state = 'COMPLETED' THEN
      UPDATE public.pay_bank_transfers AS transfer_to_update
      SET
        status = 'COMPLETED',
        completed_at_utc = COALESCE(transfer_to_update.completed_at_utc, v_event_time_utc, v_now),
        rail_state = COALESCE(v_provider_state, transfer_to_update.rail_state),
        rail_tx_id = COALESCE(NULLIF(v_provider_transaction_id, ''), NULLIF(v_provider_reference, ''), transfer_to_update.rail_tx_id),
        rail_meta_json = COALESCE(transfer_to_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'latest_bank_event_id', v_event_id,
          'latest_bank_event_state', v_normalised_state,
          'latest_bank_event_at_utc', v_now
        )
      WHERE transfer_to_update.id = v_pay_bank_transfer_id;
    ELSIF COALESCE(v_existing_transfer_is_final_paid, false) THEN
      UPDATE public.pay_bank_transfers AS transfer_to_update
      SET
        rail_meta_json = COALESCE(transfer_to_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'latest_bank_event_id', v_event_id,
          'latest_bank_event_state', v_normalised_state,
          'latest_bank_event_at_utc', v_now,
          'ignored_after_final_paid', true,
          'ignored_after_final_paid_reason', 'Existing transfer already has final-paid evidence; non-final or no-money event must not downgrade settlement evidence.'
        )
      WHERE transfer_to_update.id = v_pay_bank_transfer_id;
    ELSIF v_event_is_terminal_no_money AND v_normalised_state IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED') THEN
      UPDATE public.pay_bank_transfers AS transfer_to_update
      SET
        status = v_normalised_state,
        failed_reason = CASE
          WHEN v_normalised_state IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED') THEN COALESCE(NULLIF(v_provider_state, ''), transfer_to_update.failed_reason)
          ELSE transfer_to_update.failed_reason
        END,
        rail_state = COALESCE(v_provider_state, transfer_to_update.rail_state),
        rail_meta_json = COALESCE(transfer_to_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'latest_bank_event_id', v_event_id,
          'latest_bank_event_state', v_normalised_state,
          'latest_bank_event_at_utc', v_now
        )
      WHERE transfer_to_update.id = v_pay_bank_transfer_id;
    ELSIF v_normalised_state IN ('SUBMITTED', 'PENDING', 'PROCESSING', 'UNKNOWN') THEN
      UPDATE public.pay_bank_transfers AS transfer_to_update
      SET
        status = CASE
          WHEN v_normalised_state = 'SUBMITTED' THEN 'PENDING'
          WHEN v_normalised_state IN ('PENDING', 'PROCESSING', 'UNKNOWN') THEN v_normalised_state
          ELSE transfer_to_update.status
        END,
        rail_state = COALESCE(v_provider_state, transfer_to_update.rail_state),
        rail_tx_id = COALESCE(NULLIF(v_provider_transaction_id, ''), NULLIF(v_provider_reference, ''), transfer_to_update.rail_tx_id),
        rail_meta_json = COALESCE(transfer_to_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'latest_bank_event_id', v_event_id,
          'latest_bank_event_state', v_normalised_state,
          'latest_bank_event_at_utc', v_now
        )
      WHERE transfer_to_update.id = v_pay_bank_transfer_id;
    END IF;
  END IF;


  v_terminal_bank_event := COALESCE(v_has_strong_transfer_mapping, false)
    AND (
    COALESCE(v_event_is_final_paid, false)
    OR COALESCE(v_event_is_terminal_no_money, false)
    OR v_normalised_state IN ('COMPLETED', 'FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED', 'REVERSED')
    );

  v_settlement_required := false;
  v_settlement_trigger := CASE
    WHEN COALESCE(v_has_strong_transfer_mapping, false) IS NOT TRUE THEN 'BANK_EVENT_UNMATCHED_OR_WEAK'
    WHEN COALESCE(v_terminal_bank_event, false) THEN 'BANK_EVENT_TERMINAL_TRANSFER_ONLY'
    ELSE 'BANK_EVENT_NON_TERMINAL'
  END;
  v_all_batch_transfers_terminal := false;
  v_terminal_success_transfer_count := 0;
  v_terminal_failed_transfer_count := 0;
  v_pending_transfer_count := 0;
  v_unknown_transfer_count := 0;
  v_pending_or_unknown_transfer_count := 0;

  IF v_pay_batch_id IS NOT NULL AND COALESCE(v_terminal_bank_event, false) THEN
    SELECT
    COALESCE(COUNT(*) FILTER (WHERE terminality_rows.is_success_terminal), 0)::integer,
    COALESCE(COUNT(*) FILTER (WHERE terminality_rows.is_failed_terminal), 0)::integer,
    COALESCE(COUNT(*) FILTER (WHERE terminality_rows.is_pending_non_terminal), 0)::integer,
    COALESCE(COUNT(*) FILTER (
      WHERE terminality_rows.is_success_terminal IS NOT TRUE
        AND terminality_rows.is_failed_terminal IS NOT TRUE
        AND terminality_rows.is_pending_non_terminal IS NOT TRUE

    ), 0)::integer
    INTO
    v_terminal_success_transfer_count,
    v_terminal_failed_transfer_count,
    v_pending_transfer_count,
    v_unknown_transfer_count
    FROM (
    SELECT
      transfer_row.id AS pay_bank_transfer_id,
      (
        COALESCE(transfer_class.is_final_money_moved, false)
        OR upper(btrim(COALESCE(transfer_row.status, ''))) IN ('COMPLETED', 'COMPLETE', 'PAID', 'SETTLED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
      ) AS is_success_terminal,
      (
        COALESCE(transfer_class.is_terminal_no_money, false)
        OR upper(btrim(COALESCE(transfer_row.status, ''))) IN ('FAILED', 'FAILURE', 'REJECTED', 'DECLINED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED')
      ) AS is_failed_terminal,
      (
        COALESCE(transfer_class.is_pending_non_final, false)
        OR upper(btrim(COALESCE(transfer_row.status, ''))) IN ('PENDING', 'SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'WAITING', 'WAITING_BANK_CONFIRM')
      ) AS is_pending_non_terminal
    FROM public.pay_bank_transfers AS transfer_row
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      transfer_row.status,
      transfer_row.rail_state,
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
    ) AS transfer_class ON true
    WHERE transfer_row.pay_batch_id = v_pay_batch_id
    ) AS terminality_rows;

  v_pending_or_unknown_transfer_count := COALESCE(v_pending_transfer_count, 0) + COALESCE(v_unknown_transfer_count, 0);
  v_all_batch_transfers_terminal := (
    COALESCE(v_terminal_success_transfer_count, 0) + COALESCE(v_terminal_failed_transfer_count, 0) > 0
    AND COALESCE(v_pending_or_unknown_transfer_count, 0) = 0
    );
  v_settlement_required := COALESCE(v_all_batch_transfers_terminal, false);
  v_settlement_trigger := CASE
    WHEN COALESCE(v_settlement_required, false) THEN 'BANK_EVENT_TERMINAL_BATCH_READY'
    ELSE 'BANK_EVENT_TERMINAL_TRANSFER_ONLY'
    END;
  END IF;

  v_settlement_intent_json := jsonb_strip_nulls(jsonb_build_object(
    'settlement_required', COALESCE(v_settlement_required, false),
    'settlement_trigger', v_settlement_trigger,
    'pay_batch_id', CASE WHEN v_pay_batch_id IS NULL THEN NULL ELSE v_pay_batch_id::text END,
    'pay_bank_transfer_id', CASE WHEN v_pay_bank_transfer_id IS NULL THEN NULL ELSE v_pay_bank_transfer_id::text END,
    'normalised_state', v_normalised_state,
    'cash_state', v_event_cash_state,
    'all_batch_transfers_terminal', COALESCE(v_all_batch_transfers_terminal, false),
    'terminal_success_transfer_count', COALESCE(v_terminal_success_transfer_count, 0),
    'terminal_failed_transfer_count', COALESCE(v_terminal_failed_transfer_count, 0),
    'pending_or_unknown_transfer_count', COALESCE(v_pending_or_unknown_transfer_count, 0),
    'unknown_transfer_count', COALESCE(v_unknown_transfer_count, 0)
  ));

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_items AS released_item
    WHERE released_item.status = 'APPLIED'
      AND released_item.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND')
      AND (
        (v_pay_bank_transfer_id IS NOT NULL AND released_item.pay_bank_transfer_id = v_pay_bank_transfer_id)
        OR (v_pay_bank_transfer_id IS NULL AND v_candidate_id IS NOT NULL AND released_item.candidate_id = v_candidate_id)
      )
  ) AND COALESCE(v_event_is_final_paid, false)
  INTO v_paid_after_release;

  IF v_normalised_state = 'COMPLETED' AND COALESCE(v_has_strong_transfer_mapping, false) THEN
    SELECT COALESCE(
             p_actor_user_id,
             (
               SELECT operation_row.actor_user_id
               FROM public.banking_pay_operations AS operation_row
               WHERE operation_row.pay_batch_id = v_pay_batch_id
                 AND operation_row.actor_user_id IS NOT NULL
               ORDER BY operation_row.created_at_utc DESC, operation_row.id DESC
               LIMIT 1
             )
           )
    INTO v_settlement_actor_user_id;

    IF v_settlement_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'PAY_BANK_EVENT_SETTLEMENT_ACTOR_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
          'code', 'EVENT_AUTHORITY_REQUIRED',
          'bank_event_id', v_event_id,
          'pay_batch_id', v_pay_batch_id,
          'pay_bank_transfer_id', v_pay_bank_transfer_id,
          'message', 'The paid event was retained, but the payment execution actor could not be resolved for settlement application.'
        )::text;
    END IF;

    v_settlement_apply_result := public.pay_settle_rail(
      p_pay_batch_id => v_pay_batch_id,
      p_settlement_json => jsonb_build_array(jsonb_build_object(
        'bank_event_id', v_event_id,
        'transfer_id', v_pay_bank_transfer_id,
        'status', 'COMPLETED',
        'normalised_state', 'COMPLETED',
        'rail_tx_id', COALESCE(v_provider_transaction_id, v_provider_reference, v_transfer.rail_tx_id),
        'rail_state', COALESCE(v_provider_state, v_transfer.rail_state, 'COMPLETED'),
        'provider_event_id', v_provider_event_id,
        'provider_transaction_id', v_provider_transaction_id,
        'provider_request_id', v_provider_request_id,
        'provider_reference', v_provider_reference,
        'event_source', v_event_source,
        'event_time_utc', COALESCE(v_event_time_utc, v_now),
        'rail_meta_json', jsonb_build_object(
          'bank_event_id', v_event_id,
          'provider_event_id', v_provider_event_id,
          'provider_transaction_id', v_provider_transaction_id,
          'provider_request_id', v_provider_request_id,
          'provider_reference', v_provider_reference,
          'event_source', v_event_source,
          'settlement_authority', 'EXISTING_MAPPED_TERMINAL_EVENT'
        )
      )),
      p_actor_user_id => v_settlement_actor_user_id,
      p_operation_id => NULL::uuid,
      p_settlement_scope_ids => NULL::jsonb
    );
  END IF;

  IF v_normalised_state = 'COMPLETED'
     AND COALESCE(v_has_strong_transfer_mapping, false)
     AND COALESCE(v_paid_after_release, false) IS NOT TRUE THEN
    IF v_pay_bank_transfer_id IS NOT NULL THEN
      SELECT public._pay_manual_adjustment_carry_forward_mark_consumed(
        v_pay_batch_id,
        NULL::uuid[],
        jsonb_build_object(
          'pay_batch_id', v_pay_batch_id::text,
          'pay_bank_transfer_ids', jsonb_build_array(v_pay_bank_transfer_id::text),
          'pay_batch_item_ids', COALESCE((
            SELECT jsonb_agg(event_item_rows.id::text ORDER BY event_item_rows.id::text)
            FROM public.pay_batch_items AS event_item_rows
            JOIN public.pay_batch_candidates AS event_candidate_rows
              ON event_candidate_rows.id = event_item_rows.pay_batch_candidate_id
            WHERE event_candidate_rows.pay_batch_id = v_pay_batch_id
              AND event_item_rows.pay_bank_transfer_id = v_pay_bank_transfer_id
          ), '[]'::jsonb)
        ),
        jsonb_build_object(
          'final_paid', true,
          'cash_state', 'FINAL_PAID',
          'source', 'pay_bank_event_ingest',
          'bank_event_id', v_event_id::text
        ),
        v_settlement_actor_user_id
      )
      INTO v_carry_forward_mark_result;

      v_consumed_carry_forward_count := COALESCE(NULLIF(v_carry_forward_mark_result->>'consumed_count', '')::integer, 0);
    END IF;

    v_classification := NULL::text;
    v_correction_disposition := 'NO_CORRECTION_REQUIRED';
    v_classification_result := jsonb_build_object(
      'classification', NULL::text,
      'reasons', jsonb_build_array('COMPLETED_EVENT_NO_PAYMENT_CORRECTION_REQUIRED'),
      'evidence', jsonb_build_object(
        'mapping_status', v_mapping_status,
        'mapping_method', v_mapping_method,
        'normalised_state', v_normalised_state
      ),
      'counts', '{}'::jsonb,
      'blockers', '[]'::jsonb,
      'selected_amounts', '{}'::jsonb,
      'safe_to_auto_apply', false
    );

    UPDATE public.pay_bank_transfer_events AS bank_event_to_update
    SET
      movement_classification = NULL::text,
      correction_disposition = v_correction_disposition
    WHERE bank_event_to_update.id = v_event_id;

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_BANK_EVENT_INGEST_COMPLETED_NO_CORRECTION',
      jsonb_build_object(
        'event_id', v_event_id,
        'pay_batch_id', v_pay_batch_id,
        'pay_bank_transfer_id', v_pay_bank_transfer_id,
        'mapping_status', v_mapping_status,
        'mapping_method', v_mapping_method,
        'correction_disposition', v_correction_disposition
      ),
      'pay_payment_correction',
      v_event_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    v_signal_recommendation_json := jsonb_build_object(
      'pay_batch_id', v_pay_batch_id::text,
      'touch_payment_status', true,
      'touch_correction_progress', false,
      'touch_alerts', false,
      'touch_overview', true,
      'change_reason', 'BANK_EVENT_COMPLETED',
      'change_source', 'pay_bank_event_ingest',
      'changed_transfer_ids', CASE WHEN v_pay_bank_transfer_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_pay_bank_transfer_id::text) END,
      'changed_candidate_ids', CASE WHEN v_candidate_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_candidate_id::text) END,
      'changed_pay_batch_item_ids', '[]'::jsonb,
      'alert_candidate_kind', NULL::text,
      'alert_candidate_is_success_only', true,
      'provider_failure_reason_code', v_provider_failure_reason_code,
      'provider_failure_reason_group', v_provider_failure_reason_group,
      'source_delivery_id', v_source_delivery_id,
      'source_batch_event_group_key', v_source_batch_event_group_key,
      'change_scope_json', jsonb_build_object(
        'bank_event_id', v_event_id::text,
        'pay_bank_transfer_id', CASE WHEN v_pay_bank_transfer_id IS NULL THEN NULL ELSE v_pay_bank_transfer_id::text END,
        'normalised_state', v_normalised_state,
        'provider_event_transport', v_provider_event_transport,
        'provider_transaction_id', v_provider_transaction_id,
        'provider_request_id', v_provider_request_id
      ) || v_settlement_intent_json
    ) || v_settlement_intent_json;

    IF v_should_touch_signal THEN
      v_live_signal_result := public.banking_pay_batch_signal_touch(
        v_pay_batch_id,
        'BANK_EVENT_COMPLETED',
        'pay_bank_event_ingest',
        v_signal_recommendation_json->'change_scope_json',
        true,
        false,
        false,
        true
      );
    ELSE
      v_live_signal_result := jsonb_build_object(
        'ok', true,
        'changed', false,
        'deferred', true,
        'signal_recommendation_json', v_signal_recommendation_json
      );
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'event_id', v_event_id,
      'idempotent', NOT v_inserted_event,
      'mapped', true,
      'normalised_state', v_normalised_state,
      'manual_resolution_recorded', false,
      'release_eligible', false,
      'auto_release_request_prepared', false,
      'existing_release_request_id', NULL::uuid,
      'existing_release_operation_woken', false,
      'paid_after_release', v_paid_after_release,
      'requires_user_action', v_paid_after_release,
      'continuations', '[]'::jsonb,
      'display_status', CASE WHEN v_paid_after_release THEN 'Paid — evidence received after release' ELSE 'Paid' END,
      'display_message', CASE
        WHEN v_paid_after_release THEN 'The bank confirmed this payment after CloudTMS released its payment reservation. CloudTMS has blocked any further payment action and retained both histories for Finance review.'
        ELSE 'The bank confirmed this payment.'
      END,
      'inserted', v_inserted_event,
      'mapping_status', v_mapping_status,

      'mapping_method', v_mapping_method,
      'classification', NULL::text,
      'correction_disposition', v_correction_disposition,
      'correction_request_id', NULL::uuid,
      'admin_notice_group_id', NULL::uuid,
      'live_signal', v_live_signal_result,
      'signal_recommendation_json', v_signal_recommendation_json,
      'selection_json', NULL::jsonb,
      'classification_result', v_classification_result,
      'auto_apply', jsonb_build_object(
        'auto_setting', false,
        'safe_to_auto_apply', false,
        'request_start_result', NULL::jsonb,
        'expand_result', NULL::jsonb,
        'process_result', NULL::jsonb,
        'blocker', NULL::jsonb
      ),
      'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
      'carry_forward_mark_consumed_result', COALESCE(v_carry_forward_mark_result, '{}'::jsonb),
      'settlement_result', COALESCE(v_settlement_apply_result, '{}'::jsonb)
    ) || v_settlement_intent_json;
  END IF;

  IF v_normalised_state IN ('SUBMITTED', 'PENDING', 'PROCESSING') THEN
    IF v_mapping_status = 'MATCHED'
       AND v_mapping_method IN (
         'TRANSFER_ID',
         'PROVIDER_EVENT_ID',
         'PROVIDER_TRANSACTION_ID',
         'REQUEST_ID',
         'PROVIDER_REFERENCE',
         'RAIL_TX_ID',
         'MATCHED_PROVIDER_EVENT',
         'MANUAL_TRANSFER_SELECTION'
       )
       AND v_provider_state_upper NOT IN ('TIMEOUT', 'TIMED_OUT', 'TIMEDOUT', 'API_TIMEOUT') THEN
      v_classification := NULL::text;
      v_correction_disposition := 'NO_CORRECTION_REQUIRED';
      v_classification_result := jsonb_build_object(
        'classification', NULL::text,
        'reasons', jsonb_build_array('NON_TERMINAL_PROVIDER_STATE_NO_PAYMENT_CORRECTION_REQUIRED'),
        'evidence', jsonb_build_object(
          'mapping_status', v_mapping_status,
          'mapping_method', v_mapping_method,
          'normalised_state', v_normalised_state,
          'provider_state', v_provider_state
        ),
        'counts', '{}'::jsonb,
        'blockers', '[]'::jsonb,
        'selected_amounts', '{}'::jsonb,
        'safe_to_auto_apply', false
      );

      UPDATE public.pay_bank_transfer_events AS bank_event_to_update
      SET
        movement_classification = NULL::text,
        correction_disposition = v_correction_disposition,
        mapping_method = v_mapping_method
      WHERE bank_event_to_update.id = v_event_id;

      PERFORM public._imp_debug_audit(
        p_actor_user_id,
        'PAYMENT_BANK_EVENT_INGEST_NON_TERMINAL_NO_CORRECTION',
        jsonb_build_object(
          'event_id', v_event_id,
          'pay_batch_id', v_pay_batch_id,
          'pay_bank_transfer_id', v_pay_bank_transfer_id,
          'normalised_state', v_normalised_state,
          'mapping_status', v_mapping_status,
          'mapping_method', v_mapping_method,
          'correction_disposition', v_correction_disposition
        ),
        'pay_payment_correction',
        v_event_id::text,
        NULL::jsonb,
        NULL::text,
        NULL::text,
        NULL::text
      );

      v_signal_recommendation_json := jsonb_build_object(
        'pay_batch_id', v_pay_batch_id::text,
        'touch_payment_status', true,
        'touch_correction_progress', false,
        'touch_alerts', false,
        'touch_overview', true,
        'change_reason', 'BANK_EVENT_PENDING_OR_NON_TERMINAL',
        'change_source', 'pay_bank_event_ingest',
        'changed_transfer_ids', CASE WHEN v_pay_bank_transfer_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_pay_bank_transfer_id::text) END,
        'changed_candidate_ids', CASE WHEN v_candidate_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_candidate_id::text) END,
        'changed_pay_batch_item_ids', '[]'::jsonb,
        'alert_candidate_kind', NULL::text,
        'alert_candidate_is_success_only', false,
        'provider_failure_reason_code', v_provider_failure_reason_code,
        'provider_failure_reason_group', v_provider_failure_reason_group,
        'source_delivery_id', v_source_delivery_id,
        'source_batch_event_group_key', v_source_batch_event_group_key,
        'change_scope_json', jsonb_build_object(
          'bank_event_id', v_event_id::text,
          'pay_bank_transfer_id', CASE WHEN v_pay_bank_transfer_id IS NULL THEN NULL ELSE v_pay_bank_transfer_id::text END,
          'normalised_state', v_normalised_state,
          'provider_event_transport', v_provider_event_transport
        ) || v_settlement_intent_json
      ) || v_settlement_intent_json;

      IF v_should_touch_signal THEN
        v_live_signal_result := public.banking_pay_batch_signal_touch(
          v_pay_batch_id,
          'BANK_EVENT_PENDING_OR_NON_TERMINAL',
          'pay_bank_event_ingest',
          v_signal_recommendation_json->'change_scope_json',
          true,
          false,
          false,
          true
        );
      ELSE
        v_live_signal_result := jsonb_build_object(
          'ok', true,
          'changed', false,
          'deferred', true,
          'signal_recommendation_json', v_signal_recommendation_json
        );
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'event_id', v_event_id,
        'idempotent', NOT v_inserted_event,
        'mapped', true,
        'normalised_state', v_normalised_state,
        'manual_resolution_recorded', false,
        'release_eligible', false,
        'auto_release_request_prepared', false,
        'existing_release_request_id', NULL::uuid,
        'existing_release_operation_woken', false,
        'paid_after_release', false,
        'requires_user_action', false,
        'continuations', '[]'::jsonb,
        'display_status', 'Payment status updated',
        'display_message', 'The latest provider payment status was recorded.',
        'inserted', v_inserted_event,
        'mapping_status', v_mapping_status,
        'mapping_method', v_mapping_method,
        'classification', NULL::text,
        'correction_disposition', v_correction_disposition,
        'correction_request_id', NULL::uuid,
        'admin_notice_group_id', NULL::uuid,
        'live_signal', v_live_signal_result,
        'signal_recommendation_json', v_signal_recommendation_json,
        'message', 'Provider state recorded; no correction action required yet.',
        'selection_json', NULL::jsonb,
        'classification_result', v_classification_result,
        'auto_apply', jsonb_build_object(
          'auto_setting', false,
          'safe_to_auto_apply', false,
          'request_start_result', NULL::jsonb,
          'expand_result', NULL::jsonb,
          'process_result', NULL::jsonb,
          'final_work_item_totals', v_final_work_item_totals,
          'blocker', NULL::jsonb
        )
      ) || v_settlement_intent_json;
    END IF;
  END IF;

  IF v_pay_bank_transfer_id IS NOT NULL THEN
    v_selection_json := jsonb_build_object(
      'scope_type', 'TRANSFER',
      'pay_bank_transfer_ids', jsonb_build_array(v_pay_bank_transfer_id::text),
      'source_context', 'BANK_EVENT_INGEST',
      'requested_action', CASE
        WHEN v_event_is_terminal_no_money THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
        WHEN v_event_is_final_paid THEN 'AMEND_AND_RECOVER_OVERPAYMENT'
        ELSE 'CHECK_PROVIDER_STATUS'
      END
    );
  ELSIF v_candidate_id IS NOT NULL THEN
    v_selection_json := jsonb_build_object(
      'scope_type', 'CANDIDATES',
      'pay_batch_candidate_ids', COALESCE((
        SELECT jsonb_agg(candidate_scope_rows.id::text ORDER BY candidate_scope_rows.id::text)
        FROM public.pay_batch_candidates AS candidate_scope_rows
        WHERE candidate_scope_rows.pay_batch_id = v_pay_batch_id
          AND candidate_scope_rows.candidate_id = v_candidate_id
      ), '[]'::jsonb),
      'source_context', 'BANK_EVENT_INGEST',
      'requested_action', CASE
        WHEN v_event_is_terminal_no_money THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
        WHEN v_event_is_final_paid THEN 'AMEND_AND_RECOVER_OVERPAYMENT'
        ELSE 'CHECK_PROVIDER_STATUS'
      END
    );
  ELSE

    v_selection_json := jsonb_build_object(
      'scope_type', 'BATCH',
      'source_context', 'BANK_EVENT_INGEST',
      'requested_action', CASE
        WHEN v_event_is_terminal_no_money THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
        WHEN v_event_is_final_paid THEN 'AMEND_AND_RECOVER_OVERPAYMENT'
        ELSE 'CHECK_PROVIDER_STATUS'
      END
    );
  END IF;

  IF v_mapping_status = 'MATCHED'
     AND v_mapping_method IN (
       'TRANSFER_ID',
       'PROVIDER_EVENT_ID',
       'PROVIDER_TRANSACTION_ID',
       'REQUEST_ID',
       'PROVIDER_REFERENCE',
       'RAIL_TX_ID',
       'MATCHED_PROVIDER_EVENT',
       'MANUAL_TRANSFER_SELECTION'
     ) THEN
    v_classification_result := public._pay_payment_movement_classify(
      v_pay_batch_id,
      v_selection_json
    );
    v_classification := COALESCE(v_classification_result->>'classification', 'AMBIGUOUS_REVIEW_REQUIRED');
    v_safe_to_auto_apply := COALESCE((v_classification_result->>'safe_to_auto_apply')::boolean, false);
  ELSE
    v_classification := 'AMBIGUOUS_REVIEW_REQUIRED';
    v_classification_result := jsonb_build_object(
      'classification', v_classification,
      'reasons', jsonb_build_array('BANK_EVENT_MAPPING_NOT_STRONG_MATCH'),
      'evidence', jsonb_build_object(
        'mapping_status', v_mapping_status,
        'mapping_method', v_mapping_method
      ),
      'counts', '{}'::jsonb,
      'blockers', jsonb_build_array(jsonb_build_object(
        'code', 'BANK_EVENT_MAPPING_NOT_STRONG_MATCH',
        'message', 'Bank event could not be mapped to a transfer using a strong exact mapping method. Amount-only, unmatched, ambiguous, and legacy no-artifact mappings require manual review.'
      )),
      'selected_amounts', '{}'::jsonb,
      'safe_to_auto_apply', false
    );
    v_safe_to_auto_apply := false;
  END IF;

  SELECT COALESCE(public.settings_defaults.banking_pay_auto_unwind_terminal_no_money, false)
  INTO v_auto_setting
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_event_required_action := NULLIF(btrim(COALESCE(v_classification_result->>'recommended_action', '')), '');

  v_notice_kind := CASE
    WHEN COALESCE(v_existing_transfer_is_final_paid, false)
      OR v_event_is_final_paid
      OR v_classification = 'PAID_OR_SETTLED'
      OR v_event_required_action = 'AMEND_AND_RECOVER_OVERPAYMENT'
      THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
    WHEN v_classification IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
      OR v_event_required_action = 'NO_MONEY_UNWIND_AND_RECALCULATE'
      THEN 'NO_MONEY_UNWIND_REQUIRED'
    WHEN v_classification = 'PROVIDER_OUTCOME_UNKNOWN' OR v_event_required_action = 'CHECK_PROVIDER_STATUS' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    ELSE 'BANK_FAILURE_DETECTED'
  END;

  IF COALESCE(v_existing_transfer_is_final_paid, false) AND v_event_is_terminal_no_money THEN
    v_correction_disposition := 'ACTION_REQUIRED';
  ELSIF v_event_is_final_paid AND COALESCE(v_has_strong_transfer_mapping, false) THEN
    v_correction_disposition := 'NO_CORRECTION_REQUIRED';
  ELSIF v_event_is_final_paid THEN
    v_correction_disposition := 'ACTION_REQUIRED';
  ELSIF v_classification IS NULL THEN
    v_correction_disposition := 'NO_CORRECTION_REQUIRED';
  ELSIF v_classification = 'AMBIGUOUS_REVIEW_REQUIRED' THEN
    v_correction_disposition := 'AMBIGUOUS';
  ELSIF v_event_is_pending_non_final OR v_event_cash_state = 'UNKNOWN' OR v_event_required_action = 'CHECK_PROVIDER_STATUS' THEN
    v_correction_disposition := 'ACTION_REQUIRED';
  ELSIF NOT COALESCE(v_auto_setting, false) THEN
    v_correction_disposition := 'ACTION_REQUIRED';
  ELSIF NOT COALESCE(v_safe_to_auto_apply, false) THEN
    v_correction_disposition := 'BLOCKED';
  ELSE
    v_correction_disposition := 'ACTION_REQUIRED';
  END IF;
  IF COALESCE(v_auto_setting, false)
     AND COALESCE(v_safe_to_auto_apply, false)
     AND COALESCE(v_suppress_auto_unwind, false) IS NOT TRUE
     AND COALESCE(v_manual_confirmed_not_paid, false) IS NOT TRUE
     AND v_event_source NOT IN ('MANUAL_EVIDENCE', 'MANUAL_CONFIRM')
     AND v_mapping_status = 'MATCHED'
     AND NOT COALESCE(v_existing_transfer_is_final_paid, false)
     AND v_mapping_method IN (
       'TRANSFER_ID',
       'PROVIDER_EVENT_ID',
       'PROVIDER_TRANSACTION_ID',
       'REQUEST_ID',
       'PROVIDER_REFERENCE',
       'RAIL_TX_ID',
       'MATCHED_PROVIDER_EVENT',
       'MANUAL_TRANSFER_SELECTION'
     )
     AND v_event_is_terminal_no_money
     AND (
       v_classification IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
       OR v_event_required_action = 'NO_MONEY_UNWIND_AND_RECALCULATE'
     ) THEN
    BEGIN
      v_selection_json := v_selection_json || jsonb_build_object(
        'command', 'PREPARE',
        'contract_version', 1,
        'mode', 'EXPLICIT',
        'requested_action', 'NO_MONEY_UNWIND',
        'explicit_candidate_tokens', COALESCE((
          SELECT jsonb_agg(DISTINCT candidate_scope.id::text ORDER BY candidate_scope.id::text)
          FROM public.pay_batch_candidates AS candidate_scope
          JOIN public.pay_batch_items AS candidate_item
            ON candidate_item.pay_batch_candidate_id = candidate_scope.id
          WHERE candidate_scope.pay_batch_id = v_pay_batch_id
            AND (
              (v_pay_bank_transfer_id IS NOT NULL AND candidate_item.pay_bank_transfer_id = v_pay_bank_transfer_id)
              OR (v_pay_bank_transfer_id IS NULL AND v_candidate_id IS NOT NULL AND candidate_scope.candidate_id = v_candidate_id)
            )
        ), '[]'::jsonb),
        'filter_json', '{}'::jsonb,
        'sort_key', 'STATUS',
        'sort_direction', 'ASC',
        'idempotency_key', 'bank-event-correction:' || v_event_id::text
      );

      -- Make the provider boundary used by PREPARE deterministic. This update
      -- is inside the exception subtransaction: if request creation fails it
      -- rolls back and the outer recovery records BLOCKED instead.
      UPDATE public.pay_bank_transfer_events AS auto_event
      SET correction_disposition = 'AUTO_PROCESSING'
      WHERE auto_event.id = v_event_id;
      v_correction_disposition := 'AUTO_PROCESSING';

      v_request_start_result := public.pay_payment_correction_request_start(
        p_pay_batch_id => v_pay_batch_id,
        p_selection_json => v_selection_json,
        p_reason => 'Automatic provider-confirmed no-money release.',
        p_actor_user_id => p_actor_user_id,
        p_source_bank_event_id => v_event_id,
        p_auto_requested => true,
        p_accepted_resolution_json => jsonb_build_object(
          'contract_version', 2,
          'requested_action', 'NO_MONEY_UNWIND',
          'source', v_provider_event_transport,
          'event_source', v_event_source,
          'provider_key', v_provider_key,
          'provider_event_id', v_provider_event_id,
          'provider_event_key', v_provider_event_key,
          'provider_webhook_receipt_id', v_provider_webhook_receipt_id,
          'provider_transaction_id', v_provider_transaction_id,
          'provider_request_id', v_provider_request_id,
          'mapping_status', v_mapping_status,
          'mapping_method', v_mapping_method,
          'normalised_state', v_normalised_state,
          'classification', v_classification,
          'recommended_action', v_event_required_action,
          'safe_to_auto_apply', v_safe_to_auto_apply,
          'correction_disposition', 'AUTO_PROCESSING',
          'terminal_no_money_evidence', true,
          'signature_valid', COALESCE(v_provider_signature_valid, v_receipt_signature_valid, false),
          'source_bank_event_id', v_event_id
        )
      );

      v_correction_request_id := NULLIF(v_request_start_result->>'correction_request_id', '')::uuid;
      v_correction_disposition := CASE
        WHEN v_correction_request_id IS NULL THEN 'BLOCKED'
        ELSE 'AUTO_PROCESSING'
      END;
      v_exact_mapping_required_blocker := CASE
        WHEN v_correction_request_id IS NULL THEN jsonb_build_object(
          'code', 'AUTO_CORRECTION_REQUEST_NOT_CREATED',
          'message', 'Automatic no-money evidence was retained but the asynchronous correction request was not created.'
        )
        ELSE NULL::jsonb
      END;
      v_final_work_item_totals := jsonb_build_object(
        'total', 0, 'applied', 0, 'skipped', 0, 'blocked', 0,
        'failed_retryable', 0, 'failed_final', 0, 'pending', 0, 'processing', 0,
        'asynchronous', true
      );
    EXCEPTION WHEN OTHERS THEN
      v_correction_disposition := 'BLOCKED';
      v_exact_mapping_required_blocker := jsonb_build_object(
        'code', 'AUTO_CORRECTION_REQUEST_FAILED',
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      );
    END;
  ELSIF v_manual_confirmed_not_paid AND v_suppress_auto_unwind THEN
    v_correction_disposition := 'ACTION_REQUIRED';
    v_event_required_action := 'RELEASE_FAILED_PAYMENT';
    UPDATE public.pay_bank_transfer_events AS manual_no_money_event
    SET mapping_hints_json = COALESCE(manual_no_money_event.mapping_hints_json, '{}'::jsonb)
          || jsonb_build_object(
            'business_code', 'CONFIRMED_NOT_PAID',
            'release_eligible', true,
            'suppress_auto_unwind', true,
            'display_status', 'Not paid — ready to release'
          )
    WHERE manual_no_money_event.id = v_event_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_items AS released_item
    WHERE released_item.status = 'APPLIED'
      AND released_item.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND')
      AND (
        (v_pay_bank_transfer_id IS NOT NULL AND released_item.pay_bank_transfer_id = v_pay_bank_transfer_id)
        OR (v_pay_bank_transfer_id IS NULL AND v_candidate_id IS NOT NULL AND released_item.candidate_id = v_candidate_id)
      )
  ) AND COALESCE(v_event_is_final_paid, false)
  INTO v_paid_after_release;

  IF v_paid_after_release THEN
    v_classification := 'AMBIGUOUS_REVIEW_REQUIRED';
    v_correction_disposition := 'BLOCKED';
    v_event_required_action := 'FINANCE_REVIEW_ONLY';
    v_exact_mapping_required_blocker := jsonb_build_object(
      'code', 'PAID_EVIDENCE_AFTER_RELEASE',
      'message', 'Paid evidence arrived after CloudTMS released the payment reservation. Further payment action is blocked for Finance review.'
    );

    UPDATE public.pay_bank_transfer_events AS late_paid_event
    SET movement_classification = 'AMBIGUOUS_REVIEW_REQUIRED',
        correction_disposition = 'BLOCKED',
        mapping_status = 'MATCHED',
        mapping_hints_json = COALESCE(late_paid_event.mapping_hints_json, '{}'::jsonb)
          || jsonb_build_object(
            'business_code', 'PAID_EVIDENCE_AFTER_RELEASE',
            'review_status', CASE WHEN v_review_acknowledgement THEN 'ACKNOWLEDGED' ELSE 'REQUIRED' END,
            'blocks_new_payment_actions', true,
            'finance_review_only', true
          )
    WHERE late_paid_event.id = v_event_id;

    UPDATE public.pay_bank_transfers AS late_paid_transfer
    SET status = 'COMPLETED', rail_state = 'COMPLETED',
        rail_meta_json = COALESCE(late_paid_transfer.rail_meta_json, '{}'::jsonb)
          || jsonb_build_object(
            'business_code', 'PAID_EVIDENCE_AFTER_RELEASE',
            'bank_event_id', v_event_id,
            'finance_review_only', true
          )
    WHERE late_paid_transfer.id = v_pay_bank_transfer_id;

    UPDATE public.pay_batch_candidates AS late_paid_candidate
    SET settlement_status = 'SETTLED',
        settled_at_utc = COALESCE(late_paid_candidate.settled_at_utc, v_event_time_utc, v_now),
        settled_via = COALESCE(late_paid_candidate.settled_via, 'BANK_EVENT')
    WHERE late_paid_candidate.pay_batch_id = v_pay_batch_id
      AND (
        (v_candidate_id IS NOT NULL AND late_paid_candidate.candidate_id = v_candidate_id)
        OR late_paid_candidate.id IN (
          SELECT item_row.pay_batch_candidate_id
          FROM public.pay_batch_items AS item_row
          WHERE item_row.pay_bank_transfer_id = v_pay_bank_transfer_id
        )
      );

    UPDATE public.pay_payment_correction_work_items AS late_paid_work
    SET status = CASE WHEN late_paid_work.status = 'APPLIED' THEN 'APPLIED' ELSE 'BLOCKED' END,
        last_error = CASE WHEN late_paid_work.status = 'APPLIED' THEN late_paid_work.last_error ELSE 'PAID_EVIDENCE_AFTER_RELEASE' END,
        processed_at_utc = COALESCE(late_paid_work.processed_at_utc, v_now),
        result_json = COALESCE(late_paid_work.result_json, '{}'::jsonb)
          || jsonb_build_object('code', 'PAID_EVIDENCE_AFTER_RELEASE', 'bank_event_id', v_event_id)
    WHERE late_paid_work.pay_batch_id = v_pay_batch_id
      AND (
        late_paid_work.pay_bank_transfer_id = v_pay_bank_transfer_id
        OR (v_candidate_id IS NOT NULL AND late_paid_work.candidate_id = v_candidate_id)
      );

    WITH affected_replacement_batches AS (
      SELECT DISTINCT replacement_candidate.pay_batch_id
      FROM public.pay_batch_candidates AS replacement_candidate
      JOIN public.pay_batch_items AS replacement_item
        ON replacement_item.pay_batch_candidate_id = replacement_candidate.id
       AND COALESCE(replacement_item.is_voided, false) IS NOT TRUE
      WHERE replacement_candidate.pay_batch_id <> v_pay_batch_id
        AND replacement_candidate.candidate_id IN (
          SELECT original_candidate.candidate_id
          FROM public.pay_batch_candidates AS original_candidate
          WHERE original_candidate.pay_batch_id = v_pay_batch_id
            AND (
              (v_candidate_id IS NOT NULL AND original_candidate.candidate_id = v_candidate_id)
              OR original_candidate.id IN (
                SELECT original_item.pay_batch_candidate_id
                FROM public.pay_batch_items AS original_item
                WHERE original_item.pay_bank_transfer_id = v_pay_bank_transfer_id
              )
            )
        )
    )
    UPDATE public.pay_batches AS replacement_batch
    SET status = CASE
          WHEN replacement_batch.status IN ('AUTHORISED_FOR_PAYMENT','SCHEDULED','EXECUTING') THEN 'AWAITING_AUTHORISATION'
          ELSE replacement_batch.status
        END,
        schedule_kind = NULL, scheduled_at_utc = NULL, scheduled_by_user_id = NULL,
        funding_account_ref = NULL, funds_warning_hours_json = NULL,
        freshness_validation_status = 'STALE_POST_SCOPE_FREEZE',
        source_scope_change_generation = COALESCE(replacement_batch.source_scope_change_generation, 0) + 1
    FROM affected_replacement_batches
    WHERE replacement_batch.id = affected_replacement_batches.pay_batch_id;

    UPDATE public.pay_batch_auth_requests AS replacement_auth
    SET state = 'CANCELLED',
        finalised_at_utc = COALESCE(replacement_auth.finalised_at_utc, v_now),
        finalised_by_user_id = COALESCE(replacement_auth.finalised_by_user_id, p_actor_user_id)
    WHERE replacement_auth.state IN ('AWAITING','AUTHORISED')
      AND EXISTS (
        SELECT 1
        FROM public.pay_batch_candidates AS replacement_candidate
        JOIN public.pay_batch_items AS replacement_item
          ON replacement_item.pay_batch_candidate_id = replacement_candidate.id
         AND COALESCE(replacement_item.is_voided, false) IS NOT TRUE
        WHERE replacement_candidate.pay_batch_id = replacement_auth.pay_batch_id
          AND replacement_candidate.candidate_id IN (
            SELECT original_candidate.candidate_id
            FROM public.pay_batch_candidates AS original_candidate
            WHERE original_candidate.pay_batch_id = v_pay_batch_id
              AND (v_candidate_id IS NULL OR original_candidate.candidate_id = v_candidate_id)
          )
      );

    UPDATE public.banking_pay_operation_transfer_scope AS unsafe_scope
    SET provider_submit_ready = false,
        provider_review_required = true,
        provider_unsafe_reason = 'PAID_EVIDENCE_AFTER_RELEASE'
    WHERE EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope_items AS unsafe_item
      JOIN public.pay_batch_candidates AS replacement_candidate
        ON replacement_candidate.id = unsafe_item.pay_batch_candidate_id
      WHERE unsafe_item.transfer_scope_id = unsafe_scope.id
        AND replacement_candidate.candidate_id IN (
          SELECT original_candidate.candidate_id
          FROM public.pay_batch_candidates AS original_candidate
          WHERE original_candidate.pay_batch_id = v_pay_batch_id
            AND (v_candidate_id IS NULL OR original_candidate.candidate_id = v_candidate_id)
        )
    );

    UPDATE public.banking_pay_operations AS unsafe_operation
    SET status = 'REVIEW_REQUIRED', requires_user_action = true,
        result_json = COALESCE(unsafe_operation.result_json, '{}'::jsonb)
          || jsonb_build_object('code', 'PAID_EVIDENCE_AFTER_RELEASE', 'bank_event_id', v_event_id),
        run_after_utc = v_now
    WHERE unsafe_operation.status NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED')
      AND (
       unsafe_operation.pay_batch_id = v_pay_batch_id
       OR EXISTS (
         SELECT 1
         FROM public.pay_batch_candidates AS replacement_candidate
         JOIN public.pay_batch_items AS replacement_item
           ON replacement_item.pay_batch_candidate_id = replacement_candidate.id
          AND COALESCE(replacement_item.is_voided, false) IS NOT TRUE
         WHERE replacement_candidate.pay_batch_id = unsafe_operation.pay_batch_id
           AND replacement_candidate.candidate_id IN (
             SELECT original_candidate.candidate_id
             FROM public.pay_batch_candidates AS original_candidate
             WHERE original_candidate.pay_batch_id = v_pay_batch_id
               AND (v_candidate_id IS NULL OR original_candidate.candidate_id = v_candidate_id)
           )
       )
      );

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id, pay_batch_id, actor_kind, actor_user_id, action,
      action_at_utc, note, before_json, after_json, metadata_json
    )
    SELECT DISTINCT correction_request.id, correction_request.pay_batch_id,
      CASE WHEN p_actor_user_id IS NULL THEN 'SYSTEM' ELSE 'USER' END,
      p_actor_user_id, 'APPLY', v_now,
      'Paid evidence received after reservation release.', NULL, NULL,
      jsonb_build_object(
        'business_code', 'PAID_EVIDENCE_AFTER_RELEASE',
        'review_status', CASE WHEN v_review_acknowledgement THEN 'ACKNOWLEDGED' ELSE 'REQUIRED' END,
        'bank_event_id', v_event_id,
        'pay_bank_transfer_id', v_pay_bank_transfer_id
      )
    FROM public.pay_payment_correction_requests AS correction_request
    JOIN public.pay_payment_correction_items AS correction_item
      ON correction_item.correction_request_id = correction_request.id
     AND correction_item.status = 'APPLIED'
    WHERE (
        correction_item.pay_bank_transfer_id = v_pay_bank_transfer_id
        OR (v_candidate_id IS NOT NULL AND correction_item.candidate_id = v_candidate_id)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_actions AS existing_review_action
        WHERE existing_review_action.correction_request_id = correction_request.id
          AND existing_review_action.metadata_json ->> 'business_code' = 'PAID_EVIDENCE_AFTER_RELEASE'
          AND existing_review_action.metadata_json ->> 'review_status'
              = CASE WHEN v_review_acknowledgement THEN 'ACKNOWLEDGED' ELSE 'REQUIRED' END
          AND existing_review_action.metadata_json ->> 'bank_event_id' = v_event_id::text
      );
  END IF;

  IF v_correction_disposition NOT IN ('NO_CORRECTION_REQUIRED', 'AUTO_PROCESSING') THEN
    v_admin_notice_result := public.pay_payment_return_admin_notice_queue(
      p_notice_kind => CASE
        WHEN v_correction_disposition = 'AMBIGUOUS' THEN 'AUTO_CORRECTION_BLOCKED'
        WHEN v_correction_disposition = 'BLOCKED' THEN 'AUTO_CORRECTION_BLOCKED'
        WHEN v_correction_disposition = 'FAILED' THEN 'AUTO_CORRECTION_BLOCKED'
        WHEN v_correction_disposition = 'AUTO_APPLIED' AND (v_classification IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY') OR v_event_required_action = 'NO_MONEY_UNWIND_AND_RECALCULATE') THEN 'NO_MONEY_UNWIND_APPLIED'
        ELSE v_notice_kind
      END,
      p_pay_batch_id => v_pay_batch_id,
      p_provider_key => COALESCE(v_provider_key, v_batch.rail_provider_snapshot, 'UNKNOWN'),
      p_execution_commit_ref => v_batch.execution_commit_ref,
      p_summary_json => jsonb_build_object(
        'pay_batch_id', v_pay_batch_id,
        'pay_bank_transfer_id', v_pay_bank_transfer_id,
        'bank_event_id', v_event_id,
        'mapping_status', v_mapping_status,
        'mapping_method', v_mapping_method,
        'classification', v_classification,
        'correction_disposition', v_correction_disposition,
        'provider_key', v_provider_key,
        'provider_state', v_provider_state,
        'normalised_state', v_normalised_state,
        'amount', v_amount,
        'currency', v_currency,
        'correction_request_id', CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE v_correction_request_id::text END,
        'request_start_result', COALESCE(v_request_start_result, '{}'::jsonb),
        'expand_result', COALESCE(v_expand_result, '{}'::jsonb),
        'process_result', COALESCE(v_process_result, '{}'::jsonb),
        'final_work_item_totals', COALESCE(v_final_work_item_totals, '{}'::jsonb),
        'blocker', v_exact_mapping_required_blocker
      )
    );

    v_admin_notice_group_id := NULLIF(v_admin_notice_result->>'notice_group_id', '')::uuid;
  END IF;

  UPDATE public.pay_bank_transfer_events AS bank_event_to_update
  SET
    movement_classification = v_classification,
    correction_disposition = v_correction_disposition,
    mapping_method = v_mapping_method
  WHERE bank_event_to_update.id = v_event_id;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_BANK_EVENT_INGEST_RESULT',
    jsonb_build_object(
      'event_id', v_event_id,
      'inserted', v_inserted_event,
      'pay_batch_id', v_pay_batch_id,
      'pay_bank_transfer_id', v_pay_bank_transfer_id,
      'mapping_status', v_mapping_status,
      'mapping_method', v_mapping_method,
      'classification', v_classification,
      'safe_to_auto_apply', v_safe_to_auto_apply,
      'auto_setting', v_auto_setting,
      'correction_disposition', v_correction_disposition,
      'correction_request_id', v_correction_request_id,
      'admin_notice_group_id', v_admin_notice_group_id
    ),
    'pay_payment_correction',
    v_event_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  v_signal_recommendation_json := jsonb_build_object(
    'pay_batch_id', v_pay_batch_id::text,
    'touch_payment_status', true,
    'touch_correction_progress', v_correction_disposition IN ('AUTO_PROCESSING', 'AUTO_APPLIED'),
    'touch_alerts', (
      v_event_is_final_paid IS NOT TRUE
      AND (
        v_correction_disposition IN ('ACTION_REQUIRED', 'AMBIGUOUS', 'BLOCKED', 'FAILED', 'AUTO_PROCESSING')
        OR v_event_required_action IN ('CHECK_PROVIDER_STATUS', 'NO_MONEY_UNWIND_AND_RECALCULATE')
      )
    ),
    'touch_overview', true,
    'change_reason', 'BANK_EVENT_INGEST_RESULT',
    'change_source', 'pay_bank_event_ingest',
    'changed_transfer_ids', CASE WHEN v_pay_bank_transfer_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_pay_bank_transfer_id::text) END,
    'changed_candidate_ids', CASE WHEN v_candidate_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_candidate_id::text) END,
    'changed_pay_batch_item_ids', '[]'::jsonb,
    'alert_candidate_kind', CASE
      WHEN COALESCE(v_existing_transfer_is_final_paid, false) AND v_event_is_terminal_no_money THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
      WHEN v_event_is_final_paid THEN NULL::text
      WHEN v_event_required_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
      WHEN v_event_required_action = 'CHECK_PROVIDER_STATUS' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
      WHEN v_event_required_action = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN CASE WHEN COALESCE(v_auto_setting, false) THEN 'AUTO_UNWIND_PROGRESS' ELSE 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' END
      ELSE NULL::text
    END,
    'alert_candidate_is_success_only', COALESCE(v_event_is_final_paid, false) AND v_event_required_action IS DISTINCT FROM 'AMEND_AND_RECOVER_OVERPAYMENT',
    'provider_failure_reason_code', v_provider_failure_reason_code,
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'source_delivery_id', v_source_delivery_id,
    'source_batch_event_group_key', v_source_batch_event_group_key,
    'change_scope_json', jsonb_build_object(
      'bank_event_id', v_event_id::text,
      'pay_bank_transfer_id', CASE WHEN v_pay_bank_transfer_id IS NULL THEN NULL ELSE v_pay_bank_transfer_id::text END,
      'normalised_state', v_normalised_state,
      'correction_disposition', v_correction_disposition,
      'provider_event_transport', v_provider_event_transport,
      'provider_failure_reason_group', v_provider_failure_reason_group
    ) || v_settlement_intent_json
  ) || v_settlement_intent_json;

  IF v_should_touch_signal THEN
    v_live_signal_result := public.banking_pay_batch_signal_touch(
      v_pay_batch_id,
      'BANK_EVENT_INGEST_RESULT',
      'pay_bank_event_ingest',
      v_signal_recommendation_json->'change_scope_json',
      true,
      v_correction_disposition IN ('AUTO_PROCESSING', 'AUTO_APPLIED'),
      (
        v_event_is_final_paid IS NOT TRUE
        AND (
          v_correction_disposition IN ('ACTION_REQUIRED', 'AMBIGUOUS', 'BLOCKED', 'FAILED', 'AUTO_PROCESSING')

          OR v_event_required_action IN ('CHECK_PROVIDER_STATUS', 'NO_MONEY_UNWIND_AND_RECALCULATE')
        )
      ),
      true
    );
  ELSE
    v_live_signal_result := jsonb_build_object(
      'ok', true,
      'changed', false,
      'deferred', true,
      'signal_recommendation_json', v_signal_recommendation_json
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'event_id', v_event_id,
    'idempotent', NOT v_inserted_event,
    'mapped', v_mapping_status = 'MATCHED',
    'normalised_state', v_normalised_state,
    'manual_resolution_recorded', v_manual_confirmed_not_paid,
    'release_eligible', v_manual_confirmed_not_paid OR (
      v_event_is_terminal_no_money AND v_correction_request_id IS NULL
    ),
    'auto_release_request_prepared', v_auto_setting AND v_safe_to_auto_apply AND v_correction_request_id IS NOT NULL,
    'existing_release_request_id', v_correction_request_id,
    'existing_release_operation_woken', COALESCE((v_request_start_result->>'existing_request')::boolean, false),
    'paid_after_release', v_paid_after_release,
    'requires_user_action', v_paid_after_release OR v_correction_disposition IN ('ACTION_REQUIRED', 'AMBIGUOUS', 'BLOCKED', 'FAILED'),
    'display_status', CASE
      WHEN v_paid_after_release THEN 'Paid — evidence received after release'
      WHEN v_manual_confirmed_not_paid THEN 'Not paid — ready to release'
      WHEN v_correction_disposition = 'AUTO_PROCESSING' THEN 'Failed payment release is being prepared'
      WHEN v_mapping_status <> 'MATCHED' THEN 'Payment status needs review'
      ELSE 'Payment status updated'
    END,
    'display_message', CASE
      WHEN v_paid_after_release THEN 'The bank confirmed this payment after CloudTMS released its payment reservation. CloudTMS has blocked any further payment action and retained both histories for Finance review.'
      WHEN v_manual_confirmed_not_paid THEN 'The payment is confirmed not paid and can now be released as a separate authorised action.'
      WHEN v_correction_disposition = 'AUTO_PROCESSING' THEN 'CloudTMS is preparing the provider-confirmed failed-payment release asynchronously.'
      WHEN v_mapping_status <> 'MATCHED' THEN 'The provider evidence was retained and needs review before a financial action can continue.'
      ELSE 'The provider payment status was recorded.'
    END,
    'inserted', v_inserted_event,
    'mapping_status', v_mapping_status,
    'mapping_method', v_mapping_method,
    'classification', v_classification,
    'correction_disposition', v_correction_disposition,
    'correction_request_id', v_correction_request_id,
    'admin_notice_group_id', v_admin_notice_group_id,
    'provider_failure_reason_code', v_provider_failure_reason_code,
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'provider_failure_reason_label', v_provider_failure_reason_label,
    'live_signal', v_live_signal_result,
    'signal_recommendation_json', v_signal_recommendation_json,
    'selection_json', v_selection_json,
    'classification_result', v_classification_result,
    'auto_apply', jsonb_build_object(
      'auto_setting', v_auto_setting,
      'safe_to_auto_apply', v_safe_to_auto_apply,
      'request_start_result', v_request_start_result,
      'expand_result', v_expand_result,
      'process_result', v_process_result,
      'final_work_item_totals', v_final_work_item_totals,
      'status', v_correction_disposition,
      'requires_user_action', v_correction_disposition IN ('ACTION_REQUIRED', 'AMBIGUOUS', 'BLOCKED', 'FAILED'),
      'blocker', v_exact_mapping_required_blocker
    ),
    'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
    'carry_forward_mark_consumed_result', COALESCE(v_carry_forward_mark_result, '{}'::jsonb),
    'money_movement_classification', jsonb_build_object(
      'cash_state', v_event_cash_state,
      'is_final_money_moved', v_event_is_final_paid,
      'is_terminal_no_money', v_event_is_terminal_no_money,
      'is_pending_non_final', v_event_is_pending_non_final,
      'normalised_state', v_normalised_state,
      'reason', COALESCE(v_money_movement_classification.reason, NULL::text)
    ),
    'grouped_alert_summary_impact', jsonb_build_object(
      'alert_kind', CASE
        WHEN COALESCE(v_existing_transfer_is_final_paid, false) AND v_event_is_terminal_no_money THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
        WHEN v_event_is_final_paid THEN NULL::text
        WHEN v_event_required_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
        WHEN v_event_required_action = 'CHECK_PROVIDER_STATUS' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
        WHEN v_event_required_action = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN CASE WHEN COALESCE(v_auto_setting, false) THEN 'AUTO_UNWIND_PROGRESS' ELSE 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' END
        ELSE NULL::text
      END,
      'pay_batch_id', CASE WHEN v_pay_batch_id IS NULL THEN NULL ELSE v_pay_batch_id::text END,
      'pay_bank_transfer_id', CASE WHEN v_pay_bank_transfer_id IS NULL THEN NULL ELSE v_pay_bank_transfer_id::text END,
      'link_target', 'CURRENT_PAYMENT_STATUS'
    ),
    'policy_x_checked', true
  ) || v_settlement_intent_json || jsonb_build_object(
    'continuations', (
      SELECT COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'required', true,
            'operation_id', continuation_item.value->>'operation_id',
            'operation_type', continuation_item.value->>'operation_type',
            'pay_batch_id', continuation_item.value->>'pay_batch_id',
            'root_operation_id', continuation_item.value->>'root_operation_id',
            'phase', continuation_item.value->>'phase',
            'run_after_utc', continuation_item.value->>'run_after_utc',
            'reason', continuation_item.value->>'reason',
            'successor_relation', continuation_item.value->>'successor_relation',
            'requires_user_action', false,
            'terminal', false
          )
          ORDER BY continuation_item.ordinality
        ),
        '[]'::jsonb
      )
      FROM (
        SELECT raw_item.value, raw_item.ordinality
        FROM jsonb_array_elements(jsonb_build_array(
          v_request_start_result->'continuation',
          v_settlement_apply_result->'continuation'
        )) WITH ORDINALITY AS raw_item(value, ordinality)
        WHERE jsonb_typeof(raw_item.value) = 'object'
          AND COALESCE((raw_item.value->>'required')::boolean, false)
          AND COALESCE((raw_item.value->>'terminal')::boolean, false) IS NOT TRUE
          AND COALESCE((raw_item.value->>'requires_user_action')::boolean, false) IS NOT TRUE
        ORDER BY raw_item.ordinality
        LIMIT 4
      ) AS continuation_item
    )
  );

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_BANK_EVENT_INGEST_ERROR',
      jsonb_build_object(
        'event_keys', COALESCE(
          (
            SELECT jsonb_agg(event_key ORDER BY event_key)
            FROM jsonb_object_keys(COALESCE(p_event_json, '{}'::jsonb)) AS event_key
          ),
          '[]'::jsonb
        ),
        'event_hash', CASE
          WHEN p_event_json IS NULL THEN NULL::text
          ELSE encode(extensions.digest(convert_to(p_event_json::text, 'UTF8'), 'sha256'), 'hex')
        END,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      'BANK_EVENT_INGEST',
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

-- pay_bank_transfer_execution_classify(uuid,text,uuid,boolean,text)
CREATE OR REPLACE FUNCTION public.pay_bank_transfer_execution_classify(p_pay_batch_id uuid, p_pay_channel_scope text DEFAULT 'ALL'::text, p_operation_id uuid DEFAULT NULL::uuid, p_include_unscoped_transfers boolean DEFAULT true, p_action_context text DEFAULT NULL::text)
 RETURNS TABLE(pay_bank_transfer_id uuid, pay_batch_id uuid, pay_channel text, transfer_group_key text, scope_id uuid, scope_operation_id uuid, scope_status text, scope_request_id text, status_upper text, rail_state_upper text, amount numeric, currency text, has_route_ready boolean, has_local_prepare_identity boolean, has_provider_submission_evidence boolean, has_provider_event_evidence boolean, has_provider_attempt_without_external_id boolean, has_operation_submit_attempt boolean, has_ambiguous_external_evidence boolean, is_failed_or_blocked boolean, is_terminal_or_completed boolean, evidence_classification text, is_authorisation_ready boolean, is_unattempted_submit_eligible boolean, is_safe_local_cleanup boolean, is_canonical_pending_status boolean, has_auth_prepared_scope boolean, has_different_operation_scope boolean, has_stale_auth_request_evidence boolean, auth_request_id uuid, auth_request_state text, auth_request_operation_id uuid, has_same_operation_active_auth_request boolean, has_other_operation_active_auth_request boolean, has_cancellable_local_auth_request boolean, has_non_cancellable_auth_request boolean, has_authorised_auth_without_provider_submission boolean, has_auth_request_provider_risk boolean, auth_request_unsafe_reason text, unsafe_reason text, has_same_operation_authorised_auth_request boolean, has_pending_authorisation_auth_request boolean, is_provider_submit_ready boolean, provider_submit_unsafe_reason text, has_provider_submit_blocker boolean, provider_failure_reason_code text, provider_failure_reason_group text, provider_failure_reason_label text, is_success_only boolean, should_touch_payment_status boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := 'ALL';
  v_action_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_action_context, '')), ''), '-', '_'));
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;


  IF v_action_context IS NULL THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_REQUIRED',
              'message', 'pay_bank_transfer_execution_classify requires an explicit action/diagnostic context.'
            )::text;
  END IF;

  IF v_action_context IN (
    'PAY_BATCHES_LIST',
    'BATCH_LIST',
    'LIST',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'OPERATION_GET',
    'OPERATION_PROGRESS',
    'PROGRESS_POLLING',
    'WORKER_PROOF',
    'OPERATION_WORKER_PROOF',
    'EXECUTION_WORKER_PROOF',
    'EXECUTION_HOT_PATH',
    'PAY_EXECUTE_BANK_HOT_PATH'
  ) THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_ALLOWED',
              'context', v_action_context,
              'message', 'Live transfer execution classification is blocked from list, bootstrap, Overview, operation GET/progress, and worker proof paths. Execution must use persisted operation proofs and counters.'
            )::text;
  END IF;

  IF v_action_context NOT IN (
    'CURRENT_PAYMENT_STATUS',
    'CURRENT_PAYMENT_STATUS_TAB',
    'PAYMENT_STATUS_TAB',
    'PAYMENT_ISSUES_TAB',
    'PAYMENT_ISSUE_REVIEW',
    'CANCELLATION_ACTION',
    'CANCEL_PAYMENT_ACTION',
    'CORRECTION_REVIEW',
    'CORRECTION_ACTION',
    'PROVIDER_DIAGNOSTIC_TAB',
    'PROVIDER_DIAGNOSTIC_ACTION',
    'AUTHORISATION_ACTION',
    'AUTHORIZATION_ACTION',
    'PREPARE_ACTION',
    'SCHEDULE_ACTION',
    'USER_TRIGGERED_DIAGNOSTIC',
    'EXPLICIT_DIAGNOSTIC'
  ) THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_EXPLICIT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_EXPLICIT',
              'context', v_action_context,
              'message', 'Live transfer execution classification is only allowed from explicit action or diagnostic flows.'
            )::text;
  END IF;

  v_scope := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  IF v_scope = '' THEN
    v_scope := 'ALL';
  END IF;

  RETURN QUERY
  WITH batch_context AS (
    SELECT
      batch_rows.id AS pay_batch_id,
      batch_rows.status AS batch_status,
      batch_rows.schedule_kind AS batch_schedule_kind,
      batch_rows.scheduled_at_utc AS batch_scheduled_at_utc,
      batch_rows.cancelled_at_utc AS batch_cancelled_at_utc,
      batch_rows.execution_commit_state AS batch_execution_commit_state
    FROM public.pay_batches AS batch_rows
    WHERE batch_rows.id = p_pay_batch_id
  ), latest_auth_request AS (
    SELECT
      auth_request_rows.id AS auth_request_id,
      auth_request_rows.state AS auth_request_state,
      CASE
        WHEN NULLIF(btrim(COALESCE(auth_request_rows.execution_intent_json->>'operation_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (auth_request_rows.execution_intent_json->>'operation_id')::uuid
        ELSE NULL::uuid
      END AS auth_request_operation_id,
      ROW_NUMBER() OVER (ORDER BY auth_request_rows.created_at_utc DESC NULLS LAST, auth_request_rows.id DESC) AS auth_request_ordinal
    FROM public.pay_batch_auth_requests AS auth_request_rows
    WHERE auth_request_rows.pay_batch_id = p_pay_batch_id
      AND upper(btrim(COALESCE(auth_request_rows.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'PENDING_AUTHORIZATION', 'AUTHORISED', 'AUTHORIZED')
  ), transfer_rows AS (
    SELECT
      transfer_source_rows.id AS pay_bank_transfer_id,
      transfer_source_rows.pay_batch_id,
      transfer_source_rows.pay_channel,
      transfer_source_rows.transfer_group_key,
      latest_scope_rows.scope_id,
      latest_scope_rows.scope_operation_id,
      latest_scope_rows.scope_status,
      latest_scope_rows.scope_request_id,
      upper(btrim(COALESCE(transfer_source_rows.status, ''))) AS status_upper,
      upper(btrim(COALESCE(transfer_source_rows.rail_state, ''))) AS rail_state_upper,
      transfer_source_rows.amount,
      transfer_source_rows.currency,
      transfer_source_rows.request_id,
      transfer_source_rows.payment_reference,
      transfer_source_rows.rail_tx_id,
      COALESCE(transfer_source_rows.rail_meta_json, '{}'::jsonb) AS rail_meta_json,
      transfer_source_rows.completed_at_utc,
      transfer_source_rows.failed_reason,
      transfer_source_rows.payee_name,
      transfer_source_rows.sort_code,
      transfer_source_rows.account_number,
      transfer_source_rows.account_type
    FROM public.pay_bank_transfers AS transfer_source_rows
    JOIN batch_context AS batch_context_rows
      ON batch_context_rows.pay_batch_id = transfer_source_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        scope_rows.id AS scope_id,
        scope_rows.operation_id AS scope_operation_id,
        scope_rows.status AS scope_status,
        scope_rows.request_id AS scope_request_id
      FROM public.banking_pay_operation_transfer_scope AS scope_rows
      WHERE scope_rows.pay_batch_id = transfer_source_rows.pay_batch_id
        AND scope_rows.pay_channel = transfer_source_rows.pay_channel
        AND (
          scope_rows.pay_bank_transfer_id = transfer_source_rows.id
          OR (
            scope_rows.pay_bank_transfer_id IS NULL
            AND NULLIF(btrim(COALESCE(scope_rows.transfer_group_key, '')), '') IS NOT NULL
            AND scope_rows.transfer_group_key = transfer_source_rows.transfer_group_key
          )
        )
        AND (p_operation_id IS NULL OR scope_rows.operation_id = p_operation_id)
      ORDER BY scope_rows.updated_at_utc DESC NULLS LAST, scope_rows.created_at_utc DESC NULLS LAST, scope_rows.id DESC
      LIMIT 1
    ) AS latest_scope_rows ON true
    WHERE transfer_source_rows.pay_batch_id = p_pay_batch_id
      AND (v_scope IN ('ALL', 'ANY', '*') OR upper(btrim(COALESCE(transfer_source_rows.pay_channel, ''))) = v_scope)
      AND (
        COALESCE(p_include_unscoped_transfers, true)
        OR p_operation_id IS NULL
        OR latest_scope_rows.scope_operation_id = p_operation_id
      )
  ), scope_without_transfer_rows AS (
    SELECT
      NULL::uuid AS pay_bank_transfer_id,
      scope_source_rows.pay_batch_id,
      scope_source_rows.pay_channel,
      scope_source_rows.transfer_group_key,
      scope_source_rows.id AS scope_id,
      scope_source_rows.operation_id AS scope_operation_id,
      scope_source_rows.status AS scope_status,
      scope_source_rows.request_id AS scope_request_id,
      upper(btrim(COALESCE(scope_source_rows.status, ''))) AS status_upper,
      NULL::text AS rail_state_upper,
      scope_source_rows.amount,
      scope_source_rows.currency,
      scope_source_rows.request_id,
      scope_source_rows.payment_reference,
      NULL::text AS rail_tx_id,
      jsonb_build_object(
        'scope_id', scope_source_rows.id::text,
        'operation_id', scope_source_rows.operation_id::text,
        'scope_status', scope_source_rows.status,
        'local_scope_row', true
      ) AS rail_meta_json,
      NULL::timestamptz AS completed_at_utc,
      NULL::text AS failed_reason,
      scope_source_rows.payee_name,
      scope_source_rows.sort_code,
      scope_source_rows.account_number,
      scope_source_rows.account_type
    FROM public.banking_pay_operation_transfer_scope AS scope_source_rows
    WHERE scope_source_rows.pay_batch_id = p_pay_batch_id
      AND scope_source_rows.pay_bank_transfer_id IS NULL
      AND (v_scope IN ('ALL', 'ANY', '*') OR upper(btrim(COALESCE(scope_source_rows.pay_channel, ''))) = v_scope)
      AND (p_operation_id IS NULL OR scope_source_rows.operation_id = p_operation_id)
  ), source_rows AS (
    SELECT * FROM transfer_rows
    UNION ALL
    SELECT * FROM scope_without_transfer_rows
  ), classified_rows AS (
    SELECT
      source_rows.*,
      batch_context_rows.batch_status,
      batch_context_rows.batch_schedule_kind,
      batch_context_rows.batch_scheduled_at_utc,
      batch_context_rows.batch_cancelled_at_utc,
      COALESCE(provider_evidence_rows.evidence_class, 'LOCAL_PREPARED_ONLY') AS provider_evidence_class,
      COALESCE(provider_evidence_rows.provider_submitted, false) AS provider_submitted,
      COALESCE(provider_evidence_rows.provider_request_sent, false) AS provider_request_sent,
      COALESCE(provider_evidence_rows.provider_response_present, false) AS provider_response_present,
      COALESCE(provider_evidence_rows.provider_event_present, false) AS provider_event_present,
      COALESCE(provider_evidence_rows.provider_external_id_present, false) AS provider_external_id_present,
      COALESCE(provider_evidence_rows.local_prepared_only, source_rows.pay_bank_transfer_id IS NOT NULL OR source_rows.scope_id IS NOT NULL) AS local_prepared_only,
      COALESCE(provider_evidence_rows.cash_state, 'NO_TRANSFER_EVIDENCE') AS provider_cash_state,
      provider_evidence_rows.blocker_code AS provider_blocker_code,
      COALESCE(provider_evidence_rows.support_details_json, '{}'::jsonb) AS provider_support_details_json,
      COALESCE(rail_classification_rows.cash_state, 'UNKNOWN') AS rail_cash_state,
      COALESCE(rail_classification_rows.is_final_money_moved, false) AS rail_is_final_money_moved,
      COALESCE(rail_classification_rows.is_terminal_no_money, false) AS rail_is_terminal_no_money,
      COALESCE(rail_classification_rows.is_pending_non_final, false) AS rail_is_pending_non_final,
      auth_rows.auth_request_id,
      auth_rows.auth_request_state,
      auth_rows.auth_request_operation_id
    FROM source_rows
    JOIN batch_context AS batch_context_rows
      ON batch_context_rows.pay_batch_id = source_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT evidence_rows.*
      FROM public._pay_bank_transfer_provider_evidence_classify(
        source_rows.pay_batch_id,
        source_rows.pay_bank_transfer_id,
        CASE
          WHEN source_rows.pay_bank_transfer_id IS NOT NULL THEN jsonb_build_object('scope_type', 'TRANSFER', 'pay_bank_transfer_id', source_rows.pay_bank_transfer_id::text)
          ELSE jsonb_build_object('scope_type', 'BATCH')
        END,
        p_operation_id
      ) AS evidence_rows
      WHERE source_rows.pay_bank_transfer_id IS NOT NULL
      LIMIT 1
    ) AS provider_evidence_rows ON true
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      source_rows.status_upper,
      source_rows.rail_state_upper,
      source_rows.rail_meta_json,
      source_rows.rail_meta_json
    ) AS rail_classification_rows ON true
    LEFT JOIN LATERAL (
      SELECT latest_auth_request.auth_request_id, latest_auth_request.auth_request_state, latest_auth_request.auth_request_operation_id
      FROM latest_auth_request
      WHERE latest_auth_request.auth_request_ordinal = 1
      LIMIT 1
    ) AS auth_rows ON true
  ), lifecycle_rows AS (
    SELECT
      classified_rows.*,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_rows
        WHERE correction_item_rows.pay_batch_id = classified_rows.pay_batch_id
          AND correction_item_rows.correction_item_kind = 'PRE_BANK_CANCEL'
          AND upper(btrim(COALESCE(correction_item_rows.status, ''))) = 'APPLIED'
          AND (
            correction_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            OR EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS item_rows
              WHERE item_rows.pay_batch_candidate_id = correction_item_rows.pay_batch_candidate_id
                AND item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            )
          )
      ) AS has_applied_pre_bank_cancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS unwind_work_item_rows
        JOIN public.pay_payment_correction_requests AS unwind_request_rows
          ON unwind_request_rows.id = unwind_work_item_rows.correction_request_id
        WHERE unwind_request_rows.pay_batch_id = classified_rows.pay_batch_id
          AND upper(btrim(COALESCE(unwind_request_rows.correction_kind, ''))) IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
          AND upper(btrim(COALESCE(unwind_work_item_rows.status, ''))) IN ('APPLIED','DONE','COMPLETE','COMPLETED')
          AND (
            unwind_work_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            OR EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS unwind_item_rows
              WHERE unwind_item_rows.pay_batch_candidate_id = unwind_work_item_rows.pay_batch_candidate_id
                AND unwind_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            )
          )
      ) AS has_applied_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.banking_pay_operations AS operation_rows
        WHERE operation_rows.pay_batch_id = classified_rows.pay_batch_id
          AND (
            upper(btrim(COALESCE(operation_rows.status, ''))) = 'RETRY_LATER'
            OR upper(btrim(COALESCE(operation_rows.phase, ''))) = 'RETRY_LATER'
            OR upper(NULLIF(btrim(COALESCE(operation_rows.error_json->>'code', '')), '')) IN ('PROVIDER_OUTAGE_RETRY_LATER', 'BANK_UNAVAILABLE', 'PROVIDER_UNAVAILABLE', 'RETRY_LATER')
            OR upper(NULLIF(btrim(COALESCE(operation_rows.result_json->>'code', '')), '')) IN ('PROVIDER_OUTAGE_RETRY_LATER', 'BANK_UNAVAILABLE', 'PROVIDER_UNAVAILABLE', 'RETRY_LATER')
            OR upper(NULLIF(btrim(COALESCE(operation_rows.progress_json->>'retry_state', '')), '')) = 'RETRY_LATER'
          )
      ) AS has_retry_later_state
    FROM classified_rows
  ), final_rows AS (
    SELECT
      lifecycle_rows.*,
      CASE
        WHEN lifecycle_rows.provider_cash_state = 'FINAL_PAID' OR lifecycle_rows.rail_is_final_money_moved THEN 'PAID_OR_SETTLED'
        WHEN lifecycle_rows.provider_evidence_class = 'PROVIDER_OUTCOME_UNKNOWN'
          OR (lifecycle_rows.provider_submitted AND lifecycle_rows.provider_cash_state = 'UNKNOWN')
          OR (
            NOT lifecycle_rows.provider_submitted
            AND lifecycle_rows.rail_cash_state = 'UNKNOWN'
            AND (
              lifecycle_rows.status_upper IN ('COMMITTED', 'EXECUTED')
              OR lifecycle_rows.rail_state_upper IN ('COMMITTED', 'EXECUTED')
            )
          ) THEN 'PROVIDER_OUTCOME_UNKNOWN'
        WHEN lifecycle_rows.provider_submitted AND lifecycle_rows.provider_cash_state = 'PENDING_NON_FINAL' THEN 'PROVIDER_SUBMITTED_PENDING'
        WHEN lifecycle_rows.has_applied_pre_bank_cancel
          OR (
            NOT lifecycle_rows.provider_submitted
            AND (
              upper(COALESCE(lifecycle_rows.batch_status, '')) IN ('CANCELLED', 'CANCELED')
              OR lifecycle_rows.batch_cancelled_at_utc IS NOT NULL
            )
          )
          OR (
            NOT lifecycle_rows.provider_submitted
            AND lifecycle_rows.status_upper IN (
              'CANCELLED',
              'CANCELED',
              'CANCELLED_BEFORE_BANK_SUBMISSION',
              'CANCELED_BEFORE_BANK_SUBMISSION',
              'LOCALLY_CANCELLED',
              'LOCAL_CANCELLED',
              'VOIDED'
            )
          ) THEN 'CANCELLED_BEFORE_BANK_SUBMISSION'
        WHEN lifecycle_rows.has_applied_no_money_unwind THEN 'FINANCIALS_REWOUND'
        WHEN lifecycle_rows.provider_submitted
          AND (
            lifecycle_rows.provider_cash_state = 'TERMINAL_NO_MONEY'
            OR lifecycle_rows.rail_is_terminal_no_money
          ) THEN
          CASE WHEN lifecycle_rows.status_upper IN ('CANCELLED', 'CANCELED') OR lifecycle_rows.rail_state_upper IN ('CANCELLED', 'CANCELED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN 'PROVIDER_CANCELLED_NO_MONEY' ELSE 'PROVIDER_FAILED_NO_MONEY' END
        WHEN lifecycle_rows.has_retry_later_state AND NOT lifecycle_rows.provider_submitted THEN 'PROVIDER_OUTAGE_RETRY_LATER'
        WHEN upper(COALESCE(lifecycle_rows.batch_status, '')) = 'SCHEDULED' OR lifecycle_rows.batch_scheduled_at_utc IS NOT NULL OR lifecycle_rows.status_upper = 'SCHEDULED' THEN 'SCHEDULED_LOCAL_NOT_SENT'
        ELSE 'LOCAL_PREPARED_NOT_SENT'
      END AS derived_lifecycle_state
    FROM lifecycle_rows
  )
  SELECT
    final_rows.pay_bank_transfer_id,
    final_rows.pay_batch_id,
    final_rows.pay_channel,
    final_rows.transfer_group_key,
    final_rows.scope_id,
    final_rows.scope_operation_id,
    final_rows.scope_status,
    final_rows.scope_request_id,
    final_rows.status_upper,
    final_rows.rail_state_upper,
    final_rows.amount,
    final_rows.currency,
    (
      COALESCE(final_rows.amount, 0) > 0
      AND NULLIF(btrim(COALESCE(final_rows.currency, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.payee_name, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.sort_code, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.account_number, '')), '') IS NOT NULL
    ) AS has_route_ready,
    final_rows.local_prepared_only,
    final_rows.provider_submitted,
    final_rows.provider_event_present,
    (final_rows.provider_request_sent AND NOT final_rows.provider_external_id_present) AS has_provider_attempt_without_external_id,
    COALESCE(NULLIF(final_rows.provider_support_details_json->>'operation_submit_attempt_count', '')::integer, 0) > 0 AS has_operation_submit_attempt,
    final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' AS has_ambiguous_external_evidence,
    final_rows.derived_lifecycle_state IN ('PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY') AS is_failed_or_blocked,
    final_rows.derived_lifecycle_state IN ('PAID_OR_SETTLED', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'FINANCIALS_REWOUND') AS is_terminal_or_completed,
    final_rows.derived_lifecycle_state AS evidence_classification,
    (
      final_rows.auth_request_state IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
    ) AS is_authorisation_ready,
    (
      final_rows.auth_request_state IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')
    ) AS is_unattempted_submit_eligible,
    (NOT final_rows.provider_submitted AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')) AS is_safe_local_cleanup,
    final_rows.status_upper IN ('', 'PENDING', 'PREPARED', 'READY', 'SCHEDULED', 'QUEUED', 'SUBMITTED', 'SENT', 'PROCESSING', 'ACCEPTED') AS is_canonical_pending_status,
    final_rows.auth_request_id IS NOT NULL AS has_auth_prepared_scope,
    (final_rows.auth_request_operation_id IS NOT NULL AND p_operation_id IS NOT NULL AND final_rows.auth_request_operation_id <> p_operation_id) AS has_different_operation_scope,
    false AS has_stale_auth_request_evidence,
    final_rows.auth_request_id,
    final_rows.auth_request_state,
    final_rows.auth_request_operation_id,
    (final_rows.auth_request_id IS NOT NULL AND (p_operation_id IS NULL OR final_rows.auth_request_operation_id IS NULL OR final_rows.auth_request_operation_id = p_operation_id)) AS has_same_operation_active_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND p_operation_id IS NOT NULL AND final_rows.auth_request_operation_id IS NOT NULL AND final_rows.auth_request_operation_id <> p_operation_id) AS has_other_operation_active_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND NOT final_rows.provider_submitted) AS has_cancellable_local_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND final_rows.provider_submitted) AS has_non_cancellable_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED') AND NOT final_rows.provider_submitted) AS has_authorised_auth_without_provider_submission,
    final_rows.provider_submitted AS has_auth_request_provider_risk,
    CASE WHEN final_rows.provider_submitted THEN 'Provider evidence exists; local authorisation cleanup must not treat this as not sent.' ELSE NULL::text END AS auth_request_unsafe_reason,
    CASE
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown; check provider before retry, cancel, or unwind.'
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_SUBMITTED_PENDING' THEN 'Provider submission is pending; provider state must be checked before unwind.'
      WHEN final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED' THEN 'Payment is paid/settled; use recovery workflow rather than no-money unwind.'
      WHEN final_rows.derived_lifecycle_state = 'FINANCIALS_REWOUND' THEN 'Payment financials have already been rewound; do not submit, cancel, or unwind again.'
      ELSE NULL::text
    END AS unsafe_reason,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED') AND (p_operation_id IS NULL OR final_rows.auth_request_operation_id IS NULL OR final_rows.auth_request_operation_id = p_operation_id)) AS has_same_operation_authorised_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'PENDING_AUTHORIZATION')) AS has_pending_authorisation_auth_request,
    (
      final_rows.auth_request_id IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')
      AND COALESCE(final_rows.amount, 0) > 0
    ) AS is_provider_submit_ready,
    CASE
      WHEN final_rows.provider_submitted THEN 'PROVIDER_SUBMISSION_ALREADY_EXISTS'
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER'
      WHEN final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED' THEN 'PAYMENT_ALREADY_PAID_OR_SETTLED'
      WHEN final_rows.derived_lifecycle_state IN ('PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY') THEN 'TERMINAL_NO_MONEY_REWIND_REQUIRED'
      WHEN final_rows.derived_lifecycle_state = 'FINANCIALS_REWOUND' THEN 'FINANCIALS_ALREADY_REWOUND'
      WHEN final_rows.auth_request_id IS NULL THEN 'NO_AUTHORISED_PAYMENT_AUTH_REQUEST'
      WHEN upper(btrim(COALESCE(final_rows.auth_request_state, ''))) NOT IN ('AUTHORISED', 'AUTHORIZED') THEN 'PAYMENT_AUTHORISATION_NOT_COMPLETE'
      ELSE NULL::text
    END AS provider_submit_unsafe_reason,
    (
      final_rows.provider_submitted
      OR final_rows.derived_lifecycle_state IN ('PROVIDER_OUTCOME_UNKNOWN', 'PAID_OR_SETTLED', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'FINANCIALS_REWOUND')
      OR final_rows.auth_request_id IS NULL
      OR upper(btrim(COALESCE(final_rows.auth_request_state, ''))) NOT IN ('AUTHORISED', 'AUTHORIZED')
    ) AS has_provider_submit_blocker,
    (
      SELECT latest_event.provider_failure_reason_code
      FROM public.pay_bank_transfer_events AS latest_event
      WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
        AND latest_event.provider_failure_reason_code IS NOT NULL
      ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
      LIMIT 1
    ) AS provider_failure_reason_code,
    COALESCE(
      (
        SELECT latest_event.provider_failure_reason_group
        FROM public.pay_bank_transfer_events AS latest_event
        WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
          AND latest_event.provider_failure_reason_group IS NOT NULL
        ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
        LIMIT 1
      ),
      public._banking_provider_failure_reason_normalise(
        COALESCE(final_rows.rail_meta_json->>'provider_key', final_rows.rail_meta_json->>'rail_provider', NULL::text),
        COALESCE(final_rows.rail_state_upper, final_rows.status_upper),
        COALESCE(final_rows.failed_reason, final_rows.provider_support_details_json->>'provider_error_code'),
        COALESCE(final_rows.provider_support_details_json->>'provider_error_message_redacted', final_rows.failed_reason),
        COALESCE(final_rows.rail_meta_json, '{}'::jsonb)
      )->>'failure_reason_group'
    ) AS provider_failure_reason_group,
    COALESCE(
      (
        SELECT public._banking_provider_failure_reason_normalise(
          latest_event.provider_key,
          COALESCE(latest_event.provider_state, latest_event.normalised_state),
          latest_event.provider_failure_reason_code,
          COALESCE(latest_event.raw_payload->>'provider_failure_reason_text', latest_event.raw_payload->>'failure_reason', latest_event.raw_payload->>'reason', latest_event.raw_payload->>'message'),
          COALESCE(latest_event.raw_payload, '{}'::jsonb)
        )->>'failure_reason_label'
        FROM public.pay_bank_transfer_events AS latest_event
        WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
        ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
        LIMIT 1
      ),
      public._banking_provider_failure_reason_normalise(
        COALESCE(final_rows.rail_meta_json->>'provider_key', final_rows.rail_meta_json->>'rail_provider', NULL::text),
        COALESCE(final_rows.rail_state_upper, final_rows.status_upper),
        COALESCE(final_rows.failed_reason, final_rows.provider_support_details_json->>'provider_error_code'),
        COALESCE(final_rows.provider_support_details_json->>'provider_error_message_redacted', final_rows.failed_reason),
        COALESCE(final_rows.rail_meta_json, '{}'::jsonb)
      )->>'failure_reason_label'
    ) AS provider_failure_reason_label,
    (final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED') AS is_success_only,
    (final_rows.pay_bank_transfer_id IS NOT NULL OR final_rows.scope_id IS NOT NULL) AS should_touch_payment_status
  FROM final_rows
  ORDER BY final_rows.pay_channel, final_rows.transfer_group_key NULLS LAST, final_rows.pay_bank_transfer_id NULLS LAST, final_rows.scope_id NULLS LAST;
END;
$function$;

-- pay_bank_transfers_apply_rail_updates(uuid,jsonb,uuid,uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_bank_transfers_apply_rail_updates(p_pay_batch_id uuid, p_updates jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_transfer_ids jsonb DEFAULT NULL::jsonb, p_chunk_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_effective_operation_id uuid := p_operation_id;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_update_limit integer := 100;
  v_input_count integer := 0;
  v_after_filter_count integer := 0;
  v_matched_count integer := 0;
  v_unmatched_count integer := 0;
  v_duplicate_match_count integer := 0;
  v_updated_count integer := 0;
  v_event_count integer := 0;
  v_accepted_count integer := 0;
  v_failed_count integer := 0;
  v_unknown_count integer := 0;
  v_review_required_count integer := 0;
  v_operation_review_required boolean := false;
  v_last_provider_message text := NULL::text;
  v_signal_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_updates IS NULL OR jsonb_typeof(p_updates) <> 'array' THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_UPDATES_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_UPDATES_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  v_input_count := jsonb_array_length(p_updates);

  IF v_input_count > v_update_limit THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_TOO_MANY_UPDATES'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_TOO_MANY_UPDATES', 'pay_batch_id', p_pay_batch_id::text, 'update_count', v_input_count, 'limit', v_update_limit)::text;
  END IF;

  IF p_operation_id IS NULL AND p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_SCOPE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_SCOPE_REQUIRED',
        'pay_batch_id', p_pay_batch_id::text,
        'message', 'Rail updates must be scoped by a Banking Pay operation id and/or provider chunk id. Transfer-id-only rail update scope is disabled for the execution hot path.'
      )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    PERFORM 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_ACTOR_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_ACTOR_NOT_FOUND', 'actor_user_id', p_actor_user_id::text)::text;
    END IF;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_BATCH_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
    END IF;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT chunk_row.*
    INTO v_chunk_row
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.id = p_chunk_id
      AND (p_operation_id IS NULL OR chunk_row.operation_id = p_operation_id)
      AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_CHUNK_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_CHUNK_NOT_FOUND', 'chunk_id', p_chunk_id::text, 'operation_id', CASE WHEN v_effective_operation_id IS NULL THEN NULL ELSE v_effective_operation_id::text END)::text;
    END IF;

    IF v_effective_operation_id IS NULL THEN
      v_effective_operation_id := v_chunk_row.operation_id;

      SELECT operation_row.*
      INTO v_operation_row
      FROM public.banking_pay_operations AS operation_row
      WHERE operation_row.id = v_effective_operation_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_NOT_FOUND'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_NOT_FOUND', 'operation_id', v_effective_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
      END IF;

      IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
        RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_BATCH_MISMATCH'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_OPERATION_BATCH_MISMATCH', 'operation_id', v_effective_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
      END IF;
    END IF;
  END IF;

  IF p_transfer_ids IS NOT NULL AND jsonb_typeof(p_transfer_ids) <> 'array' THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_TRANSFER_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_TRANSFER_IDS_MUST_BE_ARRAY')::text;
  END IF;

  IF p_transfer_ids IS NOT NULL AND jsonb_array_length(p_transfer_ids) > v_update_limit THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_TRANSFER_IDS_TOO_MANY'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_TRANSFER_IDS_TOO_MANY', 'pay_batch_id', p_pay_batch_id::text, 'transfer_id_count', jsonb_array_length(p_transfer_ids), 'limit', v_update_limit)::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_rail_update_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_rail_update_rows (
    row_seq integer PRIMARY KEY,
    transfer_id uuid NULL,
    status text NOT NULL,
    rail_state text NULL,
    rail_tx_id text NULL,
    provider_state text NULL,
    provider_reference text NULL,
    provider_event_id text NULL,
    provider_transaction_id text NULL,
    request_id text NULL,
    idempotency_key text NULL,
    event_source text NOT NULL,
    provider_event_transport text NULL,
    event_time_utc timestamptz NOT NULL,
    amount numeric NULL,
    currency text NULL,
    provider_error_code text NULL,
    provider_error_message_redacted text NULL,
    provider_submit_diagnostic jsonb NOT NULL,
    raw_payload jsonb NOT NULL,
    outcome text NOT NULL,
    review_required boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_rail_update_rows (
    row_seq,
    transfer_id,
    status,
    rail_state,
    rail_tx_id,
    provider_state,
    provider_reference,
    provider_event_id,
    provider_transaction_id,
    request_id,
    idempotency_key,
    event_source,
    provider_event_transport,
    event_time_utc,
    amount,
    currency,
    provider_error_code,
    provider_error_message_redacted,
    provider_submit_diagnostic,
    raw_payload,
    outcome,
    review_required
  )
  SELECT update_element.ordinality::integer,
         CASE
           WHEN nullif(btrim(coalesce(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN nullif(btrim(coalesce(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '')::uuid
           ELSE NULL::uuid
         END,
         CASE
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'status', ''), nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), 'UNKNOWN'))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCEEDED', 'ACCEPTED') THEN 'COMPLETED'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'status', ''), nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), 'UNKNOWN'))) IN ('CANCELLED', 'CANCELED') THEN 'CANCELLED'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'status', ''), nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), 'UNKNOWN'))) IN ('SUBMITTED', 'PENDING', 'PROCESSING', 'FAILED', 'DECLINED', 'REJECTED', 'RETURNED', 'REVERTED', 'UNKNOWN') THEN upper(btrim(coalesce(nullif(update_element.value->>'status', ''), nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), 'UNKNOWN')))
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'status', ''), nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), 'UNKNOWN'))) = 'TIMEOUT' THEN 'UNKNOWN'
           ELSE 'UNKNOWN'
         END,
         nullif(btrim(coalesce(update_element.value->>'rail_state', update_element.value->>'normalised_state', update_element.value->>'normalized_state', update_element.value->>'status', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'rail_tx_id', update_element.value->>'provider_transaction_id', update_element.value->>'provider_payment_id', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'provider_state', update_element.value->>'rail_state', update_element.value->>'status', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'provider_reference', update_element.value->>'provider_payment_id', update_element.value->>'provider_transaction_id', update_element.value->>'rail_tx_id', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'provider_event_id', update_element.value->>'event_id', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'provider_transaction_id', update_element.value->>'provider_payment_id', update_element.value->>'rail_tx_id', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'request_id', update_element.value->'provider_submit_diagnostic'->>'request_id', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'idempotency_key', update_element.value->>'provider_event_key', update_element.value->>'provider_event_id', update_element.value->>'request_id', '')), ''),
         CASE
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), ''))) IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE', 'LOCAL_STATE', 'MANUAL_CONFIRM', 'MANUAL_EVIDENCE', 'SYSTEM') THEN upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), '')))
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), ''))) = 'FAILED_WEBHOOK_REPLAY' THEN 'PROVIDER_WEBHOOK'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) = 'PROVIDER_WEBHOOK' THEN 'PROVIDER_WEBHOOK'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) = 'FAILED_WEBHOOK_REPLAY' THEN 'PROVIDER_WEBHOOK'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) = 'PROVIDER_RESPONSE' THEN 'PROVIDER_RESPONSE'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) = 'LOCAL_STATE' THEN 'LOCAL_STATE'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) = 'MANUAL_CONFIRM' THEN 'MANUAL_CONFIRM'
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) = 'PROVIDER_POLL' THEN 'PROVIDER_POLL'
           ELSE 'PROVIDER_POLL'
         END,
         CASE
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'MANUAL_CONFIRM', 'LOCAL_STATE') THEN upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), '')))
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'LOCAL_STATE', 'MANUAL_CONFIRM') THEN upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), '')))
           WHEN upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), ''))) = 'FAILED_WEBHOOK_REPLAY' THEN 'FAILED_WEBHOOK_REPLAY'
           ELSE NULL::text
         END,
         coalesce(nullif(btrim(coalesce(update_element.value->>'event_time_utc', '')), '')::timestamptz, v_now),
         CASE WHEN nullif(btrim(coalesce(update_element.value->>'amount', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN nullif(btrim(coalesce(update_element.value->>'amount', '')), '')::numeric ELSE NULL::numeric END,
         upper(btrim(coalesce(nullif(update_element.value->>'currency', ''), 'GBP'))),
         nullif(btrim(coalesce(update_element.value->>'provider_error_code', update_element.value->'provider_submit_diagnostic'->>'provider_error_code', '')), ''),
         nullif(btrim(coalesce(update_element.value->>'provider_error_message_redacted', update_element.value->'provider_submit_diagnostic'->>'provider_error_message_redacted', update_element.value->>'failed_reason', '')), ''),
         jsonb_strip_nulls(coalesce(CASE WHEN jsonb_typeof(update_element.value->'provider_submit_diagnostic') = 'object' THEN update_element.value->'provider_submit_diagnostic' ELSE '{}'::jsonb END, '{}'::jsonb)),
         update_element.value,
         CASE
           WHEN upper(btrim(coalesce(update_element.value->>'provider_submission_status', update_element.value->'provider_submit_diagnostic'->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTED')
             OR upper(btrim(coalesce(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCEEDED', 'ACCEPTED') THEN 'ACCEPTED'
           WHEN upper(btrim(coalesce(update_element.value->>'provider_submission_status', update_element.value->'provider_submit_diagnostic'->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED')
             OR upper(btrim(coalesce(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', ''))) IN ('FAILED', 'REJECTED', 'DECLINED', 'RETURNED', 'CANCELLED', 'CANCELED') THEN 'FAILED'
           WHEN upper(btrim(coalesce(update_element.value->>'provider_submission_status', update_element.value->'provider_submit_diagnostic'->>'provider_submission_status', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             OR upper(btrim(coalesce(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', ''))) IN ('UNKNOWN', 'TIMEOUT') THEN 'UNKNOWN'
           ELSE 'PENDING'
         END,
         CASE
           WHEN upper(btrim(coalesce(update_element.value->>'provider_submission_status', update_element.value->'provider_submit_diagnostic'->>'provider_submission_status', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             OR lower(btrim(coalesce(update_element.value->>'manual_resolution_required', update_element.value->'provider_submit_diagnostic'->>'manual_resolution_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
           ELSE false
         END
  FROM jsonb_array_elements(p_updates) WITH ORDINALITY AS update_element(value, ordinality)
  WHERE jsonb_typeof(update_element.value) = 'object';

  SELECT count(*)::integer
  INTO v_after_filter_count
  FROM pg_temp.tmp_rail_update_rows AS update_row;

  IF v_after_filter_count <> v_input_count THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_INVALID_UPDATE_OBJECTS'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_INVALID_UPDATE_OBJECTS', 'input_count', v_input_count, 'valid_object_count', v_after_filter_count)::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_rail_scope_matches;
  CREATE TEMPORARY TABLE pg_temp.tmp_rail_scope_matches ON COMMIT DROP AS
  SELECT update_row.row_seq,
         scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         row_number() OVER (PARTITION BY update_row.row_seq ORDER BY
           CASE WHEN update_row.transfer_id IS NOT NULL AND scope_row.pay_bank_transfer_id = update_row.transfer_id THEN 0 ELSE 1 END,
           scope_row.id
         ) AS match_rank,
         count(*) OVER (PARTITION BY update_row.row_seq) AS match_count
  FROM pg_temp.tmp_rail_update_rows AS update_row
  JOIN public.banking_pay_operation_transfer_scope AS scope_row
    ON scope_row.pay_batch_id = p_pay_batch_id
   AND (v_effective_operation_id IS NULL OR scope_row.operation_id = v_effective_operation_id)
   AND (p_chunk_id IS NULL OR scope_row.provider_submit_chunk_id = p_chunk_id)
   AND (
     (update_row.transfer_id IS NOT NULL AND scope_row.pay_bank_transfer_id = update_row.transfer_id)
     OR (update_row.provider_transaction_id IS NOT NULL AND nullif(btrim(coalesce(scope_row.provider_transaction_id, '')), '') = update_row.provider_transaction_id)
     OR (update_row.request_id IS NOT NULL AND nullif(btrim(coalesce(scope_row.provider_request_id, '')), '') = update_row.request_id)
     OR (update_row.idempotency_key IS NOT NULL AND nullif(btrim(coalesce(scope_row.provider_idempotency_key, '')), '') = update_row.idempotency_key)
   )
  WHERE p_transfer_ids IS NULL
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_transfer_ids) AS allowed_transfer(value)
       WHERE (allowed_transfer.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND (allowed_transfer.value #>> '{}')::uuid = scope_row.pay_bank_transfer_id
     );

  SELECT count(*)::integer
  INTO v_duplicate_match_count
  FROM pg_temp.tmp_rail_scope_matches AS match_row
  WHERE match_row.match_count > 1;

  DROP TABLE IF EXISTS pg_temp.tmp_rail_update_matched;
  CREATE TEMPORARY TABLE pg_temp.tmp_rail_update_matched ON COMMIT DROP AS
  SELECT update_row.*,
         match_row.transfer_scope_id,
         match_row.pay_bank_transfer_id
  FROM pg_temp.tmp_rail_update_rows AS update_row
  JOIN pg_temp.tmp_rail_scope_matches AS match_row
    ON match_row.row_seq = update_row.row_seq
   AND match_row.match_rank = 1
   AND match_row.match_count = 1;

  SELECT count(*)::integer
  INTO v_matched_count
  FROM pg_temp.tmp_rail_update_matched AS matched_row;

  v_unmatched_count := GREATEST(COALESCE(v_after_filter_count, 0) - COALESCE(v_matched_count, 0), 0);
  v_operation_review_required := COALESCE(v_duplicate_match_count, 0) > 0 OR COALESCE(v_unmatched_count, 0) > 0;

  IF COALESCE(v_duplicate_match_count, 0) > 0 THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET provider_submit_state = 'REVIEW_REQUIRED',
        provider_submit_ready = false,
        provider_review_required = true,
        provider_unsafe_reason = 'RAIL_UPDATE_SCOPE_AMBIGUITY',
        updated_at_utc = v_now
    FROM (
      SELECT DISTINCT match_row.transfer_scope_id
      FROM pg_temp.tmp_rail_scope_matches AS match_row
      WHERE match_row.match_count > 1
    ) AS ambiguous_scope
    WHERE scope_update.id = ambiguous_scope.transfer_scope_id;
  END IF;

  IF v_matched_count <= 0 THEN
    IF v_effective_operation_id IS NOT NULL THEN
      UPDATE public.banking_pay_operations AS operation_update
      SET status = 'REVIEW_REQUIRED',
          runner_state = 'REVIEW_REQUIRED',
          requires_user_action = true,
          resume_reason = 'PROVIDER_RAIL_UPDATE_NO_MATCH',
          updated_at_utc = v_now
      WHERE operation_update.id = v_effective_operation_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', false,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN v_effective_operation_id IS NULL THEN NULL ELSE v_effective_operation_id::text END,
      'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
      'input_count', v_input_count,
      'updated_count', 0,
      'event_result_count', 0,
      'claim_blocked', true,
      'claim_blocker_code', 'NO_SCOPED_TRANSFER_UPDATES',
      'message', 'No supplied rail updates matched the bounded operation/chunk/transfer scope.'
    );
  END IF;

  WITH inserted_events AS (
    INSERT INTO public.pay_bank_transfer_events (
      pay_batch_id,
      pay_bank_transfer_id,
      candidate_id,
      umbrella_id,
      provider_key,
      provider_event_id,
      provider_reference,
      provider_state,
      normalised_state,
      event_source,
      event_time_utc,
      received_at_utc,
      amount,
      currency,
      mapping_status,
      mapping_method,
      raw_payload,
      idempotency_key,
      provider_event_type,
      provider_transaction_id,
      provider_request_id,
      provider_event_key,
      provider_event_transport,
      adapter_key,
      adapter_version,
      rail_env,
      provider_failure_reason_code,
      provider_failure_reason_group,
      mapping_hints_json
    )
    SELECT p_pay_batch_id,
           matched_row.pay_bank_transfer_id,
           transfer_row.candidate_id,
           transfer_row.umbrella_id,
           v_batch_row.rail_provider_snapshot,
           matched_row.provider_event_id,
           matched_row.provider_reference,
           coalesce(matched_row.provider_state, matched_row.rail_state, matched_row.status),
           matched_row.status,
           matched_row.event_source,
           matched_row.event_time_utc,
           v_now,
           coalesce(matched_row.amount, transfer_row.amount),
           coalesce(nullif(btrim(matched_row.currency), ''), transfer_row.currency, 'GBP'),
           'MATCHED',
           'OPERATION_TRANSFER_SCOPE',
           jsonb_strip_nulls(matched_row.raw_payload || jsonb_build_object('provider_submit_diagnostic', matched_row.provider_submit_diagnostic, 'operation_id', CASE WHEN v_effective_operation_id IS NULL THEN NULL ELSE v_effective_operation_id::text END, 'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END, 'transfer_scope_id', matched_row.transfer_scope_id::text)),
           coalesce(matched_row.idempotency_key, 'rail-update:' || md5(matched_row.raw_payload::text || ':' || matched_row.row_seq::text)),
           NULL::text,
           matched_row.provider_transaction_id,
           matched_row.request_id,
           coalesce(matched_row.idempotency_key, matched_row.provider_event_id, matched_row.request_id, 'rail-update:' || md5(matched_row.raw_payload::text || ':' || matched_row.row_seq::text)),
           matched_row.provider_event_transport,
           NULL::text,
           NULL::text,
           coalesce(v_batch_row.rail_env_snapshot, 'PROD'),
           CASE
             WHEN matched_row.outcome IN ('FAILED', 'UNKNOWN') THEN COALESCE(
               failure_reason.failure_json->>'failure_reason_code',
               failure_reason.failure_json->>'provider_failure_reason_code',
               CASE WHEN matched_row.outcome = 'UNKNOWN' THEN 'PROVIDER_UNKNOWN' ELSE 'PROVIDER_FAILED_UNSPECIFIED' END
             )
             ELSE NULL::text
           END,
           CASE
             WHEN matched_row.outcome IN ('FAILED', 'UNKNOWN') THEN COALESCE(
               failure_reason.failure_json->>'failure_reason_group',
               failure_reason.failure_json->>'provider_failure_reason_group',
               CASE WHEN matched_row.outcome = 'UNKNOWN' THEN 'PROVIDER_UNKNOWN' ELSE 'PROVIDER_FAILED_UNSPECIFIED' END
             )
             ELSE NULL::text
           END,
           '{}'::jsonb
    FROM pg_temp.tmp_rail_update_matched AS matched_row
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = matched_row.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    CROSS JOIN LATERAL (
      SELECT CASE
        WHEN matched_row.outcome IN ('FAILED', 'UNKNOWN') THEN public._banking_provider_failure_reason_normalise(
          v_batch_row.rail_provider_snapshot,
          coalesce(matched_row.provider_state, matched_row.rail_state, matched_row.status),
          matched_row.provider_error_code,
          matched_row.provider_error_message_redacted,
          matched_row.raw_payload
        )
        ELSE '{}'::jsonb
      END AS failure_json
    ) AS failure_reason
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS existing_event
      WHERE existing_event.idempotency_key = coalesce(matched_row.idempotency_key, matched_row.provider_event_id, matched_row.request_id, 'rail-update:' || md5(matched_row.raw_payload::text || ':' || matched_row.row_seq::text))
    )
    ON CONFLICT DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::integer
  INTO v_event_count
  FROM inserted_events;

  UPDATE public.pay_bank_transfers AS transfer_update
  SET status = CASE
        WHEN matched_row.outcome = 'ACCEPTED' THEN 'COMPLETED'
        WHEN matched_row.outcome = 'FAILED' THEN CASE WHEN matched_row.status IN ('CANCELLED', 'CANCELED') THEN 'CANCELLED' WHEN matched_row.status = 'RETURNED' THEN 'RETURNED' ELSE 'FAILED' END
        WHEN matched_row.outcome = 'UNKNOWN' THEN transfer_update.status
        WHEN matched_row.status = 'PENDING' THEN 'PENDING'
        ELSE transfer_update.status
      END,
      rail_tx_id = CASE WHEN matched_row.outcome = 'ACCEPTED' AND nullif(btrim(coalesce(matched_row.rail_tx_id, '')), '') IS NOT NULL THEN matched_row.rail_tx_id ELSE transfer_update.rail_tx_id END,
      rail_state = coalesce(nullif(btrim(matched_row.rail_state), ''), transfer_update.rail_state),
      failed_reason = CASE WHEN matched_row.outcome = 'FAILED' THEN coalesce(nullif(btrim(matched_row.provider_error_message_redacted), ''), nullif(btrim(matched_row.provider_error_code), ''), transfer_update.failed_reason, 'PROVIDER_REJECTED') ELSE transfer_update.failed_reason END,
      completed_at_utc = CASE WHEN matched_row.outcome = 'ACCEPTED' THEN coalesce(transfer_update.completed_at_utc, v_now) ELSE transfer_update.completed_at_utc END,
      rail_meta_json = jsonb_strip_nulls(coalesce(transfer_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'last_update_at_utc', v_now::text,
        'last_update_event_source', matched_row.event_source,
        'last_update_operation_id', CASE WHEN v_effective_operation_id IS NULL THEN NULL ELSE v_effective_operation_id::text END,
        'last_update_chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
        'provider_submit_diagnostic', jsonb_strip_nulls(coalesce(transfer_update.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || matched_row.provider_submit_diagnostic || jsonb_build_object(
          'provider_submission_status', CASE WHEN matched_row.outcome = 'ACCEPTED' THEN 'PROVIDER_SUBMISSION_ACCEPTED' WHEN matched_row.outcome = 'FAILED' THEN 'PROVIDER_SUBMISSION_REJECTED' WHEN matched_row.outcome = 'UNKNOWN' THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' ELSE coalesce(matched_row.provider_submit_diagnostic->>'provider_submission_status', 'PROVIDER_SUBMISSION_PENDING') END,
          'provider_request_sent', true,
          'provider_response_present', matched_row.outcome IN ('ACCEPTED', 'FAILED'),
          'provider_acceptance_evidence_present', matched_row.outcome = 'ACCEPTED',
          'provider_submission_unknown', matched_row.outcome = 'UNKNOWN',
          'manual_resolution_required', matched_row.review_required,
          'rail_tx_id', CASE WHEN matched_row.outcome = 'ACCEPTED' THEN matched_row.rail_tx_id ELSE NULL::text END,
          'provider_reference', matched_row.provider_reference,
          'provider_transaction_id', matched_row.provider_transaction_id,
          'provider_request_id', matched_row.request_id,
          'provider_idempotency_key', matched_row.idempotency_key,
          'provider_error_code', matched_row.provider_error_code,
          'provider_error_message_redacted', matched_row.provider_error_message_redacted
        ))
      ))
  FROM pg_temp.tmp_rail_update_matched AS matched_row
  WHERE transfer_update.id = matched_row.pay_bank_transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = CASE
        WHEN matched_row.outcome = 'ACCEPTED' THEN 'PROVIDER_ACCEPTED'
        WHEN matched_row.outcome = 'FAILED' THEN 'PROVIDER_REJECTED'
        WHEN matched_row.outcome = 'UNKNOWN' THEN 'PROVIDER_UNKNOWN'
        ELSE scope_update.provider_submit_state
      END,
      provider_submit_ready = false,
      provider_review_required = matched_row.review_required OR matched_row.outcome = 'UNKNOWN',
      provider_unsafe_reason = CASE
        WHEN matched_row.outcome = 'UNKNOWN' THEN 'PROVIDER_OUTCOME_UNKNOWN'
        WHEN matched_row.review_required THEN 'PROVIDER_REVIEW_REQUIRED'
        WHEN matched_row.outcome = 'FAILED' THEN coalesce(nullif(btrim(matched_row.provider_error_code), ''), 'PROVIDER_REJECTED')
        ELSE NULL::text
      END,
      provider_transaction_id = COALESCE(NULLIF(BTRIM(matched_row.provider_transaction_id), ''), scope_update.provider_transaction_id),
      provider_request_id = COALESCE(NULLIF(BTRIM(matched_row.request_id), ''), scope_update.provider_request_id),
      provider_idempotency_key = COALESCE(NULLIF(BTRIM(matched_row.idempotency_key), ''), scope_update.provider_idempotency_key),
      provider_response_at_utc = CASE WHEN matched_row.outcome IN ('ACCEPTED', 'FAILED', 'UNKNOWN') THEN COALESCE(scope_update.provider_response_at_utc, v_now) ELSE scope_update.provider_response_at_utc END,
      provider_submission_status = CASE WHEN matched_row.outcome = 'ACCEPTED' THEN 'PROVIDER_ACCEPTED' WHEN matched_row.outcome = 'FAILED' THEN 'PROVIDER_REJECTED' WHEN matched_row.outcome = 'UNKNOWN' THEN 'PROVIDER_UNKNOWN' ELSE scope_update.provider_submission_status END,
      status = CASE WHEN matched_row.outcome = 'ACCEPTED' THEN 'SUBMITTED' WHEN matched_row.outcome IN ('FAILED', 'UNKNOWN') THEN 'FAILED' ELSE scope_update.status END,
      updated_at_utc = v_now
  FROM pg_temp.tmp_rail_update_matched AS matched_row
  WHERE scope_update.id = matched_row.transfer_scope_id;

  SELECT count(*) FILTER (WHERE matched_row.outcome = 'ACCEPTED')::integer,
         count(*) FILTER (WHERE matched_row.outcome = 'FAILED')::integer,
         count(*) FILTER (WHERE matched_row.outcome = 'UNKNOWN')::integer,
         count(*) FILTER (WHERE matched_row.review_required IS TRUE)::integer,
         max(coalesce(matched_row.provider_error_message_redacted, matched_row.provider_error_code, matched_row.provider_state, matched_row.status))
  INTO v_accepted_count,
       v_failed_count,
       v_unknown_count,
       v_review_required_count,
       v_last_provider_message
  FROM pg_temp.tmp_rail_update_matched AS matched_row;

  v_operation_review_required := coalesce(v_operation_review_required, false) OR coalesce(v_unknown_count, 0) > 0 OR coalesce(v_review_required_count, 0) > 0;

  IF v_effective_operation_id IS NOT NULL THEN
    UPDATE public.banking_pay_operations AS operation_update
    SET status = CASE WHEN v_operation_review_required THEN 'REVIEW_REQUIRED' ELSE operation_update.status END,
        runner_state = CASE WHEN v_operation_review_required THEN 'REVIEW_REQUIRED' ELSE operation_update.runner_state END,
        requires_user_action = CASE WHEN v_operation_review_required THEN true ELSE operation_update.requires_user_action END,
        resume_reason = CASE WHEN v_operation_review_required THEN 'PROVIDER_RAIL_UPDATE_REVIEW_REQUIRED' ELSE operation_update.resume_reason END,
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_rail_update_at_utc', v_now::text,
          'last_rail_update_chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
          'last_rail_update_count', coalesce(v_updated_count, 0),
          'last_rail_update_accepted_count', coalesce(v_accepted_count, 0),
          'last_rail_update_failed_count', coalesce(v_failed_count, 0),
          'last_rail_update_unknown_count', coalesce(v_unknown_count, 0),
          'last_rail_update_unmatched_count', coalesce(v_unmatched_count, 0),
          'last_rail_update_duplicate_match_count', coalesce(v_duplicate_match_count, 0),
          'last_provider_message', v_last_provider_message
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = v_effective_operation_id;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET result_json = jsonb_strip_nulls(coalesce(chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
          'rail_update_applied_at_utc', v_now::text,
          'updated_count', coalesce(v_updated_count, 0),
          'event_result_count', coalesce(v_event_count, 0),
          'accepted_count', coalesce(v_accepted_count, 0),
          'failed_count', coalesce(v_failed_count, 0),
          'unknown_count', coalesce(v_unknown_count, 0),
          'review_required_count', coalesce(v_review_required_count, 0),
          'unmatched_count', coalesce(v_unmatched_count, 0),
          'duplicate_match_count', coalesce(v_duplicate_match_count, 0),
          'last_provider_message', v_last_provider_message
        )),
        updated_at_utc = v_now
    WHERE chunk_update.id = p_chunk_id
      AND (v_effective_operation_id IS NULL OR chunk_update.operation_id = v_effective_operation_id);
  END IF;

  BEGIN
    v_signal_result := public.banking_pay_batch_signal_touch(
      p_pay_batch_id,
      'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES',
      'pay_bank_transfers_apply_rail_updates',
      jsonb_build_object(
        'operation_id', CASE WHEN v_effective_operation_id IS NULL THEN NULL ELSE v_effective_operation_id::text END,
        'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
        'updated_count', coalesce(v_updated_count, 0),
        'accepted_count', coalesce(v_accepted_count, 0),
        'failed_count', coalesce(v_failed_count, 0),
        'unknown_count', coalesce(v_unknown_count, 0)
      ),
      true,
      false,
      v_operation_review_required,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    v_signal_result := '{}'::jsonb;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'bounded', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN v_effective_operation_id IS NULL THEN NULL ELSE v_effective_operation_id::text END,
    'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
    'input_count', coalesce(v_input_count, 0),
    'scoped_update_count', coalesce(v_after_filter_count, 0),
    'matched_update_count', coalesce(v_matched_count, 0),
    'unmatched_count', coalesce(v_unmatched_count, 0),
    'duplicate_match_count', coalesce(v_duplicate_match_count, 0),
    'updated_count', coalesce(v_updated_count, 0),
    'event_result_count', coalesce(v_event_count, 0),
    'accepted_count', coalesce(v_accepted_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'unknown_count', coalesce(v_unknown_count, 0),
    'review_required_count', coalesce(v_review_required_count, 0),
    'operation_review_required', coalesce(v_operation_review_required, false),
    'last_provider_message', v_last_provider_message,
    'live_signal', coalesce(v_signal_result, '{}'::jsonb),
    'server_utc', v_now::text
  );
END;
$function$;

-- pay_bank_transfers_claim_provider_submit_chunk(uuid,uuid,integer,text,integer)
CREATE OR REPLACE FUNCTION public.pay_bank_transfers_claim_provider_submit_chunk(p_operation_id uuid, p_pay_batch_id uuid, p_limit integer DEFAULT 50, p_lock_owner text DEFAULT NULL::text, p_lock_seconds integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_limit integer := LEAST(GREATEST(coalesce(p_limit, 50), 1), 50);
  v_lock_seconds integer := LEAST(GREATEST(coalesce(p_lock_seconds, 60), 10), 3600);
  v_lock_owner text := coalesce(nullif(btrim(coalesce(p_lock_owner, '')), ''), 'provider-submit:' || p_operation_id::text);
  v_pay_channel_scope text := 'ALL';
  v_chunk_id uuid := NULL::uuid;
  v_sequence_no integer := 1;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_transfer_rows jsonb := '[]'::jsonb;
  v_auth_request_ids jsonb := '[]'::jsonb;
  v_same_operation_authorised_auth_count integer := 0;
  v_claimed_count integer := 0;
  v_remaining_count integer := 0;
  v_mutation_guard jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '1s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_bank_transfers_claim_provider_submit_chunk: operation_id is required';
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_bank_transfers_claim_provider_submit_chunk: pay_batch_id is required';
  END IF;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    p_pay_batch_id,
    NULL::uuid,
    'NEW_PAYMENT_ACTION'
  );

  IF COALESCE((v_mutation_guard->>'blocked')::boolean, true) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'claim_ok', false,
      'claim_blocked', true,
      'claim_blocker_code', COALESCE(
        v_mutation_guard->>'code',
        'PAYMENT_CHANGE_IN_PROGRESS'
      ),
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'processed_count', 0,
      'status', 'BLOCKED',
      'blocker_code', COALESCE(
        v_mutation_guard->>'code',
        'PAYMENT_CHANGE_IN_PROGRESS'
      ),
      'chunk_id', NULL,
      'transfer_scope_ids', '[]'::jsonb,
      'auth_request_ids', '[]'::jsonb,
      'transfers', '[]'::jsonb,
      'claimed_count', 0,
      'remaining_count', 0,
      'provider_submission_status', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
      'review_reason_code', COALESCE(
        v_mutation_guard->>'code',
        'PAYMENT_CHANGE_IN_PROGRESS'
      ),
      'display_message', COALESCE(
        v_mutation_guard->>'message',
        'A payment change is in progress.'
      )
    );
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'operation % is not a payment execution operation', p_operation_id;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batches row % not found', p_pay_batch_id;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
     OR nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_SUBMIT_CLAIM_EXECUTION_BOUNDARY_CROSSED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_SUBMIT_CLAIM_EXECUTION_BOUNDARY_CROSSED', 'pay_batch_id', p_pay_batch_id::text, 'operation_id', p_operation_id::text)::text;
  END IF;

  v_pay_channel_scope := upper(btrim(coalesce(
    nullif(btrim(coalesce(v_operation_row.input_json->>'pay_channel_scope', '')), ''),
    nullif(btrim(coalesce(v_operation_row.input_json->>'payChannelScope', '')), ''),
    nullif(btrim(coalesce(v_operation_row.config_json->>'pay_channel_scope', '')), ''),
    nullif(btrim(coalesce(v_operation_row.config_json->>'payChannelScope', '')), ''),
    'ALL'
  )));
  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'LOANS', 'ALL') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  SELECT count(*)::integer,
         coalesce(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc DESC NULLS LAST, auth_request.id), '[]'::jsonb)
  INTO v_same_operation_authorised_auth_count,
       v_auth_request_ids
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND auth_request.state = 'AUTHORISED'
    AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text;

  IF coalesce(v_same_operation_authorised_auth_count, 0) <= 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'claim_ok', false,
      'claim_blocked', true,
      'claim_blocker_code', 'AUTH_REQUEST_NOT_AUTHORISED_FOR_OPERATION',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'processed_count', 0,
      'status', 'BLOCKED',
      'blocker_code', 'AUTH_REQUEST_NOT_AUTHORISED_FOR_OPERATION',
      'display_message', 'Payment authorisation is not valid for this operation.',
      'chunk_id', NULL,
      'transfer_scope_ids', '[]'::jsonb,
      'auth_request_ids', '[]'::jsonb,
      'transfers', '[]'::jsonb,
      'claimed_count', 0,
      'remaining_count', 0,
      'provider_submission_status', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
      'review_reason_code', 'AUTH_REQUEST_NOT_AUTHORISED_FOR_OPERATION'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_claimed_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_claimed_scope (
    transfer_scope_id uuid PRIMARY KEY,
    pay_bank_transfer_id uuid NOT NULL,
    claim_ordinal integer NOT NULL
  ) ON COMMIT DROP;

  WITH locked_scope AS (
    SELECT scope_row.id AS transfer_scope_id,
           scope_row.pay_bank_transfer_id,
           scope_row.updated_at_utc
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = scope_row.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = scope_row.pay_batch_id
     AND transfer_row.pay_channel = scope_row.pay_channel
     AND transfer_row.transfer_group_key = scope_row.transfer_group_key
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL
      AND upper(btrim(coalesce(transfer_row.status, ''))) = 'PENDING'
      AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NULL
      AND transfer_row.completed_at_utc IS NULL
      AND nullif(btrim(coalesce(transfer_row.failed_reason, '')), '') IS NULL
      AND (v_pay_channel_scope = 'ALL' OR upper(btrim(coalesce(scope_row.pay_channel, ''))) = v_pay_channel_scope)
    ORDER BY scope_row.updated_at_utc NULLS FIRST, scope_row.id
    LIMIT v_limit
    FOR UPDATE OF scope_row, transfer_row SKIP LOCKED
  ), claimable_scope AS (
    SELECT locked_scope.transfer_scope_id,
           locked_scope.pay_bank_transfer_id,
           row_number() OVER (ORDER BY locked_scope.updated_at_utc NULLS FIRST, locked_scope.transfer_scope_id)::integer AS claim_ordinal
    FROM locked_scope
  )
  INSERT INTO pg_temp.tmp_provider_submit_claimed_scope (transfer_scope_id, pay_bank_transfer_id, claim_ordinal)
  SELECT claimable_scope.transfer_scope_id,
         claimable_scope.pay_bank_transfer_id,
         claimable_scope.claim_ordinal
  FROM claimable_scope;

  SELECT count(*)::integer
  INTO v_claimed_count
  FROM pg_temp.tmp_provider_submit_claimed_scope AS claimed_scope;

  IF coalesce(v_claimed_count, 0) <= 0 THEN
    SELECT count(*)::integer
    INTO v_remaining_count
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL;

    RETURN jsonb_build_object(
      'ok', false,
      'claim_ok', false,
      'claim_blocked', true,
      'claim_blocker_code', 'PROVIDER_SUBMIT_NO_ELIGIBLE_TRANSFERS',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'processed_count', 0,
      'status', 'NO_SCOPE_DUE',
      'blocker_code', 'PROVIDER_SUBMIT_NO_ELIGIBLE_TRANSFERS',
      'display_message', 'No payment instructions are ready to submit.',
      'chunk_id', NULL,
      'transfer_scope_ids', '[]'::jsonb,
      'auth_request_ids', coalesce(v_auth_request_ids, '[]'::jsonb),
      'transfers', '[]'::jsonb,
      'claimed_count', 0,
      'remaining_count', coalesce(v_remaining_count, 0),
      'provider_submission_status', 'NO_PROVIDER_SUBMISSION_ATTEMPTED'
    );
  END IF;

  SELECT (count(*) + 1)::integer
  INTO v_sequence_no
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.operation_id = p_operation_id
    AND chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS'
    AND chunk_row.chunk_type = 'TRANSFER_SUBMIT';

  v_chunk_id := gen_random_uuid();

  SELECT coalesce(jsonb_agg(to_jsonb(claimed_scope.transfer_scope_id::text) ORDER BY claimed_scope.claim_ordinal), '[]'::jsonb),
         coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'transfer_scope_id', claimed_scope.transfer_scope_id::text,
           'pay_bank_transfer_id', transfer_row.id::text,
           'pay_batch_id', transfer_row.pay_batch_id::text,
           'payee_entity_kind', transfer_row.payee_entity_kind,
           'payee_entity_id', CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END,
           'candidate_id', CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END,
           'umbrella_id', CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END,
           'pay_channel', transfer_row.pay_channel,
           'amount', transfer_row.amount,
           'currency', coalesce(nullif(btrim(coalesce(transfer_row.currency, '')), ''), 'GBP'),
           'payment_reference', transfer_row.payment_reference,
           'payee_name', transfer_row.payee_name,
           'sort_code', transfer_row.sort_code,
           'account_number', transfer_row.account_number,
           'account_type', transfer_row.account_type,
           'bank_details_hash_snapshot', transfer_row.bank_details_hash_snapshot,
           'request_id', transfer_row.request_id,
           'idempotency_key', coalesce(nullif(btrim(coalesce(transfer_row.request_id, '')), ''), 'transfer:' || transfer_row.id::text),
           'funding_account_ref', v_batch_row.funding_account_ref,
           'rail_provider', transfer_row.rail_provider,
           'rail_env', transfer_row.rail_env,
           'transfer_group_key', transfer_row.transfer_group_key
         )) ORDER BY claimed_scope.claim_ordinal), '[]'::jsonb)
  INTO v_transfer_scope_ids,
       v_transfer_rows
  FROM pg_temp.tmp_provider_submit_claimed_scope AS claimed_scope
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = claimed_scope.pay_bank_transfer_id;

  INSERT INTO public.banking_pay_operation_chunks (
    id,
    operation_id,
    phase,
    chunk_type,
    sequence_no,
    status,
    payload_json,
    result_json,
    error_json,
    unit_count,
    completed_count,
    failed_count,
    locked_by,
    lock_expires_at_utc,
    created_at_utc,
    started_at_utc,
    completed_at_utc,
    updated_at_utc
  )
  VALUES (
    v_chunk_id,
    p_operation_id,
    'SUBMIT_PROVIDER_TRANSFERS',
    'TRANSFER_SUBMIT',
    v_sequence_no,
    'RUNNING',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'transfer_scope_ids', coalesce(v_transfer_scope_ids, '[]'::jsonb),
      'transfers', coalesce(v_transfer_rows, '[]'::jsonb),
      'claimed_at_utc', v_now::text,
      'lock_owner', v_lock_owner,
      'row_backed_provider_queue', true
    ),
    jsonb_build_object('provider_submit_stage', 'CLAIMED'),
    NULL::jsonb,
    coalesce(v_claimed_count, 0),
    0,
    0,
    v_lock_owner,
    v_now + make_interval(secs => v_lock_seconds),
    v_now,
    v_now,
    NULL::timestamptz,
    v_now
  );

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = 'CLAIMED',
      provider_submit_ready = false,
      provider_review_required = false,
      provider_unsafe_reason = NULL::text,
      provider_submit_chunk_id = v_chunk_id,
      provider_submit_claimed_at_utc = v_now,
      provider_submit_attempt_count = COALESCE(scope_update.provider_submit_attempt_count, 0) + 1,
      provider_idempotency_key = coalesce(nullif(btrim(scope_update.provider_idempotency_key), ''), coalesce(nullif(btrim(transfer_row.request_id), ''), 'scope:' || scope_update.id::text)),
      provider_request_id = coalesce(nullif(btrim(scope_update.provider_request_id), ''), transfer_row.request_id),
      updated_at_utc = v_now
  FROM pg_temp.tmp_provider_submit_claimed_scope AS claimed_scope
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = claimed_scope.pay_bank_transfer_id
  WHERE scope_update.id = claimed_scope.transfer_scope_id;

  SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL
    LIMIT 1
  ) THEN 1 ELSE 0 END
  INTO v_remaining_count;

  RETURN jsonb_build_object(
    'ok', true,
    'claim_ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'processed_count', coalesce(v_claimed_count, 0),
    'status', 'CLAIMED',
    'blocker_code', NULL,
    'display_message', 'Payment instructions claimed for bounded submission.',
    'chunk_id', v_chunk_id::text,
    'chunk_type', 'TRANSFER_SUBMIT',
    'phase', 'SUBMIT_PROVIDER_TRANSFERS',
    'sequence_no', v_sequence_no,
    'lock_owner', v_lock_owner,
    'lock_expires_at_utc', (v_now + make_interval(secs => v_lock_seconds))::text,
    'transfer_scope_ids', coalesce(v_transfer_scope_ids, '[]'::jsonb),
    'auth_request_ids', coalesce(v_auth_request_ids, '[]'::jsonb),
    'transfers', coalesce(v_transfer_rows, '[]'::jsonb),
    'unit_count', coalesce(v_claimed_count, 0),
    'claimed_count', coalesce(v_claimed_count, 0),
    'remaining_count', coalesce(v_remaining_count, 0),
    'has_more', coalesce(v_remaining_count, 0) > 0,
    'provider_submission_status', 'NO_PROVIDER_SUBMISSION_ATTEMPTED',
    'manual_resolution_required', false
  );
END;
$function$;

-- pay_banking_official_date_context_v1(timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_banking_official_date_context_v1(p_as_of_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_as_of_utc timestamptz := COALESCE(p_as_of_utc, statement_timestamp());
  v_timezone_id text := 'Europe/London';
  v_official_weekday smallint;
  v_settings_updated_at timestamptz;
  v_local_timestamp timestamp without time zone;
  v_business_date date;
  v_business_dow integer;
  v_days_to_official integer;
  v_current_official_pay_date date;
  v_next_official_pay_date date;
  v_following_official_pay_date date;
  v_pay_week_start date;
  v_pay_week_end date;
  v_configuration_fingerprint text;
  v_utc_offset_seconds integer;
BEGIN
  SELECT settings_row.banking_pay_official_pay_weekday,
         settings_row.updated_at
  INTO v_official_weekday,
       v_settings_updated_at
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANKING_PAY_DATE_CONFIGURATION_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_DATE_CONFIGURATION_MISSING',
              'message', 'Banking Pay date configuration is unavailable.'
            )::text;
  END IF;

  IF v_official_weekday IS NULL OR v_official_weekday < 0 OR v_official_weekday > 6 THEN
    RAISE EXCEPTION 'BANKING_PAY_WEEKDAY_CONFIGURATION_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_WEEKDAY_CONFIGURATION_INVALID',
              'official_pay_weekday', v_official_weekday,
              'message', 'Banking Pay official weekday configuration is invalid.'
            )::text;
  END IF;

  v_local_timestamp := v_as_of_utc AT TIME ZONE 'Europe/London';
  v_business_date := v_local_timestamp::date;
  v_business_dow := EXTRACT(DOW FROM v_business_date)::integer;
  v_days_to_official := ((v_official_weekday::integer - v_business_dow) + 7) % 7;
  v_current_official_pay_date := v_business_date + v_days_to_official;
  -- The operational current Workbench pay date is the first configured pay
  -- weekday on or after the London business date.  That is also the next
  -- official pay run used by Snooze warnings.  The following run is exposed
  -- separately so callers never need to reinterpret "next" as +7 days.
  v_next_official_pay_date := v_current_official_pay_date;
  v_following_official_pay_date := v_current_official_pay_date + 7;
  v_pay_week_end := v_current_official_pay_date;
  v_pay_week_start := v_pay_week_end - 6;
  v_configuration_fingerprint := md5(
    COALESCE(v_timezone_id, '') || '|' ||
    COALESCE(v_official_weekday::text, '') || '|' ||
    COALESCE(v_settings_updated_at::text, '')
  );
  v_utc_offset_seconds := EXTRACT(
    EPOCH FROM (
      v_local_timestamp - (v_as_of_utc AT TIME ZONE 'UTC')
    )
  )::integer;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_as_of_utc,
    'timezone_id', v_timezone_id,
    'local_timestamp', v_local_timestamp,
    'london_current_date', v_business_date::text,
    'business_date', v_business_date::text,
    'official_pay_weekday', v_official_weekday,
    'official_pay_weekday_name', TRIM(TO_CHAR(v_current_official_pay_date, 'FMDay')),
    'current_official_pay_date', v_current_official_pay_date::text,
    'next_official_pay_date', v_next_official_pay_date::text,
    'following_official_pay_date', v_following_official_pay_date::text,
    'current_pay_week_start', v_pay_week_start::text,
    'current_pay_week_end', v_pay_week_end::text,
    'current_pay_week_key', v_current_official_pay_date::text,
    'settings_defaults_updated_at', v_settings_updated_at,
    'configuration_fingerprint', v_configuration_fingerprint,
    'utc_offset_seconds', v_utc_offset_seconds,
    'as_of_override_applied', p_as_of_utc IS NOT NULL
  );
END;
$function$;

-- pay_batch_abort_failed_draft_create_partial(uuid,uuid,uuid,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_abort_failed_draft_create_partial(p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_failure_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_batch_row_after public.pay_batches%ROWTYPE;
  v_operation_status text := NULL::text;
  v_operation_phase text := NULL::text;
  v_batch_status_before text := NULL::text;
  v_batch_status_after text := NULL::text;
  v_execution_commit_state_before text := NULL::text;
  v_failure_json jsonb := '{}'::jsonb;
  v_failure_code text := 'DRAFT_CREATE_OPERATION_FAILED';
  v_failure_phase text := 'UNKNOWN';
  v_reason text := NULL::text;
  v_effective_actor_user_id uuid := NULL::uuid;
  v_expected_snapshot_run_id_text text := NULL::text;
  v_batch_snapshot_run_id_text text := NULL::text;
  v_expected_session_version_text text := NULL::text;
  v_batch_session_version_text text := NULL::text;
  v_session_version_direct_link_exception_used boolean := false;
  v_operation_direct_batch_link boolean := false;
  v_candidate_scope_link_count integer := 0;
  v_allocation_link_count integer := 0;
  v_item_link_count integer := 0;
  v_latest_draft_create_operation_id uuid := NULL::uuid;
  v_transfer_row_count integer := 0;
  v_transfer_scope_count integer := 0;
  v_provider_attempt_count integer := 0;
  v_bank_transfer_event_count integer := 0;
  v_auth_request_count integer := 0;
  v_auth_action_count integer := 0;
  v_remittance_scope_count integer := 0;
  v_settlement_scope_count integer := 0;
  v_correction_request_count integer := 0;
  v_committed_reservation_count integer := 0;
  v_submission_artifact_count integer := 0;
  v_batch_submission_flag_count integer := 0;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_active_item_count integer := 0;
  v_reservation_count integer := 0;
  v_reservations_released integer := 0;
  v_items_voided integer := 0;
  v_candidate_scopes_failed integer := 0;
  v_allocation_rows_updated integer := 0;
  v_allocation_rows_failed integer := 0;
  v_batch_status_cancelled_allowed boolean := true;
  v_candidate_scope_failed_status_allowed boolean := true;
  v_allocation_failed_status_allowed boolean := false;
  v_reservation_released_status_allowed boolean := false;
  v_called_from_failure_finalisation boolean := false;
  v_cleanup_counts_json jsonb := '{}'::jsonb;
  v_signal_scope_json jsonb := '{}'::jsonb;
  v_signal_result_json jsonb := '{}'::jsonb;
  v_cleanup_result_json jsonb := '{}'::jsonb;
  v_operation_progress_patch_json jsonb := '{}'::jsonb;
  v_operation_error_patch_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_REQUIRED'
            )::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_REQUIRED',
              'operation_id', p_operation_id::text
            )::text;
  END IF;

  v_failure_json := CASE
    WHEN p_failure_json IS NOT NULL AND jsonb_typeof(p_failure_json) = 'object' THEN COALESCE(p_failure_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_operation_status := UPPER(BTRIM(COALESCE(v_operation_row.status, '')));
  v_operation_phase := UPPER(BTRIM(COALESCE(v_operation_row.phase, '')));
  v_batch_status_before := UPPER(BTRIM(COALESCE(v_batch_row.status, '')));
  v_execution_commit_state_before := UPPER(BTRIM(COALESCE(v_batch_row.execution_commit_state, '')));
  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_operation_row.actor_user_id, v_batch_row.created_by_user_id);

  v_failure_code := UPPER(NULLIF(BTRIM(COALESCE(
    v_failure_json->>'code',
    v_failure_json->>'error_code',
    v_failure_json->>'errorCode',
    'DRAFT_CREATE_OPERATION_FAILED'
  )), ''));
  IF v_failure_code IS NULL THEN
    v_failure_code := 'DRAFT_CREATE_OPERATION_FAILED';
  END IF;

  v_failure_phase := UPPER(NULLIF(BTRIM(COALESCE(
    v_failure_json->>'phase',
    v_failure_json->>'operation_phase',
    v_failure_json->>'operationPhase',
    v_operation_phase,
    'UNKNOWN'
  )), ''));
  IF v_failure_phase IS NULL THEN
    v_failure_phase := 'UNKNOWN';
  END IF;

  v_reason := LEFT(COALESCE(
    NULLIF(BTRIM(p_reason), ''),
    'Draft creation failed during ' || v_failure_phase || ': ' || v_failure_code
  ), 500);

  v_called_from_failure_finalisation := (
    v_operation_status IN ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED')
    AND v_operation_phase NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
    AND (
      NULLIF(BTRIM(COALESCE(v_failure_json->>'code', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'error_code', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'errorCode', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'error', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'message', '')), '') IS NOT NULL
      OR LOWER(BTRIM(COALESCE(v_failure_json->>'called_from_failure_finalisation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    )
  );

  IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_TYPE_INVALID',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_type', v_operation_row.operation_type
            )::text;
  END IF;

  IF v_operation_status NOT IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
     AND v_called_from_failure_finalisation IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FAILED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FAILED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_status', v_operation_row.status,
              'operation_phase', v_operation_row.phase,
              'failure_json_present', v_failure_json <> '{}'::jsonb
            )::text;
  END IF;

  IF v_batch_status_before NOT IN ('DRAFT', 'DRAFT_CREATED', 'CANCELLED', 'CANCELED') THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_STATUS_UNSAFE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_STATUS_UNSAFE',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'batch_status', v_batch_row.status
            )::text;
  END IF;

  IF NULLIF(v_execution_commit_state_before, '') IS NOT NULL
     AND v_execution_commit_state_before <> 'NOT_SUBMITTED' THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_COMMIT_STATE_UNSAFE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_COMMIT_STATE_UNSAFE',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'execution_commit_state', v_batch_row.execution_commit_state
            )::text;
  END IF;

  IF v_operation_row.workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_SESSION_REQUIRED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF v_batch_row.source_workbench_session_id IS DISTINCT FROM v_operation_row.workbench_session_id THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_workbench_session_id', v_operation_row.workbench_session_id::text,
              'batch_source_workbench_session_id', CASE WHEN v_batch_row.source_workbench_session_id IS NULL THEN NULL ELSE v_batch_row.source_workbench_session_id::text END
            )::text;
  END IF;

  v_expected_snapshot_run_id_text := NULLIF(BTRIM(COALESCE(
    v_operation_row.input_json->>'source_snapshot_run_id',
    v_operation_row.input_json->>'sourceSnapshotRunId',
    v_operation_row.input_json->>'snapshot_run_id',
    v_operation_row.input_json->>'snapshotRunId',
    ''
  )), '');
  v_batch_snapshot_run_id_text := CASE WHEN v_batch_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_batch_row.source_snapshot_run_id::text END;

  IF v_expected_snapshot_run_id_text IS NOT NULL
     AND v_batch_snapshot_run_id_text IS DISTINCT FROM v_expected_snapshot_run_id_text THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SNAPSHOT_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SNAPSHOT_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'expected_source_snapshot_run_id', v_expected_snapshot_run_id_text,
              'batch_source_snapshot_run_id', v_batch_snapshot_run_id_text
            )::text;
  END IF;

  v_expected_session_version_text := NULLIF(BTRIM(COALESCE(
    v_operation_row.input_json->>'source_session_version',
    v_operation_row.input_json->>'sourceSessionVersion',
    v_operation_row.input_json->>'selection_session_version',
    v_operation_row.input_json->>'selectionSessionVersion',
    ''
  )), '');
  v_batch_session_version_text := CASE WHEN v_batch_row.source_session_version IS NULL THEN NULL ELSE v_batch_row.source_session_version::text END;

  v_operation_direct_batch_link := (
    v_operation_row.pay_batch_id IS NOT NULL
    AND v_operation_row.pay_batch_id = p_pay_batch_id
  );

  SELECT COUNT(*)::integer
  INTO v_candidate_scope_link_count
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_allocation_link_count
  FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
  WHERE allocation_row.operation_id = p_operation_id
    AND allocation_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_item_link_count
  FROM public.pay_batch_items AS item_row
  JOIN public.pay_batch_candidates AS candidate_row
    ON candidate_row.id = item_row.pay_batch_candidate_id
  WHERE candidate_row.pay_batch_id = p_pay_batch_id
    AND item_row.operation_source_key IS NOT NULL
    AND item_row.operation_source_key LIKE p_operation_id::text || ':%';

  v_session_version_direct_link_exception_used := (
    v_expected_session_version_text IS NOT NULL
    AND v_batch_session_version_text IS DISTINCT FROM v_expected_session_version_text
    AND (
      COALESCE(v_operation_direct_batch_link, false) IS TRUE
      OR COALESCE(v_candidate_scope_link_count, 0) > 0
      OR COALESCE(v_allocation_link_count, 0) > 0
      OR COALESCE(v_item_link_count, 0) > 0
    )
  );

  IF v_expected_session_version_text IS NOT NULL
     AND v_batch_session_version_text IS DISTINCT FROM v_expected_session_version_text
     AND COALESCE(v_session_version_direct_link_exception_used, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_VERSION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_VERSION_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'expected_source_session_version', v_expected_session_version_text,
              'batch_source_session_version', v_batch_session_version_text,
              'operation_direct_batch_link', COALESCE(v_operation_direct_batch_link, false),
              'candidate_scope_link_count', COALESCE(v_candidate_scope_link_count, 0),
              'allocation_link_count', COALESCE(v_allocation_link_count, 0),
              'item_link_count', COALESCE(v_item_link_count, 0)
            )::text;
  END IF;

  SELECT latest_operation.id
  INTO v_latest_draft_create_operation_id
  FROM public.banking_pay_operations AS latest_operation
  WHERE UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
    AND (
      latest_operation.pay_batch_id = p_pay_batch_id
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_scope AS latest_scope_row
        WHERE latest_scope_row.operation_id = latest_operation.id
          AND latest_scope_row.pay_batch_id = p_pay_batch_id
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS latest_allocation_row
        WHERE latest_allocation_row.operation_id = latest_operation.id
          AND latest_allocation_row.pay_batch_id = p_pay_batch_id
      )
    )
  ORDER BY latest_operation.updated_at_utc DESC NULLS LAST,
           latest_operation.created_at_utc DESC NULLS LAST,
           latest_operation.id DESC
  LIMIT 1;

  IF v_operation_direct_batch_link IS NOT TRUE
     AND COALESCE(v_candidate_scope_link_count, 0) = 0
     AND COALESCE(v_allocation_link_count, 0) = 0
     AND COALESCE(v_item_link_count, 0) = 0
     AND v_latest_draft_create_operation_id IS DISTINCT FROM p_operation_id THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_BATCH_LINK_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_BATCH_LINK_MISSING',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
              'candidate_scope_link_count', COALESCE(v_candidate_scope_link_count, 0),
              'allocation_link_count', COALESCE(v_allocation_link_count, 0),
              'item_link_count', COALESCE(v_item_link_count, 0),
              'latest_draft_create_operation_id', CASE WHEN v_latest_draft_create_operation_id IS NULL THEN NULL ELSE v_latest_draft_create_operation_id::text END
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_transfer_row_count
  FROM public.pay_bank_transfers AS transfer_row
  WHERE transfer_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_transfer_scope_count
  FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
  WHERE transfer_scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_provider_attempt_count
  FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
  WHERE provider_attempt_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_bank_transfer_event_count
  FROM public.pay_bank_transfer_events AS transfer_event_row
  WHERE transfer_event_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_auth_request_count
  FROM public.pay_batch_auth_requests AS auth_request_row
  WHERE auth_request_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_auth_action_count
  FROM public.pay_batch_auth_actions AS auth_action_row
  JOIN public.pay_batch_auth_requests AS auth_action_request_row
    ON auth_action_request_row.id = auth_action_row.auth_request_id
  WHERE auth_action_request_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_remittance_scope_count
  FROM public.banking_pay_operation_remittance_scope AS remittance_scope_row
  WHERE remittance_scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_settlement_scope_count
  FROM public.banking_pay_operation_settlement_scope AS settlement_scope_row
  WHERE settlement_scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_correction_request_count
  FROM public.pay_payment_correction_requests AS correction_request_row
  WHERE correction_request_row.pay_batch_id = p_pay_batch_id
    AND UPPER(BTRIM(COALESCE(correction_request_row.status, ''))) NOT IN ('CANCELLED', 'CANCELED', 'FAILED', 'FAILED_FINAL');

  SELECT COUNT(*)::integer
  INTO v_committed_reservation_count
  FROM public.pay_advance_reservations AS reservation_row
  WHERE reservation_row.pay_batch_id = p_pay_batch_id
    AND (
      reservation_row.committed_at_utc IS NOT NULL
      OR reservation_row.settled_at_utc IS NOT NULL
      OR UPPER(BTRIM(COALESCE(reservation_row.status, ''))) IN ('COMMITTED', 'SETTLED', 'PAID')
    );

  v_submission_artifact_count := COALESCE(v_transfer_row_count, 0)
    + COALESCE(v_transfer_scope_count, 0)
    + COALESCE(v_provider_attempt_count, 0)
    + COALESCE(v_bank_transfer_event_count, 0)
    + COALESCE(v_auth_request_count, 0)
    + COALESCE(v_auth_action_count, 0)
    + COALESCE(v_remittance_scope_count, 0)
    + COALESCE(v_settlement_scope_count, 0)
    + COALESCE(v_correction_request_count, 0)
    + COALESCE(v_committed_reservation_count, 0);

  v_batch_submission_flag_count := 0;
  IF NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF v_batch_row.monzo_confirmed_at_utc IS NOT NULL THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF COALESCE(jsonb_typeof(v_batch_row.bank_csv_export_json), 'null') = 'object'
     AND v_batch_row.bank_csv_export_json <> '{}'::jsonb THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF COALESCE(jsonb_typeof(v_batch_row.execution_intent_json), 'null') = 'object'
     AND v_batch_row.execution_intent_json <> '{}'::jsonb THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF COALESCE(jsonb_typeof(v_batch_row.settlement_confirmation_json), 'null') = 'object'
     AND v_batch_row.settlement_confirmation_json <> '{}'::jsonb THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;

  IF COALESCE(v_submission_artifact_count, 0) > 0 OR COALESCE(v_batch_submission_flag_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SUBMISSION_EVIDENCE_PRESENT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SUBMISSION_EVIDENCE_PRESENT',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'transfer_row_count', COALESCE(v_transfer_row_count, 0),
              'transfer_scope_count', COALESCE(v_transfer_scope_count, 0),
              'provider_attempt_count', COALESCE(v_provider_attempt_count, 0),
              'bank_transfer_event_count', COALESCE(v_bank_transfer_event_count, 0),
              'auth_request_count', COALESCE(v_auth_request_count, 0),
              'auth_action_count', COALESCE(v_auth_action_count, 0),
              'remittance_scope_count', COALESCE(v_remittance_scope_count, 0),
              'settlement_scope_count', COALESCE(v_settlement_scope_count, 0),
              'correction_request_count', COALESCE(v_correction_request_count, 0),
              'committed_reservation_count', COALESCE(v_committed_reservation_count, 0),
              'batch_submission_flag_count', COALESCE(v_batch_submission_flag_count, 0)
            )::text;
  END IF;

  SELECT CASE
           WHEN COUNT(*) = 0 THEN true
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%CANCELLED%'), false)
         END
  INTO v_batch_status_cancelled_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'pay_batches'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'pay_batches_status_chk_v2';

  IF v_batch_status_cancelled_allowed IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_CANCELLED_STATUS_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_CANCELLED_STATUS_NOT_ALLOWED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  SELECT CASE
           WHEN COUNT(*) = 0 THEN true
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%FAILED%'), false)
         END
  INTO v_candidate_scope_failed_status_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'banking_pay_operation_candidate_scope'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'banking_pay_operation_candidate_scope_status_chk';

  IF v_candidate_scope_failed_status_allowed IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SCOPE_FAILED_STATUS_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SCOPE_FAILED_STATUS_NOT_ALLOWED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  SELECT CASE
           WHEN COUNT(*) = 0 THEN false
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%FAILED%'), false)
         END
  INTO v_allocation_failed_status_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'banking_pay_operation_candidate_allocation_rows'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'banking_pay_operation_candidate_allocation_status_chk';

  SELECT CASE
           WHEN COUNT(*) = 0 THEN false
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%RELEASED%'), false)
         END
  INTO v_reservation_released_status_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'pay_advance_reservations'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'pay_advance_reservations_status_chk';

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public.pay_batch_candidates AS candidate_count_row
  WHERE candidate_count_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE COALESCE(item_count_row.is_voided, false) = false)::integer
  INTO v_item_count,
       v_active_item_count
  FROM public.pay_batch_items AS item_count_row
  JOIN public.pay_batch_candidates AS candidate_count_row
    ON candidate_count_row.id = item_count_row.pay_batch_candidate_id
  WHERE candidate_count_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_reservation_count
  FROM public.pay_advance_reservations AS reservation_count_row
  WHERE reservation_count_row.pay_batch_id = p_pay_batch_id;

  WITH released_reservations AS (
    UPDATE public.pay_advance_reservations AS reservation_update
    SET status = CASE
          WHEN v_reservation_released_status_allowed IS TRUE
               AND UPPER(BTRIM(COALESCE(reservation_update.status, ''))) = 'RESERVED' THEN 'RELEASED'
          ELSE reservation_update.status
        END,
        released_at_utc = COALESCE(reservation_update.released_at_utc, v_now),
        released_reason = COALESCE(
          NULLIF(BTRIM(reservation_update.released_reason), ''),
          LEFT('Failed draft creation cleanup: ' || v_reason, 500)
        ),
        updated_by_user_id = COALESCE(v_effective_actor_user_id, reservation_update.updated_by_user_id)
    WHERE reservation_update.pay_batch_id = p_pay_batch_id
      AND reservation_update.committed_at_utc IS NULL
      AND reservation_update.settled_at_utc IS NULL
      AND reservation_update.released_at_utc IS NULL
    RETURNING reservation_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_reservations_released
  FROM released_reservations AS released_reservation_row;

  WITH voided_items AS (
    UPDATE public.pay_batch_items AS item_update
    SET is_voided = true,
        updated_at = v_now
    FROM public.pay_batch_candidates AS candidate_for_item
    WHERE candidate_for_item.id = item_update.pay_batch_candidate_id
      AND candidate_for_item.pay_batch_id = p_pay_batch_id
      AND COALESCE(item_update.is_voided, false) = false
    RETURNING item_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_items_voided
  FROM voided_items AS voided_item_row;

  WITH failed_scopes AS (
    UPDATE public.banking_pay_operation_candidate_scope AS scope_update
    SET status = 'FAILED',
        pay_batch_id = COALESCE(scope_update.pay_batch_id, p_pay_batch_id),
        effective_summary_fragment_json = jsonb_strip_nulls(
          COALESCE(scope_update.effective_summary_fragment_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_creation_failed', true,
            'draft_creation_failed_partial', true,
            'draft_creation_failed_operation_id', p_operation_id::text,
            'draft_creation_failed_pay_batch_id', p_pay_batch_id::text,
            'draft_creation_failed_phase', v_failure_phase,
            'draft_creation_failed_code', v_failure_code,
            'draft_creation_failed_at_utc', v_now::text
          )
        ),
        candidate_totals_json = jsonb_strip_nulls(
          COALESCE(scope_update.candidate_totals_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_creation_failed', true,
            'draft_creation_failed_partial', true,
            'batch_action_blocked', true,
            'normal_draft_actions_blocked', true,
            'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT'
          )
        ),
        updated_at_utc = v_now
    WHERE scope_update.operation_id = p_operation_id
      AND (
        scope_update.pay_batch_id = p_pay_batch_id
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS scope_allocation_row
          WHERE scope_allocation_row.operation_id = p_operation_id
            AND scope_allocation_row.candidate_scope_id = scope_update.id
            AND scope_allocation_row.pay_batch_id = p_pay_batch_id
        )
      )
    RETURNING scope_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_candidate_scopes_failed
  FROM failed_scopes AS failed_scope_row;

  WITH updated_allocations AS (
    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET status = CASE
          WHEN v_allocation_failed_status_allowed IS TRUE THEN 'FAILED'
          ELSE allocation_update.status
        END,
        allocation_basis_json = jsonb_strip_nulls(
          COALESCE(allocation_update.allocation_basis_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_creation_failed', true,
            'draft_creation_failed_partial', true,
            'draft_creation_failed_operation_id', p_operation_id::text,
            'draft_creation_failed_pay_batch_id', p_pay_batch_id::text,
            'draft_creation_failed_phase', v_failure_phase,
            'draft_creation_failed_code', v_failure_code,
            'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
            'allocation_status_failed_written', v_allocation_failed_status_allowed IS TRUE,
            'draft_creation_failed_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE allocation_update.operation_id = p_operation_id
      AND (
        allocation_update.pay_batch_id = p_pay_batch_id
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS allocation_scope_row
          WHERE allocation_scope_row.id = allocation_update.candidate_scope_id
            AND allocation_scope_row.operation_id = p_operation_id
            AND allocation_scope_row.pay_batch_id = p_pay_batch_id
        )
      )
    RETURNING allocation_update.id,
              allocation_update.status
  )
  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_allocation_row.status, ''))) = 'FAILED')::integer
  INTO v_allocation_rows_updated,
       v_allocation_rows_failed
  FROM updated_allocations AS updated_allocation_row;

  UPDATE public.pay_batches AS batch_update
  SET status = 'CANCELLED',
      cancelled_at_utc = COALESCE(batch_update.cancelled_at_utc, v_now),
      cancelled_by_user_id = CASE
        WHEN batch_update.cancelled_by_user_id IS NOT NULL THEN batch_update.cancelled_by_user_id
        ELSE v_effective_actor_user_id
      END,
      cancel_reason = COALESCE(NULLIF(BTRIM(batch_update.cancel_reason), ''), v_reason),
      schedule_kind = NULL,
      scheduled_at_utc = NULL,
      scheduled_by_user_id = NULL,
      funding_account_ref = NULL,
      funds_warning_hours_json = NULL,
      execution_commit_state = CASE
        WHEN NULLIF(BTRIM(COALESCE(batch_update.execution_commit_state, '')), '') IS NULL THEN 'NOT_SUBMITTED'
        ELSE batch_update.execution_commit_state
      END
  WHERE batch_update.id = p_pay_batch_id
  RETURNING batch_update.*
  INTO v_batch_row_after;

  v_batch_status_after := UPPER(BTRIM(COALESCE(v_batch_row_after.status, '')));

  v_cleanup_counts_json := jsonb_build_object(
    'candidate_count', COALESCE(v_candidate_count, 0),
    'item_count', COALESCE(v_item_count, 0),
    'active_item_count_before', COALESCE(v_active_item_count, 0),
    'item_rows_voided', COALESCE(v_items_voided, 0),
    'reservation_count', COALESCE(v_reservation_count, 0),
    'reservations_released', COALESCE(v_reservations_released, 0),
    'candidate_scopes_failed', COALESCE(v_candidate_scopes_failed, 0),
    'allocation_rows_updated', COALESCE(v_allocation_rows_updated, 0),
    'allocation_rows_failed', COALESCE(v_allocation_rows_failed, 0)
  );

  v_cleanup_result_json := jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'status_before', v_batch_status_before,
      'status_after', v_batch_status_after,
      'execution_commit_state_before', NULLIF(v_execution_commit_state_before, ''),
      'execution_commit_state_after', v_batch_row_after.execution_commit_state
    )
    || jsonb_build_object(
      'item_count', COALESCE(v_item_count, 0),
      'candidate_count', COALESCE(v_candidate_count, 0),
      'reservations_released', COALESCE(v_reservations_released, 0),
      'item_rows_voided', COALESCE(v_items_voided, 0),
      'candidate_scopes_failed', COALESCE(v_candidate_scopes_failed, 0),
      'allocation_rows_updated', COALESCE(v_allocation_rows_updated, 0),
      'allocation_rows_failed', COALESCE(v_allocation_rows_failed, 0)
    )
    || jsonb_build_object(
      'draft_creation_failed', true,
      'draft_creation_failed_partial', true,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true,
      'failure_code', v_failure_code,
      'failure_phase', v_failure_phase,
      'reason', v_reason,
      'policy_x_checked', true
    )
    || jsonb_build_object(
      'source_workbench_session_id', v_operation_row.workbench_session_id::text,
      'source_snapshot_run_id', v_batch_snapshot_run_id_text,
      'source_session_version', v_batch_session_version_text,
      'expected_source_session_version', v_expected_session_version_text,
      'session_version_direct_link_exception_used', COALESCE(v_session_version_direct_link_exception_used, false),
      'operation_direct_batch_link', COALESCE(v_operation_direct_batch_link, false),
      'candidate_scope_link_count', COALESCE(v_candidate_scope_link_count, 0),
      'allocation_link_count', COALESCE(v_allocation_link_count, 0),
      'item_link_count', COALESCE(v_item_link_count, 0),
      'allocation_status_failed_allowed', v_allocation_failed_status_allowed,
      'reservation_status_released_allowed', v_reservation_released_status_allowed,
      'cleaned_at_utc', v_now::text,
      'counts', v_cleanup_counts_json
    )
  );

  v_operation_progress_patch_json := jsonb_strip_nulls(
    jsonb_build_object(
      'draft_creation_failed_partial', true,
      'failed_partial_cleanup_status', 'ABORTED',
      'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'failed_partial_cleanup_pay_batch_id', p_pay_batch_id::text,
      'failed_partial_cleanup_at_utc', v_now::text,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true,
      'created_pay_batch_ids', jsonb_build_array(p_pay_batch_id::text)
    )
    || jsonb_build_object(
      'failed_partial_cleanup_result', v_cleanup_result_json,
      'failed_partial_cleanup_summary_refreshed', true
    )
  );

  v_operation_error_patch_json := jsonb_strip_nulls(
    jsonb_build_object(
      'draft_creation_failed_partial', true,
      'failed_partial_cleanup_status', 'ABORTED',
      'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'failed_partial_cleanup_pay_batch_id', p_pay_batch_id::text,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true,
      'cleanup_failure_code', v_failure_code,
      'cleanup_failure_phase', v_failure_phase
    )
  );

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || v_operation_progress_patch_json
      ),
      error_json = jsonb_strip_nulls(
        COALESCE(operation_update.error_json, '{}'::jsonb)
        || v_operation_error_patch_json
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  PERFORM public.pay_batch_display_summary_refresh(p_pay_batch_id);

  v_signal_scope_json := jsonb_strip_nulls(
    jsonb_build_object(
      'operation_id', p_operation_id::text,
      'operation_type', 'DRAFT_CREATE',
      'pay_batch_id', p_pay_batch_id::text,
      'cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'draft_creation_failed', true,
      'draft_creation_failed_partial', true,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true
    )
    || jsonb_build_object(
      'failure_phase', v_failure_phase,
      'failure_code', v_failure_code,
      'status_before', v_batch_status_before,
      'status_after', v_batch_status_after,
      'execution_commit_state_before', NULLIF(v_execution_commit_state_before, ''),
      'execution_commit_state_after', v_batch_row_after.execution_commit_state,
      'counts', v_cleanup_counts_json,
      'cleaned_at_utc', v_now::text
    )
  );

  SELECT public.banking_pay_batch_signal_touch(
    p_pay_batch_id := p_pay_batch_id,
    p_change_reason := 'DRAFT_CREATE_FAILED_PARTIAL_ABORTED',
    p_change_source := 'pay_batch_abort_failed_draft_create_partial',
    p_change_scope_json := v_signal_scope_json,
    p_touch_payment_status := true,
    p_touch_correction_progress := true,
    p_touch_alerts := true,
    p_touch_overview := true
  )
  INTO v_signal_result_json;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'failed_partial_cleanup_signal_version', v_signal_result_json->>'version'
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN v_cleanup_result_json
    || jsonb_build_object(
      'signal', COALESCE(v_signal_result_json, '{}'::jsonb),
      'display_summary_refreshed', true
    );
END;
$function$;

-- pay_batch_apply_finance_adjustments(uuid,text,uuid,numeric,date,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_apply_finance_adjustments(p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid DEFAULT NULL::uuid, p_vat_rate_pct numeric DEFAULT NULL::numeric, p_week_start date DEFAULT NULL::date, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_vat_rate_pct numeric := p_vat_rate_pct;
  v_week_start date := p_week_start;
  v_now_utc timestamptz := now();
  v_stage text := NULL;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_client_filter_single uuid := NULL::uuid;
  v_rows_ins_loan_payout_items integer := 0;
  v_rows_ins_manual_credit_payout_items integer := 0;
  v_rows_ins_underpayment_payout_items integer := 0;
  v_rows_ins_overpayment_recovery_items integer := 0;
  v_rows_ins_operation_planned_overpayment_items integer := 0;
  v_rows_upd_candidates_overpayment_recovery_taken integer := 0;
  v_rows_ins_debt_items integer := 0;
  v_rows_upd_candidates_debt integer := 0;
  v_rows_ins_loan_items integer := 0;
  v_rows_upd_candidates_loan integer := 0;
  v_rows_staged_recovery_template_rows integer := 0;
  v_rows_staged_manual_debt_template_rows integer := 0;
  v_rows_staged_loan_template_rows integer := 0;
  v_rows_staged_overpayment_template_rows integer := 0;
  v_rows_staged_paye_manual_debt_template_rows integer := 0;
  v_rows_ins_dormant_recovery_template_items integer := 0;
  v_rows_ins_dormant_manual_debt_template_items integer := 0;
  v_rows_ins_dormant_loan_template_items integer := 0;
  v_rows_ins_dormant_overpayment_template_items integer := 0;
  v_rows_skipped_dormant_recovery_template_items integer := 0;
  v_rows_skipped_dormant_manual_debt_template_items integer := 0;
  v_rows_skipped_dormant_loan_template_items integer := 0;
  v_rows_skipped_dormant_overpayment_template_items integer := 0;
  v_missing_materialised_manual_debt_template_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_staged_manual_debt_template_rows_by_candidate jsonb := '{}'::jsonb;
  v_payout_instruction_freeze_rec record;
  v_operation_allocation_total integer := 0;
  v_operation_allocation_done integer := 0;
  v_operation_mismatch_details jsonb := '{}'::jsonb;
  v_operation_plan_mismatch_details jsonb := '{}'::jsonb;
  v_operation_plan_drift_details jsonb := '[]'::jsonb;
  v_canonical_provenance_mismatch_details jsonb := '[]'::jsonb;
BEGIN
  perform public._ctms_assert_pay_batch_mutable_v1(p_pay_batch_id,'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS');
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );

    SELECT settings_context.vat_rate_pct, settings_context.pay_week_start
    INTO v_vat_rate_pct, v_week_start
    FROM pg_temp.tmp_pay_build_settings_context AS settings_context
    LIMIT 1;
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;
  IF v_vat_rate_pct IS NULL THEN
    RAISE EXCEPTION 'vat_rate_pct is required';
  END IF;
  IF v_week_start IS NULL THEN
    RAISE EXCEPTION 'week_start is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_finance_case_components_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_finance_case_components_ctx temp table is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_oneoff_payout_bank_details_ctx temp table is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_timesheet_snapshots_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_timesheet_snapshots_ctx temp table is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_recovery_template_rows') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_recovery_template_rows temp table is required';
  END IF;
  SELECT COALESCE(array_agg(distinct spr.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM pg_temp.tmp_pay_build_selected_preview_rows spr;

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer,
           count(*) FILTER (
             WHERE allocation_row.status = 'ITEM_CREATED'
               AND allocation_row.pay_batch_item_id IS NOT NULL
               AND EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS linked_done_item
                 JOIN public.pay_batch_candidates AS linked_done_candidate
                   ON linked_done_candidate.id = linked_done_item.pay_batch_candidate_id
                 WHERE linked_done_item.id = allocation_row.pay_batch_item_id
                   AND linked_done_candidate.pay_batch_id = v_batch_id
                   AND linked_done_candidate.candidate_id = allocation_row.candidate_id
                   AND coalesce(linked_done_item.is_voided, false) = false
                   AND (
                     (
                       UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
                       AND linked_done_item.item_type = UPPER(BTRIM(COALESCE(allocation_row.allocation_type, '')))
                     )
                     OR (
                       UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) NOT IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
                       AND linked_done_item.item_type IN ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT')
                     )
                   )
               )
           )::integer
    INTO v_operation_allocation_total, v_operation_allocation_done
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_id = ANY(v_candidate_ids)
      AND allocation_row.pay_channel = v_scope
      AND allocation_row.finance_case_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN (
        'OVERPAYMENT_RECOVERY',
        'MANUAL_DEBT_RECOVERY',
        'PAYMENT_ADVANCE_REPAYMENT',
        'LOAN_REPAYMENT',
        'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
        'MANUAL_CREDIT_PAYOUT',
        'LOAN_PAYOUT',
        'UNDERPAYMENT_PAYMENT'
      );

    IF coalesce(v_operation_allocation_total, 0) > 0
       AND coalesce(v_operation_allocation_total, 0) = coalesce(v_operation_allocation_done, 0) THEN
      RETURN jsonb_build_object(
        'ok', true,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'applied_count', 0,
        'reused_count', v_operation_allocation_done,
        'skipped_count', 0,
        'failed_count', 0,
        'mismatch_details', '{}'::jsonb
      );
    END IF;

    -- Register the exact transaction-local Draft finance authority before
    -- either the normal materialisation path or the bounded partial-retry
    -- cleanup can touch pay_batch_items.  ASSERT_COMPLETE at the end of this
    -- function must never depend on the partial-retry branch having run.
    PERFORM private.pay_workbench_draft_expected_effects_v1(
      p_operation_id,'APPLY_FINANCE_ADJUSTMENTS','REGISTER',
      jsonb_build_array(
        jsonb_build_object('relation_name','pay_batch_items','operation','INSERT'),
        jsonb_build_object('relation_name','pay_batch_items','operation','UPDATE'),
        jsonb_build_object('relation_name','pay_batch_items','operation','DELETE')
      ),jsonb_build_object('pay_batch_id',p_pay_batch_id)
    );

    IF coalesce(v_operation_allocation_done, 0) > 0
       AND coalesce(v_operation_allocation_done, 0) < coalesce(v_operation_allocation_total, 0) THEN
      IF EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
        JOIN public.pay_batch_items AS linked_item
          ON linked_item.id = allocation_row.pay_batch_item_id
        WHERE allocation_row.operation_id = p_operation_id
          AND allocation_row.candidate_id = ANY(v_candidate_ids)
          AND allocation_row.pay_channel = v_scope
          AND allocation_row.finance_case_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN (
            'OVERPAYMENT_RECOVERY',
            'MANUAL_DEBT_RECOVERY',
            'PAYMENT_ADVANCE_REPAYMENT',
            'LOAN_REPAYMENT',
            'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
            'MANUAL_CREDIT_PAYOUT',
            'LOAN_PAYOUT',
            'UNDERPAYMENT_PAYMENT'
          )
          AND allocation_row.status = 'ITEM_CREATED'
          AND allocation_row.pay_batch_item_id IS NOT NULL
          AND linked_item.reservation_id IS NOT NULL
        LIMIT 1
      ) THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
          'code', 'OPERATION_ALLOCATION_PARTIAL_RETRY_AFTER_RESERVATION',
          'message', 'pay_batch_apply_finance_adjustments cannot safely retry a partially-linked finance chunk after reservations have been created',
          'pay_batch_id', v_batch_id::text,
          'operation_id', p_operation_id::text,
          'pay_channel_scope', v_scope
        )::text;
      END IF;

      DELETE FROM public.pay_batch_items AS linked_item_delete
      USING public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.candidate_id = ANY(v_candidate_ids)
        AND allocation_row.pay_channel = v_scope
        AND allocation_row.finance_case_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT',
          'LOAN_REPAYMENT',
          'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
          'MANUAL_CREDIT_PAYOUT',
          'LOAN_PAYOUT',
        'UNDERPAYMENT_PAYMENT'
        )
        AND allocation_row.status = 'ITEM_CREATED'
        AND allocation_row.pay_batch_item_id = linked_item_delete.id
        AND linked_item_delete.reservation_id IS NULL;

      UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_reset
      SET
        status = 'PENDING',
        pay_batch_item_id = NULL,
        updated_at_utc = now()
      WHERE allocation_reset.operation_id = p_operation_id
        AND allocation_reset.candidate_id = ANY(v_candidate_ids)
        AND allocation_reset.pay_channel = v_scope
        AND allocation_reset.finance_case_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(allocation_reset.allocation_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT',
          'LOAN_REPAYMENT',
          'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
          'MANUAL_CREDIT_PAYOUT',
          'LOAN_PAYOUT',
        'UNDERPAYMENT_PAYMENT'
        )
        AND allocation_reset.status = 'ITEM_CREATED';

      v_operation_allocation_done := 0;
    END IF;
  END IF;


  IF EXISTS (
    WITH finance_case_draft_scope AS (
      SELECT DISTINCT
        spr.finance_case_id AS finance_case_id,
        spr.candidate_id AS candidate_id,
        upper(coalesce(nullif(spr.pay_channel, ''), v_scope)) AS target_pay_channel,
        spr.line_type AS source_line_type
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS spr
      WHERE spr.draftable = true
        AND spr.finance_case_id IS NOT NULL
        AND spr.candidate_id = ANY(v_candidate_ids)
        AND (v_client_filter_single IS NULL OR spr.client_id = v_client_filter_single)
        AND spr.line_type IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY',
          'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
          'MANUAL_CREDIT_PAYOUT',
          'UNDERPAYMENT_PAYMENT'
        )

      UNION

      SELECT DISTINCT
        template_rows.finance_case_id AS finance_case_id,
        template_rows.candidate_id AS candidate_id,
        CASE
          WHEN upper(coalesce(template_rows.pay_channel, '')) IN ('PAYE', 'UMBRELLA') THEN upper(coalesce(template_rows.pay_channel, ''))
          WHEN coalesce(btrim(coalesce(template_rows.pay_channel, '')), '') = '' THEN v_scope
          ELSE upper(coalesce(template_rows.pay_channel, ''))
        END AS target_pay_channel,
        template_rows.recovery_family AS source_line_type
      FROM pg_temp.tmp_pay_build_recovery_template_rows AS template_rows
      WHERE template_rows.finance_case_id IS NOT NULL
        AND template_rows.candidate_id = ANY(v_candidate_ids)
        AND template_rows.recovery_family IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY'
        )
    )
    SELECT 1
    FROM finance_case_draft_scope AS draft_scope
    JOIN public.pay_advances AS finance_case
      ON finance_case.id = draft_scope.finance_case_id
     AND finance_case.case_type IN (
       'OVERPAYMENT'::public.pay_finance_case_type_enum,
       'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
       'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum,
       'UNDERPAYMENT'::public.pay_finance_case_type_enum
     )
     AND finance_case.status = 'ACTIVE'::public.pay_advance_status_enum
    JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.finance_case_id = draft_scope.finance_case_id
     AND finance_component.closed_at_utc IS NULL
    WHERE draft_scope.target_pay_channel IN ('PAYE', 'UMBRELLA')
      AND finance_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      AND round(coalesce(finance_component.remaining_source_amount, 0), 2) > 0
      AND upper(coalesce(finance_component.source_pay_method, '')) IN ('PAYE', 'UMBRELLA')
      AND upper(coalesce(finance_component.source_pay_method, '')) <> draft_scope.target_pay_channel
      AND (
        coalesce(finance_component.is_resolution_stale, false) = true
        OR nullif(btrim(coalesce(finance_component.saved_target_pay_method, '')), '') IS NULL
        OR upper(coalesce(finance_component.saved_target_pay_method, '')) <> draft_scope.target_pay_channel
        OR finance_component.saved_resolution_mode IS NULL
        OR jsonb_typeof(coalesce(finance_component.saved_resolution_payload_json, 'null'::jsonb)) <> 'object'
        OR jsonb_typeof(coalesce(finance_component.saved_resolution_result_json, 'null'::jsonb)) <> 'object'
        OR nullif(btrim(coalesce(finance_component.resolution_fingerprint, '')), '') IS NULL
      )
    LIMIT 1
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
      'code', 'TAXABLE_CHANNEL_RESTRUCTURE_REQUIRED',
      'message', 'pay_batch_apply_finance_adjustments: taxable PAYE/Umbrella channel restructure is required before finance items can be drafted',
      'pay_batch_id', v_batch_id::text,
      'pay_channel_scope', v_scope
    )::text;
  END IF;


v_stage := 'STAGE_12C_APPLY_LOAN_PAYOUTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with safe_case_rows as (
    select
      spr.preview_row_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(spr.pay_channel,'')) as pay_channel,
      upper(coalesce(spr.paye_treatment,'')) as paye_treatment,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      abs(round(coalesce(spr.preview_amount_ex_vat, 0), 2))::numeric(12,2) as payout_total_target_ex
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    where spr.draftable = true
      and spr.line_type = 'LOAN_PAYOUT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
  ),
  candidate_due as (
    select
      pbc.id as pay_batch_candidate_id,
      scr.preview_row_id,
      scr.candidate_id,
      scr.pay_channel,
      case when scr.pay_channel = 'UMBRELLA' then c.umbrella_id else null end as umbrella_id,
      scr.finance_case_id,
      scr.linked_timesheet_id,
      scr.paye_treatment,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.payout_total_target_ex
    from safe_case_rows scr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = scr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = scr.candidate_id
  ),
  case_component_base as (
    select
      cd.pay_batch_candidate_id,
      cd.preview_row_id,
      cd.candidate_id,
      cd.pay_channel,
      cd.umbrella_id,
      cd.finance_case_id,
      cd.linked_timesheet_id,
      cd.paye_treatment,
      cd.routing_kind,
      cd.destination_label,
      cd.taxability,
      cd.beneficiary_name,
      cd.masked_bank_account,
      cd.bank_details_hash,
      cd.is_candidate_directed_oneoff_payout,
      cd.appears_on_umbrella_remittance,
      cd.generates_candidate_payment_advice,
      pfc.id as finance_component_id,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      upper(coalesce(pfc.source_pay_method,'')) as source_pay_method,
      pfc.source_basis_json,
      upper(coalesce(pfc.saved_target_pay_method,'')) as saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      round(greatest(coalesce(pfc.source_amount, pfc.remaining_source_amount, 0), 0), 2)::numeric(12,2) as source_amount,
      round(greatest(coalesce(pfc.remaining_source_amount, 0), 0), 2)::numeric(12,2) as remaining_source_amount,
      pfc.allocation_priority_group,
      pfc.allocation_priority_order,
      pfc.created_at_utc as finance_component_created_at,
      cd.payout_total_target_ex,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'ex')::numeric, 2)::numeric(12,2)
        else round(greatest(coalesce(pfc.remaining_source_amount,0),0), 2)::numeric(12,2)
      end as remaining_target_amount_ex_vat,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as remaining_target_amount_vat,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric, 2)::numeric(12,2)
        else round(greatest(coalesce(pfc.remaining_source_amount,0),0), 2)::numeric(12,2)
      end as remaining_target_amount_inc_vat,
      obd.created_by_user_id as bank_details_created_by_user_id,
      obd.updated_by_user_id as bank_details_updated_by_user_id,
      obd.note as bank_details_note
    from candidate_due cd
    join pg_temp.tmp_pay_build_finance_case_components_ctx pfc
      on pfc.finance_case_id = cd.finance_case_id
     and coalesce(pfc.remaining_source_amount, 0) > 0
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = cd.umbrella_id
    left join pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx obd
      on obd.finance_case_id = cd.finance_case_id
  ),
  case_component_due as (
    select
      ccb.*,
      sum(ccb.remaining_target_amount_ex_vat) over (
        partition by ccb.finance_case_id
        order by ccb.allocation_priority_group, ccb.allocation_priority_order, ccb.finance_component_created_at, ccb.finance_component_id
        rows between unbounded preceding and 1 preceding
      )::numeric(12,2) as cum_before_case_target,
      least(
        ccb.remaining_target_amount_ex_vat,
        greatest(ccb.payout_total_target_ex - coalesce(sum(ccb.remaining_target_amount_ex_vat) over (
          partition by ccb.finance_case_id
          order by ccb.allocation_priority_group, ccb.allocation_priority_order, ccb.finance_component_created_at, ccb.finance_component_id
          rows between unbounded preceding and 1 preceding
        ), 0), 0)
      )::numeric(12,2) as take_target_ex
    from case_component_base ccb
  ),
  alloc as (
    select
      ccd.pay_batch_candidate_id,
      ccd.pay_channel,
      ccd.umbrella_id,
      ccd.finance_case_id,
      ccd.linked_timesheet_id,
      ccd.paye_treatment,
      ccd.routing_kind,
      ccd.destination_label,
      ccd.taxability,
      ccd.beneficiary_name,
      ccd.masked_bank_account,
      ccd.bank_details_hash,
      ccd.is_candidate_directed_oneoff_payout,
      ccd.appears_on_umbrella_remittance,
      ccd.generates_candidate_payment_advice,
      ccd.bank_details_created_by_user_id,
      ccd.bank_details_updated_by_user_id,
      ccd.bank_details_note,
      ccd.finance_component_id,
      ccd.component_key_type,
      ccd.component_key_value,
      ccd.classification,
      ccd.source_pay_method,
      ccd.source_basis_json,
      ccd.saved_target_pay_method,
      ccd.saved_resolution_mode,
      ccd.saved_resolution_payload_json,
      ccd.saved_resolution_result_json,
      ccd.source_amount,
      ccd.remaining_source_amount,
      ccd.remaining_target_amount_ex_vat,
      ccd.remaining_target_amount_vat,
      ccd.remaining_target_amount_inc_vat,
      round(ccd.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then least(
          ccd.remaining_source_amount,
          round(ccd.remaining_source_amount * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)
        )::numeric(12,2)
        else 0::numeric(12,2)
      end as take_source_amount,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then round(coalesce(ccd.remaining_target_amount_vat,0) * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as take_target_vat,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then round(coalesce(ccd.remaining_target_amount_inc_vat,0) * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as take_target_inc
    from case_component_due ccd
    where ccd.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    a.pay_batch_candidate_id,
    'LOAN_PAYOUT'::text as item_type,
    a.linked_timesheet_id as timesheet_id,
    null::text as segment_key,
    ('advance:' || a.finance_case_id::text) as source_ref,
    'Payment Advance'::text as description,
    round(a.take_target_ex, 2) as amount_ex_vat,
    round(a.take_target_vat, 2) as amount_vat,
    round(a.take_target_inc, 2) as amount_inc_vat,
    a.pay_channel,
    a.umbrella_id,
    false as is_mismatch,
    a.finance_case_id,
    a.finance_component_id,
    jsonb_build_object(
      'finance_case_id', a.finance_case_id::text,
      'finance_component_id', a.finance_component_id::text,
      'linked_timesheet_id', case when a.linked_timesheet_id is null then null else a.linked_timesheet_id::text end,
      'classification', a.classification::text,
      'source_pay_method', a.source_pay_method,
      'target_pay_method', a.pay_channel,
      'source_basis_json', a.source_basis_json,
      'saved_target_pay_method', a.saved_target_pay_method,
      'saved_resolution_mode', case when a.saved_resolution_mode is null then null else a.saved_resolution_mode::text end,
      'saved_resolution_payload_json', a.saved_resolution_payload_json,
      'saved_resolution_result_json', a.saved_resolution_result_json,
      'reserved_source_amount', round(a.take_source_amount, 2),
      'frozen_target_amount_ex_vat', round(a.take_target_ex, 2),
      'frozen_target_amount_vat', round(a.take_target_vat, 2),
      'frozen_target_amount_inc_vat', round(a.take_target_inc, 2)
    ) as frozen_component_snapshot_json,
    a.component_key_type,
    a.component_key_value,
    a.classification,
    a.source_basis_json,
    a.source_pay_method,
    a.pay_channel,
    a.saved_resolution_mode,
    a.saved_resolution_payload_json,
    a.saved_resolution_result_json,
    round(a.take_source_amount, 2),
    round(a.take_target_ex, 2),
    round(a.take_target_vat, 2),
    round(a.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', a.taxability,
        'routing_kind', a.routing_kind,
        'destination_label', a.destination_label,
        'pay_channel', a.pay_channel,
        'payee_entity_kind', case when a.is_candidate_directed_oneoff_payout then 'CANDIDATE' when a.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', a.beneficiary_name,
        'masked_bank_account', a.masked_bank_account,
        'bank_details_hash', a.bank_details_hash,
        'bank_details_note', a.bank_details_note,
        'bank_details_created_by_user_id', case when a.bank_details_created_by_user_id is null then null else a.bank_details_created_by_user_id::text end,
        'bank_details_updated_by_user_id', case when a.bank_details_updated_by_user_id is null then null else a.bank_details_updated_by_user_id::text end,
        'appears_on_umbrella_remittance', a.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', a.generates_candidate_payment_advice,
        'is_candidate_directed_oneoff_payout', a.is_candidate_directed_oneoff_payout,
        'payee_entity_id', case
          when a.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = a.pay_batch_candidate_id
            limit 1
          )
          when a.routing_kind = 'UMBRELLA_COMPANY' then case when a.umbrella_id is null then null else a.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = a.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case
      when a.pay_channel <> 'PAYE' then 'NONE'
      when a.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_ADD'
      when a.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'NET_ADD'
      else coalesce(nullif(a.paye_treatment,''), 'NET_ADD')
    end as paye_treatment
  from alloc a
  where a.take_target_ex > 0;

  get diagnostics v_rows_ins_loan_payout_items = row_count;


v_stage := 'STAGE_12D_APPLY_MANUAL_CREDIT_PAYOUTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      upper(nullif(btrim(coalesce(comp.comp_json->>'saved_target_pay_method','')), '')) as saved_target_pay_method,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'source_amount')::numeric)
          when coalesce(comp.comp_json->>'source_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'source_amount_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'frozen_source_amount','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'frozen_source_amount')::numeric)
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'remaining_source_amount')::numeric)
          when coalesce(comp.comp_json->>'remaining_source_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'remaining_source_amount_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'source_amount')::numeric)
          when coalesce(comp.comp_json->>'source_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'source_amount_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'frozen_source_amount','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'frozen_source_amount')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.routing_kind,
      n.destination_label,
      n.taxability,
      n.beneficiary_name,
      n.masked_bank_account,
      n.bank_details_hash,
      n.is_candidate_directed_oneoff_payout,
      n.appears_on_umbrella_remittance,
      n.generates_candidate_payment_advice,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', n.saved_resolution_mode_text,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'MANUAL_CREDIT_PAYOUT'::text as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    'Manual credit adjustment payment'::text as description,
    round(fa.take_target_ex, 2) as amount_ex_vat,
    round(fa.take_target_vat, 2) as amount_vat,
    round(fa.take_target_inc, 2) as amount_inc_vat,
    fa.pay_channel,
    fa.umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    fa.finance_case_id,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    round(fa.take_source_amount, 2),
    round(fa.take_target_ex, 2),
    round(fa.take_target_vat, 2),
    round(fa.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', fa.taxability,
        'routing_kind', fa.routing_kind,
        'destination_label', fa.destination_label,
        'pay_channel', fa.pay_channel,
        'payee_entity_kind', case when fa.is_candidate_directed_oneoff_payout then 'CANDIDATE' when fa.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', fa.beneficiary_name,
        'masked_bank_account', fa.masked_bank_account,
        'bank_details_hash', fa.bank_details_hash,
        'appears_on_umbrella_remittance', fa.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', fa.generates_candidate_payment_advice,
        'payee_entity_id', case
          when fa.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
          when fa.routing_kind = 'UMBRELLA_COMPANY' then case when fa.umbrella_id is null then null else fa.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_ADD'
      when fa.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'NET_ADD'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_ADD')
    end as paye_treatment
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_manual_credit_payout_items = row_count;


v_stage := 'STAGE_12E_APPLY_UNDERPAYMENT_PAYMENTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'UNDERPAYMENT_PAYMENT'
      and upper(coalesce(spr.case_type, '')) = 'UNDERPAYMENT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.linked_timesheet_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      upper(nullif(btrim(coalesce(comp.comp_json->>'saved_target_pay_method','')), '')) as saved_target_pay_method,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'target_pay_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.linked_timesheet_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.routing_kind,
      n.destination_label,
      n.taxability,
      n.beneficiary_name,
      n.masked_bank_account,
      n.bank_details_hash,
      n.is_candidate_directed_oneoff_payout,
      n.appears_on_umbrella_remittance,
      n.generates_candidate_payment_advice,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', n.saved_resolution_mode_text,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'UNDERPAYMENT_PAYMENT'::text as item_type,
    fa.linked_timesheet_id as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    'Underpayment payment'::text as description,
    round(fa.take_target_ex, 2) as amount_ex_vat,
    round(fa.take_target_vat, 2) as amount_vat,
    round(fa.take_target_inc, 2) as amount_inc_vat,
    fa.pay_channel,
    fa.umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    fa.finance_case_id,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    round(fa.take_source_amount, 2),
    round(fa.take_target_ex, 2),
    round(fa.take_target_vat, 2),
    round(fa.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', fa.taxability,
        'routing_kind', fa.routing_kind,
        'destination_label', fa.destination_label,
        'pay_channel', fa.pay_channel,
        'payee_entity_kind', case when fa.is_candidate_directed_oneoff_payout then 'CANDIDATE' when fa.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', fa.beneficiary_name,
        'masked_bank_account', fa.masked_bank_account,
        'bank_details_hash', fa.bank_details_hash,
        'appears_on_umbrella_remittance', fa.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', fa.generates_candidate_payment_advice,
        'payee_entity_id', case
          when fa.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
          when fa.routing_kind = 'UMBRELLA_COMPANY' then case when fa.umbrella_id is null then null else fa.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_ADD'
      when fa.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'NET_ADD'
      when coalesce(nullif(fa.paye_treatment,''), 'NET_ADD') in ('GROSS_ADD','NET_ADD','GROSS_DEDUCT','NET_DEDUCT','NONE') then coalesce(nullif(fa.paye_treatment,''), 'NET_ADD')
      else 'NET_ADD'
    end as paye_treatment
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_underpayment_payout_items = row_count;


v_stage := 'STAGE_16AA_APPLY_OVERPAYMENT_RECOVERY';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows_raw as (
    select
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as row_due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json,
      spr.preview_row_id
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'OVERPAYMENT_RECOVERY'
      and p_operation_id is null
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
  ), selected_case_row_caps as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      round(sum(scr.row_due_amount_ex_vat), 2)::numeric(12,2) as selected_row_due_amount_ex_vat
    from selected_case_rows_raw scr
    group by
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id
  ), selected_case_component_rows_raw as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.row_due_amount_ex_vat,
      scr.preview_row_id,
      comp.comp_json,
      coalesce(
        nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''),
        nullif(btrim(coalesce(comp.comp_json->>'component_fingerprint','')), ''),
        md5(comp.comp_json::text)
      ) as component_identity,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'target_pay_ex_vat')::numeric)
          else scr.row_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as component_due_amount_ex_vat,
      row_number() over (
        partition by scr.finance_case_id,
          coalesce(
            nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''),
            nullif(btrim(coalesce(comp.comp_json->>'component_fingerprint','')), ''),
            md5(comp.comp_json::text)
          )
        order by scr.preview_row_id
      ) as component_dedupe_rank
    from selected_case_rows_raw scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
  ), selected_case_component_rows_ranked as (
    select
      component_row.*,
      coalesce(
        sum(component_row.component_due_amount_ex_vat) over (
          partition by component_row.finance_case_id, component_row.preview_row_id
          order by component_row.component_identity
          rows between unbounded preceding and 1 preceding
        ),
        0
      )::numeric(12,2) as prior_component_due_amount_ex_vat
    from selected_case_component_rows_raw component_row
    where component_row.component_dedupe_rank = 1
  ), selected_case_component_rows as (
    select
      ranked_row.pay_batch_candidate_id,
      ranked_row.candidate_id,
      ranked_row.finance_case_id,
      ranked_row.pay_channel,
      ranked_row.paye_treatment,
      ranked_row.umbrella_id,
      ranked_row.row_due_amount_ex_vat,
      ranked_row.preview_row_id,
      ranked_row.component_identity,
      greatest(
        least(
          ranked_row.component_due_amount_ex_vat,
          greatest(
            ranked_row.row_due_amount_ex_vat - ranked_row.prior_component_due_amount_ex_vat,
            0
          )
        ),
        0
      )::numeric(12,2) as component_due_amount_ex_vat,
      jsonb_strip_nulls(
        ranked_row.comp_json
        || jsonb_build_object(
          'uncapped_preview_due_amount_ex_vat', round(ranked_row.component_due_amount_ex_vat, 2),
          'preview_due_amount_ex_vat', round(
            greatest(
              least(
                ranked_row.component_due_amount_ex_vat,
                greatest(
                  ranked_row.row_due_amount_ex_vat - ranked_row.prior_component_due_amount_ex_vat,
                  0
                )
              ),
              0
            ),
            2
          ),
          'allocated_source_due_amount_ex_vat', round(
            case
              when coalesce(ranked_row.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
               and coalesce(ranked_row.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
               and abs((ranked_row.comp_json->>'preview_due_amount_ex_vat')::numeric) > 0
              then
                abs((ranked_row.comp_json->>'allocated_source_due_amount_ex_vat')::numeric)
                * greatest(
                    least(
                      ranked_row.component_due_amount_ex_vat,
                      greatest(
                        ranked_row.row_due_amount_ex_vat - ranked_row.prior_component_due_amount_ex_vat,
                        0
                      )
                    ),
                    0
                  )
                / abs((ranked_row.comp_json->>'preview_due_amount_ex_vat')::numeric)
              else greatest(
                least(
                  ranked_row.component_due_amount_ex_vat,
                  greatest(
                    ranked_row.row_due_amount_ex_vat - ranked_row.prior_component_due_amount_ex_vat,
                    0
                  )
                ),
                0
              )
            end,
            2
          )
        )
      ) as comp_json
    from selected_case_component_rows_ranked ranked_row
  ), selected_case_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      least(
        round(sum(scr.component_due_amount_ex_vat), 2),
        max(src.selected_row_due_amount_ex_vat)
      )::numeric(12,2) as due_amount_ex_vat,
      coalesce(jsonb_agg(scr.comp_json order by scr.preview_row_id, scr.component_identity), '[]'::jsonb) as case_components_json
    from selected_case_component_rows scr
    join selected_case_row_caps src
      on src.pay_batch_candidate_id = scr.pay_batch_candidate_id
     and src.candidate_id = scr.candidate_id
     and src.finance_case_id = scr.finance_case_id
     and src.pay_channel = scr.pay_channel
     and src.paye_treatment = scr.paye_treatment
     and src.umbrella_id is not distinct from scr.umbrella_id
    where round(coalesce(scr.component_due_amount_ex_vat, 0), 2) > 0
    group by
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'target_pay_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(-n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'OVERPAYMENT_RECOVERY' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
    end as paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_overpayment_recovery_items = row_count;

  IF p_operation_id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'allocation_source_key', plan_row.allocation_source_key,
             'frozen_plan_digest', allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,plan_digest}',
             'current_plan_digest', plan_row.plan_digest
           ) ORDER BY plan_row.allocation_source_key), '[]'::jsonb)
    INTO v_operation_plan_drift_details
    FROM private.pay_workbench_draft_finance_item_plan_v1(
      p_operation_id,
      p_candidate_scope_ids
    ) AS plan_row
    JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      ON allocation_row.operation_id = plan_row.operation_id
     AND allocation_row.operation_source_key = plan_row.allocation_source_key
    WHERE plan_row.pay_channel = v_scope
      AND NULLIF(allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,plan_digest}', '')
          IS DISTINCT FROM plan_row.plan_digest;

    IF jsonb_array_length(COALESCE(v_operation_plan_drift_details, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
        'code', 'DRAFT_FINANCE_ITEM_PLAN_DRIFT',
        'message', 'Frozen Draft finance-item plan changed before materialisation',
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_scope,
        'mismatches', v_operation_plan_drift_details
      )::text;
    END IF;

    INSERT INTO public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      operation_source_key
    )
    WITH operation_plan AS (
      SELECT plan_row.*
      FROM private.pay_workbench_draft_finance_item_plan_v1(
        p_operation_id,
        p_candidate_scope_ids
      ) AS plan_row
      WHERE plan_row.planned_item_type = 'OVERPAYMENT_RECOVERY'
        AND plan_row.pay_channel = v_scope
    ), operation_plan_context AS (
      SELECT
        operation_plan.*,
        pay_batch_candidate.id AS pay_batch_candidate_id,
        candidate_context.umbrella_id,
        COALESCE(operation_plan.plan_basis_json->'finance_component', '{}'::jsonb) AS component_json,
        CASE
          WHEN UPPER(BTRIM(COALESCE(operation_plan.plan_basis_json#>>'{finance_component,classification}', ''))) = 'TAXABLE_CHANNEL_SENSITIVE'
            THEN 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          WHEN UPPER(BTRIM(COALESCE(operation_plan.plan_basis_json#>>'{finance_component,classification}', ''))) = 'REIMBURSEMENT_GROSS_FIXED'
            THEN 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
          WHEN UPPER(BTRIM(COALESCE(operation_plan.plan_basis_json#>>'{finance_component,classification}', ''))) = 'NET_PAY_FIXED_RECOVERY'
            THEN 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          ELSE NULL::public.pay_finance_component_classification_enum
        END AS classification
      FROM operation_plan
      JOIN public.pay_batch_candidates AS pay_batch_candidate
        ON pay_batch_candidate.pay_batch_id = v_batch_id
       AND pay_batch_candidate.candidate_id = operation_plan.candidate_id
      JOIN pg_temp.tmp_pay_build_candidates_ctx AS candidate_context
        ON candidate_context.id = operation_plan.candidate_id
    ), materialisation AS (
      SELECT
        operation_plan_context.*,
        CASE
          WHEN operation_plan_context.pay_channel = 'UMBRELLA'
           AND operation_plan_context.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            THEN ROUND((public._pay_umbrella_vat_calc(
                   ABS(operation_plan_context.planned_item_amount),
                   v_vat_rate_pct,
                   COALESCE(umbrella_context.vat_chargeable, false)
                 )->>'vat')::numeric, 2)
          ELSE 0::numeric
        END AS planned_vat_abs
      FROM operation_plan_context
      LEFT JOIN pg_temp.tmp_pay_build_umbrellas_ctx AS umbrella_context
        ON umbrella_context.id = operation_plan_context.umbrella_id
    )
    SELECT
      gen_random_uuid(),
      materialisation.pay_batch_candidate_id,
      materialisation.planned_item_type,
      NULL::uuid,
      NULL::text,
      'advance:' || materialisation.finance_case_id::text,
      ROUND(materialisation.planned_item_amount, 2)::numeric(12,2),
      (-materialisation.planned_vat_abs)::numeric(12,2),
      ROUND(materialisation.planned_item_amount - materialisation.planned_vat_abs, 2)::numeric(12,2),
      v_week_start,
      materialisation.pay_channel,
      CASE WHEN materialisation.pay_channel = 'UMBRELLA' THEN materialisation.umbrella_id ELSE NULL::uuid END,
      (
        materialisation.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND UPPER(COALESCE(materialisation.component_json->>'source_pay_method', '')) <> materialisation.pay_channel
      ),
      false,
      v_now_utc,
      v_now_utc,
      materialisation.finance_case_id,
      NULL::uuid,
      CASE
        WHEN materialisation.pay_channel <> 'PAYE' THEN 'NONE'
        WHEN materialisation.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN 'GROSS_DEDUCT'
        WHEN materialisation.classification IN (
          'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum,
          'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        ) THEN 'NET_DEDUCT'
        ELSE COALESCE(NULLIF(BTRIM(materialisation.plan_basis_json#>>'{line,paye_treatment}'), ''), 'NET_DEDUCT')
      END,
      materialisation.finance_component_id,
      jsonb_strip_nulls(
        materialisation.component_json
        || jsonb_build_object(
          'draft_finance_item_plan_key', materialisation.planned_item_key,
          'draft_finance_item_plan_digest', materialisation.plan_digest,
          'frozen_target_pay_method', materialisation.pay_channel,
          'frozen_source_amount', ROUND(ABS(materialisation.contribution_amount), 2),
          'frozen_target_amount_ex_vat', ROUND(materialisation.planned_item_amount, 2),
          'frozen_target_amount_vat', ROUND(-materialisation.planned_vat_abs, 2),
          'frozen_target_amount_inc_vat', ROUND(materialisation.planned_item_amount - materialisation.planned_vat_abs, 2),
          'component_preview_due_amount_ex_vat', ROUND(ABS(materialisation.contribution_amount), 2)
        )
      ),
      NULLIF(BTRIM(materialisation.component_json->>'component_key_type'), ''),
      COALESCE(NULLIF(BTRIM(materialisation.component_json->>'component_key_value'), ''), 'TOTAL'),
      materialisation.classification,
      COALESCE(materialisation.component_json->'source_basis_json', '{}'::jsonb),
      UPPER(NULLIF(BTRIM(materialisation.component_json->>'source_pay_method'), '')),
      materialisation.pay_channel,
      CASE
        WHEN NULLIF(BTRIM(materialisation.component_json->>'saved_resolution_mode'), '') IS NULL THEN NULL::public.pay_finance_component_resolution_mode_enum
        ELSE (materialisation.component_json->>'saved_resolution_mode')::public.pay_finance_component_resolution_mode_enum
      END,
      CASE
        WHEN jsonb_typeof(materialisation.component_json->'saved_resolution_payload_json') = 'object'
          THEN materialisation.component_json->'saved_resolution_payload_json'
        ELSE NULL::jsonb
      END,
      CASE
        WHEN jsonb_typeof(materialisation.component_json->'saved_resolution_result_json') = 'object'
          THEN materialisation.component_json->'saved_resolution_result_json'
        ELSE NULL::jsonb
      END,
      ROUND(COALESCE(
        CASE
          WHEN COALESCE(materialisation.component_json->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN ABS((materialisation.component_json->>'allocated_source_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        ABS(materialisation.contribution_amount)
      ), 2),
      ROUND(materialisation.planned_item_amount, 2),
      ROUND(-materialisation.planned_vat_abs, 2),
      ROUND(materialisation.planned_item_amount - materialisation.planned_vat_abs, 2),
      materialisation.planned_item_key
    FROM materialisation
    WHERE materialisation.planned_item_amount < 0
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS existing_planned_item
        WHERE existing_planned_item.pay_batch_candidate_id = materialisation.pay_batch_candidate_id
          AND existing_planned_item.operation_source_key = materialisation.planned_item_key
          AND COALESCE(existing_planned_item.is_voided, false) = false
      );

    GET DIAGNOSTICS v_rows_ins_operation_planned_overpayment_items = ROW_COUNT;
    v_rows_ins_overpayment_recovery_items :=
      COALESCE(v_rows_ins_overpayment_recovery_items, 0)
      + COALESCE(v_rows_ins_operation_planned_overpayment_items, 0);
  END IF;


  update public.pay_batch_candidates pbc
  set
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi.amount_ex_vat), 2)
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id = pbc.id
        and pbi.is_voided = false
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_overpayment_recovery_taken = row_count;

  v_rows_ins_debt_items := 0;


v_stage := 'STAGE_16B_APPLY_MANUAL_DEBT_RECOVERY';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      exists (
        select 1
        from public.pay_batch_paye_net_inputs pni_md_exists
        where pni_md_exists.pay_batch_candidate_id = pbc.id
        limit 1
      ) as has_paye_net_input,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'MANUAL_DEBT_RECOVERY'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.has_paye_net_input,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'target_pay_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.has_paye_net_input,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', n.saved_resolution_mode_text,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'MANUAL_DEBT_RECOVERY' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
    end as paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0
    and not (
      upper(coalesce(fa.pay_channel, '')) = 'PAYE'
      and coalesce(fa.has_paye_net_input, false) = false
      and (
        case
          when fa.pay_channel <> 'PAYE' then 'NONE'
          when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
          when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
          else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
        end
      ) = 'NET_DEDUCT'
    );

  get diagnostics v_rows_ins_debt_items = row_count;

v_stage := 'STAGE_16C_APPLY_PAYMENT_ADVANCE_REPAYMENTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'PAYMENT_ADVANCE_REPAYMENT'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'target_pay_ex_vat')::numeric)
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then abs((comp.comp_json->>'preview_due_amount_ex_vat')::numeric)
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(-n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'LOAN_REPAYMENT' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
    end as paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_loan_items = row_count;


  update public.pay_batch_candidates pbc
  set
    loan_repayment_taken = coalesce((
      select round(sum(-pbi.amount_ex_vat), 2)
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id = pbc.id
        and pbi.is_voided = false
        and pbi.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_loan = row_count;

v_stage := 'STAGE_16BD_INSERT_DORMANT_RECOVERY_TEMPLATES';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  create temporary table if not exists pg_temp.tmp_pay_build_dormant_recovery_template_stage (
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    finance_case_id uuid not null,
    recovery_family text not null,
    paye_treatment text null,
    normalized_pay_channel text null,
    umbrella_id uuid null,
    source_ref text null,
    finance_component_id uuid null,
    frozen_component_snapshot_json jsonb null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    frozen_component_classification public.pay_finance_component_classification_enum null,
    frozen_source_basis_json jsonb null,
    frozen_source_pay_method text null,
    frozen_target_pay_method text null,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
    frozen_resolution_payload_json jsonb null,
    frozen_resolution_result_json jsonb null,
    frozen_source_amount numeric(12,2) null,
    frozen_outstanding_amount numeric(12,2) null,
    weekly_due numeric(12,2) null,
    minimum_earnings_threshold numeric null,
    take_home_floor_override numeric null,
    default_take_home_floor numeric null,
    payout_status text null,
    next_due_week_start date null,
    sort_order integer null,
    duplicate_exists boolean not null
  ) on commit drop;
  truncate table pg_temp.tmp_pay_build_dormant_recovery_template_stage;

  insert into pg_temp.tmp_pay_build_dormant_recovery_template_stage (
    pay_batch_candidate_id,
    candidate_id,
    finance_case_id,
    recovery_family,
    paye_treatment,
    normalized_pay_channel,
    umbrella_id,
    source_ref,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_outstanding_amount,
    weekly_due,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor,
    payout_status,
    next_due_week_start,
    sort_order,
    duplicate_exists
  )
  select
    pbc.id as pay_batch_candidate_id,
    tr.candidate_id,
    tr.finance_case_id,
    tr.recovery_family,
    tr.paye_treatment,
    case
      when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
      when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
      else null::text
    end as normalized_pay_channel,
    tr.umbrella_id,
    coalesce(tr.source_ref, 'advance:' || tr.finance_case_id::text) as source_ref,
    tr.finance_component_id,
    tr.frozen_component_snapshot_json,
    tr.frozen_component_key_type,
    tr.frozen_component_key_value,
    tr.frozen_component_classification,
    tr.frozen_source_basis_json,
    tr.frozen_source_pay_method,
    coalesce(tr.frozen_target_pay_method,
      case
        when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
        when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
        else null::text
      end
    ) as frozen_target_pay_method,
    tr.frozen_resolution_mode,
    tr.frozen_resolution_payload_json,
    tr.frozen_resolution_result_json,
    tr.frozen_source_amount,
    tr.frozen_outstanding_amount,
    tr.weekly_due,
    tr.minimum_earnings_threshold,
    tr.take_home_floor_override,
    tr.default_take_home_floor,
    tr.payout_status,
    tr.next_due_week_start,
    tr.sort_order,
    exists (
      select 1
      from public.pay_batch_items as pbi_existing
      where pbi_existing.pay_batch_candidate_id = pbc.id
        and pbi_existing.finance_case_id = tr.finance_case_id
        and pbi_existing.item_type = tr.recovery_family
        and (
          (pbi_existing.finance_component_id is null and tr.finance_component_id is null)
          or pbi_existing.finance_component_id = tr.finance_component_id
        )
        and coalesce(pbi_existing.source_ref, '') = coalesce(coalesce(tr.source_ref, 'advance:' || tr.finance_case_id::text), '')
        and upper(coalesce(pbi_existing.pay_channel, '')) = upper(coalesce(
          case
            when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
            when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
            else null::text
          end,
          ''
        ))
    ) as duplicate_exists
  from pg_temp.tmp_pay_build_recovery_template_rows as tr
  join public.pay_batch_candidates as pbc
    on pbc.pay_batch_id = v_batch_id
   and pbc.candidate_id = tr.candidate_id
  where tr.candidate_id = any(v_candidate_ids)
    and coalesce(
      case
        when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
        when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
        else null::text
      end,
      ''
    ) = v_scope;

  select count(*)::integer
  into v_rows_staged_recovery_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows;

  select count(*)::integer
  into v_rows_staged_manual_debt_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY';

  select count(*)::integer
  into v_rows_staged_loan_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'LOAN_REPAYMENT';

  select count(*)::integer
  into v_rows_staged_overpayment_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'OVERPAYMENT_RECOVERY';

  select count(*)::integer
  into v_rows_staged_paye_manual_debt_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY'
    and stage_rows.normalized_pay_channel = 'PAYE';

  select coalesce(
           jsonb_object_agg(stage_counts.candidate_id::text, to_jsonb(stage_counts.template_count) order by stage_counts.candidate_id::text),
           '{}'::jsonb
         )
  into v_staged_manual_debt_template_rows_by_candidate
  from (
    select stage_rows.candidate_id, count(*)::integer as template_count
    from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
    where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY'
      and stage_rows.normalized_pay_channel = 'PAYE'
    group by stage_rows.candidate_id
  ) as stage_counts;

  select count(*)::integer
  into v_rows_skipped_dormant_recovery_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true;

  select count(*)::integer
  into v_rows_skipped_dormant_manual_debt_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true
    and stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY';

  select count(*)::integer
  into v_rows_skipped_dormant_loan_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true
    and stage_rows.recovery_family = 'LOAN_REPAYMENT';

  select count(*)::integer
  into v_rows_skipped_dormant_overpayment_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true
    and stage_rows.recovery_family = 'OVERPAYMENT_RECOVERY';

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json
  )
  select
    gen_random_uuid() as id,
    stage_rows.pay_batch_candidate_id,
    stage_rows.recovery_family as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    stage_rows.source_ref,
    null::text as description,
    0::numeric(12,2) as amount_ex_vat,
    0::numeric(12,2) as amount_vat,
    0::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    stage_rows.normalized_pay_channel as pay_channel,
    stage_rows.umbrella_id as umbrella_id,
    (
      stage_rows.frozen_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and upper(coalesce(stage_rows.frozen_source_pay_method, '')) <> upper(coalesce(stage_rows.frozen_target_pay_method, stage_rows.normalized_pay_channel, ''))
    ) as is_mismatch,
    true as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    stage_rows.finance_case_id,
    null::uuid as reservation_id,
    case
      when stage_rows.normalized_pay_channel <> 'PAYE' then 'NONE'
      when stage_rows.frozen_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when stage_rows.frozen_component_classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(stage_rows.paye_treatment, 'NET_DEDUCT')
    end as paye_treatment,
    stage_rows.finance_component_id,
    stage_rows.frozen_component_snapshot_json,
    stage_rows.frozen_component_key_type,
    stage_rows.frozen_component_key_value,
    stage_rows.frozen_component_classification,
    jsonb_strip_nulls(
      coalesce(stage_rows.frozen_source_basis_json, '{}'::jsonb)
      || jsonb_build_object(
        'recovery_family', stage_rows.recovery_family,
        'source_ref', stage_rows.source_ref,
        'pay_channel', stage_rows.normalized_pay_channel,
        'frozen_source_pay_method', stage_rows.frozen_source_pay_method,
        'frozen_target_pay_method', stage_rows.frozen_target_pay_method,
        'frozen_source_amount', stage_rows.frozen_source_amount,
        'frozen_outstanding_amount', stage_rows.frozen_outstanding_amount,
        'weekly_due', stage_rows.weekly_due,
        'minimum_earnings_threshold', stage_rows.minimum_earnings_threshold,
        'take_home_floor_override', stage_rows.take_home_floor_override,
        'default_take_home_floor', stage_rows.default_take_home_floor,
        'payout_status', stage_rows.payout_status,
        'next_due_week_start', case when stage_rows.next_due_week_start is null then null else stage_rows.next_due_week_start::text end,
        'sort_order', stage_rows.sort_order
      )
    ) as frozen_source_basis_json,
    stage_rows.frozen_source_pay_method,
    coalesce(stage_rows.frozen_target_pay_method, stage_rows.normalized_pay_channel) as frozen_target_pay_method,
    stage_rows.frozen_resolution_mode,
    stage_rows.frozen_resolution_payload_json,
    stage_rows.frozen_resolution_result_json,
    coalesce(nullif(stage_rows.frozen_outstanding_amount, 0), stage_rows.frozen_source_amount, 0::numeric(12,2)) as frozen_source_amount,
    null::numeric as frozen_target_amount_ex_vat,
    null::numeric as frozen_target_amount_vat,
    null::numeric as frozen_target_amount_inc_vat,
    null::jsonb as payout_instruction_snapshot_json
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false;

  get diagnostics v_rows_ins_dormant_recovery_template_items = row_count;

  select count(*)::integer
  into v_rows_ins_dormant_manual_debt_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false
    and stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY';

  select count(*)::integer
  into v_rows_ins_dormant_loan_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false
    and stage_rows.recovery_family = 'LOAN_REPAYMENT';

  select count(*)::integer
  into v_rows_ins_dormant_overpayment_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false
    and stage_rows.recovery_family = 'OVERPAYMENT_RECOVERY';

  if v_rows_staged_paye_manual_debt_template_rows > 0 then
    select coalesce(array_agg(missing_rows.candidate_id order by missing_rows.candidate_id), ARRAY[]::uuid[])
    into v_missing_materialised_manual_debt_template_candidate_ids
    from (
      select distinct stage_rows.candidate_id
      from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
      where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY'
        and stage_rows.normalized_pay_channel = 'PAYE'
    ) as missing_rows
    left join (
      select distinct pbc.candidate_id
      from public.pay_batch_items as pbi_materialised
      join public.pay_batch_candidates as pbc
        on pbc.id = pbi_materialised.pay_batch_candidate_id
      where pbc.pay_batch_id = v_batch_id
        and pbi_materialised.item_type = 'MANUAL_DEBT_RECOVERY'
        and upper(coalesce(pbi_materialised.pay_channel, '')) = 'PAYE'
    ) as materialised_rows
      on materialised_rows.candidate_id = missing_rows.candidate_id
    where materialised_rows.candidate_id is null;

    if coalesce(array_length(v_missing_materialised_manual_debt_template_candidate_ids, 1), 0) > 0 then
      raise exception 'MANUAL_DEBT_TEMPLATE_NOT_MATERIALISED: staged PAYE manual-debt templates did not materialise into pay_batch_items for candidates %',
        array_to_string(v_missing_materialised_manual_debt_template_candidate_ids, ',');
    end if;
  end if;

v_stage := 'STAGE_16C0_FREEZE_CANONICAL_CORRECTION_PROVENANCE';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  with correction_items as (
    select
      batch_item.id as pay_batch_item_id,
      batch_candidate.candidate_id,
      batch.source_workbench_session_id,
      batch_item.source_ref,
      batch_item.pay_channel,
      batch_item.amount_ex_vat,
      coalesce(operation_line.match_count,0) as operation_line_match_count,
      coalesce(operation_line.canonical_line_json,'{}'::jsonb)
        as operation_canonical_line_json,
      coalesce(
        operation_line.canonical_line_json->'correction_chain_component',
        '{}'::jsonb
      ) as operation_correction_component_json,
      (
        coalesce(operation_line.match_count,0)=1
        and jsonb_typeof(
          operation_line.canonical_line_json
            ->'correction_chain_component'->'resolution_required'
        )='boolean'
        and operation_line.canonical_line_json
              ->'correction_chain_component'->'resolution_required'
            ='false'::jsonb
        and jsonb_typeof(
          operation_line.canonical_line_json->'case_needs_resolution'
        )='boolean'
        and operation_line.canonical_line_json->'case_needs_resolution'
            ='false'::jsonb
      ) as automatic_correction,
      coalesce(
        nullif(batch_item.frozen_component_snapshot_json
          ->>'canonical_correction_key',''),
        nullif(operation_line.canonical_line_json
          ->'correction_chain_component'->>'canonical_correction_key',''),
        nullif(operation_line.canonical_line_json
          ->>'canonical_correction_key',''),
        nullif(batch_item.frozen_resolution_payload_json
          ->>'canonical_correction_key',''),
        nullif(batch_item.frozen_resolution_payload_json
          ->>'resolution_identity_key','')
      ) as canonical_correction_key,
      coalesce(
        nullif(batch_item.frozen_component_snapshot_json
          ->>'resolution_economic_fingerprint',''),
        nullif(operation_line.canonical_line_json
          ->'correction_chain_component'->>'resolution_economic_fingerprint',''),
        nullif(operation_line.canonical_line_json
          ->>'resolution_economic_fingerprint',''),
        nullif(batch_item.frozen_resolution_payload_json
          ->>'resolution_economic_fingerprint','')
      ) as resolution_economic_fingerprint,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json,
      batch_item.frozen_resolution_payload_json,
      batch_item.frozen_resolution_result_json
    from public.pay_batch_items batch_item
    join public.pay_batch_candidates batch_candidate
      on batch_candidate.id=batch_item.pay_batch_candidate_id
    join public.pay_batches batch
      on batch.id=batch_candidate.pay_batch_id
    left join public.banking_pay_operation_candidate_scope operation_scope
      on operation_scope.operation_id=p_operation_id
     and operation_scope.pay_batch_id=batch.id
     and operation_scope.candidate_id=batch_candidate.candidate_id
     and upper(btrim(operation_scope.pay_channel))=
         upper(btrim(batch_item.pay_channel))
    left join lateral (
      select count(*)::integer as match_count,
             (jsonb_agg(canonical_line.value
               order by canonical_line.ordinality)->0)
               as canonical_line_json
      from jsonb_array_elements(coalesce(
        operation_scope.selected_canonical_preview_lines_json,
        '[]'::jsonb
      )) with ordinality as canonical_line(value,ordinality)
      where coalesce(
        nullif(canonical_line.value->>'row_key',''),
        nullif(canonical_line.value->>'source_ref','')
      )=batch_item.source_ref
    ) operation_line on true
    where batch.id=v_batch_id
      and (
        coalesce(batch_item.frozen_source_basis_json
          ->>'source_family_key','') like 'correction-chain:%'
        or coalesce(batch_item.frozen_component_snapshot_json
          ->>'source_family_key','') like 'correction-chain:%'
        or coalesce(batch_item.frozen_resolution_payload_json
          ->>'source_family_key','') like 'correction-chain:%'
        or coalesce(batch_item.source_ref,'') like 'correction-chain:%'
      )
  ), authoritative_resolution as (
    select correction_item.*,
      resolution_row.id as target_resolution_id,
      resolution_row.resolution_origin_session_id,
      resolution_row.resolution_origin_pay_date,
      resolution_row.source_basis_fingerprint
        as current_source_basis_fingerprint,
      resolution_row.resolution_origin_source_basis_fingerprint,
      resolution_row.payload_json as current_resolution_payload_json,
      carry_row.id as carry_registration_id,
      carry_row.source_resolution_id,
      carry_row.source_resolution_identity_key
    from correction_items correction_item
    left join lateral (
      select saved_resolution.*
      from public.banking_pay_workbench_session_case_resolutions
        saved_resolution
      where saved_resolution.session_id=
          correction_item.source_workbench_session_id
        and saved_resolution.candidate_id=correction_item.candidate_id
        and saved_resolution.resolution_identity_key=
          correction_item.canonical_correction_key
      order by saved_resolution.updated_at_utc desc,
               saved_resolution.id desc
      limit 1
    ) resolution_row on true
    left join lateral (
      select registration.*
      from public.banking_pay_workbench_case_resolution_carry_registrations
        registration
      where registration.target_session_id=
          correction_item.source_workbench_session_id
        and registration.candidate_id=correction_item.candidate_id
        and registration.canonical_resolution_key=
          correction_item.canonical_correction_key
        and registration.status='CARRIED'
        and registration.target_resolution_id=resolution_row.id
      order by registration.completed_at_utc desc,
               registration.id desc
      limit 1
    ) carry_row on true
  ), prepared as (
    select authoritative_resolution.*,
      case when authoritative_resolution.automatic_correction then
        (
          coalesce(
            authoritative_resolution.frozen_resolution_result_json,
            '{}'::jsonb
          )-'resolution_result_fingerprint'
        ) || jsonb_build_object(
          'resolution_authority','AUTOMATIC_CORRECTION_CHAIN',
          'resolution_required',false,
          'resolution_complete',true,
          'canonical_correction_key',
            authoritative_resolution.canonical_correction_key,
          'resolution_identity_key',
            authoritative_resolution.canonical_correction_key,
          'resolution_identity_version','CORRECTION_CHAIN_V1',
          'resolution_economic_fingerprint',
            authoritative_resolution.resolution_economic_fingerprint,
          'target_pay_method',
            upper(btrim(authoritative_resolution.pay_channel)),
          'target_amount_ex_vat',
            round(authoritative_resolution.amount_ex_vat,2)
        )
      else
        coalesce(
          authoritative_resolution.frozen_resolution_result_json,
          '{}'::jsonb
        )-'resolution_result_fingerprint'
      end as resolution_result_base_json
    from authoritative_resolution
  ), frozen as (
    select prepared.*,
      encode(
        extensions.digest(
          convert_to(
            prepared.resolution_result_base_json::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ) as resolution_result_fingerprint
    from prepared
  )
  update public.pay_batch_items batch_item
  set frozen_component_snapshot_json=
        coalesce(batch_item.frozen_component_snapshot_json,'{}'::jsonb)
        ||jsonb_build_object(
          'canonical_correction_key',frozen.canonical_correction_key,
          'correction_identity_version','CORRECTION_CHAIN_V1',
          'correction_root_id',coalesce(
            batch_item.frozen_component_snapshot_json
              ->>'correction_root_id',
            frozen.operation_correction_component_json
              ->>'correction_root_id',
            frozen.operation_canonical_line_json
              ->>'correction_root_id',
            frozen.current_resolution_payload_json
              ->>'correction_root_id'
          ),
          'component_key_type',
            batch_item.frozen_component_key_type,
          'component_key_value',
            batch_item.frozen_component_key_value,
          'ordered_member_timesheet_ids',coalesce(
            batch_item.frozen_component_snapshot_json
              ->'ordered_member_timesheet_ids',
            frozen.operation_correction_component_json
              ->'ordered_member_timesheet_ids',
            frozen.operation_canonical_line_json
              ->'ordered_member_timesheet_ids',
            frozen.current_resolution_payload_json
              ->'ordered_member_timesheet_ids',
            '[]'::jsonb
          ),
          'component_lineage_fingerprint',coalesce(
            batch_item.frozen_component_snapshot_json
              ->>'component_lineage_fingerprint',
            frozen.operation_correction_component_json
              ->>'component_lineage_fingerprint',
            frozen.operation_canonical_line_json
              ->>'component_lineage_fingerprint',
            frozen.current_resolution_payload_json
              ->>'component_lineage_fingerprint'
          ),
          'carrier_source_line_id',coalesce(
            batch_item.frozen_component_snapshot_json
              ->>'carrier_source_line_id',
            batch_item.frozen_component_snapshot_json
              ->>'source_line_id',
            frozen.operation_canonical_line_json
              ->>'line_id'
          ),
          'resolution_economic_fingerprint',
            frozen.resolution_economic_fingerprint
        ),
      frozen_source_basis_json=
        coalesce(batch_item.frozen_source_basis_json,'{}'::jsonb)
        ||jsonb_build_object(
          'source_family_key',coalesce(
            batch_item.frozen_source_basis_json
              ->>'source_family_key',
            batch_item.frozen_component_snapshot_json
              ->>'source_family_key',
            frozen.operation_correction_component_json
              ->>'source_family_key',
            frozen.operation_canonical_line_json
              ->>'source_family_key',
            frozen.current_resolution_payload_json
              ->>'source_family_key'
          ),
          'source_basis_fingerprint',coalesce(
            batch_item.frozen_source_basis_json
              ->>'source_basis_fingerprint',
            batch_item.frozen_component_snapshot_json
              ->>'source_basis_fingerprint',
            frozen.operation_correction_component_json
              ->>'source_basis_fingerprint',
            frozen.operation_canonical_line_json
              ->>'source_basis_fingerprint',
            frozen.operation_canonical_line_json
              #>>'{source_basis_json,source_basis_fingerprint}',
            frozen.current_source_basis_fingerprint
          ),
          'correction_chain_fingerprint',coalesce(
            batch_item.frozen_source_basis_json
              ->>'correction_chain_fingerprint',
            frozen.current_resolution_payload_json
              ->>'correction_chain_fingerprint'
          ),
          'correction_residual_fingerprint',coalesce(
            batch_item.frozen_source_basis_json
              ->>'correction_residual_fingerprint',
            batch_item.frozen_source_basis_json
              ->>'correction_chain_residual_fingerprint',
            frozen.current_resolution_payload_json
              ->>'correction_chain_residual_fingerprint'
          ),
          'correction_financials_policy_envelope_fingerprint',
            coalesce(
              batch_item.frozen_source_basis_json
                ->>'correction_financials_policy_envelope_fingerprint',
              frozen.operation_correction_component_json
                ->>'correction_financials_policy_envelope_fingerprint',
              frozen.operation_canonical_line_json
                ->>'correction_financials_policy_envelope_fingerprint',
              frozen.current_resolution_payload_json
                ->>'correction_financials_policy_envelope_fingerprint'
            ),
          'represented_source_family_key',coalesce(
            batch_item.frozen_source_basis_json
              ->>'represented_source_family_key',
            batch_item.frozen_source_basis_json
              ->>'source_family_key'
          ),
          'source_build_run_id',coalesce(
            batch_item.frozen_source_basis_json
              ->>'source_build_run_id',
            batch_item.frozen_component_snapshot_json
              ->>'source_build_run_id',
            batch_item.frozen_resolution_payload_json
              ->>'source_build_run_id',
            frozen.current_resolution_payload_json
              ->>'source_build_run_id'
          ),
          'operation_source_ref',case
            when frozen.automatic_correction then frozen.source_ref
            else batch_item.frozen_source_basis_json->>'operation_source_ref'
          end
        ),
      frozen_resolution_payload_json=
        coalesce(batch_item.frozen_resolution_payload_json,'{}'::jsonb)
        ||jsonb_build_object(
          'resolution_identity_key',frozen.canonical_correction_key,
          'resolution_identity_version','CORRECTION_CHAIN_V1',
          'canonical_correction_key',frozen.canonical_correction_key,
          'resolution_economic_fingerprint',
            frozen.resolution_economic_fingerprint,
          'source_resolution_id',coalesce(
            frozen.source_resolution_id,
            frozen.target_resolution_id
          ),
          'source_resolution_identity_key',coalesce(
            frozen.source_resolution_identity_key,
            frozen.canonical_correction_key
          ),
          'target_resolution_id',frozen.target_resolution_id,
          'carry_registration_id',frozen.carry_registration_id,
          'resolution_origin_session_id',
            frozen.resolution_origin_session_id,
          'resolution_origin_pay_date',
            frozen.resolution_origin_pay_date,
          'resolution_origin_source_basis_fingerprint',
            frozen.resolution_origin_source_basis_fingerprint
        )
        || case when frozen.automatic_correction then
          jsonb_build_object(
            'resolution_authority','AUTOMATIC_CORRECTION_CHAIN',
            'resolution_required',false,
            'resolution_complete',true,
            'target_resolution_id',null,
            'operation_line_match_count',
              frozen.operation_line_match_count,
            'operation_source_ref',frozen.source_ref
          )
        else '{}'::jsonb end,
      frozen_resolution_result_json=
        frozen.resolution_result_base_json
        ||jsonb_build_object(
          'resolution_result_fingerprint',
            frozen.resolution_result_fingerprint
        ),
      updated_at=v_now_utc
  from frozen
  where batch_item.id=frozen.pay_batch_item_id;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'pay_batch_item_id',batch_item.id,
    'candidate_id',batch_candidate.candidate_id,
    'canonical_component_key',
      batch_item.frozen_component_snapshot_json
        ->>'canonical_correction_key',
    'canonical_resolution_key',
      batch_item.frozen_resolution_payload_json
        ->>'resolution_identity_key',
    'component_economic_fingerprint',
      batch_item.frozen_component_snapshot_json
        ->>'resolution_economic_fingerprint',
    'resolution_economic_fingerprint',
      batch_item.frozen_resolution_payload_json
        ->>'resolution_economic_fingerprint',
    'resolution_authority',
      batch_item.frozen_resolution_payload_json
        ->>'resolution_authority',
    'resolution_required',
      batch_item.frozen_resolution_payload_json
        ->>'resolution_required'
  )) order by batch_item.id),'[]'::jsonb)
  into v_canonical_provenance_mismatch_details
  from public.pay_batch_items batch_item
  join public.pay_batch_candidates batch_candidate
    on batch_candidate.id=batch_item.pay_batch_candidate_id
  where batch_candidate.pay_batch_id=v_batch_id
    and (
      coalesce(batch_item.frozen_source_basis_json
        ->>'source_family_key','') like 'correction-chain:%'
      or coalesce(batch_item.source_ref,'') like 'correction-chain:%'
    )
    and (
      nullif(batch_item.frozen_component_snapshot_json
        ->>'canonical_correction_key','') is null
      or nullif(batch_item.frozen_component_snapshot_json
        ->>'correction_identity_version','')
          is distinct from 'CORRECTION_CHAIN_V1'
      or nullif(batch_item.frozen_component_snapshot_json
        ->>'component_lineage_fingerprint','') is null
      or jsonb_typeof(batch_item.frozen_component_snapshot_json
        ->'ordered_member_timesheet_ids') is distinct from 'array'
      or nullif(batch_item.frozen_resolution_payload_json
        ->>'resolution_identity_key','') is null
      or nullif(batch_item.frozen_resolution_payload_json
        ->>'resolution_economic_fingerprint','') is null
      or nullif(batch_item.frozen_resolution_result_json
        ->>'resolution_result_fingerprint','') is null
      or batch_item.frozen_component_snapshot_json
          ->>'canonical_correction_key'
        is distinct from
          batch_item.frozen_resolution_payload_json
            ->>'resolution_identity_key'
      or batch_item.frozen_component_snapshot_json
          ->>'resolution_economic_fingerprint'
        is distinct from
          batch_item.frozen_resolution_payload_json
            ->>'resolution_economic_fingerprint'
      or (
        coalesce(batch_item.frozen_resolution_payload_json
          ->>'resolution_authority','')='AUTOMATIC_CORRECTION_CHAIN'
        and (
          batch_item.frozen_resolution_payload_json
            ->>'resolution_required' is distinct from 'false'
          or batch_item.frozen_resolution_payload_json
            ->>'resolution_complete' is distinct from 'true'
          or nullif(batch_item.frozen_resolution_payload_json
            ->>'target_resolution_id','') is not null
          or batch_item.frozen_resolution_payload_json
            ->>'operation_line_match_count' is distinct from '1'
          or batch_item.frozen_resolution_payload_json
            ->>'operation_source_ref' is distinct from batch_item.source_ref
          or batch_item.frozen_resolution_result_json
            ->>'resolution_authority'
              is distinct from 'AUTOMATIC_CORRECTION_CHAIN'
          or batch_item.frozen_resolution_result_json
            ->>'resolution_required' is distinct from 'false'
          or batch_item.frozen_resolution_result_json
            ->>'resolution_complete' is distinct from 'true'
          or batch_item.frozen_resolution_result_json
            ->>'canonical_correction_key'
              is distinct from batch_item.frozen_resolution_payload_json
                ->>'resolution_identity_key'
          or batch_item.frozen_resolution_result_json
            ->>'resolution_economic_fingerprint'
              is distinct from batch_item.frozen_resolution_payload_json
                ->>'resolution_economic_fingerprint'
          or nullif(batch_item.frozen_component_snapshot_json
            ->>'correction_root_id','') is null
          or case
            when jsonb_typeof(batch_item.frozen_component_snapshot_json
              ->'ordered_member_timesheet_ids')='array'
            then jsonb_array_length(batch_item.frozen_component_snapshot_json
              ->'ordered_member_timesheet_ids')
            else 0
          end=0
          or coalesce(batch_item.frozen_source_basis_json
            ->>'source_family_key','') not like 'correction-chain:%'
        )
      )
      or (
        coalesce(batch_item.frozen_resolution_payload_json
          ->>'resolution_authority','')<>'AUTOMATIC_CORRECTION_CHAIN'
        and nullif(batch_item.frozen_resolution_payload_json
          ->>'target_resolution_id','') is null
      )
    );

  if jsonb_array_length(v_canonical_provenance_mismatch_details)>0 then
    raise exception 'PAY_BATCH_CANONICAL_CORRECTION_PROVENANCE_INVALID'
      using errcode='P0001',
            detail=jsonb_build_object(
              'code','PAY_BATCH_CANONICAL_CORRECTION_PROVENANCE_INVALID',
              'pay_batch_id',v_batch_id,
              'mismatches',v_canonical_provenance_mismatch_details
            )::text;
  end if;

v_stage := 'STAGE_16C1_FREEZE_ALL_FINANCE_ITEM_PAYOUT_INSTRUCTIONS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'helper_exists', false,
        'mode', 'STAGED_PREVIEW_FINANCE_PAYOUT_AUTHORITY'
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;


  v_stage := 'STAGE_16C2_ENRICH_FINANCE_PAYOUT_INSTRUCTION_EXEC_FIELDS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;


  update public.pay_batch_items as pbi_set
  set payout_instruction_snapshot_json = pbi_src.payout_instruction_snapshot_json
  from (
    with finance_case_preview_ctx as (
      select distinct on (spr.finance_case_id)
        spr.finance_case_id,
        spr.timesheet_id as linked_timesheet_id,
        upper(coalesce(spr.pay_channel, '')) as preview_pay_channel,
        nullif(btrim(coalesce(spr.routing_kind, '')), '') as routing_kind,
        nullif(btrim(coalesce(spr.destination_label, '')), '') as destination_label,
        nullif(btrim(coalesce(spr.taxability, '')), '') as taxability,
        nullif(btrim(coalesce(spr.beneficiary_name, '')), '') as beneficiary_name,
        nullif(btrim(coalesce(spr.masked_bank_account, '')), '') as masked_bank_account,
        nullif(btrim(coalesce(spr.bank_details_hash, '')), '') as bank_details_hash,
        coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
        coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
        coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice
      from pg_temp.tmp_pay_build_selected_preview_rows spr
      where spr.finance_case_id is not null
      order by spr.finance_case_id, spr.preview_row_id
    )
    select
      pbi.id as pay_batch_item_id,
      jsonb_strip_nulls(
        coalesce(pbi.payout_instruction_snapshot_json, '{}'::jsonb)
        || jsonb_build_object(
          'taxability',
            coalesce(
              nullif(btrim(coalesce(fpc.taxability, '')), ''),
              case when pbi.frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum then 'NON_TAXABLE' else 'TAXABLE' end
            ),
          'routing_kind',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')), ''),
              nullif(btrim(coalesce(fpc.routing_kind, '')), ''),
              case when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA_COMPANY' else 'NORMAL_PAY_ROUTE' end
            ),
          'destination_label',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'destination_label', '')), ''),
              nullif(btrim(coalesce(fpc.destination_label, '')), ''),
              case when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'umbrella company' else 'normal PAYE route' end
            ),
          'pay_channel', upper(coalesce(pbi.pay_channel::text, '')),
          'payee_entity_kind',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then 'UMBRELLA'
              else 'CANDIDATE'
            end,
          'payee_entity_id',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then pbc.candidate_id::text
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false and coalesce(pbi.umbrella_id, c.umbrella_id) is not null then coalesce(pbi.umbrella_id, c.umbrella_id)::text
              else pbc.candidate_id::text
            end,
          'beneficiary_name',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name', '')), ''),
              nullif(btrim(coalesce(fpc.beneficiary_name, '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                  then nullif(btrim(coalesce(obd.beneficiary_name, '')), '')
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false
                  then nullif(btrim(coalesce(u.name, '')), '')
                else nullif(btrim(coalesce(c.account_holder, c.display_name, concat_ws(' ', c.first_name, c.last_name))), '')
              end
            ),
          'sort_code',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'sort_code', '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                 and length(coalesce(obd.sort_code, '')) = 6
                  then substr(obd.sort_code, 1, 2) || '-' || substr(obd.sort_code, 3, 2) || '-' || substr(obd.sort_code, 5, 2)
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false and length(coalesce(u.sort_code, '')) = 6
                  then substr(u.sort_code, 1, 2) || '-' || substr(u.sort_code, 3, 2) || '-' || substr(u.sort_code, 5, 2)
                when length(coalesce(c.sort_code, '')) = 6
                  then substr(c.sort_code, 1, 2) || '-' || substr(c.sort_code, 3, 2) || '-' || substr(c.sort_code, 5, 2)
                else null
              end
            ),
          'account_number',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_number', '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                  then nullif(obd.account_number, '')
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false
                  then nullif(u.account_number, '')
                else nullif(c.account_number, '')
              end
            ),
          'account_type',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_type', '')), ''),
              case
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then 'Business'
                else 'Personal'
              end
            ),
          'masked_bank_account',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'masked_bank_account', '')), ''),
              nullif(btrim(coalesce(fpc.masked_bank_account, '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                 and nullif(coalesce(obd.account_number, ''), '') is not null
                  then lpad(right(obd.account_number, 4), length(obd.account_number), '*')
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false and nullif(coalesce(u.account_number, ''), '') is not null
                  then lpad(right(u.account_number, 4), length(u.account_number), '*')
                when nullif(coalesce(c.account_number, ''), '') is not null
                  then lpad(right(c.account_number, 4), length(c.account_number), '*')
                else null
              end
            ),
          'bank_details_hash',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''),
              nullif(btrim(coalesce(fpc.bank_details_hash, '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then obd.bank_details_hash
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then u.bank_details_hash
                else c.bank_details_hash
              end
            ),
          'bank_details_note', coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_note', '')), ''), obd.note),
          'bank_details_created_by_user_id', coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id', '')), ''), case when obd.created_by_user_id is null then null else obd.created_by_user_id::text end),
          'bank_details_updated_by_user_id', coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id', '')), ''), case when obd.updated_by_user_id is null then null else obd.updated_by_user_id::text end),
          'week_ending_bucket',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
               and upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) <> 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                then case
                  when pbi.item_type in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
                    then coalesce(
                      matching_positive_group.week_ending_bucket,
                      case when ts_ctx.week_ending_date is null then null else ts_ctx.week_ending_date::text end,
                      (v_week_start + 6)::text
                    )
                  else coalesce(
                    case when ts_ctx.week_ending_date is null then null else ts_ctx.week_ending_date::text end,
                    (v_week_start + 6)::text
                  )
                end
              else null
            end,
          'rail_provider', upper(btrim(coalesce(pb.rail_provider_snapshot, ''))),
          'rail_env', upper(btrim(coalesce(pb.rail_env_snapshot, ''))),
          'payee_id',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then case when c.payee_id is null then null else c.payee_id::text end
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then case when u.payee_id is null then null else u.payee_id::text end
              else case when c.payee_id is null then null else c.payee_id::text end
            end,
          'payee_account_id',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then case when c.payee_account_id is null then null else c.payee_account_id::text end
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then case when u.payee_account_id is null then null else u.payee_account_id::text end
              else case when c.payee_account_id is null then null else c.payee_account_id::text end
            end,
          'appears_on_umbrella_remittance',
            coalesce(
              (pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance')::boolean,
              fpc.appears_on_umbrella_remittance,
              case when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then true else false end
            ),
          'generates_candidate_payment_advice',
            coalesce(
              (pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice')::boolean,
              fpc.generates_candidate_payment_advice,
              false
            ),
          'is_candidate_directed_oneoff_payout',
            coalesce(
              (pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout')::boolean,
              fpc.is_candidate_directed_oneoff_payout,
              false
            )
        )
      ) as payout_instruction_snapshot_json
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    join pg_temp.tmp_pay_build_candidates_ctx as c
      on c.id = pbc.candidate_id
    left join pg_temp.tmp_pay_build_umbrellas_ctx as u
      on u.id = coalesce(pbi.umbrella_id, c.umbrella_id)
    left join finance_case_preview_ctx as fpc
      on fpc.finance_case_id = pbi.finance_case_id
    left join pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx as obd
      on obd.finance_case_id = pbi.finance_case_id
    left join pg_temp.tmp_pay_build_timesheet_snapshots_ctx as ts_ctx
      on ts_ctx.timesheet_id = coalesce(pbi.timesheet_id, fpc.linked_timesheet_id)
    left join lateral (
      select
        positive_item.payout_instruction_snapshot_json->>'week_ending_bucket' as week_ending_bucket
      from public.pay_batch_items as positive_item
      where positive_item.pay_batch_candidate_id = pbi.pay_batch_candidate_id
        and positive_item.id <> pbi.id
        and coalesce(positive_item.is_voided, false) = false
        and upper(coalesce(positive_item.pay_channel::text, '')) = upper(coalesce(pbi.pay_channel::text, ''))
        and round(coalesce(positive_item.amount_inc_vat, positive_item.amount_ex_vat, 0), 2) > 0
        and coalesce(positive_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$'
        and (
          upper(coalesce(pbi.pay_channel::text, '')) <> 'UMBRELLA'
          or coalesce(positive_item.umbrella_id, c.umbrella_id)
             is not distinct from coalesce(pbi.umbrella_id, c.umbrella_id)
        )
      order by
        (positive_item.payout_instruction_snapshot_json->>'week_ending_bucket')::date,
        positive_item.id
      limit 1
    ) as matching_positive_group
      on pbi.item_type in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.finance_case_id is not null
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT')
  ) as pbi_src
  where pbi_set.id = pbi_src.pay_batch_item_id;


  IF p_operation_id IS NOT NULL THEN
    WITH allocation_matches AS (
      SELECT DISTINCT ON (allocation_row.id)
        allocation_row.id AS allocation_row_id,
        batch_item.id AS pay_batch_item_id,
        COALESCE(
          NULLIF(allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,planned_item_key}', ''),
          allocation_row.operation_source_key
        ) AS operation_source_key
      FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = v_batch_id
       AND batch_candidate.candidate_id = allocation_row.candidate_id
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.pay_batch_candidate_id = batch_candidate.id
       AND batch_item.finance_case_id IS NOT DISTINCT FROM allocation_row.finance_case_id
       AND (
         allocation_row.finance_component_id IS NULL
         OR batch_item.finance_component_id IS NOT DISTINCT FROM allocation_row.finance_component_id
       )
       AND (
         (
           NULLIF(allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,planned_item_key}', '') IS NOT NULL
           AND batch_item.operation_source_key = allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,planned_item_key}'
           AND ROUND(COALESCE(batch_item.amount_ex_vat, 0), 2) = ROUND(COALESCE(allocation_row.allocated_amount, 0), 2)
         )
         OR (
           NULLIF(allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,planned_item_key}', '') IS NULL
           AND ROUND(ABS(COALESCE(batch_item.amount_ex_vat, 0)), 2) = ROUND(ABS(COALESCE(allocation_row.allocated_amount, 0)), 2)
           AND (
             batch_item.operation_source_key IS NULL
             OR batch_item.operation_source_key = allocation_row.operation_source_key
           )
         )
       )
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.candidate_id = ANY(v_candidate_ids)
        AND allocation_row.pay_channel = v_scope
        AND allocation_row.finance_case_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT',
          'LOAN_REPAYMENT',
          'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
          'MANUAL_CREDIT_PAYOUT',
          'LOAN_PAYOUT',
        'UNDERPAYMENT_PAYMENT'
        )
        AND (
          (
            UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
            AND batch_item.item_type = UPPER(BTRIM(COALESCE(allocation_row.allocation_type, '')))
          )
          OR (
            UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) NOT IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
            AND batch_item.item_type IN ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT')
          )
        )
        AND coalesce(batch_item.is_voided, false) = false
      ORDER BY
        allocation_row.id,
        CASE
          WHEN batch_item.operation_source_key = allocation_row.operation_source_key THEN 0
          WHEN batch_item.operation_source_key = NULLIF(
            allocation_row.allocation_basis_json#>>'{draft_finance_item_plan,planned_item_key}', ''
          ) THEN 0
          WHEN batch_item.id = allocation_row.pay_batch_item_id THEN 1
          ELSE 2
        END,
        batch_item.created_at NULLS LAST,
        batch_item.id
    ),
    updated_items AS (
      UPDATE public.pay_batch_items AS batch_item_update
      SET
        operation_source_key = allocation_matches.operation_source_key,
        updated_at = now()
      FROM allocation_matches
      WHERE batch_item_update.id = allocation_matches.pay_batch_item_id
        AND batch_item_update.operation_source_key IS DISTINCT FROM allocation_matches.operation_source_key
      RETURNING batch_item_update.id
    )
    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET
      status = 'ITEM_CREATED',
      pay_batch_id = v_batch_id,
      pay_batch_item_id = allocation_matches.pay_batch_item_id,
      updated_at_utc = now()
    FROM allocation_matches
    WHERE allocation_update.id = allocation_matches.allocation_row_id
      AND (allocation_update.status <> 'ITEM_CREATED' OR allocation_update.pay_batch_item_id IS DISTINCT FROM allocation_matches.pay_batch_item_id);

    WITH expected_plan AS (
      SELECT plan_row.*
      FROM private.pay_workbench_draft_finance_item_plan_v1(p_operation_id, p_candidate_scope_ids) AS plan_row
      WHERE plan_row.pay_channel = v_scope
        AND plan_row.planned_item_type = 'OVERPAYMENT_RECOVERY'
    ), created_plan AS (
      SELECT
        batch_item.operation_source_key AS planned_item_key,
        batch_item.amount_ex_vat,
        batch_item.item_type,
        batch_candidate.candidate_id,
        batch_item.finance_case_id,
        batch_item.finance_component_id,
        count(*) OVER (PARTITION BY batch_item.operation_source_key) AS key_count
      FROM public.pay_batch_items AS batch_item
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = batch_item.pay_batch_candidate_id
      WHERE batch_candidate.pay_batch_id = v_batch_id
        AND batch_candidate.candidate_id = ANY(v_candidate_ids)
        AND batch_item.item_type = 'OVERPAYMENT_RECOVERY'
        AND batch_item.finance_case_id IS NOT NULL
        AND batch_item.operation_source_key LIKE (p_operation_id::text || ':%')
        AND COALESCE(batch_item.is_voided, false) = false
    ), mismatch AS (
      SELECT
        (SELECT count(*)::integer FROM expected_plan) AS expected_key_count,
        (SELECT count(DISTINCT created_plan.planned_item_key)::integer FROM created_plan) AS created_key_count,
        (SELECT count(*)::integer
         FROM expected_plan
         WHERE NOT EXISTS (
           SELECT 1 FROM created_plan
           WHERE created_plan.planned_item_key = expected_plan.planned_item_key
         )) AS missing_key_count,
        (SELECT count(*)::integer
         FROM created_plan
         WHERE NOT EXISTS (
           SELECT 1 FROM expected_plan
           WHERE expected_plan.planned_item_key = created_plan.planned_item_key
         )) AS unexpected_key_count,
        (SELECT count(*)::integer FROM created_plan WHERE created_plan.key_count > 1) AS duplicate_key_count,
        (SELECT count(*)::integer
         FROM expected_plan
         JOIN created_plan ON created_plan.planned_item_key = expected_plan.planned_item_key
         WHERE ROUND(created_plan.amount_ex_vat, 2) IS DISTINCT FROM ROUND(expected_plan.planned_item_amount, 2)
            OR created_plan.item_type IS DISTINCT FROM expected_plan.planned_item_type
            OR created_plan.candidate_id IS DISTINCT FROM expected_plan.candidate_id
            OR created_plan.finance_case_id IS DISTINCT FROM expected_plan.finance_case_id
            OR created_plan.finance_component_id IS DISTINCT FROM expected_plan.finance_component_id) AS identity_or_amount_mismatch_count,
        COALESCE((
          SELECT jsonb_agg(missing_row.planned_item_key ORDER BY missing_row.planned_item_key)
          FROM (
            SELECT expected_plan.planned_item_key
            FROM expected_plan
            WHERE NOT EXISTS (
              SELECT 1 FROM created_plan
              WHERE created_plan.planned_item_key = expected_plan.planned_item_key
            )
            ORDER BY expected_plan.planned_item_key
            LIMIT 20
          ) AS missing_row
        ), '[]'::jsonb) AS missing_key_sample,
        COALESCE((
          SELECT jsonb_agg(unexpected_row.planned_item_key ORDER BY unexpected_row.planned_item_key)
          FROM (
            SELECT created_plan.planned_item_key
            FROM created_plan
            WHERE NOT EXISTS (
              SELECT 1 FROM expected_plan
              WHERE expected_plan.planned_item_key = created_plan.planned_item_key
            )
            ORDER BY created_plan.planned_item_key
            LIMIT 20
          ) AS unexpected_row
        ), '[]'::jsonb) AS unexpected_key_sample
    )
    SELECT jsonb_build_object(
      'expected_key_count', mismatch.expected_key_count,
      'created_key_count', mismatch.created_key_count,
      'missing_key_count', mismatch.missing_key_count,
      'unexpected_key_count', mismatch.unexpected_key_count,
      'duplicate_key_count', mismatch.duplicate_key_count,
      'identity_or_amount_mismatch_count', mismatch.identity_or_amount_mismatch_count,
      'missing_key_sample', mismatch.missing_key_sample,
      'unexpected_key_sample', mismatch.unexpected_key_sample
    )
    INTO v_operation_plan_mismatch_details
    FROM mismatch;

    IF COALESCE((v_operation_plan_mismatch_details->>'missing_key_count')::integer, 0) > 0
       OR COALESCE((v_operation_plan_mismatch_details->>'unexpected_key_count')::integer, 0) > 0
       OR COALESCE((v_operation_plan_mismatch_details->>'duplicate_key_count')::integer, 0) > 0
       OR COALESCE((v_operation_plan_mismatch_details->>'identity_or_amount_mismatch_count')::integer, 0) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
        'code', 'DRAFT_FINANCE_ITEM_PLAN_PARITY_FAILED',
        'message', 'Created Draft finance items do not exactly match the frozen canonical finance-item plan',
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_scope,
        'mismatch_details', v_operation_plan_mismatch_details
      )::text;
    END IF;

    SELECT jsonb_build_object(
             'allocation_rows_total', count(*)::integer,
             'allocation_rows_unlinked', count(*) FILTER (WHERE allocation_row.status <> 'ITEM_CREATED' OR allocation_row.pay_batch_item_id IS NULL)::integer
           )
    INTO v_operation_mismatch_details
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_id = ANY(v_candidate_ids)
      AND allocation_row.pay_channel = v_scope
      AND allocation_row.finance_case_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) IN (
        'OVERPAYMENT_RECOVERY',
        'MANUAL_DEBT_RECOVERY',
        'PAYMENT_ADVANCE_REPAYMENT',
        'LOAN_REPAYMENT',
        'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
        'MANUAL_CREDIT_PAYOUT',
        'LOAN_PAYOUT',
        'UNDERPAYMENT_PAYMENT'
      );

    IF coalesce((v_operation_mismatch_details->>'allocation_rows_unlinked')::integer, 0) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
        'code', 'OPERATION_ALLOCATION_ROWS_NOT_LINKED',
        'message', 'pay_batch_apply_finance_adjustments could not link every operation allocation row to a created pay batch item',
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_scope,
        'mismatch_details', v_operation_mismatch_details
      )::text;
    END IF;

    UPDATE public.banking_pay_operation_candidate_scope AS scope_update
    SET status = CASE
          WHEN NOT EXISTS (
            SELECT 1
            FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_remaining
            WHERE allocation_remaining.operation_id = p_operation_id
              AND allocation_remaining.candidate_scope_id = scope_update.id
              AND UPPER(BTRIM(COALESCE(allocation_remaining.status, ''))) IN ('PENDING', 'ITEM_PENDING')
          ) THEN 'DRAFTED'
          ELSE scope_update.status
        END,
        pay_batch_id = v_batch_id,
        updated_at_utc = now()
    WHERE scope_update.operation_id = p_operation_id
      AND scope_update.candidate_id = ANY(v_candidate_ids)
      AND scope_update.pay_channel = v_scope;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    PERFORM private.pay_workbench_draft_expected_effects_v1(
      p_operation_id,'APPLY_FINANCE_ADJUSTMENTS','ASSERT_COMPLETE','[]'::jsonb,
      jsonb_build_object('pay_batch_id',p_pay_batch_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'pay_channel_scope', v_scope,
    'applied_count', (coalesce(v_rows_ins_loan_payout_items, 0) + coalesce(v_rows_ins_manual_credit_payout_items, 0) + coalesce(v_rows_ins_underpayment_payout_items, 0) + coalesce(v_rows_ins_overpayment_recovery_items, 0) + coalesce(v_rows_ins_debt_items, 0) + coalesce(v_rows_ins_loan_items, 0) + coalesce(v_rows_ins_dormant_recovery_template_items, 0) + coalesce(v_rows_ins_dormant_manual_debt_template_items, 0) + coalesce(v_rows_ins_dormant_loan_template_items, 0) + coalesce(v_rows_ins_dormant_overpayment_template_items, 0)),
    'reused_count', coalesce(v_operation_allocation_done, 0),
    'skipped_count', (coalesce(v_rows_skipped_dormant_recovery_template_items, 0) + coalesce(v_rows_skipped_dormant_manual_debt_template_items, 0) + coalesce(v_rows_skipped_dormant_loan_template_items, 0) + coalesce(v_rows_skipped_dormant_overpayment_template_items, 0)),
    'failed_count', 0,
    'mismatch_details', coalesce(v_operation_mismatch_details, '{}'::jsonb),
    'loan_payout_items_inserted', coalesce(v_rows_ins_loan_payout_items, 0),
    'manual_credit_payout_items_inserted', coalesce(v_rows_ins_manual_credit_payout_items, 0),
    'underpayment_payment_items_inserted', coalesce(v_rows_ins_underpayment_payout_items, 0),
    'overpayment_recovery_items_inserted', coalesce(v_rows_ins_overpayment_recovery_items, 0),
    'manual_debt_recovery_items_inserted', coalesce(v_rows_ins_debt_items, 0),
    'loan_repayment_items_inserted', coalesce(v_rows_ins_loan_items, 0),
    'staged_recovery_template_rows', coalesce(v_rows_staged_recovery_template_rows, 0),
    'staged_manual_debt_template_rows', coalesce(v_rows_staged_manual_debt_template_rows, 0),
    'staged_loan_template_rows', coalesce(v_rows_staged_loan_template_rows, 0),
    'staged_overpayment_template_rows', coalesce(v_rows_staged_overpayment_template_rows, 0),
    'staged_paye_manual_debt_template_rows', coalesce(v_rows_staged_paye_manual_debt_template_rows, 0),
    'staged_manual_debt_template_rows_by_candidate', coalesce(v_staged_manual_debt_template_rows_by_candidate, '{}'::jsonb),
    'dormant_recovery_template_items_inserted', coalesce(v_rows_ins_dormant_recovery_template_items, 0),
    'dormant_manual_debt_template_items_inserted', coalesce(v_rows_ins_dormant_manual_debt_template_items, 0),
    'dormant_loan_template_items_inserted', coalesce(v_rows_ins_dormant_loan_template_items, 0),
    'dormant_overpayment_template_items_inserted', coalesce(v_rows_ins_dormant_overpayment_template_items, 0),
    'dormant_recovery_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_recovery_template_items, 0),
    'dormant_manual_debt_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_manual_debt_template_items, 0),
    'dormant_loan_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_loan_template_items, 0),
    'dormant_overpayment_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_overpayment_template_items, 0)
  );
END;
$function$;

-- pay_batch_assert_integrity(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_assert_integrity(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_stage text := NULL;
  v_breakdown_missing_ct integer := 0;
  v_breakdown_bad_ct integer := 0;
  v_breakdown_bad jsonb := '[]'::jsonb;
  v_blocked_candidates jsonb := '[]'::jsonb;
  v_rows_upd_timesheet_overrides_consumed integer := 0;
  v_consumed_timesheet_payment_overrides jsonb := '[]'::jsonb;
  v_rail_provider_default text := NULL;
  v_rail_env_default text := NULL;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_now_utc timestamptz := now();
  v_override_consume_rec record;
  v_operation_mismatch_details jsonb := '{}'::jsonb;
  v_operation_affected_candidate_ids jsonb := '[]'::jsonb;
  v_operation_mismatch_count integer := 0;
  v_operation_active_item_count integer := 0;
  v_operation_scope_count integer := 0;
  v_operation_reservation_unavailable_scope_count integer := 0;
  v_consumed_timesheet_payment_override_ids jsonb := '[]'::jsonb;
  v_expected_advance_override_count integer := 0;
  v_expected_advance_override_ids jsonb := '[]'::jsonb;
  v_advance_override_consumption_mismatch_count integer := 0;
  v_advance_override_consumption_mismatches jsonb := '[]'::jsonb;
  v_integrity_operation public.banking_pay_operations%ROWTYPE;
  v_integrity_batch public.pay_batches%ROWTYPE;
  v_generation_provenance_mismatch_count integer := 0;
  v_generation_provenance_json jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_integrity_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;

    SELECT batch_row.*
    INTO v_integrity_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = v_batch_id;

    IF v_integrity_operation.id IS NULL OR v_integrity_batch.id IS NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'code', 'DRAFT_CREATE_OPERATION_BATCH_PROVENANCE_MISMATCH',
        'mismatch_details', jsonb_build_array(jsonb_build_object('check_code', 'OPERATION_OR_BATCH_NOT_FOUND'))
      );
    END IF;

    IF UPPER(BTRIM(COALESCE(v_integrity_operation.operation_type, ''))) = 'DRAFT_CREATE' THEN
      SELECT COUNT(*)::integer
      INTO v_generation_provenance_mismatch_count
      FROM public.banking_pay_operation_candidate_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = v_batch_id
        AND (
          scope_row.workbench_session_id IS DISTINCT FROM v_integrity_operation.workbench_session_id
          OR scope_row.source_session_version IS DISTINCT FROM v_integrity_operation.frozen_source_session_version
          OR scope_row.source_snapshot_run_id IS DISTINCT FROM v_integrity_operation.frozen_source_snapshot_run_id
        );

      v_generation_provenance_json := jsonb_build_object(
        'scope_freeze_status', v_integrity_operation.scope_freeze_status,
        'operation_scope_change_generation', v_integrity_operation.frozen_scope_change_generation,
        'batch_scope_change_generation', v_integrity_batch.source_scope_change_generation,
        'operation_workbench_session_id', v_integrity_operation.workbench_session_id,
        'batch_workbench_session_id', v_integrity_batch.source_workbench_session_id,
        'operation_source_session_version', v_integrity_operation.frozen_source_session_version,
        'batch_source_session_version', v_integrity_batch.source_session_version,
        'operation_source_snapshot_run_id', v_integrity_operation.frozen_source_snapshot_run_id,
        'batch_source_snapshot_run_id', v_integrity_batch.source_snapshot_run_id,
        'policy_x_authority', 'FROZEN_OPERATION_SCOPE'
      );

      IF UPPER(BTRIM(COALESCE(v_integrity_operation.scope_freeze_status, ''))) <> 'FROZEN'
         OR NOT COALESCE(v_integrity_operation.source_scope_seed_complete, false)
         OR v_integrity_operation.frozen_scope_change_generation IS NULL
         OR v_integrity_batch.source_scope_change_generation IS DISTINCT FROM v_integrity_operation.frozen_scope_change_generation
         OR v_integrity_batch.source_workbench_session_id IS DISTINCT FROM v_integrity_operation.workbench_session_id
         OR v_integrity_batch.source_session_version IS DISTINCT FROM v_integrity_operation.frozen_source_session_version
         OR v_integrity_batch.source_snapshot_run_id IS DISTINCT FROM v_integrity_operation.frozen_source_snapshot_run_id
         OR v_generation_provenance_mismatch_count > 0
         OR NOT EXISTS (
           SELECT 1
           FROM public.banking_pay_operation_candidate_scope AS linked_scope
           WHERE linked_scope.operation_id = p_operation_id
             AND linked_scope.pay_batch_id = v_batch_id
         ) THEN
        RETURN jsonb_build_object(
          'ok', false,
          'pay_batch_id', v_batch_id::text,
          'operation_id', p_operation_id::text,
          'pass', false,
          'error', 'DRAFT_INTEGRITY_FAILED',
          'code', 'DRAFT_CREATE_OPERATION_BATCH_PROVENANCE_MISMATCH',
          'mismatch_details', jsonb_build_array(
            jsonb_build_object(
              'check_code', 'DRAFT_CREATE_OPERATION_BATCH_PROVENANCE_MISMATCH',
              'generation_provenance', v_generation_provenance_json,
              'candidate_scope_provenance_mismatch_count', v_generation_provenance_mismatch_count
            )
          ),
          'friendly_error_message', 'Draft integrity failed because frozen operation and batch provenance do not match.'
        );
      END IF;
    END IF;
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_settings_context') IS NOT NULL THEN
    SELECT ctx.rail_provider_default, ctx.rail_env_default, ctx.need_name_check, ctx.requires_payee_map
    INTO v_rail_provider_default, v_rail_env_default, v_need_name_check, v_requires_payee_map
    FROM pg_temp.tmp_pay_build_settings_context AS ctx
    LIMIT 1;
  END IF;

  IF (v_rail_provider_default IS NULL OR v_rail_env_default IS NULL) AND p_operation_id IS NOT NULL THEN
    SELECT batch_row.rail_provider_snapshot,
           batch_row.rail_env_snapshot,
           (coalesce(settings_row.rail_supports_name_check, false) = true and upper(btrim(coalesce(batch_row.rail_provider_snapshot, ''))) <> 'CSV') AS need_name_check,
           (upper(btrim(coalesce(batch_row.rail_provider_snapshot, ''))) <> 'CSV') AS requires_payee_map
    INTO v_rail_provider_default, v_rail_env_default, v_need_name_check, v_requires_payee_map
    FROM public.pay_batches AS batch_row
    CROSS JOIN LATERAL (
      SELECT settings_defaults_row.rail_supports_name_check
      FROM public.settings_defaults AS settings_defaults_row
      ORDER BY settings_defaults_row.id ASC
      LIMIT 1
    ) AS settings_row
    WHERE batch_row.id = v_batch_id;
  END IF;

  IF v_rail_provider_default IS NULL OR v_rail_env_default IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_settings_context temp table is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct spr.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS spr;
  ELSIF p_operation_id IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct scope_row.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = v_batch_id;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_candidates_ctx (
      id uuid PRIMARY KEY,
      tms_ref text,
      display_name text,
      pay_method text,
      umbrella_id uuid,
      first_name text,
      last_name text,
      account_holder text,
      sort_code text,
      account_number text,
      bank_details_hash text,
      payee_id text,
      payee_account_id text,
      umbrella_vat_chargeable boolean
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_build_candidates_ctx (
      id,
      tms_ref,
      display_name,
      pay_method,
      umbrella_id,
      first_name,
      last_name,
      account_holder,
      sort_code,
      account_number,
      bank_details_hash,
      payee_id,
      payee_account_id,
      umbrella_vat_chargeable
    )
    SELECT
      candidate_row.id,
      candidate_row.tms_ref,
      candidate_row.display_name,
      upper(coalesce(candidate_row.pay_method, '')),
      candidate_row.umbrella_id,
      candidate_row.first_name,
      candidate_row.last_name,
      candidate_row.account_holder,
      regexp_replace(coalesce(candidate_row.sort_code, ''), '[^0-9]', '', 'g'),
      nullif(regexp_replace(coalesce(candidate_row.account_number, ''), '[^0-9]', '', 'g'), ''),
      candidate_row.bank_details_hash,
      bank_payee_candidate.payee_id,
      bank_payee_candidate.payee_account_id,
      coalesce(umbrella_row.vat_chargeable, false)
    FROM public.candidates AS candidate_row
    LEFT JOIN public.umbrellas AS umbrella_row
      ON umbrella_row.id = candidate_row.umbrella_id
    LEFT JOIN public.bank_payee_map AS bank_payee_candidate
      ON upper(coalesce(bank_payee_candidate.rail_provider, '')) = upper(btrim(coalesce(v_rail_provider_default, '')))
     AND upper(coalesce(bank_payee_candidate.rail_env, '')) = upper(btrim(coalesce(v_rail_env_default, '')))
     AND upper(coalesce(bank_payee_candidate.entity_kind, '')) = 'CANDIDATE'
     AND bank_payee_candidate.entity_id = candidate_row.id
     AND bank_payee_candidate.bank_details_hash = candidate_row.bank_details_hash
    WHERE candidate_row.id = ANY(v_candidate_ids)
    ON CONFLICT (id) DO NOTHING;

    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_umbrellas_ctx (
      id uuid PRIMARY KEY,
      name text,
      vat_chargeable boolean,
      sort_code text,
      account_number text,
      bank_details_hash text,
      payee_id text,
      payee_account_id text
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_build_umbrellas_ctx (
      id,
      name,
      vat_chargeable,
      sort_code,
      account_number,
      bank_details_hash,
      payee_id,
      payee_account_id
    )
    SELECT
      umbrella_row.id,
      umbrella_row.name,
      coalesce(umbrella_row.vat_chargeable, false),
      regexp_replace(coalesce(umbrella_row.sort_code, ''), '[^0-9]', '', 'g'),
      nullif(regexp_replace(coalesce(umbrella_row.account_number, ''), '[^0-9]', '', 'g'), ''),
      umbrella_row.bank_details_hash,
      bank_payee_umbrella.payee_id,
      bank_payee_umbrella.payee_account_id
    FROM public.umbrellas AS umbrella_row
    JOIN (
      SELECT DISTINCT candidate_ctx.umbrella_id
      FROM pg_temp.tmp_pay_build_candidates_ctx AS candidate_ctx
      WHERE candidate_ctx.umbrella_id IS NOT NULL
    ) AS required_umbrella
      ON required_umbrella.umbrella_id = umbrella_row.id
    LEFT JOIN public.bank_payee_map AS bank_payee_umbrella
      ON upper(coalesce(bank_payee_umbrella.rail_provider, '')) = upper(btrim(coalesce(v_rail_provider_default, '')))
     AND upper(coalesce(bank_payee_umbrella.rail_env, '')) = upper(btrim(coalesce(v_rail_env_default, '')))
     AND upper(coalesce(bank_payee_umbrella.entity_kind, '')) = 'UMBRELLA'
     AND bank_payee_umbrella.entity_id = umbrella_row.id
     AND bank_payee_umbrella.bank_details_hash = umbrella_row.bank_details_hash
    ON CONFLICT (id) DO NOTHING;
  END IF;


v_stage := 'STAGE_21_BREAKDOWN_INTEGRITY_MISSING';

  -- ✅ Integrity checks: every active (non-voided) item must have ≥1 breakdown row; sums must match exactly
  select count(*)
  into v_breakdown_missing_ct
  from public.pay_batch_items pbi_m
  join public.pay_batch_candidates pbc_m
    on pbc_m.id = pbi_m.pay_batch_candidate_id
  where pbc_m.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc_m.candidate_id = any(v_candidate_ids))
    and coalesce(pbi_m.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_batch_item_breakdowns pbib_m
      where pbib_m.pay_batch_item_id = pbi_m.id
      limit 1
    );

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_21_BREAKDOWN_MISSING_COUNT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_breakdown_missing_ct,0) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_BREAKDOWN_MISSING',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0),
          'error', 'PAY_BATCH_BREAKDOWN_MISSING'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'mismatch_details', jsonb_build_array(jsonb_build_object(
          'check_code', 'PAY_BATCH_BREAKDOWN_MISSING',
          'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0)
        )),
        'affected_candidate_ids', coalesce(to_jsonb(v_candidate_ids), '[]'::jsonb),
        'friendly_error_message', 'Draft integrity failed because one or more active batch items have no breakdown rows.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb)
      );
    END IF;

    raise exception 'PAY_BATCH_BREAKDOWN_MISSING: % items have no breakdown rows', v_breakdown_missing_ct;
  end if;

  v_stage := 'STAGE_22_BREAKDOWN_INTEGRITY_SUM_MATCH';

  with sums as (
    select
      pbi_s.id as pay_batch_item_id,
      round(pbi_s.amount_ex_vat,2) as item_ex,
      round(pbi_s.amount_vat,2) as item_vat,
      round(pbi_s.amount_inc_vat,2) as item_inc,
      round(coalesce(sum(pbib_s.amount_ex_vat),0),2) as sum_ex,
      round(coalesce(sum(pbib_s.amount_vat),0),2) as sum_vat,
      round(coalesce(sum(pbib_s.amount_inc_vat),0),2) as sum_inc
    from public.pay_batch_items pbi_s
    join public.pay_batch_candidates pbc_s
      on pbc_s.id = pbi_s.pay_batch_candidate_id
    left join public.pay_batch_item_breakdowns pbib_s
      on pbib_s.pay_batch_item_id = pbi_s.id
    where pbc_s.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc_s.candidate_id = any(v_candidate_ids))
      and coalesce(pbi_s.is_voided, false) = false
    group by pbi_s.id, pbi_s.amount_ex_vat, pbi_s.amount_vat, pbi_s.amount_inc_vat
  ),
  bad as (
    select
      s.pay_batch_item_id,
      s.item_ex, s.sum_ex,
      s.item_vat, s.sum_vat,
      s.item_inc, s.sum_inc
    from sums s
    where s.item_ex <> s.sum_ex
       or s.item_vat <> s.sum_vat
       or s.item_inc <> s.sum_inc
  )
  select
    count(*),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'pay_batch_item_id', b.pay_batch_item_id::text,
          'item_ex', b.item_ex, 'sum_ex', b.sum_ex,
          'item_vat', b.item_vat, 'sum_vat', b.sum_vat,
          'item_inc', b.item_inc, 'sum_inc', b.sum_inc
        )
        order by b.pay_batch_item_id::text
      ),
      '[]'::jsonb
    )
  into v_breakdown_bad_ct, v_breakdown_bad
  from bad b;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_22_BREAKDOWN_SUMS_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
        'breakdown_bad_sample', (
          case
            when jsonb_typeof(v_breakdown_bad) = 'array' then (
              select coalesce(jsonb_agg(x order by (x->>'pay_batch_item_id')), '[]'::jsonb)
              from (
                select e as x
                from jsonb_array_elements(v_breakdown_bad) e
                limit 50
              ) s
            )
            else v_breakdown_bad
          end
        )
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_breakdown_bad_ct,0) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_BREAKDOWN_MISMATCH',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
          'breakdown_bad', v_breakdown_bad,
          'error', 'PAY_BATCH_BREAKDOWN_MISMATCH'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'mismatch_details', coalesce(v_breakdown_bad, '[]'::jsonb),
        'affected_candidate_ids', coalesce(to_jsonb(v_candidate_ids), '[]'::jsonb),
        'friendly_error_message', 'Draft integrity failed because one or more item breakdown totals do not match their batch item totals.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb)
      );
    END IF;

    raise exception 'PAY_BATCH_BREAKDOWN_MISMATCH %', v_breakdown_bad::text;
  end if;

  v_stage := 'STAGE_23_FINAL_SAFETY_ASSERT_BLOCKERS';

  with destination_items as (
    select
      pbc.candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      upper(coalesce(pbi.pay_channel::text,'')) as pay_channel,
      upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) as routing_kind,
      pbi.payout_instruction_snapshot_json,
      pbi.umbrella_id as item_umbrella_id,
      c.umbrella_id as candidate_umbrella_id,
      c.bank_details_hash as candidate_bank_hash,
      u.bank_details_hash as umbrella_bank_hash,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as snapshot_bank_hash
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = pbc.candidate_id
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = coalesce(pbi.umbrella_id, c.umbrella_id)
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.item_type <> 'DEBT_CREATED'
      and pbc.candidate_id = any(v_candidate_ids)
  ),
  destinations as (
    select distinct
      di.candidate_id,
      case
        when di.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE'
        when di.pay_channel = 'PAYE' then 'CANDIDATE'
        when di.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA'
        when di.pay_channel = 'UMBRELLA' then 'UMBRELLA'
        else 'CANDIDATE'
      end as entity_kind,
      case
        when di.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then di.candidate_id
        when di.pay_channel = 'PAYE' then di.candidate_id
        when di.routing_kind = 'UMBRELLA_COMPANY' then coalesce(di.item_umbrella_id, di.candidate_umbrella_id)
        when di.pay_channel = 'UMBRELLA' then coalesce(di.item_umbrella_id, di.candidate_umbrella_id)
        else di.candidate_id
      end as entity_id,
      case
        when di.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then di.snapshot_bank_hash
        when di.pay_channel = 'PAYE' then di.candidate_bank_hash
        when di.routing_kind = 'UMBRELLA_COMPANY' then di.umbrella_bank_hash
        when di.pay_channel = 'UMBRELLA' then di.umbrella_bank_hash
        else di.candidate_bank_hash
      end as bank_hash
    from destination_items di
  ),
  destination_blockers as (

    select
      d.candidate_id,
      d.entity_kind,
      d.entity_id,
      d.bank_hash,
      (
        (case
           when d.entity_id is null or d.bank_hash is null or btrim(d.bank_hash) = '' then jsonb_build_array('BLOCKED_BANK_DETAILS')
           else '[]'::jsonb
         end)
        ||
        (case
           when d.entity_id is not null
            and d.bank_hash is not null and btrim(d.bank_hash) <> ''
            and v_need_name_check = true
            and not exists (
              select 1
              from public.bank_name_checks bnc
              where upper(coalesce(bnc.rail_provider,'')) = upper(btrim(coalesce(v_rail_provider_default,'')))
                and upper(coalesce(bnc.rail_env,'')) = upper(btrim(coalesce(v_rail_env_default,'')))
                and upper(coalesce(bnc.entity_kind,'')) = d.entity_kind
                and bnc.entity_id = d.entity_id
                and bnc.bank_details_hash = d.bank_hash
                and (
                  upper(coalesce(bnc.status,'')) = 'PASS'
                  or (
                    bnc.override_reason is not null
                    and bnc.override_hash is not null
                    and bnc.override_hash = d.bank_hash
                  )
                )
              limit 1
            )
           then jsonb_build_array('BLOCKED_NAME_CHECK')
           else '[]'::jsonb
         end)
        ||
        (case
           when d.entity_id is not null
            and d.bank_hash is not null and btrim(d.bank_hash) <> ''
            and v_requires_payee_map = true
            and not exists (
              select 1
              from public.bank_payee_map bpm
              where upper(coalesce(bpm.rail_provider,'')) = upper(btrim(coalesce(v_rail_provider_default,'')))
                and upper(coalesce(bpm.rail_env,'')) = upper(btrim(coalesce(v_rail_env_default,'')))
                and upper(coalesce(bpm.entity_kind,'')) = d.entity_kind
                and bpm.entity_id = d.entity_id
                and bpm.bank_details_hash = d.bank_hash
              limit 1
            )
           then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
           else '[]'::jsonb
         end)
      ) as blockers
    from destinations d
  ),
  bad as (
    select
      db.candidate_id,
      db.blockers
    from destination_blockers db
    where jsonb_array_length(db.blockers) > 0
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', b.candidate_id::text,
        'blockers', b.blockers
      )
      order by b.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_blocked_candidates
  from bad b;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_23_BLOCKER_ASSERT_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'blocked_candidates', (
          case
            when jsonb_typeof(v_blocked_candidates) = 'array' then (
              select coalesce(jsonb_agg(x order by (x->>'candidate_id')), '[]'::jsonb)
              from (
                select e as x
                from jsonb_array_elements(v_blocked_candidates) e
                limit 50
              ) s
            )
            else v_blocked_candidates
          end
        ),
        'blocked_count', jsonb_array_length(v_blocked_candidates)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if jsonb_array_length(v_blocked_candidates) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_DRAFT_CONTAINS_BLOCKED_ITEMS',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'blocked_candidates', v_blocked_candidates,
          'error', 'DRAFT_CONTAINS_BLOCKED_ITEMS'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'mismatch_details', coalesce(v_blocked_candidates, '[]'::jsonb),
        'affected_candidate_ids', coalesce((
          SELECT jsonb_agg(DISTINCT blocked_candidate.value->>'candidate_id')
          FROM jsonb_array_elements(coalesce(v_blocked_candidates, '[]'::jsonb)) AS blocked_candidate(value)
          WHERE NULLIF(blocked_candidate.value->>'candidate_id', '') IS NOT NULL
        ), '[]'::jsonb),
        'friendly_error_message', 'Draft integrity failed because the draft contains blocked payment destinations.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb)
      );
    END IF;

    raise exception 'DRAFT_CONTAINS_BLOCKED_ITEMS %', v_blocked_candidates::text;
  end if;

  v_stage := 'STAGE_23B_CONSUME_TIMESHEET_PAYMENT_OVERRIDES';

  with consumed as (
    update public.timesheet_payment_overrides tpo
    set
      consumed_by_pay_batch_id = v_batch_id,
      consumed_at_utc = v_now_utc
    where tpo.cleared_at_utc is null
      and tpo.consumed_by_pay_batch_id is null
      and tpo.consumed_at_utc is null
      and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
      and tpo.id in (
        select tpo_pick.id
        from (
          select distinct on (tpo2.timesheet_id)
            tpo2.id,
            tpo2.timesheet_id
          from public.timesheet_payment_overrides tpo2
          where tpo2.cleared_at_utc is null
            and tpo2.consumed_by_pay_batch_id is null
            and tpo2.consumed_at_utc is null
            and upper(coalesce(tpo2.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
            and exists (
              select 1
              from public.pay_batch_items pbi
              join public.pay_batch_candidates pbc
                on pbc.id = pbi.pay_batch_candidate_id
              where pbc.pay_batch_id = v_batch_id
                and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
                and pbi.timesheet_id = tpo2.timesheet_id
                and coalesce(pbi.is_voided, false) = false
                and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            )
          order by tpo2.timesheet_id, tpo2.created_at_utc desc, tpo2.id desc
        ) tpo_pick
      )
    returning
      tpo.id,
      tpo.timesheet_id,
      tpo.candidate_id,
      tpo.override_type,
      tpo.reason,
      tpo.created_at_utc,
      tpo.created_by_user_id,
      tpo.consumed_by_pay_batch_id,
      tpo.consumed_at_utc
  )
  select
    count(*)::int,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'override_id', consumed.id::text,
          'timesheet_id', consumed.timesheet_id::text,
          'candidate_id', case when consumed.candidate_id is null then null else consumed.candidate_id::text end,
          'override_type', consumed.override_type,
          'reason', consumed.reason,
          'created_at_utc', consumed.created_at_utc,
          'created_by_user_id', case when consumed.created_by_user_id is null then null else consumed.created_by_user_id::text end,
          'consumed_by_pay_batch_id', case when consumed.consumed_by_pay_batch_id is null then null else consumed.consumed_by_pay_batch_id::text end,
          'consumed_at_utc', consumed.consumed_at_utc
        )
        order by consumed.timesheet_id::text, consumed.id::text
      ),
      '[]'::jsonb
    ),
    coalesce(
      jsonb_agg(to_jsonb(consumed.id::text) order by consumed.timesheet_id::text, consumed.id::text),
      '[]'::jsonb
    )
  into
    v_rows_upd_timesheet_overrides_consumed,
    v_consumed_timesheet_payment_overrides,
    v_consumed_timesheet_payment_override_ids
  from consumed;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_23B_TIMESHEET_OVERRIDES_CONSUMED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_payment_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb),
        'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_rows_upd_timesheet_overrides_consumed, 0) > 0 then
    for v_override_consume_rec in
      select
        x.override_id::uuid as override_id,
        x.timesheet_id::uuid as timesheet_id,
        case when x.candidate_id is null or btrim(x.candidate_id) = '' then null else x.candidate_id::uuid end as candidate_id,
        x.override_type,
        x.reason,
        case when x.created_by_user_id is null or btrim(x.created_by_user_id) = '' then null else x.created_by_user_id::uuid end as created_by_user_id,
        x.created_at_utc::timestamptz as created_at_utc,
        case when x.consumed_by_pay_batch_id is null or btrim(x.consumed_by_pay_batch_id) = '' then null else x.consumed_by_pay_batch_id::uuid end as consumed_by_pay_batch_id,
        x.consumed_at_utc::timestamptz as consumed_at_utc
      from jsonb_to_recordset(v_consumed_timesheet_payment_overrides) as x(
        override_id text,
        timesheet_id text,
        candidate_id text,
        override_type text,
        reason text,
        created_at_utc text,
        created_by_user_id text,
        consumed_by_pay_batch_id text,
        consumed_at_utc text
      )
    loop
      begin
        perform public._audit_insert(
          'timesheets',
          v_override_consume_rec.timesheet_id::text,
          'TIMESHEET_PAYMENT_OVERRIDE_CONSUMED',
          jsonb_build_object(
            'override_id', v_override_consume_rec.override_id::text,
            'timesheet_id', v_override_consume_rec.timesheet_id::text,
            'candidate_id', case when v_override_consume_rec.candidate_id is null then null else v_override_consume_rec.candidate_id::text end,
            'override_type', v_override_consume_rec.override_type,
            'reason', v_override_consume_rec.reason,
            'created_at_utc', v_override_consume_rec.created_at_utc,
            'created_by_user_id', case when v_override_consume_rec.created_by_user_id is null then null else v_override_consume_rec.created_by_user_id::text end
          ),
          jsonb_build_object(
            'override_id', v_override_consume_rec.override_id::text,
            'timesheet_id', v_override_consume_rec.timesheet_id::text,
            'candidate_id', case when v_override_consume_rec.candidate_id is null then null else v_override_consume_rec.candidate_id::text end,
            'consumed_by_pay_batch_id', case when v_override_consume_rec.consumed_by_pay_batch_id is null then null else v_override_consume_rec.consumed_by_pay_batch_id::text end,
            'consumed_at_utc', v_override_consume_rec.consumed_at_utc,
            'pay_batch_id', v_batch_id::text
          ),
          'ADVANCE_THIS_PAYMENT',
          p_actor_user_id
        );
      exception when others then
        null;
      end;
    end loop;
  end if;

  


  v_stage := 'STAGE_23C_ASSERT_ADVANCE_OVERRIDE_CONSUMPTION';

  IF p_operation_id IS NOT NULL THEN
    WITH selected_advanced_lines AS (
      SELECT
        scope_row.id AS candidate_scope_id,
        scope_row.candidate_id,
        scope_row.pay_channel,
        COALESCE(
          NULLIF(BTRIM(COALESCE(line_element.value->>'preview_row_id', '')), ''),
          NULLIF(BTRIM(COALESCE(line_element.value->>'line_id', '')), ''),
          NULLIF(BTRIM(COALESCE(line_element.value->>'row_id', '')), ''),
          NULLIF(BTRIM(COALESCE(line_element.value->>'id', '')), '')
        ) AS preview_row_id,
        CASE
          WHEN COALESCE(line_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (line_element.value->>'timesheet_id')::uuid
          ELSE NULL::uuid
        END AS timesheet_id,
        CASE
          WHEN COALESCE(line_element.value->>'advanced_override_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (line_element.value->>'advanced_override_id')::uuid
          ELSE NULL::uuid
        END AS advanced_override_id,
        NULLIF(BTRIM(COALESCE(line_element.value->>'advanced_override_id', '')), '') AS raw_advanced_override_id,
        lower(coalesce(line_element.value->>'is_advanced', 'false')) IN ('true','t','1','yes','y') AS is_advanced
      FROM public.banking_pay_operation_candidate_scope AS scope_row
      CROSS JOIN LATERAL jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS line_element(value)
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = v_batch_id
        AND jsonb_typeof(line_element.value) = 'object'
        AND (
          lower(coalesce(line_element.value->>'is_advanced', 'false')) IN ('true','t','1','yes','y')
          OR NULLIF(BTRIM(COALESCE(line_element.value->>'advanced_override_id', '')), '') IS NOT NULL
        )
    ), expected_advanced_overrides AS (
      SELECT DISTINCT
        selected_advanced_lines.candidate_scope_id,
        selected_advanced_lines.candidate_id,
        selected_advanced_lines.pay_channel,
        selected_advanced_lines.preview_row_id,
        selected_advanced_lines.timesheet_id,
        selected_advanced_lines.advanced_override_id,
        selected_advanced_lines.raw_advanced_override_id
      FROM selected_advanced_lines
      WHERE selected_advanced_lines.timesheet_id IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS entitlement_item
          JOIN public.pay_batch_candidates AS entitlement_candidate
            ON entitlement_candidate.id = entitlement_item.pay_batch_candidate_id
          WHERE entitlement_candidate.pay_batch_id = v_batch_id
            AND entitlement_candidate.candidate_id = selected_advanced_lines.candidate_id
            AND entitlement_item.timesheet_id = selected_advanced_lines.timesheet_id
            AND coalesce(entitlement_item.is_voided, false) = false
            AND entitlement_item.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            AND (
              entitlement_item.operation_source_key IS NULL
              OR entitlement_item.operation_source_key LIKE (p_operation_id::text || ':%')
              OR EXISTS (
                SELECT 1
                FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
                WHERE allocation_row.operation_id = p_operation_id
                  AND allocation_row.pay_batch_id = v_batch_id
                  AND allocation_row.pay_batch_item_id = entitlement_item.id
              )
            )
          LIMIT 1
        )
    ), matched_advanced_overrides AS (
      SELECT
        expected_advanced_overrides.candidate_scope_id,
        expected_advanced_overrides.candidate_id,
        expected_advanced_overrides.pay_channel,
        expected_advanced_overrides.preview_row_id,
        expected_advanced_overrides.timesheet_id,
        expected_advanced_overrides.advanced_override_id,
        expected_advanced_overrides.raw_advanced_override_id,
        COUNT(matching_override.id)::integer AS matching_consumed_count
      FROM expected_advanced_overrides
      LEFT JOIN public.timesheet_payment_overrides AS matching_override
        ON matching_override.id = expected_advanced_overrides.advanced_override_id
       AND matching_override.timesheet_id = expected_advanced_overrides.timesheet_id
       AND matching_override.candidate_id = expected_advanced_overrides.candidate_id
       AND upper(coalesce(matching_override.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
       AND matching_override.cleared_at_utc IS NULL
       AND matching_override.consumed_by_pay_batch_id = v_batch_id
       AND matching_override.consumed_at_utc IS NOT NULL
      GROUP BY
        expected_advanced_overrides.candidate_scope_id,
        expected_advanced_overrides.candidate_id,
        expected_advanced_overrides.pay_channel,
        expected_advanced_overrides.preview_row_id,
        expected_advanced_overrides.timesheet_id,
        expected_advanced_overrides.advanced_override_id,
        expected_advanced_overrides.raw_advanced_override_id
    ), mismatch_rows AS (
      SELECT
        matched_advanced_overrides.*,
        CASE
          WHEN matched_advanced_overrides.advanced_override_id IS NULL THEN 'ADVANCED_OVERRIDE_ID_MISSING_OR_INVALID'
          ELSE 'PAY_DRAFT_ADVANCE_OVERRIDE_NOT_CONSUMED'
        END AS reason_code
      FROM matched_advanced_overrides
      WHERE matched_advanced_overrides.advanced_override_id IS NULL
         OR matched_advanced_overrides.matching_consumed_count <> 1
    )
    SELECT
      (SELECT COUNT(*)::integer FROM expected_advanced_overrides),
      COALESCE((
        SELECT jsonb_agg(to_jsonb(expected_ids.advanced_override_id::text) ORDER BY expected_ids.advanced_override_id::text)
        FROM (
          SELECT DISTINCT expected_advanced_overrides.advanced_override_id
          FROM expected_advanced_overrides
          WHERE expected_advanced_overrides.advanced_override_id IS NOT NULL
        ) AS expected_ids
      ), '[]'::jsonb),
      (SELECT COUNT(*)::integer FROM mismatch_rows),
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'check_code', 'PAY_DRAFT_ADVANCE_OVERRIDE_NOT_CONSUMED',
            'reason_code', mismatch_rows.reason_code,
            'candidate_scope_id', mismatch_rows.candidate_scope_id::text,
            'candidate_id', mismatch_rows.candidate_id::text,
            'pay_channel', mismatch_rows.pay_channel,
            'preview_row_id', mismatch_rows.preview_row_id,
            'timesheet_id', mismatch_rows.timesheet_id::text,
            'advanced_override_id', CASE WHEN mismatch_rows.advanced_override_id IS NULL THEN NULL ELSE mismatch_rows.advanced_override_id::text END,
            'raw_advanced_override_id', mismatch_rows.raw_advanced_override_id,
            'matching_consumed_count', mismatch_rows.matching_consumed_count
          )
          ORDER BY mismatch_rows.candidate_id::text, mismatch_rows.timesheet_id::text, mismatch_rows.preview_row_id
        )
        FROM mismatch_rows
      ), '[]'::jsonb)
    INTO
      v_expected_advance_override_count,
      v_expected_advance_override_ids,
      v_advance_override_consumption_mismatch_count,
      v_advance_override_consumption_mismatches;

    BEGIN
      PERFORM public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:STAGE_23C_ADVANCE_OVERRIDE_CONSUMPTION_ASSERT_RESULT',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'operation_id', p_operation_id::text,
          'expected_advance_override_count', coalesce(v_expected_advance_override_count, 0),
          'expected_advance_override_ids', coalesce(v_expected_advance_override_ids, '[]'::jsonb),
          'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
          'consumed_timesheet_payment_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb),
          'advance_override_consumption_mismatch_count', coalesce(v_advance_override_consumption_mismatch_count, 0),
          'advance_override_consumption_mismatches', coalesce(v_advance_override_consumption_mismatches, '[]'::jsonb)
        ),
        'pay_batches',
        v_batch_id::text,
        NULL, NULL, NULL, NULL, NULL
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    IF coalesce(v_advance_override_consumption_mismatch_count, 0) > 0 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'error', 'PAY_DRAFT_ADVANCE_OVERRIDE_NOT_CONSUMED',
        'code', 'PAY_DRAFT_ADVANCE_OVERRIDE_NOT_CONSUMED',
        'message', 'Draft integrity failed because one or more selected Advance Pay overrides were not consumed by the draft batch.',
        'friendly_error_message', 'Draft integrity failed because one or more selected Advance Pay overrides were not consumed by the draft batch.',
        'mismatch_details', coalesce(v_advance_override_consumption_mismatches, '[]'::jsonb),
        'affected_candidate_ids', coalesce((
          SELECT jsonb_agg(DISTINCT mismatch_value.value->>'candidate_id')
          FROM jsonb_array_elements(coalesce(v_advance_override_consumption_mismatches, '[]'::jsonb)) AS mismatch_value(value)
          WHERE NULLIF(mismatch_value.value->>'candidate_id', '') IS NOT NULL
        ), '[]'::jsonb),
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb),
        'expected_advance_override_count', coalesce(v_expected_advance_override_count, 0),
        'expected_advance_override_ids', coalesce(v_expected_advance_override_ids, '[]'::jsonb)
      );
    END IF;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_operation_active_item_count
    FROM public.pay_batch_items AS item_row
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = item_row.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = v_batch_id
      AND coalesce(item_row.is_voided, false) = false
      AND (
        (
          item_row.operation_source_key IS NOT NULL
          AND item_row.operation_source_key LIKE (p_operation_id::text || ':%')
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS linked_allocation_row
          WHERE linked_allocation_row.operation_id = p_operation_id
            AND linked_allocation_row.pay_batch_id = v_batch_id
            AND linked_allocation_row.pay_batch_item_id = item_row.id
        )
      );

    SELECT count(*)::integer,
           count(*) FILTER (
             WHERE lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) IN ('true','t','1','yes','y')
           )::integer
    INTO v_operation_scope_count, v_operation_reservation_unavailable_scope_count
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = v_batch_id;

    IF coalesce(v_operation_active_item_count, 0) = 0 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'error', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED'
          ELSE 'PAY_DRAFT_NO_PAYABLE_ITEMS_REMAIN'
        END,
        'code', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED'
          ELSE 'PAY_DRAFT_NO_PAYABLE_ITEMS_REMAIN'
        END,
        'message', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'No draft was created because all selected payments are already reserved in another active draft batch.'
          ELSE 'No draft was created because no payable items remained after eligibility checks.'
        END,
        'friendly_error_message', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'No draft was created because all selected payments are already reserved in another active draft batch.'
          ELSE 'No draft was created because no payable items remained after eligibility checks.'
        END,
        'mismatch_details', jsonb_build_array(jsonb_build_object(
          'check_code', CASE
            WHEN coalesce(v_operation_scope_count, 0) > 0
             AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
              THEN 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED'
            ELSE 'PAY_DRAFT_NO_PAYABLE_ITEMS_REMAIN'
          END,
          'active_item_count', coalesce(v_operation_active_item_count, 0),
          'operation_scope_count', coalesce(v_operation_scope_count, 0),
          'reservation_unavailable_scope_count', coalesce(v_operation_reservation_unavailable_scope_count, 0)
        )),
        'affected_candidate_ids', coalesce(to_jsonb(v_candidate_ids), '[]'::jsonb),
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb)
      );
    END IF;

    WITH operation_checks AS (
      SELECT 'MISSING_BATCH_CANDIDATE'::text AS check_code,
             scope_row.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', scope_row.id::text,
               'candidate_id', scope_row.candidate_id::text,
               'pay_channel', scope_row.pay_channel
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = v_batch_id
        AND lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) NOT IN ('true','t','1','yes','y')
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS batch_candidate
          WHERE batch_candidate.pay_batch_id = v_batch_id
            AND batch_candidate.candidate_id = scope_row.candidate_id
        )

      UNION ALL

      SELECT 'UNLINKED_ALLOCATION_ROW'::text AS check_code,
             allocation_row.candidate_id,
             jsonb_build_object(
               'allocation_row_id', allocation_row.id::text,
               'candidate_scope_id', allocation_row.candidate_scope_id::text,
               'candidate_id', allocation_row.candidate_id::text,
               'pay_channel', allocation_row.pay_channel,
               'operation_source_key', allocation_row.operation_source_key
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.pay_batch_id = v_batch_id
        AND (UPPER(BTRIM(COALESCE(allocation_row.status, ''))) NOT IN ('ITEM_CREATED', 'ITEM_INSERTED') OR allocation_row.pay_batch_item_id IS NULL)

      UNION ALL

      SELECT 'DUPLICATE_BATCH_CANDIDATE'::text AS check_code,
             duplicate_candidate.candidate_id,
             jsonb_build_object(
               'candidate_id', duplicate_candidate.candidate_id::text,
               'duplicate_count', duplicate_candidate.duplicate_count
             ) AS detail_json
      FROM (
        SELECT batch_candidate.candidate_id, count(*)::integer AS duplicate_count
        FROM public.pay_batch_candidates AS batch_candidate
        WHERE batch_candidate.pay_batch_id = v_batch_id
          AND batch_candidate.candidate_id = ANY(v_candidate_ids)
        GROUP BY batch_candidate.candidate_id
        HAVING count(*) > 1
      ) AS duplicate_candidate

      UNION ALL

      SELECT 'DUPLICATE_OPERATION_ITEM_KEY'::text AS check_code,
             batch_candidate.candidate_id,
             jsonb_build_object(
               'candidate_id', batch_candidate.candidate_id::text,
               'operation_source_key', duplicate_item.operation_source_key,
               'duplicate_count', duplicate_item.duplicate_count
             ) AS detail_json
      FROM (
        SELECT item_row.pay_batch_candidate_id, item_row.operation_source_key, count(*)::integer AS duplicate_count
        FROM public.pay_batch_items AS item_row
        WHERE item_row.operation_source_key IS NOT NULL
          AND item_row.operation_source_key LIKE (p_operation_id::text || ':%')
        GROUP BY item_row.pay_batch_candidate_id, item_row.operation_source_key
        HAVING count(*) > 1
      ) AS duplicate_item
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = duplicate_item.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = v_batch_id

      UNION ALL

      SELECT 'DUPLICATE_OPERATION_BREAKDOWN_KEY'::text AS check_code,
             batch_candidate.candidate_id,
             jsonb_build_object(
               'candidate_id', batch_candidate.candidate_id::text,
               'operation_source_key', duplicate_breakdown.operation_source_key,
               'duplicate_count', duplicate_breakdown.duplicate_count
             ) AS detail_json
      FROM (
        SELECT breakdown_row.pay_batch_item_id, breakdown_row.operation_source_key, count(*)::integer AS duplicate_count
        FROM public.pay_batch_item_breakdowns AS breakdown_row
        WHERE breakdown_row.operation_source_key IS NOT NULL
          AND breakdown_row.operation_source_key LIKE (p_operation_id::text || ':%')
        GROUP BY breakdown_row.pay_batch_item_id, breakdown_row.operation_source_key
        HAVING count(*) > 1
      ) AS duplicate_breakdown
      JOIN public.pay_batch_items AS item_row
        ON item_row.id = duplicate_breakdown.pay_batch_item_id
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = item_row.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = v_batch_id

      UNION ALL

      SELECT 'DUPLICATE_TIMESHEET_SNAPSHOT'::text AS check_code,
             snapshot_duplicate.candidate_id,
             jsonb_build_object(
               'timesheet_id', snapshot_duplicate.timesheet_id::text,
               'candidate_id', snapshot_duplicate.candidate_id::text,
               'pay_channel', snapshot_duplicate.pay_channel,
               'duplicate_count', snapshot_duplicate.duplicate_count
             ) AS detail_json
      FROM (
        SELECT snapshot_row.timesheet_id, snapshot_row.candidate_id, snapshot_row.pay_channel, count(*)::integer AS duplicate_count
        FROM public.pay_batch_timesheet_snapshots AS snapshot_row
        WHERE snapshot_row.pay_batch_id = v_batch_id
          AND snapshot_row.candidate_id = ANY(v_candidate_ids)
        GROUP BY snapshot_row.timesheet_id, snapshot_row.candidate_id, snapshot_row.pay_channel
        HAVING count(*) > 1
      ) AS snapshot_duplicate

      UNION ALL

      SELECT 'MISSING_TIMESHEET_SNAPSHOT'::text AS check_code,
             batch_candidate.candidate_id,
             jsonb_build_object(
               'pay_batch_item_id', item_row.id::text,
               'candidate_id', batch_candidate.candidate_id::text,
               'timesheet_id', item_row.timesheet_id::text,
               'pay_channel', item_row.pay_channel,
               'operation_source_key', item_row.operation_source_key
             ) AS detail_json
      FROM public.pay_batch_items AS item_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = item_row.pay_batch_candidate_id
      WHERE batch_candidate.pay_batch_id = v_batch_id
        AND coalesce(item_row.is_voided, false) = false
        AND item_row.operation_source_key IS NOT NULL
        AND item_row.operation_source_key LIKE (p_operation_id::text || ':%')
        AND item_row.timesheet_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(item_row.item_type::text, ''))) IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_timesheet_snapshots AS snapshot_row
          WHERE snapshot_row.pay_batch_id = v_batch_id
            AND snapshot_row.timesheet_id = item_row.timesheet_id
            AND snapshot_row.candidate_id = batch_candidate.candidate_id
            AND UPPER(BTRIM(COALESCE(snapshot_row.pay_channel, ''))) = UPPER(BTRIM(COALESCE(item_row.pay_channel, '')))
        )

      UNION ALL

      SELECT 'DRAFT_SCOPE_SELECTED_LINES_MISSING'::text AS check_code,
             scope_row.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', scope_row.id::text,
               'candidate_id', scope_row.candidate_id::text,
               'pay_channel', scope_row.pay_channel,
               'selected_row_count_seeded_in_page', CASE
                 WHEN COALESCE(scope_row.candidate_totals_json->>'selected_row_count_seeded_in_page', '') ~ '^[0-9]+$'
                   THEN (scope_row.candidate_totals_json->>'selected_row_count_seeded_in_page')::integer
                 WHEN COALESCE(scope_row.candidate_totals_json->>'selected_preview_row_count', '') ~ '^[0-9]+$'
                   THEN (scope_row.candidate_totals_json->>'selected_preview_row_count')::integer
                 WHEN COALESCE(scope_row.candidate_totals_json->>'selected_row_count', '') ~ '^[0-9]+$'
                   THEN (scope_row.candidate_totals_json->>'selected_row_count')::integer
                 ELSE 0
               END,
               'selected_canonical_preview_lines_count', CASE
                 WHEN jsonb_typeof(scope_row.selected_canonical_preview_lines_json) = 'array'
                   THEN jsonb_array_length(scope_row.selected_canonical_preview_lines_json)
                 ELSE 0
               END
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = v_batch_id
        AND lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) NOT IN ('true','t','1','yes','y')
        AND (
          CASE
            WHEN COALESCE(scope_row.candidate_totals_json->>'selected_row_count_seeded_in_page', '') ~ '^[0-9]+$'
              THEN (scope_row.candidate_totals_json->>'selected_row_count_seeded_in_page')::integer
            WHEN COALESCE(scope_row.candidate_totals_json->>'selected_preview_row_count', '') ~ '^[0-9]+$'
              THEN (scope_row.candidate_totals_json->>'selected_preview_row_count')::integer
            WHEN COALESCE(scope_row.candidate_totals_json->>'selected_row_count', '') ~ '^[0-9]+$'
              THEN (scope_row.candidate_totals_json->>'selected_row_count')::integer
            ELSE 0
          END
        ) > 0
        AND NOT (
          jsonb_typeof(scope_row.selected_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(scope_row.selected_canonical_preview_lines_json) > 0
        )

      UNION ALL

      SELECT 'MISSING_SELECTED_PREVIEW_ROW_ITEM'::text AS check_code,
             selected_line.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', selected_line.candidate_scope_id::text,
               'candidate_id', selected_line.candidate_id::text,
               'pay_channel', selected_line.pay_channel,
               'preview_row_id', selected_line.preview_row_id,
               'finance_case_id', CASE WHEN selected_line.finance_case_id IS NULL THEN NULL ELSE selected_line.finance_case_id::text END,
               'timesheet_id', CASE WHEN selected_line.timesheet_id IS NULL THEN NULL ELSE selected_line.timesheet_id::text END
             ) AS detail_json
      FROM (
        SELECT
          scope_row.id AS candidate_scope_id,
          scope_row.candidate_id,
          scope_row.pay_channel,
          coalesce(
            nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'id', '')), '')
          ) AS preview_row_id,
          CASE WHEN coalesce(line_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (line_element.value->>'finance_case_id')::uuid ELSE NULL::uuid END AS finance_case_id,
          CASE WHEN coalesce(line_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (line_element.value->>'timesheet_id')::uuid ELSE NULL::uuid END AS timesheet_id,
          upper(btrim(coalesce(line_element.value->>'line_type', line_element.value->>'item_type', line_element.value->>'case_type', ''))) AS line_type,
          round(coalesce(
            CASE WHEN coalesce(reservation_metadata.reservation_json->>'effective_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (reservation_metadata.reservation_json->>'effective_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN coalesce(line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN coalesce(line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
            0::numeric
          ), 2) AS expected_amount_ex_vat,
          coalesce(
            lower(coalesce(reservation_metadata.reservation_json->>'skipped_due_to_active_reservation', 'false')) IN ('true','t','1','yes','y'),
            false
          ) AS skipped_due_to_active_reservation
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        CROSS JOIN LATERAL jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS line_element(value)
        LEFT JOIN LATERAL (
          SELECT reservation_row.value AS reservation_json
          FROM jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}') = 'array'
                THEN scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}'
              ELSE '[]'::jsonb
            END
          ) AS reservation_row(value)
          WHERE reservation_row.value->>'preview_row_id' = coalesce(
            nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'id', '')), '')
          )
          LIMIT 1
        ) AS reservation_metadata ON true
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = v_batch_id
          AND jsonb_typeof(line_element.value) = 'object'
          AND coalesce(CASE WHEN lower(coalesce(line_element.value->>'draftable', 'true')) IN ('true','false') THEN (line_element.value->>'draftable')::boolean ELSE true END, true) = true
      ) AS selected_line
      WHERE selected_line.preview_row_id IS NOT NULL
        AND coalesce(selected_line.skipped_due_to_active_reservation, false) = false
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS batch_candidate
          JOIN public.pay_batch_items AS item_row
            ON item_row.pay_batch_candidate_id = batch_candidate.id
          WHERE batch_candidate.pay_batch_id = v_batch_id
            AND batch_candidate.candidate_id = selected_line.candidate_id
            AND coalesce(item_row.is_voided, false) = false
            AND (
              item_row.operation_source_key IS NOT NULL
              AND item_row.operation_source_key LIKE (p_operation_id::text || ':%')
              AND item_row.operation_source_key LIKE ('%' || selected_line.preview_row_id || '%')
            )
          LIMIT 1
        )

      UNION ALL

      SELECT 'CANDIDATE_SCOPE_TOTAL_MISMATCH'::text AS check_code,
             scope_totals.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', scope_totals.candidate_scope_id::text,
               'candidate_id', scope_totals.candidate_id::text,
               'pay_channel', scope_totals.pay_channel,
               'expected_amount_ex_vat', scope_totals.expected_amount_ex_vat,
               'actual_amount_ex_vat', scope_totals.actual_amount_ex_vat
             ) AS detail_json
      FROM (
        SELECT
          scope_row.id AS candidate_scope_id,
          scope_row.candidate_id,
          scope_row.pay_channel,
          round(coalesce((
            SELECT sum(
              round(coalesce(
                CASE WHEN coalesce(reservation_metadata.reservation_json->>'effective_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (reservation_metadata.reservation_json->>'effective_amount_ex_vat')::numeric ELSE NULL::numeric END,
                CASE WHEN coalesce(selected_line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_line_element.value->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
                CASE WHEN coalesce(selected_line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_line_element.value->>'preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
                0::numeric
              ), 2)
            )
            FROM jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS selected_line_element(value)
            LEFT JOIN LATERAL (
              SELECT reservation_row.value AS reservation_json
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}') = 'array'
                    THEN scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}'
                  ELSE '[]'::jsonb
                END
              ) AS reservation_row(value)
              WHERE reservation_row.value->>'preview_row_id' = coalesce(
                nullif(btrim(coalesce(selected_line_element.value->>'preview_row_id', '')), ''),
                nullif(btrim(coalesce(selected_line_element.value->>'line_id', '')), ''),
                nullif(btrim(coalesce(selected_line_element.value->>'row_id', '')), ''),
                nullif(btrim(coalesce(selected_line_element.value->>'id', '')), '')
              )
              LIMIT 1
            ) AS reservation_metadata ON true
            WHERE jsonb_typeof(selected_line_element.value) = 'object'
              AND coalesce(CASE WHEN lower(coalesce(selected_line_element.value->>'draftable', 'true')) IN ('true','false') THEN (selected_line_element.value->>'draftable')::boolean ELSE true END, true) = true
          ), 0::numeric), 2) AS expected_amount_ex_vat,
          round(coalesce((
            SELECT sum(coalesce(item_row.amount_ex_vat, 0))
            FROM public.pay_batch_candidates AS batch_candidate
            JOIN public.pay_batch_items AS item_row
              ON item_row.pay_batch_candidate_id = batch_candidate.id
            WHERE batch_candidate.pay_batch_id = v_batch_id
              AND batch_candidate.candidate_id = scope_row.candidate_id
              AND upper(coalesce(item_row.pay_channel, '')) = upper(coalesce(scope_row.pay_channel, ''))
              AND coalesce(item_row.is_voided, false) = false
          ), 0), 2) AS actual_amount_ex_vat
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = v_batch_id
      ) AS scope_totals
      WHERE scope_totals.expected_amount_ex_vat IS NOT NULL
        AND scope_totals.expected_amount_ex_vat <> scope_totals.actual_amount_ex_vat

      UNION ALL

      SELECT 'ALLOCATION_ITEM_AMOUNT_MISMATCH'::text AS check_code,
             allocation_row.candidate_id,
             jsonb_build_object(
               'allocation_row_id', allocation_row.id::text,
               'pay_batch_item_id', CASE WHEN item_row.id IS NULL THEN NULL ELSE item_row.id::text END,
               'candidate_id', allocation_row.candidate_id::text,
               'pay_channel', allocation_row.pay_channel,
               'operation_source_key', allocation_row.operation_source_key,
               'expected_allocated_amount', round(coalesce(allocation_row.allocated_amount, 0), 2),
               'actual_item_amount_ex_vat', CASE WHEN item_row.id IS NULL THEN NULL ELSE round(coalesce(item_row.amount_ex_vat, 0), 2) END
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      LEFT JOIN public.pay_batch_items AS item_row
        ON item_row.id = allocation_row.pay_batch_item_id
       AND coalesce(item_row.is_voided, false) = false
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.pay_batch_id = v_batch_id
        AND UPPER(BTRIM(COALESCE(allocation_row.status, ''))) IN ('ITEM_CREATED', 'ITEM_INSERTED')
        AND (
          item_row.id IS NULL
          OR round(coalesce(item_row.amount_ex_vat, 0), 2) <> round(coalesce(allocation_row.allocated_amount, 0), 2)
        )

      UNION ALL

      SELECT 'PAY_CHANNEL_SCOPE_TOTAL_MISMATCH'::text AS check_code,
             NULL::uuid AS candidate_id,
             jsonb_build_object(
               'pay_channel', channel_totals.pay_channel,
               'expected_amount_ex_vat', channel_totals.expected_amount_ex_vat,
               'actual_amount_ex_vat', channel_totals.actual_amount_ex_vat
             ) AS detail_json
      FROM (
        SELECT
          expected_channel.pay_channel,
          round(sum(expected_channel.expected_amount_ex_vat), 2) AS expected_amount_ex_vat,
          round(coalesce((
            SELECT sum(coalesce(item_row.amount_ex_vat, 0))
            FROM public.pay_batch_items AS item_row
            JOIN public.pay_batch_candidates AS batch_candidate
              ON batch_candidate.id = item_row.pay_batch_candidate_id
            WHERE batch_candidate.pay_batch_id = v_batch_id
              AND upper(coalesce(item_row.pay_channel, '')) = expected_channel.pay_channel
              AND coalesce(item_row.is_voided, false) = false
          ), 0), 2) AS actual_amount_ex_vat
        FROM (
          SELECT
            upper(btrim(coalesce(scope_row.pay_channel, ''))) AS pay_channel,
            round(coalesce(
              CASE WHEN coalesce(reservation_metadata.reservation_json->>'effective_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (reservation_metadata.reservation_json->>'effective_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN coalesce(line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN coalesce(line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
              0::numeric
            ), 2) AS expected_amount_ex_vat
          FROM public.banking_pay_operation_candidate_scope AS scope_row
          CROSS JOIN LATERAL jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS line_element(value)
          LEFT JOIN LATERAL (
            SELECT reservation_row.value AS reservation_json
            FROM jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}') = 'array'
                  THEN scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}'
                ELSE '[]'::jsonb
              END
            ) AS reservation_row(value)
            WHERE reservation_row.value->>'preview_row_id' = coalesce(
              nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''),
              nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''),
              nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''),
              nullif(btrim(coalesce(line_element.value->>'id', '')), '')
            )
            LIMIT 1
          ) AS reservation_metadata ON true
          WHERE scope_row.operation_id = p_operation_id
            AND scope_row.pay_batch_id = v_batch_id
            AND jsonb_typeof(line_element.value) = 'object'
            AND coalesce(CASE WHEN lower(coalesce(line_element.value->>'draftable', 'true')) IN ('true','false') THEN (line_element.value->>'draftable')::boolean ELSE true END, true) = true
        ) AS expected_channel
        WHERE expected_channel.pay_channel IN ('PAYE','UMBRELLA')
        GROUP BY expected_channel.pay_channel
      ) AS channel_totals
      WHERE channel_totals.expected_amount_ex_vat <> channel_totals.actual_amount_ex_vat
    )
    SELECT count(*)::integer,
           coalesce(jsonb_agg(operation_checks.detail_json || jsonb_build_object('check_code', operation_checks.check_code) order by operation_checks.check_code, operation_checks.candidate_id::text), '[]'::jsonb),
           coalesce(jsonb_agg(distinct to_jsonb(operation_checks.candidate_id::text)) filter (where operation_checks.candidate_id is not null), '[]'::jsonb)
    INTO v_operation_mismatch_count, v_operation_mismatch_details, v_operation_affected_candidate_ids
    FROM operation_checks;

    IF coalesce(v_operation_mismatch_count, 0) > 0 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'error', 'DRAFT_INTEGRITY_FAILED',
        'code', 'DRAFT_INTEGRITY_FAILED',
        'mismatch_details', coalesce(v_operation_mismatch_details, '[]'::jsonb),
        'affected_candidate_ids', coalesce(v_operation_affected_candidate_ids, '[]'::jsonb),
        'friendly_error_message', 'Operation draft integrity checks failed. The chunked draft does not exactly match the snapshotted operation scope.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb)
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'pass', true,
    'mismatch_details', coalesce(v_operation_mismatch_details, '{}'::jsonb),
    'affected_candidate_ids', coalesce(v_operation_affected_candidate_ids, '[]'::jsonb),
    'generation_provenance', CASE
      WHEN p_operation_id IS NULL THEN NULL::jsonb
      ELSE v_generation_provenance_json
    END,
    'friendly_error_message', null::text,
    'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
    'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
    'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
    'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_override_ids', coalesce(v_consumed_timesheet_payment_override_ids, '[]'::jsonb)
  );
END;
$function$;

-- pay_batch_auth_apply_action(uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.pay_batch_auth_apply_action(p_auth_request_id uuid, p_actor_user_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
declare
  v_now timestamptz := now();
  v_action text := upper(btrim(coalesce(p_action,'')));

  v_req record;
  v_user record;

  v_inserted_id uuid := null;
  v_approved_count int := 0;

  v_became_authorised boolean := false;
  v_new_auth_state text := null;
  v_new_batch_status text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;

  v_schedule_kind text := null;
  v_scheduled_at_utc timestamptz := null;
  v_funding_account_ref text := null;
  v_funds_warning_hours_json jsonb := null;
  v_schedule_result jsonb := '{}'::jsonb;
  v_worker_communications jsonb := '{}'::jsonb;
  v_remittance_queue_stage_result jsonb := '{}'::jsonb;
  v_remittance_send_timing text := 'ON_EXECUTION';
  v_pay_batch_id uuid := null::uuid;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_active_scope_hash text := null::text;
  v_payment_operation_id uuid := null::uuid;
begin
  if p_auth_request_id is null then
    raise exception 'pay_batch_auth_apply_action: auth_request_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_batch_auth_apply_action: actor_user_id is required';
  end if;

  if v_action not in ('AUTHORISE','USE_GOLDEN_KEY','REJECT') then
    raise exception 'pay_batch_auth_apply_action: invalid action (AUTHORISE|USE_GOLDEN_KEY|REJECT)';
  end if;

  select auth_lookup.pay_batch_id
  into v_pay_batch_id
  from public.pay_batch_auth_requests as auth_lookup
  where auth_lookup.id = p_auth_request_id;

  if v_pay_batch_id is null then
    raise exception 'pay_batch_auth_apply_action: auth_request not found';
  end if;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    v_pay_batch_id,
    null::uuid,
    'NEW_PAYMENT_ACTION'
  );

  if coalesce((v_mutation_guard->>'blocked')::boolean, true) then
    raise exception 'PAYMENT_CHANGE_IN_PROGRESS'
      using errcode = 'P0001', detail = jsonb_build_object(
        'code', coalesce(v_mutation_guard->>'code', 'PAYMENT_CHANGE_IN_PROGRESS'),
        'message', coalesce(v_mutation_guard->>'message', 'A payment change is in progress.'),
        'pay_batch_id', v_pay_batch_id
      )::text;
  end if;

  select
    pbar.id,
    pbar.pay_batch_id,
    pbar.state,
    pbar.required_quantity,
    pbar.schedule_kind,
    pbar.scheduled_at_utc,
    pbar.funding_account_ref,
    pbar.funds_warning_hours_json,
    pbar.execution_intent_json
  into v_req
  from public.pay_batch_auth_requests pbar
  where pbar.id = p_auth_request_id
  for update;

  if v_req.id is null then
    raise exception 'pay_batch_auth_apply_action: auth_request not found';
  end if;

  if v_req.state <> 'AWAITING' then
    raise exception 'pay_batch_auth_apply_action: auth_request must be AWAITING (current=%)', v_req.state;
  end if;

  if v_req.execution_intent_json is not null and jsonb_typeof(v_req.execution_intent_json) = 'object' then
    v_execution_intent_json := v_req.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  v_active_scope_hash := private.pay_payment_correction_sha256_v1(
    jsonb_build_object(
      'version', 1,
      'pay_batch_id', v_req.pay_batch_id,
      'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
      'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
      'active_items', (
        select coalesce(
          jsonb_agg(
            jsonb_build_array(
              candidate_row.id,
              item_row.id,
              round(coalesce(item_row.amount_inc_vat, 0) * 100)::bigint,
              item_row.item_type,
              item_row.pay_channel,
              item_row.reservation_id,
              item_row.finance_component_id,
              item_row.pay_bank_transfer_id
            )
            order by candidate_row.id, item_row.id
          ),
          '[]'::jsonb
        )
        from public.pay_batch_candidates as candidate_row
        join public.pay_batch_items as item_row
          on item_row.pay_batch_candidate_id = candidate_row.id
        where candidate_row.pay_batch_id = v_req.pay_batch_id
          and coalesce(item_row.is_voided, false) is not true
      )
    )
  );

  if nullif(btrim(coalesce(v_execution_intent_json->>'active_scope_hash', '')), '') is not null
     and v_execution_intent_json->>'active_scope_hash' is distinct from v_active_scope_hash then
    raise exception 'PAY_BATCH_AUTH_SCOPE_STALE'
      using errcode = 'P0001', detail = jsonb_build_object(
        'code', 'AUTH_SCOPE_STALE',
        'pay_batch_id', v_req.pay_batch_id,
        'expected_active_scope_hash', v_execution_intent_json->>'active_scope_hash',
        'actual_active_scope_hash', v_active_scope_hash
      )::text;
  end if;

  v_execution_intent_json := v_execution_intent_json || jsonb_build_object(
    'active_scope_hash', v_active_scope_hash,
    'active_scope_revalidated_at_utc', v_now
  );

  select coalesce(nullif(btrim(coalesce(sd.payment_remittance_send_timing, '')), ''), 'ON_EXECUTION')
  into v_remittance_send_timing
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  v_remittance_send_timing := coalesce(nullif(btrim(coalesce(v_remittance_send_timing, '')), ''), 'ON_EXECUTION');
  if v_remittance_send_timing not in ('ON_EXECUTION', 'ON_PAYMENT_CONFIRMED') then
    v_remittance_send_timing := 'ON_EXECUTION';
  end if;

  select
    tu.id,
    tu.is_active,
    tu.payment_authoriser,
    tu.payment_golden_key
  into v_user
  from public.tms_users tu
  where tu.id = p_actor_user_id
  limit 1;

  if v_user.id is null then
    raise exception 'pay_batch_auth_apply_action: actor_user not found';
  end if;

  if coalesce(v_user.is_active,false) = false then
    raise exception 'pay_batch_auth_apply_action: actor_user is not active';
  end if;

  if coalesce(v_user.payment_authoriser,false) = false and coalesce(v_user.payment_golden_key,false) = false then
    raise exception 'pay_batch_auth_apply_action: actor_user is not an authoriser';
  end if;

  if v_action = 'USE_GOLDEN_KEY' and coalesce(v_user.payment_golden_key,false) = false then
    raise exception 'pay_batch_auth_apply_action: actor_user does not have payment golden key';
  end if;

  perform public._imp_debug_audit(
    p_actor_user_id,
    'PAY_BATCH_AUTH_APPLY_ACTION_START',
    jsonb_build_object(
      'auth_request_id', p_auth_request_id::text,
      'pay_batch_id', v_req.pay_batch_id::text,
      'action', v_action,
      'required_quantity', v_req.required_quantity,
      'payment_remittance_send_timing', v_remittance_send_timing
    ),
    'pay_batch_auth_requests',
    p_auth_request_id::text,
    null::jsonb,
    null::text,
    null::text,
    null::text
  );

  insert into public.pay_batch_auth_actions(
    auth_request_id,
    pay_batch_id,
    actor_user_id,
    action,
    action_at_utc,
    note
  )
  values (
    p_auth_request_id,
    v_req.pay_batch_id,
    p_actor_user_id,
    v_action,
    v_now,
    p_note
  )
  on conflict on constraint ux_pay_batch_auth_actions_one_per_user
  do nothing
  returning id into v_inserted_id;

  if v_inserted_id is null then
    raise exception 'pay_batch_auth_apply_action: actor_user has already acted on this request';
  end if;

  if v_action = 'REJECT' then
    update public.pay_batch_auth_requests pbar2
    set
      state = 'REJECTED',
      finalised_at_utc = v_now,
      finalised_by_user_id = p_actor_user_id,
      golden_key_used = false,
      golden_key_user_id = null
    where pbar2.id = p_auth_request_id;

    update public.pay_batch_auth_tokens pbat2
    set used_at_utc = v_now
    where pbat2.auth_request_id = p_auth_request_id
      and pbat2.used_at_utc is null;

    update public.pay_batches pb2
    set
      status = 'READY',
      schedule_kind = null,
      scheduled_at_utc = null,
      scheduled_by_user_id = null,
      funding_account_ref = null,
      funds_warning_hours_json = null,
      execution_intent_json = null
    where pb2.id = v_req.pay_batch_id;
    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', false,
      'message_kind', 'NONE',
      'trigger_status', 'AUTH_REJECTED_NO_QUEUE',
      'dispatch_required', false,
      'error', null,
      'result', jsonb_build_object(
        'ok', true,
        'queued', false,
        'deferred', false,
        'dispatch_required', false,
        'trigger_status', 'AUTH_REJECTED_NO_QUEUE',
        'configured_timing', v_remittance_send_timing
      )
    );
    v_remittance_queue_stage_result := v_worker_communications->'result';

    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_AUTH_APPLY_ACTION_REJECTED',
      jsonb_build_object(
        'auth_request_id', p_auth_request_id::text,
        'pay_batch_id', v_req.pay_batch_id::text,
        'worker_communications', v_worker_communications
      ),
      'pay_batch_auth_requests',
      p_auth_request_id::text,
      null::jsonb,
      null::text,
      null::text,
      null::text
    );

    return jsonb_build_object(
      'ok', true,
      'pay_batch_id', v_req.pay_batch_id::text,
      'status', (select pb3.status from public.pay_batches pb3 where pb3.id = v_req.pay_batch_id),
      'auth_request_id', p_auth_request_id::text,
      'auth_state', 'REJECTED',
      'state', 'REJECTED',
      'operation_id', NULL,
      'schedule_revision', (
        select coalesce(pb_revision.source_scope_change_generation, 0)
        from public.pay_batches as pb_revision
        where pb_revision.id = v_req.pay_batch_id
      ),
      'active_scope_hash', v_active_scope_hash,
      'display_message', 'Payment authorisation rejected.',
      'required_quantity', v_req.required_quantity,
      'approved_count', 0,
      'became_authorised', false,
      'payment_remittance_send_timing', v_remittance_send_timing,
      'execution_intent_json', v_execution_intent_json,
      'execution_mode', v_execution_intent_json->>'execution_mode',
      'suppress_remittances', lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on'),
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', v_remittance_queue_stage_result
    );
  end if;

  select count(*)::int
  into v_approved_count
  from public.pay_batch_auth_actions pbaa0
  where pbaa0.auth_request_id = p_auth_request_id
    and pbaa0.action in ('AUTHORISE','USE_GOLDEN_KEY');

  if v_action = 'USE_GOLDEN_KEY' or v_approved_count >= greatest(1, coalesce(v_req.required_quantity,1)) then
    v_became_authorised := true;

    v_schedule_kind := upper(btrim(coalesce(
      nullif(v_req.schedule_kind, ''),
      nullif(v_execution_intent_json->>'schedule_kind', ''),
      'IMMEDIATE'
    )));
    if v_schedule_kind not in ('IMMEDIATE','SCHEDULED') then
      raise exception 'pay_batch_auth_apply_action: invalid stored schedule_kind %', v_schedule_kind;
    end if;

    v_scheduled_at_utc := v_req.scheduled_at_utc;
    if v_scheduled_at_utc is null and nullif(btrim(coalesce(v_execution_intent_json->>'scheduled_at_utc', '')), '') is not null then
      v_scheduled_at_utc := (v_execution_intent_json->>'scheduled_at_utc')::timestamptz;
    end if;
    if v_schedule_kind = 'SCHEDULED' and v_scheduled_at_utc is null then
      raise exception 'pay_batch_auth_apply_action: stored scheduled_at_utc is required for SCHEDULED authorisation';
    end if;

    v_funding_account_ref := v_req.funding_account_ref;
    v_funds_warning_hours_json := v_req.funds_warning_hours_json;

    update public.pay_batch_auth_requests pbar3
    set
      state = 'AUTHORISED',
      finalised_at_utc = v_now,
      finalised_by_user_id = p_actor_user_id,
      golden_key_used = case when v_action = 'USE_GOLDEN_KEY' then true else coalesce(pbar3.golden_key_used,false) end,
      golden_key_user_id = case when v_action = 'USE_GOLDEN_KEY' then p_actor_user_id else pbar3.golden_key_user_id end,
      execution_intent_json = v_execution_intent_json
    where pbar3.id = p_auth_request_id;

    update public.pay_batch_auth_tokens pbat3
    set used_at_utc = v_now
    where pbat3.auth_request_id = p_auth_request_id
      and pbat3.used_at_utc is null;

    update public.pay_batches pb_before_schedule
    set
      execution_intent_json = v_execution_intent_json,
      execution_commit_state = coalesce(nullif(btrim(coalesce(pb_before_schedule.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
    where pb_before_schedule.id = v_req.pay_batch_id;

    select started_operation.operation_id
    into v_payment_operation_id
    from public.banking_pay_operation_start(
      'PAYMENT_EXECUTE',
      p_actor_user_id,
      'payment-execute-auth:' || p_auth_request_id::text || ':' || v_active_scope_hash,
      null::uuid,
      v_req.pay_batch_id,
      null::uuid,
      jsonb_build_object(
        'auth_request_id', p_auth_request_id,
        'active_scope_hash', v_active_scope_hash,
        'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
        'initial_phase', 'INITIALISE',
        'backend_runner_owned', true
      ),
      jsonb_strip_nulls(jsonb_build_object(
        'run_after_utc', case
          when v_schedule_kind = 'SCHEDULED' then v_scheduled_at_utc
          else v_now
        end
      ))
    ) as started_operation
    limit 1;

    v_execution_intent_json := v_execution_intent_json || jsonb_build_object(
      'operation_id', v_payment_operation_id,
      'active_scope_hash', v_active_scope_hash
    );

    update public.pay_batch_auth_requests as auth_with_operation
    set execution_intent_json = v_execution_intent_json
    where auth_with_operation.id = p_auth_request_id;

    v_schedule_result := public.pay_batch_schedule(
      v_req.pay_batch_id,
      v_schedule_kind,
      v_scheduled_at_utc,
      v_funding_account_ref,
      v_funds_warning_hours_json,
      p_actor_user_id,
      v_payment_operation_id,
      v_execution_intent_json->>'freshness_result_hash'
    );

    update public.pay_batches pb4
    set
      status = 'AUTHORISED_FOR_PAYMENT',
      execution_intent_json = v_execution_intent_json,
      authoritative_payment_date = coalesce(
        pb4.authoritative_payment_date,
        (pb4.scheduled_at_utc at time zone 'Europe/London')::date,
        pb4.pay_date
      ),
      authoritative_payment_date_source = coalesce(pb4.authoritative_payment_date_source, 'AUTH_APPLY_SCHEDULED_AT_UTC')
    where pb4.id = v_req.pay_batch_id;

    v_worker_communications := coalesce(v_schedule_result->'worker_communications', '{}'::jsonb);
    v_remittance_queue_stage_result := coalesce(
      v_schedule_result->'remittance_queue_stage_result',
      v_worker_communications->'remittance_queue_stage_result',
      v_worker_communications->'result',
      '{}'::jsonb
    );

    v_new_auth_state := 'AUTHORISED';
    v_new_batch_status := 'AUTHORISED_FOR_PAYMENT';
  else
    v_became_authorised := false;
    v_new_auth_state := 'AWAITING';

    update public.pay_batches pb5
    set
      status = 'AWAITING_AUTHORISATION',
      execution_intent_json = v_execution_intent_json
    where pb5.id = v_req.pay_batch_id;

    v_new_batch_status := 'AWAITING_AUTHORISATION';
    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', false,
      'message_kind', case when upper(btrim(coalesce(v_execution_intent_json->>'execution_mode', 'STANDARD_BANK'))) in ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then 'PAYOUT_NOTICE_AND_REMITTANCE' else 'REMITTANCE' end,
      'trigger_status', 'AWAITING_AUTHORISATION',
      'dispatch_required', false,
      'error', null,
      'result', jsonb_build_object(
        'ok', true,
        'queued', false,
        'deferred', true,
        'dispatch_required', false,
        'trigger_status', 'AWAITING_AUTHORISATION',
        'configured_timing', v_remittance_send_timing
      )
    );
    v_remittance_queue_stage_result := v_worker_communications->'result';
  end if;

  perform public._imp_debug_audit(
    p_actor_user_id,
    'PAY_BATCH_AUTH_APPLY_ACTION_RESULT',
    jsonb_build_object(
      'auth_request_id', p_auth_request_id::text,
      'pay_batch_id', v_req.pay_batch_id::text,
      'action', v_action,
      'approved_count', v_approved_count,
      'became_authorised', v_became_authorised,
      'auth_state', v_new_auth_state,
      'batch_status', v_new_batch_status,
      'schedule_result', v_schedule_result,
      'worker_communications', v_worker_communications
    ),
    'pay_batch_auth_requests',
    p_auth_request_id::text,
    null::jsonb,
    null::text,
    null::text,
    null::text
  );

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_req.pay_batch_id::text,
    'status', (select pb6.status from public.pay_batches pb6 where pb6.id = v_req.pay_batch_id),
    'auth_request_id', p_auth_request_id::text,
    'auth_state', v_new_auth_state,
    'state', v_new_auth_state,
    'required_quantity', v_req.required_quantity,
    'approved_count', v_approved_count,
    'became_authorised', v_became_authorised,
    'operation_id', v_payment_operation_id,
    'schedule_revision', coalesce(
      nullif(v_schedule_result->>'schedule_revision', '')::bigint,
      (
        select coalesce(pb_revision.source_scope_change_generation, 0)
        from public.pay_batches as pb_revision
        where pb_revision.id = v_req.pay_batch_id
      )
    ),
    'active_scope_hash', v_active_scope_hash,
    'display_message', case
      when v_became_authorised then 'Payment authorised for the current active scope.'
      else 'Authorisation recorded. Further approval is required.'
    end,
    'payment_remittance_send_timing', v_remittance_send_timing,
    'execution_intent_json', v_execution_intent_json,
    'execution_mode', v_execution_intent_json->>'execution_mode',
    'suppress_remittances', lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on'),
    'schedule_result', v_schedule_result,
    'worker_communications', v_worker_communications,
    'remittance_queue_stage_result', v_remittance_queue_stage_result,
    'continuation', jsonb_build_object(
      'required', v_became_authorised AND v_payment_operation_id IS NOT NULL,
      'operation_id', v_payment_operation_id,
      'operation_type', 'PAYMENT_EXECUTE',
      'pay_batch_id', v_req.pay_batch_id,
      'root_operation_id', NULL,
      'phase', CASE WHEN v_became_authorised THEN 'VALIDATE_BATCH' ELSE NULL END,
      'run_after_utc', CASE WHEN v_became_authorised THEN clock_timestamp() ELSE NULL END,
      'reason', CASE WHEN v_became_authorised THEN 'PAYMENT_AUTHORISED' ELSE 'AWAITING_AUTHORISATION' END,
      'successor_relation', CASE WHEN v_became_authorised THEN 'SELF' ELSE 'NONE' END,
      'requires_user_action', NOT v_became_authorised,
      'terminal', false
    )
  );
exception
  when others then
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_AUTH_APPLY_ACTION_ERROR',
      jsonb_build_object(
        'auth_request_id', p_auth_request_id::text,
        'action', v_action,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_batch_auth_requests',
      coalesce(p_auth_request_id::text, 'NO_AUTH_REQUEST_ID'),
      null::jsonb,
      null::text,
      null::text,
      null::text
    );
    raise;
end;
$function$;

-- pay_batch_auth_invites_upsert(uuid,uuid,uuid[])
CREATE OR REPLACE FUNCTION public.pay_batch_auth_invites_upsert(p_auth_request_id uuid, p_actor_user_id uuid, p_target_user_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req record;
  v_now timestamptz := now();
  v_expires timestamptz := (now() + interval '7 days');

  v_target_count int := 0;
  v_inserted_count int := 0;
  v_tokens jsonb := '[]'::jsonb;
begin
  if p_auth_request_id is null then
    raise exception 'pay_batch_auth_invites_upsert: auth_request_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_batch_auth_invites_upsert: actor_user_id is required';
  end if;

  select
    pbar.id,
    pbar.pay_batch_id,
    pbar.state
  into v_req
  from public.pay_batch_auth_requests pbar
  where pbar.id = p_auth_request_id
  for update;

  if v_req.id is null then
    raise exception 'pay_batch_auth_invites_upsert: auth_request not found';
  end if;

  if v_req.state <> 'AWAITING' then
    raise exception 'pay_batch_auth_invites_upsert: auth_request must be AWAITING (current=%)', v_req.state;
  end if;

  with targets as (
    select
      tu.id as user_id
    from public.tms_users tu
    where tu.is_active = true
      and (coalesce(tu.payment_authoriser,false) = true or coalesce(tu.payment_golden_key,false) = true)
      and (
        p_target_user_ids is null
        or coalesce(array_length(p_target_user_ids,1),0) = 0
        or tu.id = any(p_target_user_ids)
      )
  )
  select count(*)::int
  into v_target_count
  from targets;

  if v_target_count = 0 then
    raise exception 'pay_batch_auth_invites_upsert: no eligible target users resolved';
  end if;

  with targets as (
    select
      tu.id as user_id
    from public.tms_users tu
    where tu.is_active = true
      and (coalesce(tu.payment_authoriser,false) = true or coalesce(tu.payment_golden_key,false) = true)
      and (
        p_target_user_ids is null
        or coalesce(array_length(p_target_user_ids,1),0) = 0
        or tu.id = any(p_target_user_ids)
      )
  )
  insert into public.pay_batch_auth_tokens(
    token,
    auth_request_id,
    target_user_id,
    expires_at_utc,
    used_at_utc,
    created_at_utc
  )
  select
    encode(gen_random_bytes(24), 'hex'),
    p_auth_request_id,
    t.user_id,
    v_expires,
    null,
    v_now
  from targets t
  on conflict on constraint ux_pay_batch_auth_tokens_one_per_target
  do nothing;

  get diagnostics v_inserted_count = row_count;

  with targets as (
    select
      tu.id as user_id
    from public.tms_users tu
    where tu.is_active = true
      and (coalesce(tu.payment_authoriser,false) = true or coalesce(tu.payment_golden_key,false) = true)
      and (
        p_target_user_ids is null
        or coalesce(array_length(p_target_user_ids,1),0) = 0
        or tu.id = any(p_target_user_ids)
      )
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'target_user_id', pbat.target_user_id::text,
        'token', pbat.token,
        'expires_at_utc', pbat.expires_at_utc,
        'used_at_utc', pbat.used_at_utc,
        'created_at_utc', pbat.created_at_utc
      )
      order by pbat.created_at_utc asc nulls last, pbat.token asc
    ),
    '[]'::jsonb
  )
  into v_tokens
  from public.pay_batch_auth_tokens pbat
  join targets t
    on t.user_id = pbat.target_user_id
  where pbat.auth_request_id = p_auth_request_id;

  return jsonb_build_object(
    'ok', true,
    'auth_request_id', p_auth_request_id::text,
    'pay_batch_id', v_req.pay_batch_id::text,
    'resolved_target_count', v_target_count,
    'inserted_count', v_inserted_count,
    'expires_at_utc', v_expires,
    'tokens', v_tokens
  );
end;
$function$;

-- pay_batch_auth_start(uuid,text,timestamp with time zone,text,jsonb,uuid,text,text,date,text,boolean,boolean,boolean,text,text,uuid,text,text)
CREATE OR REPLACE FUNCTION public.pay_batch_auth_start(p_pay_batch_id uuid, p_schedule_kind text, p_scheduled_at_utc timestamp with time zone, p_funding_account_ref text, p_warning_hours_json jsonb, p_actor_user_id uuid, p_actor_intent text DEFAULT NULL::text, p_execution_mode text DEFAULT 'STANDARD_BANK'::text, p_payment_date date DEFAULT NULL::date, p_pay_channel_scope text DEFAULT 'ALL'::text, p_suppress_remittances boolean DEFAULT false, p_suppress_remittances_confirmed boolean DEFAULT false, p_csv_uploaded_confirmed boolean DEFAULT false, p_csv_bank_confirm_ref text DEFAULT NULL::text, p_external_settlement_comment text DEFAULT NULL::text, p_operation_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_freshness_result_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_kind text := upper(btrim(coalesce(p_schedule_kind, '')));
  v_intent text := upper(btrim(coalesce(p_actor_intent, '')));
  v_execution_mode text := upper(btrim(coalesce(p_execution_mode, 'STANDARD_BANK')));
  v_pay_channel_scope text := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  v_actor_row record;
  v_batch_row public.pay_batches%ROWTYPE;
  v_cfg_row public.settings_defaults%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_prepare_json jsonb := '{}'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_existing_auth_id uuid := NULL::uuid;
  v_existing_auth_state text := NULL::text;
  v_existing_auth_intent_json jsonb := '{}'::jsonb;
  v_existing_auth_operation_id text := NULL::text;
  v_existing_auth_idempotency_key text := NULL::text;
  v_conflicting_auth_id uuid := NULL::uuid;
  v_conflicting_auth_state text := NULL::text;
  v_conflicting_auth_operation_id text := NULL::text;
  v_conflicting_auth_idempotency_key text := NULL::text;
  v_requested_idempotency_key text := NULL::text;
  v_effective_freshness_result_hash text := NULL::text;
  v_effective_freshness_scope_hash text := NULL::text;
  v_auth_id uuid := NULL::uuid;
  v_auth_state text := 'AWAITING';
  v_required_quantity integer := 1;
  v_use_golden_key boolean := false;
  v_payment_date date := p_payment_date;
  v_scheduled_at_utc timestamptz := NULL::timestamptz;
  v_funding_account_ref text := NULL::text;
  v_warning_hours_json jsonb := '[]'::jsonb;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_next_required_phase text := 'WAIT_FOR_AUTHORISATION';
  v_ready boolean := false;
  v_blocker_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_authorisation_ready_transfer_count integer := 0;
  v_local_only_transfer_count integer := 0;
  v_provider_attempt_or_evidence_transfer_count integer := 0;
  v_provider_or_ambiguous_evidence_transfer_count integer := 0;
  v_unsafe_transfer_count integer := 0;
  v_blocked_transfer_count integer := 0;
  v_canonical_pending_status_transfer_count integer := 0;
  v_scoped_operation_scope_count integer := 0;
  v_scoped_scope_prepared_count integer := 0;
  v_scoped_scope_failed_count integer := 0;
  v_scoped_scope_skipped_count integer := 0;
  v_scoped_scope_without_transfer_count integer := 0;
  v_non_cancellable_auth_request_count integer := 0;
  v_auth_request_retry_blocker_count integer := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_auth_start_path text := 'FULL_PREPARE_PATH';
  v_used_operation_scope_proof boolean := false;
  v_provider_submit_chunk_risk_count integer := 0;
  v_operation_provider_submit_marker_count integer := 0;
  v_transfer_amount_mismatch_count integer := 0;
  v_transfer_currency_mismatch_count integer := 0;
  v_transfer_status_not_pending_count integer := 0;
  v_transfer_external_state_count integer := 0;
  v_transfer_identity_mismatch_count integer := 0;
  v_scope_provider_not_ready_count integer := 0;
  v_scope_prepared_hash_missing_count integer := 0;
  v_scope_prepared_amount_mismatch_count integer := 0;
  v_scope_item_rollup_pending_count integer := 0;
  v_payout_instruction_missing_count integer := 0;
  v_scope_amount_total numeric(14,2) := 0;
  v_transfer_amount_total numeric(14,2) := 0;
  v_scope_item_amount_total numeric(14,2) := 0;
  v_batch_item_amount_total numeric(14,2) := 0;
  v_auth_freshness_json jsonb := '{}'::jsonb;
  v_auth_carry_forward_freshness_json jsonb := '{}'::jsonb;
  v_auth_carry_forward_blocker_count integer := 0;
  v_auth_freshness_blocker_reasons jsonb := '[]'::jsonb;
  v_global_paye_missing_count integer := 0;
  v_global_paye_zero_count integer := 0;
  v_global_paye_positive_count integer := 0;
  v_global_positive_bank_payment_count integer := 0;
  v_global_positive_bank_payment_total numeric(14,2) := 0;
  v_global_invalid_payment_row_count integer := 0;
  v_current_paye_net_state_hash text := NULL::text;
  v_all_bank_payment_projection_hash text := NULL::text;
  v_scoped_paye_missing_count integer := 0;
  v_scoped_explicit_zero_count integer := 0;
  v_scoped_paye_positive_count integer := 0;
  v_scoped_positive_bank_payment_count integer := 0;
  v_scoped_positive_bank_payment_total numeric(14,2) := 0;
  v_scoped_invalid_payment_row_count integer := 0;
  v_scoped_paye_net_state_hash text := NULL::text;
  v_current_bank_payment_projection_hash text := NULL::text;
  v_operation_no_bank_payment_marker boolean := false;
  v_operation_allow_explicit_zero_marker boolean := false;
  v_operation_scoped_no_transfer_marker boolean := false;
  v_operation_projection_scope text := NULL::text;
  v_operation_no_bank_proof_json jsonb := '{}'::jsonb;
  v_operation_proof_source text := NULL::text;
  v_operation_proof_operation_id uuid := NULL::uuid;
  v_operation_proof_pay_batch_id uuid := NULL::uuid;
  v_operation_expected_global_paye_net_state_hash text := NULL::text;
  v_operation_expected_global_bank_payment_projection_hash text := NULL::text;
  v_operation_expected_scoped_paye_net_state_hash text := NULL::text;
  v_operation_expected_scoped_bank_payment_projection_hash text := NULL::text;
  v_operation_expected_global_missing_count integer := NULL::integer;
  v_operation_expected_global_zero_count integer := NULL::integer;
  v_operation_expected_global_positive_count integer := NULL::integer;
  v_operation_expected_global_invalid_count integer := NULL::integer;
  v_operation_expected_scoped_missing_count integer := NULL::integer;
  v_operation_expected_scoped_zero_count integer := NULL::integer;
  v_operation_expected_scoped_positive_count integer := NULL::integer;
  v_operation_expected_scoped_invalid_count integer := NULL::integer;
  v_server_explicit_zero_scope_eligible boolean := false;
  v_server_scoped_no_transfer_eligible boolean := false;
  v_server_no_bank_payment_eligible boolean := false;
  v_allow_explicit_zero_no_bank_scopes_validated boolean := false;
  v_scoped_no_transfer_execution_validated boolean := false;
  v_no_bank_payment_validated boolean := false;
  v_seed_proof_validated boolean := false;
  v_server_projection_proof_json jsonb := '{}'::jsonb;
  v_no_bank_scope_artifact_count integer := 0;
  v_no_bank_batch_transfer_count integer := 0;
  v_no_bank_transfer_event_count integer := 0;
  v_no_bank_provider_attempt_count integer := 0;
  v_bank_csv_export_json jsonb := '{}'::jsonb;
  v_stored_csv_scope text := NULL::text;
  v_stored_csv_paye_net_state_hash text := NULL::text;
  v_stored_csv_bank_projection_hash text := NULL::text;
  v_stored_csv_row_count integer := NULL::integer;
  v_stored_csv_total numeric(14,2) := NULL::numeric;
  v_stored_csv_generated_at_utc text := NULL::text;
  v_stored_csv_generated_by_user_id text := NULL::text;
  v_stored_csv_filename text := NULL::text;
  v_stored_csv_zero_row boolean := false;
  v_csv_evidence_validated boolean := false;
  v_csv_evidence_json jsonb := NULL::jsonb;
  v_effective_csv_uploaded_confirmed boolean := false;
  v_effective_csv_bank_confirm_ref text := NULL::text;
  v_effective_external_settlement_comment text := NULL::text;
  v_prepare_blockers jsonb := '[]'::jsonb;
  v_prepare_unwaived_blockers jsonb := '[]'::jsonb;
  v_prepare_waived_blockers jsonb := '[]'::jsonb;
  v_supplied_execution_mode_raw text := upper(btrim(coalesce(p_execution_mode, 'STANDARD_BANK')));
  v_durable_execution_mode_raw text := NULL::text;
  v_durable_execution_mode text := NULL::text;
  v_durable_operation_idempotency_key text := NULL::text;
  v_manual_confirmation_mode text := NULL::text;
  v_prepare_execution_mode text := NULL::text;
  v_prepare_next_required_phase text := NULL::text;
  v_existing_auth_execution_mode text := NULL::text;
  v_existing_auth_compatible boolean := false;
  v_existing_auth_cross_operation boolean := false;
  v_existing_auth_cross_operation_authorised boolean := false;
  v_existing_auth_compatibility_json jsonb := '{}'::jsonb;
  v_auth_lookup_pass integer := 0;
  v_old_operation_row public.banking_pay_operations%ROWTYPE;
  v_old_operation_id uuid := NULL::uuid;
  v_old_operation_execution_mode_raw text := NULL::text;
  v_old_operation_execution_mode text := NULL::text;
  v_old_auth_execution_mode text := NULL::text;
  v_old_auth_scope text := NULL::text;
  v_old_operation_reset_terminal boolean := false;
  v_old_operation_manual_reset_marker boolean := false;
  v_stale_auth_request_cancelled boolean := false;
  v_stale_auth_cancelled_request_id uuid := NULL::uuid;
  v_stale_auth_cancelled_operation_id uuid := NULL::uuid;
  v_stale_auth_tokens_voided integer := 0;
  v_stale_auth_safety_json jsonb := '{}'::jsonb;
  v_stale_auth_failed_checks jsonb := '[]'::jsonb;
  v_stale_provider_attempt_count integer := 0;
  v_stale_transfer_event_count integer := 0;
  v_stale_scope_provider_evidence_count integer := 0;
  v_stale_transfer_provider_evidence_count integer := 0;
  v_stale_provider_chunk_evidence_count integer := 0;
  v_stale_settlement_scope_count integer := 0;
  v_stale_remittance_scope_count integer := 0;
  v_stale_correction_request_count integer := 0;
  v_stale_correction_item_count integer := 0;
  v_stale_carry_forward_count integer := 0;
  v_stale_advance_patch_count integer := 0;
  v_stale_advance_reservation_count integer := 0;
  v_stale_advance_payout_count integer := 0;
  v_stale_other_active_operation_count integer := 0;
  v_stale_remaining_active_auth_count integer := 0;
  v_expected_manual_confirmation_mode text := NULL::text;
  v_existing_auth_schedule_kind text := NULL::text;
  v_existing_auth_scheduled_at_utc timestamptz := NULL::timestamptz;
  v_existing_auth_funding_account_ref text := NULL::text;
  v_existing_auth_warning_hours_json jsonb := NULL::jsonb;
  v_conflicting_auth_intent_json jsonb := '{}'::jsonb;
  v_existing_auth_identity_matches boolean := false;
  v_existing_auth_mode_specific_proof_matches boolean := false;
  v_old_operation_found boolean := false;
  v_old_operation_scope_compatible boolean := false;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_current_active_scope_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('OPERATION_ADVANCE');
  PERFORM set_config('lock_timeout', '1s', true);

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user_id is required';
  END IF;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    p_pay_batch_id,
    NULL::uuid,
    'NEW_PAYMENT_ACTION'
  );

  IF COALESCE((v_mutation_guard->>'blocked')::boolean, true) THEN
    RAISE EXCEPTION 'PAYMENT_CHANGE_IN_PROGRESS'
      USING ERRCODE = 'P0001', DETAIL = JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', COALESCE(
          v_mutation_guard->>'code',
          'PAYMENT_CHANGE_IN_PROGRESS'
        ),
        'message', COALESCE(
          v_mutation_guard->>'message',
          'A payment change is in progress.'
        ),
        'pay_batch_id', p_pay_batch_id
      )::text;
  END IF;

  IF v_kind NOT IN ('IMMEDIATE', 'SCHEDULED') THEN
    RAISE EXCEPTION 'pay_batch_auth_start: invalid schedule_kind (IMMEDIATE|SCHEDULED)';
  END IF;

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    RAISE EXCEPTION 'pay_batch_auth_start: invalid pay_channel_scope';
  END IF;

  IF v_execution_mode NOT IN ('STANDARD_BANK', 'BANK', 'CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN
    RAISE EXCEPTION 'pay_batch_auth_start: invalid execution_mode';
  END IF;

  v_execution_mode := CASE
    WHEN v_execution_mode IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN v_execution_mode IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN v_execution_mode IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE v_execution_mode
  END;

  v_requested_idempotency_key := nullif(btrim(coalesce(p_idempotency_key, '')), '');

  SELECT actor_user.id,
         actor_user.is_active,
         actor_user.payment_authoriser,
         actor_user.payment_golden_key
  INTO v_actor_row
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF v_actor_row.id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user not found';
  END IF;

  IF coalesce(v_actor_row.is_active, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user is not active';
  END IF;

  IF coalesce(v_actor_row.payment_authoriser, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user must be a payment authoriser';
  END IF;

  v_use_golden_key := v_intent = 'USE_GOLDEN_KEY';
  IF v_use_golden_key AND coalesce(v_actor_row.payment_golden_key, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user does not have payment golden key';
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_auth_start: pay_batch not found';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'The payment execution operation was not found.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_TYPE_NOT_SUPPORTED_FOR_AUTH_START',
        'message', 'Payment authorisation must be bound to a payment execution operation.',
        'operation_id', p_operation_id::text,
        'operation_type', v_operation_row.operation_type,
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'The payment execution operation is not bound to the requested pay batch.',
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL::text ELSE v_operation_row.pay_batch_id::text END,
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_ACTOR_MISMATCH',
        'message', 'The payment execution operation belongs to another actor.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_durable_execution_mode_raw := UPPER(BTRIM(COALESCE(v_operation_row.input_json->>'execution_mode', '')));
    v_durable_execution_mode := CASE
      WHEN v_durable_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN v_durable_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN v_durable_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE NULL::text
    END;

    IF v_durable_execution_mode IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_EXECUTION_MODE_INVALID',
        'message', 'The durable payment execution mode is missing or unsupported.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'durable_execution_mode_raw', NULLIF(v_durable_execution_mode_raw, ''),
        'supported_execution_modes', JSONB_BUILD_ARRAY('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_execution_mode IS DISTINCT FROM v_durable_execution_mode THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_EXECUTION_MODE_MISMATCH',
        'message', 'The requested authorisation mode does not match the durable payment execution mode.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'requested_execution_mode_raw', NULLIF(v_supplied_execution_mode_raw, ''),
        'requested_execution_mode', v_execution_mode,
        'durable_execution_mode_raw', NULLIF(v_durable_execution_mode_raw, ''),
        'durable_execution_mode', v_durable_execution_mode
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_execution_mode := v_durable_execution_mode;
    v_durable_operation_idempotency_key := NULLIF(BTRIM(COALESCE(v_operation_row.idempotency_key, '')), '');
    IF v_requested_idempotency_key IS NOT NULL
       AND v_durable_operation_idempotency_key IS NOT NULL
       AND v_requested_idempotency_key IS DISTINCT FROM v_durable_operation_idempotency_key THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_IDEMPOTENCY_KEY_MISMATCH',
        'message', 'The supplied authorisation idempotency key does not match the durable payment execution operation.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'supplied_idempotency_key_present', true,
        'durable_idempotency_key_present', true
      )::text USING ERRCODE = 'P0001';
    END IF;
    v_requested_idempotency_key := COALESCE(v_requested_idempotency_key, v_durable_operation_idempotency_key);
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_auth_projection_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_auth_projection_rows
  ON COMMIT DROP
  AS
  SELECT projection_row.*
  FROM public._pay_batch_bank_payment_projection_rows(
    p_pay_batch_id,
    'ALL'
  ) AS projection_row;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_auth_scoped_projection_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_auth_scoped_projection_rows
  ON COMMIT DROP
  AS
  SELECT projection_row.*
  FROM public._pay_batch_bank_payment_projection_rows(
    p_pay_batch_id,
    v_pay_channel_scope
  ) AS projection_row;

  SELECT
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'MISSING'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'ZERO'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'POSITIVE'
    )::integer,
    COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
    ROUND(
      COALESCE(
        SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
        0
      ),
      2
    )::numeric(14,2),
    COUNT(*) FILTER (
      WHERE (
        projection_row.paye_net_required IS TRUE
        AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
      )
      OR (
        COALESCE(projection_row.paye_net_required, false) IS FALSE
        AND (
          projection_row.final_frozen_bank_amount IS NULL
          OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
        )
      )
    )::integer,
    MAX(projection_row.paye_net_state_hash),
    MAX(projection_row.bank_payment_projection_hash)
  INTO
    v_global_paye_missing_count,
    v_global_paye_zero_count,
    v_global_paye_positive_count,
    v_global_positive_bank_payment_count,
    v_global_positive_bank_payment_total,
    v_global_invalid_payment_row_count,
    v_current_paye_net_state_hash,
    v_all_bank_payment_projection_hash
  FROM pg_temp.tmp_pay_batch_auth_projection_rows AS projection_row;

  SELECT
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'MISSING'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'ZERO'
    )::integer,
    COUNT(*) FILTER (
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.paye_net_classification = 'POSITIVE'
    )::integer,
    COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
    ROUND(
      COALESCE(
        SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
        0
      ),
      2
    )::numeric(14,2),
    COUNT(*) FILTER (
      WHERE (
        projection_row.paye_net_required IS TRUE
        AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
      )
      OR (
        COALESCE(projection_row.paye_net_required, false) IS FALSE
        AND (
          projection_row.final_frozen_bank_amount IS NULL
          OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
        )
      )
    )::integer,
    MAX(projection_row.paye_net_state_hash),
    MAX(projection_row.bank_payment_projection_hash)
  INTO
    v_scoped_paye_missing_count,
    v_scoped_explicit_zero_count,
    v_scoped_paye_positive_count,
    v_scoped_positive_bank_payment_count,
    v_scoped_positive_bank_payment_total,
    v_scoped_invalid_payment_row_count,
    v_scoped_paye_net_state_hash,
    v_current_bank_payment_projection_hash
  FROM pg_temp.tmp_pay_batch_auth_scoped_projection_rows AS projection_row;

  v_global_paye_missing_count := COALESCE(v_global_paye_missing_count, 0);
  v_global_paye_zero_count := COALESCE(v_global_paye_zero_count, 0);
  v_global_paye_positive_count := COALESCE(v_global_paye_positive_count, 0);
  v_global_positive_bank_payment_count := COALESCE(v_global_positive_bank_payment_count, 0);
  v_global_positive_bank_payment_total := ROUND(COALESCE(v_global_positive_bank_payment_total, 0), 2);
  v_global_invalid_payment_row_count := COALESCE(v_global_invalid_payment_row_count, 0);
  v_current_paye_net_state_hash := COALESCE(
    v_current_paye_net_state_hash,
    MD5(JSONB_BUILD_OBJECT(
      'pay_batch_id', p_pay_batch_id::text,
      'scope', 'ALL',
      'rows', '[]'::jsonb
    )::text)
  );
  v_all_bank_payment_projection_hash := COALESCE(
    v_all_bank_payment_projection_hash,
    MD5(JSONB_BUILD_OBJECT(
      'pay_batch_id', p_pay_batch_id::text,
      'scope', 'ALL',
      'rows', '[]'::jsonb
    )::text)
  );

  v_scoped_paye_missing_count := COALESCE(v_scoped_paye_missing_count, 0);
  v_scoped_explicit_zero_count := COALESCE(v_scoped_explicit_zero_count, 0);
  v_scoped_paye_positive_count := COALESCE(v_scoped_paye_positive_count, 0);
  v_scoped_positive_bank_payment_count := COALESCE(v_scoped_positive_bank_payment_count, 0);
  v_scoped_positive_bank_payment_total := ROUND(COALESCE(v_scoped_positive_bank_payment_total, 0), 2);
  v_scoped_invalid_payment_row_count := COALESCE(v_scoped_invalid_payment_row_count, 0);
  v_scoped_paye_net_state_hash := COALESCE(
    v_scoped_paye_net_state_hash,
    MD5(JSONB_BUILD_OBJECT(
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_pay_channel_scope,
      'rows', '[]'::jsonb
    )::text)
  );
  v_current_bank_payment_projection_hash := COALESCE(
    v_current_bank_payment_projection_hash,
    MD5(JSONB_BUILD_OBJECT(
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_pay_channel_scope,
      'rows', '[]'::jsonb
    )::text)
  );

  IF v_global_paye_missing_count > 0 THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'PAYE_NET_REQUIRED_FOR_EXECUTION',
      'message', 'Every required PAYE net amount must be explicitly entered or imported before payment authorisation can start.',
      'pay_batch_id', p_pay_batch_id::text,
      'pay_channel_scope', v_pay_channel_scope,
      'missing_explicit_paye_input_count', v_global_paye_missing_count
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_server_explicit_zero_scope_eligible := (
    v_global_paye_missing_count = 0
    AND v_scoped_explicit_zero_count > 0
    AND v_scoped_invalid_payment_row_count = 0
  );
  v_server_scoped_no_transfer_eligible := (
    v_server_explicit_zero_scope_eligible
    AND v_scoped_positive_bank_payment_count = 0
  );
  v_server_no_bank_payment_eligible := (
    v_server_scoped_no_transfer_eligible
    AND v_global_positive_bank_payment_count = 0
    AND v_global_invalid_payment_row_count = 0
  );

  IF p_operation_id IS NOT NULL THEN
    v_operation_no_bank_proof_json := CASE
      WHEN JSONB_TYPEOF(v_operation_row.progress_json->'no_bank_payment_proof') = 'object'
        THEN COALESCE(v_operation_row.progress_json->'no_bank_payment_proof', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    v_operation_proof_source := UPPER(NULLIF(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'proof_source',
      v_operation_row.progress_json->>'proof_source',
      ''
    )), ''));

    IF NULLIF(BTRIM(COALESCE(v_operation_no_bank_proof_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_operation_proof_operation_id := (v_operation_no_bank_proof_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_operation_no_bank_proof_json->>'pay_batch_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_operation_proof_pay_batch_id := (v_operation_no_bank_proof_json->>'pay_batch_id')::uuid;
    END IF;

    v_operation_no_bank_payment_marker := LOWER(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'no_bank_payment_execution',
      v_operation_row.progress_json->>'no_bank_payment_execution',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_operation_allow_explicit_zero_marker := LOWER(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'allow_explicit_zero_no_bank_scopes',
      v_operation_row.progress_json->>'allow_explicit_zero_no_bank_scopes',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_operation_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'scoped_no_transfer_execution',
      v_operation_row.progress_json->>'scoped_no_transfer_execution',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');

    v_operation_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'pay_channel_scope',
      v_operation_row.progress_json->>'pay_channel_scope',
      v_operation_row.progress_json->>'scope',
      ''
    )), ''));
    v_operation_expected_global_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'global_paye_net_state_hash',
      v_operation_no_bank_proof_json->>'paye_net_state_hash',
      ''
    )), '');
    v_operation_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'global_bank_payment_projection_hash',
      ''
    )), '');
    v_operation_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'scoped_paye_net_state_hash',
      ''
    )), '');
    v_operation_expected_scoped_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_no_bank_proof_json->>'scoped_bank_payment_projection_hash',
      v_operation_no_bank_proof_json->>'bank_payment_projection_hash',
      ''
    )), '');

    IF COALESCE(v_operation_no_bank_proof_json->>'global_missing_explicit_paye_input_count', v_operation_no_bank_proof_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_global_missing_count := COALESCE(v_operation_no_bank_proof_json->>'global_missing_explicit_paye_input_count', v_operation_no_bank_proof_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'global_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_global_zero_count := (v_operation_no_bank_proof_json->>'global_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_global_positive_count := (v_operation_no_bank_proof_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_global_invalid_count := (v_operation_no_bank_proof_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_scoped_missing_count := (v_operation_no_bank_proof_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_scoped_zero_count := (v_operation_no_bank_proof_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'scoped_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_scoped_positive_count := (v_operation_no_bank_proof_json->>'scoped_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_no_bank_proof_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_operation_expected_scoped_invalid_count := (v_operation_no_bank_proof_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;
  END IF;

  IF v_scoped_explicit_zero_count > 0 THEN
    v_seed_proof_validated := (
      p_operation_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
      AND v_operation_proof_source = 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_SEED'
      AND v_operation_proof_operation_id = p_operation_id
      AND v_operation_proof_pay_batch_id = p_pay_batch_id
      AND v_operation_projection_scope IS NOT DISTINCT FROM v_pay_channel_scope
      AND v_operation_allow_explicit_zero_marker IS TRUE
      AND v_operation_scoped_no_transfer_marker IS NOT DISTINCT FROM v_server_scoped_no_transfer_eligible
      AND v_operation_no_bank_payment_marker IS NOT DISTINCT FROM v_server_no_bank_payment_eligible
      AND v_operation_expected_global_paye_net_state_hash IS NOT DISTINCT FROM v_current_paye_net_state_hash
      AND v_operation_expected_global_bank_payment_projection_hash IS NOT DISTINCT FROM v_all_bank_payment_projection_hash
      AND v_operation_expected_scoped_paye_net_state_hash IS NOT DISTINCT FROM v_scoped_paye_net_state_hash
      AND v_operation_expected_scoped_bank_payment_projection_hash IS NOT DISTINCT FROM v_current_bank_payment_projection_hash
      AND v_operation_expected_global_missing_count IS NOT DISTINCT FROM v_global_paye_missing_count
      AND v_operation_expected_global_zero_count IS NOT DISTINCT FROM v_global_paye_zero_count
      AND v_operation_expected_global_positive_count IS NOT DISTINCT FROM v_global_positive_bank_payment_count
      AND v_operation_expected_global_invalid_count IS NOT DISTINCT FROM v_global_invalid_payment_row_count
      AND v_operation_expected_scoped_missing_count IS NOT DISTINCT FROM v_scoped_paye_missing_count
      AND v_operation_expected_scoped_zero_count IS NOT DISTINCT FROM v_scoped_explicit_zero_count
      AND v_operation_expected_scoped_positive_count IS NOT DISTINCT FROM v_scoped_positive_bank_payment_count
      AND v_operation_expected_scoped_invalid_count IS NOT DISTINCT FROM v_scoped_invalid_payment_row_count
    );

    IF v_seed_proof_validated IS NOT TRUE THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'EXPLICIT_ZERO_SEED_PROOF_REQUIRED',
        'message', 'Explicit-zero PAYE authorisation requires a matching server-owned transfer-scope seed proof.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'pay_channel_scope', v_pay_channel_scope,
        'operation_projection_scope', v_operation_projection_scope,
        'seed_proof_source', v_operation_proof_source,
        'scoped_no_transfer_execution', v_server_scoped_no_transfer_eligible,
        'no_bank_payment_execution', v_server_no_bank_payment_eligible,
        'global_invalid_payment_row_count', v_global_invalid_payment_row_count,
        'scoped_invalid_payment_row_count', v_scoped_invalid_payment_row_count
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_allow_explicit_zero_no_bank_scopes_validated := true;
    v_scoped_no_transfer_execution_validated := v_server_scoped_no_transfer_eligible;
    v_no_bank_payment_validated := v_server_no_bank_payment_eligible;
  ELSE
    IF v_operation_allow_explicit_zero_marker
       OR v_operation_scoped_no_transfer_marker
       OR v_operation_no_bank_payment_marker THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'ZERO_SCOPE_SEED_PROOF_INVALID',
        'message', 'The stored explicit-zero/no-bank seed markers do not match the current frozen payment projection.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'pay_channel_scope', v_pay_channel_scope
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_scoped_no_transfer_execution_validated THEN
    SELECT COUNT(*)::integer
    INTO v_no_bank_scope_artifact_count
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
    WHERE transfer_scope_row.operation_id = p_operation_id
      AND transfer_scope_row.pay_batch_id = p_pay_batch_id
      AND (
        v_pay_channel_scope = 'ALL'
        OR UPPER(BTRIM(COALESCE(transfer_scope_row.pay_channel, ''))) = v_pay_channel_scope
        OR (
          v_pay_channel_scope = 'LOANS'
          AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
          AND UPPER(BTRIM(COALESCE(transfer_scope_row.pay_channel, ''))) = 'PAYE'
        )
      );

    SELECT COUNT(*)::integer
    INTO v_no_bank_batch_transfer_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (
        v_pay_channel_scope = 'ALL'
        OR UPPER(BTRIM(COALESCE(transfer_row.pay_channel, ''))) = v_pay_channel_scope
        OR (
          v_pay_channel_scope = 'LOANS'
          AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
          AND UPPER(BTRIM(COALESCE(transfer_row.pay_channel, ''))) = 'PAYE'
        )
      );

    SELECT COUNT(*)::integer
    INTO v_no_bank_transfer_event_count
    FROM public.pay_bank_transfer_events AS transfer_event_row
    LEFT JOIN public.pay_bank_transfers AS event_transfer_row
      ON event_transfer_row.id = transfer_event_row.pay_bank_transfer_id
    WHERE transfer_event_row.pay_batch_id = p_pay_batch_id
      AND (
        v_pay_channel_scope = 'ALL'
        OR UPPER(BTRIM(COALESCE(event_transfer_row.pay_channel, ''))) = v_pay_channel_scope
        OR (
          v_pay_channel_scope = 'LOANS'
          AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
          AND UPPER(BTRIM(COALESCE(event_transfer_row.pay_channel, ''))) = 'PAYE'
        )
        OR transfer_event_row.pay_bank_transfer_id IS NULL
      );

    SELECT COUNT(*)::integer
    INTO v_no_bank_provider_attempt_count
    FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
    WHERE provider_attempt_row.operation_id = p_operation_id;

    IF COALESCE(v_no_bank_scope_artifact_count, 0) <> 0
       OR COALESCE(v_no_bank_batch_transfer_count, 0) <> 0
       OR COALESCE(v_no_bank_transfer_event_count, 0) <> 0
       OR COALESCE(v_no_bank_provider_attempt_count, 0) <> 0 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'NO_TRANSFER_EXECUTION_EVIDENCE_CONFLICT',
        'message', 'No-transfer authorisation cannot continue because transfer or provider-submission evidence already exists in the requested execution scope.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_pay_channel_scope,
        'transfer_scope_count', COALESCE(v_no_bank_scope_artifact_count, 0),
        'bank_transfer_count', COALESCE(v_no_bank_batch_transfer_count, 0),
        'bank_transfer_event_count', COALESCE(v_no_bank_transfer_event_count, 0),
        'provider_attempt_count', COALESCE(v_no_bank_provider_attempt_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_bank_csv_export_json := CASE
    WHEN JSONB_TYPEOF(v_batch_row.bank_csv_export_json) = 'object'
      THEN COALESCE(v_batch_row.bank_csv_export_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_stored_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'scope',
    v_bank_csv_export_json->>'pay_channel_scope',
    v_bank_csv_export_json->>'payChannelScope',
    ''
  )), ''));
  v_stored_csv_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'paye_net_state_hash',
    v_bank_csv_export_json->>'current_paye_net_state_hash',
    v_bank_csv_export_json->>'payeNetStateHash',
    ''
  )), '');
  v_stored_csv_bank_projection_hash := NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'bank_payment_projection_hash',
    v_bank_csv_export_json->>'current_bank_payment_projection_hash',
    v_bank_csv_export_json->>'bankPaymentProjectionHash',
    ''
  )), '');
  IF COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount', '') ~ '^[0-9]+$' THEN
    v_stored_csv_row_count := COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount')::integer;
  END IF;
  IF COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount', v_bank_csv_export_json->>'total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_stored_csv_total := ROUND(COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount', v_bank_csv_export_json->>'total')::numeric, 2)::numeric(14,2);
  END IF;
  v_stored_csv_generated_at_utc := NULLIF(BTRIM(COALESCE(v_bank_csv_export_json->>'generated_at_utc', v_bank_csv_export_json->>'generatedAtUtc', '')), '');
  v_stored_csv_generated_by_user_id := NULLIF(BTRIM(COALESCE(v_bank_csv_export_json->>'generated_by_user_id', v_bank_csv_export_json->>'generatedByUserId', '')), '');
  v_stored_csv_filename := NULLIF(BTRIM(COALESCE(v_bank_csv_export_json->>'filename', '')), '');
  v_stored_csv_zero_row := COALESCE(v_stored_csv_row_count, -1) = 0;

  v_server_projection_proof_json := JSONB_BUILD_OBJECT(
    'server_owned_payment_projection_proof', true,
    'payment_projection_proof_source', 'PAY_BATCH_AUTH_START',
    'payment_projection_proof_generated_at_utc', v_now::text,
    'pay_batch_id', p_pay_batch_id::text,
    'pay_channel_scope', v_pay_channel_scope,
    'scoped_no_transfer_execution', v_scoped_no_transfer_execution_validated,
    'no_bank_payment_execution', v_no_bank_payment_validated,
    'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_validated,
    'paye_net_state_hash', v_current_paye_net_state_hash,
    'global_paye_net_state_hash', v_current_paye_net_state_hash,
    'global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'bank_payment_projection_hash', v_current_bank_payment_projection_hash,
    'scoped_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
    'missing_explicit_paye_input_count', v_global_paye_missing_count,
    'global_missing_explicit_paye_input_count', v_global_paye_missing_count,
    'explicit_zero_count', v_global_paye_zero_count,
    'global_explicit_zero_count', v_global_paye_zero_count,
    'global_paye_positive_count', v_global_paye_positive_count,
    'global_positive_bank_payment_count', v_global_positive_bank_payment_count,
    'global_positive_bank_payment_total', v_global_positive_bank_payment_total,
    'global_invalid_payment_row_count', v_global_invalid_payment_row_count,
    'current_global_paye_net_state_hash', v_current_paye_net_state_hash,
    'current_global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'scoped_missing_explicit_paye_input_count', v_scoped_paye_missing_count,
    'scoped_explicit_zero_count', v_scoped_explicit_zero_count,
    'scoped_paye_positive_count', v_scoped_paye_positive_count,
    'positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'scoped_positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'positive_bank_payment_total', v_scoped_positive_bank_payment_total,
    'scoped_positive_bank_payment_total', v_scoped_positive_bank_payment_total,
    'scoped_invalid_payment_row_count', v_scoped_invalid_payment_row_count,
    'current_scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'current_scoped_bank_payment_projection_hash', v_current_bank_payment_projection_hash
  );

  v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  IF v_execution_commit_state <> 'NOT_SUBMITTED' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'This payment batch has already crossed the execution submission boundary and cannot be authorised again.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state
    )::text;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'This payment batch has provider submission or execution commit evidence and cannot be authorised again.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
      'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT settings_default.*
  INTO v_cfg_row
  FROM public.settings_defaults AS settings_default
  WHERE settings_default.id = 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_auth_start: settings_defaults missing (id=1)';
  END IF;

  v_required_quantity := GREATEST(1, coalesce(v_cfg_row.payment_authoriser_quantity, 1));
  v_warning_hours_json := CASE WHEN p_warning_hours_json IS NOT NULL THEN p_warning_hours_json ELSE coalesce(v_cfg_row.funds_warning_hours_json, '[]'::jsonb) END;

  IF v_warning_hours_json IS NOT NULL AND jsonb_typeof(v_warning_hours_json) <> 'array' THEN
    RAISE EXCEPTION 'pay_batch_auth_start: warning_hours_json must be a JSON array';
  END IF;

  v_payment_date := coalesce(v_payment_date, v_batch_row.authoritative_payment_date, v_batch_row.pay_date);
  IF v_payment_date IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: payment_date is required';
  END IF;
  IF v_payment_date < (v_now AT TIME ZONE 'Europe/London')::date THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'PAYMENT_DATE_IN_PAST',
      'message', 'The payment date must be today or in the future.',
      'payment_date', v_payment_date,
      'minimum_payment_date', (v_now AT TIME ZONE 'Europe/London')::date
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_kind = 'SCHEDULED' THEN
    IF p_scheduled_at_utc IS NULL THEN
      RAISE EXCEPTION 'pay_batch_auth_start: scheduled_at_utc is required when schedule_kind=SCHEDULED';
    END IF;
    v_scheduled_at_utc := p_scheduled_at_utc;
    IF (v_scheduled_at_utc AT TIME ZONE 'Europe/London')::date < (v_now AT TIME ZONE 'Europe/London')::date THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'SCHEDULE_DATE_IN_PAST',
        'message', 'The scheduled payment date must be today or in the future.',
        'scheduled_at_utc', v_scheduled_at_utc,
        'minimum_payment_date', (v_now AT TIME ZONE 'Europe/London')::date
      )::text USING ERRCODE = 'P0001';
    END IF;
  ELSE
    v_scheduled_at_utc := v_now;
  END IF;

  v_funding_account_ref := nullif(btrim(coalesce(p_funding_account_ref, '')), '');
  v_funding_account_ref := coalesce(v_funding_account_ref, nullif(btrim(coalesce(v_batch_row.funding_account_ref, '')), ''), nullif(btrim(coalesce(v_cfg_row.rail_default_funding_account_ref, '')), ''));

  IF v_funding_account_ref IS NULL THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'FUNDING_ACCOUNT_REF_REQUIRED',
      'message', 'A funding account reference is required by the installed authorisation request contract.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
      'execution_mode', v_execution_mode
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF coalesce(p_suppress_remittances, false) AND coalesce(p_suppress_remittances_confirmed, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: suppress_remittances requires explicit user confirmation';
  END IF;

  v_effective_csv_uploaded_confirmed := COALESCE(p_csv_uploaded_confirmed, false);
  v_effective_csv_bank_confirm_ref := NULLIF(BTRIM(COALESCE(p_csv_bank_confirm_ref, '')), '');
  v_effective_external_settlement_comment := NULLIF(BTRIM(COALESCE(p_external_settlement_comment, '')), '');
  v_expected_manual_confirmation_mode := CASE
    WHEN v_execution_mode = 'CSV_SETTLEMENT' AND v_scoped_positive_bank_payment_count > 0 THEN 'BANK_UPLOAD_CONFIRMED'
    WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN 'ZERO_ROW_REVIEW_NO_BANK_PAYMENT'
    WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' AND v_scoped_positive_bank_payment_count > 0 THEN 'EXTERNAL_SETTLEMENT_CONFIRMED'
    WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN 'NO_BANK_PAYMENT_CONFIRMED'
    ELSE NULL::text
  END;
  v_manual_confirmation_mode := CASE
    WHEN p_operation_id IS NOT NULL THEN
      UPPER(NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'manual_confirmation_mode', '')), ''))
    ELSE
      UPPER(NULLIF(BTRIM(COALESCE(
        v_batch_row.execution_intent_json->>'manual_confirmation_mode',
        v_expected_manual_confirmation_mode,
        ''
      )), ''))
  END;

  IF v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
     AND v_manual_confirmation_mode IS DISTINCT FROM v_expected_manual_confirmation_mode THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'MANUAL_CONFIRMATION_MODE_MISMATCH',
      'message', 'The local/manual settlement confirmation mode does not match the durable execution route and frozen projection.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
      'execution_mode', v_execution_mode,
      'expected_manual_confirmation_mode', v_expected_manual_confirmation_mode,
      'actual_manual_confirmation_mode', v_manual_confirmation_mode,
      'scoped_positive_bank_payment_count', v_scoped_positive_bank_payment_count,
      'scoped_explicit_zero_count', v_scoped_explicit_zero_count
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    IF UPPER(BTRIM(COALESCE(
         NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'pay_channel_scope', '')), ''),
         NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'payChannelScope', '')), ''),
         'ALL'
       ))) IS DISTINCT FROM v_pay_channel_scope THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_SCOPE_MISMATCH',
        'message', 'The requested authorisation scope does not match the durable payment execution scope.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'requested_scope', v_pay_channel_scope,
        'durable_scope', UPPER(BTRIM(COALESCE(v_operation_row.input_json->>'pay_channel_scope', v_operation_row.input_json->>'payChannelScope', 'ALL')))
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'payment_date', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'payment_date', '')), '') IS DISTINCT FROM v_payment_date::text THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_PAYMENT_DATE_MISMATCH',
        'message', 'The requested accounting payment date does not match the durable payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'requested_payment_date', v_payment_date::text,
        'durable_payment_date', v_operation_row.input_json->>'payment_date'
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'schedule_kind', '')), '') IS NOT NULL
       AND UPPER(BTRIM(COALESCE(v_operation_row.input_json->>'schedule_kind', ''))) IS DISTINCT FROM v_kind THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_SCHEDULE_KIND_MISMATCH',
        'message', 'The requested schedule kind does not match the durable payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'requested_schedule_kind', v_kind,
        'durable_schedule_kind', v_operation_row.input_json->>'schedule_kind'
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'funding_account_ref', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'funding_account_ref', '')), '') IS DISTINCT FROM v_funding_account_ref THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_FUNDING_ACCOUNT_MISMATCH',
        'message', 'The requested funding account does not match the durable payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'actor_intent', '')), '') IS NOT NULL
       AND UPPER(BTRIM(COALESCE(v_operation_row.input_json->>'actor_intent', ''))) IS DISTINCT FROM NULLIF(v_intent, '') THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_ACTOR_INTENT_MISMATCH',
        'message', 'The requested authorisation intent does not match the durable payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_execution_mode = 'CSV_SETTLEMENT'
       AND (
         LOWER(BTRIM(COALESCE(v_operation_row.input_json->>'csv_uploaded_confirmed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR v_effective_csv_uploaded_confirmed IS NOT TRUE
         OR NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'csv_bank_confirm_ref', '')), '') IS DISTINCT FROM v_effective_csv_bank_confirm_ref
       ) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_CSV_CONFIRMATION_MISMATCH',
        'message', 'The supplied CSV confirmation evidence does not match the durable payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'durable_csv_uploaded_confirmed', v_operation_row.input_json->'csv_uploaded_confirmed',
        'supplied_csv_uploaded_confirmed', v_effective_csv_uploaded_confirmed,
        'durable_csv_bank_confirm_ref', v_operation_row.input_json->>'csv_bank_confirm_ref',
        'supplied_csv_bank_confirm_ref', v_effective_csv_bank_confirm_ref
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_execution_mode = 'EXTERNAL_SETTLEMENT'
       AND NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'external_settlement_comment', '')), '') IS DISTINCT FROM v_effective_external_settlement_comment THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_EXTERNAL_CONFIRMATION_MISMATCH',
        'message', 'The supplied external settlement evidence does not match the durable payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'durable_external_comment_present', NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'external_settlement_comment', '')), '') IS NOT NULL,
        'supplied_external_comment_present', v_effective_external_settlement_comment IS NOT NULL
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_execution_mode = 'CSV_SETTLEMENT' THEN
    IF v_stored_csv_scope IS DISTINCT FROM v_pay_channel_scope
       OR v_stored_csv_paye_net_state_hash IS DISTINCT FROM v_scoped_paye_net_state_hash
       OR v_stored_csv_bank_projection_hash IS DISTINCT FROM v_current_bank_payment_projection_hash
       OR v_stored_csv_row_count IS NULL
       OR v_stored_csv_row_count <> v_scoped_positive_bank_payment_count
       OR v_stored_csv_total IS NULL
       OR ROUND(v_stored_csv_total, 2) <> ROUND(v_scoped_positive_bank_payment_total, 2)
       OR v_scoped_invalid_payment_row_count <> 0 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'CSV_REGENERATION_REQUIRED',
        'message', 'The generated Bank CSV is missing, stale, or does not match the exact authorised payment scope.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'requested_scope', v_pay_channel_scope,
        'stored_scope', v_stored_csv_scope,
        'stored_paye_net_state_hash', v_stored_csv_paye_net_state_hash,
        'current_paye_net_state_hash', v_scoped_paye_net_state_hash,
        'stored_bank_payment_projection_hash', v_stored_csv_bank_projection_hash,
        'current_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
        'stored_row_count', v_stored_csv_row_count,
        'current_row_count', v_scoped_positive_bank_payment_count,
        'stored_total_amount', v_stored_csv_total,
        'current_total_amount', v_scoped_positive_bank_payment_total,
        'invalid_payment_row_count', v_scoped_invalid_payment_row_count
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_effective_csv_uploaded_confirmed IS NOT TRUE THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'CSV_UPLOAD_CONFIRMATION_REQUIRED',
        'message', CASE
          WHEN v_scoped_no_transfer_execution_validated
            THEN 'Confirm that the current zero-row Bank CSV was reviewed and that no bank upload or payment is required.'
          ELSE 'Confirm that the current CloudTMS Bank CSV was uploaded or processed with the bank.'
        END,
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'pay_channel_scope', v_pay_channel_scope
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_scoped_positive_bank_payment_count > 0
       AND v_effective_csv_bank_confirm_ref IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'CSV_BANK_CONFIRM_REF_REQUIRED',
        'message', 'Positive CSV settlement requires a bank confirmation reference before authorisation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'pay_channel_scope', v_pay_channel_scope
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_scoped_no_transfer_execution_validated THEN
      v_effective_csv_bank_confirm_ref := NULL::text;
      v_payment_date := COALESCE(v_batch_row.authoritative_payment_date, v_batch_row.pay_date);
      IF v_payment_date IS NULL THEN
        RAISE EXCEPTION 'pay_batch_auth_start: batch payment date is required for zero-row CSV settlement';
      END IF;
    END IF;

    v_stored_csv_zero_row := v_stored_csv_row_count = 0;
    v_csv_evidence_validated := true;
    v_csv_evidence_json := JSONB_STRIP_NULLS(
      JSONB_BUILD_OBJECT(
        'validated', true,
        'validated_at_utc', v_now::text,
        'scope', v_stored_csv_scope,
        'paye_net_state_hash', v_stored_csv_paye_net_state_hash,
        'bank_payment_projection_hash', v_stored_csv_bank_projection_hash,
        'row_count', v_stored_csv_row_count,
        'total_amount', v_stored_csv_total,
        'zero_row', v_stored_csv_zero_row,
        'no_bank_payment_required_for_scope', v_scoped_no_transfer_execution_validated,
        'confirmation_kind', CASE
          WHEN v_scoped_no_transfer_execution_validated THEN 'ZERO_ROW_REVIEW'
          ELSE 'BANK_UPLOAD_CONFIRMATION'
        END,
        'generated_at_utc', v_stored_csv_generated_at_utc,
        'generated_by_user_id', v_stored_csv_generated_by_user_id,
        'filename', v_stored_csv_filename
      )
      || JSONB_BUILD_OBJECT(
        'csv_uploaded_confirmed', v_effective_csv_uploaded_confirmed,
        'csv_bank_confirm_ref', v_effective_csv_bank_confirm_ref,
        'authoritative_accounting_payment_date', v_payment_date::text,
        'source', 'PAY_BATCH_AUTH_START'
      )
    );
  ELSIF v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN
    IF v_scoped_positive_bank_payment_count > 0
       AND v_effective_external_settlement_comment IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'EXTERNAL_SETTLEMENT_COMMENT_REQUIRED',
        'message', 'Positive external settlement requires a mandatory settlement comment before authorisation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'pay_channel_scope', v_pay_channel_scope
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    v_effective_freshness_result_hash := nullif(btrim(coalesce(p_freshness_result_hash, v_batch_row.freshness_result_hash, v_operation_row.progress_json->>'freshness_result_hash', '')), '');
    v_effective_freshness_scope_hash := nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, v_operation_row.progress_json->>'freshness_scope_hash', '')), '');

    IF nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch freshness result hash is required before operation-scoped bank authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'batch_freshness_result_hash_present', false
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_TYPE_NOT_SUPPORTED_FOR_AUTH_START_FAST_PATH',
        'message', 'Operation-scoped payment authorisation can only use a payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_type', v_operation_row.operation_type
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_operation_row.status, ''))) NOT IN ('QUEUED', 'RUNNING', 'WAITING_AUTHORISATION') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_NOT_ACTIVE_FOR_AUTH_START',
        'message', 'Operation-scoped payment authorisation requires an active payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_status', v_operation_row.status
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_batch_row.status, ''))) <> 'DRAFT' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Only a draft payment batch can be authorised for execution.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'batch_status', v_batch_row.status
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(p_freshness_result_hash, '')), '') <> nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'Payment freshness proof does not match the batch freshness result.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'provided_freshness_result_hash', nullif(btrim(coalesce(p_freshness_result_hash, '')), ''),
        'batch_freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), '') <> nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'Operation freshness proof does not match the batch freshness result.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_freshness_result_hash', nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
        'batch_freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(v_effective_freshness_result_hash, '')), '') IS NULL
       OR upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))) <> 'PASSED'
       OR coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false) IS TRUE THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch freshness must be passed and non-stale before authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_batch_row.freshness_validation_status,
        'freshness_result_hash_present', nullif(btrim(coalesce(v_effective_freshness_result_hash, '')), '') IS NOT NULL,
        'freshness_is_stale', coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  ---------------------------------------------------------------------------
  -- Final pre-authorisation freshness gate.
  -- Operation-proof path must not run the legacy full-batch freshness scan.
  -- It trusts the already persisted central freshness proof on pay_batches,
  -- then performs only the explicit carry-forward freshness check, which is
  -- bounded to this batch/scope and does not remap batch economic keys.
  ---------------------------------------------------------------------------
  IF p_operation_id IS NOT NULL THEN
    v_auth_freshness_json := jsonb_build_object(
      'is_stale', false,
      'stale_reasons', '[]'::jsonb,
      'diff', '[]'::jsonb,
      'proof_mode', true,
      'freshness_result_hash', v_effective_freshness_result_hash,
      'freshness_scope_hash', v_effective_freshness_scope_hash
    );

    v_auth_carry_forward_freshness_json := public._pay_manual_adjustment_carry_forward_freshness_check(
      p_pay_batch_id,
      NULL::uuid[],
      NULL::uuid[],
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'surface', 'pay_batch_auth_start',
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'idempotency_key_present', v_requested_idempotency_key IS NOT NULL
      ),
      p_actor_user_id
    );

    v_auth_carry_forward_blocker_count := jsonb_array_length(
      CASE
        WHEN jsonb_typeof(v_auth_carry_forward_freshness_json->'blockers') = 'array'
          THEN COALESCE(v_auth_carry_forward_freshness_json->'blockers', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    );

    SELECT COALESCE(jsonb_agg(DISTINCT reason_rows.reason_text ORDER BY reason_rows.reason_text), '[]'::jsonb)
    INTO v_auth_freshness_blocker_reasons
    FROM (
      SELECT CASE
        WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
          THEN 'Manual adjustment carry-forward was consumed elsewhere'
        WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
          THEN 'Source payment scope changed'
        ELSE 'Manual adjustment carry-forward changed'
      END AS reason_text
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_auth_carry_forward_freshness_json->'blockers') = 'array'
            THEN COALESCE(v_auth_carry_forward_freshness_json->'blockers', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS carry_forward_blockers(blocker_value)
    ) AS reason_rows
    WHERE NULLIF(BTRIM(COALESCE(reason_rows.reason_text, '')), '') IS NOT NULL;

    IF COALESCE(v_auth_carry_forward_blocker_count, 0) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_STALE',
        'message', 'Payment batch freshness is stale and must be refreshed before authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'stale_reasons', COALESCE(v_auth_freshness_blocker_reasons, '[]'::jsonb),
        'freshness_result', COALESCE(v_auth_freshness_json, '{}'::jsonb),
        'carry_forward_freshness_result', COALESCE(v_auth_carry_forward_freshness_json, '{}'::jsonb)
      )::text USING ERRCODE = 'P0001';
    END IF;
  ELSE
    v_auth_freshness_json := public.pay_batch_validate_freshness(
      p_pay_batch_id,
      p_actor_user_id,
      false
    );

    v_auth_carry_forward_freshness_json := public._pay_manual_adjustment_carry_forward_freshness_check(
      p_pay_batch_id,
      NULL::uuid[],
      NULL::uuid[],
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'surface', 'pay_batch_auth_start',
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'idempotency_key_present', v_requested_idempotency_key IS NOT NULL
      ),
      p_actor_user_id
    );

    v_auth_carry_forward_blocker_count := jsonb_array_length(
      CASE
        WHEN jsonb_typeof(v_auth_carry_forward_freshness_json->'blockers') = 'array'
          THEN COALESCE(v_auth_carry_forward_freshness_json->'blockers', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    );

    SELECT COALESCE(jsonb_agg(DISTINCT reason_rows.reason_text ORDER BY reason_rows.reason_text), '[]'::jsonb)
    INTO v_auth_freshness_blocker_reasons
    FROM (
      SELECT stale_reason_values.reason_text
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_auth_freshness_json->'stale_reasons') = 'array'
            THEN COALESCE(v_auth_freshness_json->'stale_reasons', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS stale_reason_values(reason_text)

      UNION ALL

      SELECT CASE
        WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
          THEN 'Manual adjustment carry-forward was consumed elsewhere'
        WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
          THEN 'Source payment scope changed'
        ELSE 'Manual adjustment carry-forward changed'
      END AS reason_text
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_auth_carry_forward_freshness_json->'blockers') = 'array'
            THEN COALESCE(v_auth_carry_forward_freshness_json->'blockers', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS carry_forward_blockers(blocker_value)
    ) AS reason_rows
    WHERE NULLIF(BTRIM(COALESCE(reason_rows.reason_text, '')), '') IS NOT NULL;

    IF LOWER(COALESCE(v_auth_freshness_json->>'is_stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
       OR COALESCE(v_auth_carry_forward_blocker_count, 0) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_STALE',
        'message', 'Payment batch freshness is stale and must be refreshed before authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'stale_reasons', COALESCE(v_auth_freshness_blocker_reasons, '[]'::jsonb),
        'freshness_result', COALESCE(v_auth_freshness_json, '{}'::jsonb),
        'carry_forward_freshness_result', COALESCE(v_auth_carry_forward_freshness_json, '{}'::jsonb)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;


  PERFORM 1
  FROM public.pay_batch_auth_requests AS auth_request_lock
  WHERE auth_request_lock.pay_batch_id = p_pay_batch_id
    AND auth_request_lock.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
  FOR UPDATE OF auth_request_lock;

  IF p_operation_id IS NOT NULL THEN
    v_auth_start_path := CASE
      WHEN v_scoped_no_transfer_execution_validated THEN 'OPERATION_SCOPED_NO_TRANSFER_PATH'
      WHEN v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT') THEN 'OPERATION_SCOPED_LOCAL_MANUAL_PROOF_PATH'
      ELSE 'OPERATION_SCOPED_PROOF_PATH'
    END;
    v_used_operation_scope_proof := v_scoped_no_transfer_execution_validated IS NOT TRUE;

    v_prepare_json := public.pay_batch_prepare(
      p_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id,
      p_operation_id => p_operation_id,
      p_freshness_result_hash => p_freshness_result_hash
    );

    v_prepare_execution_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_prepare_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_prepare_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_prepare_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE NULL::text
    END;
    v_prepare_next_required_phase := UPPER(BTRIM(COALESCE(v_prepare_json->>'next_required_phase', '')));

    IF v_prepare_execution_mode IS DISTINCT FROM v_execution_mode THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_PREPARE_EXECUTION_MODE_MISMATCH',
        'message', 'Payment batch prepare returned an execution mode that does not match the durable operation mode.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'durable_execution_mode', v_execution_mode,
        'prepare_execution_mode', v_prepare_execution_mode,
        'prepare_next_required_phase', NULLIF(v_prepare_next_required_phase, '')
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
       AND (
         v_prepare_next_required_phase IN (
           'PROVIDER_SUBMIT_CLAIM', 'CLAIM_PROVIDER_SUBMIT', 'SUBMIT_PROVIDER_TRANSFERS',
           'SEND_PROVIDER_CHUNK', 'REQUEST_PROVIDER_SEND', 'FINALISE_PROVIDER_CHUNK', 'APPLY_RAIL_UPDATES'
         )
         OR LOWER(BTRIM(COALESCE(v_prepare_json->>'provider_submission_required', ''))) <> 'false'
         OR LOWER(BTRIM(COALESCE(v_prepare_json->>'provider_submission_attempted', ''))) <> 'false'
         OR LOWER(BTRIM(COALESCE(v_prepare_json->>'submitted_to_bank', ''))) <> 'false'
       ) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'LOCAL_MANUAL_PREPARE_PROVIDER_ROUTE_REJECTED',
        'message', 'Local/manual payment preparation returned provider-submission routing or evidence.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_mode', v_execution_mode,
        'prepare_next_required_phase', NULLIF(v_prepare_next_required_phase, ''),
        'provider_submission_required', v_prepare_json->'provider_submission_required',
        'provider_submission_attempted', v_prepare_json->'provider_submission_attempted',
        'submitted_to_bank', v_prepare_json->'submitted_to_bank'
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_ready := COALESCE((v_prepare_json->>'ready')::boolean, false);
    v_blocker_count := COALESCE(NULLIF(v_prepare_json->>'blocker_count', '')::integer, 0);
    v_prepare_blockers := CASE
      WHEN JSONB_TYPEOF(v_prepare_json->'blockers') = 'array'
        THEN COALESCE(v_prepare_json->'blockers', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    IF JSONB_ARRAY_LENGTH(v_prepare_blockers) = 0
       AND COALESCE(v_prepare_json->>'code', '') IN (
         'OPERATION_TRANSFER_SCOPE_PROOF_MISSING',
         'OPERATION_TRANSFER_SCOPE_NOT_PREPARED',
         'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED',
         'BANK_TRANSFERS_NOT_PREPARED',
         'NO_AUTHORISATION_READY_TRANSFERS'
       ) THEN
      v_prepare_blockers := JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', v_prepare_json->>'code',
        'message', v_prepare_json->>'message'
      ));
    END IF;

    IF v_ready IS NOT TRUE AND v_scoped_no_transfer_execution_validated THEN
      SELECT
        COALESCE(JSONB_AGG(blocker_element.value ORDER BY blocker_element.ordinality) FILTER (
          WHERE COALESCE(blocker_element.value->>'code', '') NOT IN (
            'OPERATION_TRANSFER_SCOPE_PROOF_MISSING',
            'OPERATION_TRANSFER_SCOPE_NOT_PREPARED',
            'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED',
            'BANK_TRANSFERS_NOT_PREPARED',
            'NO_AUTHORISATION_READY_TRANSFERS'
          )
        ), '[]'::jsonb),
        COALESCE(JSONB_AGG(blocker_element.value ORDER BY blocker_element.ordinality) FILTER (
          WHERE COALESCE(blocker_element.value->>'code', '') IN (
            'OPERATION_TRANSFER_SCOPE_PROOF_MISSING',
            'OPERATION_TRANSFER_SCOPE_NOT_PREPARED',
            'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED',
            'BANK_TRANSFERS_NOT_PREPARED',
            'NO_AUTHORISATION_READY_TRANSFERS'
          )
        ), '[]'::jsonb)
      INTO
        v_prepare_unwaived_blockers,
        v_prepare_waived_blockers
      FROM JSONB_ARRAY_ELEMENTS(v_prepare_blockers) WITH ORDINALITY AS blocker_element(value, ordinality);

      IF JSONB_ARRAY_LENGTH(v_prepare_blockers) > 0
         AND JSONB_ARRAY_LENGTH(v_prepare_unwaived_blockers) = 0 THEN
        v_ready := true;
        v_blocker_count := 0;
        v_auth_start_path := 'OPERATION_SCOPED_NO_TRANSFER_PATH';
        v_used_operation_scope_proof := false;
        v_prepare_json := v_prepare_json
          || JSONB_BUILD_OBJECT(
            'ready', true,
            'blocker_count', 0,
            'blockers', '[]'::jsonb,
            'no_bank_payment_execution', true,
            'waived_no_transfer_blockers', v_prepare_waived_blockers
          );
      END IF;
    END IF;

    IF v_ready IS NOT TRUE THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch is not ready for operation-scoped authorisation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_start_path', v_auth_start_path,
        'blocker_count', v_blocker_count,
        'blockers', COALESCE(v_prepare_json->'blockers', '[]'::jsonb)
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
       AND v_prepare_next_required_phase NOT IN ('START_AUTHORISATION', 'START_AUTHORISATION_PROOF') THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'LOCAL_MANUAL_PREPARE_AUTHORISATION_ROUTE_REQUIRED',
        'message', 'A ready local/manual payment proof must route to authorisation, never provider submission or direct settlement.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_mode', v_execution_mode,
        'prepare_next_required_phase', NULLIF(v_prepare_next_required_phase, '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_summary_json := COALESCE(v_prepare_json->'execution_summary', '{}'::jsonb);
    v_effective_freshness_result_hash := NULLIF(BTRIM(COALESCE(p_freshness_result_hash, v_prepare_json #>> '{freshness,freshness_result_hash}', v_batch_row.freshness_result_hash, '')), '');
    v_effective_freshness_scope_hash := NULLIF(BTRIM(COALESCE(v_prepare_json #>> '{freshness,freshness_scope_hash}', v_batch_row.freshness_scope_hash, '')), '');
    v_authorisation_ready_transfer_count := COALESCE(NULLIF(v_prepare_json->>'authorisation_ready_transfer_count', '')::integer, NULLIF(v_summary_json->>'authorisation_ready_transfer_count', '')::integer, 0);
    v_scoped_operation_scope_count := COALESCE(NULLIF(v_prepare_json->>'scoped_operation_scope_count', '')::integer, NULLIF(v_summary_json->>'transfer_count', '')::integer, 0);
    v_scoped_scope_prepared_count := COALESCE(NULLIF(v_prepare_json->>'scoped_scope_prepared_count', '')::integer, v_scoped_operation_scope_count, 0);
    v_pending_transfer_count := COALESCE(v_authorisation_ready_transfer_count, 0);
    v_provider_attempt_or_evidence_transfer_count := COALESCE(NULLIF(v_prepare_json->>'provider_attempt_or_evidence_transfer_count', '')::integer, 0);
    v_provider_or_ambiguous_evidence_transfer_count := COALESCE(NULLIF(v_prepare_json->>'provider_or_ambiguous_evidence_transfer_count', '')::integer, 0);
    v_canonical_pending_status_transfer_count := COALESCE(NULLIF(v_prepare_json->>'canonical_pending_status_transfer_count', '')::integer, 0);
    v_unsafe_transfer_count := COALESCE(NULLIF(v_prepare_json->>'unsafe_transfer_count', '')::integer, 0);
    v_scope_amount_total := COALESCE(NULLIF(v_summary_json->>'scope_amount_total', '')::numeric, 0);
    v_transfer_amount_total := COALESCE(NULLIF(v_summary_json->>'transfer_amount_total', '')::numeric, v_scope_amount_total);
    v_scope_item_amount_total := COALESCE(NULLIF(v_summary_json->>'scope_item_amount_total', '')::numeric, v_scope_amount_total);
    v_batch_item_amount_total := COALESCE(NULLIF(v_summary_json->>'batch_item_amount_total', '')::numeric, v_scope_amount_total);

  ELSE
    v_prepare_json := public.pay_batch_prepare(
      p_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id,
      p_operation_id => p_operation_id,
      p_freshness_result_hash => p_freshness_result_hash
    );
    v_ready := coalesce((v_prepare_json->>'ready')::boolean, false);
    v_blocker_count := coalesce(NULLIF(v_prepare_json->>'blocker_count', '')::integer, 0);
    v_effective_freshness_result_hash := nullif(btrim(coalesce(p_freshness_result_hash, v_prepare_json #>> '{freshness,freshness_result_hash}', '')), '');
    v_effective_freshness_scope_hash := nullif(btrim(coalesce(v_prepare_json #>> '{freshness,freshness_scope_hash}', '')), '');

    IF v_ready IS NOT TRUE THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch is not ready for authorisation.',
        'pay_batch_id', p_pay_batch_id::text,
        'blocker_count', v_blocker_count,
        'blockers', coalesce(v_prepare_json->'blockers', '[]'::jsonb)
      )::text;
    END IF;

    v_summary_json := coalesce(v_prepare_json->'execution_summary', public.pay_batch_execution_summary_get(p_pay_batch_id, p_actor_user_id));
    v_pending_transfer_count := coalesce(NULLIF(v_summary_json->>'pending_transfer_count', '')::integer, 0);

    IF v_execution_mode IN ('STANDARD_BANK', 'BANK') THEN
      SELECT
        count(*) FILTER (WHERE classified_transfer.is_authorisation_ready)::integer,
        count(*) FILTER (WHERE classified_transfer.evidence_classification = 'local_only_evidence')::integer,
        count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt)::integer,
        count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt OR classified_transfer.has_ambiguous_external_evidence)::integer,
        count(*) FILTER (WHERE classified_transfer.is_failed_or_blocked)::integer,
        count(*) FILTER (WHERE classified_transfer.status_upper = 'PENDING')::integer,
        count(DISTINCT classified_transfer.auth_request_id) FILTER (
          WHERE classified_transfer.auth_request_id IS NOT NULL
            AND classified_transfer.has_non_cancellable_auth_request IS TRUE
        )::integer,
        count(DISTINCT classified_transfer.auth_request_id) FILTER (
          WHERE classified_transfer.auth_request_id IS NOT NULL
            AND (
              classified_transfer.has_non_cancellable_auth_request IS TRUE
              OR classified_transfer.has_auth_request_provider_risk IS TRUE
              OR classified_transfer.has_other_operation_active_auth_request IS TRUE
            )
        )::integer
      INTO v_authorisation_ready_transfer_count,
           v_local_only_transfer_count,
           v_provider_attempt_or_evidence_transfer_count,
           v_provider_or_ambiguous_evidence_transfer_count,
           v_blocked_transfer_count,
           v_canonical_pending_status_transfer_count,
           v_non_cancellable_auth_request_count,
           v_auth_request_retry_blocker_count
      FROM public.pay_bank_transfer_execution_classify(
        p_pay_batch_id => p_pay_batch_id,
        p_pay_channel_scope => v_pay_channel_scope,
        p_operation_id => p_operation_id,
        p_include_unscoped_transfers => CASE WHEN p_operation_id IS NULL THEN true ELSE false END,
        p_action_context => 'AUTHORISATION_ACTION'
      ) AS classified_transfer;

      IF p_operation_id IS NOT NULL THEN
        SELECT count(*)::integer,
               count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'PREPARED')::integer,
               count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'FAILED')::integer,
               count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'SKIPPED')::integer,
               count(*) FILTER (WHERE operation_scope.pay_bank_transfer_id IS NULL)::integer
        INTO v_scoped_operation_scope_count,
             v_scoped_scope_prepared_count,
             v_scoped_scope_failed_count,
             v_scoped_scope_skipped_count,
             v_scoped_scope_without_transfer_count
        FROM public.banking_pay_operation_transfer_scope AS operation_scope
        WHERE operation_scope.pay_batch_id = p_pay_batch_id
          AND operation_scope.operation_id = p_operation_id
          AND (
            v_pay_channel_scope IN ('ALL', 'ANY', '*')
            OR upper(btrim(coalesce(operation_scope.pay_channel, ''))) = v_pay_channel_scope
          );
      END IF;

      IF COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_AUTH_START',
          'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
          'message', 'An active authorisation request is not safe to reuse or cancel automatically for this payment execution attempt.',
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_pay_channel_scope,
          'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
          'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
          'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF p_operation_id IS NOT NULL
         AND (
           COALESCE(v_scoped_operation_scope_count, 0) <= 0
           OR COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
           OR COALESCE(v_scoped_scope_failed_count, 0) <> 0
           OR COALESCE(v_scoped_scope_skipped_count, 0) <> 0
           OR COALESCE(v_scoped_scope_without_transfer_count, 0) <> 0
           OR COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         ) THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_AUTH_START',
          'code', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED' ELSE 'NO_AUTHORISATION_READY_TRANSFERS' END,
          'message', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'One or more scoped transfers have provider submission evidence or ambiguous provider state and must be reviewed before authorisation can continue.' ELSE 'All scoped transfer groups must be prepared and authorisation-ready before authorisation can start.' END,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_pay_channel_scope,
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
          'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
          'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
          'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
          'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
          'blocked_transfer_count', COALESCE(v_blocked_transfer_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF p_operation_id IS NULL AND COALESCE(v_authorisation_ready_transfer_count, 0) <= 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_AUTH_START',
          'code', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED' ELSE 'NO_AUTHORISATION_READY_TRANSFERS' END,
          'message', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'One or more transfers have provider submission evidence or ambiguous provider state and must be reviewed before authorisation can continue.' ELSE 'No safe locally prepared transfers are available for authorisation.' END,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_pay_channel_scope,
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
          'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
          'blocked_transfer_count', COALESCE(v_blocked_transfer_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  IF v_effective_freshness_result_hash IS NULL THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'FRESHNESS_RESULT_HASH_REQUIRED',
      'message', 'A server-owned freshness result hash is required before an authorisation request can be created or reused.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
      'execution_mode', v_execution_mode
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_current_active_scope_hash := private.pay_payment_correction_sha256_v1(
    JSONB_BUILD_OBJECT(
      'version', 1,
      'pay_batch_id', p_pay_batch_id,
      'freshness_result_hash', v_effective_freshness_result_hash,
      'freshness_scope_hash', v_effective_freshness_scope_hash,
      'active_items', (
        SELECT COALESCE(
          JSONB_AGG(
            JSONB_BUILD_ARRAY(
              candidate_row.id,
              item_row.id,
              ROUND(COALESCE(item_row.amount_inc_vat, 0) * 100)::bigint,
              item_row.item_type,
              item_row.pay_channel,
              item_row.reservation_id,
              item_row.finance_component_id,
              item_row.pay_bank_transfer_id
            )
            ORDER BY candidate_row.id, item_row.id
          ),
          '[]'::jsonb
        )
        FROM public.pay_batch_candidates AS candidate_row
        JOIN public.pay_batch_items AS item_row
          ON item_row.pay_batch_candidate_id = candidate_row.id
        WHERE candidate_row.pay_batch_id = p_pay_batch_id
          AND COALESCE(item_row.is_voided, false) IS NOT TRUE
      )
    )
  );

  v_execution_intent_json := JSONB_STRIP_NULLS(
    JSONB_BUILD_OBJECT(
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
      'idempotency_key', v_requested_idempotency_key,
      'execution_mode', v_execution_mode,
      'pay_channel_scope', v_pay_channel_scope,
      'payment_date', v_payment_date::text,
      'freshness_result_hash', v_effective_freshness_result_hash,
      'freshness_scope_hash', v_effective_freshness_scope_hash,
      'active_scope_hash', v_current_active_scope_hash,
      'schedule_kind', v_kind,
      'scheduled_at_utc', CASE WHEN v_scheduled_at_utc IS NULL THEN NULL::text ELSE v_scheduled_at_utc::text END,
      'funding_account_ref', v_funding_account_ref,
      'funds_warning_hours_json', v_warning_hours_json,
      'actor_intent', NULLIF(v_intent, ''),
      'actor_user_id', p_actor_user_id::text
    )
    || JSONB_BUILD_OBJECT(
      'suppress_remittances', COALESCE(p_suppress_remittances, false),
      'suppress_remittances_confirmed', COALESCE(p_suppress_remittances_confirmed, false),
      'auth_start_path', v_auth_start_path,
      'pay_batch_prepare_skipped', v_used_operation_scope_proof,
      'used_operation_scope_proof', v_used_operation_scope_proof,
      'waived_no_transfer_blockers', CASE WHEN v_scoped_no_transfer_execution_validated THEN v_prepare_waived_blockers ELSE NULL::jsonb END,
      'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
      'provider_submission_attempted', false,
      'submitted_to_bank', false
    )
    || v_server_projection_proof_json
    || CASE
         WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN
           JSONB_BUILD_OBJECT(
             'csv_uploaded_confirmed', v_effective_csv_uploaded_confirmed,
             'csv_bank_confirm_ref', v_effective_csv_bank_confirm_ref,
             'manual_confirmation_mode', v_manual_confirmation_mode,
             'bank_csv_evidence', v_csv_evidence_json,
             'csv_evidence_validated', v_csv_evidence_validated,
             'csv_zero_row', v_stored_csv_zero_row,
             'bank_csv_generated', true,
             'bank_csv_current', true,
             'bank_csv_scope', v_stored_csv_scope,
             'bank_csv_paye_net_state_hash', v_stored_csv_paye_net_state_hash,
             'bank_csv_bank_payment_projection_hash', v_stored_csv_bank_projection_hash,
             'bank_csv_row_count', v_stored_csv_row_count,
             'bank_csv_total_amount', v_stored_csv_total
           )
           || JSONB_BUILD_OBJECT(
             'csv_currentness_proof', JSONB_BUILD_OBJECT(
               'validated', true,
               'current', true,
               'validated_at_utc', v_now::text,
               'scope', v_stored_csv_scope,
               'paye_net_state_hash', v_stored_csv_paye_net_state_hash,
               'bank_payment_projection_hash', v_stored_csv_bank_projection_hash,
               'row_count', v_stored_csv_row_count,
               'total_amount', v_stored_csv_total,
               'source', 'PAY_BATCH_AUTH_START'
             )
           )
         WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN
           JSONB_BUILD_OBJECT(
             'external_settlement_comment', v_effective_external_settlement_comment,
             'manual_confirmation_mode', v_manual_confirmation_mode,
             'external_settlement_proof_source', 'EXTERNAL_MANUAL_CONFIRMATION',
             'external_settlement_confirmed', true
           )
         ELSE '{}'::jsonb
       END
  );


  <<auth_lookup_loop>>
  LOOP
    v_auth_lookup_pass := v_auth_lookup_pass + 1;
    IF v_auth_lookup_pass > 2 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'AUTH_REQUEST_RECONCILIATION_LOOP_GUARD',
        'message', 'Authorisation request reconciliation did not reach a stable state.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_existing_auth_id := NULL::uuid;
    v_existing_auth_state := NULL::text;
    v_existing_auth_intent_json := '{}'::jsonb;
    v_existing_auth_operation_id := NULL::text;
    v_existing_auth_idempotency_key := NULL::text;
    v_existing_auth_schedule_kind := NULL::text;
    v_existing_auth_scheduled_at_utc := NULL::timestamptz;
    v_existing_auth_funding_account_ref := NULL::text;
    v_existing_auth_warning_hours_json := NULL::jsonb;
    v_existing_auth_execution_mode := NULL::text;
    v_existing_auth_compatible := false;
    v_existing_auth_cross_operation := false;
    v_existing_auth_cross_operation_authorised := false;
    v_existing_auth_identity_matches := false;
    v_existing_auth_mode_specific_proof_matches := false;
    v_existing_auth_compatibility_json := '{}'::jsonb;
    v_conflicting_auth_id := NULL::uuid;
    v_conflicting_auth_state := NULL::text;
    v_conflicting_auth_operation_id := NULL::text;
    v_conflicting_auth_idempotency_key := NULL::text;
    v_conflicting_auth_intent_json := '{}'::jsonb;

    SELECT auth_request.id,
           auth_request.state,
           COALESCE(auth_request.execution_intent_json, '{}'::jsonb),
           NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), ''),
           NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'idempotency_key', '')), ''),
           UPPER(BTRIM(COALESCE(auth_request.schedule_kind, ''))),
           auth_request.scheduled_at_utc,
           NULLIF(BTRIM(COALESCE(auth_request.funding_account_ref, '')), ''),
           COALESCE(auth_request.funds_warning_hours_json, '[]'::jsonb)
    INTO v_existing_auth_id,
         v_existing_auth_state,
         v_existing_auth_intent_json,
         v_existing_auth_operation_id,
         v_existing_auth_idempotency_key,
         v_existing_auth_schedule_kind,
         v_existing_auth_scheduled_at_utc,
         v_existing_auth_funding_account_ref,
         v_existing_auth_warning_hours_json
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.pay_batch_id = p_pay_batch_id
      AND auth_request.state IN ('AWAITING', 'AUTHORISED')
      AND (
        (
          p_operation_id IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
        )
        OR (
          v_requested_idempotency_key IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key
        )
      )
    ORDER BY
      CASE
        WHEN p_operation_id IS NOT NULL
         AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text THEN 0
        WHEN v_requested_idempotency_key IS NOT NULL
         AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key THEN 1
        ELSE 2
      END,
      auth_request.created_at_utc DESC NULLS LAST,
      auth_request.id DESC
    LIMIT 1;

    IF v_existing_auth_id IS NOT NULL THEN
      v_existing_auth_execution_mode := CASE
        WHEN UPPER(BTRIM(COALESCE(v_existing_auth_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
        WHEN UPPER(BTRIM(COALESCE(v_existing_auth_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
        WHEN UPPER(BTRIM(COALESCE(v_existing_auth_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
        ELSE NULL::text
      END;
      v_existing_auth_identity_matches := (
        (p_operation_id IS NOT NULL AND v_existing_auth_operation_id = p_operation_id::text)
        OR (v_requested_idempotency_key IS NOT NULL AND v_existing_auth_idempotency_key = v_requested_idempotency_key)
      );
      v_existing_auth_cross_operation := p_operation_id IS NOT NULL
        AND v_existing_auth_operation_id IS NOT NULL
        AND v_existing_auth_operation_id <> p_operation_id::text;
      v_existing_auth_cross_operation_authorised := v_existing_auth_cross_operation
        AND UPPER(BTRIM(COALESCE(v_existing_auth_state, ''))) = 'AUTHORISED';

      v_existing_auth_mode_specific_proof_matches := CASE
        WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN
          LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'csv_bank_confirm_ref', '')), '') IS NOT DISTINCT FROM v_effective_csv_bank_confirm_ref
          AND UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'manual_confirmation_mode', '')), '')) IS NOT DISTINCT FROM v_manual_confirmation_mode
          AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'csv_evidence_validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'bank_csv_generated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'bank_csv_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'bank_csv_scope', '')), '')) IS NOT DISTINCT FROM v_stored_csv_scope
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'bank_csv_paye_net_state_hash', '')), '') IS NOT DISTINCT FROM v_stored_csv_paye_net_state_hash
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'bank_csv_bank_payment_projection_hash', '')), '') IS NOT DISTINCT FROM v_stored_csv_bank_projection_hash
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'bank_csv_row_count', '')), '') IS NOT DISTINCT FROM v_stored_csv_row_count::text
          AND CASE
                WHEN COALESCE(v_existing_auth_intent_json->>'bank_csv_total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                  THEN ROUND((v_existing_auth_intent_json->>'bank_csv_total_amount')::numeric, 2) IS NOT DISTINCT FROM ROUND(v_stored_csv_total, 2)
                ELSE false
              END
          AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json #>> '{csv_currentness_proof,validated}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json #>> '{csv_currentness_proof,current}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN
          UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'manual_confirmation_mode', '')), '')) IS NOT DISTINCT FROM v_manual_confirmation_mode
          AND UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'external_settlement_proof_source', '')), '')) = 'EXTERNAL_MANUAL_CONFIRMATION'
          AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'external_settlement_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND (
            v_scoped_positive_bank_payment_count = 0
            OR NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'external_settlement_comment', '')), '') IS NOT DISTINCT FROM v_effective_external_settlement_comment
          )
        ELSE true
      END;

      v_existing_auth_compatible := (
        v_existing_auth_identity_matches
        AND v_existing_auth_cross_operation_authorised IS NOT TRUE
        AND (p_operation_id IS NULL OR v_existing_auth_operation_id = p_operation_id::text)
        AND UPPER(BTRIM(COALESCE(v_existing_auth_state, ''))) IN ('AWAITING', 'AUTHORISED')
        AND v_existing_auth_execution_mode IS NOT DISTINCT FROM v_execution_mode
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text
        AND UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'pay_channel_scope', '')), '')) IS NOT DISTINCT FROM v_pay_channel_scope
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'payment_date', '')), '') IS NOT DISTINCT FROM v_payment_date::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'freshness_result_hash', '')), '') IS NOT DISTINCT FROM v_effective_freshness_result_hash
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'freshness_scope_hash', '')), '') IS NOT DISTINCT FROM v_effective_freshness_scope_hash
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_paye_net_state_hash', '')), '') IS NOT DISTINCT FROM v_current_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_bank_payment_projection_hash', '')), '') IS NOT DISTINCT FROM v_all_bank_payment_projection_hash
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_paye_net_state_hash', '')), '') IS NOT DISTINCT FROM v_scoped_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_bank_payment_projection_hash', '')), '') IS NOT DISTINCT FROM v_current_bank_payment_projection_hash
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_missing_explicit_paye_input_count', '')), '') IS NOT DISTINCT FROM v_global_paye_missing_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_explicit_zero_count', '')), '') IS NOT DISTINCT FROM v_global_paye_zero_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_positive_bank_payment_count', '')), '') IS NOT DISTINCT FROM v_global_positive_bank_payment_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_invalid_payment_row_count', '')), '') IS NOT DISTINCT FROM v_global_invalid_payment_row_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_missing_explicit_paye_input_count', '')), '') IS NOT DISTINCT FROM v_scoped_paye_missing_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_explicit_zero_count', '')), '') IS NOT DISTINCT FROM v_scoped_explicit_zero_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_positive_bank_payment_count', '')), '') IS NOT DISTINCT FROM v_scoped_positive_bank_payment_count::text
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_invalid_payment_row_count', '')), '') IS NOT DISTINCT FROM v_scoped_invalid_payment_row_count::text
        AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(v_existing_auth_schedule_kind, ''))) IS NOT DISTINCT FROM v_kind
        AND (v_kind <> 'SCHEDULED' OR v_existing_auth_scheduled_at_utc IS NOT DISTINCT FROM v_scheduled_at_utc)
        AND v_existing_auth_funding_account_ref IS NOT DISTINCT FROM v_funding_account_ref
        AND COALESCE(v_existing_auth_warning_hours_json, '[]'::jsonb) IS NOT DISTINCT FROM COALESCE(v_warning_hours_json, '[]'::jsonb)
        AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'suppress_remittances', 'false'))) = CASE WHEN COALESCE(p_suppress_remittances, false) THEN 'true' ELSE 'false' END
        AND LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'suppress_remittances_confirmed', 'false'))) = CASE WHEN COALESCE(p_suppress_remittances_confirmed, false) THEN 'true' ELSE 'false' END
        AND UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'actor_intent', '')), '')) IS NOT DISTINCT FROM NULLIF(v_intent, '')
        AND v_existing_auth_mode_specific_proof_matches
        AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'auth_request_id', '')), '') = v_existing_auth_id::text
      );

      v_existing_auth_compatibility_json := JSONB_BUILD_OBJECT(
        'identity_matches', v_existing_auth_identity_matches,
        'operation_binding_matches', p_operation_id IS NULL OR v_existing_auth_operation_id = p_operation_id::text,
        'cross_operation_authorised', v_existing_auth_cross_operation_authorised,
        'state_reusable', UPPER(BTRIM(COALESCE(v_existing_auth_state, ''))) IN ('AWAITING', 'AUTHORISED'),
        'execution_mode_matches', v_existing_auth_execution_mode IS NOT DISTINCT FROM v_execution_mode,
        'pay_batch_matches', NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text,
        'scope_matches', UPPER(NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'pay_channel_scope', '')), '')) IS NOT DISTINCT FROM v_pay_channel_scope,
        'payment_date_matches', NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'payment_date', '')), '') IS NOT DISTINCT FROM v_payment_date::text,
        'freshness_result_hash_matches', NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'freshness_result_hash', '')), '') IS NOT DISTINCT FROM v_effective_freshness_result_hash,
        'freshness_scope_hash_matches', NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'freshness_scope_hash', '')), '') IS NOT DISTINCT FROM v_effective_freshness_scope_hash,
        'projection_hashes_match',
          NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_paye_net_state_hash', '')), '') IS NOT DISTINCT FROM v_current_paye_net_state_hash
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'global_bank_payment_projection_hash', '')), '') IS NOT DISTINCT FROM v_all_bank_payment_projection_hash
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_paye_net_state_hash', '')), '') IS NOT DISTINCT FROM v_scoped_paye_net_state_hash
          AND NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'scoped_bank_payment_projection_hash', '')), '') IS NOT DISTINCT FROM v_current_bank_payment_projection_hash,
        'mode_specific_proof_matches', v_existing_auth_mode_specific_proof_matches,
        'compatible', v_existing_auth_compatible
      ) || JSONB_BUILD_OBJECT(
        'schedule_matches', UPPER(BTRIM(COALESCE(v_existing_auth_schedule_kind, ''))) IS NOT DISTINCT FROM v_kind
          AND (v_kind <> 'SCHEDULED' OR v_existing_auth_scheduled_at_utc IS NOT DISTINCT FROM v_scheduled_at_utc),
        'funding_matches', v_existing_auth_funding_account_ref IS NOT DISTINCT FROM v_funding_account_ref,
        'warning_hours_match', COALESCE(v_existing_auth_warning_hours_json, '[]'::jsonb) IS NOT DISTINCT FROM COALESCE(v_warning_hours_json, '[]'::jsonb),
        'server_owned_projection_proof_present', LOWER(BTRIM(COALESCE(v_existing_auth_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'auth_request_binding_matches', NULLIF(BTRIM(COALESCE(v_existing_auth_intent_json->>'auth_request_id', '')), '') = v_existing_auth_id::text
      );

      IF v_existing_auth_compatible THEN
        EXIT auth_lookup_loop;
      END IF;

      IF v_existing_auth_cross_operation IS NOT TRUE THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_BATCH_AUTH_START',
          'code', 'AUTH_REQUEST_REUSE_PROOF_MISMATCH',
          'message', 'The same-operation or same-idempotency authorisation request is not compatible with the current frozen payment proof.',
          'pay_batch_id', p_pay_batch_id::text,
          'auth_request_id', v_existing_auth_id::text,
          'auth_request_state', v_existing_auth_state,
          'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
          'compatibility', v_existing_auth_compatibility_json
        )::text USING ERRCODE = 'P0001';
      END IF;

      v_conflicting_auth_id := v_existing_auth_id;
      v_conflicting_auth_state := v_existing_auth_state;
      v_conflicting_auth_operation_id := v_existing_auth_operation_id;
      v_conflicting_auth_idempotency_key := v_existing_auth_idempotency_key;
      v_conflicting_auth_intent_json := v_existing_auth_intent_json;
    END IF;

    IF v_conflicting_auth_id IS NULL THEN
      SELECT auth_request.id,
             auth_request.state,
             NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), ''),
             NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'idempotency_key', '')), ''),
             COALESCE(auth_request.execution_intent_json, '{}'::jsonb)
      INTO v_conflicting_auth_id,
           v_conflicting_auth_state,
           v_conflicting_auth_operation_id,
           v_conflicting_auth_idempotency_key,
           v_conflicting_auth_intent_json
      FROM public.pay_batch_auth_requests AS auth_request
      WHERE auth_request.pay_batch_id = p_pay_batch_id
        AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      ORDER BY auth_request.created_at_utc DESC NULLS LAST,
               auth_request.id DESC
      LIMIT 1;
    END IF;

    IF v_conflicting_auth_id IS NULL THEN
      EXIT auth_lookup_loop;
    END IF;

    IF p_operation_id IS NULL
       OR v_execution_mode NOT IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT') THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
        'message', 'An active authorisation request belongs to another execution attempt or is not safely reusable.',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', v_conflicting_auth_id::text,
        'auth_request_state', v_conflicting_auth_state,
        'auth_request_operation_id', v_conflicting_auth_operation_id,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
        'execution_mode', v_execution_mode,
        'compatibility', CASE WHEN v_existing_auth_id = v_conflicting_auth_id THEN v_existing_auth_compatibility_json ELSE NULL::jsonb END
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_stale_auth_failed_checks := '[]'::jsonb;
    v_stale_auth_safety_json := '{}'::jsonb;
    v_old_operation_id := NULL::uuid;
    v_old_operation_found := false;
    v_old_operation_execution_mode_raw := NULL::text;
    v_old_operation_execution_mode := NULL::text;
    v_old_auth_execution_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_conflicting_auth_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_conflicting_auth_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_conflicting_auth_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE NULL::text
    END;
    v_old_auth_scope := UPPER(NULLIF(BTRIM(COALESCE(v_conflicting_auth_intent_json->>'pay_channel_scope', v_conflicting_auth_intent_json->>'scope', '')), ''));
    v_old_operation_reset_terminal := false;
    v_old_operation_manual_reset_marker := false;
    v_old_operation_scope_compatible := false;

    IF COALESCE(v_conflicting_auth_operation_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_old_operation_id := v_conflicting_auth_operation_id::uuid;
      SELECT old_operation.*
      INTO v_old_operation_row
      FROM public.banking_pay_operations AS old_operation
      WHERE old_operation.id = v_old_operation_id
      FOR UPDATE;
      v_old_operation_found := FOUND;
    END IF;

    IF v_old_operation_found THEN
      v_old_operation_execution_mode_raw := UPPER(BTRIM(COALESCE(v_old_operation_row.input_json->>'execution_mode', '')));
      v_old_operation_execution_mode := CASE
        WHEN v_old_operation_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
        WHEN v_old_operation_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
        WHEN v_old_operation_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
        ELSE NULL::text
      END;
      v_old_operation_manual_reset_marker := (
        LOWER(BTRIM(COALESCE(
          v_old_operation_row.progress_json->>'manual_reset_completed',
          v_old_operation_row.progress_json->>'safe_manual_reset_completed',
          v_old_operation_row.result_json->>'manual_reset_completed',
          v_old_operation_row.error_json->>'manual_reset_completed',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND NULLIF(BTRIM(COALESCE(
          v_old_operation_row.progress_json->>'manual_reset_at_utc',
          v_old_operation_row.progress_json->>'safe_manual_reset_at_utc',
          v_old_operation_row.result_json->>'manual_reset_at_utc',
          v_old_operation_row.error_json->>'manual_reset_at_utc',
          ''
        )), '') IS NOT NULL
      );
      v_old_operation_reset_terminal := (
        UPPER(BTRIM(COALESCE(v_old_operation_row.status, ''))) = 'CANCELLED'
        OR (
          UPPER(BTRIM(COALESCE(v_old_operation_row.status, ''))) = 'FAILED'
          AND UPPER(BTRIM(COALESCE(v_old_operation_row.resume_reason, ''))) = 'PAYMENT_EXECUTION_LOCAL_ARTIFACTS_CLEANED'
          AND UPPER(BTRIM(COALESCE(
            v_old_operation_row.error_json->>'cleanup_mode',
            v_old_operation_row.progress_json->>'cleanup_mode',
            v_old_operation_row.result_json->>'cleanup_mode',
            ''
          ))) = 'CLEANED_BOUNDED_LOCAL_ARTIFACTS'
        )
        OR (
          UPPER(BTRIM(COALESCE(v_old_operation_row.status, ''))) IN ('FAILED', 'CANCELLED')
          AND v_old_operation_manual_reset_marker
        )
      );
      v_old_operation_scope_compatible := v_old_operation_row.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(v_old_operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
        AND v_old_operation_execution_mode IS NOT DISTINCT FROM v_execution_mode
        AND v_old_auth_execution_mode IS NOT DISTINCT FROM v_execution_mode
        AND v_old_auth_scope IS NOT DISTINCT FROM v_pay_channel_scope;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_stale_provider_attempt_count
    FROM public.banking_pay_operation_provider_attempts AS provider_attempt
    WHERE provider_attempt.pay_batch_id = p_pay_batch_id
       OR provider_attempt.operation_id = v_old_operation_id;

    SELECT COUNT(*)::integer
    INTO v_stale_transfer_event_count
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE transfer_event.pay_batch_id = p_pay_batch_id;

    SELECT COUNT(*)::integer
    INTO v_stale_scope_provider_evidence_count
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope
    WHERE transfer_scope.pay_batch_id = p_pay_batch_id
      AND (
        COALESCE(transfer_scope.provider_submit_ready, false)
        OR COALESCE(transfer_scope.provider_submit_attempt_count, 0) > 0
        OR transfer_scope.provider_submit_chunk_id IS NOT NULL
        OR transfer_scope.provider_submit_claimed_at_utc IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_idempotency_key, '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_transaction_id, '')), '') IS NOT NULL
        OR transfer_scope.provider_request_prepared_at_utc IS NOT NULL
        OR transfer_scope.provider_request_sending_at_utc IS NOT NULL
        OR transfer_scope.provider_request_sent_at_utc IS NOT NULL
        OR transfer_scope.provider_response_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(transfer_scope.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
        OR UPPER(BTRIM(COALESCE(transfer_scope.status, ''))) = 'SUBMITTED'
      );

    SELECT COUNT(*)::integer
    INTO v_stale_transfer_provider_evidence_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (
        NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        OR transfer_row.completed_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(transfer_row.status, ''))) NOT IN ('PENDING', 'BLOCKED', 'FAILED')
        OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
        OR UPPER(BTRIM(COALESCE(transfer_row.failed_reason, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_LOCAL')
        OR UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json->>'provider_stage', ''))) IN (
          'REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED',
          'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED'
        )
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      );

    SELECT COUNT(*)::integer
    INTO v_stale_provider_chunk_evidence_count
    FROM public.banking_pay_operation_chunks AS provider_chunk
    WHERE provider_chunk.operation_id = v_old_operation_id
      AND (
        UPPER(BTRIM(COALESCE(provider_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
        OR UPPER(BTRIM(COALESCE(provider_chunk.phase, ''))) IN (
          'SUBMIT_PROVIDER_TRANSFERS', 'SEND_PROVIDER_CHUNK', 'REQUEST_PROVIDER_SEND',
          'FINALISE_PROVIDER_CHUNK', 'APPLY_RAIL_UPDATES'
        )
      )
      AND UPPER(BTRIM(COALESCE(provider_chunk.status, ''))) <> 'SKIPPED';

    SELECT COUNT(*)::integer
    INTO v_stale_settlement_scope_count
    FROM public.banking_pay_operation_settlement_scope AS settlement_scope
    WHERE settlement_scope.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(settlement_scope.status, ''))) <> 'SKIPPED'
      AND settlement_scope.operation_id IN (
        SELECT related_operation.id
        FROM public.banking_pay_operations AS related_operation
        WHERE related_operation.id = v_old_operation_id
           OR related_operation.root_operation_id = v_old_operation_id
      );

    SELECT COUNT(*)::integer
    INTO v_stale_remittance_scope_count
    FROM public.banking_pay_operation_remittance_scope AS remittance_scope
    WHERE remittance_scope.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(remittance_scope.status, ''))) <> 'SKIPPED'
      AND remittance_scope.operation_id IN (
        SELECT related_operation.id
        FROM public.banking_pay_operations AS related_operation
        WHERE related_operation.id = v_old_operation_id
           OR related_operation.root_operation_id = v_old_operation_id
      );

    SELECT COUNT(*)::integer
    INTO v_stale_correction_request_count
    FROM public.pay_payment_correction_requests AS correction_request
    WHERE correction_request.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(correction_request.status, ''))) NOT IN ('CANCELLED', 'REJECTED');

    SELECT COUNT(*)::integer
    INTO v_stale_correction_item_count
    FROM public.pay_payment_correction_items AS correction_item
    WHERE correction_item.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(correction_item.status, ''))) IN ('APPLIED', 'BLOCKED', 'FAILED');

    SELECT COUNT(*)::integer
    INTO v_stale_carry_forward_count
    FROM public.pay_manual_adjustment_carry_forwards AS carry_forward
    WHERE (carry_forward.source_pay_batch_id = p_pay_batch_id OR carry_forward.target_pay_batch_id = p_pay_batch_id)
      AND UPPER(BTRIM(COALESCE(carry_forward.status, ''))) NOT IN ('CANCELLED', 'SUPERSEDED');

    SELECT COUNT(*)::integer
    INTO v_stale_advance_patch_count
    FROM public.pay_advance_patches AS advance_patch
    WHERE advance_patch.pay_batch_id = p_pay_batch_id;

    SELECT COUNT(*)::integer
    INTO v_stale_advance_reservation_count
    FROM public.pay_advance_reservations AS advance_reservation
    WHERE advance_reservation.pay_batch_id = p_pay_batch_id
      AND (
        UPPER(BTRIM(COALESCE(advance_reservation.status, ''))) IN ('COMMITTED', 'SETTLED')
        OR advance_reservation.committed_at_utc IS NOT NULL
        OR advance_reservation.settled_at_utc IS NOT NULL
      );

    SELECT COUNT(*)::integer
    INTO v_stale_advance_payout_count
    FROM public.pay_advances AS advance_row
    WHERE advance_row.payout_pay_batch_id = p_pay_batch_id
      AND (
        UPPER(BTRIM(COALESCE(advance_row.payout_status::text, ''))) = 'PAID'
        OR advance_row.payout_transfer_id IS NOT NULL
      );

    SELECT COUNT(*)::integer
    INTO v_stale_other_active_operation_count
    FROM public.banking_pay_operations AS active_operation
    WHERE active_operation.pay_batch_id = p_pay_batch_id
      AND active_operation.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
      AND active_operation.id <> p_operation_id
      AND active_operation.id IS DISTINCT FROM v_old_operation_id
      AND UPPER(BTRIM(COALESCE(active_operation.status, ''))) NOT IN ('COMPLETE', 'FAILED', 'CANCELLED');

    SELECT COUNT(*)::integer
    INTO v_stale_remaining_active_auth_count
    FROM public.pay_batch_auth_requests AS other_auth_request
    WHERE other_auth_request.pay_batch_id = p_pay_batch_id
      AND other_auth_request.id <> v_conflicting_auth_id
      AND other_auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

    IF v_old_operation_id IS NULL THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'OLD_OPERATION_ID_VALID', 'passed', false));
    END IF;
    IF v_old_operation_found IS NOT TRUE THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'OLD_OPERATION_EXISTS', 'passed', false));
    END IF;
    IF v_old_operation_reset_terminal IS NOT TRUE THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'OLD_OPERATION_EXPLICITLY_RESET_TERMINAL', 'passed', false, 'old_operation_status', CASE WHEN v_old_operation_found THEN v_old_operation_row.status ELSE NULL::text END, 'old_operation_resume_reason', CASE WHEN v_old_operation_found THEN v_old_operation_row.resume_reason ELSE NULL::text END));
    END IF;
    IF v_old_operation_scope_compatible IS NOT TRUE THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'BATCH_SCOPE_MODE_COMPATIBLE', 'passed', false, 'old_operation_type', CASE WHEN v_old_operation_found THEN v_old_operation_row.operation_type ELSE NULL::text END, 'old_operation_mode', v_old_operation_execution_mode, 'old_auth_mode', v_old_auth_execution_mode, 'current_mode', v_execution_mode, 'old_auth_scope', v_old_auth_scope, 'current_scope', v_pay_channel_scope));
    END IF;
    IF UPPER(BTRIM(COALESCE(v_batch_row.status, ''))) <> 'DRAFT' THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'BATCH_STATUS_DRAFT', 'passed', false, 'batch_status', v_batch_row.status));
    END IF;
    IF UPPER(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
       OR NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
       OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'EXECUTION_BOUNDARY_NOT_CROSSED', 'passed', false, 'execution_commit_state', v_batch_row.execution_commit_state, 'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL, 'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL));
    END IF;
    IF v_batch_row.settlement_confirmation_json IS NOT NULL
       AND v_batch_row.settlement_confirmation_json <> '{}'::jsonb THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_SETTLEMENT_CONFIRMATION', 'passed', false));
    END IF;
    IF COALESCE(v_stale_provider_attempt_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_PROVIDER_ATTEMPTS', 'passed', false, 'count', v_stale_provider_attempt_count));
    END IF;
    IF COALESCE(v_stale_transfer_event_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_TRANSFER_EVENTS', 'passed', false, 'count', v_stale_transfer_event_count));
    END IF;
    IF COALESCE(v_stale_scope_provider_evidence_count, 0) > 0
       OR COALESCE(v_stale_transfer_provider_evidence_count, 0) > 0
       OR COALESCE(v_stale_provider_chunk_evidence_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_PROVIDER_REQUEST_TRANSACTION_OR_SUBMISSION_EVIDENCE', 'passed', false, 'scope_evidence_count', v_stale_scope_provider_evidence_count, 'transfer_evidence_count', v_stale_transfer_provider_evidence_count, 'provider_chunk_count', v_stale_provider_chunk_evidence_count));
    END IF;
    IF COALESCE(v_stale_settlement_scope_count, 0) > 0 OR COALESCE(v_stale_remittance_scope_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_SETTLEMENT_OR_REMITTANCE_EXECUTION_SCOPE', 'passed', false, 'settlement_scope_count', v_stale_settlement_scope_count, 'remittance_scope_count', v_stale_remittance_scope_count));
    END IF;
    IF COALESCE(v_stale_correction_request_count, 0) > 0
       OR COALESCE(v_stale_correction_item_count, 0) > 0
       OR COALESCE(v_stale_carry_forward_count, 0) > 0
       OR COALESCE(v_stale_advance_patch_count, 0) > 0
       OR COALESCE(v_stale_advance_reservation_count, 0) > 0
       OR COALESCE(v_stale_advance_payout_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_ECONOMIC_CORRECTION_CARRY_FORWARD_OR_ADVANCE_CONSEQUENCE', 'passed', false, 'correction_request_count', v_stale_correction_request_count, 'correction_item_count', v_stale_correction_item_count, 'carry_forward_count', v_stale_carry_forward_count, 'advance_patch_count', v_stale_advance_patch_count, 'advance_reservation_count', v_stale_advance_reservation_count, 'advance_payout_count', v_stale_advance_payout_count));
    END IF;
    IF COALESCE(v_stale_other_active_operation_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_OTHER_ACTIVE_PAYMENT_EXECUTE_OPERATION', 'passed', false, 'count', v_stale_other_active_operation_count));
    END IF;
    IF COALESCE(v_stale_remaining_active_auth_count, 0) > 0 THEN
      v_stale_auth_failed_checks := v_stale_auth_failed_checks || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('check', 'NO_OTHER_ACTIVE_AUTH_REQUEST', 'passed', false, 'count', v_stale_remaining_active_auth_count));
    END IF;

    v_stale_auth_safety_json := JSONB_BUILD_OBJECT(
      'safe_to_cancel', JSONB_ARRAY_LENGTH(v_stale_auth_failed_checks) = 0,
      'failed_checks', v_stale_auth_failed_checks,
      'old_auth_request_id', v_conflicting_auth_id::text,
      'old_operation_id', CASE WHEN v_old_operation_id IS NULL THEN NULL::text ELSE v_old_operation_id::text END,
      'superseding_operation_id', p_operation_id::text,
      'execution_mode', v_execution_mode,
      'pay_channel_scope', v_pay_channel_scope,
      'provider_attempt_count', COALESCE(v_stale_provider_attempt_count, 0),
      'transfer_event_count', COALESCE(v_stale_transfer_event_count, 0),
      'scope_provider_evidence_count', COALESCE(v_stale_scope_provider_evidence_count, 0),
      'transfer_provider_evidence_count', COALESCE(v_stale_transfer_provider_evidence_count, 0),
      'provider_chunk_evidence_count', COALESCE(v_stale_provider_chunk_evidence_count, 0),
      'settlement_scope_count', COALESCE(v_stale_settlement_scope_count, 0),
      'remittance_scope_count', COALESCE(v_stale_remittance_scope_count, 0)
    ) || JSONB_BUILD_OBJECT(
      'correction_request_count', COALESCE(v_stale_correction_request_count, 0),
      'correction_item_count', COALESCE(v_stale_correction_item_count, 0),
      'carry_forward_count', COALESCE(v_stale_carry_forward_count, 0),
      'advance_patch_count', COALESCE(v_stale_advance_patch_count, 0),
      'advance_reservation_count', COALESCE(v_stale_advance_reservation_count, 0),
      'advance_payout_count', COALESCE(v_stale_advance_payout_count, 0),
      'other_active_operation_count', COALESCE(v_stale_other_active_operation_count, 0),
      'other_active_auth_request_count', COALESCE(v_stale_remaining_active_auth_count, 0)
    );

    IF JSONB_ARRAY_LENGTH(v_stale_auth_failed_checks) > 0 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
        'message', 'The previous operation authorisation request could not be cancelled because one or more execution-boundary safety checks failed.',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', v_conflicting_auth_id::text,
        'auth_request_state', v_conflicting_auth_state,
        'auth_request_operation_id', v_conflicting_auth_operation_id,
        'operation_id', p_operation_id::text,
        'safety_reconciliation', v_stale_auth_safety_json
      )::text USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.pay_batch_auth_requests AS stale_auth_update
    SET state = 'CANCELLED',
        finalised_at_utc = COALESCE(stale_auth_update.finalised_at_utc, v_now),
        finalised_by_user_id = COALESCE(stale_auth_update.finalised_by_user_id, p_actor_user_id),
        execution_intent_json = JSONB_STRIP_NULLS(
          COALESCE(stale_auth_update.execution_intent_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'stale_auth_safe_cancelled', true,
            'stale_auth_safe_cancel_reason', 'SUPERSEDED_AFTER_EXPLICIT_OPERATION_RESET_WITH_NO_EXECUTION_BOUNDARY',
            'stale_auth_safe_cancelled_at_utc', v_now::text,
            'stale_auth_safe_cancelled_by_user_id', p_actor_user_id::text,
            'old_operation_id', CASE WHEN v_old_operation_id IS NULL THEN NULL::text ELSE v_old_operation_id::text END,
            'superseding_operation_id', p_operation_id::text,
            'superseding_idempotency_key', v_requested_idempotency_key,
            'stale_auth_safety_reconciliation', v_stale_auth_safety_json
          )
        )
    WHERE stale_auth_update.id = v_conflicting_auth_id
      AND stale_auth_update.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'STALE_AUTH_REQUEST_CANCELLATION_RACE',
        'message', 'The stale authorisation request changed state before safe cancellation could be recorded.',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', v_conflicting_auth_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.pay_batch_auth_tokens AS stale_token_update
    SET used_at_utc = COALESCE(stale_token_update.used_at_utc, v_now),
        expires_at_utc = LEAST(stale_token_update.expires_at_utc, v_now)
    WHERE stale_token_update.auth_request_id = v_conflicting_auth_id
      AND stale_token_update.used_at_utc IS NULL;
    GET DIAGNOSTICS v_stale_auth_tokens_voided = ROW_COUNT;

    IF v_old_operation_found THEN
      UPDATE public.banking_pay_operations AS old_operation_audit
      SET progress_json = JSONB_STRIP_NULLS(
            COALESCE(old_operation_audit.progress_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'stale_auth_request_cancelled', true,
              'stale_auth_request_id', v_conflicting_auth_id::text,
              'stale_auth_request_cancelled_at_utc', v_now::text,
              'superseding_operation_id', p_operation_id::text,
              'stale_auth_safety_reconciliation', v_stale_auth_safety_json
            )
          ),
          updated_at_utc = v_now
      WHERE old_operation_audit.id = v_old_operation_id;
    END IF;

    UPDATE public.banking_pay_operations AS current_operation_audit
    SET progress_json = JSONB_STRIP_NULLS(
          COALESCE(current_operation_audit.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'stale_auth_request_cancelled', true,
            'stale_auth_request_id', v_conflicting_auth_id::text,
            'stale_auth_request_operation_id', CASE WHEN v_old_operation_id IS NULL THEN NULL::text ELSE v_old_operation_id::text END,
            'stale_auth_request_cancelled_at_utc', v_now::text,
            'stale_auth_tokens_voided', COALESCE(v_stale_auth_tokens_voided, 0),
            'stale_auth_safety_reconciliation', v_stale_auth_safety_json
          )
        ),
        updated_at_utc = v_now
    WHERE current_operation_audit.id = p_operation_id;

    v_stale_auth_request_cancelled := true;
    v_stale_auth_cancelled_request_id := v_conflicting_auth_id;
    v_stale_auth_cancelled_operation_id := v_old_operation_id;
    CONTINUE auth_lookup_loop;
  END LOOP auth_lookup_loop;

  IF v_existing_auth_id IS NOT NULL AND v_existing_auth_compatible THEN
    v_auth_state := v_existing_auth_state;
    v_execution_intent_json := v_existing_auth_intent_json;
    v_next_required_phase := CASE
      WHEN v_auth_state = 'AUTHORISED' AND v_scoped_no_transfer_execution_validated AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
      WHEN v_auth_state = 'AUTHORISED' AND v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT') THEN 'SETTLEMENT'
      WHEN v_auth_state = 'AUTHORISED' AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
      WHEN v_auth_state = 'AUTHORISED' THEN 'SUBMIT_PROVIDER_TRANSFERS'
      ELSE 'WAIT_FOR_AUTHORISATION'
    END;

    UPDATE public.pay_batches AS existing_auth_batch_update
    SET execution_intent_json = v_execution_intent_json
    WHERE existing_auth_batch_update.id = p_pay_batch_id;

    IF p_operation_id IS NOT NULL
       AND v_auth_state = 'AWAITING' THEN
      UPDATE public.banking_pay_operations AS operation_wait
      SET status = 'WAITING_AUTHORISATION',
          requires_user_action = true,
          runner_state = 'WAITING_USER',
          resume_reason = 'AWAITING_PAYMENT_AUTHORISATION',
          progress_json = JSONB_STRIP_NULLS(
            COALESCE(operation_wait.progress_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'waiting_authorisation_at_utc', v_now::text,
              'auth_request_id', v_existing_auth_id::text,
              'auth_state', v_auth_state,
              'next_required_phase', 'WAIT_FOR_AUTHORISATION'
            )
          ),
          updated_at_utc = v_now
      WHERE operation_wait.id = p_operation_id;
    END IF;

    RETURN JSONB_BUILD_OBJECT(
      'ok', true,
      'idempotent_reuse', true,
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', v_existing_auth_id::text,
      'auth_state', v_auth_state,
      'state', v_auth_state,
      'active_candidate_count', (
        SELECT pg_catalog.count(*)::integer
        FROM public.pay_batch_candidates AS active_candidate
        WHERE active_candidate.pay_batch_id = p_pay_batch_id
          AND EXISTS (
            SELECT 1
            FROM public.pay_batch_items AS active_item
            WHERE active_item.pay_batch_candidate_id = active_candidate.id
              AND coalesce(active_item.is_voided, false) IS NOT TRUE
          )
      ),
      'active_amount', (
        SELECT coalesce(
          pg_catalog.sum(active_candidate.net_bank_amount),
          0::numeric
        )::numeric(14,2)
        FROM public.pay_batch_candidates AS active_candidate
        WHERE active_candidate.pay_batch_id = p_pay_batch_id
          AND EXISTS (
            SELECT 1
            FROM public.pay_batch_items AS active_item
            WHERE active_item.pay_batch_candidate_id = active_candidate.id
              AND coalesce(active_item.is_voided, false) IS NOT TRUE
          )
      ),
      'active_scope_hash', v_current_active_scope_hash,
      'reauthorisation', EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_requests AS completed_correction
        WHERE completed_correction.pay_batch_id = p_pay_batch_id
          AND completed_correction.status IN (
            'APPLIED', 'APPLIED_WITH_BLOCKERS', 'BLOCKED'
          )
      ),
      'display_message', 'Existing payment authorisation request reopened for the current active scope.',
      'operation_id', v_execution_intent_json->>'operation_id',
      'idempotency_key', v_execution_intent_json->>'idempotency_key',
      'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
      'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
      'next_required_phase', v_next_required_phase,
      'execution_mode', v_execution_mode,
      'schedule_kind', v_kind,
      'auth_request_reuse_reason', CASE
        WHEN p_operation_id IS NOT NULL AND v_existing_auth_operation_id = p_operation_id::text THEN 'SAME_OPERATION'
        ELSE 'SAME_IDEMPOTENCY_KEY'
      END,
      'auth_request_compatibility', v_existing_auth_compatibility_json,
      'stale_auth_request_cancelled', v_stale_auth_request_cancelled,
      'stale_auth_cancelled_request_id', CASE WHEN v_stale_auth_cancelled_request_id IS NULL THEN NULL::text ELSE v_stale_auth_cancelled_request_id::text END,
      'stale_auth_cancelled_operation_id', CASE WHEN v_stale_auth_cancelled_operation_id IS NULL THEN NULL::text ELSE v_stale_auth_cancelled_operation_id::text END,
      'stale_auth_tokens_voided', COALESCE(v_stale_auth_tokens_voided, 0),
      'execution_intent_json', v_execution_intent_json
    );
  END IF;

  UPDATE public.pay_batches AS batch_update
  SET schedule_kind = v_kind,
      scheduled_at_utc = CASE WHEN v_kind = 'SCHEDULED' THEN v_scheduled_at_utc ELSE NULL END,
      scheduled_by_user_id = CASE WHEN v_kind = 'SCHEDULED' THEN p_actor_user_id ELSE NULL END,
      funding_account_ref = v_funding_account_ref,
      funds_warning_hours_json = v_warning_hours_json,
      authoritative_payment_date = v_payment_date,
      authoritative_payment_date_source = 'PAY_BATCH_AUTH_START',
      execution_intent_json = v_execution_intent_json
  WHERE batch_update.id = p_pay_batch_id;

  INSERT INTO public.pay_batch_auth_requests (
    pay_batch_id,
    requested_by_user_id,
    required_quantity,
    schedule_kind,
    scheduled_at_utc,
    funding_account_ref,
    funds_warning_hours_json,
    execution_intent_json,
    state,
    golden_key_used,
    golden_key_user_id,
    created_at_utc
  )
  VALUES (
    p_pay_batch_id,
    p_actor_user_id,
    v_required_quantity,
    v_kind,
    v_scheduled_at_utc,
    v_funding_account_ref,
    v_warning_hours_json,
    v_execution_intent_json,
    'AWAITING',
    false,
    NULL::uuid,
    v_now
  )
  RETURNING id INTO v_auth_id;

  v_execution_intent_json := jsonb_set(v_execution_intent_json, '{auth_request_id}', to_jsonb(v_auth_id::text), true);

  UPDATE public.pay_batch_auth_requests AS auth_request_update
  SET execution_intent_json = v_execution_intent_json
  WHERE auth_request_update.id = v_auth_id;

  UPDATE public.pay_batches AS batch_intent_update
  SET execution_intent_json = v_execution_intent_json
  WHERE batch_intent_update.id = p_pay_batch_id;


  INSERT INTO public.pay_batch_auth_actions (
    auth_request_id,
    pay_batch_id,
    actor_user_id,
    action,
    action_at_utc,
    note
  )
  VALUES (
    v_auth_id,
    p_pay_batch_id,
    p_actor_user_id,
    CASE WHEN v_use_golden_key THEN 'USE_GOLDEN_KEY' ELSE 'AUTHORISE' END,
    v_now,
    NULL::text
  )
  ON CONFLICT (auth_request_id, actor_user_id) DO NOTHING;

  IF v_use_golden_key OR v_required_quantity <= 1 THEN
    UPDATE public.pay_batch_auth_requests AS auth_request_finalise
    SET state = 'AUTHORISED',
        golden_key_used = v_use_golden_key,
        golden_key_user_id = CASE WHEN v_use_golden_key THEN p_actor_user_id ELSE NULL::uuid END,
        finalised_at_utc = v_now,
        finalised_by_user_id = p_actor_user_id,
        execution_intent_json = v_execution_intent_json
    WHERE auth_request_finalise.id = v_auth_id;

    v_auth_state := 'AUTHORISED';
  ELSE
    v_auth_state := 'AWAITING';
  END IF;

  v_next_required_phase := CASE
    WHEN v_auth_state = 'AUTHORISED' AND v_scoped_no_transfer_execution_validated AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
    WHEN v_auth_state = 'AUTHORISED' AND (v_scoped_no_transfer_execution_validated OR v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')) THEN 'SETTLEMENT'
    WHEN v_auth_state = 'AUTHORISED' AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
    WHEN v_auth_state = 'AUTHORISED' THEN 'SUBMIT_PROVIDER_TRANSFERS'
    ELSE 'WAIT_FOR_AUTHORISATION'
  END;

  IF p_operation_id IS NOT NULL
     AND v_auth_state IN ('AWAITING', 'PENDING_AUTHORISATION') THEN
    UPDATE public.banking_pay_operations AS operation_wait
    SET status = 'WAITING_AUTHORISATION',
        requires_user_action = true,
        runner_state = 'WAITING_USER',
        resume_reason = 'AWAITING_PAYMENT_AUTHORISATION',
        progress_json = jsonb_strip_nulls(
          COALESCE(operation_wait.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'waiting_authorisation_at_utc', v_now::text,
            'auth_request_id', CASE WHEN v_auth_id IS NULL THEN NULL ELSE v_auth_id::text END,
            'auth_state', v_auth_state,
            'next_required_phase', 'WAIT_FOR_AUTHORISATION'
          )
        ),
        updated_at_utc = v_now
    WHERE operation_wait.id = p_operation_id;
  END IF;



  RETURN jsonb_build_object(
    'ok', true,
    'idempotent_reuse', false,
    'pay_batch_id', p_pay_batch_id::text,
    'auth_request_id', v_auth_id::text,
    'auth_state', v_auth_state,
    'state', v_auth_state,
    'active_candidate_count', (
      SELECT pg_catalog.count(*)::integer
      FROM public.pay_batch_candidates AS active_candidate
      WHERE active_candidate.pay_batch_id = p_pay_batch_id
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS active_item
          WHERE active_item.pay_batch_candidate_id = active_candidate.id
            AND coalesce(active_item.is_voided, false) IS NOT TRUE
        )
    ),
    'active_amount', (
      SELECT coalesce(
        pg_catalog.sum(active_candidate.net_bank_amount),
        0::numeric
      )::numeric(14,2)
      FROM public.pay_batch_candidates AS active_candidate
      WHERE active_candidate.pay_batch_id = p_pay_batch_id
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS active_item
          WHERE active_item.pay_batch_candidate_id = active_candidate.id
            AND coalesce(active_item.is_voided, false) IS NOT TRUE
        )
    ),
    'active_scope_hash', v_current_active_scope_hash,
    'reauthorisation', EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_requests AS completed_correction
      WHERE completed_correction.pay_batch_id = p_pay_batch_id
        AND completed_correction.status IN (
          'APPLIED', 'APPLIED_WITH_BLOCKERS', 'BLOCKED'
        )
    ),
    'display_message', 'Payment authorisation requested for the current active scope.',
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'idempotency_key', v_requested_idempotency_key,
    'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
    'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
    'next_required_phase', v_next_required_phase,
    'execution_mode', v_execution_mode,
    'schedule_kind', v_kind,
    'scheduled_at_utc', CASE WHEN v_scheduled_at_utc IS NULL THEN NULL ELSE v_scheduled_at_utc::text END,
    'funding_account_ref', v_funding_account_ref,
    'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
    'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
    'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
    'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
    'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
    'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
    'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
    'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
    'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
    'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
    'payment_date', v_payment_date::text,
    'required_quantity', v_required_quantity,
    'auth_start_path', v_auth_start_path,
    'pay_batch_prepare_skipped', v_used_operation_scope_proof,
    'used_operation_scope_proof', v_used_operation_scope_proof
  ) || jsonb_build_object(
    'provider_submit_chunk_risk_count', COALESCE(v_provider_submit_chunk_risk_count, 0),
    'operation_provider_submit_marker_count', COALESCE(v_operation_provider_submit_marker_count, 0),
    'transfer_identity_mismatch_count', COALESCE(v_transfer_identity_mismatch_count, 0),
    'transfer_amount_mismatch_count', COALESCE(v_transfer_amount_mismatch_count, 0),
    'transfer_currency_mismatch_count', COALESCE(v_transfer_currency_mismatch_count, 0),
    'transfer_external_state_count', COALESCE(v_transfer_external_state_count, 0),
    'scope_provider_not_ready_count', COALESCE(v_scope_provider_not_ready_count, 0),
    'scope_prepared_hash_missing_count', COALESCE(v_scope_prepared_hash_missing_count, 0),
    'scope_prepared_amount_mismatch_count', COALESCE(v_scope_prepared_amount_mismatch_count, 0),
    'scope_item_rollup_pending_count', COALESCE(v_scope_item_rollup_pending_count, 0),
    'payout_instruction_missing_count', COALESCE(v_payout_instruction_missing_count, 0),
    'scope_amount_total', ROUND(COALESCE(v_scope_amount_total, 0), 2),
    'transfer_amount_total', ROUND(COALESCE(v_transfer_amount_total, 0), 2),
    'scope_item_amount_total', ROUND(COALESCE(v_scope_item_amount_total, 0), 2),
    'batch_item_amount_total', ROUND(COALESCE(v_batch_item_amount_total, 0), 2),
    'scoped_no_transfer_execution', v_scoped_no_transfer_execution_validated,
    'no_bank_payment_execution', v_no_bank_payment_validated,
    'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_validated,
    'server_owned_payment_projection_proof', true,
    'payment_projection_proof_source', 'PAY_BATCH_AUTH_START',
    'paye_net_state_hash', v_current_paye_net_state_hash,
    'global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'bank_payment_projection_hash', v_current_bank_payment_projection_hash,
    'missing_explicit_paye_input_count', v_global_paye_missing_count,
    'explicit_zero_count', v_global_paye_zero_count,
    'global_positive_bank_payment_count', v_global_positive_bank_payment_count,
    'global_invalid_payment_row_count', v_global_invalid_payment_row_count,
    'scoped_missing_explicit_paye_input_count', v_scoped_paye_missing_count,
    'scoped_explicit_zero_count', v_scoped_explicit_zero_count,
    'positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'positive_bank_payment_total', v_scoped_positive_bank_payment_total,
    'scoped_invalid_payment_row_count', v_scoped_invalid_payment_row_count,
    'bank_csv_evidence', v_csv_evidence_json,
    'waived_no_transfer_blockers', v_prepare_waived_blockers,
    'stale_auth_request_cancelled', v_stale_auth_request_cancelled,
    'stale_auth_cancelled_request_id', CASE WHEN v_stale_auth_cancelled_request_id IS NULL THEN NULL::text ELSE v_stale_auth_cancelled_request_id::text END,
    'stale_auth_cancelled_operation_id', CASE WHEN v_stale_auth_cancelled_operation_id IS NULL THEN NULL::text ELSE v_stale_auth_cancelled_operation_id::text END,
    'stale_auth_tokens_voided', COALESCE(v_stale_auth_tokens_voided, 0),
    'execution_intent_json', v_execution_intent_json
  );
END;
$function$;

-- pay_batch_build_item_breakdowns(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_build_item_breakdowns(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_inserted_count integer := 0;
  v_reused_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'p_operation_id is required for row-backed breakdown creation';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'p_actor_user_id is required for row-backed breakdown creation';
  END IF;

  IF p_candidate_scope_ids IS NULL OR jsonb_typeof(v_scope_ids) <> 'array' OR jsonb_array_length(v_scope_ids) = 0 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array';
  END IF;

  v_scope_id_count := jsonb_array_length(v_scope_ids);

  IF v_scope_id_count > 100 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids exceeds the 100 row cap: %', v_scope_id_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  ) THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must contain UUID strings only';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_breakdown_item_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_breakdown_item_page ON COMMIT DROP AS
  SELECT pay_batch_item.*
  FROM public.pay_batch_items AS pay_batch_item
  JOIN public.pay_batch_candidates AS pay_batch_candidate
    ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
  JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    ON allocation_row.pay_batch_item_id = pay_batch_item.id
   AND allocation_row.operation_id = p_operation_id
  WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
    AND allocation_row.candidate_scope_id IN (
      SELECT (supplied_scope.scope_value #>> '{}')::uuid
      FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    )
    AND COALESCE(pay_batch_item.is_voided, false) = false
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_batch_item_breakdowns AS existing_breakdown
      WHERE existing_breakdown.pay_batch_item_id = pay_batch_item.id
    )
  ORDER BY allocation_row.candidate_scope_id, allocation_row.sort_order, pay_batch_item.id
  LIMIT 100;

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'BUILD_ITEM_BREAKDOWNS','REGISTER',
    jsonb_build_array(
      jsonb_build_object('relation_name','pay_batch_item_breakdowns','operation','INSERT'),
      jsonb_build_object('relation_name','pay_batch_item_breakdowns','operation','UPDATE')
    ),jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  WITH segment_component_wrapper_source AS (
    SELECT
      item_page.*,
      wrapper_entry.component_json AS wrapper_component_json,
      wrapper_entry.component_ordinal::integer AS wrapper_component_ordinal
    FROM pg_temp.tmp_pay_batch_breakdown_item_page AS item_page
    JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(item_page.frozen_resolution_payload_json->'case_components') = 'array'
          THEN item_page.frozen_resolution_payload_json->'case_components'
        ELSE '[]'::jsonb
      END
    ) WITH ORDINALITY AS wrapper_entry(component_json, component_ordinal)
      ON item_page.item_type = 'SEGMENT_DELTA'
  ), segment_component_source AS (
    SELECT
      item_page.*,
      component_entry.component_json,
      component_entry.component_ordinal
    FROM segment_component_wrapper_source AS item_page
    JOIN LATERAL (
      SELECT
        (
          item_page.wrapper_component_json
          || resolution_entry.resolution_json
          || bucket_entry.bucket_json
        ) AS component_json,
        (
          item_page.wrapper_component_ordinal * 1000000
          + resolution_entry.resolution_ordinal * 1000
          + bucket_entry.bucket_ordinal
        )::integer AS component_ordinal
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(item_page.wrapper_component_json->'resolution_rows') = 'array'
            THEN item_page.wrapper_component_json->'resolution_rows'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS resolution_entry(resolution_json, resolution_ordinal)
      JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(resolution_entry.resolution_json#>'{payload_json,bucket_resolutions}') = 'array'
            THEN resolution_entry.resolution_json#>'{payload_json,bucket_resolutions}'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS bucket_entry(bucket_json, bucket_ordinal)
        ON true

      UNION ALL

      SELECT
        item_page.wrapper_component_json AS component_json,
        (item_page.wrapper_component_ordinal * 1000000)::integer AS component_ordinal
      WHERE NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(item_page.wrapper_component_json->'resolution_rows') = 'array'
              THEN item_page.wrapper_component_json->'resolution_rows'
            ELSE '[]'::jsonb
          END
        ) AS fallback_resolution(resolution_json)
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(fallback_resolution.resolution_json#>'{payload_json,bucket_resolutions}') = 'array'
              THEN fallback_resolution.resolution_json#>'{payload_json,bucket_resolutions}'
            ELSE '[]'::jsonb
          END
        ) AS fallback_bucket(bucket_json)
      )
    ) AS component_entry
      ON true
    CROSS JOIN LATERAL (
      SELECT
        UPPER(NULLIF(BTRIM(COALESCE(
          item_page.frozen_component_key_type,
          item_page.frozen_source_basis_json->>'key_type',
          item_page.frozen_source_basis_json#>>'{economic_key,key_type}',
          item_page.frozen_component_snapshot_json->>'component_key_type',
          item_page.frozen_component_snapshot_json#>>'{source_basis_json,component_key_type}',
          item_page.frozen_component_snapshot_json#>>'{source_basis_json,key_type}',
          ''
        )), '')) AS item_economic_key_type,
        NULLIF(BTRIM(COALESCE(
          item_page.frozen_component_key_value,
          item_page.frozen_source_basis_json->>'key_value',
          item_page.frozen_source_basis_json#>>'{economic_key,key_value}',
          item_page.frozen_component_snapshot_json->>'component_key_value',
          item_page.frozen_component_snapshot_json#>>'{source_basis_json,component_key_value}',
          item_page.frozen_component_snapshot_json#>>'{source_basis_json,key_value}',
          ''
        )), '') AS item_economic_key_value,
        LOWER(NULLIF(BTRIM(COALESCE(
          CASE WHEN item_page.timesheet_id IS NULL THEN NULL ELSE item_page.timesheet_id::text END,
          item_page.frozen_source_basis_json->>'timesheet_id',
          item_page.frozen_source_basis_json#>>'{economic_key,timesheet_id}',
          item_page.frozen_component_snapshot_json->>'timesheet_id',
          item_page.frozen_component_snapshot_json#>>'{source_basis_json,timesheet_id}',
          ''
        )), '')) AS item_timesheet_id_text,
        UPPER(NULLIF(BTRIM(COALESCE(
          item_page.frozen_component_snapshot_json->>'bucket_code',
          item_page.frozen_source_basis_json->>'bucket_code',
          ''
        )), '')) AS item_bucket_code
    ) AS item_match
    CROSS JOIN LATERAL (
      SELECT
        UPPER(NULLIF(BTRIM(COALESCE(
          component_entry.component_json->>'component_key_type',
          component_entry.component_json->>'key_type',
          component_entry.component_json#>>'{economic_key,key_type}',
          component_entry.component_json#>>'{source_basis_json,component_key_type}',
          component_entry.component_json#>>'{source_basis_json,key_type}',
          component_entry.component_json#>>'{source_basis_json,economic_key,key_type}',
          ''
        )), '')) AS component_economic_key_type,
        NULLIF(BTRIM(COALESCE(
          component_entry.component_json->>'component_key_value',
          component_entry.component_json->>'key_value',
          component_entry.component_json#>>'{economic_key,key_value}',
          component_entry.component_json#>>'{source_basis_json,component_key_value}',
          component_entry.component_json#>>'{source_basis_json,key_value}',
          component_entry.component_json#>>'{source_basis_json,economic_key,key_value}',
          ''
        )), '') AS component_economic_key_value,
        NULLIF(BTRIM(COALESCE(
          component_entry.component_json#>>'{source_basis_json,work_date}',
          component_entry.component_json->>'work_date',
          component_entry.component_json#>>'{source_basis_json,date}',
          component_entry.component_json->>'date',
          component_entry.component_json->>'source_work_date',
          component_entry.component_json->>'source_basis_work_date',
          ''
        )), '') AS component_work_date_value,
        LOWER(NULLIF(BTRIM(COALESCE(
          component_entry.component_json->>'timesheet_id',
          component_entry.component_json->>'real_business_timesheet_id',
          component_entry.component_json#>>'{economic_key,timesheet_id}',
          component_entry.component_json#>>'{source_basis_json,timesheet_id}',
          component_entry.component_json#>>'{source_basis_json,real_business_timesheet_id}',
          component_entry.component_json#>>'{source_basis_json,economic_key,timesheet_id}',
          ''
        )), '')) AS component_timesheet_id_text,
        UPPER(NULLIF(BTRIM(COALESCE(
          component_entry.component_json->>'bucket_code',
          component_entry.component_json#>>'{source_basis_json,bucket_code}',
          component_entry.component_json->>'label',
          ''
        )), '')) AS component_bucket_code
    ) AS component_match
    WHERE component_entry.component_json IS NOT NULL
      AND jsonb_typeof(component_entry.component_json) = 'object'
      AND (
        NULLIF(BTRIM(COALESCE(component_entry.component_json->>'label', '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(component_entry.component_json->>'bucket_code', component_entry.component_json #>> '{source_basis_json,bucket_code}', '')), '') IS NOT NULL
        OR COALESCE(component_entry.component_json->>'target_units', component_entry.component_json->>'source_units', component_entry.component_json #>> '{source_basis_json,source_units}', component_entry.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
        OR COALESCE(component_entry.component_json->>'target_rate', component_entry.component_json->>'source_rate', component_entry.component_json #>> '{source_basis_json,source_rate}', component_entry.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
        OR COALESCE(component_entry.component_json->>'target_pay_ex_vat', component_entry.component_json->>'target_amount_ex_vat', component_entry.component_json->>'component_amount_ex_vat', component_entry.component_json->>'preview_component_amount_ex_vat', component_entry.component_json->>'ready_preview_amount_ex_vat', component_entry.component_json->>'source_pay_ex_vat', component_entry.component_json->>'source_amount_ex_vat', component_entry.component_json #>> '{source_basis_json,source_pay_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      )
      AND (
        (
          item_match.item_economic_key_type = 'TS_DAY'
          AND item_match.item_economic_key_value IS NOT NULL
          AND (
            component_match.component_economic_key_type = 'TS_DAY'
            OR component_match.component_economic_key_type IS NULL
          )
          AND (
            component_match.component_work_date_value = item_match.item_economic_key_value
            OR component_match.component_economic_key_value = item_match.item_economic_key_value
          )
          AND (
            component_match.component_timesheet_id_text IS NULL
            OR (
              item_match.item_timesheet_id_text IS NOT NULL
              AND component_match.component_timesheet_id_text = item_match.item_timesheet_id_text
            )
          )
        )
        OR (
          item_match.item_economic_key_type IS NOT NULL
          AND item_match.item_economic_key_type <> 'TS_DAY'
          AND item_match.item_economic_key_value IS NOT NULL
          AND component_match.component_economic_key_type = item_match.item_economic_key_type
          AND component_match.component_economic_key_value = item_match.item_economic_key_value
          AND (
            component_match.component_timesheet_id_text IS NULL
            OR (
              item_match.item_timesheet_id_text IS NOT NULL
              AND component_match.component_timesheet_id_text = item_match.item_timesheet_id_text
            )
          )
        )
      )
      AND (
        item_match.item_bucket_code IS NULL
        OR component_match.component_bucket_code = item_match.item_bucket_code
      )
      AND NOT (
        NULLIF(BTRIM(COALESCE(component_entry.component_json->>'resolved_rate_resolution_id', '')), '') IS NULL
        AND UPPER(BTRIM(COALESCE(component_entry.component_json->>'resolution_state', ''))) = 'FIXED'
        AND LOWER(BTRIM(COALESCE(component_entry.component_json->>'is_actionable_resolution_row', 'false')))
              IN ('false','f','0','no','n','off')
        AND COALESCE(component_entry.component_json->>'source_pay_ex_vat', '') ~ '^-[0-9]+(\.[0-9]+)?$'
        AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(item_page.frozen_resolution_payload_json->'case_components') = 'array'
                THEN item_page.frozen_resolution_payload_json->'case_components'
              ELSE '[]'::jsonb
            END
          ) AS explicit_resolved_component(component_json)
          WHERE UPPER(BTRIM(COALESCE(explicit_resolved_component.component_json->>'component_key_type', ''))) = item_match.item_economic_key_type
            AND BTRIM(COALESCE(explicit_resolved_component.component_json->>'component_key_value', '')) = item_match.item_economic_key_value
            AND NULLIF(BTRIM(COALESCE(explicit_resolved_component.component_json->>'resolved_rate_resolution_id', '')), '') IS NOT NULL
        )
      )
  ), segment_component_derived AS (
    SELECT
      segment_component_source.*,
      NULLIF(UPPER(BTRIM(COALESCE(
        segment_component_source.component_json->>'bucket_code',
        segment_component_source.component_json #>> '{source_basis_json,bucket_code}',
        segment_component_source.component_json->>'label',
        ''
      ))), '') AS derived_bucket_code,
      COALESCE(
        NULLIF(BTRIM(segment_component_source.component_json->>'label'), ''),
        NULLIF(UPPER(BTRIM(segment_component_source.component_json->>'bucket_code')), ''),
        NULLIF(UPPER(BTRIM(segment_component_source.component_json #>> '{source_basis_json,bucket_code}')), ''),
        NULLIF(BTRIM(segment_component_source.frozen_component_snapshot_json->>'label'), ''),
        NULLIF(BTRIM(segment_component_source.description), ''),
        segment_component_source.item_type
      ) AS derived_unit_name,
      NULLIF(BTRIM(COALESCE(
        segment_component_source.component_json->>'target_units',
        segment_component_source.component_json->>'source_units',
        segment_component_source.component_json #>> '{source_basis_json,source_units}',
        segment_component_source.component_json #>> '{source_basis_json,units}',
        segment_component_source.frozen_component_snapshot_json->>'target_units',
        segment_component_source.frozen_source_basis_json->>'units',
        ''
      )), '') AS derived_units_text,
      NULLIF(BTRIM(COALESCE(
        segment_component_source.component_json->>'target_rate',
        segment_component_source.component_json->>'source_rate',
        segment_component_source.component_json #>> '{source_basis_json,source_rate}',
        segment_component_source.component_json #>> '{source_basis_json,rate}',
        segment_component_source.frozen_component_snapshot_json->>'target_rate',
        segment_component_source.frozen_source_basis_json->>'rate',
        ''
      )), '') AS derived_rate_text,
      NULLIF(BTRIM(COALESCE(
        segment_component_source.component_json->>'target_pay_ex_vat',
        segment_component_source.component_json->>'target_amount_ex_vat',
        segment_component_source.component_json->>'component_amount_ex_vat',
        segment_component_source.component_json->>'preview_component_amount_ex_vat',
        segment_component_source.component_json->>'ready_preview_amount_ex_vat',
        segment_component_source.component_json->>'source_pay_ex_vat',
        segment_component_source.component_json->>'source_amount_ex_vat',
        segment_component_source.component_json #>> '{source_basis_json,source_pay_ex_vat}',
        ''
      )), '') AS derived_amount_text
    FROM segment_component_source
  ), segment_component_amounts AS (
    SELECT
      segment_component_derived.*,
      CASE WHEN segment_component_derived.derived_units_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN segment_component_derived.derived_units_text::numeric ELSE NULL::numeric END AS derived_units,
      CASE WHEN segment_component_derived.derived_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN segment_component_derived.derived_rate_text::numeric ELSE NULL::numeric END AS derived_rate,
      CASE
        WHEN segment_component_derived.derived_amount_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN segment_component_derived.derived_amount_text::numeric
        WHEN segment_component_derived.derived_units_text ~ '^-?[0-9]+(\.[0-9]+)?$'
         AND segment_component_derived.derived_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN segment_component_derived.derived_units_text::numeric * segment_component_derived.derived_rate_text::numeric
        ELSE 0::numeric
      END AS derived_amount_ex_vat,
      ROUND(COALESCE(segment_component_derived.frozen_target_amount_vat, segment_component_derived.amount_vat, 0), 2) AS item_total_vat
    FROM segment_component_derived
  ), segment_component_prorated AS (
    SELECT
      segment_component_amounts.*,
      COUNT(*) OVER (PARTITION BY segment_component_amounts.id) AS component_count,
      ROW_NUMBER() OVER (PARTITION BY segment_component_amounts.id ORDER BY segment_component_amounts.component_ordinal, segment_component_amounts.id) AS component_position,
      SUM(ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)) OVER (PARTITION BY segment_component_amounts.id) AS component_total_ex_vat,
      ROUND(COALESCE(
        segment_component_amounts.frozen_target_amount_ex_vat,
        segment_component_amounts.amount_ex_vat,
        0
      ), 2) AS item_total_ex_vat,
      ROUND(
        CASE
          WHEN SUM(ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)) OVER (PARTITION BY segment_component_amounts.id) <> 0 THEN
            COALESCE(
              segment_component_amounts.frozen_target_amount_ex_vat,
              segment_component_amounts.amount_ex_vat,
              0
            )
            * ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)
            / NULLIF(SUM(ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)) OVER (PARTITION BY segment_component_amounts.id), 0)
          WHEN COUNT(*) OVER (PARTITION BY segment_component_amounts.id) > 0 THEN
            COALESCE(
              segment_component_amounts.frozen_target_amount_ex_vat,
              segment_component_amounts.amount_ex_vat,
              0
            ) / NULLIF(COUNT(*) OVER (PARTITION BY segment_component_amounts.id), 0)
          ELSE 0
        END,
        2
      ) AS provisional_component_ex_vat,
      ROUND(
        CASE
          WHEN SUM(ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)) OVER (PARTITION BY segment_component_amounts.id) <> 0 THEN
            COALESCE(segment_component_amounts.item_total_vat, 0)
            * ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)
            / NULLIF(SUM(ROUND(COALESCE(segment_component_amounts.derived_amount_ex_vat, 0), 2)) OVER (PARTITION BY segment_component_amounts.id), 0)
          WHEN COUNT(*) OVER (PARTITION BY segment_component_amounts.id) > 0 THEN
            COALESCE(segment_component_amounts.item_total_vat, 0) / NULLIF(COUNT(*) OVER (PARTITION BY segment_component_amounts.id), 0)
          ELSE 0
        END,
        2
      ) AS provisional_component_vat
    FROM segment_component_amounts
  ), segment_component_allocated AS (
    SELECT
      segment_component_prorated.*,
      CASE
        WHEN segment_component_prorated.component_position = segment_component_prorated.component_count THEN
          ROUND(
            COALESCE(segment_component_prorated.item_total_ex_vat, 0)
            - COALESCE(
                SUM(segment_component_prorated.provisional_component_ex_vat) OVER (
                  PARTITION BY segment_component_prorated.id
                  ORDER BY segment_component_prorated.component_ordinal, segment_component_prorated.id
                  ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                ),
                0
              ),
            2
          )
        ELSE segment_component_prorated.provisional_component_ex_vat
      END AS allocated_amount_ex_vat,
      CASE
        WHEN segment_component_prorated.component_position = segment_component_prorated.component_count THEN
          ROUND(
            COALESCE(segment_component_prorated.item_total_vat, 0)
            - COALESCE(
                SUM(segment_component_prorated.provisional_component_vat) OVER (
                  PARTITION BY segment_component_prorated.id
                  ORDER BY segment_component_prorated.component_ordinal, segment_component_prorated.id
                  ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                ),
                0
              ),
            2
          )
        ELSE segment_component_prorated.provisional_component_vat
      END AS derived_amount_vat
    FROM segment_component_prorated
  ), component_breakdown_rows AS (
    SELECT
      segment_component_allocated.id AS pay_batch_item_id,
      'TS_BUCKET'::text AS line_kind,
      segment_component_allocated.derived_bucket_code AS bucket_code,
      segment_component_allocated.derived_unit_name AS unit_name,
      segment_component_allocated.derived_units AS units,
      segment_component_allocated.derived_rate AS rate,
      ROUND(COALESCE(segment_component_allocated.allocated_amount_ex_vat, 0), 2) AS amount_ex_vat,
      ROUND(COALESCE(segment_component_allocated.derived_amount_vat, 0), 2) AS amount_vat,
      ROUND(COALESCE(segment_component_allocated.allocated_amount_ex_vat, 0) + COALESCE(segment_component_allocated.derived_amount_vat, 0), 2) AS amount_inc_vat,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_case_id', CASE WHEN segment_component_allocated.finance_case_id IS NULL THEN NULL ELSE segment_component_allocated.finance_case_id::text END,
          'finance_component_id', CASE WHEN segment_component_allocated.finance_component_id IS NULL THEN NULL ELSE segment_component_allocated.finance_component_id::text END,
          'component_key_type', segment_component_allocated.frozen_component_key_type,
          'component_key_value', segment_component_allocated.frozen_component_key_value,
          'economic_key_type', segment_component_allocated.frozen_component_key_type,
          'economic_key_value', segment_component_allocated.frozen_component_key_value,
          'source_basis_json', segment_component_allocated.frozen_source_basis_json,
          'frozen_component_snapshot_json', segment_component_allocated.frozen_component_snapshot_json,
          'case_component_json', segment_component_allocated.component_json,
          'case_component_ordinal', segment_component_allocated.component_ordinal,
          'source_reservation_amount_ex_vat', public._pay_batch_item_source_reservation_amount_ex_vat(segment_component_allocated.id),
          'target_amount_ex_vat', ROUND(COALESCE(segment_component_allocated.allocated_amount_ex_vat, 0), 2),
          'full_resolved_target_amount_ex_vat', ROUND(COALESCE(segment_component_allocated.derived_amount_ex_vat, 0), 2),
          'resolution_mode', CASE WHEN segment_component_allocated.frozen_resolution_mode IS NULL THEN NULL ELSE segment_component_allocated.frozen_resolution_mode::text END,
          'resolution_payload_json', segment_component_allocated.frozen_resolution_payload_json,
          'resolution_result_json', segment_component_allocated.frozen_resolution_result_json
        )
      ) AS meta_json,
      p_operation_id::text || ':breakdown:' || segment_component_allocated.id::text || ':component:' || segment_component_allocated.component_ordinal::text AS operation_source_key
    FROM segment_component_allocated
  ), fallback_breakdown_rows AS (
    SELECT
      item_page.id AS pay_batch_item_id,
      CASE
        WHEN item_page.item_type = 'SEGMENT_DELTA' THEN 'TS_BUCKET'
        WHEN item_page.item_type = 'MILEAGE_DELTA' THEN 'MILEAGE'
        WHEN item_page.item_type = 'ADJUSTMENT_DELTA' THEN 'ADJUSTMENT'
        WHEN item_page.item_type IN (
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'MANUAL_DEBT_RECOVERY',
          'MANUAL_CREDIT_PAYOUT',
          'LOAN_PAYOUT',
          'UNDERPAYMENT_PAYMENT',
          'DEBT_CREATED'
        ) THEN item_page.item_type
        ELSE 'EXPENSE'
      END AS line_kind,
      NULLIF(UPPER(BTRIM(COALESCE(item_page.frozen_component_snapshot_json->>'bucket_code', item_page.frozen_source_basis_json->>'bucket_code', ''))), '') AS bucket_code,
      COALESCE(NULLIF(BTRIM(item_page.frozen_component_snapshot_json->>'label'), ''), NULLIF(BTRIM(item_page.description), ''), item_page.item_type) AS unit_name,
      CASE WHEN COALESCE(item_page.frozen_component_snapshot_json->>'target_units', item_page.frozen_source_basis_json->>'units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN COALESCE(item_page.frozen_component_snapshot_json->>'target_units', item_page.frozen_source_basis_json->>'units')::numeric ELSE NULL::numeric END AS units,
      CASE WHEN COALESCE(item_page.frozen_component_snapshot_json->>'target_rate', item_page.frozen_source_basis_json->>'rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN COALESCE(item_page.frozen_component_snapshot_json->>'target_rate', item_page.frozen_source_basis_json->>'rate')::numeric ELSE NULL::numeric END AS rate,
      ROUND(COALESCE(item_page.frozen_target_amount_ex_vat, item_page.amount_ex_vat, 0), 2) AS amount_ex_vat,
      ROUND(COALESCE(item_page.frozen_target_amount_vat, item_page.amount_vat, 0), 2) AS amount_vat,
      ROUND(COALESCE(item_page.frozen_target_amount_inc_vat, item_page.amount_inc_vat, 0), 2) AS amount_inc_vat,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_case_id', CASE WHEN item_page.finance_case_id IS NULL THEN NULL ELSE item_page.finance_case_id::text END,
          'finance_component_id', CASE WHEN item_page.finance_component_id IS NULL THEN NULL ELSE item_page.finance_component_id::text END,
          'component_key_type', item_page.frozen_component_key_type,
          'component_key_value', item_page.frozen_component_key_value,
          'economic_key_type', item_page.frozen_component_key_type,
          'economic_key_value', item_page.frozen_component_key_value,
          'source_basis_json', item_page.frozen_source_basis_json,
          'frozen_component_snapshot_json', item_page.frozen_component_snapshot_json,
          'source_reservation_amount_ex_vat', public._pay_batch_item_source_reservation_amount_ex_vat(item_page.id),
          'target_amount_ex_vat', COALESCE(item_page.frozen_target_amount_ex_vat, item_page.amount_ex_vat),
          'resolution_mode', CASE WHEN item_page.frozen_resolution_mode IS NULL THEN NULL ELSE item_page.frozen_resolution_mode::text END,
          'resolution_payload_json', item_page.frozen_resolution_payload_json,
          'resolution_result_json', item_page.frozen_resolution_result_json
        )
      ) AS meta_json,
      p_operation_id::text || ':breakdown:' || item_page.id::text AS operation_source_key
    FROM pg_temp.tmp_pay_batch_breakdown_item_page AS item_page
    WHERE item_page.item_type <> 'SEGMENT_DELTA'
       OR NOT EXISTS (
         SELECT 1
         FROM segment_component_source AS existing_component
         WHERE existing_component.id = item_page.id
       )
  ), breakdown_rows AS (
    SELECT * FROM component_breakdown_rows
    UNION ALL
    SELECT * FROM fallback_breakdown_rows
  ), inserted_breakdowns AS (
    INSERT INTO public.pay_batch_item_breakdowns(
      pay_batch_item_id,
      line_kind,
      bucket_code,
      unit_name,
      units,
      rate,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      meta_json,
      operation_source_key
    )
    SELECT
      breakdown_rows.pay_batch_item_id,
      breakdown_rows.line_kind,
      breakdown_rows.bucket_code,
      breakdown_rows.unit_name,
      breakdown_rows.units,
      breakdown_rows.rate,
      breakdown_rows.amount_ex_vat,
      breakdown_rows.amount_vat,
      breakdown_rows.amount_inc_vat,
      breakdown_rows.meta_json,
      breakdown_rows.operation_source_key
    FROM breakdown_rows
    ON CONFLICT (pay_batch_item_id, operation_source_key) WHERE operation_source_key IS NOT NULL DO NOTHING
    RETURNING public.pay_batch_item_breakdowns.id
  )
  SELECT COUNT(*)::integer INTO v_inserted_count FROM inserted_breakdowns;

  SELECT COUNT(*)::integer
  INTO v_reused_count
  FROM public.pay_batch_item_breakdowns AS existing_breakdown
  JOIN pg_temp.tmp_pay_batch_breakdown_item_page AS item_page
    ON item_page.id = existing_breakdown.pay_batch_item_id;

  v_reused_count := GREATEST(COALESCE(v_reused_count, 0) - COALESCE(v_inserted_count, 0), 0);

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'BUILD_ITEM_BREAKDOWNS','ASSERT_COMPLETE','[]'::jsonb,
    jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'candidate_scope_count', v_scope_id_count,
    'inserted_count', COALESCE(v_inserted_count, 0),
    'reused_count', COALESCE(v_reused_count, 0),
    'failed_count', 0,
    'inserted_breakdown_rows', COALESCE(v_inserted_count, 0),
    'has_more', EXISTS (
      SELECT 1
      FROM public.pay_batch_items AS remaining_item
      JOIN public.pay_batch_candidates AS remaining_candidate
        ON remaining_candidate.id = remaining_item.pay_batch_candidate_id
      JOIN public.banking_pay_operation_candidate_allocation_rows AS remaining_allocation
        ON remaining_allocation.pay_batch_item_id = remaining_item.id
       AND remaining_allocation.operation_id = p_operation_id
      WHERE remaining_candidate.pay_batch_id = p_pay_batch_id
        AND remaining_allocation.candidate_scope_id IN (
          SELECT (supplied_scope.scope_value #>> '{}')::uuid
          FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
        )
        AND COALESCE(remaining_item.is_voided, false) = false
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_item_breakdowns AS remaining_breakdown
          WHERE remaining_breakdown.pay_batch_item_id = remaining_item.id
        )
    )
  );
END;
$function$;

-- pay_batch_cancel(uuid,uuid,text,uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_cancel(p_pay_batch_id uuid, p_actor_user_id uuid, p_reason text, p_correction_request_id uuid DEFAULT NULL::uuid, p_work_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_batch public.pay_batches%rowtype;
  v_result jsonb := '{}'::jsonb;
  v_active_candidate_count integer := 0;
  v_active_item_count integer := 0;
  v_enabled boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_CANCEL_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANCEL_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_CANCEL_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANCEL_ACTOR_REQUIRED')::text;
  END IF;

  IF p_work_item_id IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_CANCEL_LEGACY_WORK_ITEM_CALL_RETIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANCEL_LEGACY_WORK_ITEM_CALL_RETIRED')::text;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_candidate_cancellation_enabled, false)
  INTO v_enabled
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  IF v_enabled IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_FEATURE_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAYMENT_CORRECTION_FEATURE_DISABLED')::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_CANCEL_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANCEL_BATCH_NOT_FOUND')::text;
  END IF;

  IF upper(btrim(COALESCE(v_batch.status, ''))) <> 'DRAFT' THEN
    RAISE EXCEPTION 'PAY_BATCH_CANCEL_BATCH_NOT_DRAFT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANCEL_BATCH_NOT_DRAFT')::text;
  END IF;

  SELECT
    count(DISTINCT candidates.id)::integer,
    count(items.id)::integer
  INTO v_active_candidate_count, v_active_item_count
  FROM public.pay_batch_candidates AS candidates
  JOIN public.pay_batch_items AS items
    ON items.pay_batch_candidate_id = candidates.id
   AND COALESCE(items.is_voided, false) = false
  WHERE candidates.pay_batch_id = p_pay_batch_id;

  IF v_active_candidate_count = 0 OR v_active_item_count = 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_CANCEL_NO_ACTIVE_PAYMENTS'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANCEL_NO_ACTIVE_PAYMENTS')::text;
  END IF;

  v_result := public.pay_payment_correction_request_start(
    p_pay_batch_id => p_pay_batch_id,
    p_selection_json => jsonb_build_object(
      'command', 'PREPARE',
      'contract_version', 1,
      'scope_type', 'BATCH',
      'mode', 'ALL_MATCHING',
      'requested_action', 'DRAFT_CANCEL',
      'filter', '{}'::jsonb,
      'exclusions', '[]'::jsonb,
      'correction_request_id', p_correction_request_id,
      'source_context', 'pay_batch_cancel'
    ),
    p_reason => 'DRAFT_PAYMENT_CANCELLED_BY_USER',
    p_actor_user_id => p_actor_user_id,
    p_source_bank_event_id => NULL::uuid,
    p_auto_requested => false,
    p_accepted_resolution_json => NULL::jsonb
  );

  RETURN COALESCE(v_result, '{}'::jsonb) || jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id,
    'correction_request_id', NULLIF(v_result->>'correction_request_id', '')::uuid,
    'operation_id', NULLIF(v_result->>'operation_id', '')::uuid,
    'request_status', COALESCE(v_result->>'request_status', 'PLANNING'),
    'operation_status', COALESCE(v_result->>'operation_status', 'RUNNING'),
    'phase', COALESCE(v_result->>'phase', 'PREPARE_SELECTION'),
    'continuation', v_result->'continuation',
    'status_url', '/api/banking/pay/correction/' || COALESCE(v_result->>'correction_request_id', '') || '/status',
    'display_message', 'Draft cancellation is being prepared.'
  );
END;
$function$;

-- pay_batch_create_timesheet_snapshots(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_create_timesheet_snapshots(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_inserted_count integer := 0;
  v_updated_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'p_operation_id is required for row-backed timesheet snapshot creation';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'p_actor_user_id is required for row-backed timesheet snapshot creation';
  END IF;

  IF p_candidate_scope_ids IS NULL OR jsonb_typeof(v_scope_ids) <> 'array' OR jsonb_array_length(v_scope_ids) = 0 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array';
  END IF;

  v_scope_id_count := jsonb_array_length(v_scope_ids);

  IF v_scope_id_count > 100 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids exceeds the 100 row cap: %', v_scope_id_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  ) THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must contain UUID strings only';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_snapshot_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_snapshot_page ON COMMIT DROP AS
  WITH scoped_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      pay_batch_item.timesheet_id,
      pay_batch_item.pay_channel,
      pay_batch_item.frozen_component_snapshot_json,
      pay_batch_item.frozen_source_basis_json,
      pay_batch_item.frozen_component_key_type,
      pay_batch_item.frozen_component_key_value,
      pay_batch_item.frozen_target_amount_ex_vat,
      pay_batch_item.frozen_target_amount_vat,
      pay_batch_item.frozen_target_amount_inc_vat,
      pay_batch_candidate.candidate_id,
      allocation_row.allocation_basis_json
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      ON allocation_row.pay_batch_item_id = pay_batch_item.id
     AND allocation_row.operation_id = p_operation_id
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND allocation_row.candidate_scope_id IN (
        SELECT (supplied_scope.scope_value #>> '{}')::uuid
        FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
      )
      AND pay_batch_item.timesheet_id IS NOT NULL
      AND COALESCE(pay_batch_item.is_voided, false) = false
  ), touched_timesheets AS (
    SELECT DISTINCT scoped_items.timesheet_id, scoped_items.candidate_id, scoped_items.pay_channel
    FROM scoped_items
    ORDER BY scoped_items.timesheet_id, scoped_items.pay_channel
    LIMIT 100
  )
  SELECT touched_timesheets.*
  FROM touched_timesheets
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.pay_batch_timesheet_snapshots AS existing_snapshot
    WHERE existing_snapshot.pay_batch_id = p_pay_batch_id
      AND existing_snapshot.timesheet_id = touched_timesheets.timesheet_id
      AND existing_snapshot.pay_channel = touched_timesheets.pay_channel
  );

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'CREATE_TIMESHEET_SNAPSHOTS','REGISTER',
    jsonb_build_array(
      jsonb_build_object('relation_name','pay_batch_timesheet_snapshots','operation','INSERT'),
      jsonb_build_object('relation_name','pay_batch_timesheet_snapshots','operation','UPDATE')
    ),jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  WITH snapshot_rows AS (
    SELECT
      snapshot_page.timesheet_id,
      snapshot_page.candidate_id,
      snapshot_page.pay_channel,
      COALESCE(display_source.base_snapshot_json, '{}'::jsonb) AS base_snapshot_json,
      (
        jsonb_strip_nulls(
          jsonb_build_object(
            'source', 'pay_batch_items_frozen_artifacts',
            'timesheet_id', snapshot_page.timesheet_id::text,
            'candidate_id', snapshot_page.candidate_id::text,
            'pay_channel', snapshot_page.pay_channel,
            'resolved_components', COALESCE((
              SELECT jsonb_agg(
                jsonb_strip_nulls(
                  jsonb_build_object(
                    'pay_batch_item_id', component_item.id::text,
                    'component_key_type', component_item.frozen_component_key_type,
                    'component_key_value', component_item.frozen_component_key_value,
                    'frozen_component_snapshot_json', component_item.frozen_component_snapshot_json,
                    'frozen_source_basis_json', component_item.frozen_source_basis_json,
                    'frozen_target_amount_ex_vat', component_item.frozen_target_amount_ex_vat,
                    'frozen_target_amount_vat', component_item.frozen_target_amount_vat,
                    'frozen_target_amount_inc_vat', component_item.frozen_target_amount_inc_vat
                  )
                )
                ORDER BY component_item.id
              )
              FROM public.pay_batch_items AS component_item
              JOIN public.pay_batch_candidates AS component_candidate
                ON component_candidate.id = component_item.pay_batch_candidate_id
              WHERE component_candidate.pay_batch_id = p_pay_batch_id
                AND component_item.timesheet_id = snapshot_page.timesheet_id
                AND component_item.pay_channel = snapshot_page.pay_channel
                AND COALESCE(component_item.is_voided, false) = false
            ), '[]'::jsonb)
          )
        )
        || COALESCE(display_source.display_metadata_json, '{}'::jsonb)
      ) AS target_snapshot_json
    FROM pg_temp.tmp_pay_batch_snapshot_page AS snapshot_page
    LEFT JOIN LATERAL (
      WITH source_material AS (
        SELECT
          source_allocation.allocation_basis_json -> 'line' AS allocation_line_json,
          source_allocation.allocation_basis_json #> '{line,target_snapshot_json}' AS allocation_target_json,
          source_allocation.allocation_basis_json #> '{line,base_snapshot_json}' AS allocation_base_json,
          source_batch_item.frozen_source_basis_json AS frozen_source_basis_json,
          source_batch_item.frozen_component_snapshot_json AS frozen_component_snapshot_json
        FROM public.banking_pay_operation_candidate_allocation_rows AS source_allocation
        JOIN public.pay_batch_items AS source_batch_item
          ON source_batch_item.id = source_allocation.pay_batch_item_id
        WHERE source_allocation.operation_id = p_operation_id
          AND source_batch_item.timesheet_id = snapshot_page.timesheet_id
          AND source_batch_item.pay_channel = snapshot_page.pay_channel
          AND COALESCE(source_batch_item.is_voided, false) = false
        ORDER BY source_allocation.sort_order, source_allocation.id
        LIMIT 1
      )
      SELECT
        COALESCE(
          CASE WHEN jsonb_typeof(source_material.allocation_base_json) = 'object' THEN source_material.allocation_base_json ELSE NULL::jsonb END,
          '{}'::jsonb
        ) AS base_snapshot_json,
        jsonb_strip_nulls(
          jsonb_build_object(
            'client_name', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'client_name',
              source_material.allocation_target_json #>> '{client,name}',
              source_material.allocation_line_json ->> 'client_name',
              source_material.allocation_line_json #>> '{client,name}',
              source_material.allocation_base_json ->> 'client_name',
              source_material.allocation_base_json #>> '{client,name}',
              source_material.frozen_source_basis_json ->> 'client_name',
              source_material.frozen_source_basis_json #>> '{client,name}',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,client_name}',
              source_material.frozen_component_snapshot_json ->> 'client_name',
              ''
            )), ''),
            'client_id', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'client_id',
              source_material.allocation_target_json #>> '{client,id}',
              source_material.allocation_line_json ->> 'client_id',
              source_material.allocation_line_json #>> '{client,id}',
              source_material.allocation_base_json ->> 'client_id',
              source_material.allocation_base_json #>> '{client,id}',
              source_material.frozen_source_basis_json ->> 'client_id',
              source_material.frozen_source_basis_json #>> '{client,id}',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,client_id}',
              source_material.frozen_component_snapshot_json ->> 'client_id',
              ''
            )), ''),
            'week_ending_date', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'week_ending_date',
              source_material.allocation_target_json ->> 'week_ending',
              source_material.allocation_line_json ->> 'week_ending_date',
              source_material.allocation_line_json ->> 'week_ending',
              source_material.allocation_base_json ->> 'week_ending_date',
              source_material.allocation_base_json ->> 'week_ending',
              source_material.frozen_source_basis_json ->> 'week_ending_date',
              source_material.frozen_source_basis_json ->> 'week_ending',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,week_ending_date}',
              source_material.frozen_component_snapshot_json ->> 'week_ending_date',
              ''
            )), ''),
            'job_title', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'job_title',
              source_material.allocation_target_json ->> 'jobTitle',
              source_material.allocation_line_json ->> 'job_title',
              source_material.allocation_line_json ->> 'jobTitle',
              source_material.allocation_base_json ->> 'job_title',
              source_material.frozen_source_basis_json ->> 'job_title',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,job_title}',
              source_material.frozen_component_snapshot_json ->> 'job_title',
              ''
            )), ''),
            'band', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'band',
              source_material.allocation_line_json ->> 'band',
              source_material.allocation_base_json ->> 'band',
              source_material.frozen_source_basis_json ->> 'band',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,band}',
              source_material.frozen_component_snapshot_json ->> 'band',
              ''
            )), ''),
            'grade', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'grade',
              source_material.allocation_line_json ->> 'grade',
              source_material.allocation_base_json ->> 'grade',
              source_material.frozen_source_basis_json ->> 'grade',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,grade}',
              source_material.frozen_component_snapshot_json ->> 'grade',
              ''
            )), ''),
            'reference_number', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'reference_number',
              source_material.allocation_target_json ->> 'timesheet_reference',
              source_material.allocation_line_json ->> 'reference_number',
              source_material.allocation_line_json ->> 'timesheet_reference',
              source_material.allocation_base_json ->> 'reference_number',
              source_material.allocation_base_json ->> 'timesheet_reference',
              source_material.frozen_source_basis_json ->> 'reference_number',
              source_material.frozen_source_basis_json ->> 'timesheet_reference',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,reference_number}',
              source_material.frozen_component_snapshot_json ->> 'reference_number',
              ''
            )), ''),
            'timesheet_type', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'timesheet_type',
              source_material.allocation_line_json ->> 'timesheet_type',
              source_material.allocation_base_json ->> 'timesheet_type',
              source_material.frozen_source_basis_json ->> 'timesheet_type',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,timesheet_type}',
              source_material.frozen_component_snapshot_json ->> 'timesheet_type',
              ''
            )), ''),
            'schedule_rows', COALESCE(
              CASE WHEN jsonb_typeof(source_material.allocation_target_json -> 'schedule_rows') = 'array' THEN source_material.allocation_target_json -> 'schedule_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_line_json -> 'schedule_rows') = 'array' THEN source_material.allocation_line_json -> 'schedule_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_base_json -> 'schedule_rows') = 'array' THEN source_material.allocation_base_json -> 'schedule_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json -> 'schedule_rows') = 'array' THEN source_material.frozen_source_basis_json -> 'schedule_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json #> '{target_snapshot_json,schedule_rows}') = 'array' THEN source_material.frozen_source_basis_json #> '{target_snapshot_json,schedule_rows}' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_component_snapshot_json -> 'schedule_rows') = 'array' THEN source_material.frozen_component_snapshot_json -> 'schedule_rows' ELSE NULL::jsonb END
            ),
            'segments', COALESCE(
              CASE WHEN jsonb_typeof(source_material.allocation_target_json -> 'segments') = 'array' THEN source_material.allocation_target_json -> 'segments' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_line_json -> 'segments') = 'array' THEN source_material.allocation_line_json -> 'segments' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_base_json -> 'segments') = 'array' THEN source_material.allocation_base_json -> 'segments' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json -> 'segments') = 'array' THEN source_material.frozen_source_basis_json -> 'segments' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json #> '{target_snapshot_json,segments}') = 'array' THEN source_material.frozen_source_basis_json #> '{target_snapshot_json,segments}' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_component_snapshot_json -> 'segments') = 'array' THEN source_material.frozen_component_snapshot_json -> 'segments' ELSE NULL::jsonb END
            ),
            'segment_rows', COALESCE(
              CASE WHEN jsonb_typeof(source_material.allocation_target_json -> 'segment_rows') = 'array' THEN source_material.allocation_target_json -> 'segment_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_line_json -> 'segment_rows') = 'array' THEN source_material.allocation_line_json -> 'segment_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_base_json -> 'segment_rows') = 'array' THEN source_material.allocation_base_json -> 'segment_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json -> 'segment_rows') = 'array' THEN source_material.frozen_source_basis_json -> 'segment_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json #> '{target_snapshot_json,segment_rows}') = 'array' THEN source_material.frozen_source_basis_json #> '{target_snapshot_json,segment_rows}' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_component_snapshot_json -> 'segment_rows') = 'array' THEN source_material.frozen_component_snapshot_json -> 'segment_rows' ELSE NULL::jsonb END
            ),
            'shift_rows', COALESCE(
              CASE WHEN jsonb_typeof(source_material.allocation_target_json -> 'shift_rows') = 'array' THEN source_material.allocation_target_json -> 'shift_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_line_json -> 'shift_rows') = 'array' THEN source_material.allocation_line_json -> 'shift_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_base_json -> 'shift_rows') = 'array' THEN source_material.allocation_base_json -> 'shift_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json -> 'shift_rows') = 'array' THEN source_material.frozen_source_basis_json -> 'shift_rows' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json #> '{target_snapshot_json,shift_rows}') = 'array' THEN source_material.frozen_source_basis_json #> '{target_snapshot_json,shift_rows}' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_component_snapshot_json -> 'shift_rows') = 'array' THEN source_material.frozen_component_snapshot_json -> 'shift_rows' ELSE NULL::jsonb END
            ),
            'schedule_changes', COALESCE(
              CASE WHEN jsonb_typeof(source_material.allocation_target_json -> 'schedule_changes') = 'array' THEN source_material.allocation_target_json -> 'schedule_changes' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_line_json -> 'schedule_changes') = 'array' THEN source_material.allocation_line_json -> 'schedule_changes' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.allocation_base_json -> 'schedule_changes') = 'array' THEN source_material.allocation_base_json -> 'schedule_changes' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json -> 'schedule_changes') = 'array' THEN source_material.frozen_source_basis_json -> 'schedule_changes' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_source_basis_json #> '{target_snapshot_json,schedule_changes}') = 'array' THEN source_material.frozen_source_basis_json #> '{target_snapshot_json,schedule_changes}' ELSE NULL::jsonb END,
              CASE WHEN jsonb_typeof(source_material.frozen_component_snapshot_json -> 'schedule_changes') = 'array' THEN source_material.frozen_component_snapshot_json -> 'schedule_changes' ELSE NULL::jsonb END
            ),
            'amendment_note', NULLIF(BTRIM(COALESCE(
              source_material.allocation_target_json ->> 'amendment_note',
              source_material.allocation_target_json ->> 'schedule_note',
              source_material.allocation_line_json ->> 'amendment_note',
              source_material.allocation_line_json ->> 'schedule_note',
              source_material.allocation_base_json ->> 'amendment_note',
              source_material.frozen_source_basis_json ->> 'amendment_note',
              source_material.frozen_source_basis_json #>> '{target_snapshot_json,amendment_note}',
              source_material.frozen_component_snapshot_json ->> 'amendment_note',
              ''
            )), '')
          )
        ) AS display_metadata_json
      FROM source_material
    ) AS display_source ON true
  ), inserted_snapshots AS (
    INSERT INTO public.pay_batch_timesheet_snapshots(
      pay_batch_id,
      timesheet_id,
      candidate_id,
      pay_channel,
      base_snapshot_json,
      target_snapshot_json,
      signature,
      created_at_utc
    )
    SELECT
      p_pay_batch_id,
      snapshot_rows.timesheet_id,
      snapshot_rows.candidate_id,
      snapshot_rows.pay_channel,
      snapshot_rows.base_snapshot_json,
      snapshot_rows.target_snapshot_json,
      md5(snapshot_rows.target_snapshot_json::text),
      v_now
    FROM snapshot_rows
    ON CONFLICT (pay_batch_id, timesheet_id, pay_channel)
    DO UPDATE
    SET candidate_id = EXCLUDED.candidate_id,
        base_snapshot_json = EXCLUDED.base_snapshot_json,
        target_snapshot_json = EXCLUDED.target_snapshot_json,
        signature = EXCLUDED.signature
    RETURNING public.pay_batch_timesheet_snapshots.id
  )
  SELECT COUNT(*)::integer
  INTO v_inserted_count
  FROM inserted_snapshots;

  v_updated_count := 0;

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'CREATE_TIMESHEET_SNAPSHOTS','ASSERT_COMPLETE','[]'::jsonb,
    jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'candidate_scope_count', v_scope_id_count,
    'inserted_count', COALESCE(v_inserted_count, 0),
    'updated_count', COALESCE(v_updated_count, 0),
    'reused_count', 0,
    'failed_count', 0,
    'inserted_snapshot_rows', COALESCE(v_inserted_count, 0),
    'missing_snapshot_count', 0,
    'has_more', EXISTS (
      SELECT 1
      FROM public.pay_batch_items AS remaining_item
      JOIN public.pay_batch_candidates AS remaining_candidate
        ON remaining_candidate.id = remaining_item.pay_batch_candidate_id
      JOIN public.banking_pay_operation_candidate_allocation_rows AS remaining_allocation
        ON remaining_allocation.pay_batch_item_id = remaining_item.id
       AND remaining_allocation.operation_id = p_operation_id
      WHERE remaining_candidate.pay_batch_id = p_pay_batch_id
        AND remaining_allocation.candidate_scope_id IN (
          SELECT (supplied_scope.scope_value #>> '{}')::uuid
          FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
        )
        AND remaining_item.timesheet_id IS NOT NULL
        AND COALESCE(remaining_item.is_voided, false) = false
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_timesheet_snapshots AS remaining_snapshot
          WHERE remaining_snapshot.pay_batch_id = p_pay_batch_id
            AND remaining_snapshot.timesheet_id = remaining_item.timesheet_id
            AND remaining_snapshot.pay_channel = remaining_item.pay_channel
        )
    )
  );
END;
$function$;

-- pay_batch_display_summary_refresh(uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_display_summary_refresh(p_pay_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_REQUIRED'
            )::text;
  END IF;

  INSERT INTO public.pay_batch_display_summary (
    pay_batch_id,
    batch_status,
    batch_kind,
    candidate_count,
    item_count,
    transfer_count,
    total_payable,
    total_bank_out,
    execution_commit_state,
    rail_provider_label,
    rail_env_label,
    issue_summary_counts,
    latest_operation_id,
    latest_operation_status,
    latest_operation_phase,
    display_label,
    stale_summary_json,
    freshness_validation_status,
    freshness_checked_at_utc,
    freshness_result_hash,
    summary_version,
    updated_at_utc
  )
  SELECT
    pay_batch_row.id AS pay_batch_id,
    pay_batch_row.status AS batch_status,
    pay_batch_row.batch_kind_fixed AS batch_kind,
    COALESCE(candidate_summary.candidate_count, 0) AS candidate_count,
    COALESCE(item_summary.item_count, 0) AS item_count,
    COALESCE(transfer_summary.transfer_count, 0) AS transfer_count,
    ROUND(COALESCE(item_summary.total_payable, 0), 2)::numeric(14,2) AS total_payable,
    ROUND(
      COALESCE(
        CASE
          WHEN COALESCE(transfer_summary.transfer_count, 0) > 0 THEN transfer_summary.transfer_amount_total
          ELSE pay_batch_row.total_bank_out
        END,
        0
      ),
      2
    )::numeric(14,2) AS total_bank_out,
    pay_batch_row.execution_commit_state AS execution_commit_state,
    pay_batch_row.rail_provider_snapshot AS rail_provider_label,
    pay_batch_row.rail_env_snapshot AS rail_env_label,
    jsonb_strip_nulls(
      jsonb_build_object(
        'candidate_count', COALESCE(candidate_summary.candidate_count, 0),
        'settled_candidate_count', COALESCE(candidate_summary.settled_candidate_count, 0),
        'awaiting_net_amount_count', COALESCE(candidate_summary.awaiting_net_amount_count, 0),
        'item_count', COALESCE(item_summary.item_count, 0),
        'voided_item_count', COALESCE(item_summary.voided_item_count, 0),
        'mismatch_item_count', COALESCE(item_summary.mismatch_item_count, 0),
        'transfer_count', COALESCE(transfer_summary.transfer_count, 0),
        'transfer_amount_total', ROUND(COALESCE(transfer_summary.transfer_amount_total, 0), 2),
        'failed_transfer_count', COALESCE(transfer_summary.failed_transfer_count, 0),
        'uncertain_transfer_count', COALESCE(transfer_summary.uncertain_transfer_count, 0),
        'sent_confirmed_count', COALESCE(transfer_summary.sent_confirmed_count, 0),
        'sent_confirmed_amount', ROUND(COALESCE(transfer_summary.sent_confirmed_amount, 0), 2),
        'pending_submitted_count', COALESCE(transfer_summary.pending_submitted_count, 0),
        'pending_submitted_amount', ROUND(COALESCE(transfer_summary.pending_submitted_amount, 0), 2),
        'failed_returned_count', COALESCE(transfer_summary.failed_returned_count, 0),
        'failed_returned_amount', ROUND(COALESCE(transfer_summary.failed_returned_amount, 0), 2),
        'check_required_count', COALESCE(transfer_summary.check_required_count, 0),
        'check_required_amount', ROUND(COALESCE(transfer_summary.check_required_amount, 0), 2),
        'not_sent_count', COALESCE(transfer_summary.not_sent_count, 0),
        'not_sent_amount', ROUND(COALESCE(transfer_summary.not_sent_amount, 0), 2),
        'remittance_operation_failed_count', COALESCE(communication_summary.remittance_operation_failed_count, 0),
        'remittance_requires_user_action_count', COALESCE(communication_summary.remittance_requires_user_action_count, 0),
        'remittance_scope_pending_count', COALESCE(communication_summary.remittance_scope_pending_count, 0),
        'remittance_scope_without_outbox_count', COALESCE(communication_summary.remittance_scope_without_outbox_count, 0),
        'remittance_outbox_failed_count', COALESCE(communication_summary.remittance_outbox_failed_count, 0),
        'completion_notice_skipped_count', COALESCE(communication_summary.completion_notice_skipped_count, 0),
        'completion_notice_failed_count', COALESCE(communication_summary.completion_notice_failed_count, 0),
        'completion_notice_due_count', COALESCE(communication_summary.completion_notice_due_count, 0),
        'mail_outbox_failed_count', COALESCE(communication_summary.mail_outbox_failed_count, 0),
        'post_settlement_communication_issue_count', COALESCE(communication_summary.post_settlement_communication_issue_count, 0),
        'post_settlement_communication_issue', COALESCE(communication_summary.post_settlement_communication_issue, false),
        'post_settlement_communication_issue_lines', COALESCE(communication_summary.post_settlement_communication_issue_lines, '[]'::jsonb)
      )
      || jsonb_build_object(
        'summary_source', 'durable_refresh',
        'summary_refresh_required', false,
        'refreshed_at_utc', now()::text,
        'latest_operation_status', CASE
          WHEN COALESCE(latest_operation.obsolete_by_durable_settlement, false) THEN 'COMPLETE'
          ELSE latest_operation.status
        END,
        'latest_operation_phase', CASE
          WHEN COALESCE(latest_operation.obsolete_by_durable_settlement, false) THEN 'COMPLETE'
          ELSE latest_operation.phase
        END,
        'latest_operation_status_raw', latest_operation.status,
        'latest_operation_phase_raw', latest_operation.phase,
        'latest_operation_type', latest_operation.operation_type,
        'durable_settlement_success', COALESCE(durable_settlement_summary.durable_settlement_success, false),
        'latest_operation_obsolete_by_durable_settlement', COALESCE(latest_operation.obsolete_by_durable_settlement, false),
        'batch_status_raw', pay_batch_row.status,
        'batch_status_label', CASE
          WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) THEN 'Draft creation failed'
          ELSE public._pay_batch_status_display_label(
            pay_batch_row.status,
            COALESCE(transfer_summary.pending_bank_outcome_count, 0),
            COALESCE(transfer_summary.unknown_bank_outcome_count, 0)
          )
        END,
        'draft_creation_failed_empty_shell', COALESCE(draft_create_failure_summary.draft_creation_failed_empty_shell, false),
        'draft_creation_failed', COALESCE(draft_create_failure_summary.draft_creation_failed, false),
        'draft_creation_failed_partial', COALESCE(draft_create_failure_summary.draft_creation_failed_partial, false),
        'draft_creation_failed_has_items', COALESCE(draft_create_failure_summary.draft_creation_failed_has_items, false),
        'batch_action_blocked', CASE
          WHEN COALESCE(durable_settlement_summary.durable_settlement_success, false) THEN false
          ELSE COALESCE(draft_create_failure_summary.draft_creation_failed, false)
        END,
        'normal_draft_actions_blocked', CASE
          WHEN COALESCE(durable_settlement_summary.durable_settlement_success, false) THEN false
          ELSE COALESCE(draft_create_failure_summary.draft_creation_failed, false)
        END,
        'draft_creation_failed_operation_id', CASE
          WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) AND COALESCE(durable_settlement_summary.durable_settlement_success, false) IS NOT TRUE THEN latest_operation.id::text
          ELSE NULL::text
        END,
        'draft_creation_failed_operation_phase', CASE
          WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) AND COALESCE(durable_settlement_summary.durable_settlement_success, false) IS NOT TRUE THEN latest_operation.phase
          ELSE NULL::text
        END
      )
      || jsonb_build_object(
        'batch_terminal_with_failed_payments', UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'FAILED',
        'pending_bank_outcome_count', COALESCE(transfer_summary.pending_bank_outcome_count, 0),
        'unknown_bank_outcome_count', COALESCE(transfer_summary.unknown_bank_outcome_count, 0),
        'terminal_failed_payment_count', COALESCE(transfer_summary.terminal_failed_payment_count, 0),
        'terminal_success_payment_count', COALESCE(transfer_summary.terminal_success_payment_count, 0),
        'settlement_required', (
          COALESCE(durable_settlement_summary.durable_settlement_success, false) IS NOT TRUE
          AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'WAITING_BANK_CONFIRM'
          AND COALESCE(transfer_summary.transfer_count, 0) > 0
          AND COALESCE(transfer_summary.pending_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.unknown_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.not_sent_count, 0) = 0
          AND (COALESCE(transfer_summary.terminal_success_payment_count, 0) + COALESCE(transfer_summary.terminal_failed_payment_count, 0)) > 0
        ),
        'settlement_nudge_recommended', (
          COALESCE(durable_settlement_summary.durable_settlement_success, false) IS NOT TRUE
          AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'WAITING_BANK_CONFIRM'
          AND COALESCE(transfer_summary.transfer_count, 0) > 0
          AND COALESCE(transfer_summary.pending_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.unknown_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.not_sent_count, 0) = 0
          AND (COALESCE(transfer_summary.terminal_success_payment_count, 0) + COALESCE(transfer_summary.terminal_failed_payment_count, 0)) > 0
        )
      )
    ) AS issue_summary_counts,
    latest_operation.id AS latest_operation_id,
    CASE
      WHEN COALESCE(latest_operation.obsolete_by_durable_settlement, false) THEN 'COMPLETE'
      ELSE latest_operation.status
    END AS latest_operation_status,
    CASE
      WHEN COALESCE(latest_operation.obsolete_by_durable_settlement, false) THEN 'COMPLETE'
      ELSE latest_operation.phase
    END AS latest_operation_phase,
    NULLIF(
      BTRIM(
        CONCAT_WS(
          ' · ',
          NULLIF(BTRIM(COALESCE(pay_batch_row.batch_kind_fixed, '')), ''),
          NULLIF(BTRIM(COALESCE(CASE
            WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) THEN 'Draft creation failed'
            ELSE public._pay_batch_status_display_label(
              pay_batch_row.status,
              COALESCE(transfer_summary.pending_bank_outcome_count, 0),
              COALESCE(transfer_summary.unknown_bank_outcome_count, 0)
            )
          END, '')), ''),
          CASE WHEN pay_batch_row.pay_date IS NULL THEN NULL::text ELSE pay_batch_row.pay_date::text END
        )
      ),
      ''
    ) AS display_label,
    jsonb_strip_nulls(
      jsonb_build_object(
        'freshness_validation_status', pay_batch_row.freshness_validation_status,
        'freshness_checked_at_utc', CASE WHEN pay_batch_row.freshness_checked_at_utc IS NULL THEN NULL::text ELSE pay_batch_row.freshness_checked_at_utc::text END,
        'freshness_result_hash', pay_batch_row.freshness_result_hash,
        'freshness_scope_hash', pay_batch_row.freshness_scope_hash,
        'summary_refresh_required', false
      )
    ) AS stale_summary_json,
    pay_batch_row.freshness_validation_status AS freshness_validation_status,
    pay_batch_row.freshness_checked_at_utc AS freshness_checked_at_utc,
    pay_batch_row.freshness_result_hash AS freshness_result_hash,
    1 AS summary_version,
    now() AS updated_at_utc
  FROM public.pay_batches AS pay_batch_row
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::integer AS candidate_count,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(candidate_row.settlement_status, ''))) = 'SETTLED'
           OR candidate_row.settled_at_utc IS NOT NULL
      )::integer AS settled_candidate_count,
      COUNT(*) FILTER (
        WHERE COALESCE(candidate_row.awaiting_net_amount, false) = true
      )::integer AS awaiting_net_amount_count
    FROM public.pay_batch_candidates AS candidate_row
    WHERE candidate_row.pay_batch_id = pay_batch_row.id
  ) AS candidate_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*) FILTER (WHERE COALESCE(item_row.is_voided, false) = false)::integer AS item_count,
      COUNT(*) FILTER (WHERE COALESCE(item_row.is_voided, false) = true)::integer AS voided_item_count,
      COUNT(*) FILTER (WHERE COALESCE(item_row.is_mismatch, false) = true)::integer AS mismatch_item_count,
      ROUND(
        COALESCE(
          SUM(
            COALESCE(
              item_row.frozen_target_amount_inc_vat,
              item_row.amount_inc_vat,
              item_row.frozen_target_amount_ex_vat,
              item_row.amount_ex_vat,
              0
            )
          ) FILTER (WHERE COALESCE(item_row.is_voided, false) = false),
          0
        ),
        2
      )::numeric AS total_payable
    FROM public.pay_batch_candidates AS candidate_for_item
    JOIN public.pay_batch_items AS item_row
      ON item_row.pay_batch_candidate_id = candidate_for_item.id
    WHERE candidate_for_item.pay_batch_id = pay_batch_row.id
  ) AS item_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::integer AS transfer_count,
      ROUND(COALESCE(SUM(transfer_class.amount), 0), 2)::numeric AS transfer_amount_total,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED')::integer AS failed_transfer_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket IN ('PENDING_SUBMITTED','CHECK_REQUIRED'))::integer AS uncertain_transfer_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'SENT_CONFIRMED')::integer AS sent_confirmed_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'SENT_CONFIRMED'), 0), 2)::numeric AS sent_confirmed_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'PENDING_SUBMITTED')::integer AS pending_submitted_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'PENDING_SUBMITTED'), 0), 2)::numeric AS pending_submitted_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED')::integer AS failed_returned_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED'), 0), 2)::numeric AS failed_returned_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'CHECK_REQUIRED')::integer AS check_required_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'CHECK_REQUIRED'), 0), 2)::numeric AS check_required_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'NOT_SENT')::integer AS not_sent_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'NOT_SENT'), 0), 2)::numeric AS not_sent_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'PENDING_SUBMITTED')::integer AS pending_bank_outcome_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'CHECK_REQUIRED')::integer AS unknown_bank_outcome_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED')::integer AS terminal_failed_payment_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'SENT_CONFIRMED')::integer AS terminal_success_payment_count
    FROM (
      SELECT
        transfer_row.amount,
        CASE
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','BLOCKED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','BLOCKED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            THEN 'FAILED_RETURNED'
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
            OR transfer_row.completed_at_utc IS NOT NULL
            THEN 'SENT_CONFIRMED'
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
            THEN 'CHECK_REQUIRED'
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
            OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
            OR UPPER(BTRIM(COALESCE(
              transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
              transfer_row.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
              transfer_row.rail_meta_json->>'provider_submission_status',
              ''
            ))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
            THEN 'PENDING_SUBMITTED'
          ELSE 'NOT_SENT'
        END AS bucket
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = pay_batch_row.id
    ) AS transfer_class
  ) AS transfer_summary ON true
  LEFT JOIN LATERAL (
    SELECT (
      UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'SETTLED'
      AND UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'COMMITTED'
      AND COALESCE(transfer_summary.terminal_success_payment_count, 0) > 0
      AND COALESCE(transfer_summary.terminal_failed_payment_count, 0) = 0
      AND COALESCE(transfer_summary.pending_bank_outcome_count, 0) = 0
      AND COALESCE(transfer_summary.unknown_bank_outcome_count, 0) = 0
      AND COALESCE(transfer_summary.not_sent_count, 0) = 0
      AND COALESCE(candidate_summary.candidate_count, 0) > 0
      AND COALESCE(candidate_summary.settled_candidate_count, 0) = COALESCE(candidate_summary.candidate_count, 0)
    ) AS durable_settlement_success
  ) AS durable_settlement_summary ON true
  LEFT JOIN LATERAL (
    WITH remittance_ops AS (
      SELECT op.*
      FROM public.banking_pay_operations AS op
      WHERE op.pay_batch_id = pay_batch_row.id
        AND UPPER(BTRIM(COALESCE(op.operation_type, ''))) = 'REMITTANCE_QUEUE'
    ),
    batch_mail AS (
      SELECT mail.*
      FROM public.mail_outbox AS mail
      WHERE (mail.context_kind = 'pay_batches' AND mail.context_id = pay_batch_row.id)
         OR mail.deterministic_outbox_key ILIKE ('%' || pay_batch_row.id::text || '%')
         OR mail.reference ILIKE ('%' || pay_batch_row.id::text || '%')
         OR mail.payment_scope_json->>'pay_batch_id' = pay_batch_row.id::text
    ),
    counts AS (
      SELECT
        (
          SELECT COUNT(*)
          FROM remittance_ops AS op
          WHERE UPPER(BTRIM(COALESCE(op.status, ''))) IN ('FAILED', 'ERROR')
             OR UPPER(BTRIM(COALESCE(op.runner_state, ''))) = 'FAILED'
        )::integer AS remittance_operation_failed_count,
        (
          SELECT COUNT(*)
          FROM remittance_ops AS op
          WHERE COALESCE(op.requires_user_action, false) = true
        )::integer AS remittance_requires_user_action_count,
        (
          SELECT COUNT(*)
          FROM public.banking_pay_operation_remittance_scope AS scope
          WHERE scope.pay_batch_id = pay_batch_row.id
            AND UPPER(BTRIM(COALESCE(scope.status, ''))) = 'PENDING'
        )::integer AS remittance_scope_pending_count,
        (
          SELECT COUNT(*)
          FROM public.banking_pay_operation_remittance_scope AS scope
          WHERE scope.pay_batch_id = pay_batch_row.id
            AND UPPER(BTRIM(COALESCE(scope.status, ''))) = 'PENDING'
            AND scope.outbox_id IS NULL
        )::integer AS remittance_scope_without_outbox_count,
        (
          SELECT COUNT(DISTINCT mail.id)
          FROM public.banking_pay_operation_remittance_scope AS scope
          JOIN public.mail_outbox AS mail
            ON mail.id = scope.outbox_id
            OR mail.deterministic_outbox_key = scope.deterministic_outbox_key
          WHERE scope.pay_batch_id = pay_batch_row.id
            AND UPPER(BTRIM(COALESCE(mail.status::text, ''))) = 'FAILED'
        )::integer AS remittance_outbox_failed_count,
        (
          SELECT COUNT(*)
          FROM batch_mail AS mail
          WHERE UPPER(BTRIM(COALESCE(mail.status::text, ''))) = 'FAILED'
        )::integer AS mail_outbox_failed_count,
        (
          SELECT COUNT(*)
          FROM batch_mail AS mail
          WHERE (
              mail.payment_scope_json->>'notice_kind' IN ('PAYMENT_COMPLETED', 'PAYMENT_COMPLETED_WITH_ISSUES')
              OR mail.deterministic_outbox_key ILIKE 'pay_batch_completed:%'
            )
            AND UPPER(BTRIM(COALESCE(mail.status::text, ''))) = 'FAILED'
        )::integer AS completion_notice_failed_count,
        (
          SELECT COUNT(*)
          FROM batch_mail AS mail
          WHERE mail.payment_scope_json->>'notice_kind' IN ('PAYMENT_COMPLETED', 'PAYMENT_COMPLETED_WITH_ISSUES')
             OR mail.deterministic_outbox_key ILIKE 'pay_batch_completed:%'
        )::integer AS completion_notice_outbox_count
    ),
    final_counts AS (
      SELECT
        counts.*,
        CASE
          WHEN UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'SETTLED'
           AND UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'COMMITTED'
           AND pay_batch_row.completion_notice_queued_at_utc IS NULL
           AND UPPER(BTRIM(COALESCE(
             pay_batch_row.completion_notice_last_result_json->>'completion_notice_skip_reason',
             pay_batch_row.completion_notice_last_result_json->>'skip_reason',
             pay_batch_row.completion_notice_last_result_json #>> '{outcome,skip_reason}',
             pay_batch_row.completion_notice_last_result_json #>> '{completion_notice_result,skip_reason}',
             ''
           ))) <> 'NO_MATERIALISED_TRANSFERS'
           AND (
             UPPER(BTRIM(COALESCE(pay_batch_row.completion_notice_last_result_json->>'completion_notice_skipped', ''))) IN ('TRUE', '1', 'YES')
             OR UPPER(BTRIM(COALESCE(pay_batch_row.completion_notice_last_result_json->>'skipped', ''))) IN ('TRUE', '1', 'YES')
             OR NULLIF(BTRIM(COALESCE(
               pay_batch_row.completion_notice_last_result_json->>'completion_notice_skip_reason',
               pay_batch_row.completion_notice_last_result_json->>'skip_reason',
               pay_batch_row.completion_notice_last_result_json #>> '{outcome,skip_reason}',
               pay_batch_row.completion_notice_last_result_json #>> '{completion_notice_result,skip_reason}',
               ''
             )), '') IS NOT NULL
           )
            THEN 1
          ELSE 0
        END::integer AS completion_notice_skipped_count,
        CASE
          WHEN UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'SETTLED'
           AND UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'COMMITTED'
           AND COALESCE(transfer_summary.transfer_count, 0) > 0
           AND pay_batch_row.completion_notice_queued_at_utc IS NULL
           AND COALESCE(counts.completion_notice_outbox_count, 0) = 0
           AND (pay_batch_row.completion_notice_next_attempt_at_utc IS NULL OR pay_batch_row.completion_notice_next_attempt_at_utc <= now())
            THEN 1
          ELSE 0
        END::integer AS completion_notice_due_count
      FROM counts
    )
    SELECT
      final_counts.remittance_operation_failed_count,
      final_counts.remittance_requires_user_action_count,
      final_counts.remittance_scope_pending_count,
      final_counts.remittance_scope_without_outbox_count,
      final_counts.remittance_outbox_failed_count,
      final_counts.mail_outbox_failed_count,
      final_counts.completion_notice_failed_count,
      final_counts.completion_notice_skipped_count,
      final_counts.completion_notice_due_count,
      (
        final_counts.remittance_operation_failed_count
        + final_counts.remittance_requires_user_action_count
        + CASE WHEN (final_counts.remittance_operation_failed_count + final_counts.remittance_requires_user_action_count) > 0 THEN final_counts.remittance_scope_without_outbox_count ELSE 0 END
        + final_counts.remittance_outbox_failed_count
        + final_counts.mail_outbox_failed_count
        + final_counts.completion_notice_failed_count
        + final_counts.completion_notice_skipped_count
        + final_counts.completion_notice_due_count
      )::integer AS post_settlement_communication_issue_count,
      (
        final_counts.remittance_operation_failed_count
        + final_counts.remittance_requires_user_action_count
        + CASE WHEN (final_counts.remittance_operation_failed_count + final_counts.remittance_requires_user_action_count) > 0 THEN final_counts.remittance_scope_without_outbox_count ELSE 0 END
        + final_counts.remittance_outbox_failed_count
        + final_counts.mail_outbox_failed_count
        + final_counts.completion_notice_failed_count
        + final_counts.completion_notice_skipped_count
        + final_counts.completion_notice_due_count
      ) > 0 AS post_settlement_communication_issue,
      COALESCE((
        SELECT jsonb_agg(issue_line.line_value)
        FROM (VALUES
          (CASE WHEN (final_counts.remittance_operation_failed_count + final_counts.remittance_requires_user_action_count + final_counts.remittance_outbox_failed_count) > 0 THEN 'Payment settled, but remittance email failed and needs attention.'::text ELSE NULL::text END),
          (CASE WHEN (final_counts.completion_notice_failed_count + final_counts.completion_notice_skipped_count + final_counts.completion_notice_due_count) > 0 THEN 'Payment settled, but final payment completion email was skipped/failed or has not queued.'::text ELSE NULL::text END),
          (CASE WHEN final_counts.mail_outbox_failed_count > 0 THEN 'Payment settled, but one or more payment communication emails failed.'::text ELSE NULL::text END)
        ) AS issue_line(line_value)
        WHERE issue_line.line_value IS NOT NULL
      ), '[]'::jsonb) AS post_settlement_communication_issue_lines
    FROM final_counts
  ) AS communication_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      operation_row.id,
      operation_row.operation_type,
      operation_row.status,
      operation_row.phase,
      (
        COALESCE(durable_settlement_summary.durable_settlement_success, false) = true
        AND UPPER(BTRIM(COALESCE(operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT')
        AND UPPER(BTRIM(COALESCE(operation_row.status, ''))) IN ('FAILED', 'REVIEW_REQUIRED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER')
      ) AS obsolete_by_durable_settlement
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.pay_batch_id = pay_batch_row.id
       OR EXISTS (
         SELECT 1
         FROM public.banking_pay_operation_candidate_scope AS operation_scope
         WHERE operation_scope.operation_id = operation_row.id
           AND operation_scope.pay_batch_id = pay_batch_row.id
       )
    ORDER BY
             CASE
               WHEN COALESCE(durable_settlement_summary.durable_settlement_success, false) = true
                AND UPPER(BTRIM(COALESCE(operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT')
                AND UPPER(BTRIM(COALESCE(operation_row.status, ''))) IN ('FAILED', 'REVIEW_REQUIRED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER')
                 THEN 1
               ELSE 0
             END ASC,
             operation_row.updated_at_utc DESC NULLS LAST,
             operation_row.created_at_utc DESC NULLS LAST,
             operation_row.id DESC
    LIMIT 1
  ) AS latest_operation ON true
  LEFT JOIN LATERAL (
    SELECT
      (
        UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
        AND UPPER(BTRIM(COALESCE(latest_operation.status, ''))) IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
        AND UPPER(BTRIM(COALESCE(latest_operation.phase, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
        AND pay_batch_row.source_workbench_session_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) IN ('DRAFT', 'CANCELLED', 'CANCELED')
        AND (
          NULLIF(BTRIM(COALESCE(pay_batch_row.execution_commit_state, '')), '') IS NULL
          OR UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
        )
      ) AS draft_creation_failed,
      (
        UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
        AND UPPER(BTRIM(COALESCE(latest_operation.status, ''))) IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
        AND UPPER(BTRIM(COALESCE(latest_operation.phase, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
        AND pay_batch_row.source_workbench_session_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) IN ('DRAFT', 'CANCELLED', 'CANCELED')
        AND (
          NULLIF(BTRIM(COALESCE(pay_batch_row.execution_commit_state, '')), '') IS NULL
          OR UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
        )
        AND COALESCE(candidate_summary.candidate_count, 0) = 0
        AND COALESCE(item_summary.item_count, 0) = 0
        AND COALESCE(item_summary.voided_item_count, 0) = 0
      ) AS draft_creation_failed_empty_shell,
      (
        UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
        AND UPPER(BTRIM(COALESCE(latest_operation.status, ''))) IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
        AND UPPER(BTRIM(COALESCE(latest_operation.phase, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
        AND pay_batch_row.source_workbench_session_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) IN ('DRAFT', 'CANCELLED', 'CANCELED')
        AND (
          NULLIF(BTRIM(COALESCE(pay_batch_row.execution_commit_state, '')), '') IS NULL
          OR UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
        )
        AND (
          COALESCE(candidate_summary.candidate_count, 0) > 0
          OR COALESCE(item_summary.item_count, 0) > 0
          OR COALESCE(item_summary.voided_item_count, 0) > 0
        )
      ) AS draft_creation_failed_partial,
      (
        COALESCE(item_summary.item_count, 0) > 0
        OR COALESCE(item_summary.voided_item_count, 0) > 0
      ) AS draft_creation_failed_has_items
  ) AS draft_create_failure_summary ON true
  WHERE pay_batch_row.id = p_pay_batch_id
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    batch_status = EXCLUDED.batch_status,
    batch_kind = EXCLUDED.batch_kind,
    candidate_count = EXCLUDED.candidate_count,
    item_count = EXCLUDED.item_count,
    transfer_count = EXCLUDED.transfer_count,
    total_payable = EXCLUDED.total_payable,
    total_bank_out = EXCLUDED.total_bank_out,
    execution_commit_state = EXCLUDED.execution_commit_state,
    rail_provider_label = EXCLUDED.rail_provider_label,
    rail_env_label = EXCLUDED.rail_env_label,
    issue_summary_counts = EXCLUDED.issue_summary_counts,
    latest_operation_id = EXCLUDED.latest_operation_id,
    latest_operation_status = EXCLUDED.latest_operation_status,
    latest_operation_phase = EXCLUDED.latest_operation_phase,
    display_label = EXCLUDED.display_label,
    stale_summary_json = EXCLUDED.stale_summary_json,
    freshness_validation_status = EXCLUDED.freshness_validation_status,
    freshness_checked_at_utc = EXCLUDED.freshness_checked_at_utc,
    freshness_result_hash = EXCLUDED.freshness_result_hash,
    summary_version = COALESCE(pay_batch_display_summary.summary_version, 0) + 1,
    updated_at_utc = now();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  INSERT INTO public.banking_pay_batch_change_signals (
    pay_batch_id,
    version,
    payment_status_version,
    correction_progress_version,
    alert_version,
    overview_version,
    last_changed_at_utc,
    last_payment_status_changed_at_utc,
    last_correction_progress_changed_at_utc,
    last_alert_changed_at_utc,
    last_change_reason,
    last_change_source,
    last_change_scope_json,
    last_changed_transfer_ids,
    last_changed_candidate_ids,
    last_changed_pay_batch_item_ids,
    updated_at_utc
  )
  VALUES (
    p_pay_batch_id,
    1,
    1,
    0,
    1,
    1,
    now(),
    now(),
    NULL::timestamptz,
    now(),
    'DISPLAY_SUMMARY_REFRESH',
    'pay_batch_display_summary_refresh',
    jsonb_build_object(
      'summary_source', 'durable_refresh',
      'summary_refresh_required', false,
      'changed_areas', jsonb_build_array('overview', 'payment_status', 'remittances', 'payment_issues', 'alerts')
    ),
    '[]'::jsonb,
    '[]'::jsonb,
    '[]'::jsonb,
    now()
  )
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    version = COALESCE(banking_pay_batch_change_signals.version, 0) + 1,
    payment_status_version = COALESCE(banking_pay_batch_change_signals.payment_status_version, 0) + 1,
    alert_version = COALESCE(banking_pay_batch_change_signals.alert_version, 0) + 1,
    overview_version = COALESCE(banking_pay_batch_change_signals.overview_version, 0) + 1,
    last_changed_at_utc = now(),
    last_payment_status_changed_at_utc = now(),
    last_alert_changed_at_utc = now(),
    last_change_reason = 'DISPLAY_SUMMARY_REFRESH',
    last_change_source = 'pay_batch_display_summary_refresh',
    last_change_scope_json = COALESCE(banking_pay_batch_change_signals.last_change_scope_json, '{}'::jsonb) || jsonb_build_object(
      'summary_source', 'durable_refresh',
      'summary_refresh_required', false,
      'changed_areas', jsonb_build_array('overview', 'payment_status', 'remittances', 'payment_issues', 'alerts')
    ),
    updated_at_utc = now();
END;
$function$;

-- pay_batch_display_summary_touch(uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_display_summary_touch(p_pay_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_REQUIRED'
            )::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pay_batches AS pay_batch_row
    WHERE pay_batch_row.id = p_pay_batch_id
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  INSERT INTO public.pay_batch_display_summary (
    pay_batch_id,
    issue_summary_counts,
    stale_summary_json,
    summary_version,
    updated_at_utc
  )
  VALUES (
    p_pay_batch_id,
    '{}'::jsonb,
    jsonb_build_object(
      'summary_refresh_required', true,
      'touched_at_utc', now()::text
    ),
    1,
    now()
  )
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    stale_summary_json = COALESCE(pay_batch_display_summary.stale_summary_json, '{}'::jsonb) || jsonb_build_object(
      'summary_refresh_required', true,
      'touched_at_utc', now()::text
    ),
    summary_version = COALESCE(pay_batch_display_summary.summary_version, 0) + 1,
    updated_at_utc = now();
END;
$function$;

-- pay_batch_execution_summary_get(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_batch_execution_summary_get(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT 'LIGHT'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_mode text := upper(btrim(coalesce(p_mode, 'LIGHT')));
  v_batch_row public.pay_batches%ROWTYPE;
  v_display_summary jsonb := '{}'::jsonb;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_active_item_count integer := 0;
  v_total_amount numeric := 0;
  v_transfer_count integer := 0;
  v_transfer_pending_count integer := 0;
  v_transfer_completed_count integer := 0;
  v_transfer_failed_count integer := 0;
  v_transfer_unknown_count integer := 0;
  v_active_operation_id uuid := NULL::uuid;
  v_active_operation_type text := NULL::text;
  v_active_operation_status text := NULL::text;
  v_active_operation_phase text := NULL::text;
  v_runner_state text := NULL::text;
  v_operation_progress_json jsonb := '{}'::jsonb;
  v_scope_count integer := 0;
  v_scope_prepared_count integer := 0;
  v_scope_ready_count integer := 0;
  v_scope_claimed_count integer := 0;
  v_scope_accepted_count integer := 0;
  v_scope_rejected_count integer := 0;
  v_scope_unknown_count integer := 0;
  v_scope_review_count integer := 0;
  v_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_completed_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_signal_version bigint := 0;
  v_payment_status_version bigint := 0;
  v_overview_version bigint := 0;
  v_correction_progress_version bigint := 0;
  v_alert_version bigint := 0;
  v_last_status_hash text := NULL::text;
  v_last_alert_hash text := NULL::text;
  v_submission_evidence_json jsonb := '{}'::jsonb;
  v_batch_status_raw text := NULL::text;
  v_batch_status_label text := NULL::text;
  v_batch_terminal_with_failed_payments boolean := false;
  v_pending_bank_outcome_count integer := 0;
  v_unknown_bank_outcome_count integer := 0;
  v_terminal_success_payment_count integer := 0;
  v_terminal_failed_payment_count integer := 0;
  v_payment_outcome_summary jsonb := '{}'::jsonb;
  v_paye_missing_count integer := 0;
  v_paye_zero_count integer := 0;
  v_paye_positive_count integer := 0;
  v_positive_bank_payment_count integer := 0;
  v_positive_bank_payment_total numeric(14,2) := 0;
  v_global_invalid_payment_row_count integer := 0;
  v_paye_net_state_hash text := NULL::text;
  v_all_bank_payment_projection_hash text := NULL::text;
  v_bank_payment_projection_scope text := 'ALL';
  v_scoped_paye_missing_count integer := 0;
  v_scoped_paye_zero_count integer := 0;
  v_scoped_paye_positive_count integer := 0;
  v_scoped_positive_bank_payment_count integer := 0;
  v_scoped_invalid_payment_row_count integer := 0;
  v_scoped_paye_net_state_hash text := NULL::text;
  v_bank_payment_projection_hash text := NULL::text;
  v_current_bank_payment_row_count integer := 0;
  v_current_bank_payment_total numeric(14,2) := 0;
  v_bank_csv_export_json jsonb := '{}'::jsonb;
  v_bank_csv_generated boolean := false;
  v_bank_csv_current boolean := false;
  v_bank_csv_stale_reason text := NULL::text;
  v_stored_csv_scope_raw text := NULL::text;
  v_stored_csv_scope text := NULL::text;
  v_stored_paye_net_state_hash text := NULL::text;
  v_stored_bank_payment_projection_hash text := NULL::text;
  v_stored_bank_csv_row_count integer := NULL::integer;
  v_stored_bank_csv_total numeric(14,2) := NULL::numeric;
  v_paye_net_preflight jsonb := '{}'::jsonb;
  v_bank_csv_scope_preflight jsonb := '{}'::jsonb;
  v_paye_net_complete boolean := false;
  v_all_required_paye_explicit_zero boolean := false;
  v_has_positive_bank_payments boolean := false;
  v_no_bank_payment_execution_eligible boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('DISPLAY');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    PERFORM 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_ACTOR_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_ACTOR_NOT_FOUND', 'actor_user_id', p_actor_user_id::text)::text;
    END IF;
  END IF;

  IF v_mode IS NULL OR v_mode = '' THEN
    v_mode := 'LIGHT';
  END IF;

  IF v_mode NOT IN ('LIGHT', 'OPERATION_LIGHT') THEN
    RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_MODE_NOT_SUPPORTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_MODE_NOT_SUPPORTED', 'mode', p_mode)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  SELECT to_jsonb(summary_row.*)
  INTO v_display_summary
  FROM public.pay_batch_display_summary AS summary_row
  WHERE summary_row.pay_batch_id = p_pay_batch_id;

  IF v_display_summary IS NULL THEN
    v_display_summary := '{}'::jsonb;
  END IF;

  v_bank_csv_export_json := CASE
    WHEN v_batch_row.bank_csv_export_json IS NOT NULL
     AND JSONB_TYPEOF(v_batch_row.bank_csv_export_json) = 'object'
      THEN v_batch_row.bank_csv_export_json
    ELSE '{}'::jsonb
  END;

  v_bank_csv_generated := v_bank_csv_export_json <> '{}'::jsonb
    AND NULLIF(BTRIM(COALESCE(
      v_bank_csv_export_json->>'generated_at_utc',
      v_bank_csv_export_json->>'generatedAtUtc',
      v_bank_csv_export_json->>'filename',
      v_bank_csv_export_json->>'bank_payment_projection_hash',
      v_bank_csv_export_json->>'transfer_hash',
      ''
    )), '') IS NOT NULL;

  v_stored_csv_scope_raw := UPPER(NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'scope',
    v_bank_csv_export_json->>'pay_channel_scope',
    v_bank_csv_export_json->>'payChannelScope',
    ''
  )), ''));

  IF v_stored_csv_scope_raw IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS') THEN
    v_stored_csv_scope := v_stored_csv_scope_raw;
  ELSE
    v_stored_csv_scope := NULL::text;
  END IF;

  v_bank_payment_projection_scope := COALESCE(v_stored_csv_scope, 'ALL');
  v_stored_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'paye_net_state_hash',
    v_bank_csv_export_json->>'current_paye_net_state_hash',
    v_bank_csv_export_json->>'payeNetStateHash',
    ''
  )), '');
  v_stored_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'bank_payment_projection_hash',
    v_bank_csv_export_json->>'current_bank_payment_projection_hash',
    v_bank_csv_export_json->>'bankPaymentProjectionHash',
    ''
  )), '');

  IF COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount', '') ~ '^[0-9]+$' THEN
    v_stored_bank_csv_row_count := COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount')::integer;
  END IF;

  IF COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_stored_bank_csv_total := ROUND(COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount')::numeric, 2)::numeric(14,2);
  END IF;

  WITH global_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      'ALL'
    ) AS projection_row
  ), global_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS paye_missing_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS paye_zero_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'POSITIVE'
      )::integer AS paye_positive_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_bank_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_bank_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM global_projection_rows AS projection_row
  ), scoped_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_bank_payment_projection_scope
    ) AS projection_row
  ), scoped_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS paye_missing_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS paye_zero_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'POSITIVE'
      )::integer AS paye_positive_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_bank_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_bank_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM scoped_projection_rows AS projection_row
  )
  SELECT
    COALESCE(global_projection_summary.paye_missing_count, 0),
    COALESCE(global_projection_summary.paye_zero_count, 0),
    COALESCE(global_projection_summary.paye_positive_count, 0),
    COALESCE(global_projection_summary.positive_bank_payment_count, 0),
    COALESCE(global_projection_summary.positive_bank_payment_total, 0),
    COALESCE(global_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      global_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      global_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(scoped_projection_summary.paye_missing_count, 0),
    COALESCE(scoped_projection_summary.paye_zero_count, 0),
    COALESCE(scoped_projection_summary.paye_positive_count, 0),
    COALESCE(scoped_projection_summary.positive_bank_payment_count, 0),
    COALESCE(scoped_projection_summary.positive_bank_payment_total, 0),
    COALESCE(scoped_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      scoped_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_bank_payment_projection_scope,
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      scoped_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_bank_payment_projection_scope,
        'rows', '[]'::jsonb
      )::text)
    )
  INTO
    v_paye_missing_count,
    v_paye_zero_count,
    v_paye_positive_count,
    v_positive_bank_payment_count,
    v_positive_bank_payment_total,
    v_global_invalid_payment_row_count,
    v_paye_net_state_hash,
    v_all_bank_payment_projection_hash,
    v_scoped_paye_missing_count,
    v_scoped_paye_zero_count,
    v_scoped_paye_positive_count,
    v_scoped_positive_bank_payment_count,
    v_current_bank_payment_total,
    v_scoped_invalid_payment_row_count,
    v_scoped_paye_net_state_hash,
    v_bank_payment_projection_hash
  FROM global_projection_summary
  CROSS JOIN scoped_projection_summary;

  v_paye_missing_count := COALESCE(v_paye_missing_count, 0);
  v_paye_zero_count := COALESCE(v_paye_zero_count, 0);
  v_paye_positive_count := COALESCE(v_paye_positive_count, 0);
  v_positive_bank_payment_count := COALESCE(v_positive_bank_payment_count, 0);
  v_positive_bank_payment_total := ROUND(COALESCE(v_positive_bank_payment_total, 0), 2);
  v_global_invalid_payment_row_count := COALESCE(v_global_invalid_payment_row_count, 0);
  v_scoped_paye_missing_count := COALESCE(v_scoped_paye_missing_count, 0);
  v_scoped_paye_zero_count := COALESCE(v_scoped_paye_zero_count, 0);
  v_scoped_paye_positive_count := COALESCE(v_scoped_paye_positive_count, 0);
  v_scoped_positive_bank_payment_count := COALESCE(v_scoped_positive_bank_payment_count, 0);
  v_scoped_invalid_payment_row_count := COALESCE(v_scoped_invalid_payment_row_count, 0);
  v_current_bank_payment_row_count := v_scoped_positive_bank_payment_count;
  v_current_bank_payment_total := ROUND(COALESCE(v_current_bank_payment_total, 0), 2);

  v_paye_net_complete := v_paye_missing_count = 0;
  v_all_required_paye_explicit_zero := (
    v_paye_missing_count = 0
    AND v_paye_zero_count > 0
    AND v_paye_positive_count = 0
  );
  v_has_positive_bank_payments := v_positive_bank_payment_count > 0;
  v_no_bank_payment_execution_eligible := (
    v_paye_missing_count = 0
    AND v_paye_zero_count > 0
    AND v_positive_bank_payment_count = 0
    AND v_global_invalid_payment_row_count = 0
  );

  v_paye_net_preflight := JSONB_BUILD_OBJECT(
    'scope', 'ALL',
    'missing_explicit_paye_input_count', v_paye_missing_count,
    'explicit_zero_count', v_paye_zero_count,
    'positive_paye_count', v_paye_positive_count,
    'positive_bank_payment_count', v_positive_bank_payment_count,
    'positive_total', v_positive_bank_payment_total,
    'invalid_payment_row_count', v_global_invalid_payment_row_count,
    'paye_net_state_hash', v_paye_net_state_hash,
    'bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'no_bank_payment_execution_eligible', v_no_bank_payment_execution_eligible
  );

  v_bank_csv_scope_preflight := JSONB_BUILD_OBJECT(
    'scope', v_bank_payment_projection_scope,
    'missing_explicit_paye_input_count', v_scoped_paye_missing_count,
    'explicit_zero_count', v_scoped_paye_zero_count,
    'positive_paye_count', v_scoped_paye_positive_count,
    'positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'positive_total', v_current_bank_payment_total,
    'invalid_payment_row_count', v_scoped_invalid_payment_row_count,
    'paye_net_state_hash', v_scoped_paye_net_state_hash,
    'bank_payment_projection_hash', v_bank_payment_projection_hash
  );

  IF v_bank_csv_generated IS NOT TRUE THEN
    v_bank_csv_stale_reason := 'CSV_NOT_GENERATED';
  ELSIF v_stored_csv_scope IS NULL THEN
    v_bank_csv_stale_reason := 'CSV_SCOPE_INVALID';
  ELSIF v_scoped_paye_missing_count > 0 THEN
    v_bank_csv_stale_reason := 'CSV_PAYE_NET_REQUIRED';
  ELSIF v_scoped_invalid_payment_row_count > 0 THEN
    v_bank_csv_stale_reason := 'CSV_PAYMENT_PROJECTION_INVALID';
  ELSIF v_stored_paye_net_state_hash IS NULL THEN
    v_bank_csv_stale_reason := 'CSV_PAYE_NET_STATE_HASH_MISSING';
  ELSIF v_stored_bank_payment_projection_hash IS NULL THEN
    v_bank_csv_stale_reason := 'CSV_BANK_PAYMENT_PROJECTION_HASH_MISSING';
  ELSIF v_stored_paye_net_state_hash <> v_scoped_paye_net_state_hash THEN
    v_bank_csv_stale_reason := 'CSV_PAYE_NET_STATE_CHANGED';
  ELSIF v_stored_bank_payment_projection_hash <> v_bank_payment_projection_hash THEN
    v_bank_csv_stale_reason := 'CSV_BANK_PAYMENT_PROJECTION_CHANGED';
  ELSIF v_stored_bank_csv_row_count IS NOT NULL
    AND v_stored_bank_csv_row_count <> v_current_bank_payment_row_count THEN
    v_bank_csv_stale_reason := 'CSV_ROW_COUNT_CHANGED';
  ELSIF v_stored_bank_csv_total IS NOT NULL
    AND ROUND(v_stored_bank_csv_total, 2) <> ROUND(v_current_bank_payment_total, 2) THEN
    v_bank_csv_stale_reason := 'CSV_TOTAL_CHANGED';
  ELSE
    v_bank_csv_stale_reason := NULL::text;
  END IF;

  v_bank_csv_current := v_bank_csv_generated AND v_bank_csv_stale_reason IS NULL;

  SELECT operation_row.id,
         operation_row.operation_type,
         operation_row.status,
         operation_row.phase,
         operation_row.runner_state,
         coalesce(operation_row.progress_json, '{}'::jsonb)
  INTO v_active_operation_id,
       v_active_operation_type,
       v_active_operation_status,
       v_active_operation_phase,
       v_runner_state,
       v_operation_progress_json
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT')
    AND upper(btrim(coalesce(operation_row.status, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED')
    AND NOT (
      upper(btrim(coalesce(operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE'
      AND (
        lower(btrim(coalesce(operation_row.input_json->>'prepare_bank_csv_export_only', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR upper(btrim(coalesce(operation_row.input_json->>'execution_mode', ''))) = 'BANK_CSV_EXPORT_PREPARE'
        OR btrim(coalesce(operation_row.input_json->>'source', '')) = 'handleBankingPayBatchExportCsv'
        OR lower(coalesce(operation_row.idempotency_key, '')) LIKE 'bank-csv-export-prepare:%'
      )
    )
  ORDER BY operation_row.updated_at_utc DESC NULLS LAST,
           operation_row.created_at_utc DESC NULLS LAST,
           operation_row.id DESC
  LIMIT 1;

  SELECT coalesce(signal_row.version, 0),
         coalesce(signal_row.payment_status_version, 0),
         coalesce(signal_row.overview_version, 0),
         coalesce(signal_row.correction_progress_version, 0),
         coalesce(signal_row.alert_version, 0),
         signal_row.last_status_hash,
         signal_row.last_alert_hash
  INTO v_signal_version,
       v_payment_status_version,
       v_overview_version,
       v_correction_progress_version,
       v_alert_version,
       v_last_status_hash,
       v_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS signal_row
  WHERE signal_row.pay_batch_id = p_pay_batch_id;

  SELECT
    CASE WHEN coalesce(v_display_summary->>'candidate_count', v_display_summary->>'pay_batch_candidate_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'candidate_count', v_display_summary->>'pay_batch_candidate_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'item_count', v_display_summary->>'pay_batch_item_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'item_count', v_display_summary->>'pay_batch_item_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'active_item_count', v_display_summary->>'payable_item_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'active_item_count', v_display_summary->>'payable_item_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'total_amount', v_display_summary->>'total_bank_out', v_display_summary->>'amount_total', '0') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN coalesce(v_display_summary->>'total_amount', v_display_summary->>'total_bank_out', v_display_summary->>'amount_total')::numeric ELSE 0::numeric END,
    CASE WHEN coalesce(v_display_summary->>'transfer_count', v_display_summary->>'bank_transfer_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'transfer_count', v_display_summary->>'bank_transfer_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'pending_transfer_count', v_display_summary->>'transfer_pending_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'pending_transfer_count', v_display_summary->>'transfer_pending_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'completed_transfer_count', v_display_summary->>'transfer_completed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'completed_transfer_count', v_display_summary->>'transfer_completed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'failed_transfer_count', v_display_summary->>'transfer_failed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'failed_transfer_count', v_display_summary->>'transfer_failed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'unknown_transfer_count', v_display_summary->>'transfer_unknown_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'unknown_transfer_count', v_display_summary->>'transfer_unknown_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_count', v_operation_progress_json->>'scope_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_count', v_operation_progress_json->>'scope_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_prepared_count', v_operation_progress_json->>'scope_prepared_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_prepared_count', v_operation_progress_json->>'scope_prepared_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_provider_ready_count', v_operation_progress_json->>'remaining_ready_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_provider_ready_count', v_operation_progress_json->>'remaining_ready_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_claimed_count', v_operation_progress_json->>'claimed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_claimed_count', v_operation_progress_json->>'claimed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_accepted_count', v_operation_progress_json->>'accepted_count', v_operation_progress_json->>'last_rail_update_accepted_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_accepted_count', v_operation_progress_json->>'accepted_count', v_operation_progress_json->>'last_rail_update_accepted_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_rejected_count', v_operation_progress_json->>'failed_count', v_operation_progress_json->>'last_rail_update_failed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_rejected_count', v_operation_progress_json->>'failed_count', v_operation_progress_json->>'last_rail_update_failed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_unknown_count', v_operation_progress_json->>'unknown_count', v_operation_progress_json->>'last_rail_update_unknown_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_unknown_count', v_operation_progress_json->>'unknown_count', v_operation_progress_json->>'last_rail_update_unknown_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_review_required_count', v_operation_progress_json->>'review_required_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_review_required_count', v_operation_progress_json->>'review_required_count')::integer WHEN v_active_operation_status = 'REVIEW_REQUIRED' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'pending_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'pending_chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'running_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'running_chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'completed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'completed_chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'failed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'failed_chunk_count')::integer ELSE 0 END
  INTO v_candidate_count,
       v_item_count,
       v_active_item_count,
       v_total_amount,
       v_transfer_count,
       v_transfer_pending_count,
       v_transfer_completed_count,
       v_transfer_failed_count,
       v_transfer_unknown_count,
       v_scope_count,
       v_scope_prepared_count,
       v_scope_ready_count,
       v_scope_claimed_count,
       v_scope_accepted_count,
       v_scope_rejected_count,
       v_scope_unknown_count,
       v_scope_review_count,
       v_chunk_count,
       v_pending_chunk_count,
       v_running_chunk_count,
       v_completed_chunk_count,
       v_failed_chunk_count;


  v_batch_status_raw := v_batch_row.status;

  WITH transfer_classification AS (
    SELECT
      transfer_row.id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
          OR (
            transfer_row.completed_at_utc IS NOT NULL
            AND UPPER(BTRIM(COALESCE(transfer_row.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            AND UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ) THEN 'TERMINAL_SUCCESS'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          THEN 'TERMINAL_FAILED'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          THEN 'UNKNOWN'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
          OR UPPER(BTRIM(COALESCE(
            transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
            transfer_row.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
            transfer_row.rail_meta_json ->> 'provider_submission_status',
            ''
          ))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
          THEN 'PENDING'
        ELSE 'UNKNOWN'
      END AS terminal_class
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_SUCCESS')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_FAILED')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'UNKNOWN')::integer
  INTO
    v_transfer_count,
    v_pending_bank_outcome_count,
    v_terminal_success_payment_count,
    v_terminal_failed_payment_count,
    v_unknown_bank_outcome_count
  FROM transfer_classification;

  v_transfer_pending_count := COALESCE(v_pending_bank_outcome_count, 0);
  v_transfer_completed_count := COALESCE(v_terminal_success_payment_count, 0);
  v_transfer_failed_count := COALESCE(v_terminal_failed_payment_count, 0);
  v_transfer_unknown_count := COALESCE(v_unknown_bank_outcome_count, 0);
  v_batch_terminal_with_failed_payments := UPPER(BTRIM(COALESCE(v_batch_status_raw, ''))) = 'FAILED';
  v_batch_status_label := public._pay_batch_status_display_label(
    v_batch_status_raw,
    COALESCE(v_pending_bank_outcome_count, 0),
    COALESCE(v_unknown_bank_outcome_count, 0)
  );
  v_payment_outcome_summary := jsonb_build_object(
    'batch_status_raw', v_batch_status_raw,
    'batch_status_label', v_batch_status_label,
    'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
    'transfer_count', COALESCE(v_transfer_count, 0),
    'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
    'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
    'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
    'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
    'all_transfers_terminal', (
      COALESCE(v_transfer_count, 0) > 0
      AND COALESCE(v_pending_bank_outcome_count, 0) = 0
      AND COALESCE(v_unknown_bank_outcome_count, 0) = 0
      AND (COALESCE(v_terminal_success_payment_count, 0) + COALESCE(v_terminal_failed_payment_count, 0)) = COALESCE(v_transfer_count, 0)
    )
  );

  v_submission_evidence_json := jsonb_build_object(
    'operation_light', true,
    'submitted_count', coalesce(v_scope_claimed_count, 0) + coalesce(v_scope_accepted_count, 0) + coalesce(v_scope_rejected_count, 0) + coalesce(v_scope_unknown_count, 0),
    'accepted_count', coalesce(v_scope_accepted_count, 0),
    'failed_count', coalesce(v_scope_rejected_count, 0),
    'unknown_count', coalesce(v_scope_unknown_count, 0),
    'review_required_count', coalesce(v_scope_review_count, 0),
    'remaining_ready_count', coalesce(v_scope_ready_count, 0),
    'last_provider_message', coalesce(v_operation_progress_json->>'last_provider_message', v_operation_progress_json->>'provider_submission_status')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', v_mode,
    'light_mode', true,
    'pay_batch_id', p_pay_batch_id::text,
    'batch_id', p_pay_batch_id::text,
    'batch_status', v_batch_row.status,
    'status', v_batch_row.status,
    'batch_status_raw', v_batch_status_raw,
    'batch_status_label', v_batch_status_label,
    'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
    'payment_outcome_summary', COALESCE(v_payment_outcome_summary, '{}'::jsonb),
    'batch_kind_fixed', v_batch_row.batch_kind_fixed,
    'rail_provider_snapshot', v_batch_row.rail_provider_snapshot,
    'rail_env_snapshot', v_batch_row.rail_env_snapshot,
    'execution_commit_state', v_batch_row.execution_commit_state,
    'execution_commit_ref_present', nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
    'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END,
    'freshness_validation_status', v_batch_row.freshness_validation_status,
    'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END,
    'freshness_result_hash', v_batch_row.freshness_result_hash,
    'display_summary', coalesce(v_display_summary, '{}'::jsonb),
    'candidate_count', coalesce(v_candidate_count, 0),
    'item_count', coalesce(v_item_count, 0),
    'active_item_count', coalesce(v_active_item_count, 0),
    'total_amount', coalesce(v_total_amount, 0),
    'transfer_count', coalesce(v_transfer_count, 0),
    'pending_transfer_count', coalesce(v_transfer_pending_count, 0),
    'completed_transfer_count', coalesce(v_transfer_completed_count, 0),
    'failed_transfer_count', coalesce(v_transfer_failed_count, 0),
    'unknown_transfer_count', coalesce(v_transfer_unknown_count, 0),
    'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
    'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
    'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
    'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0)
  ) || jsonb_build_object(
    'active_operation_id', CASE WHEN v_active_operation_id IS NULL THEN NULL ELSE v_active_operation_id::text END,
    'active_operation_type', v_active_operation_type,
    'active_operation_status', v_active_operation_status,
    'active_operation_phase', v_active_operation_phase,
    'runner_state', v_runner_state,
    'operation_progress', coalesce(v_operation_progress_json, '{}'::jsonb),
    'operation_scope_count', coalesce(v_scope_count, 0),
    'operation_scope_prepared_count', coalesce(v_scope_prepared_count, 0),
    'operation_scope_provider_ready_count', coalesce(v_scope_ready_count, 0),
    'operation_scope_claimed_count', coalesce(v_scope_claimed_count, 0),
    'operation_scope_accepted_count', coalesce(v_scope_accepted_count, 0),
    'operation_scope_rejected_count', coalesce(v_scope_rejected_count, 0),
    'operation_scope_unknown_count', coalesce(v_scope_unknown_count, 0),
    'operation_scope_review_required_count', coalesce(v_scope_review_count, 0),
    'chunk_count', coalesce(v_chunk_count, 0),
    'pending_chunk_count', coalesce(v_pending_chunk_count, 0),
    'running_chunk_count', coalesce(v_running_chunk_count, 0),
    'completed_chunk_count', coalesce(v_completed_chunk_count, 0),
    'failed_chunk_count', coalesce(v_failed_chunk_count, 0),
    'submission_evidence', v_submission_evidence_json,
    'live_signal_version', coalesce(v_signal_version, 0),
    'payment_status_version', coalesce(v_payment_status_version, 0),
    'overview_version', coalesce(v_overview_version, 0),
    'correction_progress_version', coalesce(v_correction_progress_version, 0),
    'alert_version', coalesce(v_alert_version, 0),
    'last_status_hash', v_last_status_hash,
    'last_alert_hash', v_last_alert_hash,
    'classification_called', false,
    'cancelability_called', false,
    'correction_plan_called', false,
    'provider_diagnostic_called', false,
    'mail_outbox_scanned', false
  ) || jsonb_build_object(
    'paye_net_preflight', v_paye_net_preflight,
    'global_execute_preflight', v_paye_net_preflight,
    'bank_csv_scope_preflight', v_bank_csv_scope_preflight,
    'paye_net_complete', v_paye_net_complete,
    'all_required_paye_explicit_zero', v_all_required_paye_explicit_zero,
    'has_positive_bank_payments', v_has_positive_bank_payments,
    'no_bank_payment_execution_eligible', v_no_bank_payment_execution_eligible,
    'global_invalid_payment_row_count', v_global_invalid_payment_row_count,
    'scoped_invalid_payment_row_count', v_scoped_invalid_payment_row_count,
    'global_missing_explicit_paye_input_count', v_paye_missing_count,
    'global_explicit_zero_count', v_paye_zero_count,
    'global_positive_paye_count', v_paye_positive_count,
    'global_positive_bank_payment_count', v_positive_bank_payment_count,
    'global_positive_bank_payment_total', v_positive_bank_payment_total,
    'scoped_missing_explicit_paye_input_count', v_scoped_paye_missing_count,
    'scoped_explicit_zero_count', v_scoped_paye_zero_count,
    'scoped_positive_paye_count', v_scoped_paye_positive_count,
    'scoped_positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'paye_net_state_hash', v_paye_net_state_hash,
    'global_paye_net_state_hash', v_paye_net_state_hash,
    'current_paye_net_state_hash', v_paye_net_state_hash,
    'scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'current_scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'bank_payment_projection_scope', v_bank_payment_projection_scope,
    'bank_payment_projection_hash', v_bank_payment_projection_hash,
    'current_bank_payment_projection_hash', v_bank_payment_projection_hash,
    'all_scope_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'global_bank_payment_projection_hash', v_all_bank_payment_projection_hash
  ) || jsonb_build_object(
    'current_bank_payment_row_count', v_current_bank_payment_row_count,
    'current_bank_payment_total', v_current_bank_payment_total,
    'bank_csv_generated', v_bank_csv_generated,
    'bank_csv_current', v_bank_csv_current,
    'bank_csv_stale_reason', v_bank_csv_stale_reason,
    'bank_csv_scope', v_stored_csv_scope,
    'stored_paye_net_state_hash', v_stored_paye_net_state_hash,
    'stored_bank_payment_projection_hash', v_stored_bank_payment_projection_hash,
    'stored_bank_csv_row_count', v_stored_bank_csv_row_count,
    'stored_bank_csv_total', v_stored_bank_csv_total,
    'bank_csv_export_json', v_bank_csv_export_json
  );
END;
$function$;

-- pay_batch_export_csv_rows(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_export_csv_rows(p_pay_batch_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();

  v_batch record;
  v_batch_kind text := null;
  v_channels text[] := null;

  v_is_cancelled boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_pre_execution_export boolean := false;
  v_freshness_validation_status text := null;
  v_freshness_result_hash text := null;
  v_freshness_scope_hash text := null;
  v_freshness_result_json jsonb := '{}'::jsonb;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_rows jsonb := '[]'::jsonb;
  v_row_count int := 0;
  v_kind_counts jsonb := '{}'::jsonb;
  v_batch_status_raw text := NULL::text;
  v_batch_status_label text := NULL::text;
  v_batch_terminal_with_failed_payments boolean := false;
  v_pending_bank_outcome_count integer := 0;
  v_unknown_bank_outcome_count integer := 0;
  v_terminal_success_payment_count integer := 0;
  v_terminal_failed_payment_count integer := 0;
  v_completed_at_utc timestamptz := NULL::timestamptz;
begin
  if p_pay_batch_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_export_csv_rows: pay_batch_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_export_csv_rows: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.cancelled_at_utc,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash,
    pb.freshness_result_json,
    pb.freshness_operation_id,
    pb.completed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_export_csv_rows: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_is_cancelled := (
    v_batch.cancelled_at_utc is not null
    or upper(btrim(coalesce(v_batch.status, ''))) in ('CANCELLED', 'CANCELED')
  );
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;
  v_freshness_validation_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
  v_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
  v_pre_execution_export := (
    v_is_cancelled = false
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_execution_commit_ref is null
    and v_execution_committed_at_utc is null
  );


  v_completed_at_utc := v_batch.completed_at_utc;
  v_batch_status_raw := v_batch.status;

  WITH transfer_classification AS (
    SELECT
      transfer_row.id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
          OR (
            transfer_row.completed_at_utc IS NOT NULL
            AND UPPER(BTRIM(COALESCE(transfer_row.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            AND UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ) THEN 'TERMINAL_SUCCESS'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          THEN 'TERMINAL_FAILED'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          THEN 'UNKNOWN'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
          THEN 'PENDING'
        ELSE 'UNKNOWN'
      END AS terminal_class
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  )
  SELECT
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'UNKNOWN')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_SUCCESS')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_FAILED')::integer
  INTO
    v_pending_bank_outcome_count,
    v_unknown_bank_outcome_count,
    v_terminal_success_payment_count,
    v_terminal_failed_payment_count
  FROM transfer_classification;

  v_batch_terminal_with_failed_payments := UPPER(BTRIM(COALESCE(v_batch_status_raw, ''))) = 'FAILED';
  v_batch_status_label := public._pay_batch_status_display_label(
    v_batch_status_raw,
    COALESCE(v_pending_bank_outcome_count, 0),
    COALESCE(v_unknown_bank_outcome_count, 0)
  );

  select ch.channels
  into v_channels
  from (
    select
      array_agg(distinct upper(coalesce(pbi.pay_channel,'')) order by upper(coalesce(pbi.pay_channel,'')))
        filter (where upper(coalesce(pbi.pay_channel,'')) in ('PAYE','UMBRELLA')) as channels
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
  ) ch;

  v_batch_kind := case
    when v_channels is null then null
    when array_position(v_channels,'PAYE') is not null and array_position(v_channels,'UMBRELLA') is not null then 'MIXED'
    when array_position(v_channels,'PAYE') is not null then 'PAYE'
    when array_position(v_channels,'UMBRELLA') is not null then 'UMBRELLA'
    else null
  end;

  if upper(coalesce(v_batch.batch_kind_fixed,'')) = 'LOANS' then
    v_batch_kind := 'LOANS';
  end if;

  if v_pre_execution_export then
    if v_freshness_validation_status = 'PASSED' and v_freshness_result_hash is not null then
      v_fresh := jsonb_build_object(
        'is_stale', false,
        'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
        'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
        'freshness_validation_status', v_freshness_validation_status,
        'freshness_result_hash', v_freshness_result_hash,
        'freshness_scope_hash', v_freshness_scope_hash,
        'source', 'stored_chunked_freshness'
      );
      v_is_stale := false;
      v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
      v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
    else
      v_fresh := public.pay_batch_validate_freshness(
        p_pay_batch_id => p_pay_batch_id,
        p_actor_user_id => p_actor_user_id,
        p_allow_large_full_scan => false
      );

      v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
      v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      if v_is_stale = true then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
          'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
          'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_batch_export_csv_rows: chunked freshness validation is required before payment-initiation export' else 'pay_batch_export_csv_rows: batch is stale; regenerate draft before exporting' end,
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff', v_diff_sample,
          'freshness_validation_status', v_freshness_validation_status,
          'freshness_result_hash', v_freshness_result_hash,
          'freshness_scope_hash', v_freshness_scope_hash
        )::text;
      end if;
    end if;
  else
    v_fresh := jsonb_build_object(
      'is_stale', coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false),
      'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
      'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'source', 'stored_freshness_metadata_non_blocking'
    );
    v_is_stale := coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false);
    v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
    v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
  end if;

  create temp table if not exists _tmp_pay_export_rows (
    sort_surname text not null,
    sort_group int not null,
    sort_work_date date null,
    sort_timesheet_id uuid null,
    sort_line_rank int not null,
    sort_bucket_code text null,
    sort_unit_name text null,
    line_kind text not null,
    row_json jsonb not null
  ) on commit drop;

  truncate table _tmp_pay_export_rows;

  insert into _tmp_pay_export_rows(
    sort_surname,
    sort_group,
    sort_work_date,
    sort_timesheet_id,
    sort_line_rank,
    sort_bucket_code,
    sort_unit_name,
    line_kind,
    row_json
  )
  with
  net_latest as (
    select
      pbc.id as pay_batch_candidate_id,
      (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) as paye_net_amount
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  base as (
    select
      pbc.candidate_id as candidate_id,
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_tms_ref as candidate_tms_ref_snap,
      pbc.candidate_display_name as candidate_display_name_snap,

      c.first_name as cand_first_name,
      c.last_name as cand_last_name,
      c.tms_ref as cand_tms_ref_live,

      pbi.id as pay_batch_item_id,
      pbi.item_type as item_type,
      pbi.timesheet_id as timesheet_id,
      pbi.segment_key as segment_key,
      pbi.source_ref as source_ref,
      pbi.description as item_description,
      pbi.pay_channel as pay_channel,
      pbi.repayment_week_start as repayment_week_start,
      pbi.finance_case_id as finance_case_id,
      pbi.finance_component_id as finance_component_id,
      pbi.paye_treatment as paye_treatment,
      pbi.payout_instruction_snapshot_json as payout_instruction_snapshot_json,
      coalesce(pbi.frozen_component_snapshot_json, '{}'::jsonb) as frozen_component_snapshot_json,
      coalesce(pbi.frozen_source_basis_json, '{}'::jsonb) as frozen_source_basis_json,
      pbi.frozen_resolution_mode as frozen_resolution_mode,
      pbi.frozen_resolution_payload_json as frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json as frozen_resolution_result_json,
      pbi.frozen_source_amount as frozen_source_amount,
      pbi.frozen_target_amount_ex_vat as frozen_target_amount_ex_vat,
      pbi.pay_bank_transfer_id as pay_bank_transfer_id,
      pbt.status as payment_status_raw,
      pbt.rail_state as payment_rail_state,
      pbt.rail_provider as payment_provider,
      pbt.rail_env as payment_rail,
      pbt.rail_tx_id as payment_rail_tx_id,
      pbt.request_id as payment_request_id,
      pbt.completed_at_utc as payment_completed_at_utc,
      pbt.failed_reason as payment_failed_reason,
      coalesce(pbt.rail_meta_json, '{}'::jsonb) as payment_rail_meta_json,
      latest_event.provider_key as payment_event_provider_key,
      latest_event.provider_transaction_id as payment_provider_transaction_id,
      latest_event.provider_request_id as payment_provider_request_id,
      latest_event.provider_event_id as payment_provider_event_id,
      latest_event.provider_event_key as payment_provider_event_key,
      latest_event.provider_reference as payment_provider_reference,
      latest_event.normalised_state as payment_event_normalised_state,
      latest_event.provider_state as payment_event_provider_state,
      latest_event.event_time_utc as payment_event_time_utc,
      latest_event.received_at_utc as payment_event_received_at_utc,
      latest_event.provider_failure_reason_code as payment_provider_failure_reason_code,
      latest_event.provider_failure_reason_group as payment_provider_failure_reason_group,
      latest_event.correction_disposition as payment_action_review_status,

      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.units as units,
      pbib.rate as rate,
      pbib.amount_ex_vat as amount_ex_vat,
      pbib.amount_vat as amount_vat,
      pbib.amount_inc_vat as amount_inc_vat,
      coalesce(pbib.meta_json, '{}'::jsonb) as breakdown_meta_json,

      ecomp.key_type as economic_key_type,
      ecomp.key_value as economic_key_value,
      ecomp.source_amount_ex_vat as economic_source_amount_ex_vat,
      ecomp.target_amount_ex_vat as economic_target_amount_ex_vat,
      ecomp.key_resolution_source as economic_key_resolution_source,
      ecomp.key_resolution_failure_reason as economic_key_resolution_failure_reason,

      ts.week_ending_date as week_ending_date,
      ts.reference_number as reference_number,
      cl.id as client_id,
      cl.name as client_name,

      nl.paye_net_amount as paye_net_amount,

      segd.work_date as seg_work_date,

      vfcr.case_type as finance_case_type,
      vfcr.taxability as finance_taxability,
      vfcr.routing_kind as finance_routing_kind,
      vfcr.management_group as finance_management_group,
      vfcr.lifecycle_status_display as finance_lifecycle_status_display,
      vfcr.status as finance_status,
      vfcr.payout_status as finance_payout_status,
      vfcr.adjustment_comment as finance_adjustment_comment,
      vfcr.notes as finance_notes,
      vfcr.is_candidate_directed_oneoff_payout as is_candidate_directed_oneoff_payout,
      vfcr.appears_on_umbrella_remittance as appears_on_umbrella_remittance,
      vfcr.generates_candidate_payment_advice as generates_candidate_payment_advice,

      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_created_by_user_id,

      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_updated_by_user_id,

      tuc.display_name as bank_details_created_by_display_name,
      tuc.email as bank_details_created_by_email,
      tuu.display_name as bank_details_updated_by_display_name,
      tuu.email as bank_details_updated_by_email,

      case
        when coalesce(ecomp.key_type,'') = 'TS_DAY' and coalesce(ecomp.key_value,'') ~ '^\d{4}-\d{2}-\d{2}$' then ecomp.key_value::date
        else null::date
      end as economic_work_date,

      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_units','')), ''))::numeric
        else pbib.units
      end as source_units,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_units','')), ''))::numeric
        else pbib.units
      end as target_units,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_rate','')), ''))::numeric
        else pbib.rate
      end as source_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_rate','')), ''))::numeric
        else pbib.rate
      end as target_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_amount_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbib.meta_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_pay_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_pay_ex_vat','')), ''))::numeric
        else ecomp.source_amount_ex_vat
      end as source_amount_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_amount_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbib.meta_json->>'target_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_pay_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_pay_ex_vat','')), ''))::numeric
        else coalesce(ecomp.target_amount_ex_vat, pbib.amount_ex_vat)
      end as target_amount_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_charge_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_rate','')), ''))::numeric
        else null::numeric
      end as source_charge_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_charge_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_rate','')), ''))::numeric
        else null::numeric
      end as target_charge_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_charge_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_ex_vat','')), ''))::numeric
        else null::numeric
      end as source_charge_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_charge_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_ex_vat','')), ''))::numeric
        else null::numeric
      end as target_charge_ex_vat,
      coalesce(
        nullif(btrim(coalesce(pbib.meta_json->>'resolution_mode','')), ''),
        nullif(btrim(coalesce(pbi.frozen_resolution_mode::text,'')), ''),
        nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'resolution_mode','')), '')
      ) as resolution_mode,
      coalesce(
        nullif(pbib.meta_json->'resolution_payload_json', 'null'::jsonb),
        pbi.frozen_resolution_payload_json,
        nullif(pbi.frozen_component_snapshot_json->'resolution_payload_json', 'null'::jsonb),
        nullif(pbi.frozen_component_snapshot_json->'saved_resolution_payload_json', 'null'::jsonb)
      ) as resolution_payload_json,
      coalesce(
        nullif(pbib.meta_json->'resolution_result_json', 'null'::jsonb),
        pbi.frozen_resolution_result_json,
        nullif(pbi.frozen_component_snapshot_json->'resolution_result_json', 'null'::jsonb),
        nullif(pbi.frozen_component_snapshot_json->'saved_resolution_result_json', 'null'::jsonb)
      ) as resolution_result_json
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
     and pbc.pay_batch_id = p_pay_batch_id
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = pbi.id
    left join public._pay_batch_item_economic_components(p_pay_batch_id, null::uuid[]) ecomp
      on ecomp.pay_batch_item_id = pbi.id
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    left join lateral (
      select
        pbe.provider_key,
        pbe.provider_transaction_id,
        pbe.provider_request_id,
        pbe.provider_event_id,
        pbe.provider_event_key,
        pbe.provider_reference,
        pbe.normalised_state,
        pbe.provider_state,
        pbe.event_time_utc,
        pbe.received_at_utc,
        pbe.provider_failure_reason_code,
        pbe.provider_failure_reason_group,
        pbe.correction_disposition
      from public.pay_bank_transfer_events pbe
      where pbe.pay_batch_id = p_pay_batch_id
        and pbe.pay_bank_transfer_id = pbt.id
      order by coalesce(pbe.event_time_utc, pbe.received_at_utc, pbe.created_at_utc) desc nulls last,
               pbe.id desc
      limit 1
    ) latest_event on true
    left join public.candidates c
      on c.id = pbc.candidate_id
    left join public.timesheets ts
      on ts.timesheet_id = pbi.timesheet_id
     and ts.is_current = true
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cl
      on cl.id = ct.client_id
    left join net_latest nl
      on nl.pay_batch_candidate_id = pbc.id
    left join public.pay_batch_timesheet_snapshots pbts
      on pbts.pay_batch_id = p_pay_batch_id
     and pbts.timesheet_id = pbi.timesheet_id
     and pbts.candidate_id = pbc.candidate_id
     and upper(coalesce(pbts.pay_channel,'')) = upper(coalesce(pbi.pay_channel,''))
    left join lateral (
      select
        nullif(btrim(coalesce(seg->>'date','')),'')::date as work_date
      from jsonb_array_elements(coalesce(pbts.target_snapshot_json->'segments','[]'::jsonb)) seg
      where pbi.item_type = 'SEGMENT_DELTA'
        and seg is not null
        and jsonb_typeof(seg) = 'object'
        and nullif(btrim(coalesce(seg->>'segment_id','')),'') = coalesce(
          nullif(btrim(coalesce(pbi.segment_key,'')), ''),
          case
            when pbi.source_ref is not null and btrim(coalesce(pbi.source_ref,'')) like 'seg:%'
              then nullif(btrim(split_part(pbi.source_ref,':',2)),'')
            else null
          end
        )
        and nullif(btrim(coalesce(seg->>'date','')),'') ~ '^\d{4}-\d{2}-\d{2}$'
      limit 1
    ) segd on true
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    left join public.tms_users tuc
      on tuc.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end
    left join public.tms_users tuu
      on tuu.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end
    where pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
  ),
  rows0 as (
    select
      coalesce(
        nullif(btrim(coalesce(b.cand_last_name,'')), ''),
        nullif(btrim(regexp_replace(coalesce(b.candidate_display_name_snap,''), '^.*\s', '')), ''),
        nullif(btrim(coalesce(b.candidate_display_name_snap,'')), ''),
        b.candidate_id::text
      ) as sort_surname,

      case
        when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 3
        when b.timesheet_id is null then 2
        else 1
      end as sort_group,

      coalesce(b.economic_work_date, b.seg_work_date, b.week_ending_date, b.repayment_week_start) as sort_work_date,

      b.timesheet_id as sort_timesheet_id,

      case
        when b.item_type = 'OVERPAYMENT_RECOVERY' then 900
        when b.item_type = 'LOAN_REPAYMENT' then 910
        when b.item_type = 'MANUAL_DEBT_RECOVERY' then 915
        when b.item_type = 'LOAN_PAYOUT' then 920
        when b.item_type = 'UNDERPAYMENT_PAYMENT' then 925
        when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 930
        else case upper(coalesce(b.line_kind,''))
          when 'TS_BUCKET' then 100
          when 'ADDITIONAL_UNIT' then 200
          when 'MILEAGE' then 300
          when 'EXPENSE' then 400
          when 'ADJUSTMENT' then 500
          when 'CONVERSION_ADJ' then 600
          when 'DEBT_CREATED' then 950
          else 800
        end
      end as sort_line_rank,

      upper(nullif(btrim(coalesce(b.bucket_code,'')),'')) as sort_bucket_code,
      nullif(btrim(coalesce(b.unit_name,'')),'') as sort_unit_name,

      case
        when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
        when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
        when b.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
        when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
        when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
        when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
        else upper(coalesce(b.line_kind,''))
      end as line_kind,

      jsonb_strip_nulls(
        jsonb_build_object(
          'candidate_id', b.candidate_id::text,
          'candidate_tms_ref', coalesce(
            nullif(btrim(coalesce(b.candidate_tms_ref_snap,'')), ''),
            nullif(btrim(coalesce(b.cand_tms_ref_live,'')), ''),
            null
          ),
          'candidate_first_name', nullif(btrim(coalesce(b.cand_first_name,'')), ''),
          'candidate_last_name', nullif(btrim(coalesce(b.cand_last_name,'')), ''),
          'candidate_display_name', nullif(btrim(coalesce(b.candidate_display_name_snap,'')), ''),
          'client_id', case when b.client_id is null then null else b.client_id::text end,
          'client_name', b.client_name,
          'timesheet_id', case when b.timesheet_id is null then null else b.timesheet_id::text end,
          'week_ending_date', case when b.week_ending_date is null then null else b.week_ending_date::text end,
          'work_date', case
            when b.economic_work_date is not null then b.economic_work_date::text
            when b.seg_work_date is not null then b.seg_work_date::text
            when b.week_ending_date is not null then b.week_ending_date::text
            when b.repayment_week_start is not null then b.repayment_week_start::text
            else null
          end,
          'reference_number', b.reference_number,
          'pay_channel', upper(coalesce(b.pay_channel,'')),
          'pay_method', upper(coalesce(b.pay_channel,'')),
          'item_type', b.item_type,
          'item_type_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            else null
          end,
          'payment_or_deduction', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 'DEDUCTION'
            when b.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT') then 'PAYMENT'
            when coalesce(b.amount_ex_vat, 0) < 0 then 'DEDUCTION'
            when coalesce(b.amount_ex_vat, 0) > 0 then 'PAYMENT'
            else 'ZERO'
          end,
          'finance_case_id', case when b.finance_case_id is null then null else b.finance_case_id::text end,
          'finance_case_reference', case when b.finance_case_id is null then null else b.finance_case_id::text end,
          'finance_component_id', case when b.finance_component_id is null then null else b.finance_component_id::text end,
          'finance_case_type', case when b.finance_case_type is null then null else b.finance_case_type::text end,
          'finance_management_group', b.finance_management_group,
          'lifecycle_status', b.finance_lifecycle_status_display,
          'finance_status', case when b.finance_status is null then null else b.finance_status::text end,
          'finance_payout_status', case when b.finance_payout_status is null then null else b.finance_payout_status::text end,
          'taxability', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'taxability','')), ''),
          'routing_kind', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '')
        )
        || jsonb_build_object(
          'payout_destination', coalesce(
            nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'destination_label','')), ''),
            case
              when nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
              when nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'UMBRELLA_COMPANY' then 'umbrella company'
              when upper(coalesce(b.pay_channel,'')) = 'PAYE' then 'normal PAYE route'
              when upper(coalesce(b.pay_channel,'')) = 'UMBRELLA' then 'umbrella company'
              else null
            end
          ),
          'sort_code', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'sort_code','')), ''),
          'account_number', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'account_number','')), ''),
          'destination_group_key', concat_ws(
            '|',
            upper(coalesce(b.pay_channel,'')),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'payee_entity_kind','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'payee_entity_id','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'beneficiary_name','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'sort_code','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'account_number','')), ''), '')
          ),
          'masked_bank_account', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
          'masked_bank_account_paid_to', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
          'beneficiary_name', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
          'bank_details_hash', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
          'bank_details_note', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'bank_details_note','')), ''),
          'bank_details_created_by_user_id', case when b.bank_details_created_by_user_id is null then null else b.bank_details_created_by_user_id::text end,
          'bank_details_created_by', coalesce(
            nullif(btrim(coalesce(b.bank_details_created_by_display_name,'')), ''),
            nullif(btrim(coalesce(b.bank_details_created_by_email,'')), ''),
            case when b.bank_details_created_by_user_id is null then null else b.bank_details_created_by_user_id::text end
          ),
          'bank_details_updated_by_user_id', case when b.bank_details_updated_by_user_id is null then null else b.bank_details_updated_by_user_id::text end,
          'bank_details_updated_by', coalesce(
            nullif(btrim(coalesce(b.bank_details_updated_by_display_name,'')), ''),
            nullif(btrim(coalesce(b.bank_details_updated_by_email,'')), ''),
            case when b.bank_details_updated_by_user_id is null then null else b.bank_details_updated_by_user_id::text end
          ),
          'appears_on_umbrella_remittance', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','')), '')) in ('true','t','1','yes','y')), false),
          'generates_candidate_payment_advice', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','')), '')) in ('true','t','1','yes','y')), false),
          'is_candidate_directed_oneoff_payout', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout','')), '')) in ('true','t','1','yes','y')), false),
          'line_kind', case
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when b.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
            else b.line_kind
          end,
          'line_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when nullif(btrim(coalesce(b.unit_name,'')), '') is not null then b.unit_name
            when nullif(btrim(coalesce(b.line_kind,'')), '') is not null then b.line_kind
            else b.item_type
          end,
          'friendly_line_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when upper(coalesce(b.line_kind,'')) = 'TS_BUCKET' then case upper(coalesce(b.bucket_code,''))
              when 'DAY' then 'Day'
              when 'NIGHT' then 'Night'
              when 'SAT' then 'Sat'
              when 'SUN' then 'Sun'
              when 'BH' then 'BH'
              else coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Hours')
            end
            when upper(coalesce(b.line_kind,'')) = 'ADDITIONAL_UNIT' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Additional unit')
            when upper(coalesce(b.line_kind,'')) = 'MILEAGE' then 'Mileage'
            when upper(coalesce(b.line_kind,'')) = 'EXPENSE' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Expense')
            when upper(coalesce(b.line_kind,'')) = 'ADJUSTMENT' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Adjustment')
            when upper(coalesce(b.line_kind,'')) = 'CONVERSION_ADJ' then 'Conversion adjustment'
            when nullif(btrim(coalesce(b.unit_name,'')), '') is not null then b.unit_name
            when nullif(btrim(coalesce(b.line_kind,'')), '') is not null then b.line_kind
            else b.item_type
          end,
          'row_group', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 'DEDUCTION'
            when b.timesheet_id is null then 'NON_TIMESHEET'
            else 'TIMESHEET'
          end,
          'is_non_timesheet_line', (b.timesheet_id is null),
          'bucket_code', b.bucket_code,
          'unit_name', b.unit_name,
          'units', b.units,
          'rate', b.rate,
          'amount_ex_vat', b.amount_ex_vat,
          'amount_vat', b.amount_vat
        )
        || jsonb_build_object(
          'amount_inc_vat', b.amount_inc_vat,
          'economic_key_type', b.economic_key_type,
          'economic_key_value', b.economic_key_value,
          'key_type', b.economic_key_type,
          'key_value', b.economic_key_value,
          'key_resolution_source', b.economic_key_resolution_source,
          'key_resolution_failure_reason', b.economic_key_resolution_failure_reason,
          'source_units', b.source_units,
          'target_units', b.target_units,
          'source_rate', b.source_rate,
          'target_rate', b.target_rate,
          'source_amount_ex_vat', b.source_amount_ex_vat,
          'target_amount_ex_vat', b.target_amount_ex_vat,
          'target_amount_paid_ex_vat', b.target_amount_ex_vat,
          'source_charge_rate', b.source_charge_rate,
          'target_charge_rate', b.target_charge_rate,
          'source_charge_ex_vat', b.source_charge_ex_vat,
          'target_charge_ex_vat', b.target_charge_ex_vat,
          'resolution_mode', b.resolution_mode,
          'resolution_payload_json', b.resolution_payload_json,
          'resolution_result_json', b.resolution_result_json,
          'source_target_detail', jsonb_strip_nulls(jsonb_build_object(
            'source_units', b.source_units,
            'target_units', b.target_units,
            'source_rate', b.source_rate,
            'target_rate', b.target_rate,
            'source_amount_ex_vat', b.source_amount_ex_vat,
            'target_amount_ex_vat', b.target_amount_ex_vat,
            'source_charge_rate', b.source_charge_rate,
            'target_charge_rate', b.target_charge_rate,
            'source_charge_ex_vat', b.source_charge_ex_vat,
            'target_charge_ex_vat', b.target_charge_ex_vat,
            'economic_key_type', b.economic_key_type,
            'economic_key_value', b.economic_key_value,
            'resolution_mode', b.resolution_mode
          )),
          'signed_amount_ex_vat', b.amount_ex_vat,
          'signed_amount_inc_vat', b.amount_inc_vat,
          'amount_sign', case
            when coalesce(b.amount_ex_vat, 0) < 0 then 'NEGATIVE'
            when coalesce(b.amount_ex_vat, 0) > 0 then 'POSITIVE'
            else 'ZERO'
          end,
          'is_overpayment_recovery', (b.item_type = 'OVERPAYMENT_RECOVERY'),
          'is_loan_repayment', (b.item_type = 'LOAN_REPAYMENT'),
          'is_manual_debt_recovery', (b.item_type = 'MANUAL_DEBT_RECOVERY'),
          'is_underpayment_payment', (b.item_type = 'UNDERPAYMENT_PAYMENT'),
          'deduction_kind', case
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_ADJUSTMENT'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            else null
          end,
          'deduction_amount_ex_vat', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(b.amount_ex_vat,0)),2)
            else null
          end,
          'deduction_amount_inc_vat', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(b.amount_inc_vat,0)),2)
            else null
          end,
          'paye_net_amount', case
            when upper(coalesce(b.pay_channel,'')) = 'PAYE' then b.paye_net_amount
            else null
          end,
          'paye_treatment', b.paye_treatment,
          'adjustment_comment', b.finance_adjustment_comment,
          'note', coalesce(b.finance_notes, b.item_description),
          'comment_or_note', coalesce(b.finance_adjustment_comment, b.finance_notes, b.item_description),
          'description', b.item_description,
          'source_ref', b.source_ref,
          'repayment_week_start', case when b.repayment_week_start is null then null else b.repayment_week_start::text end
        )
        || jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN b.pay_bank_transfer_id IS NULL THEN NULL ELSE b.pay_bank_transfer_id::text END,
          'payment_status_raw', b.payment_status_raw,
          'payment_status_label', CASE
            WHEN v_pre_execution_export
             AND UPPER(BTRIM(COALESCE(v_batch_status_raw, ''))) IN ('DRAFT', 'DRAFT_CREATED')
             AND b.pay_bank_transfer_id IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_status_raw, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_rail_state, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_rail_tx_id, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_request_id, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_provider_transaction_id, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_provider_request_id, '')), '') IS NULL
              THEN 'Not yet submitted'
            ELSE public._pay_bank_transfer_status_display_label(
              b.payment_status_raw,
              b.payment_rail_state,
              CASE
                WHEN (
              UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
              OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
              OR (
                b.payment_completed_at_utc IS NOT NULL
                AND UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                AND UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              )
            ) THEN 'FINAL_PAID'
                WHEN (
              UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            ) THEN 'TERMINAL_NO_MONEY'
                ELSE NULL::text
              END
            )
          END,
          'rail_state', b.payment_rail_state,
          'payment_terminal_success', (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
            OR (
              b.payment_completed_at_utc IS NOT NULL
              AND UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              AND UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            )
          ),
          'payment_terminal_failed', (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ),
          'payment_terminal', (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR b.payment_completed_at_utc IS NOT NULL
          ),
          'provider', COALESCE(b.payment_provider, b.payment_event_provider_key),
          'rail', b.payment_rail,
          'rail_tx_id', NULLIF(BTRIM(COALESCE(b.payment_rail_tx_id, '')), ''),
          'provider_transaction_id', NULLIF(BTRIM(COALESCE(b.payment_provider_transaction_id, b.payment_rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', b.payment_rail_meta_json #>> '{provider_transaction_id}', '')), ''),
          'provider_request_id', NULLIF(BTRIM(COALESCE(b.payment_provider_request_id, b.payment_rail_meta_json #>> '{provider_submit_diagnostic,request_id}', b.payment_request_id, '')), ''),
          'payment_completed_at_utc', CASE WHEN b.payment_completed_at_utc IS NULL THEN NULL ELSE b.payment_completed_at_utc::text END,
          'payment_failed_at_utc', CASE WHEN UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT') OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','CANCELLED','CANCELED') THEN COALESCE(b.payment_event_time_utc, b.payment_event_received_at_utc)::text ELSE NULL::text END,
          'payment_returned_at_utc', CASE WHEN UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('RETURNED','REVERTED') OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('RETURNED','REVERTED') THEN COALESCE(b.payment_event_time_utc, b.payment_event_received_at_utc)::text ELSE NULL::text END,
          'payment_terminal_at_utc', CASE
            WHEN (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
            OR (
              b.payment_completed_at_utc IS NOT NULL
              AND UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              AND UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            )
          ) THEN COALESCE(b.payment_completed_at_utc, b.payment_event_time_utc, b.payment_event_received_at_utc)::text
            WHEN (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ) THEN COALESCE(b.payment_event_time_utc, b.payment_event_received_at_utc, b.payment_completed_at_utc)::text
            ELSE NULL::text
          END,
          'action_review_status', b.payment_action_review_status,
          'provider_failure_reason_code', b.payment_provider_failure_reason_code,
          'provider_failure_reason_group', b.payment_provider_failure_reason_group
        )
      ) as row_json
    from base b
  )
  select
    r.sort_surname,
    r.sort_group,
    r.sort_work_date,
    r.sort_timesheet_id,
    r.sort_line_rank,
    r.sort_bucket_code,
    r.sort_unit_name,
    r.line_kind,
    r.row_json
  from rows0 r;

  select count(*)::int
  into v_row_count
  from _tmp_pay_export_rows;

  select coalesce(
    jsonb_object_agg(t.lk, t.ct),
    '{}'::jsonb
  )
  into v_kind_counts
  from (
    select
      coalesce(nullif(btrim(coalesce(per.line_kind,'')),'') , 'UNKNOWN') as lk,
      count(*)::int as ct
    from _tmp_pay_export_rows per
    group by coalesce(nullif(btrim(coalesce(per.line_kind,'')),'') , 'UNKNOWN')
  ) t;

  select coalesce(
    jsonb_agg(
      per.row_json
      order by
        per.sort_surname asc,
        per.sort_group asc,
        per.sort_work_date asc nulls last,
        per.sort_timesheet_id asc nulls last,
        per.sort_line_rank asc,
        per.sort_bucket_code asc nulls last,
        per.sort_unit_name asc nulls last
    ),
    '[]'::jsonb
  )
  into v_rows
  from _tmp_pay_export_rows per;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_EXPORT_CSV_ROWS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'row_count', v_row_count,
        'line_kind_counts', v_kind_counts,
        'is_cancelled', v_is_cancelled,
        'is_stale', v_is_stale,
        'stale_reasons', v_stale_reasons
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'batch', jsonb_build_object(
      'id', v_batch.id::text,
      'status', v_batch.status,
      'batch_status_raw', v_batch_status_raw,
      'batch_status_label', v_batch_status_label,
      'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_execution_committed_at_utc IS NULL THEN NULL ELSE v_execution_committed_at_utc::text END,
      'completed_at_utc', CASE WHEN v_completed_at_utc IS NULL THEN NULL ELSE v_completed_at_utc::text END,
      'finalised_at_utc', CASE WHEN v_completed_at_utc IS NULL THEN NULL ELSE v_completed_at_utc::text END,
      'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
      'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
      'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
      'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
      'pay_date', case when v_batch.pay_date is null then null else v_batch.pay_date::text end,
      'batch_kind', v_batch_kind,
      'batch_kind_fixed', case when v_batch.batch_kind_fixed is null then null else v_batch.batch_kind_fixed end,
      'is_cancelled', v_is_cancelled,
      'generated_at_utc', v_now_utc::text
    ),
    'freshness', jsonb_build_object(
      'is_stale', v_is_stale,
      'stale_reasons', v_stale_reasons,
      'diff_sample', v_diff_sample,
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'freshness_operation_id', case when v_batch.freshness_operation_id is null then null else v_batch.freshness_operation_id::text end,
      'source', coalesce(v_fresh->>'source', case when v_pre_execution_export then 'legacy_or_stored_pre_execution' else 'stored_freshness_metadata_non_blocking' end)
    ),
    'summary', jsonb_build_object(
      'row_count', v_row_count,
      'line_kind_counts', v_kind_counts
    ),
    'rows', v_rows
  );
end;
$function$;

-- pay_batch_finalize_reservations_and_markers(uuid,text,uuid,date,date,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_finalize_reservations_and_markers(p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid DEFAULT NULL::uuid, p_pay_date date DEFAULT NULL::date, p_week_start date DEFAULT NULL::date, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope text := UPPER(BTRIM(COALESCE(p_pay_channel_scope, '')));
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_week_start date := p_week_start;
  v_candidate_rows_before_empty_delete integer := 0;
  v_candidate_rows_after_empty_delete integer := 0;
  v_deleted_candidate_rows integer := 0;
  v_awaiting_net_rows_updated integer := 0;
  v_reservations_created integer := 0;
  v_reservations_reused integer := 0;
  v_invalid_item_sample jsonb := '[]'::jsonb;
  v_overrun_sample jsonb := '[]'::jsonb;
  v_reservation_check_component_count integer := 0;
  v_reservation_requested_amount_ex_vat numeric := 0;
  v_reservation_outstanding_before_batch_ex_vat numeric := 0;
  v_summary_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_summary_chunk_ids uuid[] := ARRAY[]::uuid[];
  v_summary_offset integer := 1;
  v_summary_total integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'p_operation_id is required for row-backed draft finalisation';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'p_actor_user_id is required for row-backed draft finalisation';
  END IF;

  IF p_candidate_scope_ids IS NULL OR jsonb_typeof(v_scope_ids) <> 'array' OR jsonb_array_length(v_scope_ids) = 0 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array';
  END IF;

  v_scope_id_count := jsonb_array_length(v_scope_ids);

  IF v_scope_id_count > 100 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids exceeds the 100 row cap: %', v_scope_id_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  ) THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must contain UUID strings only';
  END IF;

  IF v_week_start IS NULL THEN
    v_week_start := public._pay_week_start_monday(COALESCE(p_pay_date, (SELECT batch_row.pay_date FROM public.pay_batches AS batch_row WHERE batch_row.id = p_pay_batch_id)));
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_finalize_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_finalize_scope ON COMMIT DROP AS
  SELECT scope_row.*
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND scope_row.pay_channel = v_scope
    AND scope_row.id IN (
      SELECT (supplied_scope.scope_value #>> '{}')::uuid
      FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    )
  ORDER BY scope_row.chunk_sequence NULLS LAST, scope_row.candidate_id, scope_row.id;

  IF (SELECT COUNT(*)::integer FROM pg_temp.tmp_pay_batch_finalize_scope) <> v_scope_id_count THEN
    RAISE EXCEPTION 'one or more candidate scope ids do not belong to operation %, batch %, and scope %', p_operation_id, p_pay_batch_id, v_scope;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_candidate_rows_before_empty_delete
  FROM public.pay_batch_candidates AS candidate_before
  WHERE candidate_before.pay_batch_id = p_pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row
      WHERE scope_row.candidate_id = candidate_before.candidate_id
    );

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'FINALISE_RESERVATIONS','REGISTER',
    jsonb_build_array(
      jsonb_build_object('relation_name','pay_batch_candidates','operation','DELETE'),
      jsonb_build_object('relation_name','pay_advance_reservations','operation','INSERT'),
      jsonb_build_object('relation_name','pay_advance_reservations','operation','UPDATE'),
      jsonb_build_object('relation_name','pay_batch_items','operation','UPDATE')
    ),jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  DELETE FROM public.pay_batch_candidates AS candidate_delete
  WHERE candidate_delete.pay_batch_id = p_pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row
      WHERE scope_row.candidate_id = candidate_delete.candidate_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_batch_items AS item_check
      WHERE item_check.pay_batch_candidate_id = candidate_delete.id
        AND COALESCE(item_check.is_voided, false) = false
        AND item_check.item_type <> 'DEBT_CREATED'
    );
  GET DIAGNOSTICS v_deleted_candidate_rows = ROW_COUNT;

  SELECT COUNT(*)::integer
  INTO v_candidate_rows_after_empty_delete
  FROM public.pay_batch_candidates AS candidate_after
  WHERE candidate_after.pay_batch_id = p_pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row
      WHERE scope_row.candidate_id = candidate_after.candidate_id
    );

  IF COALESCE(v_candidate_rows_after_empty_delete, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'nothing_payable_after_reservation_exclusion', true,
      'message', 'Nothing to pay for this bounded scope after blockers and reservation availability checks.',
      'candidate_rows_before_empty_delete', COALESCE(v_candidate_rows_before_empty_delete, 0),
      'deleted_candidate_rows', COALESCE(v_deleted_candidate_rows, 0),
      'candidate_rows_after_empty_delete', COALESCE(v_candidate_rows_after_empty_delete, 0)
    );
  END IF;

  WITH scoped_items AS (
    SELECT pay_batch_item.id AS pay_batch_item_id,
           pay_batch_item.timesheet_id,
           pay_batch_item.item_type,
           economic_component.key_type,
           economic_component.key_value,
           economic_component.source_amount_ex_vat,
           economic_component.key_resolution_failure_reason,
           NULLIF(BTRIM(COALESCE(
             pay_batch_item.frozen_source_basis_json->>'source_family_key',
             pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
             ''
           )), '') AS source_family_key,
           COALESCE(
             pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
             pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
           ) AS correction_chain_residual
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      ON allocation_row.pay_batch_item_id = pay_batch_item.id
     AND allocation_row.operation_id = p_operation_id
    JOIN LATERAL public._pay_batch_item_economic_components(NULL::uuid, ARRAY[pay_batch_item.id]::uuid[]) AS economic_component
      ON true
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND allocation_row.candidate_scope_id IN (SELECT finalize_scope.id FROM pg_temp.tmp_pay_batch_finalize_scope AS finalize_scope)
      AND pay_batch_item.timesheet_id IS NOT NULL
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND pay_batch_item.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
  ), invalid_items AS (
    SELECT scoped_items.*,
           CASE
             WHEN scoped_items.key_resolution_failure_reason IS NOT NULL THEN scoped_items.key_resolution_failure_reason
             WHEN scoped_items.key_type IS NULL OR BTRIM(COALESCE(scoped_items.key_type, '')) = '' THEN 'MISSING_ECONOMIC_KEY_TYPE'
             WHEN scoped_items.key_value IS NULL OR BTRIM(COALESCE(scoped_items.key_value, '')) = '' THEN 'MISSING_ECONOMIC_KEY_VALUE'
             WHEN scoped_items.key_type = 'TS_DAY' AND scoped_items.key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN 'INVALID_TS_DAY_KEY_VALUE'
             WHEN scoped_items.source_amount_ex_vat IS NULL THEN 'MISSING_SOURCE_RESERVATION_AMOUNT'
             WHEN scoped_items.source_family_key LIKE 'correction-chain:%'
              AND jsonb_typeof(scoped_items.correction_chain_residual) IS DISTINCT FROM 'object'
               THEN 'MISSING_FROZEN_CORRECTION_CHAIN_RESIDUAL'
             WHEN scoped_items.source_family_key LIKE 'correction-chain:%'
              AND NOT EXISTS (
                SELECT 1
                FROM jsonb_array_elements(
                  CASE
                    WHEN jsonb_typeof(scoped_items.correction_chain_residual->'components') = 'array'
                      THEN scoped_items.correction_chain_residual->'components'
                    ELSE '[]'::jsonb
                  END
                ) AS frozen_component(component_json)
                WHERE UPPER(BTRIM(COALESCE(frozen_component.component_json->>'component_key_type', ''))) = scoped_items.key_type
                  AND BTRIM(COALESCE(frozen_component.component_json->>'component_key_value', '')) = scoped_items.key_value
                  AND COALESCE(frozen_component.component_json->>'effective_source_outstanding_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              )
               THEN 'MISSING_FROZEN_CORRECTION_CHAIN_COMPONENT'
             ELSE NULL::text
           END AS failure_reason
    FROM scoped_items
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'pay_batch_item_id', invalid_items.pay_batch_item_id::text,
           'timesheet_id', invalid_items.timesheet_id::text,
           'item_type', invalid_items.item_type,
           'key_type', invalid_items.key_type,
           'key_value', invalid_items.key_value,
           'source_amount_ex_vat', invalid_items.source_amount_ex_vat,
           'source_family_key', invalid_items.source_family_key,
           'failure_reason', invalid_items.failure_reason
         ) ORDER BY invalid_items.pay_batch_item_id::text), '[]'::jsonb)
  INTO v_invalid_item_sample
  FROM invalid_items
  WHERE invalid_items.failure_reason IS NOT NULL
  LIMIT 25;

  IF jsonb_array_length(COALESCE(v_invalid_item_sample, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_ITEM_ECONOMIC_KEY_OR_SOURCE_RESOLUTION_FAILED',
      'pay_batch_id', p_pay_batch_id::text,
      'items', v_invalid_item_sample
    )::text;
  END IF;

  WITH scoped_item_components AS (
    SELECT economic_component.timesheet_id,
           economic_component.key_type,
           economic_component.key_value,
           economic_component.source_amount_ex_vat,
           economic_component.target_amount_ex_vat,
           CASE
             WHEN COALESCE(resolved_component.component_json->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               THEN ROUND((resolved_component.component_json->>'source_pay_ex_vat')::numeric, 2)
             ELSE NULL::numeric
           END AS resolved_source_amount_ex_vat,
           CASE
             WHEN COALESCE(
                    resolved_component.component_json->>'ready_preview_amount_ex_vat',
                    resolved_component.component_json->>'target_pay_ex_vat',
                    resolved_component.component_json->>'target_amount_ex_vat',
                    ''
                  ) ~ '^-?[0-9]+(\.[0-9]+)?$'
               THEN ROUND(COALESCE(
                 resolved_component.component_json->>'ready_preview_amount_ex_vat',
                 resolved_component.component_json->>'target_pay_ex_vat',
                 resolved_component.component_json->>'target_amount_ex_vat'
               )::numeric, 2)
             ELSE NULL::numeric
           END AS resolved_target_amount_ex_vat,
           (
             resolved_component.component_json IS NOT NULL
             AND LOWER(BTRIM(COALESCE(resolved_component.component_json->>'is_resolution_stale', 'false'))) NOT IN ('true','t','1','yes','y','on')
             AND LOWER(BTRIM(COALESCE(resolved_component.component_json->>'is_stale_saved_resolution', 'false'))) NOT IN ('true','t','1','yes','y','on')
             AND LOWER(BTRIM(COALESCE(resolved_component.component_json->>'requires_resolution', 'true'))) IN ('false','f','0','no','n','off')
             AND NULLIF(BTRIM(COALESCE(resolved_component.component_json->>'component_fingerprint', '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(resolved_component.component_json->>'source_basis_fingerprint', '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(resolved_component.component_json->>'resolved_rate_resolution_id', '')), '') IS NOT NULL
           ) AS resolved_component_is_fresh,
           NULLIF(BTRIM(COALESCE(
             pay_batch_item.frozen_source_basis_json->>'source_family_key',
             pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
             ''
           )), '') AS source_family_key,
           frozen_chain_component.component_json AS correction_chain_component
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      ON allocation_row.pay_batch_item_id = pay_batch_item.id
     AND allocation_row.operation_id = p_operation_id
    JOIN LATERAL public._pay_batch_item_economic_components(NULL::uuid, ARRAY[pay_batch_item.id]::uuid[]) AS economic_component
      ON true
    LEFT JOIN LATERAL (
      SELECT jsonb_build_object(
               'source_pay_ex_vat',
               ROUND(SUM(
                 CASE
                   WHEN COALESCE(frozen_resolution_component.component_json->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                     THEN (frozen_resolution_component.component_json->>'source_pay_ex_vat')::numeric
                   ELSE NULL::numeric
                 END
               ), 2),
               'ready_preview_amount_ex_vat',
               ROUND(SUM(
                 CASE
                   WHEN COALESCE(
                          frozen_resolution_component.component_json->>'ready_preview_amount_ex_vat',
                          frozen_resolution_component.component_json->>'target_pay_ex_vat',
                          frozen_resolution_component.component_json->>'target_amount_ex_vat',
                          ''
                        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
                     THEN COALESCE(
                            frozen_resolution_component.component_json->>'ready_preview_amount_ex_vat',
                            frozen_resolution_component.component_json->>'target_pay_ex_vat',
                            frozen_resolution_component.component_json->>'target_amount_ex_vat'
                          )::numeric
                   ELSE NULL::numeric
                 END
               ), 2),
               'is_resolution_stale',
               BOOL_OR(
                 LOWER(BTRIM(COALESCE(frozen_resolution_component.component_json->>'is_resolution_stale', 'false')))
                   IN ('true','t','1','yes','y','on')
               ),
               'is_stale_saved_resolution',
               BOOL_OR(
                 LOWER(BTRIM(COALESCE(frozen_resolution_component.component_json->>'is_stale_saved_resolution', 'false')))
                   IN ('true','t','1','yes','y','on')
               ),
               'requires_resolution',
               NOT (
                 LOWER(BTRIM(COALESCE(
                   pay_batch_item.frozen_resolution_payload_json->>'has_resolved_rate',
                   pay_batch_item.frozen_resolution_payload_json#>>'{case_resolution_summary,has_resolved_rate}',
                   'false'
                 ))) IN ('true','t','1','yes','y','on')
                 AND LOWER(BTRIM(COALESCE(
                   pay_batch_item.frozen_resolution_payload_json->>'case_resolution_satisfied_now',
                   pay_batch_item.frozen_resolution_payload_json#>>'{case_resolution_summary,case_resolution_satisfied_now}',
                   'false'
                 ))) IN ('true','t','1','yes','y','on')
                 AND BOOL_AND(
                   LOWER(BTRIM(COALESCE(frozen_resolution_component.component_json->>'requires_resolution', 'true')))
                     IN ('false','f','0','no','n','off')
                 )
                 AND BOOL_AND(
                   COALESCE(frozen_resolution_component.component_json->>'source_pay_ex_vat', '')
                     ~ '^-?[0-9]+(\.[0-9]+)?$'
                 )
                 AND BOOL_AND(
                   COALESCE(
                     frozen_resolution_component.component_json->>'ready_preview_amount_ex_vat',
                     frozen_resolution_component.component_json->>'target_pay_ex_vat',
                     frozen_resolution_component.component_json->>'target_amount_ex_vat',
                     ''
                   ) ~ '^-?[0-9]+(\.[0-9]+)?$'
                 )
               ),
               'component_fingerprint',
               CASE
                 WHEN BOOL_AND(NULLIF(BTRIM(COALESCE(frozen_resolution_component.component_json->>'component_fingerprint', '')), '') IS NOT NULL)
                   THEN md5(string_agg(
                     frozen_resolution_component.component_json->>'component_fingerprint',
                     '|' ORDER BY frozen_resolution_component.component_json->>'resolved_rate_resolution_id'
                   ))
                 ELSE NULL::text
               END,
               'source_basis_fingerprint',
               CASE
                 WHEN BOOL_AND(NULLIF(BTRIM(COALESCE(frozen_resolution_component.component_json->>'source_basis_fingerprint', '')), '') IS NOT NULL)
                   THEN md5(string_agg(
                     frozen_resolution_component.component_json->>'source_basis_fingerprint',
                     '|' ORDER BY frozen_resolution_component.component_json->>'resolved_rate_resolution_id'
                   ))
                 ELSE NULL::text
               END,
               'resolved_rate_resolution_id',
               md5(string_agg(
                 frozen_resolution_component.component_json->>'resolved_rate_resolution_id',
                 '|' ORDER BY frozen_resolution_component.component_json->>'resolved_rate_resolution_id'
               ))
             ) AS component_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(pay_batch_item.frozen_resolution_payload_json->'case_components') = 'array'
            THEN pay_batch_item.frozen_resolution_payload_json->'case_components'
          ELSE '[]'::jsonb
        END
      ) AS frozen_resolution_component(component_json)
      WHERE UPPER(BTRIM(COALESCE(frozen_resolution_component.component_json->>'component_key_type', ''))) = economic_component.key_type
        AND BTRIM(COALESCE(frozen_resolution_component.component_json->>'component_key_value', '')) = economic_component.key_value
        AND NULLIF(BTRIM(COALESCE(frozen_resolution_component.component_json->>'resolved_rate_resolution_id', '')), '') IS NOT NULL
      HAVING COUNT(*) > 0
    ) AS resolved_component
      ON true
    LEFT JOIN LATERAL (
      SELECT frozen_component.component_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(
            pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
            pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
          )->'components') = 'array'
            THEN COALESCE(
              pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
              pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
            )->'components'
          ELSE '[]'::jsonb
        END
      ) AS frozen_component(component_json)
      WHERE UPPER(BTRIM(COALESCE(frozen_component.component_json->>'component_key_type', ''))) = economic_component.key_type
        AND BTRIM(COALESCE(frozen_component.component_json->>'component_key_value', '')) = economic_component.key_value
      LIMIT 1
    ) AS frozen_chain_component
      ON NULLIF(BTRIM(COALESCE(
           pay_batch_item.frozen_source_basis_json->>'source_family_key',
           pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
           ''
         )), '') LIKE 'correction-chain:%'
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND allocation_row.candidate_scope_id IN (SELECT finalize_scope.id FROM pg_temp.tmp_pay_batch_finalize_scope AS finalize_scope)
      AND economic_component.timesheet_id IS NOT NULL
      AND economic_component.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
      AND economic_component.key_value IS NOT NULL
      AND NOT (economic_component.key_type = 'TS_DAY' AND economic_component.key_value !~ '^\d{4}-\d{2}-\d{2}$')
      AND economic_component.source_amount_ex_vat IS NOT NULL
  ), scoped_components AS (
    SELECT scoped_item_component.timesheet_id,
           scoped_item_component.key_type,
           scoped_item_component.key_value,
           scoped_item_component.source_family_key,
           scoped_item_component.source_family_key LIKE 'correction-chain:%' AS is_correction_chain_residual,
           SUM(ROUND(COALESCE(scoped_item_component.source_amount_ex_vat, 0), 2)) AS requested_source_amount_ex_vat,
           SUM(ROUND(COALESCE(scoped_item_component.target_amount_ex_vat, 0), 2)) AS requested_target_amount_ex_vat,
           SUM(scoped_item_component.resolved_source_amount_ex_vat) AS resolved_source_amount_ex_vat,
           SUM(scoped_item_component.resolved_target_amount_ex_vat) AS resolved_target_amount_ex_vat,
           BOOL_AND(COALESCE(scoped_item_component.resolved_component_is_fresh, false)) AS resolved_component_is_fresh,
           MAX(
             CASE
               WHEN scoped_item_component.source_family_key LIKE 'correction-chain:%'
                AND COALESCE(scoped_item_component.correction_chain_component->>'effective_source_outstanding_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                 THEN ROUND((scoped_item_component.correction_chain_component->>'effective_source_outstanding_ex_vat')::numeric, 2)
               ELSE NULL::numeric
             END
           ) AS frozen_chain_outstanding_ex_vat
    FROM scoped_item_components AS scoped_item_component
    GROUP BY
      scoped_item_component.timesheet_id,
      scoped_item_component.key_type,
      scoped_item_component.key_value,
      scoped_item_component.source_family_key
  ), timesheet_ids AS (
    SELECT COALESCE(array_agg(DISTINCT scoped_component_rows.timesheet_id), ARRAY[]::uuid[]) AS timesheet_id_array
    FROM scoped_components AS scoped_component_rows
    WHERE scoped_component_rows.is_correction_chain_residual IS NOT TRUE
  ), outstanding_components AS (
    SELECT outstanding_component.timesheet_id,
           UPPER(BTRIM(COALESCE(outstanding_component.key_type, ''))) AS key_type,
           BTRIM(COALESCE(outstanding_component.key_value, '')) AS key_value,
           ROUND(COALESCE(outstanding_component.truth_ex_vat, 0), 2) AS truth_ex_vat,
           ROUND(COALESCE(outstanding_component.baseline_ex_vat, 0), 2) AS baseline_ex_vat,
           ROUND(COALESCE(outstanding_component.reserved_ex_vat, 0), 2) AS reserved_ex_vat,
           ROUND(COALESCE(outstanding_component.outstanding_ex_vat, 0), 2) AS outstanding_ex_vat
    FROM public._pay_outstanding_components(
      p_timesheet_ids => (SELECT timesheet_ids.timesheet_id_array FROM timesheet_ids),
      p_exclude_pay_batch_id => p_pay_batch_id
    ) AS outstanding_component
  ), joined_components AS (
    SELECT scoped_component_rows.timesheet_id,
           scoped_component_rows.key_type,
           scoped_component_rows.key_value,
           scoped_component_rows.source_family_key,
           scoped_component_rows.is_correction_chain_residual,
           ROUND(scoped_component_rows.requested_source_amount_ex_vat, 2) AS requested_source_amount_ex_vat,
           ROUND(scoped_component_rows.requested_target_amount_ex_vat, 2) AS requested_target_amount_ex_vat,
           CASE
             WHEN scoped_component_rows.is_correction_chain_residual
               THEN ROUND(scoped_component_rows.requested_source_amount_ex_vat, 2)
             WHEN scoped_component_rows.resolved_component_is_fresh
               THEN ROUND(scoped_component_rows.requested_target_amount_ex_vat, 2)
             ELSE ROUND(scoped_component_rows.requested_source_amount_ex_vat, 2)
           END AS reservation_requested_amount_ex_vat,
           CASE
             WHEN scoped_component_rows.is_correction_chain_residual
               THEN ROUND(COALESCE(scoped_component_rows.frozen_chain_outstanding_ex_vat, 0), 2)
             WHEN scoped_component_rows.resolved_component_is_fresh
              AND ROUND(COALESCE(scoped_component_rows.resolved_source_amount_ex_vat, 0), 2)
                  = ROUND(COALESCE(outstanding_component_rows.truth_ex_vat, 0), 2)
              AND ROUND(COALESCE(outstanding_component_rows.reserved_ex_vat, 0), 2) = 0
              AND ROUND(COALESCE(scoped_component_rows.requested_target_amount_ex_vat, 0), 2)
                  = ROUND(
                      GREATEST(
                        COALESCE(scoped_component_rows.resolved_target_amount_ex_vat, 0)
                          - COALESCE(outstanding_component_rows.baseline_ex_vat, 0),
                        0
                      ),
                      2
                    )
               THEN ROUND(
                      GREATEST(
                        COALESCE(scoped_component_rows.resolved_target_amount_ex_vat, 0)
                          - COALESCE(outstanding_component_rows.baseline_ex_vat, 0),
                        0
                      ),
                      2
                    )
             WHEN scoped_component_rows.resolved_component_is_fresh
               THEN 0::numeric
             ELSE ROUND(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0), 2)
           END AS outstanding_ex_vat,
           CASE
             WHEN scoped_component_rows.is_correction_chain_residual
               THEN 'FROZEN_CORRECTION_CHAIN_RESIDUAL'
             WHEN scoped_component_rows.resolved_component_is_fresh
              AND ROUND(COALESCE(scoped_component_rows.resolved_source_amount_ex_vat, 0), 2)
                  = ROUND(COALESCE(outstanding_component_rows.truth_ex_vat, 0), 2)
              AND ROUND(COALESCE(outstanding_component_rows.reserved_ex_vat, 0), 2) = 0
              AND ROUND(COALESCE(scoped_component_rows.requested_target_amount_ex_vat, 0), 2)
                  = ROUND(
                      GREATEST(
                        COALESCE(scoped_component_rows.resolved_target_amount_ex_vat, 0)
                          - COALESCE(outstanding_component_rows.baseline_ex_vat, 0),
                        0
                      ),
                      2
                    )
               THEN 'FROZEN_FRESH_PRE_DRAFT_RESOLUTION_TARGET_REMAINDER'
             WHEN scoped_component_rows.resolved_component_is_fresh
               THEN 'FROZEN_FRESH_PRE_DRAFT_RESOLUTION_MISMATCH_OR_RESERVED'
             ELSE 'LIVE_PRE_DRAFT_OUTSTANDING'
           END AS outstanding_evidence_source
    FROM scoped_components AS scoped_component_rows
    LEFT JOIN outstanding_components AS outstanding_component_rows
      ON scoped_component_rows.is_correction_chain_residual IS NOT TRUE
     AND outstanding_component_rows.timesheet_id = scoped_component_rows.timesheet_id
     AND outstanding_component_rows.key_type = scoped_component_rows.key_type
     AND outstanding_component_rows.key_value = scoped_component_rows.key_value
  ), overruns AS (
    SELECT joined_component_rows.timesheet_id,
           joined_component_rows.key_type,
           joined_component_rows.key_value,
           joined_component_rows.source_family_key,
           joined_component_rows.requested_source_amount_ex_vat,
           joined_component_rows.requested_target_amount_ex_vat,
           joined_component_rows.reservation_requested_amount_ex_vat,
           joined_component_rows.outstanding_ex_vat,
           joined_component_rows.outstanding_evidence_source
    FROM joined_components AS joined_component_rows
    WHERE joined_component_rows.reservation_requested_amount_ex_vat > joined_component_rows.outstanding_ex_vat + 0.01
  )
  SELECT COALESCE(
           (
             SELECT jsonb_agg(
                      jsonb_build_object(
                        'timesheet_id', overrun_sample_rows.timesheet_id::text,
                        'key_type', overrun_sample_rows.key_type,
                        'key_value', overrun_sample_rows.key_value,
                        'source_family_key', overrun_sample_rows.source_family_key,
                        'requested_source_amount_ex_vat', overrun_sample_rows.requested_source_amount_ex_vat,
                        'requested_target_amount_ex_vat', overrun_sample_rows.requested_target_amount_ex_vat,
                        'reservation_requested_amount_ex_vat', overrun_sample_rows.reservation_requested_amount_ex_vat,
                        'outstanding_ex_vat', overrun_sample_rows.outstanding_ex_vat,
                        'outstanding_evidence_source', overrun_sample_rows.outstanding_evidence_source
                      )
                      ORDER BY overrun_sample_rows.timesheet_id::text,
                               overrun_sample_rows.key_type,
                               overrun_sample_rows.key_value
                    )
             FROM (
               SELECT overrun_rows.*
               FROM overruns AS overrun_rows
               ORDER BY overrun_rows.timesheet_id::text, overrun_rows.key_type, overrun_rows.key_value
               LIMIT 25
             ) AS overrun_sample_rows
           ),
           '[]'::jsonb
         ),
         COALESCE((SELECT COUNT(*)::integer FROM scoped_components AS scoped_count_rows), 0),
         ROUND(COALESCE((SELECT SUM(joined_sum_rows.reservation_requested_amount_ex_vat) FROM joined_components AS joined_sum_rows), 0), 2),
         ROUND(COALESCE((SELECT SUM(joined_sum_rows.outstanding_ex_vat) FROM joined_components AS joined_sum_rows), 0), 2)
  INTO v_overrun_sample,
       v_reservation_check_component_count,
       v_reservation_requested_amount_ex_vat,
       v_reservation_outstanding_before_batch_ex_vat;

  IF jsonb_array_length(COALESCE(v_overrun_sample, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION '%', (
      jsonb_build_object(
        'error', 'PAY_BATCH_RESERVATION_OVERRUN',
        'pay_batch_id', p_pay_batch_id::text,
        'overruns', v_overrun_sample
      )
      || jsonb_build_object(
        'reservation_check_excluded_pay_batch_id', p_pay_batch_id::text,
        'reservation_component_count', COALESCE(v_reservation_check_component_count, 0),
        'reservation_requested_amount_ex_vat', COALESCE(v_reservation_requested_amount_ex_vat, 0),
        'reservation_outstanding_before_batch_ex_vat', COALESCE(v_reservation_outstanding_before_batch_ex_vat, 0)
      )
    )::text;
  END IF;

  UPDATE public.pay_batch_candidates AS pay_batch_candidate
  SET awaiting_net_amount = (
        v_scope = 'PAYE'
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_paye_net_inputs AS net_input
          WHERE net_input.pay_batch_candidate_id = pay_batch_candidate.id
        )
      ),
      updated_at = v_now
  WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row
      WHERE scope_row.candidate_id = pay_batch_candidate.candidate_id
    );
  GET DIAGNOSTICS v_awaiting_net_rows_updated = ROW_COUNT;

  WITH scoped_finance_items AS (
    SELECT pay_batch_item.id AS pay_batch_item_id,
           pay_batch_item.reservation_id AS current_reservation_id,
           pay_batch_item.finance_case_id,
           pay_batch_item.finance_component_id,
           pay_batch_item.pay_batch_candidate_id,
           pay_batch_item.repayment_week_start,
           pay_batch_item.frozen_component_snapshot_json,
           pay_batch_item.frozen_component_key_type,
           pay_batch_item.frozen_component_key_value,
           pay_batch_item.frozen_component_classification,
           pay_batch_item.frozen_source_basis_json,
           pay_batch_item.frozen_source_pay_method,
           pay_batch_item.frozen_target_pay_method,
           pay_batch_item.frozen_resolution_mode,
           pay_batch_item.frozen_resolution_payload_json,
           pay_batch_item.frozen_resolution_result_json,
           ROUND(ABS(COALESCE(public._pay_batch_item_source_reservation_amount_ex_vat(pay_batch_item.id), pay_batch_item.frozen_source_amount, pay_batch_item.amount_ex_vat, 0)), 2) AS reserved_source_amount,
           ROUND(ABS(COALESCE(pay_batch_item.frozen_target_amount_ex_vat, pay_batch_item.amount_ex_vat, 0)), 2) AS frozen_rounded_target_amount,
           (
             substr(md5(p_pay_batch_id::text || ':' || pay_batch_item.id::text || ':' || COALESCE(pay_batch_item.finance_case_id::text, 'no_case') || ':' || COALESCE(pay_batch_item.finance_component_id::text, 'no_component')), 1, 8) || '-' ||
             substr(md5(p_pay_batch_id::text || ':' || pay_batch_item.id::text || ':' || COALESCE(pay_batch_item.finance_case_id::text, 'no_case') || ':' || COALESCE(pay_batch_item.finance_component_id::text, 'no_component')), 9, 4) || '-' ||
             substr(md5(p_pay_batch_id::text || ':' || pay_batch_item.id::text || ':' || COALESCE(pay_batch_item.finance_case_id::text, 'no_case') || ':' || COALESCE(pay_batch_item.finance_component_id::text, 'no_component')), 13, 4) || '-' ||
             substr(md5(p_pay_batch_id::text || ':' || pay_batch_item.id::text || ':' || COALESCE(pay_batch_item.finance_case_id::text, 'no_case') || ':' || COALESCE(pay_batch_item.finance_component_id::text, 'no_component')), 17, 4) || '-' ||
             substr(md5(p_pay_batch_id::text || ':' || pay_batch_item.id::text || ':' || COALESCE(pay_batch_item.finance_case_id::text, 'no_case') || ':' || COALESCE(pay_batch_item.finance_component_id::text, 'no_component')), 21, 12)
           )::uuid AS deterministic_reservation_id
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      ON allocation_row.pay_batch_item_id = pay_batch_item.id
     AND allocation_row.operation_id = p_operation_id
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND allocation_row.candidate_scope_id IN (SELECT scope_row.id FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row)
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND pay_batch_item.finance_case_id IS NOT NULL
      AND pay_batch_item.reservation_id IS NULL
    ORDER BY allocation_row.candidate_scope_id, allocation_row.sort_order, pay_batch_item.id
    LIMIT 100
  ), inserted_reservations AS (
    INSERT INTO public.pay_advance_reservations (
      id,
      finance_case_id,
      finance_component_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      reserved_source_amount,
      frozen_rounded_target_amount
    )
    SELECT
      scoped_finance_items.deterministic_reservation_id,
      scoped_finance_items.finance_case_id,
      scoped_finance_items.finance_component_id,
      p_pay_batch_id,
      scoped_finance_items.pay_batch_candidate_id,
      scoped_finance_items.pay_batch_item_id,
      scoped_finance_items.frozen_rounded_target_amount,
      scoped_finance_items.repayment_week_start,
      'RESERVED',
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::text,
      p_actor_user_id,
      p_actor_user_id,
      scoped_finance_items.frozen_component_snapshot_json,
      scoped_finance_items.frozen_component_key_type,
      scoped_finance_items.frozen_component_key_value,
      scoped_finance_items.frozen_component_classification,
      scoped_finance_items.frozen_source_basis_json,
      scoped_finance_items.frozen_source_pay_method,
      scoped_finance_items.frozen_target_pay_method,
      scoped_finance_items.frozen_resolution_mode,
      scoped_finance_items.frozen_resolution_payload_json,
      scoped_finance_items.frozen_resolution_result_json,
      scoped_finance_items.reserved_source_amount,
      scoped_finance_items.frozen_rounded_target_amount
    FROM scoped_finance_items
    ON CONFLICT (id) DO UPDATE
    SET pay_batch_id = EXCLUDED.pay_batch_id,
        pay_batch_candidate_id = EXCLUDED.pay_batch_candidate_id,
        pay_batch_item_id = EXCLUDED.pay_batch_item_id,
        updated_by_user_id = EXCLUDED.updated_by_user_id
    RETURNING public.pay_advance_reservations.id, public.pay_advance_reservations.pay_batch_item_id, xmax = 0 AS inserted_flag
  ), linked_items AS (
    UPDATE public.pay_batch_items AS item_update
    SET reservation_id = inserted_reservations.id,
        updated_at = v_now
    FROM inserted_reservations
    WHERE item_update.id = inserted_reservations.pay_batch_item_id
    RETURNING inserted_reservations.inserted_flag
  )
  SELECT COUNT(*) FILTER (WHERE linked_items.inserted_flag)::integer,
         COUNT(*) FILTER (WHERE NOT linked_items.inserted_flag)::integer
  INTO v_reservations_created, v_reservations_reused
  FROM linked_items;

  UPDATE public.banking_pay_operation_candidate_scope AS scope_update
  SET status = CASE
        WHEN NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_remaining
          JOIN public.pay_batch_items AS item_remaining
            ON item_remaining.id = allocation_remaining.pay_batch_item_id
          WHERE allocation_remaining.candidate_scope_id = scope_update.id
            AND COALESCE(item_remaining.is_voided, false) = false
            AND item_remaining.finance_case_id IS NOT NULL
            AND item_remaining.reservation_id IS NULL
        ) THEN 'DRAFTED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.operation_id = p_operation_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row
      WHERE scope_row.id = scope_update.id
    );

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT batch_item.timesheet_id ORDER BY batch_item.timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_summary_timesheet_ids
  FROM public.pay_batch_items AS batch_item
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id = batch_item.pay_batch_candidate_id
  JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    ON allocation_row.pay_batch_item_id = batch_item.id
   AND allocation_row.operation_id = p_operation_id
  WHERE batch_candidate.pay_batch_id = p_pay_batch_id
    AND allocation_row.candidate_scope_id IN (
      SELECT scope_row.id
      FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row
    )
    AND batch_item.timesheet_id IS NOT NULL
    AND COALESCE(batch_item.is_voided, false) = false
    AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) IN (
      'SEGMENT_DELTA',
      'EXPENSE_DELTA',
      'ADJUSTMENT_DELTA',
      'MILEAGE_DELTA'
    );

  v_summary_total := COALESCE(CARDINALITY(v_summary_timesheet_ids), 0);
  v_summary_offset := 1;

  WHILE v_summary_offset <= v_summary_total LOOP
    SELECT COALESCE(
      ARRAY_AGG(chunk_rows.timesheet_id ORDER BY chunk_rows.ordinality),
      ARRAY[]::uuid[]
    )
    INTO v_summary_chunk_ids
    FROM UNNEST(v_summary_timesheet_ids) WITH ORDINALITY AS chunk_rows(timesheet_id, ordinality)
    WHERE chunk_rows.ordinality BETWEEN v_summary_offset AND v_summary_offset + 99;

    PERFORM public.pay_timesheet_summary_pay_state_refresh(
      p_timesheet_ids => v_summary_chunk_ids,
      p_actor_user_id => p_actor_user_id
    );

    v_summary_offset := v_summary_offset + 100;
  END LOOP;

  PERFORM public.pay_batch_display_summary_touch(p_pay_batch_id);

  PERFORM public.banking_pay_batch_signal_touch(
    p_pay_batch_id => p_pay_batch_id,
    p_change_reason => 'DRAFT_ARTIFACTS_FINALISED',
    p_change_source => 'pay_batch_finalize_reservations_and_markers',
    p_change_scope_json => jsonb_build_object(
      'operation_id', p_operation_id::text,
      'candidate_scope_count', v_scope_id_count,
      'pay_channel_scope', v_scope
    ) || jsonb_build_object(
      'reservation_check_excluded_pay_batch_id', p_pay_batch_id::text,
      'reservation_component_count', COALESCE(v_reservation_check_component_count, 0),
      'reservation_requested_amount_ex_vat', COALESCE(v_reservation_requested_amount_ex_vat, 0),
      'reservation_outstanding_before_batch_ex_vat', COALESCE(v_reservation_outstanding_before_batch_ex_vat, 0)
    ),
    p_touch_payment_status => false,
    p_touch_correction_progress => false,
    p_touch_alerts => false,
    p_touch_overview => true
  );

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'FINALISE_RESERVATIONS','ASSERT_COMPLETE','[]'::jsonb,
    jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'candidate_scope_count', v_scope_id_count,
    'reservations_created', COALESCE(v_reservations_created, 0),
    'reservations_reused', COALESCE(v_reservations_reused, 0),
    'markers_updated', COALESCE(v_awaiting_net_rows_updated, 0),
    'failed_count', 0,
    'candidate_rows_before_empty_delete', COALESCE(v_candidate_rows_before_empty_delete, 0),
    'deleted_candidate_rows', COALESCE(v_deleted_candidate_rows, 0),
    'candidate_rows_after_empty_delete', COALESCE(v_candidate_rows_after_empty_delete, 0),
    'awaiting_net_rows_updated', COALESCE(v_awaiting_net_rows_updated, 0),
    'reservation_check_excluded_pay_batch_id', p_pay_batch_id::text,
    'reservation_component_count', COALESCE(v_reservation_check_component_count, 0),
    'reservation_requested_amount_ex_vat', COALESCE(v_reservation_requested_amount_ex_vat, 0),
    'reservation_outstanding_before_batch_ex_vat', COALESCE(v_reservation_outstanding_before_batch_ex_vat, 0),
    'has_more', EXISTS (
      SELECT 1
      FROM public.pay_batch_items AS remaining_item
      JOIN public.pay_batch_candidates AS remaining_candidate
        ON remaining_candidate.id = remaining_item.pay_batch_candidate_id
      JOIN public.banking_pay_operation_candidate_allocation_rows AS remaining_allocation
        ON remaining_allocation.pay_batch_item_id = remaining_item.id
       AND remaining_allocation.operation_id = p_operation_id
      WHERE remaining_candidate.pay_batch_id = p_pay_batch_id
        AND remaining_allocation.candidate_scope_id IN (SELECT scope_row.id FROM pg_temp.tmp_pay_batch_finalize_scope AS scope_row)
        AND COALESCE(remaining_item.is_voided, false) = false
        AND remaining_item.finance_case_id IS NOT NULL
        AND remaining_item.reservation_id IS NULL
    )
  );
END;
$function$;

-- pay_batch_freshness_result_get(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_freshness_result_get(p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_pay_batch_id uuid := p_pay_batch_id;
  v_actor_is_valid boolean := true;
  v_progress_summary jsonb := '{}'::jsonb;

  v_total_unit_count integer := 0;
  v_fresh_unit_count integer := 0;
  v_stale_unit_count integer := 0;
  v_pending_unit_count integer := 0;
  v_error_unit_count integer := 0;
  v_completed_unit_count integer := 0;
  v_unit_result_hashes jsonb := '[]'::jsonb;

  v_total_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_complete_chunk_count integer := 0;
  v_chunk_result_hashes jsonb := '[]'::jsonb;

  v_validation_complete boolean := false;
  v_is_stale boolean := false;
  v_checked_count integer := 0;
  v_stale_count integer := 0;
  v_failed_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_stale_reason_counts jsonb := '{}'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;
  v_failed_sample jsonb := '[]'::jsonb;
  v_checked_at_utc timestamptz := NULL::timestamptz;
  v_scope_hash text := NULL::text;
  v_result_hash text := NULL::text;
  v_status text := 'PENDING';
  v_result jsonb := '{}'::jsonb;
  v_hash_basis jsonb := '{}'::jsonb;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_ID_REQUIRED')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text
            )::text;
  END IF;

  v_pay_batch_id := COALESCE(v_pay_batch_id, v_operation.pay_batch_id);

  IF v_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_PAY_BATCH_ID_REQUIRED',
              'operation_id', p_operation_id::text
            )::text;
  END IF;

  IF v_operation.pay_batch_id IS NOT NULL AND v_operation.pay_batch_id <> v_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'operation_pay_batch_id', v_operation.pay_batch_id::text,
              'pay_batch_id', v_pay_batch_id::text
            )::text;
  END IF;

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = v_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_BATCH_NOT_FOUND',
              'pay_batch_id', v_pay_batch_id::text
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  v_progress_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'FRESH')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'STALE')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'ERROR')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) NOT IN ('FRESH', 'STALE', 'ERROR'))::integer
  INTO
    v_total_unit_count,
    v_fresh_unit_count,
    v_stale_unit_count,
    v_error_unit_count,
    v_pending_unit_count
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL);

  IF COALESCE(v_total_unit_count, 0) > 0 THEN
    v_completed_unit_count := COALESCE(v_fresh_unit_count, 0) + COALESCE(v_stale_unit_count, 0) + COALESCE(v_error_unit_count, 0);
    v_validation_complete := COALESCE(v_pending_unit_count, 0) = 0;
    v_checked_count := v_completed_unit_count;
    v_stale_count := COALESCE(v_stale_unit_count, 0);
    v_failed_count := COALESCE(v_error_unit_count, 0);

    IF COALESCE(v_pending_unit_count, 0) > 0 THEN
      v_status := 'PENDING';
    ELSIF COALESCE(v_error_unit_count, 0) > 0 THEN
      v_status := 'ERROR';
    ELSIF COALESCE(v_stale_unit_count, 0) > 0 THEN
      v_status := 'STALE';
    ELSE
      v_status := 'PASSED';
    END IF;

    v_is_stale := v_status IN ('STALE', 'ERROR');

    v_scope_hash := COALESCE(
      NULLIF(BTRIM(COALESCE(v_progress_summary->>'scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_batch.freshness_scope_hash, '')), '')
    );

    IF v_scope_hash IS NULL THEN
      WITH scope_key_rows AS (
        SELECT
          scope_unit.unit_ordinal,
          scope_unit.unit_key
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
        ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
      )
      SELECT md5(COALESCE(jsonb_agg(scope_key_rows.unit_key ORDER BY scope_key_rows.unit_ordinal, scope_key_rows.unit_key), '[]'::jsonb)::text)
      INTO v_scope_hash
      FROM scope_key_rows;
    END IF;

    WITH reason_values AS (
      SELECT DISTINCT NULLIF(BTRIM(reason_source.reason_value), '') AS reason_value
      FROM (
        SELECT reason_text.reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        CROSS JOIN LATERAL jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
              THEN scope_unit.unit_payload_json #> '{validation_result,stale_reasons}'
            ELSE '[]'::jsonb
          END
        ) AS reason_text(reason_value)
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)

        UNION ALL

        SELECT scope_unit.error_json->>'code' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL

        UNION ALL

        SELECT scope_unit.error_json->>'reason' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL
      ) AS reason_source
      WHERE NULLIF(BTRIM(reason_source.reason_value), '') IS NOT NULL
    )
    SELECT COALESCE(jsonb_agg(reason_values.reason_value ORDER BY reason_values.reason_value), '[]'::jsonb)
    INTO v_stale_reasons
    FROM reason_values;

    WITH reason_values AS (
      SELECT NULLIF(BTRIM(reason_source.reason_value), '') AS reason_value
      FROM (
        SELECT reason_text.reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        CROSS JOIN LATERAL jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
              THEN scope_unit.unit_payload_json #> '{validation_result,stale_reasons}'
            ELSE '[]'::jsonb
          END
        ) AS reason_text(reason_value)
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)

        UNION ALL

        SELECT scope_unit.error_json->>'code' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL

        UNION ALL

        SELECT scope_unit.error_json->>'reason' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL
      ) AS reason_source
      WHERE NULLIF(BTRIM(reason_source.reason_value), '') IS NOT NULL
    ),
    reason_counts AS (
      SELECT
        reason_values.reason_value AS reason_key,
        COUNT(*)::integer AS reason_count
      FROM reason_values
      GROUP BY reason_values.reason_value
    )
    SELECT COALESCE(jsonb_object_agg(reason_counts.reason_key, reason_counts.reason_count ORDER BY reason_counts.reason_key), '{}'::jsonb)
    INTO v_stale_reason_counts
    FROM reason_counts;

    WITH key_failure_units AS (
      SELECT DISTINCT scope_unit.id
      FROM public.banking_pay_operation_scope_units AS scope_unit
      LEFT JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
            THEN scope_unit.unit_payload_json #> '{validation_result,stale_reasons}'
          ELSE '[]'::jsonb
        END
      ) AS reason_text(reason_value) ON true
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
        AND (
          UPPER(BTRIM(COALESCE(reason_text.reason_value, ''))) IN ('POST_DRAFT_KEY_RESOLUTION_FAILED', 'KEY_RESOLUTION_FAILED')
          OR UPPER(BTRIM(COALESCE(reason_text.reason_value, ''))) LIKE '%KEY_RESOLUTION%'
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'code', ''))) IN ('POST_DRAFT_KEY_RESOLUTION_FAILED', 'KEY_RESOLUTION_FAILED')
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'code', ''))) LIKE '%KEY_RESOLUTION%'
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'reason', ''))) LIKE '%KEY_RESOLUTION%'
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'message', ''))) LIKE '%KEY_RESOLUTION%'
        )
    )
    SELECT COUNT(*)::integer
    INTO v_key_resolution_failure_count
    FROM key_failure_units;

    WITH diff_items AS (
      SELECT
        scope_unit.unit_ordinal,
        scope_unit.unit_key,
        diff_item.diff_value
      FROM public.banking_pay_operation_scope_units AS scope_unit
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,diff}') = 'array'
            THEN scope_unit.unit_payload_json #> '{validation_result,diff}'
          WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,diff_sample}') = 'array'
            THEN scope_unit.unit_payload_json #> '{validation_result,diff_sample}'
          ELSE '[]'::jsonb
        END
      ) AS diff_item(diff_value)
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
      ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key, diff_item.diff_value::text
      LIMIT 50
    )
    SELECT COALESCE(jsonb_agg(diff_items.diff_value ORDER BY diff_items.unit_ordinal, diff_items.unit_key, diff_items.diff_value::text), '[]'::jsonb)
    INTO v_diff_sample
    FROM diff_items;

    WITH failed_rows AS (
      SELECT
        scope_unit.unit_ordinal,
        scope_unit.unit_key,
        jsonb_build_object(
          'unit_id', scope_unit.id::text,
          'unit_key', scope_unit.unit_key,
          'status', UPPER(BTRIM(COALESCE(scope_unit.status, ''))),
          'error', COALESCE(scope_unit.error_json, '{}'::jsonb)
        ) AS failed_json
      FROM public.banking_pay_operation_scope_units AS scope_unit
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
        AND UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'ERROR'
      ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
      LIMIT 20
    )
    SELECT COALESCE(jsonb_agg(failed_rows.failed_json ORDER BY failed_rows.unit_ordinal, failed_rows.unit_key), '[]'::jsonb)
    INTO v_failed_sample
    FROM failed_rows;

    WITH unit_hash_rows AS (
      SELECT
        scope_unit.unit_ordinal,
        scope_unit.unit_key,
        COALESCE(
          NULLIF(BTRIM(COALESCE(scope_unit.result_hash, '')), ''),
          md5((jsonb_build_object(
            'unit_key', scope_unit.unit_key,
            'status', UPPER(BTRIM(COALESCE(scope_unit.status, ''))),
            'error_json', COALESCE(scope_unit.error_json, '{}'::jsonb),
            'validation_result', COALESCE(scope_unit.unit_payload_json->'validation_result', '{}'::jsonb)
          ))::text)
        ) AS unit_result_hash
      FROM public.banking_pay_operation_scope_units AS scope_unit
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
      ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
    )
    SELECT COALESCE(jsonb_agg(unit_hash_rows.unit_result_hash ORDER BY unit_hash_rows.unit_ordinal, unit_hash_rows.unit_key), '[]'::jsonb)
    INTO v_unit_result_hashes
    FROM unit_hash_rows;

    IF COALESCE(v_failed_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'UNIT_ERROR') THEN
      v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('UNIT_ERROR');
      v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('UNIT_ERROR', COALESCE(v_failed_count, 0));
    END IF;

    IF COALESCE(v_key_resolution_failure_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'KEY_RESOLUTION_FAILED') THEN
      v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('KEY_RESOLUTION_FAILED');
      v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('KEY_RESOLUTION_FAILED', COALESCE(v_key_resolution_failure_count, 0));
    END IF;

    v_hash_basis := jsonb_build_object(
      'source', 'banking_pay_operation_scope_units',
      'validation_complete', v_validation_complete,
      'is_stale', v_is_stale,
      'status', v_status,
      'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'checked_count', COALESCE(v_checked_count, 0),
      'stale_count', COALESCE(v_stale_count, 0),
      'failed_count', COALESCE(v_failed_count, 0)
    ) || jsonb_build_object(
      'key_resolution_failure_count', COALESCE(v_key_resolution_failure_count, 0),
      'diff_sample', COALESCE(v_diff_sample, '[]'::jsonb),
      'failed_sample', COALESCE(v_failed_sample, '[]'::jsonb),
      'freshness_scope_hash', v_scope_hash,
      'total_units', COALESCE(v_total_unit_count, 0),
      'fresh_units', COALESCE(v_fresh_unit_count, 0),
      'stale_units', COALESCE(v_stale_unit_count, 0),
      'pending_units', COALESCE(v_pending_unit_count, 0),
      'error_units', COALESCE(v_error_unit_count, 0),
      'unit_result_hashes', COALESCE(v_unit_result_hashes, '[]'::jsonb)
    );

    IF v_status <> 'PENDING' THEN
      v_result_hash := md5(v_hash_basis::text);
      v_checked_at_utc := v_now;

      IF v_batch.freshness_operation_id = p_operation_id
         AND NULLIF(BTRIM(COALESCE(v_batch.freshness_result_hash, '')), '') = v_result_hash
         AND v_batch.freshness_checked_at_utc IS NOT NULL THEN
        v_checked_at_utc := v_batch.freshness_checked_at_utc;
      END IF;
    END IF;

    v_result := jsonb_build_object(
      'ok', true,
      'phase', 'FRESHNESS',
      'validation_complete', v_validation_complete,
      'is_stale', v_is_stale,
      'status', v_status,
      'checked_count', COALESCE(v_checked_count, 0),
      'stale_count', COALESCE(v_stale_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'key_resolution_failure_count', COALESCE(v_key_resolution_failure_count, 0),
      'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb)
    ) || jsonb_build_object(
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'diff_sample', COALESCE(v_diff_sample, '[]'::jsonb),
      'diff', COALESCE(v_diff_sample, '[]'::jsonb),
      'diff_samples', COALESCE(v_diff_sample, '[]'::jsonb),
      'failed_sample', COALESCE(v_failed_sample, '[]'::jsonb),
      'freshness_checked_at_utc', CASE WHEN v_checked_at_utc IS NULL THEN NULL ELSE to_jsonb(v_checked_at_utc) END,
      'checked_at_utc', CASE WHEN v_checked_at_utc IS NULL THEN NULL ELSE v_checked_at_utc::text END,
      'freshness_result_hash', v_result_hash,
      'result_hash', v_result_hash,
      'freshness_scope_hash', v_scope_hash
    ) || jsonb_build_object(
      'scope_hash', v_scope_hash,
      'total_units', COALESCE(v_total_unit_count, 0),
      'fresh_units', COALESCE(v_fresh_unit_count, 0),
      'stale_units', COALESCE(v_stale_unit_count, 0),
      'pending_units', COALESCE(v_pending_unit_count, 0),
      'error_units', COALESCE(v_error_unit_count, 0),
      'fresh_count', COALESCE(v_fresh_unit_count, 0),
      'pending_count', COALESCE(v_pending_unit_count, 0),
      'error_count', COALESCE(v_error_unit_count, 0)
    ) || jsonb_build_object(
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_pay_batch_id::text,
      'progress_source', 'banking_pay_operation_scope_units'
    );

    UPDATE public.pay_batches AS pay_batch_update
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_status,
        freshness_checked_at_utc = CASE WHEN v_status <> 'PENDING' THEN v_checked_at_utc ELSE pay_batch_update.freshness_checked_at_utc END,
        freshness_result_hash = CASE WHEN v_status <> 'PENDING' THEN v_result_hash ELSE pay_batch_update.freshness_result_hash END,
        freshness_scope_hash = COALESCE(v_scope_hash, pay_batch_update.freshness_scope_hash),
        freshness_result_json = v_result
    WHERE pay_batch_update.id = v_pay_batch_id;

    UPDATE public.banking_pay_operations AS operation_update
    SET progress_json = jsonb_strip_nulls(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'freshness_summary', v_result,
            'freshness_validation_status', v_status,
            'freshness_status', v_status,
            'freshness_result_hash', v_result_hash,
            'freshness_scope_hash', v_scope_hash,
            'freshness_checked_at_utc', CASE WHEN v_checked_at_utc IS NULL THEN NULL ELSE v_checked_at_utc::text END,
            'freshness_is_stale', v_is_stale
          )
          || jsonb_build_object(
            'freshness_total_units', COALESCE(v_total_unit_count, 0),
            'freshness_pending_units', COALESCE(v_pending_unit_count, 0),
            'freshness_stale_units', COALESCE(v_stale_unit_count, 0),
            'freshness_error_units', COALESCE(v_error_unit_count, 0)
          )
        ),
        result_json = CASE
          WHEN v_status <> 'PENDING' THEN jsonb_set(COALESCE(operation_update.result_json, '{}'::jsonb), '{freshness}', v_result, true)
          ELSE operation_update.result_json
        END,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN v_result;
  END IF;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'RUNNING')::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'FAILED')::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'COMPLETE')::integer
  INTO
    v_total_chunk_count,
    v_pending_chunk_count,
    v_running_chunk_count,
    v_failed_chunk_count,
    v_complete_chunk_count
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.operation_id = p_operation_id
    AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
    AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE';

  IF COALESCE(v_total_chunk_count, 0) = 0 THEN
    v_result := jsonb_build_object(
      'validation_complete', false,
      'is_stale', false,
      'status', 'PENDING',
      'reason', 'NO_FRESHNESS_CHUNKS',
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_pay_batch_id::text
    );

    RETURN v_result;
  END IF;

  v_validation_complete := COALESCE(v_pending_chunk_count, 0) = 0
    AND COALESCE(v_running_chunk_count, 0) = 0;

  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_progress_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_batch.freshness_scope_hash, '')), '')
  );

  IF v_validation_complete IS NOT TRUE THEN
    v_result := jsonb_build_object(
      'validation_complete', false,
      'is_stale', false,
      'status', 'PENDING',
      'pending_count', COALESCE(v_pending_chunk_count, 0),
      'running_count', COALESCE(v_running_chunk_count, 0),
      'complete_count', COALESCE(v_complete_chunk_count, 0),
      'failed_count', COALESCE(v_failed_chunk_count, 0),
      'checked_count', 0,
      'stale_count', 0,
      'key_resolution_failure_count', 0,
      'diff_sample', '[]'::jsonb,
      'freshness_checked_at_utc', NULL,
      'freshness_result_hash', NULL,
      'freshness_scope_hash', v_scope_hash,
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_pay_batch_id::text
    );

    RETURN v_result;
  END IF;

  WITH chunk_results AS (
    SELECT
      chunk_row.id,
      chunk_row.status,
      COALESCE(chunk_row.result_json, '{}'::jsonb) AS result_json,
      COALESCE(chunk_row.error_json, '{}'::jsonb) AS error_json
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
  ),
  counts AS (
    SELECT
      SUM(COALESCE((chunk_results.result_json->>'checked_count')::integer, 0))::integer AS checked_count,
      SUM(COALESCE((chunk_results.result_json->>'stale_count')::integer, 0))::integer AS stale_count,
      SUM(COALESCE((chunk_results.result_json->>'key_resolution_failure_count')::integer, 0))::integer AS key_resolution_failure_count,
      COUNT(*) FILTER (WHERE chunk_results.status = 'FAILED')::integer AS failed_count,
      BOOL_OR(COALESCE((chunk_results.result_json->>'is_stale')::boolean, false)) AS any_stale,
      BOOL_OR(chunk_results.status = 'FAILED') AS any_failed
    FROM chunk_results
  )
  SELECT
    COALESCE(counts.checked_count, 0),
    COALESCE(counts.stale_count, 0),
    COALESCE(counts.key_resolution_failure_count, 0),
    COALESCE(counts.failed_count, 0),
    COALESCE(counts.any_stale, false) OR COALESCE(counts.any_failed, false) OR COALESCE(counts.key_resolution_failure_count, 0) > 0
  INTO
    v_checked_count,
    v_stale_count,
    v_key_resolution_failure_count,
    v_failed_count,
    v_is_stale
  FROM counts;

  WITH reason_values AS (
    SELECT DISTINCT reason_text.reason_value
    FROM public.banking_pay_operation_chunks AS chunk_row
    CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(chunk_row.result_json->'stale_reasons', '[]'::jsonb)) AS reason_text(reason_value)
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.result_json IS NOT NULL
  )
  SELECT COALESCE(jsonb_agg(reason_values.reason_value ORDER BY reason_values.reason_value), '[]'::jsonb)
  INTO v_stale_reasons
  FROM reason_values;

  WITH reason_pairs AS (
    SELECT
      reason_entry.key AS reason_key,
      SUM(COALESCE(reason_entry.value::text::integer, 0))::integer AS reason_count
    FROM public.banking_pay_operation_chunks AS chunk_row
    CROSS JOIN LATERAL jsonb_each(COALESCE(chunk_row.result_json->'stale_reason_counts', '{}'::jsonb)) AS reason_entry(key, value)
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.result_json IS NOT NULL
    GROUP BY reason_entry.key
  )
  SELECT COALESCE(jsonb_object_agg(reason_pairs.reason_key, reason_pairs.reason_count ORDER BY reason_pairs.reason_key), '{}'::jsonb)
  INTO v_stale_reason_counts
  FROM reason_pairs;

  WITH diff_items AS (
    SELECT
      chunk_row.sequence_no,
      diff_item.diff_value
    FROM public.banking_pay_operation_chunks AS chunk_row
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(chunk_row.result_json->'diff_sample', '[]'::jsonb)) AS diff_item(diff_value)
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.result_json IS NOT NULL
    ORDER BY chunk_row.sequence_no, diff_item.diff_value::text
    LIMIT 50
  )
  SELECT COALESCE(jsonb_agg(diff_items.diff_value ORDER BY diff_items.sequence_no, diff_items.diff_value::text), '[]'::jsonb)
  INTO v_diff_sample
  FROM diff_items;

  WITH chunk_hash_rows AS (
    SELECT
      chunk_row.sequence_no,
      NULLIF(BTRIM(COALESCE(chunk_row.result_json->>'chunk_result_hash', '')), '') AS chunk_result_hash
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND NULLIF(BTRIM(COALESCE(chunk_row.result_json->>'chunk_result_hash', '')), '') IS NOT NULL
    ORDER BY chunk_row.sequence_no
  )
  SELECT COALESCE(jsonb_agg(chunk_hash_rows.chunk_result_hash ORDER BY chunk_hash_rows.sequence_no), '[]'::jsonb)
  INTO v_chunk_result_hashes
  FROM chunk_hash_rows;

  WITH failed_rows AS (
    SELECT
      chunk_row.sequence_no,
      jsonb_build_object(
        'chunk_id', chunk_row.id::text,
        'sequence_no', chunk_row.sequence_no,
        'error', COALESCE(chunk_row.error_json, '{}'::jsonb)
      ) AS failed_json
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.status = 'FAILED'
    ORDER BY chunk_row.sequence_no
    LIMIT 20
  )
  SELECT COALESCE(jsonb_agg(failed_rows.failed_json ORDER BY failed_rows.sequence_no), '[]'::jsonb)
  INTO v_failed_sample
  FROM failed_rows;

  IF COALESCE(v_failed_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'CHUNK_FAILED') THEN
    v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('CHUNK_FAILED');
    v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('CHUNK_FAILED', COALESCE(v_failed_count, 0));
  END IF;

  IF COALESCE(v_key_resolution_failure_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'KEY_RESOLUTION_FAILED') THEN
    v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('KEY_RESOLUTION_FAILED');
    v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('KEY_RESOLUTION_FAILED', COALESCE(v_key_resolution_failure_count, 0));
  END IF;

  IF COALESCE(v_failed_count, 0) > 0 THEN
    v_status := 'FAILED';
  ELSIF v_is_stale THEN
    v_status := 'STALE';
  ELSE
    v_status := 'PASSED';
  END IF;

  v_hash_basis := jsonb_build_object(
    'source', 'banking_pay_operation_chunks',
    'validation_complete', true,
    'is_stale', v_is_stale,
    'status', v_status,
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
    'checked_count', COALESCE(v_checked_count, 0),
    'stale_count', COALESCE(v_stale_count, 0),
    'failed_count', COALESCE(v_failed_count, 0)
  ) || jsonb_build_object(
    'key_resolution_failure_count', COALESCE(v_key_resolution_failure_count, 0),
    'diff_sample', COALESCE(v_diff_sample, '[]'::jsonb),
    'failed_sample', COALESCE(v_failed_sample, '[]'::jsonb),
    'freshness_scope_hash', v_scope_hash,
    'chunk_count', COALESCE(v_total_chunk_count, 0),
    'complete_chunk_count', COALESCE(v_complete_chunk_count, 0),
    'chunk_result_hashes', COALESCE(v_chunk_result_hashes, '[]'::jsonb)
  );

  v_result_hash := md5(v_hash_basis::text);
  v_checked_at_utc := v_now;

  IF v_batch.freshness_operation_id = p_operation_id
     AND NULLIF(BTRIM(COALESCE(v_batch.freshness_result_hash, '')), '') = v_result_hash
     AND v_batch.freshness_checked_at_utc IS NOT NULL THEN
    v_checked_at_utc := v_batch.freshness_checked_at_utc;
  END IF;

  v_result := v_hash_basis || jsonb_build_object(
    'ok', true,
    'phase', 'FRESHNESS',
    'freshness_checked_at_utc', to_jsonb(v_checked_at_utc),
    'checked_at_utc', v_checked_at_utc::text,
    'freshness_result_hash', v_result_hash,
    'result_hash', v_result_hash,
    'freshness_scope_hash', v_scope_hash,
    'scope_hash', v_scope_hash,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'progress_source', 'banking_pay_operation_chunks'
  );

  UPDATE public.pay_batches AS pay_batch_update
  SET freshness_operation_id = p_operation_id,
      freshness_validation_status = v_status,
      freshness_checked_at_utc = v_checked_at_utc,
      freshness_result_hash = v_result_hash,
      freshness_scope_hash = v_scope_hash,
      freshness_result_json = v_result
  WHERE pay_batch_update.id = v_pay_batch_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_result,
          'freshness_validation_status', v_status,
          'freshness_status', v_status,
          'freshness_result_hash', v_result_hash,
          'freshness_scope_hash', v_scope_hash,
          'freshness_checked_at_utc', to_jsonb(v_checked_at_utc),
          'freshness_is_stale', v_is_stale
        ),
      result_json = jsonb_set(COALESCE(operation_update.result_json, '{}'::jsonb), '{freshness}', v_result, true),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN v_result;
END;
$function$;

-- pay_batch_freshness_result_get(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_freshness_result_get(p_operation_id uuid, p_pay_batch_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN public.pay_batch_freshness_result_get(
    p_operation_id,
    p_pay_batch_id,
    NULL::uuid
  );
END;
$function$;

